async function main(argv) {
  let commandError = null;
  try {
    return await mainImpl(argv);
  } catch (error) {
    commandError = error;
    throw error;
  } finally {
    await stopActivePublishLeaseHeartbeat();
    try {
      await finalizeCommandScopedPublishLease({
        succeeded: commandError === null,
      });
    } catch (cleanupError) {
      if (!commandError) throw cleanupError;
      commandError.publishLeaseCleanupError = {
        code: cleanupError?.code || 'PUBLISH_LEASE_CLEANUP_FAILED',
        message: maskText(cleanupError?.message || String(cleanupError)),
      };
      warn(
        `发布命令失败后的租约清理也未完成：${commandError.publishLeaseCleanupError.message}`
      );
    }
    activePublishRequestContext = null;
  }
}

async function mainImpl(argv) {
  const [command, ...rest] = argv;
  if (command === 'version' || command === '--version' || command === '-v') {
    return version(rest);
  }
  if (!command || command === 'help' || command === '--help' || command === '-h') {
    printHelp();
    return;
  }

  if (command === 'login') return login(rest);
  if (command === 'update') return update(rest);
  if (command === 'env') return env(rest);
  if (command === 'auth') return auth(rest);
  if (command === 'platform') return platform(rest);
  if (command === 'doctor') return doctor(rest);
  if (command === 'contract') return contract(rest);
  if (command === 'policy') return policy(rest);
  if (command === 'open-api') return openApi(rest);
  if (command === 'design') return design(rest);
  if (command === 'sdd') return sdd(rest);
  if (command === 'environment') return environment(rest);
  if (['check', 'deploy', 'status', 'retry', 'rollback'].includes(command)) {
    return getDeliveryV2Cli().run(command, rest);
  }
  if (command === 'release') return release(rest);
  if (command === 'studio') return studio(rest);
  if (command === 'task') return task(rest);
  if (command === 'workspace') return workspace(rest);
  if (command === 'app') return app(rest);
  if (command === 'form') return form(rest);
  if (command === 'page') return page(rest);
  if (command === 'menu') return menu(rest);
  if (command === 'workflow') return workflow(rest);
  if (command === 'automation') return automation(rest);
  if (command === 'data-view') return dataView(rest);
  if (command === 'scope') return scope(rest);
  if (command === 'route') return route(rest);
  if (command === 'public-access') return publicAccess(rest);
  if (command === 'auth-config') return authConfig(rest);
  if (command === 'function') return appFunction(rest);
  if (command === 'secret') return appSecret(rest);
  if (command === 'connector') return connector(rest);
  if (command === 'notification') return notification(rest);
  if (command === 'organization') return organization(rest);
  if (command === 'permission') return permission(rest);
  if (command === 'settings') return settings(rest);
  if (command === 'resource') return resource(rest);
  if (command === 'runtime') return runtime(rest);
  if (command === 'inspect') return inspect(rest);
  if (command === 'skill') return skill(rest);
  if (command === 'feedback') return feedback(rest);
  if (command === 'commands') return commands(rest);

  fail(`未知命令: ${command}`);
}

