const SUBCOMMAND_BOOLEAN_FLAGS = new Set([
  '--apply',
  '--check',
  '--all',
  '--activate',
  '--dry-run',
  '--enabled',
  '--force',
  '--full-replace',
  '--help',
  '--include-sourcemaps',
  '--json',
  '--legacy-form-bundle',
  '--no-activate',
  '--no-build',
  '--no-open',
  '--no-runtime-aliases',
  '--prune',
  '--publish',
  '--published',
  '--redact',
  '--release',
  '--resources',
  '--skip-resources',
  '--show-secret',
  '--confirm-production',
  '--stage-only',
  '--strict',
  '--sdd-bypass',
  '--summary',
  '--unpublish',
  '--value-stdin',
  '--wait',
  '--watch',
  '--write-manifest',
  '--yes',
  '-h',
]);

function parseSubcommandArgs(args) {
  const leadingFlags = [];
  let index = 0;
  while (index < args.length) {
    const item = args[index];
    if (!isFlagToken(item)) break;
    if (item === '--') {
      index += 1;
      break;
    }
    leadingFlags.push(item);
    if (hasInlineFlagValue(item) || isSubcommandBooleanFlag(item)) {
      index += 1;
      continue;
    }
    const next = args[index + 1];
    if (next && !isFlagToken(next)) {
      leadingFlags.push(next);
      index += 2;
      continue;
    }
    index += 1;
  }
  return {
    subcommand: args[index],
    rest: [...leadingFlags, ...args.slice(index + 1)],
  };
}

function isFlagToken(value) {
  return typeof value === 'string' && value.startsWith('-');
}

function hasInlineFlagValue(value) {
  return typeof value === 'string' && value.startsWith('--') && value.includes('=');
}

function isSubcommandBooleanFlag(value) {
  return SUBCOMMAND_BOOLEAN_FLAGS.has(value) || /^--no-/.test(String(value || ''));
}

function wantsSubcommandHelp(subcommand, flags) {
  return (
    !subcommand ||
    subcommand === 'help' ||
    subcommand === '--help' ||
    subcommand === '-h' ||
    flags.help ||
    flags.h
  );
}

async function version(args) {
  const { flags } = parseArgs(args);
  const result = {
    name: NPM_PACKAGE_NAME,
    version: CURRENT_VERSION,
    contracts: {
      appFunctionSecrets: APP_FUNCTION_SECRET_CAPABILITIES.contractVersion,
      trustedNode: APP_FUNCTION_SECRET_CAPABILITIES.runtimeContractVersion,
      backendRelease: APP_FUNCTION_SECRET_CAPABILITIES.backendRelease,
      atomicActivation: APP_FUNCTION_SECRET_CAPABILITIES.atomicActivation,
    },
    updateCheckCommand: 'openxiangda update check --json',
  };
  if (flags.json) return writeJson(result);
  print(CURRENT_VERSION);
}

async function update(args) {
  const requestedSubcommand = args[0] && !args[0].startsWith('--') ? args[0] : 'check';
  const parsedArgs = requestedSubcommand === args[0] ? args.slice(1) : args;
  const { flags } = parseArgs(parsedArgs);
  if (wantsSubcommandHelp(requestedSubcommand, flags)) {
    print('用法: openxiangda update check|install [--json] [--registry https://registry.npmjs.org] [--timeout-seconds 300] [--no-skills]');
    return;
  }
  const registry = normalizeNpmRegistry(flags.registry || OFFICIAL_NPM_REGISTRY);
  const selection = resolveUpdateTarget({ target: flags.target });

  if (requestedSubcommand === 'check') {
    const result = checkOpenXiangdaUpdate(registry, selection);
    if (flags.json) return writeJson(result);
    printUpdateCheck(result);
    return;
  }

  if (requestedSubcommand === 'install') {
    const result = await installOpenXiangdaUpdate(registry, {
      json: Boolean(flags.json),
      skipSkills: Boolean(flags['no-skills']),
      timeoutSeconds: flags['timeout-seconds'],
      ...selection,
    });
    if (flags.json) return writeJson(result);
    print('OpenXiangda 已更新。');
    if (result.skillInstall?.attempted && result.skillInstall.status !== 0) {
      warn(`skill install 未完成: ${result.skillInstall.error}`);
    }
    return;
  }

  fail('用法: openxiangda update check|install [--json] [--registry https://registry.npmjs.org] [--timeout-seconds 300] [--no-skills]');
}

function normalizeNpmRegistry(value) {
  const registry = String(value || OFFICIAL_NPM_REGISTRY).trim();
  return registry.replace(/\/+$/, '') || OFFICIAL_NPM_REGISTRY;
}

function checkOpenXiangdaUpdate(registry, selection = resolveUpdateTarget()) {
  const latestVersion = fetchLatestOpenXiangdaVersion(registry, selection.channel);
  const versionComparison = compareVersions(latestVersion, CURRENT_VERSION);
  const updateAvailable = versionComparison > 0;
  return {
    packageName: NPM_PACKAGE_NAME,
    currentVersion: CURRENT_VERSION,
    latestVersion,
    registry,
    updateAvailable,
    status: updateAvailable
      ? 'update_available'
      : versionComparison < 0
        ? 'local_newer_than_registry'
        : 'latest',
    target: selection.target,
    channel: selection.channel,
    installCommand: `openxiangda update install --target ${selection.target}`,
    skillInstallCommand: 'openxiangda skill install',
    compatibilityCheckCommand: 'openxiangda commands --json',
    checkedAt: new Date().toISOString(),
    notes: [
      'Use the official npm registry for OpenXiangda updates; domestic mirrors may lag.',
      'After updating the package, refresh OpenXiangda skills so AI guidance matches the CLI version.',
    ],
  };
}

function fetchLatestOpenXiangdaVersion(registry, channel = 'v1') {
  const result = spawnSync(
    'npm',
    ['view', `${NPM_PACKAGE_NAME}@${channel}`, 'version', `--registry=${registry}`, '--json'],
    {
      encoding: 'utf8',
      timeout: 30000,
      killSignal: 'SIGTERM',
      env: {
        ...process.env,
        npm_config_registry: registry,
        npm_config_fetch_retries: '1',
        npm_config_fetch_timeout: '15000',
      },
    }
  );
  if (result.error) {
    fail(`无法执行 npm: ${result.error.message}`);
  }
  if (result.status !== 0) {
    fail(`检查 OpenXiangda 更新失败: ${formatSpawnOutput(result)}`);
  }
  const raw = String(result.stdout || '').trim();
  if (!raw) fail('检查 OpenXiangda 更新失败: npm 未返回版本号');
  try {
    const parsed = JSON.parse(raw);
    return String(parsed).trim();
  } catch (_error) {
    return raw.replace(/^"|"$/g, '').trim();
  }
}

function normalizeUpdateInstallTimeoutSeconds(value) {
  const parsed = Number(value === undefined ? 300 : value);
  if (!Number.isFinite(parsed) || parsed < 30 || parsed > 1800) {
    fail('--timeout-seconds 必须是 30 到 1800 之间的数字');
  }
  return Math.round(parsed);
}

function buildOpenXiangdaUpdateInstallPlan(registryInput, options = {}) {
  const registry = normalizeNpmRegistry(registryInput);
  const selection = resolveUpdateTarget(options);
  const version = options.version || fetchLatestOpenXiangdaVersion(registry, selection.channel);
  const execution = buildGenerationUpdateCommand(selection, version);
  const timeoutSeconds = normalizeUpdateInstallTimeoutSeconds(
    options.timeoutSeconds
  );
  return {
    registry,
    timeoutSeconds,
    ...selection,
    command: execution.command,
    version,
    args: [
      ...execution.args,
      `--registry=${registry}`,
      ...(execution.command === 'npm' ? [
      '--prefer-offline',
      '--legacy-peer-deps',
      '--no-audit',
      '--no-fund',
      '--progress=false',
      '--fetch-retries=2',
      '--fetch-timeout=60000',
      '--fetch-retry-mintimeout=1000',
      '--fetch-retry-maxtimeout=10000',
      ] : []),
    ],
  };
}

async function runCommandWithHeartbeat(command, args, options = {}) {
  const startedAt = Date.now();
  const quiet = Boolean(options.quiet);
  const timeoutMs = Number(options.timeoutMs || 300000);
  return await new Promise(resolve => {
    let child;
    try {
      child = spawn(command, args, {
        cwd: options.cwd || process.cwd(),
        encoding: 'utf8',
        stdio: quiet ? ['ignore', 'pipe', 'pipe'] : 'inherit',
        env: options.env || process.env,
      });
    } catch (error) {
      resolve({
        status: null,
        error,
        stdout: '',
        stderr: '',
        timedOut: false,
        durationMs: Date.now() - startedAt,
      });
      return;
    }
    let stdout = '';
    let stderr = '';
    let spawnError = null;
    let timedOut = false;
    let forceKillTimer = null;
    const append = (current, chunk) =>
      `${current}${String(chunk || '')}`.slice(-2 * 1024 * 1024);
    child.stdout?.on('data', chunk => {
      stdout = append(stdout, chunk);
    });
    child.stderr?.on('data', chunk => {
      stderr = append(stderr, chunk);
    });
    child.once('error', error => {
      spawnError = error;
    });
    const heartbeat = setInterval(() => {
      const seconds = Math.max(1, Math.round((Date.now() - startedAt) / 1000));
      process.stderr.write(
        `[openxiangda update] npm 仍在运行 (${seconds}s)，正在使用本地缓存并限制网络重试…\n`
      );
    }, 15000);
    heartbeat.unref?.();
    const timeout = setTimeout(() => {
      timedOut = true;
      child.kill('SIGTERM');
      forceKillTimer = setTimeout(() => child.kill('SIGKILL'), 5000);
      forceKillTimer.unref?.();
    }, timeoutMs);
    timeout.unref?.();
    child.once('close', (status, signal) => {
      clearInterval(heartbeat);
      clearTimeout(timeout);
      if (forceKillTimer) clearTimeout(forceKillTimer);
      resolve({
        status,
        signal,
        error: spawnError,
        stdout,
        stderr,
        timedOut,
        durationMs: Date.now() - startedAt,
      });
    });
  });
}

async function installOpenXiangdaUpdate(registry, options = {}) {
  const plan = buildOpenXiangdaUpdateInstallPlan(registry, options);
  const npmArgs = plan.args;
  const quiet = Boolean(options.json);
  if (!quiet) {
    print(`执行: npm ${npmArgs.join(' ')}`);
  }
  const installResult = await runCommandWithHeartbeat(plan.command, npmArgs, {
    cwd: plan.cwd,
    quiet,
    timeoutMs: plan.timeoutSeconds * 1000,
    env: { ...process.env, npm_config_registry: plan.registry },
  });
  if (installResult.timedOut) {
    fail(
      `OPENXIANGDA_UPDATE_TIMEOUT: npm 安装超过 ${plan.timeoutSeconds}s，已终止；缓存已保留，可直接重试 openxiangda update install`
    );
  }
  if (installResult.error) {
    fail(`无法执行 npm: ${installResult.error.message}`);
  }
  if (installResult.status !== 0) {
    fail(`OpenXiangda 更新失败: ${formatSpawnOutput(installResult)}`);
  }

  const result = {
    packageName: NPM_PACKAGE_NAME,
    registry: plan.registry,
    installCommand: `npm ${npmArgs.join(' ')}`,
    installed: true,
    durationMs: installResult.durationMs,
    cacheMode: 'prefer-offline',
    timeoutSeconds: plan.timeoutSeconds,
    skillInstall: {
      attempted: false,
      status: null,
      error: null,
    },
  };

  if (!options.skipSkills && plan.target === 'workspace') {
    if (!quiet) {
      print('刷新 OpenXiangda skills: openxiangda skill install --force');
    }
    const localManifest = path.join(plan.cwd, 'node_modules/openxiangda/package.json');
    const localPackage = JSON.parse(fs.readFileSync(localManifest, 'utf8'));
    const localBin = path.resolve(path.dirname(localManifest), typeof localPackage.bin === 'string' ? localPackage.bin : localPackage.bin.openxiangda);
    const skillResult = spawnSync(process.execPath, [localBin, 'skill', 'install'], {
      cwd: plan.cwd,
      encoding: 'utf8',
      stdio: quiet ? 'pipe' : 'inherit',
      timeout: 60000,
      killSignal: 'SIGTERM',
      env: process.env,
    });
    result.skillInstall.attempted = true;
    result.skillInstall.status = skillResult.status;
    if (skillResult.error || skillResult.status !== 0) {
      result.skillInstall.error = skillResult.error?.message || formatSpawnOutput(skillResult);
    }
  }

  return result;
}

function printUpdateCheck(result) {
  const lines = [
    'OpenXiangda update check',
    `current: ${result.currentVersion}`,
    `latest: ${result.latestVersion}`,
    `registry: ${result.registry}`,
  ];
  if (result.updateAvailable) {
    lines.push('status: update available');
    lines.push('recommended:');
    lines.push(`  ${result.installCommand}`);
    lines.push(`  ${result.skillInstallCommand}`);
  } else if (result.status === 'local_newer_than_registry') {
    lines.push('status: local version is newer than registry');
  } else {
    lines.push('status: already latest');
  }
  lines.push(`compatibility: ${result.compatibilityCheckCommand}`);
  print(lines.join('\n'));
}

function formatSpawnOutput(result) {
  return (
    String(result.stderr || '').trim() ||
    String(result.stdout || '').trim() ||
    `exit status ${result.status}`
  );
}

function compareVersions(a, b) {
  const left = parseSemver(a);
  const right = parseSemver(b);
  for (let index = 0; index < 3; index += 1) {
    if (left.numbers[index] !== right.numbers[index]) {
      return left.numbers[index] > right.numbers[index] ? 1 : -1;
    }
  }
  if (left.prerelease === right.prerelease) return 0;
  if (!left.prerelease) return 1;
  if (!right.prerelease) return -1;
  return left.prerelease > right.prerelease ? 1 : -1;
}

function parseSemver(value) {
  const match = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?/.exec(String(value || ''));
  if (!match) {
    return { numbers: [0, 0, 0], prerelease: String(value || '') };
  }
  return {
    numbers: [Number(match[1]), Number(match[2]), Number(match[3])],
    prerelease: match[4] || '',
  };
}

async function design(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  const topic = flags.topic || positional[0];
  if (wantsSubcommandHelp(subcommand, flags)) {
    if (flags.json) return writeJson(getDesignTopicCatalog());
    print(renderDesignHelp());
    return;
  }

  if (subcommand === 'gates') {
    const result = getDesignGates(topic);
    if (flags.json) return writeJson(result);
    print(renderDesignGatesText(topic));
    return;
  }

  if (subcommand === 'template') {
    const result = {
      topic: topic || 'all',
      content: renderDesignTemplate(topic),
    };
    if (flags.json) return writeJson(result);
    print(result.content);
    return;
  }

  if (subcommand === 'review') {
    const hasResources = fs.existsSync(path.join(process.cwd(), 'src', 'resources'));
    const manifest = hasResources ? loadWorkspaceResources() : null;
    const validation = manifest ? validateWorkspaceResources(manifest) : {
      errors: [],
      warnings: ['未发现 src/resources，无法审查资源 manifest'],
    };
    const result = buildDesignReview({
      cwd: process.cwd(),
      manifest,
      validation,
    });
    if (flags.json) return writeJson(result);
    print(renderDesignReview(result));
    return;
  }

  fail('用法: openxiangda design gates|template|review [--topic code] [--json]');
}

async function sdd(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda sdd init|migrate|propose|quick|ready|bundle|approve|status|context|verify|render|sync|archive [change] [--change id] [--json]',
      '常用流程:',
      '  openxiangda sdd init --upgrade',
      '  openxiangda sdd propose add-customer-list --title "客户列表" --forms customer --pages customer_list --resources',
      '  openxiangda sdd propose shared-query-fix --changed-resources-json <JSON|file> --runtime-dependencies-json <JSON|file> --deploy-targets-json <JSON|file>',
      '  openxiangda sdd quick tune-customer-copy --kind copy --pages customer_list --files src/pages/customer_list/index.tsx --summary "用户确认小范围文案调整"',
      '  openxiangda sdd approve add-customer-list --summary "用户确认设计"',
      '  openxiangda sdd ready add-customer-list',
      '  openxiangda sdd bundle mainline-release --changes add-customer-list,fix-order-log [--source-base-ref <commit>]',
      '  openxiangda sdd context --change add-customer-list --json',
      '  openxiangda sdd verify --change add-customer-list --stage prepublish --json',
      '  openxiangda sdd render add-customer-list  # 仅在确实需要完整文档时',
      '  openxiangda sdd archive --change add-customer-list',
      '说明:',
      '  - SDD 记录保存在 openspec/，不依赖官方 OpenSpec CLI。',
      '  - 新工作区默认只维护 change.json/coverage.json/release.json；proposal/specs/design/tasks/evidence 由 sdd render 按需生成。',
      '  - 高风险发布需要 approved change 的 coverage 覆盖本次 forms/pages/functions/automations/workflows/JS_CODE/resources/runtime 目标和高风险文件。',
      '  - 新 change 将 changedResources（实际修改）、runtimeDependencies（构建/运行依赖）、deployTargets（本次激活）分开记录；依赖不会再自动扩大部署范围。',
      '  - --change 使用该 change 的 coverage/release 与范围内 dirty files；不会吸收其他并行会话的全局变更。',
      '  - 在 Codex 中 propose/quick/context 会按 CODEX_THREAD_ID 占用当前 worktree；其他任务必须切换到独立 worktree。',
      '  - quick 仅用于 L1 精确小改动；Function quick 还必须提供完整 --risk-json，不能用 riskTier 标签绕过。',
      '  - verify stage 可选 implementation、prepublish、postpublish、archive；不传保持旧版全量校验。',
      '  - 默认 streamlined 校验只把 approval、精确资源/文件范围、实际发布命令作为硬门禁；任务、证据和规格文案仅告警。配置 strictDocumentation: true 可恢复严格文档门禁。',
      '  - bundle 聚合多个 approved change；提交并推送该 bundle 后，在权威主分支执行一次 staged + atomic 发布。',
      '  - bundle 默认保留来源 change 创建时的共同 Git 基线；仅迁移旧 change 缺少 sourceBase 时使用 --source-base-ref 显式补充。',
      '  - 新 release 只能从已推送且与权威远端默认主分支一致的 clean HEAD 开始。',
      '  - release end 后回到 canonical 主工作区运行 workspace cleanup；只对 SAFE 项执行 --apply。',
    ].join('\n'));
    return;
  }

  if (subcommand === 'init' || subcommand === 'migrate' || subcommand === 'upgrade') {
    const result = initSddWorkspace({
      cwd: process.cwd(),
      path: flags.path,
      force: Boolean(flags.force),
      upgrade: Boolean(flags.upgrade || subcommand === 'migrate' || subcommand === 'upgrade'),
    });
    if (flags.json) return writeJson(result);
    printSddInitReport(result);
    return;
  }

  if (subcommand === 'propose' || subcommand === 'new') {
    const changeId = positional[0] || flags.change;
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const affected = parseSddAffectedFlags(flags);
    const result = proposeSddChange({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
      title: flags.title || flags.name,
      riskLevel: flags.risk || flags['risk-level'],
      domain: flags.domain,
      force: Boolean(flags.force),
      affected,
      scopes: parseSddScopeFlags(flags, affected),
    });
    if (flags.json) return writeJson(result);
    print(`已创建 SDD change: ${result.change.id}\n目录: ${result.dir}`);
    return;
  }

  if (subcommand === 'quick') {
    const changeId = positional[0] || flags.change;
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const affected = parseSddAffectedFlags(flags);
    const riskAssessment = flags['risk-json']
      ? readJsonArg(flags['risk-json'], 'risk-json')
      : flags['risk-file']
        ? readJsonArg(flags['risk-file'], 'risk-file')
        : {};
    const result = createQuickSddChange({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
      title: flags.title || flags.name,
      changeKind: flags.kind || flags['change-kind'],
      approvalSummary: flags.summary || flags.note,
      affected,
      scopes: parseSddScopeFlags(flags, affected),
      riskAssessment,
    });
    if (flags.json) return writeJson(result);
    print(
      `已创建并确认 L1 quick change: ${result.change.id}\nkind=${result.change.changeKind} risk=${result.change.riskTier}`
    );
    return;
  }

  if (subcommand === 'bundle') {
    const changeId = positional[0] || flags.change;
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const sourceChangeIds = String(flags.changes || '')
      .split(',')
      .map(item => item.trim())
      .filter(Boolean);
    const integration = collectIntegrationTaskResults({
      cwd: process.cwd(),
      changeIds: sourceChangeIds,
    });
    const result = createMainlineSddBundle({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
      title: flags.title || flags.name,
      changes: flags.changes,
      integration,
      profile: flags.profile,
      sourceBaseRef: flags['source-base-ref'],
      force: Boolean(flags.force),
    });
    if (flags.json) return writeJson(result);
    print(
      `已创建主线发布 bundle: ${result.change.id}\nchanges=${result.bundledChanges.join(', ')}\n目录: ${result.dir}`
    );
    return;
  }

  if (subcommand === 'ready') {
    const changeId = positional[0] || flags.change;
    const scope = getSddChangeScope({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
    });
    if (scope.change?.status !== 'approved' || !scope.change?.approvedAt) {
      fail(`INTEGRATION_TASK_CHANGE_NOT_APPROVED: ${changeId} 尚未 approved`);
    }
    const result = recordIntegrationTaskResult({
      cwd: process.cwd(),
      changeId,
      targets: scope.targets,
      changedFiles: scope.changedFiles,
      sourceBase: scope.change?.sourceBase,
    });
    const ownerStatus = getWorktreeOwnerStatus({ cwd: process.cwd() });
    if (
      ownerStatus.ownedByCurrentThread &&
      ownerStatus.owner?.changeId === changeId
    ) {
      const released = releaseWorktreeOwner({
        cwd: process.cwd(),
        expectedThreadId: ownerStatus.owner.threadId,
        expectedChangeId: changeId,
      });
      result.worktreeOwnershipReleased = Boolean(released.released);
    }
    result.nextActions = [
      '将任务提交合并并 push 到权威远端默认主分支',
      '从 canonical main/master 创建 bundle 并完成 release end',
      '运行 openxiangda workspace cleanup，确认 SAFE 后再运行 --apply',
    ];
    if (flags.json) return writeJson(result);
    print(
      `任务已准备合并: ${result.changeId}@${result.commit.slice(0, 12)}\nbranch=${result.branch}${result.worktreeOwnershipReleased ? '\nworktree owner 已自动释放' : ''}\n下一步: 合并/push → canonical 主线发布并 release end → workspace cleanup`
    );
    return;
  }

  if (subcommand === 'approve') {
    const changeId = positional[0] || flags.change;
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const result = approveSddChange({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
      summary: flags.summary || flags.note,
    });
    if (flags.json) return writeJson(result);
    print(`SDD change 已确认: ${result.change.id} approvedAt=${result.change.approvedAt}`);
    return;
  }

  if (subcommand === 'status' || subcommand === 'context') {
    const changeId = positional[0] || flags.change;
    if (subcommand === 'context') {
      assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    }
    const releasePlan = buildWorkspaceReleasePlan({
      changed: Boolean(flags.changed || flags['changed-only']),
      since: flags.since,
      profile: flags.profile || '<profile>',
      skipSdd: true,
      changeId,
    });
    const status = buildSddStatus({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      releasePlan,
      changeId,
    });
    const result = {
      ...status,
      releasePlan,
      contracts:
        subcommand === 'context'
          ? Object.fromEntries(
              Object.entries(API_CONTRACTS).map(([name, contract]) => [
                name,
                {
                  mode: contract.mode,
                  endpoint: contract.endpoint,
                  response: contract.response,
                  guarantees: contract.guarantees,
                },
              ])
            )
          : undefined,
    };
    if (flags.json || subcommand === 'context') return writeJson(result);
    printSddStatusReport(result);
    return;
  }

  if (subcommand === 'verify') {
    const changeId = positional[0] || flags.change;
    const hasExplicitReleaseScope = Boolean(
      changeId || flags.changed || flags['changed-only'] || flags.since || flags.all || flags['no-changed']
    );
    const releasePlan = hasExplicitReleaseScope
      ? buildWorkspaceReleasePlan({
          changed: Boolean(flags.changed || flags['changed-only'] || flags.since) && flags.changed !== false,
          since: flags.since,
          profile: flags.profile || '<profile>',
          skipSdd: true,
          changeId,
        })
      : null;
    const result = verifySddChange({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
      releasePlan,
      writeMetadata: false,
      stage: flags.stage,
    });
    if (flags.json) {
      writeJson(result);
      if (!result.passed) process.exitCode = 1;
      return;
    }
    printSddVerifyReport(result);
    if (!result.passed) fail(`SDD verify 失败: ${result.errors[0].message}`);
    return;
  }

  if (subcommand === 'render') {
    const changeId = positional[0] || flags.change;
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const result = renderSddDocumentation({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
      force: Boolean(flags.force),
    });
    if (flags.json) return writeJson(result);
    print(
      result.rendered.length > 0
        ? `已按需生成 SDD 文档:\n${result.rendered.map(item => `- ${item}`).join('\n')}`
        : 'SDD 文档已存在；使用 --force 重新生成'
    );
    return;
  }

  if (subcommand === 'sync') {
    const changeId = positional[0] || flags.change;
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const result = syncSddChange({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
    });
    if (flags.json) return writeJson(result);
    print(`SDD specs 已同步: ${result.change.id}\n${result.synced.map(item => `- ${item}`).join('\n')}`);
    return;
  }

  if (subcommand === 'archive') {
    const changeId = positional[0] || flags.change;
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const releasePlan = buildWorkspaceReleasePlan({
      changed: flags.changed !== false,
      since: flags.since,
      profile: flags.profile || '<profile>',
      skipSdd: true,
      changeId,
    });
    const result = archiveSddChange({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
      releasePlan,
      force: Boolean(flags.force),
    });
    releaseWorktreeOwner({ cwd: process.cwd() });
    if (flags.json) return writeJson(result);
    print(`SDD change 已归档: ${result.change.id}\n目录: ${result.archiveDir}`);
    return;
  }

  fail('用法: openxiangda sdd init|migrate|propose|quick|bundle|approve|status|context|verify|render|sync|archive [change] [--json]');
}

function parseSddAffectedFlags(flags) {
  const split = value =>
    value === undefined || value === null || value === false
      ? []
      : String(value)
          .split(',')
          .map(item => item.trim())
          .filter(Boolean);
  return {
    forms: split(flags.forms || flags.form),
    pages: split(flags.pages || flags.page),
    functions: split(flags.functions || flags.function),
    automations: split(flags.automations || flags.automation),
    workflows: split(flags.workflows || flags.workflow),
    jsCodeNodes: split(flags['js-code-nodes'] || flags.jsCodeNodes || flags['js-code']),
    files: split(flags.files || flags.file),
    resources: Boolean(flags.resources),
    runtime: Boolean(flags.runtime),
    backend: Boolean(flags.backend),
    contracts: Boolean(flags.contracts),
  };
}

function parseSddScopeFlags(flags, affected) {
  const combined = flags['scopes-json']
    ? readJsonArg(flags['scopes-json'], 'scopes-json')
    : {};
  const readScope = (flagName, fieldName, fallback) =>
    flags[flagName]
      ? readJsonArg(flags[flagName], flagName)
      : combined?.[fieldName] || fallback;
  return {
    changedResources: readScope(
      'changed-resources-json',
      'changedResources',
      affected
    ),
    runtimeDependencies: readScope(
      'runtime-dependencies-json',
      'runtimeDependencies',
      {}
    ),
    deployTargets: readScope(
      'deploy-targets-json',
      'deployTargets',
      affected
    ),
  };
}

function releaseExecutionDir(changeId) {
  return path.join(
    process.cwd(),
    '.openxiangda',
    'releases',
    String(changeId || '').trim()
  );
}

function releaseExecutionFile(changeId, deploymentId) {
  return releaseExecutionPath(changeId, deploymentId, process.cwd());
}

function directPublishReceiptFile(changeId) {
  return path.join(releaseExecutionDir(changeId), 'direct-publish.json');
}

function managedShipFile(changeId) {
  return path.join(releaseExecutionDir(changeId), 'ship.json');
}

function readManagedShip(changeId) {
  const file = managedShipFile(changeId);
  if (!fs.existsSync(file)) return null;
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (error) {
    fail(
      `MANAGED_SHIP_INVALID: ${path.relative(process.cwd(), file)} 无法读取: ${error.message}`
    );
  }
}

function writeManagedShip(changeId, value) {
  const existing = readManagedShip(changeId);
  const now = new Date().toISOString();
  const record = {
    schemaVersion: 'openxiangda_managed_ship_v1',
    changeId,
    createdAt: existing?.createdAt || now,
    ...(existing || {}),
    ...value,
    updatedAt: now,
  };
  const file = managedShipFile(changeId);
  writePrivateJsonAtomic(file, record);
  return {
    record,
    file: path.relative(process.cwd(), file).replace(/\\/g, '/'),
  };
}

function normalizeManagedShipIntent(value = {}) {
  const enabled = Boolean(value.enabled);
  return {
    enabled,
    reason: enabled
      ? String(value.reason || '').trim() || null
      : null,
  };
}

function managedShipIntentMatches(left, right) {
  const normalizedLeft = normalizeManagedShipIntent(left);
  const normalizedRight = normalizeManagedShipIntent(right);
  return (
    normalizedLeft.enabled === normalizedRight.enabled &&
    normalizedLeft.reason === normalizedRight.reason
  );
}

function resolveManagedShipIntents(flags = {}, existingShip = null) {
  const manifestReplacement = normalizeManagedShipIntent({
    enabled: flags['replace-manifest'],
    reason: flags.reason,
  });
  const requestedBaselineAdoption = normalizeManagedShipIntent({
    enabled: flags['adopt-online-baseline'],
    reason: flags['adoption-reason'],
  });
  const requestedRuntimeRollback = normalizeManagedShipIntent({
    enabled: flags['allow-runtime-rollback'],
    reason: flags.reason,
  });
  const hasFrozenCandidate = Boolean(existingShip?.candidateId);
  let baselineAdoption = requestedBaselineAdoption;
  let runtimeRollback = requestedRuntimeRollback;

  if (hasFrozenCandidate) {
    const recordedReplacement = normalizeManagedShipIntent(
      existingShip.manifestReplacement
    );
    if (!managedShipIntentMatches(recordedReplacement, manifestReplacement)) {
      fail(
        'RELEASE_SHIP_REPLACE_MANIFEST_INTENT_MISMATCH: --replace-manifest/--reason 必须与该 candidate 的预发发布意图完全一致；请使用 ship.json 记录的同一对参数'
      );
    }

    const hasRecordedAdoption = Object.prototype.hasOwnProperty.call(
      existingShip,
      'baselineAdoption'
    );
    const recordedAdoption = normalizeManagedShipIntent(
      existingShip.baselineAdoption
    );
    const adoptionExplicitlySupplied =
      Object.prototype.hasOwnProperty.call(
        flags,
        'adopt-online-baseline'
      ) ||
      Object.prototype.hasOwnProperty.call(flags, 'adoption-reason');
    if (
      hasRecordedAdoption &&
      adoptionExplicitlySupplied &&
      !managedShipIntentMatches(recordedAdoption, requestedBaselineAdoption)
    ) {
      fail(
        'RELEASE_SHIP_ADOPTION_INTENT_MISMATCH: --adopt-online-baseline/--adoption-reason 与该 candidate 的预发发布意图不一致；省略这两个参数可自动复用 ship.json 中的已冻结意图'
      );
    }
    baselineAdoption = adoptionExplicitlySupplied
      ? requestedBaselineAdoption
      : recordedAdoption;

    const hasRecordedRuntimeRollback = Object.prototype.hasOwnProperty.call(
      existingShip,
      'runtimeRollback'
    );
    const recordedRuntimeRollback = normalizeManagedShipIntent(
      existingShip.runtimeRollback
    );
    const runtimeRollbackExplicitlySupplied =
      Object.prototype.hasOwnProperty.call(
        flags,
        'allow-runtime-rollback'
      );
    if (
      hasRecordedRuntimeRollback &&
      runtimeRollbackExplicitlySupplied &&
      !managedShipIntentMatches(
        recordedRuntimeRollback,
        requestedRuntimeRollback
      )
    ) {
      fail(
        'RELEASE_SHIP_RUNTIME_ROLLBACK_INTENT_MISMATCH: --allow-runtime-rollback/--reason 与该 candidate 的预发 Runtime 发布意图不一致；省略这两个参数可自动复用 ship.json 中的已冻结意图'
      );
    }
    runtimeRollback = runtimeRollbackExplicitlySupplied
      ? requestedRuntimeRollback
      : recordedRuntimeRollback;
  }

  const effectiveFlags = { ...flags };
  if (baselineAdoption.enabled) {
    effectiveFlags['adopt-online-baseline'] = true;
    effectiveFlags['adoption-reason'] = baselineAdoption.reason;
  } else {
    delete effectiveFlags['adopt-online-baseline'];
    delete effectiveFlags['adoption-reason'];
  }
  if (runtimeRollback.enabled) {
    const existingReason = String(effectiveFlags.reason || '').trim();
    if (existingReason && existingReason !== runtimeRollback.reason) {
      fail(
        'RELEASE_SHIP_RUNTIME_ROLLBACK_REASON_CONFLICT: Runtime rollback 与 manifest replacement 共用 --reason 时必须使用同一审计原因'
      );
    }
    effectiveFlags['allow-runtime-rollback'] = true;
    effectiveFlags.reason = runtimeRollback.reason;
  } else {
    delete effectiveFlags['allow-runtime-rollback'];
  }

  return {
    manifestReplacement,
    baselineAdoption,
    runtimeRollback,
    effectiveFlags,
  };
}

function buildManagedShipCommand(
  changeId,
  profileName,
  intents,
  options = {}
) {
  const args = [
    'openxiangda release ship',
    '--change',
    JSON.stringify(changeId),
    '--profile',
    JSON.stringify(profileName),
  ];
  if (options.confirmProduction) args.push('--confirm-production');
  let sharedReason = null;
  if (intents.manifestReplacement.enabled) {
    args.push('--replace-manifest');
    sharedReason = intents.manifestReplacement.reason;
  }
  if (intents.runtimeRollback.enabled) {
    args.push('--allow-runtime-rollback');
    sharedReason = intents.runtimeRollback.reason;
  }
  if (sharedReason) {
    args.push('--reason', JSON.stringify(sharedReason));
  }
  if (intents.baselineAdoption.enabled) {
    args.push(
      '--adopt-online-baseline',
      '--adoption-reason',
      JSON.stringify(intents.baselineAdoption.reason)
    );
  }
  return args.join(' ');
}

function managedShipFailure(error) {
  return {
    code: String(error?.code || 'OPENXIANGDA_DEPLOYMENT_FAILED'),
    message: maskText(error?.message || String(error)).slice(0, 2000),
    deploymentId: error?.deploymentId || null,
    deploymentStatus: error?.deploymentStatus || 'failed',
    recordedAt: new Date().toISOString(),
  };
}

function writePrivateJsonAtomic(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const tempFile = `${file}.${process.pid}.${Date.now()}.tmp`;
  fs.writeFileSync(tempFile, `${JSON.stringify(value, null, 2)}\n`, {
    mode: 0o600,
  });
  fs.renameSync(tempFile, file);
}

function readReleaseExecution(changeId, deploymentId) {
  const file = releaseExecutionFile(changeId, deploymentId);
  if (!fs.existsSync(file)) return null;
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (error) {
    fail(
      `RELEASE_EXECUTION_INVALID: ${path.relative(process.cwd(), file)} 无法读取: ${error.message}`
    );
  }
}

function readDirectPublishReceipt(changeId) {
  const file = directPublishReceiptFile(changeId);
  if (!fs.existsSync(file)) return null;
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (error) {
    fail(
      `DIRECT_PUBLISH_RECEIPT_INVALID: ${path.relative(process.cwd(), file)} 无法读取: ${error.message}`
    );
  }
}

function writeDirectPublishReceipt(changeId, input = {}) {
  if (!changeId) return null;
  const receipt = {
    schemaVersion: 'openxiangda_direct_publish_receipt_v1',
    changeId,
    status: 'completed',
    command: input.command || null,
    writeAttempted: Boolean(input.writeAttempted),
    selectors: unique(input.selectors || []).sort(),
    sourceRevision: input.sourceRevision || null,
    result: input.result || null,
    completedAt: new Date().toISOString(),
  };
  const file = directPublishReceiptFile(changeId);
  writePrivateJsonAtomic(file, receipt);
  return {
    file: path.relative(process.cwd(), file).replace(/\\/g, '/'),
    receipt,
  };
}

function summarizeReleaseStepResult(result) {
  const value =
    result && typeof result === 'object' && !Array.isArray(result)
      ? result
      : {};
  const findId = candidate =>
    String(
      candidate?.id ||
        candidate?.releaseId ||
        candidate?.activeAppReleaseId ||
        ''
    ).trim() || null;
  return {
    resultHash: canonicalJsonSha256(value),
    releaseId:
      findId(value.activated) ||
      findId(value.verified) ||
      findId(value.prepared) ||
      findId(value),
    healthStatus:
      value.healthWait?.status ||
      value.activated?.activation?.postCommit?.status ||
      null,
  };
}

function releaseExecutionContextFromBegin(result, target, changeId) {
  const value =
    result && typeof result === 'object' && !Array.isArray(result)
      ? result
      : {};
  const releaseSourceRevision =
    value.releaseSourceRevision &&
    typeof value.releaseSourceRevision === 'object' &&
    !Array.isArray(value.releaseSourceRevision)
      ? value.releaseSourceRevision
      : null;
  if (
    !value.leaseId ||
    !value.clientSessionId ||
    !releaseSourceRevision?.baseCommit
  ) {
    return null;
  }
  return {
    appType: target.appType,
    profile: target.profileName,
    changeId,
    deploymentId: target.deploymentId || null,
    leaseId: String(value.leaseId),
    baselineId: value.baselineId ? String(value.baselineId) : null,
    clientSessionId: String(value.clientSessionId),
    releaseSourceRevision,
    capturedAt: new Date().toISOString(),
  };
}

function parseChildJsonOutput(stdout) {
  const text = String(stdout || '').trim();
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    const lines = text.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const candidate = lines.slice(index).join('\n').trim();
      if (!candidate.startsWith('{') && !candidate.startsWith('[')) continue;
      try {
        return JSON.parse(candidate);
      } catch {
        // Continue until the first complete JSON payload is found.
      }
    }
    return { output: maskText(text).slice(-4000) };
  }
}

async function runOpenXiangdaInProcess(args, options = {}) {
  let stdout = '';
  const originalWrite = process.stdout.write;
  const previousExitCode = process.exitCode;
  process.exitCode = undefined;
  process.stdout.write = function capture(chunk, encoding, callback) {
    stdout += Buffer.isBuffer(chunk) ? chunk.toString(encoding) : String(chunk);
    if (typeof encoding === 'function') encoding();
    if (typeof callback === 'function') callback();
    return true;
  };
  try {
    await mainImpl([...args, '--json']);
    if (process.exitCode && process.exitCode !== 0) {
      const error = new Error(
        maskText(stdout).trim() ||
          `openxiangda ${args.join(' ')} exited with ${process.exitCode}`
      );
      error.code =
        error.message.match(/\b([A-Z][A-Z0-9_]{3,})\b/)?.[1] ||
        'RELEASE_STEP_FAILED';
      error.exitCode = process.exitCode;
      throw error;
    }
    return parseChildJsonOutput(stdout);
  } catch (error) {
    if (!options.quiet && stdout.trim()) {
      warn(maskText(stdout).trimEnd());
    }
    throw error;
  } finally {
    process.stdout.write = originalWrite;
    process.exitCode = previousExitCode;
  }
}

function getDeliveryV2Cli() {
  if (deliveryV2Cli) return deliveryV2Cli;
  deliveryV2Cli = createDeliveryV2Cli({
    clearDeliveryContext: clearDeliveryV2Context,
    downloadWithAuth,
    getWorkspaceTarget,
    installDeliveryContext: installDeliveryV2Context,
    loadConfig,
    requestFormWithAuth,
    requestWithAuth,
    runOpenXiangdaInProcess,
  });
  return deliveryV2Cli;
}

function installDeliveryV2Context(target, run, targets = {}) {
  const control = run?.control || {};
  const publishLeaseId = String(control.publishLeaseId || '').trim();
  const baselineId = String(control.baselineId || '').trim();
  const changeId = String(control.changeId || '').trim();
  const clientSessionId = String(control.clientSessionId || '').trim();
  const packageDigest = String(run?.packageDigest || '').trim();
  if (
    !publishLeaseId ||
    !baselineId ||
    !changeId ||
    !clientSessionId ||
    !/^[a-f0-9]{64}$/.test(packageDigest)
  ) {
    fail(
      'DELIVERY_CONTROL_INVALID: ReleaseRun 缺少 publishLease/baseline/change/session/package 控制信息'
    );
  }
  const sourceRevision = deliveryV2SourceRevision(target, packageDigest);
  saveChangeBaseline(target, {
    baselineId,
    appType: target.appType,
    profile: target.profileName,
    changeId,
    clientSessionId,
    sourceBase: {
      repo: sourceRevision.repo,
      baseCommit: packageDigest,
      treeHash: packageDigest,
    },
    releaseSourceRevision: sourceRevision,
    resourceHeads: {},
    lifecycleState: 'active',
  });
  savePublishLease(target, {
    leaseId: publishLeaseId,
    expiresAt:
      control.leaseExpiresAt ||
      new Date(Date.now() + 60 * 60 * 1000).toISOString(),
    appType: target.appType,
    profile: target.profileName,
    changeId,
    clientSessionId,
    baseRevision: packageDigest,
    holder: 'self',
    workspace: {
      branch: 'delivery-v2',
      commit: packageDigest,
      treeHash: packageDigest,
    },
  });
  activeDeliveryV2Context = {
    runId: run.id,
    appType: target.appType,
    profileName: target.profileName,
    packageDigest,
    publishLeaseId,
    baselineId,
    changeId,
    clientSessionId,
    leaseExpiresAt: control.leaseExpiresAt,
    sourceRevision,
    targets,
  };
  activePublishRequestContext = normalizePublishContext({
    appType: target.appType,
    profileName: target.profileName,
    publishLeaseId,
    changeBaselineId: baselineId,
    changeId,
    clientSessionId,
  });
  return activeDeliveryV2Context;
}

function clearDeliveryV2Context(target, run) {
  const context = activeDeliveryV2Context;
  if (!context) return;
  if (run?.id && context.runId !== run.id) return;
  clearPublishLease(target, context.publishLeaseId);
  clearChangeBaseline(target, context.baselineId);
  activePublishRequestContext = null;
  activeDeliveryV2Context = null;
}

function normalizeReleaseWaitSeconds(flags) {
  const raw =
    readStringFlag(flags, 'wait-seconds') ||
    readStringFlag(flags, 'lease-wait-seconds');
  if (raw === '') return 1800;
  const value = Number(raw);
  if (!Number.isFinite(value) || value < 0 || value > 86400) {
    fail('--wait-seconds 必须是 0-86400 之间的秒数');
  }
  return Math.floor(value);
}

async function waitForPublishLeaseAvailability(config, target, flags = {}) {
  if (getUsableStoredPublishLease(target)) return { waitedMs: 0 };
  const waitSeconds = normalizeReleaseWaitSeconds(flags);
  const startedAt = Date.now();
  const deadline = startedAt + waitSeconds * 1000;
  const clientSessionId = createPublishClientSessionId();
  let attempts = 0;
  let lastNoticeFingerprint = '';
  let lastNoticeAt = 0;
  while (true) {
    const remote = await fetchPublishLeaseStatus(
      config,
      target,
      clientSessionId
    );
    if (!remote?.active) {
      return { waitedMs: Date.now() - startedAt, attempts, remote };
    }
    const remoteHolder =
      remote?.changeId ||
      remote?.clientSessionId ||
      remote?.holder?.changeId ||
      remote?.holder?.clientSessionId ||
      (typeof remote?.holder === 'string' ? remote.holder : null) ||
      'another release';
    if (Date.now() >= deadline) {
      fail(
        `PUBLISH_LEASE_WAIT_TIMEOUT: ${target.appType} 仍由 ${remoteHolder} 发布中；已等待 ${waitSeconds}s`
      );
    }
    attempts += 1;
    const suggestedSeconds = Number(
      remote?.retryAfterSeconds || remote?.retryAfter || 5
    );
    const delayMs = Math.min(
      Math.max(Number.isFinite(suggestedSeconds) ? suggestedSeconds * 1000 : 5000, 1000),
      30000,
      Math.max(1000, deadline - Date.now())
    );
    const noticeFingerprint = [
      remoteHolder,
      remote?.leaseId || '',
    ].join(':');
    if (
      noticeFingerprint !== lastNoticeFingerprint ||
      Date.now() - lastNoticeAt >= 120_000
    ) {
      warn(
        `发布队列等待中: app=${target.appType} holder=${remoteHolder} retry=${Math.ceil(delayMs / 1000)}s${remote?.expiresAt ? ` expiresAt=${remote.expiresAt}` : ''}`
      );
      lastNoticeFingerprint = noticeFingerprint;
      lastNoticeAt = Date.now();
    }
    await sleep(delayMs);
  }
}

function readReleaseRecoveryContext(target, changeId, deploymentId) {
  if (!changeId) return null;
  const execution = readReleaseExecution(changeId, deploymentId);
  const context = execution?.releaseContext;
  if (!context || typeof context !== 'object' || Array.isArray(context)) {
    return null;
  }
  if (
    context.appType !== target.appType ||
    context.profile !== target.profileName ||
    context.changeId !== changeId ||
    !context.leaseId ||
    !context.clientSessionId ||
    !context.releaseSourceRevision
  ) {
    return null;
  }
  return { execution, context };
}

function releaseSourceRevisionFromExecution(execution) {
  return (
    execution?.releaseSourceRevision ||
    execution?.releaseContext?.releaseSourceRevision ||
    null
  );
}

function privateReleasePathLabel(file) {
  return path.relative(process.cwd(), file).replace(/\\/g, '/');
}

function readReleaseLineageRecovery(changeId, deploymentId) {
  if (!changeId) {
    return {
      sourceRevision: null,
      source: null,
      checked: [],
    };
  }

  const checked = [];
  const recovered = [];
  const inspectedExecutions = new Set();
  const inspectExecution = (candidateDeploymentId, label) => {
    const normalizedDeploymentId = String(candidateDeploymentId || '').trim();
    const key = normalizedDeploymentId || '<root>';
    if (inspectedExecutions.has(key)) return;
    inspectedExecutions.add(key);
    const file = releaseExecutionFile(
      changeId,
      normalizedDeploymentId || undefined
    );
    const exists = fs.existsSync(file);
    const execution = exists
      ? readReleaseExecution(changeId, normalizedDeploymentId || undefined)
      : null;
    const sourceRevision = releaseSourceRevisionFromExecution(execution);
    const changeMatches =
      !execution?.changeId || execution.changeId === changeId;
    checked.push({
      label,
      file: privateReleasePathLabel(file),
      exists,
      field:
        sourceRevision && changeMatches
          ? 'releaseSourceRevision'
          : sourceRevision
            ? `changeId 不匹配 (${execution.changeId})`
            : '缺少 releaseContext.releaseSourceRevision/releaseSourceRevision',
    });
    if (sourceRevision && changeMatches) {
      recovered.push({
        sourceRevision,
        source: privateReleasePathLabel(file),
      });
    }
  };

  const shipFile = managedShipFile(changeId);
  const shipExists = fs.existsSync(shipFile);
  const ship = shipExists ? readManagedShip(changeId) : null;
  const shipSourceRevision = ship?.sourceRevision || null;
  checked.push({
    label: 'managed ship journal',
    file: privateReleasePathLabel(shipFile),
    exists: shipExists,
    field: shipSourceRevision ? 'sourceRevision' : '缺少 sourceRevision',
  });
  if (shipSourceRevision) {
    return {
      sourceRevision: shipSourceRevision,
      source: `${privateReleasePathLabel(shipFile)}#sourceRevision`,
      checked,
    };
  }

  if (deploymentId) {
    inspectExecution(deploymentId, 'explicit deployment execution');
  }
  for (const [label, candidateDeploymentId] of [
    ['production deployment execution', ship?.productionDeploymentId],
    ['preproduction deployment execution', ship?.preproductionDeploymentId],
  ]) {
    if (candidateDeploymentId) {
      inspectExecution(candidateDeploymentId, label);
    }
  }
  inspectExecution(null, 'root release execution');

  const releaseDir = releaseExecutionDir(changeId);
  if (fs.existsSync(releaseDir)) {
    for (const entry of fs
      .readdirSync(releaseDir, { withFileTypes: true })
      .filter(item => item.isDirectory())
      .sort((left, right) => left.name.localeCompare(right.name))) {
      inspectExecution(entry.name, 'discovered deployment execution');
    }
  }

  const distinct = new Map();
  for (const item of recovered) {
    const fingerprint = sha256Canonical({
      repo:
        item.sourceRevision?.repo ||
        item.sourceRevision?.repositoryId ||
        null,
      baseCommit:
        item.sourceRevision?.baseCommit ||
        item.sourceRevision?.commit ||
        null,
      treeHash: item.sourceRevision?.treeHash || null,
      remoteName: item.sourceRevision?.remoteName || null,
      remoteUrlHash: item.sourceRevision?.remoteUrlHash || null,
      mainBranch: item.sourceRevision?.mainBranch || null,
    });
    if (!distinct.has(fingerprint)) distinct.set(fingerprint, item);
  }
  if (distinct.size > 1) {
    fail(
      `RELEASE_SOURCE_LINEAGE_CONFLICT: change ${changeId} 的私有 deployment execution 日志包含互不一致的 releaseSourceRevision: ${Array.from(
        distinct.values(),
        item => item.source
      ).join(', ')}`
    );
  }
  return {
    sourceRevision: recovered[0]?.sourceRevision || null,
    source: recovered[0]?.source || null,
    checked,
  };
}

function remoteLeaseOwnedByRecovery(remote, recovery) {
  if (!remote?.active || !recovery) return false;
  const holder = remote.holder;
  const holderIsSelf =
    holder === 'self' ||
    holder?.self === true ||
    holder?.clientSessionId === recovery.clientSessionId;
  return Boolean(
    holderIsSelf &&
      String(remote.leaseId || '') === String(recovery.leaseId) &&
      String(remote.changeId || '') === String(recovery.changeId)
  );
}

async function endReleaseWithoutLocalLease(
  config,
  target,
  flags,
  baseline
) {
  const changeId = readStringFlag(flags, 'change');
  const recovered = readReleaseRecoveryContext(target, changeId);
  const recovery = recovered?.context || null;
  const clientSessionId =
    recovery?.clientSessionId ||
    baseline?.clientSessionId ||
    createPublishClientSessionId();
  const remote = await fetchPublishLeaseStatus(
    config,
    target,
    clientSessionId
  );
  const sourceRevision =
    baseline?.releaseSourceRevision ||
    recovery?.releaseSourceRevision ||
    null;

  if (remote?.active) {
    if (!recovery) {
      fail(
        `PUBLISH_LEASE_RECOVERY_REQUIRED: 远端仍有活动发布租约 ${remote.leaseId || '-'}；本地状态缺失，禁止误报 inactive。请使用原 change 的私有 execution.json 恢复，或等待租约过期后只读核对`
      );
    }
    if (!remoteLeaseOwnedByRecovery(remote, recovery)) {
      fail(
        'PUBLISH_LEASE_RECOVERY_MISMATCH: 远端活动租约不属于当前 change/session；未释放任何租约'
      );
    }
    const integration = assertReleaseSourceIntegrated(sourceRevision, {
      cwd: process.cwd(),
    });
    const remoteResult = await requestWithAuth(
      config,
      target.profileName,
      publishLeaseApiPath(
        target,
        `/${encodeURIComponent(recovery.leaseId)}/release`
      ),
      {
        method: 'POST',
        retryTransient: true,
        retries: 2,
        body: {
          completion: 'mainline-integrated-recovered',
          sourceCommit: integration.sourceCommit,
          mainBranch: integration.mainBranch,
          mainTipCommit: integration.mainTipCommit,
        },
      }
    );
    if (baseline) {
      clearChangeBaseline(target, baseline.baselineId || baseline.id);
    }
    releaseWorktreeOwner({ cwd: process.cwd() });
    recovered.execution.leaseReleasedAt = new Date().toISOString();
    recovered.execution.leaseReleaseRecovered = true;
    recovered.execution.updatedAt = recovered.execution.leaseReleasedAt;
    writePrivateJsonAtomic(
      releaseExecutionFile(changeId),
      recovered.execution
    );
    return {
      ...(remoteResult && typeof remoteResult === 'object'
        ? remoteResult
        : {}),
      active: false,
      appType: target.appType,
      recovered: true,
      integration,
    };
  }

  const integration = sourceRevision
    ? assertReleaseSourceIntegrated(sourceRevision, { cwd: process.cwd() })
    : null;
  if (baseline && !integration) {
    fail(
      'RELEASE_SOURCE_LINEAGE_REQUIRED: 本地仍有发布基线，但缺少可验证的 releaseSourceRevision；禁止无证据清理'
    );
  }
  if (baseline) {
    clearChangeBaseline(target, baseline.baselineId || baseline.id);
  }
  releaseWorktreeOwner({ cwd: process.cwd() });
  return {
    active: false,
    appType: target.appType,
    local: false,
    remote,
    recovered: false,
    integration,
  };
}

function decorateEnvironmentReleaseSteps(steps, target, flags = {}) {
  const managedEnvironment = Boolean(
    target.environmentId && target.targetName
  );
  const deploymentId = readStringFlag(flags, 'deployment-id');
  for (const step of steps) {
    step.args = managedEnvironment
      ? withManagedReleaseForwardedFlags(step.id, step.args, flags)
      : withOnlineBaselineAdoptionFlags(step.args, flags);
    if (!managedEnvironment) {
      step.command = commandFromArgs(step.args);
      continue;
    }
    step.args.push('--environment', target.targetName);
    if (deploymentId) step.args.push('--deployment-id', deploymentId);
    if (step.id === 'runtime-stage' && flags.__verifiedCandidate) {
      const artifacts =
        flags.__verifiedCandidate.sourceBundleManifest
          ?.runtimeArtifacts || [];
      const artifact = artifacts.find(
        item =>
          item.targetName === target.targetName &&
          item.environmentId === target.environmentId &&
          item.appType === target.appType
      );
      if (!artifact) {
        fail(
          `CANDIDATE_RUNTIME_ARTIFACT_MISSING: candidate 未封存目标 ${target.targetName}(${target.appType}) 的 Runtime 产物`
        );
      }
      step.args.push(
        '--no-build',
        '--dist',
        artifact.distPath,
        '--build-id',
        artifact.buildId,
        '--upload-mode',
        'staged'
      );
    }
    if (step.id === 'app-finalize') {
      for (const [flag, value] of [
        ['--environment-id', target.environmentId],
        ['--candidate-id', readStringFlag(flags, 'candidate-id')],
      ]) {
        if (value) step.args.push(flag, value);
      }
      const stagedIndex = step.args.indexOf('--staged-resources-json');
      if (stagedIndex >= 0 && deploymentId) {
        step.args[stagedIndex + 1] = path
          .relative(
            process.cwd(),
            stagedResourcesFileForChange(changeIdFromStep(step), deploymentId)
          )
          .replace(/\\/g, '/');
      }
    }
    step.command = commandFromArgs(step.args);
  }
  return steps;
}

function assertReleasePublishAdoptionFlags(flags = {}) {
  const adoptionRequested = Boolean(flags['adopt-online-baseline']);
  const adoptionReasonSupplied = Object.prototype.hasOwnProperty.call(
    flags,
    'adoption-reason'
  );
  const adoptionReason = String(flags['adoption-reason'] || '').trim();
  if (!adoptionRequested && adoptionReasonSupplied) {
    const error = new Error(
      'RELEASE_PUBLISH_ADOPTION_FLAG_REQUIRED: --adoption-reason 必须与 --adopt-online-baseline 一起使用；命令已在任何发布租约或资源写入前终止'
    );
    error.code = 'RELEASE_PUBLISH_ADOPTION_FLAG_REQUIRED';
    throw error;
  }
  if (adoptionRequested && adoptionReason.length < 8) {
    const error = new Error(
      'RELEASE_PUBLISH_ADOPTION_REASON_REQUIRED: --adopt-online-baseline 必须提供至少 8 个字符的 --adoption-reason；命令已在任何发布租约或资源写入前终止'
    );
    error.code = 'RELEASE_PUBLISH_ADOPTION_REASON_REQUIRED';
    throw error;
  }
}

function assertReleasePublishAdoptionScope(steps = [], flags = {}) {
  if (!flags['adopt-online-baseline']) return;
  const adoptionSteps = steps.filter(step =>
    step.args?.includes('--adopt-online-baseline')
  );
  if (adoptionSteps.length === 0) {
    const error = new Error(
      'RELEASE_PUBLISH_ADOPTION_SCOPE_REQUIRED: 当前发布计划没有可精确采纳线上基线的 resource publish --only/--code 阶段；命令已在任何发布租约或资源写入前终止'
    );
    error.code = 'RELEASE_PUBLISH_ADOPTION_SCOPE_REQUIRED';
    throw error;
  }
}

function changeIdFromStep(step) {
  const index = step.args.indexOf('--change');
  return index >= 0 ? step.args[index + 1] : 'change';
}

async function publishWorkspaceRelease(config, target, flags = {}) {
  const changeId = readStringFlag(flags, 'change');
  const deploymentId = readStringFlag(flags, 'deployment-id') || null;
  const clientSessionId = readStringFlag(flags, 'client-session-id');
  const candidateId = readStringFlag(flags, 'candidate-id');
  if (!changeId) {
    fail('用法: openxiangda release publish --change <id> --profile <name>');
  }
  assertReleasePublishAdoptionFlags(flags);
  assertManagedRuntimeRollbackFlags(flags);
  const releaseCandidate = flags.__verifiedCandidate
    ? assertLocalCandidate(flags.__verifiedCandidate)
    : readReleaseCandidate(candidateId);
  const plan = buildWorkspaceReleasePlan({
    changed: true,
    since: flags.since,
    profile: target.profileName,
    skipSdd: true,
    changeId,
    expandDependencies: Boolean(flags['expand-dependencies']),
  });
  if (plan.errors.length > 0) {
    fail(
      `RELEASE_PLAN_INVALID: ${plan.errors
        .map(error => error.message || error.name)
        .join('; ')}`
    );
  }
  const steps = buildWorkspaceReleaseSteps(
    plan.targets,
    plan.workspace.runtimeMode,
    target.profileName,
    changeId
  );
  decorateEnvironmentReleaseSteps(steps, target, flags);
  assertReleasePublishAdoptionScope(steps, flags);
  const releaseScope = getSddChangeScope({
    cwd: process.cwd(),
    configText: readWorkspaceConfigText(),
    changeId,
  });
  const isMainlineBundle =
    releaseScope.change?.changeMode === 'mainline-bundle';
  const integration = isMainlineBundle
    ? inspectIntegrationBundleCommits(
        releaseScope.release?.integration,
        { cwd: process.cwd() }
      )
    : null;
  const planHash = releasePlanHash({
    schemaVersion: 'openxiangda_release_execution_v1',
    appType: target.appType,
    profile: target.profileName,
    changeId,
    runtimeMode: plan.workspace.runtimeMode,
    targets: plan.activationTargets,
    commands: steps.map(step => step.command),
    candidateHash: releaseCandidate?.candidateHash || null,
  });
  if (flags['dry-run']) {
    return {
      dryRun: true,
      appType: target.appType,
      profile: target.profileName,
      changeId,
      planHash,
      targets: plan.targets,
      activationTargets: plan.activationTargets,
      steps,
      integration,
    };
  }
  if (isMainlineBundle) {
    assertIntegrationBundleCommits(releaseScope.release?.integration, {
      cwd: process.cwd(),
    });
  }
  const verifiedByCandidate =
    releaseCandidate &&
    assertCandidatePrepublishVerification(
      releaseCandidate,
      plan
    );
  if (!verifiedByCandidate) {
    const verification = verifySddChange({
      cwd: process.cwd(),
      changeId,
      releasePlan: {
        ...plan,
        commands: steps.map(step => step.command),
      },
      writeMetadata: false,
      stage: 'prepublish',
    });
    if (!verification.passed) {
      fail(
        `SDD_PREPUBLISH_FAILED: ${verification.errors
          .map(error => error.message)
          .join('; ')}`
      );
    }
  }
  if (steps.length === 0) {
    return {
      completed: true,
      noOp: true,
      appType: target.appType,
      profile: target.profileName,
      changeId,
      planHash,
      execution: null,
    };
  }
  const plannedSourceRevision = normalizeManagedReleaseSourceRevision(
    target,
    releaseCandidate?.sourceRevision ||
      prepareReleaseSourceRevision({
        cwd: process.cwd(),
      })
  );
  const existing = readReleaseExecution(changeId, deploymentId);
  if (
    existing &&
    (existing.planHash !== planHash ||
      existing.appType !== target.appType ||
      existing.profile !== target.profileName)
  ) {
    fail(
      'RELEASE_EXECUTION_PLAN_CHANGED: 已存在不同计划的执行日志；请先完成或人工核对旧发布，禁止静默覆盖'
    );
  }
  if (
    existing?.status === 'write-review-required' &&
    !flags['resume-after-review']
  ) {
    fail(
      'RELEASE_WRITE_REVIEW_REQUIRED: 上次写请求结果不确定；请先只读核对 staged release，确认可重试后追加 --resume-after-review'
    );
  }
  if (existing?.releaseSourceRevision) {
    assertStoredReleaseSourceStable(existing);
  }
  const now = new Date().toISOString();
  const execution = existing || {
    schemaVersion: 'openxiangda_release_execution_v1',
    appType: target.appType,
    profile: target.profileName,
    changeId,
    ...(deploymentId ? { deploymentId } : {}),
    ...(releaseCandidate ? { candidateId: releaseCandidate.id } : {}),
    planHash,
    releaseSourceRevision: plannedSourceRevision,
    status: 'planned',
    createdAt: now,
    updatedAt: now,
    stagedWriteOccurred: false,
    writeAttempted: false,
    steps: [
      {
        id: 'lease-and-capture',
        command: `openxiangda release begin --change ${changeId} --profile ${target.profileName}${
          target.targetName ? ` --environment ${target.targetName}` : ''
        }${
          clientSessionId
            ? ` --client-session-id ${clientSessionId}`
            : ''
        } --freeze-app-capture`,
        status: 'pending',
      },
      ...steps.map(step => ({
        id: step.id,
        command: step.command,
        stagedKind: step.stagedKind,
        status: 'pending',
      })),
      {
        id: 'release-lease',
        command: `openxiangda release end --change ${changeId} --profile ${target.profileName}${
          target.targetName ? ` --environment ${target.targetName}` : ''
        }`,
        status: 'pending',
      },
    ],
  };
  if (!execution.releaseSourceRevision) {
    execution.releaseSourceRevision = plannedSourceRevision;
  }
  if (execution.status === 'completed') {
    return {
      completed: true,
      resumed: true,
      appType: target.appType,
      profile: target.profileName,
      changeId,
      planHash,
      executionFile: path
        .relative(process.cwd(), releaseExecutionFile(changeId, deploymentId))
        .replace(/\\/g, '/'),
      execution,
    };
  }
  execution.status = 'running';
  execution.updatedAt = new Date().toISOString();
  writePrivateJsonAtomic(
    releaseExecutionFile(changeId, deploymentId),
    execution
  );

  const runnable = [
    {
      id: 'lease-and-capture',
      args: withReleaseClientSessionArgs(
        [
          'release',
          'begin',
          '--change',
          changeId,
          '--profile',
          target.profileName,
          ...(target.targetName
            ? ['--environment', target.targetName]
            : []),
          ...(deploymentId
            ? ['--deployment-id', deploymentId]
            : []),
          ...(releaseCandidate
            ? [
                '--candidate-id',
                releaseCandidate.id,
                '--sealed-candidate-source',
              ]
            : []),
          '--freeze-app-capture',
        ],
        flags
      ),
    },
    ...steps,
    {
      id: 'release-lease',
      args: [
        'release',
        'end',
        '--change',
        changeId,
        '--profile',
        target.profileName,
        ...(target.targetName
          ? ['--environment', target.targetName]
          : []),
        ...(deploymentId
          ? ['--deployment-id', deploymentId]
          : []),
      ],
    },
  ];
  try {
    for (const step of runnable) {
      const journalStep = execution.steps.find(item => item.id === step.id);
      if (journalStep?.status === 'completed') continue;
      if (step.id === 'lease-and-capture') {
        await waitForPublishLeaseAvailability(config, target, flags);
      }
      journalStep.status = 'running';
      journalStep.startedAt = new Date().toISOString();
      execution.updatedAt = journalStep.startedAt;
      writePrivateJsonAtomic(
        releaseExecutionFile(changeId, deploymentId),
        execution
      );
      warn(`发布步骤开始: ${step.id}`);
      const result = await runOpenXiangdaInProcess(step.args);
      journalStep.status = 'completed';
      journalStep.completedAt = new Date().toISOString();
      journalStep.result = summarizeReleaseStepResult(result);
      if (step.id === 'lease-and-capture') {
        execution.releaseContext = releaseExecutionContextFromBegin(
          result,
          target,
          changeId
        );
      }
      if (
        step.id !== 'lease-and-capture' &&
        step.id !== 'release-lease' &&
        step.writes !== false
      ) {
        execution.writeAttempted = true;
      }
      if (step.stagedKind) execution.stagedWriteOccurred = true;
      execution.updatedAt = journalStep.completedAt;
      writePrivateJsonAtomic(
        releaseExecutionFile(changeId, deploymentId),
        execution
      );
    }
    execution.status = 'completed';
    execution.completedAt = new Date().toISOString();
    execution.updatedAt = execution.completedAt;
    writePrivateJsonAtomic(
      releaseExecutionFile(changeId, deploymentId),
      execution
    );
    return {
      completed: true,
      resumed: Boolean(existing),
      appType: target.appType,
      profile: target.profileName,
      changeId,
      planHash,
      executionFile: path
        .relative(process.cwd(), releaseExecutionFile(changeId, deploymentId))
        .replace(/\\/g, '/'),
      execution,
    };
  } catch (error) {
    const runningStep = execution.steps.find(step => step.status === 'running');
    if (runningStep) {
      runningStep.status = 'failed';
      runningStep.failedAt = new Date().toISOString();
      runningStep.error = {
        code: error.code || 'RELEASE_STEP_FAILED',
        message: maskText(error.message).slice(0, 1000),
      };
      const runningDefinition = runnable.find(
        step => step.id === runningStep.id
      );
      if (
        runningDefinition &&
        runningDefinition.id !== 'lease-and-capture' &&
        runningDefinition.id !== 'release-lease' &&
        runningDefinition.writes !== false &&
        !isDefinitelyPreWriteReleaseError(error)
      ) {
        execution.writeAttempted = true;
      }
    }
    execution.status = classifyReleaseExecutionFailure({
      error,
      stagedWriteOccurred: execution.stagedWriteOccurred,
      writeAttempted: execution.writeAttempted,
    });
    execution.updatedAt = new Date().toISOString();
    writePrivateJsonAtomic(
      releaseExecutionFile(changeId, deploymentId),
      execution
    );
    if (!execution.writeAttempted) {
      try {
        await runOpenXiangdaInProcess(
          [
            'release',
            'end',
            '--change',
            changeId,
            '--profile',
            target.profileName,
            ...(target.targetName
              ? ['--environment', target.targetName]
              : []),
            ...(deploymentId
              ? ['--deployment-id', deploymentId]
              : []),
          ],
          { quiet: true }
        );
      } catch {
        // The original error remains authoritative; lease cleanup is best effort.
      }
    }
    throw error;
  }
}

function environmentSetApiPath(code, suffix = '') {
  const base = '/openxiangda-api/v1/environment-sets';
  return code
    ? `${base}/${encodeURIComponent(code)}${suffix}`
    : base;
}

function defaultEnvironmentSideEffectPolicy(kind) {
  return kind === 'production'
    ? {
        notifications: 'real',
        organizationWrites: 'explicit_capability_only',
        scheduledAutomations: 'enabled',
        externalWrites: 'configured',
        payments: 'configured',
        publicIndexing: 'configured',
        environmentBanner: false,
      }
    : {
        notifications: 'tester_allowlist',
        notificationAllowlist: [],
        organizationWrites: 'deny',
        scheduledAutomations: 'disabled',
        externalWrites: 'allowlist',
        payments: 'deny',
        publicIndexing: 'deny',
        environmentBanner: true,
      };
}

function saveEnvironmentWorkspaceState(state, setDetail, environmentDetail, input) {
  state.logicalApp = {
    id: setDetail.id,
    code: setDetail.code,
    name: setDetail.name,
    sourceRepositoryId: setDetail.sourceRepositoryId,
    updatedAt: new Date().toISOString(),
  };
  const legacyBound = state.profiles?.[input.profile];
  const seedResources =
    input.seedResources ??
    (legacyBound?.appType === environmentDetail.appType
      ? legacyBound.resources
      : undefined);
  const bound = bindEnvironmentTarget(state, {
    targetName: input.targetName,
    profile: input.profile,
    environmentId: environmentDetail.id,
    kind: environmentDetail.kind,
    appType: environmentDetail.appType,
    displayName: environmentDetail.displayName,
    publicOrigin: environmentDetail.publicOrigin,
    sideEffectPolicy: environmentDetail.sideEffectPolicy,
    revision: environmentDetail.revision,
    seedResources,
    replaceResources: input.replaceResources,
    seedAppScopedState: input.seedAppScopedState,
    replaceAppScopedState: input.replaceAppScopedState,
  });
  ensureResourceBuckets(bound);
  saveProjectState(state);
  return bound;
}

async function environment(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda environment init --logical-app <code> --name <name> --kind preproduction --app-type APP_XXX [--target name] [--profile name]',
      '      openxiangda environment attach --logical-app <code> [--preproduction-target name] [--production-target name] [--profile name]',
      '      openxiangda environment bind preproduction|production --app-type APP_XXX [--target name] [--profile name]',
      '      openxiangda environment swap --reason <text> --confirm-production [--preproduction-side-effect-policy-json <JSON|file>] [--production-side-effect-policy-json <JSON|file>] [--profile name]',
      '      openxiangda environment policy update preproduction|production --side-effect-policy-json <JSON|file> --reason <text> [--dry-run] [--full-replace] [--confirm-production] [--profile name]',
      '      openxiangda environment list|status|diff [--logical-app code] [--profile name] [--json]',
      '      openxiangda environment use <target|preproduction|production>',
    ].join('\n'));
    return;
  }
  const config = loadConfig();
  const state = loadProjectState();

  if (subcommand === 'use') {
    const selected = resolveEnvironmentTarget(
      state,
      positional[0] || flags.environment || flags.target
    );
    state.currentTarget = selected.targetName;
    saveProjectState(state);
    const result = {
      currentTarget: selected.targetName,
      kind: selected.binding.kind,
      appType: selected.binding.appType,
    };
    if (flags.json) return writeJson(result);
    print(
      `当前环境 target: ${result.currentTarget} (${result.kind}, ${result.appType})`
    );
    return;
  }

  if (subcommand === 'list') {
    const profileName = flags.profile || config.currentProfile;
    const data = await requestWithAuth(
      config,
      profileName,
      environmentSetApiPath()
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'init') {
    const code = readStringFlag(flags, 'logical-app');
    const name = readStringFlag(flags, 'name');
    const kind = normalizeEnvironmentKind(
      flags.kind || positional[0] || 'preproduction'
    );
    const appType = readStringFlag(flags, 'app-type');
    const profileName = flags.profile || config.currentProfile;
    if (!code || !name || !appType || !profileName) {
      fail(
        'environment init 必须提供 --logical-app、--name、--app-type 和 --profile'
      );
    }
    const profile = getProfile(config, profileName);
    const sourceBase = readGitSourceBase(process.cwd(), 'HEAD');
    const sourceRepositoryId =
      readStringFlag(flags, 'source-repository-id') ||
      sourceBase.repositoryId ||
      sourceBase.repo;
    const sideEffectPolicy = flags['side-effect-policy-json']
      ? readJsonInput(
          flags['side-effect-policy-json'],
          'side-effect-policy-json'
        )
      : defaultEnvironmentSideEffectPolicy(kind);
    const data = await requestWithAuth(
      config,
      profile.profileName,
      environmentSetApiPath(),
      {
        method: 'POST',
        body: {
          code,
          name,
          sourceRepositoryId,
          initialEnvironment: {
            kind,
            appType,
            displayName: flags['display-name'],
            publicOrigin: flags['public-origin'],
            sideEffectPolicy,
          },
        },
      }
    );
    const environmentDetail = (data.environments || []).find(
      item => item.kind === kind
    );
    if (!environmentDetail) {
      fail('平台创建环境组成功，但响应缺少初始 environment');
    }
    const bound = saveEnvironmentWorkspaceState(
      state,
      data,
      environmentDetail,
      {
        targetName: flags.target || flags.environment || kind,
        profile: profile.profileName,
      }
    );
    const result = { logicalApp: state.logicalApp, target: bound };
    if (flags.json) return writeJson(result);
    print(
      `应用环境组已创建: ${state.logicalApp.code}; ${bound.targetName}=${bound.appType}`
    );
    return;
  }

  if (subcommand === 'attach') {
    const code = readStringFlag(flags, 'logical-app');
    const profileName = flags.profile || config.currentProfile;
    if (!code || !profileName) {
      fail('environment attach 必须提供 --logical-app 和 --profile');
    }
    const profile = getProfile(config, profileName);
    const setDetail = await requestWithAuth(
      config,
      profile.profileName,
      environmentSetApiPath(code)
    );
    const environments = setDetail.environments || [];
    if (environments.length === 0) {
      fail(`应用环境组没有可绑定环境: ${code}`);
    }
    const targets = [];
    for (const environmentDetail of environments) {
      const targetName =
        flags[`${environmentDetail.kind}-target`] ||
        environmentDetail.kind;
      targets.push(
        saveEnvironmentWorkspaceState(
          state,
          setDetail,
          environmentDetail,
          {
            targetName,
            profile: profile.profileName,
          }
        )
      );
    }
    const result = { logicalApp: state.logicalApp, targets };
    if (flags.json) return writeJson(result);
    print(
      `应用环境组已接入: ${state.logicalApp.code}; ${targets
        .map(target => `${target.targetName}=${target.appType}`)
        .join(', ')}`
    );
    return;
  }

  const code =
    readStringFlag(flags, 'logical-app') || state.logicalApp?.code;
  if (!code) {
    fail('当前工作区未登记 logical app，请先执行 openxiangda environment init');
  }
  const selectedProfile =
    flags.profile ||
    Object.values(state.targets || {})[0]?.profile ||
    config.currentProfile;

  if (subcommand === 'policy') {
    if (positional[0] !== 'update') {
      fail(
        '用法: openxiangda environment policy update preproduction|production --side-effect-policy-json <JSON|file> --reason <text> [--dry-run]',
      );
    }
    const selector = positional[1] || flags.environment || flags.target;
    if (!selector) {
      fail('environment policy update 必须指定环境 kind、id 或本地 target');
    }
    const reason = readStringFlag(flags, 'reason');
    if (!reason || reason.length < 10) {
      fail('environment policy update 必须提供至少 10 个字符的 --reason');
    }
    const policySource = readStringFlag(flags, 'side-effect-policy-json');
    if (!policySource) {
      fail('environment policy update 必须提供 --side-effect-policy-json');
    }
    const profile = getProfile(config, selectedProfile);
    const setDetail = await requestWithAuth(
      config,
      profile.profileName,
      environmentSetApiPath(code),
    );
    const localTarget = state.targets?.[selector];
    const environmentSelector = localTarget?.environmentId || selector;
    const matches = (setDetail.environments || []).filter(
      item =>
        item.id === environmentSelector || item.kind === environmentSelector,
    );
    if (matches.length !== 1) {
      fail(`应用环境不存在或不唯一: ${selector}`);
    }
    const environmentDetail = matches[0];
    const explicitExpectedRevision = readStringFlag(
      flags,
      'expected-revision',
    );
    const expectedRevision = explicitExpectedRevision
      ? Number(explicitExpectedRevision)
      : Number(environmentDetail.revision);
    if (!Number.isSafeInteger(expectedRevision) || expectedRevision < 1) {
      fail('environment policy update 缺少有效的环境 revision');
    }
    const policyUpdate = readJsonInput(
      policySource,
      'side-effect-policy-json',
    );
    const diff = buildSideEffectPolicyDiff(
      environmentDetail.sideEffectPolicy || {},
      policyUpdate,
      { fullReplace: Boolean(flags['full-replace']) },
    );
    const preview = {
      logicalApp: {
        id: setDetail.id,
        code: setDetail.code,
      },
      environment: {
        id: environmentDetail.id,
        kind: environmentDetail.kind,
        appType: environmentDetail.appType,
        revision: environmentDetail.revision,
      },
      expectedRevision,
      reason,
      dryRun: Boolean(flags['dry-run']),
      ...diff,
    };
    if (flags['dry-run'] || !diff.changed) {
      if (flags.json) return writeJson(preview);
      print(JSON.stringify(preview, null, 2));
      return;
    }
    if (
      environmentDetail.kind === 'production' &&
      !flags['confirm-production']
    ) {
      fail(
        'environment policy update 正式环境写入必须提供 --confirm-production；--dry-run 不需要',
      );
    }
    const data = await requestWithAuth(
      config,
      profile.profileName,
      environmentSetApiPath(
        code,
        `/environments/${encodeURIComponent(environmentDetail.id)}/policy`,
      ),
      {
        method: 'POST',
        body: {
          expectedRevision,
          sideEffectPolicy: policyUpdate,
          reason,
          fullReplace: Boolean(flags['full-replace']),
          confirmProduction: Boolean(flags['confirm-production']),
        },
      },
    );
    const previousTarget = Object.values(state.targets || {}).find(
      target => target.environmentId === environmentDetail.id,
    );
    const updatedTarget = saveEnvironmentWorkspaceState(
      state,
      setDetail,
      data.environment,
      {
        targetName:
          previousTarget?.targetName ||
          localTarget?.targetName ||
          data.environment.kind,
        profile: previousTarget?.profile || profile.profileName,
      },
    );
    const result = {
      ...preview,
      dryRun: false,
      environment: data.environment,
      audit: data.audit,
      target: updatedTarget,
    };
    if (flags.json) return writeJson(result);
    print(JSON.stringify(result, null, 2));
    return;
  }

  if (subcommand === 'swap') {
    if (!flags['confirm-production']) {
      fail(
        'environment swap 会交换真实应用的预发/正式角色，必须提供 --confirm-production'
      );
    }
    const reason = readStringFlag(flags, 'reason');
    if (!reason || reason.trim().length < 10) {
      fail('environment swap 必须提供至少 10 个字符的 --reason');
    }
    const profile = getProfile(config, selectedProfile);
    const previousTargets = Object.values(state.targets || {}).map(target =>
      JSON.parse(JSON.stringify(target))
    );
    const readOptionalPolicy = flagName =>
      flags[flagName]
        ? readJsonInput(flags[flagName], flagName)
        : undefined;
    const data = await requestWithAuth(
      config,
      profile.profileName,
      environmentSetApiPath(code, '/environments/swap-roles'),
      {
        method: 'POST',
        body: {
          confirmation: 'SWAP_PREPRODUCTION_AND_PRODUCTION',
          reason,
          preproduction: {
            displayName: flags['preproduction-display-name'],
            publicOrigin: flags['preproduction-public-origin'],
            sideEffectPolicy: readOptionalPolicy(
              'preproduction-side-effect-policy-json'
            ),
          },
          production: {
            displayName: flags['production-display-name'],
            publicOrigin: flags['production-public-origin'],
            sideEffectPolicy: readOptionalPolicy(
              'production-side-effect-policy-json'
            ),
          },
        },
      }
    );
    const targets = [];
    for (const environmentDetail of data.environments || []) {
      const previousKindTarget = previousTargets.find(
        target => target.kind === environmentDetail.kind
      );
      const previousAppTarget = previousTargets.find(
        target => target.appType === environmentDetail.appType
      );
      targets.push(
        saveEnvironmentWorkspaceState(state, data, environmentDetail, {
          targetName:
            previousKindTarget?.targetName || environmentDetail.kind,
          profile:
            previousKindTarget?.profile ||
            previousAppTarget?.profile ||
            profile.profileName,
          seedResources: previousAppTarget?.resources,
          replaceResources: true,
          seedAppScopedState: previousAppTarget,
          replaceAppScopedState: true,
        })
      );
    }
    const result = {
      logicalApp: state.logicalApp,
      targets,
      roleSwap: data.roleSwap,
    };
    if (flags.json) return writeJson(result);
    print(
      `应用环境角色已交换: ${targets
        .map(target => `${target.kind}=${target.appType}`)
        .join(', ')}`
    );
    return;
  }

  if (subcommand === 'bind') {
    const kind = normalizeEnvironmentKind(positional[0] || flags.kind);
    const appType = readStringFlag(flags, 'app-type');
    if (!appType) fail('environment bind 必须提供 --app-type');
    const profile = getProfile(config, selectedProfile);
    const sideEffectPolicy = flags['side-effect-policy-json']
      ? readJsonInput(
          flags['side-effect-policy-json'],
          'side-effect-policy-json'
        )
      : defaultEnvironmentSideEffectPolicy(kind);
    const environmentDetail = await requestWithAuth(
      config,
      profile.profileName,
      environmentSetApiPath(code, '/environments'),
      {
        method: 'POST',
        body: {
          kind,
          appType,
          displayName: flags['display-name'],
          publicOrigin: flags['public-origin'],
          sideEffectPolicy,
        },
      }
    );
    const setDetail = await requestWithAuth(
      config,
      profile.profileName,
      environmentSetApiPath(code)
    );
    const bound = saveEnvironmentWorkspaceState(
      state,
      setDetail,
      environmentDetail,
      {
        targetName: flags.target || flags.environment || kind,
        profile: profile.profileName,
      }
    );
    if (flags.json) return writeJson(bound);
    print(`应用环境已绑定: ${bound.targetName}=${bound.appType}`);
    return;
  }

  if (subcommand === 'status' || subcommand === 'diff') {
    const data = await requestWithAuth(
      config,
      selectedProfile,
      environmentSetApiPath(code, '/status')
    );
    const result =
      subcommand === 'diff'
        ? buildEnvironmentStatusDiff(data)
        : data;
    if (flags.json) return writeJson(result);
    print(JSON.stringify(result, null, 2));
    return;
  }

  fail('用法: openxiangda environment init|attach|bind|swap|policy update|list|status|diff|use');
}

function buildEnvironmentStatusDiff(status) {
  const environments = status?.environments || [];
  const preproduction = environments.find(
    item => item.kind === 'preproduction'
  );
  const production = environments.find(item => item.kind === 'production');
  return {
    logicalApp: {
      id: status?.id || null,
      code: status?.code || null,
      name: status?.name || null,
    },
    preproduction: preproduction || null,
    production: production || null,
    drift: {
      sameAppRelease:
        Boolean(preproduction?.heads?.appReleaseId) &&
        preproduction?.heads?.appReleaseId ===
          production?.heads?.appReleaseId,
      candidate:
        preproduction?.latestDeployment?.candidateId || null,
      promotedCandidate:
        production?.latestDeployment?.candidateId || null,
      promotionReady:
        preproduction?.latestDeployment?.status === 'succeeded' &&
        preproduction?.latestDeployment?.candidateId !== null &&
        preproduction?.latestDeployment?.candidateId !== undefined,
    },
  };
}

function readStudioGit(args, cwd = process.cwd()) {
  const result = spawnSync('git', args, {
    cwd,
    encoding: 'utf8',
    timeout: 5000,
  });
  return result.status === 0 ? String(result.stdout || '').trim() : '';
}

function studioGitSnapshot() {
  const porcelain = readStudioGit([
    'status',
    '--porcelain',
    '--untracked-files=all',
  ]);
  const branch = readStudioGit(['branch', '--show-current']);
  const commit = readStudioGit(['rev-parse', 'HEAD']);
  const upstream = readStudioGit([
    'rev-parse',
    '--abbrev-ref',
    '--symbolic-full-name',
    '@{upstream}',
  ]);
  const upstreamCommit = upstream
    ? readStudioGit(['rev-parse', upstream])
    : '';
  const upstreamParts = upstream.split('/');
  const remoteName = upstreamParts.length > 1 ? upstreamParts[0] : '';
  const upstreamBranch = upstreamParts.slice(1).join('/');
  const remoteHeadCommit =
    remoteName && upstreamBranch
      ? readStudioGit([
          'ls-remote',
          '--heads',
          remoteName,
          `refs/heads/${upstreamBranch}`,
        ]).split(/\s+/)[0] || ''
      : '';
  const aheadBehind = upstream
    ? readStudioGit([
        'rev-list',
        '--left-right',
        '--count',
        `${upstream}...HEAD`,
      ])
        .split(/\s+/)
        .map(value => Number(value))
    : [];
  const worktreePaths = readStudioGit(['worktree', 'list', '--porcelain'])
    .split(/\r?\n/)
    .filter(line => line.startsWith('worktree '))
    .map(line => line.slice('worktree '.length))
    .filter(Boolean);
  const dirtyWorktrees = worktreePaths
    .filter(worktreePath => path.resolve(worktreePath) !== process.cwd())
    .filter(worktreePath =>
      Boolean(
        readStudioGit(
          ['status', '--porcelain', '--untracked-files=all'],
          worktreePath
        )
      )
    );
  const ahead = Number.isFinite(aheadBehind[1]) ? aheadBehind[1] : null;
  const behind = Number.isFinite(aheadBehind[0]) ? aheadBehind[0] : null;
  const authoritativeBranch = ['main', 'master'].includes(branch);
  const upstreamMainline = /\/(?:main|master)$/.test(upstream);
  const clean = !porcelain;
  const mainlineAligned =
    clean &&
    authoritativeBranch &&
    upstreamMainline &&
    commit === upstreamCommit &&
    commit === remoteHeadCommit &&
    ahead === 0 &&
    behind === 0 &&
    dirtyWorktrees.length === 0;
  return {
    branch,
    commit,
    upstream: upstream || null,
    upstreamCommit: upstreamCommit || null,
    remoteHeadCommit: remoteHeadCommit || null,
    ahead,
    behind,
    clean,
    mainlineAligned,
    dirtyWorktrees,
    worktreeCount: worktreePaths.length,
    changes: porcelain ? porcelain.split(/\r?\n/).slice(0, 50) : [],
  };
}

function isProductionCommissioning(environment) {
  const policy = environment?.sideEffectPolicy || {};
  return (
    policy.payments === 'deny' &&
    policy.notifications === 'tester_allowlist' &&
    policy.externalWrites === 'deny' &&
    policy.publicIndexing === 'deny' &&
    policy.organizationWrites === 'deny' &&
    policy.scheduledAutomations === 'disabled' &&
    policy.environmentBanner === true
  );
}

function isDeploymentEvidenceValid(deployment, now = Date.now()) {
  if (!deployment?.evidenceHash) return false;
  const evidence = deployment.evidenceSummary;
  if (!evidence || evidence.outcome !== 'passed') return false;
  const validUntil = Date.parse(evidence.validUntil || '');
  return Number.isFinite(validUntil) && validUntil > now;
}

async function studio(args) {
  const { flags } = parseArgs(args);
  const config = loadConfig();
  const initialState = loadProjectState();
  if (!initialState.logicalApp?.code) {
    fail(
      'Developer Center 需要环境管理工作区；请先执行 openxiangda environment init'
    );
  }
  const getStatus = async () => {
    const state = loadProjectState();
    const selected = resolveEnvironmentTarget(
      state,
      state.currentTarget || 'preproduction'
    );
    const remoteStatus = await requestWithAuth(
      config,
      selected.binding.profile,
      environmentSetApiPath(state.logicalApp.code, '/status')
    );
    const environments = await Promise.all(
      (remoteStatus?.environments || []).map(async environment => {
        const deploymentId = environment?.latestDeployment?.id;
        if (!deploymentId) return environment;
        try {
          const latestDeployment = await requestWithAuth(
            config,
            selected.binding.profile,
            applicationDeploymentApiPath(
              state.logicalApp.code,
              deploymentId
            )
          );
          return { ...environment, latestDeployment };
        } catch {
          return environment;
        }
      })
    );
    const remote = { ...remoteStatus, environments };
    const git = studioGitSnapshot();
    const preproduction = environments.find(
      environment => environment.kind === 'preproduction'
    );
    const production = environments.find(
      environment => environment.kind === 'production'
    );
    const drift = buildEnvironmentStatusDiff(remote).drift;
    const evidenceValid = isDeploymentEvidenceValid(
      preproduction?.latestDeployment
    );
    const productionCommissioning =
      isProductionCommissioning(production);
    const candidateReady = git.mainlineAligned;
    const testRegistrationReady = Boolean(
      preproduction?.latestDeployment?.id &&
        preproduction.latestDeployment.status !== 'failed'
    );
    const promotionReady =
      candidateReady &&
      productionCommissioning &&
      evidenceValid &&
      preproduction?.latestDeployment?.status === 'succeeded' &&
      Boolean(preproduction.latestDeployment.candidateId);
    return {
      workspace: process.cwd(),
      logicalApp: state.logicalApp,
      currentTarget: state.currentTarget,
      targets: state.targets,
      git,
      drift,
      deliveryGates: {
        candidateReady,
        evidenceValid,
        productionCommissioning,
        promotionReady,
        rollbackReady: Boolean(production?.heads?.appReleaseId),
        testRegistrationReady,
      },
      openxiangdaVersion: CURRENT_VERSION,
      remote,
    };
  };
  const runAction = async body => {
    const state = loadProjectState();
    const action = String(body?.action || '').trim();
    const value = String(body?.value || '').trim();
    const details = String(body?.details || '').trim();
    const pre = resolveEnvironmentTarget(state, 'preproduction');
    const production =
      action === 'promote' || action === 'rollback'
        ? resolveEnvironmentTarget(state, 'production')
        : null;
    if (action === 'candidate') {
      if (!value) throw new Error('请输入 OpenSpec changeId');
      return await runOpenXiangdaInProcess([
        'release',
        'candidate',
        '--change',
        value,
        '--environment',
        pre.targetName,
      ]);
    }
    if (action === 'deploy') {
      if (!value) throw new Error('请输入 candidateId');
      return await runOpenXiangdaInProcess([
        'release',
        'deploy',
        '--candidate',
        value,
        '--environment',
        pre.targetName,
      ]);
    }
    if (action === 'test') {
      if (!details) throw new Error('请输入测试证据 JSON');
      return await runOpenXiangdaInProcess([
        'release',
        'test',
        ...(value ? ['--deployment', value] : []),
        '--evidence-json',
        details,
        '--environment',
        pre.targetName,
      ]);
    }
    if (action === 'promote') {
      if (!body?.confirmProduction) {
        throw new Error('production action requires explicit confirmation');
      }
      if (!value) throw new Error('请输入 candidateId');
      return await runOpenXiangdaInProcess([
        'release',
        'promote',
        '--candidate',
        value,
        '--environment',
        production.targetName,
        '--confirm-production',
      ]);
    }
    if (action === 'rollback') {
      if (!body?.confirmProduction) {
        throw new Error('production action requires explicit confirmation');
      }
      if (!value || details.length < 8) {
        throw new Error('请输入目标 AppReleaseId 和至少 8 个字符的回退原因');
      }
      return await runOpenXiangdaInProcess([
        'release',
        'rollback',
        '--to',
        value,
        '--reason',
        details,
        '--environment',
        production.targetName,
        '--confirm-production',
      ]);
    }
    throw new Error(`未注册的 Developer Center 操作: ${action}`);
  };
  const port = flags.port === undefined ? 0 : Number(flags.port);
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    fail('studio --port 必须是 0-65535 的整数');
  }
  const center = await startDeveloperCenter({ port, getStatus, runAction });
  if (!flags['no-open']) openBrowser(center.url);
  const publicUrl = center.url.replace(/\?.*$/, '');
  print(
    flags['no-open']
      ? `OpenXiangda Developer Center: ${center.url}`
      : `OpenXiangda Developer Center 已启动: ${publicUrl}`
  );
}

function requireLogicalApplication(target) {
  const logicalApp = target.logicalApp || target.state?.logicalApp;
  if (!logicalApp?.code || !logicalApp?.id) {
    fail(
      '当前工作区尚未登记 logical app；请先执行 openxiangda environment init'
    );
  }
  return logicalApp;
}

function applicationDeploymentApiPath(logicalAppCode, deploymentId, action) {
  const suffix = deploymentId
    ? `/deployments/${encodeURIComponent(deploymentId)}${
        action ? `/${action}` : ''
      }`
    : '/deployments';
  return environmentSetApiPath(logicalAppCode, suffix);
}

function assertLocalCandidate(candidate) {
  if (
    !candidate?.id ||
    !candidate?.candidateHash ||
    !candidate?.sourceBundleManifest ||
    sha256Canonical(candidate.sourceBundleManifest) !== candidate.candidateHash ||
    sha256Canonical(candidate.sourceBundleManifest.sourceRevision) !==
      sha256Canonical(candidate.sourceRevision)
  ) {
    fail('LOCAL_CANDIDATE_INVALID: 本地 candidate 文件缺失或哈希不一致');
  }
  assertReleaseSourceRevisionStable(candidate.sourceRevision, {
    cwd: process.cwd(),
    allowDescendant: true,
  });
  assertCandidateBundleFilesCurrent(candidate, process.cwd());
  assertCandidateEnvironmentBindingsCurrent(
    candidate,
    loadProjectState()
  );
  return candidate;
}

function readReleaseCandidate(candidateId) {
  const normalized = String(candidateId || '').trim();
  if (!normalized) return null;
  const candidate = readCandidate(normalized);
  if (!candidate) {
    fail(`LOCAL_CANDIDATE_NOT_FOUND: 本地未找到 candidate ${normalized}`);
  }
  return assertLocalCandidate(candidate);
}

function assertStoredReleaseSourceStable(record) {
  const candidateId = String(record?.candidateId || '').trim();
  if (candidateId) {
    const candidate = readReleaseCandidate(candidateId);
    if (
      sha256Canonical(candidate.sourceRevision) !==
      sha256Canonical(record.releaseSourceRevision)
    ) {
      fail(
        'CANDIDATE_RELEASE_SOURCE_MISMATCH: 私有发布状态与 sealed candidate 的源码版本不一致'
      );
    }
    return candidate;
  }
  assertReleaseSourceRevisionStable(record?.releaseSourceRevision, {
    cwd: process.cwd(),
  });
  return null;
}

function candidateReleasePlanFingerprint(plan) {
  return sha256Canonical({
    schemaVersion: 'openxiangda_candidate_release_plan_v1',
    runtimeMode: plan.workspace.runtimeMode,
    targets: plan.activationTargets,
    files: unique(plan.changedFiles || []).sort(),
    commands: plan.commands || [],
    scopes: plan.scopeModel || null,
    dependencyImpact: plan.dependencyImpact || {},
  });
}

function buildCandidatePreflight(changeId, plan) {
  const planErrors = (plan.errors || []).map(error => ({
    name: error.name || 'release-plan-invalid',
    message: error.message || String(error),
  }));
  const verification =
    planErrors.length === 0
      ? verifySddChange({
          cwd: process.cwd(),
          changeId,
          releasePlan: plan,
          writeMetadata: false,
          stage: 'prepublish',
        })
      : null;
  const errors = [
    ...planErrors,
    ...(verification?.errors || []),
  ];
  const payload = {
    schemaVersion: 'openxiangda_candidate_preflight_v1',
    changeId,
    passed: errors.length === 0,
    releasePlanFingerprint: candidateReleasePlanFingerprint(plan),
    scopes: plan.scopeModel || null,
    dependencyImpact: plan.dependencyImpact || {},
    checks: {
      releasePlan: planErrors.length === 0 ? 'passed' : 'failed',
      sddPrepublish:
        verification === null
          ? 'not_run'
          : verification.passed
            ? 'passed'
            : 'failed',
    },
    errors,
  };
  return {
    ...payload,
    preflightHash: sha256Canonical(payload),
  };
}

function assertCandidatePreflight(candidate, plan) {
  const preflight = candidate?.candidatePreflight;
  if (!preflight) return false;
  const { preflightHash, ...payload } = preflight;
  if (
    preflight.schemaVersion !==
      'openxiangda_candidate_preflight_v1' ||
    preflight.passed !== true ||
    !preflightHash ||
    sha256Canonical(payload) !== preflightHash ||
    candidate.sourceBundleManifest?.candidatePreflightHash !==
      preflightHash ||
    preflight.changeId !== candidate.changeId ||
    preflight.releasePlanFingerprint !==
      candidateReleasePlanFingerprint(plan)
  ) {
    fail(
      'CANDIDATE_PREFLIGHT_ATTESTATION_INVALID: candidate 的只读预检凭证与当前主线计划不一致'
    );
  }
  return true;
}

function buildCandidatePrepublishVerification(
  changeId,
  sourceRevision,
  plan
) {
  const payload = {
    schemaVersion: 'openxiangda_candidate_prepublish_v1',
    stage: 'prepublish',
    passed: true,
    changeId,
    sourceRevisionHash: sha256Canonical(sourceRevision),
    releasePlanFingerprint: candidateReleasePlanFingerprint(plan),
  };
  return {
    ...payload,
    verificationHash: sha256Canonical(payload),
  };
}

function assertCandidatePrepublishVerification(candidate, plan) {
  assertCandidatePreflight(candidate, plan);
  const attestation = candidate?.prepublishVerification;
  if (
    !attestation ||
    attestation.schemaVersion !==
      'openxiangda_candidate_prepublish_v1' ||
    attestation.stage !== 'prepublish' ||
    attestation.passed !== true
  ) {
    return false;
  }
  const { verificationHash, ...payload } = attestation;
  if (
    !verificationHash ||
    sha256Canonical(payload) !== verificationHash ||
    candidate.sourceBundleManifest?.prepublishVerificationHash !==
      verificationHash ||
    payload.changeId !== candidate.changeId ||
    payload.sourceRevisionHash !==
      sha256Canonical(candidate.sourceRevision) ||
    payload.releasePlanFingerprint !==
      candidateReleasePlanFingerprint(plan)
  ) {
    fail(
      'CANDIDATE_PREPUBLISH_ATTESTATION_INVALID: candidate 的预发布校验凭证与当前主线计划不一致'
    );
  }
  return true;
}

async function createApplicationCandidate(config, target, flags, positional) {
  const logicalApp = requireLogicalApplication(target);
  const changeId =
    readStringFlag(flags, 'change') || positional[0];
  if (!changeId) {
    fail('用法: openxiangda release candidate --change <id>');
  }
  const plan = buildWorkspaceReleasePlan({
    changed: true,
    since: flags.since,
    profile: target.profileName,
    skipSdd: true,
    changeId,
    expandDependencies: Boolean(flags['expand-dependencies']),
  });
  const candidatePreflight = buildCandidatePreflight(changeId, plan);
  if (!candidatePreflight.passed) {
    const error = new Error(
      `CANDIDATE_PREFLIGHT_FAILED: ${candidatePreflight.errors
        .map(item => item.message || item.name)
        .join('; ')}`
    );
    error.code = 'CANDIDATE_PREFLIGHT_FAILED';
    error.preflight = candidatePreflight;
    throw error;
  }
  const sourceRevision = normalizeManagedReleaseSourceRevision(
    target,
    prepareReleaseSourceRevision({ cwd: process.cwd() }),
    { errorCode: 'CANDIDATE_REPOSITORY_MISMATCH' }
  );
  const prepublishVerification =
    buildCandidatePrepublishVerification(
      changeId,
      sourceRevision,
      plan
    );
  const testPlan = flags['test-plan-json']
    ? readJsonInput(flags['test-plan-json'], 'test-plan-json')
    : undefined;
  const runtimeArtifacts = await buildCandidateRuntimeArtifacts(
    target,
    plan,
    sourceRevision,
    changeId
  );
  const candidateFiles = [
    ...getCandidateSourceFiles(plan),
    ...runtimeArtifacts.flatMap(artifact =>
      artifact.files.map(file => file.path)
    ),
  ];
  const bundle = buildCandidateBundle({
    cwd: process.cwd(),
    logicalAppCode: logicalApp.code,
    changeId,
    sourceRevision,
    runtimeMode: plan.workspace.runtimeMode,
    targets: plan.activationTargets,
    files: candidateFiles,
    environmentBindings: buildCandidateEnvironmentBindings(
      target.state
    ),
    runtimeArtifacts,
    testPlan,
    prepublishVerificationHash:
      prepublishVerification.verificationHash,
    candidatePreflightHash:
      candidatePreflight.preflightHash,
    openxiangdaVersion: CURRENT_VERSION,
  });
  const runtimeArtifactHash =
    runtimeArtifacts.length > 0
      ? sha256Canonical(runtimeArtifacts)
      : null;
  const runtimeArtifactLocator =
    runtimeArtifacts.length > 0
      ? JSON.stringify({
          schemaVersion: 1,
          artifacts: runtimeArtifacts.map(artifact => ({
            targetName: artifact.targetName,
            environmentId: artifact.environmentId,
            appType: artifact.appType,
            buildId: artifact.buildId,
            distPath: artifact.distPath,
            artifactHash: artifact.artifactHash,
          })),
        })
      : null;
  let data;
  try {
    data = await requestWithAuth(
      config,
      target.profileName,
      environmentSetApiPath(logicalApp.code, '/candidates'),
      {
        method: 'POST',
        body: {
          candidateHash: bundle.candidateHash,
          changeId,
          sourceRepositoryId: logicalApp.sourceRepositoryId,
          sourceRevision,
          sourceBundleManifest: bundle.sourceBundleManifest,
          runtimeArtifactHash,
          runtimeArtifactLocator,
          testPlanHash: bundle.testPlanHash,
          openxiangdaVersion: CURRENT_VERSION,
        },
      }
    );
  } catch (error) {
    removeCandidateRuntimeArtifacts(runtimeArtifacts);
    throw error;
  }
  const localCandidate = {
    ...data,
    logicalAppCode: logicalApp.code,
    sourceRevision,
    sourceBundleManifest: bundle.sourceBundleManifest,
    testPlan: bundle.testPlan,
    releasePlan: plan,
    candidatePreflight,
    prepublishVerification,
    savedAt: new Date().toISOString(),
  };
  const file = saveCandidate(localCandidate);
  return {
    candidate: localCandidate,
    candidateFile: path.relative(process.cwd(), file).replace(/\\/g, '/'),
  };
}

async function buildCandidateRuntimeArtifacts(
  target,
  plan,
  sourceRevision,
  changeId
) {
  if (!plan.targets?.runtime) return [];
  const buildCommand = assertRuntimeBuildReady();
  const bindings = Object.entries(target.state?.targets || {})
    .filter(
      ([, binding]) =>
        ['preproduction', 'production'].includes(binding?.kind) &&
        binding?.environmentId &&
        binding?.appType
    )
    .sort(([left], [right]) => left.localeCompare(right));
  if (bindings.length !== 2) {
    fail(
      'CANDIDATE_RUNTIME_TARGETS_INCOMPLETE: Runtime candidate 必须同时封存唯一的预发与生产目标产物'
    );
  }
  const kinds = bindings.map(([, binding]) => binding.kind).sort();
  if (
    kinds[0] !== 'preproduction' ||
    kinds[1] !== 'production'
  ) {
    fail(
      'CANDIDATE_RUNTIME_TARGETS_INVALID: Runtime candidate 必须恰好包含 preproduction 与 production'
    );
  }
  const artifactSourceId = sha256Canonical({
    schemaVersion: 1,
    changeId,
    sourceRevision,
    targets: bindings.map(([targetName, binding]) => ({
      targetName,
      environmentId: binding.environmentId,
      kind: binding.kind,
      appType: binding.appType,
    })),
  }).slice(0, 24);
  const artifactSetId = `${artifactSourceId}-${crypto
    .randomBytes(4)
    .toString('hex')}`;
  const artifactRoot = path.resolve(
    process.cwd(),
    '.openxiangda',
    'candidates',
    'artifacts',
    artifactSetId
  );
  const artifacts = [];
  try {
    for (const [targetName, binding] of bindings) {
      const buildId = normalizeRuntimeBuildId(
        `candidate-${artifactSetId}-${binding.kind}`
      );
      const assetBaseUrl = buildRuntimeAssetBaseUrl(
        binding.appType,
        buildId
      );
      await runRuntimeBuild({
        buildId,
        appType: binding.appType,
        assetBaseUrl,
        command: buildCommand,
        jsonOutput: false,
      });
      assertReleaseSourceRevisionStable(sourceRevision, {
        cwd: process.cwd(),
        allowDescendant: false,
      });
      const builtFiles = collectRuntimeDistFiles(
        path.resolve(process.cwd(), 'dist')
      );
      const distPath = normalizeWorkspaceRelativePath(
        path.join(
          '.openxiangda',
          'candidates',
          'artifacts',
          artifactSetId,
          targetName
        )
      );
      const artifactDirectory = path.resolve(
        process.cwd(),
        distPath
      );
      for (const file of builtFiles) {
        const output = path.join(artifactDirectory, file.path);
        fs.mkdirSync(path.dirname(output), {
          recursive: true,
          mode: 0o700,
        });
        fs.writeFileSync(output, file.buffer, { mode: 0o600 });
      }
      const files = builtFiles
        .map(file => ({
          path: normalizeWorkspaceRelativePath(
            path.join(distPath, file.path)
          ),
          size: file.size,
          sha256: file.sha256,
        }))
        .sort((left, right) =>
          left.path.localeCompare(right.path)
        );
      artifacts.push({
        schemaVersion: 1,
        targetName,
        environmentId: binding.environmentId,
        environmentKind: binding.kind,
        appType: binding.appType,
        buildId,
        assetBaseUrl,
        distPath,
        artifactHash: sha256Canonical(files),
        files,
      });
    }
  } catch (error) {
    fs.rmSync(artifactRoot, { recursive: true, force: true });
    throw error;
  }
  return artifacts;
}

function removeCandidateRuntimeArtifacts(artifacts) {
  const workspace = path.resolve(process.cwd());
  const allowedRoot = path.join(
    workspace,
    '.openxiangda',
    'candidates',
    'artifacts'
  );
  for (const artifact of artifacts || []) {
    const target = path.resolve(workspace, artifact.distPath || '');
    const relative = path.relative(allowedRoot, target);
    if (
      !relative ||
      relative.startsWith('..') ||
      path.isAbsolute(relative)
    ) {
      continue;
    }
    fs.rmSync(target, { recursive: true, force: true });
    const parent = path.dirname(target);
    try {
      if (fs.readdirSync(parent).length === 0) {
        fs.rmdirSync(parent);
      }
    } catch {
      // A concurrent retry or another target artifact still owns the parent.
    }
  }
}

async function markApplicationDeploymentFailed(
  config,
  target,
  logicalAppCode,
  deploymentId,
  error
) {
  try {
    return await requestWithAuth(
      config,
      target.profileName,
      applicationDeploymentApiPath(
        logicalAppCode,
        deploymentId,
        'fail'
      ),
      {
        method: 'POST',
        body: {
          code: error?.code || 'OPENXIANGDA_DEPLOYMENT_FAILED',
          message: maskText(error?.message || String(error)).slice(0, 2000),
          details: {
            command: 'openxiangda release',
            recordedAt: new Date().toISOString(),
          },
        },
      }
    );
  } catch (recordError) {
    warn(
      `部署失败记录未写入平台: ${maskText(recordError?.message || recordError)}`
    );
    return null;
  }
}

function deploymentQueueDetails(error) {
  if (error?.code !== 'APP_DEPLOYMENT_QUEUE_BUSY') return null;
  const value =
    error?.data && typeof error.data === 'object'
      ? error.data
      : error?.payload?.data && typeof error.payload.data === 'object'
        ? error.payload.data
        : {};
  return value;
}

function deploymentQueueWaitDecision(statusInput) {
  const status = String(statusInput || '').trim().toLowerCase();
  return {
    status,
    wait: status === 'running',
    evidencePending: status === 'deployed',
  };
}

function deploymentEvidencePendingError(deployment = {}) {
  const deploymentId = String(deployment.deploymentId || deployment.id || '').trim();
  const error = new Error(
    `APP_DEPLOYMENT_EVIDENCE_PENDING: 目标环境部署 ${deploymentId || '-'} 已完成激活，当前为 deployed，待提交测试证据；请先执行 openxiangda release test --deployment ${deploymentId || '<id>'} --evidence-json <JSON|file>`
  );
  error.code = 'APP_DEPLOYMENT_EVIDENCE_PENDING';
  error.data = {
    deploymentId: deploymentId || null,
    status: 'deployed',
    nextAction: 'release test',
  };
  return error;
}

async function createApplicationDeploymentWhenAvailable(
  config,
  target,
  logicalAppCode,
  body,
  flags = {}
) {
  const waitSeconds = normalizeReleaseWaitSeconds(flags);
  const deadline = Date.now() + waitSeconds * 1000;
  await waitForPublishLeaseAvailability(config, target, flags);
  while (true) {
    try {
      return await requestWithAuth(
        config,
        target.profileName,
        applicationDeploymentApiPath(logicalAppCode),
        { method: 'POST', body }
      );
    } catch (error) {
      const queue = deploymentQueueDetails(error);
      if (!queue) throw error;
      const deploymentId = String(queue.deploymentId || '').trim();
      if (!deploymentId) throw error;
      const queuedState = deploymentQueueWaitDecision(queue.status);
      if (queuedState.evidencePending) {
        throw deploymentEvidencePendingError({
          ...queue,
          deploymentId,
        });
      }
      if (Date.now() >= deadline || waitSeconds === 0) throw error;
      const delaySeconds = Math.min(
        Math.max(Number(queue.retryAfterSeconds || 5), 1),
        30
      );
      warn(
        `目标环境发布队列等待中: deployment=${deploymentId} status=${queue.status || 'running'} retry=${delaySeconds}s`
      );
      while (Date.now() < deadline) {
        await sleep(
          Math.min(delaySeconds * 1000, Math.max(1, deadline - Date.now()))
        );
        let active;
        try {
          active = await requestWithAuth(
            config,
            target.profileName,
            applicationDeploymentApiPath(logicalAppCode, deploymentId)
          );
        } catch {
          break;
        }
        const activeState = deploymentQueueWaitDecision(active?.status);
        if (activeState.evidencePending) {
          throw deploymentEvidencePendingError({
            ...active,
            deploymentId,
          });
        }
        if (!activeState.wait) break;
      }
      if (Date.now() >= deadline) {
        fail(
          `APP_DEPLOYMENT_QUEUE_TIMEOUT: 目标环境部署 ${deploymentId} 在 ${waitSeconds}s 内未完成`
        );
      }
      await waitForPublishLeaseAvailability(config, target, {
        ...flags,
        'wait-seconds': Math.max(
          0,
          Math.floor((deadline - Date.now()) / 1000)
        ),
      });
    }
  }
}

async function deployApplicationCandidate(
  config,
  target,
  candidate,
  options = {}
) {
  const logicalApp = requireLogicalApplication(target);
  assertLocalCandidate(candidate);
  await assertRemoteCandidateMatches(
    config,
    target,
    logicalApp.code,
    candidate
  );
  const kind = options.kind || 'deploy';
  const body = {
    kind,
    targetEnvironmentId: target.environmentId,
    ...(options.sourceEnvironmentId
      ? { sourceEnvironmentId: options.sourceEnvironmentId }
      : {}),
    ...(kind === 'rollback'
      ? { rollbackTargetReleaseId: options.rollbackTargetReleaseId }
      : { candidateId: candidate.id }),
  };
  const deployment = await createApplicationDeploymentWhenAvailable(
    config,
    target,
    logicalApp.code,
    body,
    options.flags || {}
  );
  rememberTargetDeployment(target, deployment);
  try {
    const published = await publishWorkspaceRelease(config, target, {
      ...options.flags,
      change: candidate.changeId,
      environment: target.targetName,
      'candidate-id': candidate.id,
      'deployment-id': deployment.id,
      __verifiedCandidate: candidate,
    });
    const detail = await requestWithAuth(
      config,
      target.profileName,
      applicationDeploymentApiPath(logicalApp.code, deployment.id)
    );
    rememberTargetDeployment(target, detail);
    return { deployment: detail, published };
  } catch (error) {
    let activatedDeployment = null;
    try {
      activatedDeployment = await requestWithAuth(
        config,
        target.profileName,
        applicationDeploymentApiPath(logicalApp.code, deployment.id)
      );
    } catch {
      // Preserve the primary deployment error when the read-only check fails.
    }
    if (
      isRecoverablePostActivationDeploymentError(error, activatedDeployment)
    ) {
      rememberTargetDeployment(target, activatedDeployment);
      warn(
        `AppRelease 已激活，发布租约清理发生并发冲突；部署 ${deployment.id} 保持 deployed，请执行 release status/end 完成只读回合清理。`
      );
      return {
        deployment: activatedDeployment,
        published: null,
        recoveredAfterActivation: true,
        postActivationError: {
          code: error?.code || 'PUBLISH_LEASE_CLEANUP_CONFLICT',
          message: maskText(error?.message || String(error)),
        },
      };
    }
    const failedDeployment = await markApplicationDeploymentFailed(
      config,
      target,
      logicalApp.code,
      deployment.id,
      error
    );
    rememberTargetDeployment(
      target,
      failedDeployment?.id
        ? failedDeployment
        : {
            ...deployment,
            status: 'failed',
          }
    );
    error.deploymentId = deployment.id;
    error.deploymentStatus = failedDeployment?.status || 'failed';
    throw error;
  }
}

async function assertRemoteCandidateMatches(
  config,
  target,
  logicalAppCode,
  candidate
) {
  const remote = await requestWithAuth(
    config,
    target.profileName,
    environmentSetApiPath(
      logicalAppCode,
      `/candidates/${encodeURIComponent(candidate.id)}`
    )
  );
  const localRuntimeArtifactHash =
    candidate.sourceBundleManifest?.runtimeArtifacts?.length > 0
      ? sha256Canonical(
          candidate.sourceBundleManifest.runtimeArtifacts
        )
      : null;
  const optionalHash = value =>
    value === undefined || value === null
      ? null
      : sha256Canonical(value);
  const mismatches = [];
  for (const [field, expected, current] of [
    ['candidateHash', candidate.candidateHash, remote.candidateHash],
    ['changeId', candidate.changeId, remote.changeId],
    [
      'sourceRevision',
      optionalHash(candidate.sourceRevision),
      optionalHash(remote.sourceRevision),
    ],
    [
      'sourceBundleManifest',
      optionalHash(candidate.sourceBundleManifest),
      optionalHash(remote.sourceBundleManifest),
    ],
    [
      'runtimeArtifactHash',
      localRuntimeArtifactHash,
      remote.runtimeArtifactHash || null,
    ],
    ['testPlanHash', candidate.testPlanHash, remote.testPlanHash],
  ]) {
    if (expected !== current) {
      mismatches.push({ field, expected, current });
    }
  }
  if (mismatches.length > 0) {
    const error = new Error(
      `REMOTE_CANDIDATE_MISMATCH: 本地 candidate 与平台冻结记录不一致: ${mismatches
        .map(item => item.field)
        .join(', ')}`
    );
    error.code = 'REMOTE_CANDIDATE_MISMATCH';
    error.details = mismatches;
    throw error;
  }
  return remote;
}

function buildBoundDeploymentEvidence(input, target, deployment, candidate) {
  const source = input || {};
  const finishedAt = source.finishedAt || new Date().toISOString();
  const finishedAtMs = Date.parse(finishedAt);
  if (!Number.isFinite(finishedAtMs)) {
    fail('测试证据 finishedAt 无效');
  }
  const validUntil =
    source.validUntil ||
    new Date(finishedAtMs + 24 * 60 * 60 * 1000).toISOString();
  return {
    ...source,
    schemaVersion: 1,
    deploymentId: deployment.id,
    candidateId: candidate?.id || null,
    candidateHash: candidate?.candidateHash || null,
    testPlanHash: candidate?.testPlanHash || null,
    environmentId: target.environmentId,
    environmentKind: target.environmentKind,
    appType: target.appType,
    appReleaseId: deployment.targetAppReleaseId,
    outcome: source.outcome || 'passed',
    startedAt: source.startedAt || finishedAt,
    finishedAt,
    validUntil,
  };
}

function managedShipTestPlan() {
  return {
    schemaVersion: 1,
    requiredGates: [
      'preproductionDeployment',
      'cleanup',
    ],
    maximumEvidenceAgeHours: 24,
    policy: 'fast_explicit_confirmation_v1',
  };
}

function managedEnvironmentTarget(config, state, kind) {
  const selected = resolveEnvironmentTarget(state, kind);
  return getWorkspaceTarget(
    config,
    selected.binding.profile,
    { environment: selected.targetName }
  );
}

async function readManagedDeployment(
  config,
  target,
  logicalAppCode,
  deploymentId,
  options = {}
) {
  const apiPath = applicationDeploymentApiPath(
    logicalAppCode,
    deploymentId
  );
  const deployment = await requestWithAuth(
    config,
    target.profileName,
    options.full ? `${apiPath}?full=true` : apiPath
  );
  rememberTargetDeployment(target, deployment);
  return deployment;
}

function inspectSucceededPreproductionDeployment(
  deployment,
  context,
  now = Date.now()
) {
  const candidate = context?.candidate || {};
  const target = context?.target || {};
  const currentAppReleaseId = String(
    context?.currentAppReleaseId || ''
  ).trim();
  const evidence = deployment?.evidenceSummary;
  const reasons = [];
  if (deployment?.status !== 'succeeded') {
    reasons.push('status_not_succeeded');
  }
  if (deployment?.kind !== 'deploy') {
    reasons.push('kind_not_preproduction_deploy');
  }
  if (deployment?.candidateId !== candidate.id) {
    reasons.push('candidate_mismatch');
  }
  if (deployment?.targetEnvironmentId !== target.environmentId) {
    reasons.push('target_environment_mismatch');
  }
  if (!currentAppReleaseId) reasons.push('current_app_release_missing');
  if (deployment?.targetAppReleaseId !== currentAppReleaseId) {
    reasons.push('active_app_release_mismatch');
  }
  if (!deployment?.evidenceHash) reasons.push('evidence_hash_missing');
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) {
    reasons.push('evidence_summary_missing');
  } else {
    if (sha256Canonical(evidence) !== deployment.evidenceHash) {
      reasons.push('evidence_hash_mismatch');
    }
    if (evidence.outcome !== 'passed') reasons.push('evidence_not_passed');
    if (evidence.deploymentId !== deployment.id) {
      reasons.push('evidence_deployment_mismatch');
    }
    if (evidence.candidateId !== candidate.id) {
      reasons.push('evidence_candidate_mismatch');
    }
    if (evidence.candidateHash !== candidate.candidateHash) {
      reasons.push('evidence_candidate_hash_mismatch');
    }
    if ((evidence.testPlanHash || null) !== (candidate.testPlanHash || null)) {
      reasons.push('evidence_test_plan_hash_mismatch');
    }
    if (evidence.environmentId !== target.environmentId) {
      reasons.push('evidence_environment_mismatch');
    }
    if (evidence.environmentKind !== 'preproduction') {
      reasons.push('evidence_environment_kind_mismatch');
    }
    if (evidence.appType !== target.appType) {
      reasons.push('evidence_app_type_mismatch');
    }
    if (evidence.appReleaseId !== deployment.targetAppReleaseId) {
      reasons.push('evidence_app_release_mismatch');
    }
    const validUntil = Date.parse(evidence.validUntil || '');
    if (!Number.isFinite(validUntil) || validUntil <= now) {
      reasons.push('evidence_expired');
    }
  }
  return { accepted: reasons.length === 0, reasons };
}

function selectSucceededPreproductionDeployment(
  deployments,
  context,
  now = Date.now()
) {
  const ordered = [...(deployments || [])].sort((left, right) => {
    const rightCreated =
      Date.parse(right?.createdAt || right?.finishedAt || '') || 0;
    const leftCreated =
      Date.parse(left?.createdAt || left?.finishedAt || '') || 0;
    return rightCreated - leftCreated;
  });
  for (const deployment of ordered) {
    const validation = inspectSucceededPreproductionDeployment(
      deployment,
      context,
      now
    );
    if (validation.accepted) return deployment;
  }
  return null;
}

function managedPreproductionEvidenceLineage(
  deployment,
  candidate,
  target
) {
  return {
    deploymentId: deployment.id,
    candidateId: candidate.id,
    candidateHash: candidate.candidateHash,
    testPlanHash: candidate.testPlanHash || null,
    environmentId: target.environmentId,
    environmentKind: target.environmentKind,
    appType: target.appType,
    appReleaseId: deployment.targetAppReleaseId,
    evidenceHash: deployment.evidenceHash || null,
  };
}

function recoveredPreproductionShipPatch(
  resolution,
  candidate,
  target,
  recoveredAt = new Date().toISOString()
) {
  const deployment = resolution.deployment;
  return {
    status: 'awaiting_production_confirmation',
    preproductionDeploymentId: deployment.id,
    preproductionAppReleaseId: deployment.targetAppReleaseId,
    preproductionStatus: deployment.status,
    preproductionEvidenceHash: deployment.evidenceHash,
    preproductionEvidenceLineage: managedPreproductionEvidenceLineage(
      deployment,
      candidate,
      target
    ),
    preproductionRecovery: {
      status: 'recovered_from_candidate_history',
      replacedDeploymentId: resolution.replacedDeploymentId,
      replacedDeploymentStatus: resolution.replacedDeploymentStatus,
      selectedDeploymentId: deployment.id,
      recoveredAt,
    },
    failure: null,
  };
}

async function resolvePreproductionDeploymentForAcceptance(
  config,
  target,
  logicalAppCode,
  originalDeploymentId,
  candidate
) {
  await assertRemoteCandidateMatches(
    config,
    target,
    logicalAppCode,
    candidate
  );
  const status = await requestWithAuth(
    config,
    target.profileName,
    environmentSetApiPath(logicalAppCode, '/status')
  );
  const targetStatus = (status?.environments || []).find(
    environment =>
      environment?.id === target.environmentId &&
      environment?.kind === 'preproduction' &&
      environment?.appType === target.appType
  );
  const currentAppReleaseId = String(
    targetStatus?.heads?.appReleaseId || ''
  ).trim();
  if (!targetStatus || !currentAppReleaseId) {
    fail(
      `PREPRODUCTION_ACTIVE_HEAD_REQUIRED: 预发环境 ${target.environmentId} 缺少可验证的当前 AppRelease head`
    );
  }

  let originalDeployment = null;
  let originalReadError = null;
  try {
    originalDeployment = await readManagedDeployment(
      config,
      target,
      logicalAppCode,
      originalDeploymentId,
      { full: true }
    );
  } catch (error) {
    originalReadError = error;
  }
  const context = { candidate, target, currentAppReleaseId };
  if (originalDeployment?.status === 'deployed') {
    const identityMatches =
      originalDeployment.kind === 'deploy' &&
      originalDeployment.candidateId === candidate.id &&
      originalDeployment.targetEnvironmentId === target.environmentId &&
      originalDeployment.targetAppReleaseId === currentAppReleaseId;
    if (identityMatches) {
      return {
        deployment: originalDeployment,
        recovered: false,
        currentAppReleaseId,
      };
    }
  }
  if (originalDeployment?.status === 'succeeded') {
    const validation = inspectSucceededPreproductionDeployment(
      originalDeployment,
      context
    );
    if (validation.accepted) {
      return {
        deployment: originalDeployment,
        recovered: false,
        currentAppReleaseId,
      };
    }
  }

  const history = await requestWithAuth(
    config,
    target.profileName,
    `${applicationDeploymentApiPath(logicalAppCode)}?limit=200`
  );
  const summaries = (Array.isArray(history) ? history : [])
    .filter(
      deployment =>
        deployment?.id !== originalDeploymentId &&
        deployment?.status === 'succeeded' &&
        deployment?.kind === 'deploy' &&
        deployment?.candidateId === candidate.id &&
        deployment?.targetEnvironmentId === target.environmentId &&
        deployment?.targetAppReleaseId === currentAppReleaseId
    )
    .sort((left, right) => {
      const rightCreated = Date.parse(right?.createdAt || '') || 0;
      const leftCreated = Date.parse(left?.createdAt || '') || 0;
      return rightCreated - leftCreated;
    });
  const details = [];
  for (const summary of summaries) {
    const detail = await requestWithAuth(
      config,
      target.profileName,
      `${applicationDeploymentApiPath(
        logicalAppCode,
        summary.id
      )}?full=true`
    );
    details.push(detail);
  }
  const replacement = selectSucceededPreproductionDeployment(
    details,
    context
  );
  if (!replacement) {
    const originalStatus = originalDeployment?.status || 'unreadable';
    const error = new Error(
      `PREPRODUCTION_NOT_READY_FOR_ACCEPTANCE: 预发 deployment ${originalDeploymentId} 当前状态为 ${originalStatus}，且未找到同 candidate、同环境、当前 AppRelease 和有效测试证据完全一致的 succeeded replacement`
    );
    error.code = 'PREPRODUCTION_NOT_READY_FOR_ACCEPTANCE';
    error.data = {
      originalDeploymentId,
      originalStatus,
      originalReadErrorCode: originalReadError?.code || null,
      candidateId: candidate.id,
      targetEnvironmentId: target.environmentId,
      currentAppReleaseId,
    };
    throw error;
  }
  rememberTargetDeployment(target, replacement);
  return {
    deployment: replacement,
    recovered: true,
    replacedDeploymentId: originalDeploymentId,
    replacedDeploymentStatus: originalDeployment?.status || 'unreadable',
    currentAppReleaseId,
  };
}

async function completeManagedDeployment(
  config,
  target,
  logicalAppCode,
  deployment,
  candidate,
  evidenceInput
) {
  if (deployment.status === 'succeeded') {
    return {
      deployment,
      evidence: deployment.evidenceSummary || evidenceInput || null,
    };
  }
  if (!['deployed', 'failed'].includes(deployment.status)) {
    fail(
      `DEPLOYMENT_NOT_READY_FOR_COMPLETION: deployment ${deployment.id} 当前状态为 ${deployment.status}`
    );
  }
  const reconciled = await requestWithAuth(
    config,
    target.profileName,
    applicationDeploymentApiPath(
      logicalAppCode,
      deployment.id,
      'reconcile'
    ),
    {
      method: 'POST',
      body: {
        reason: 'bind final active AppRelease lineage before test evidence',
      },
    }
  );
  if (reconciled.status === 'succeeded') {
    rememberTargetDeployment(target, reconciled);
    return {
      deployment: reconciled,
      evidence: reconciled.evidenceSummary || evidenceInput || null,
    };
  }
  if (reconciled.status !== 'deployed') {
    fail(
      `DEPLOYMENT_RECONCILIATION_NOT_CONFIRMED: deployment ${deployment.id} 恢复后状态为 ${reconciled.status}`
    );
  }
  deployment = reconciled;
  rememberTargetDeployment(target, deployment);
  const evidence = buildBoundDeploymentEvidence(
    evidenceInput,
    target,
    deployment,
    candidate
  );
  const completed = await requestWithAuth(
    config,
    target.profileName,
    applicationDeploymentApiPath(
      logicalAppCode,
      deployment.id,
      'complete'
    ),
    {
      method: 'POST',
      body: {
        evidenceSummary: evidence,
        evidenceHash: sha256Canonical(evidence),
      },
    }
  );
  if (completed.status !== 'succeeded') {
    fail(
      `DEPLOYMENT_COMPLETION_NOT_CONFIRMED: deployment ${deployment.id} 完成后状态为 ${completed.status}`
    );
  }
  rememberTargetDeployment(target, completed);
  return { deployment: completed, evidence };
}

const RELEASE_SHIP_SUPPORTED_FLAGS = new Set([
  'change',
  'profile',
  'environment',
  'app-type',
  'since',
  'expand-dependencies',
  'replace-manifest',
  'allow-runtime-rollback',
  'reason',
  'adopt-online-baseline',
  'adoption-reason',
  'confirm-production',
  'acceptance-note',
  'evidence-json',
  'json',
]);

function assertReleaseShipFlags(flags = {}) {
  const unsupported = Object.keys(flags)
    .filter(name => !RELEASE_SHIP_SUPPORTED_FLAGS.has(name))
    .sort();
  if (unsupported.length > 0) {
    const error = new Error(
      `RELEASE_SHIP_UNSUPPORTED_FLAG: release ship 不支持 ${unsupported
        .map(name => `--${name}`)
        .join(', ')}；命令已在任何 candidate/deployment 写入前终止`
    );
    error.code = 'RELEASE_SHIP_UNSUPPORTED_FLAG';
    error.unsupportedFlags = unsupported;
    throw error;
  }
  const replacementRequested = Boolean(flags['replace-manifest']);
  const runtimeRollbackRequested = Boolean(
    flags['allow-runtime-rollback']
  );
  const replacementReason = String(flags.reason || '').trim();
  if (
    !replacementRequested &&
    !runtimeRollbackRequested &&
    replacementReason
  ) {
    const error = new Error(
      'RELEASE_SHIP_SCOPED_REASON_FLAG_REQUIRED: --reason 必须与 --replace-manifest 或 --allow-runtime-rollback 一起使用；命令已在任何 candidate/deployment 写入前终止'
    );
    error.code = 'RELEASE_SHIP_SCOPED_REASON_FLAG_REQUIRED';
    throw error;
  }
  if (replacementRequested && replacementReason.length < 8) {
    const error = new Error(
      'RELEASE_SHIP_REPLACE_MANIFEST_REASON_REQUIRED: --replace-manifest 必须提供至少 8 个字符的 --reason；命令已在任何 candidate/deployment 写入前终止'
    );
    error.code = 'RELEASE_SHIP_REPLACE_MANIFEST_REASON_REQUIRED';
    throw error;
  }
  if (runtimeRollbackRequested && replacementReason.length < 8) {
    const error = new Error(
      'RELEASE_SHIP_RUNTIME_ROLLBACK_REASON_REQUIRED: --allow-runtime-rollback 必须提供至少 8 个字符的 --reason；命令已在任何 candidate/deployment 写入前终止'
    );
    error.code = 'RELEASE_SHIP_RUNTIME_ROLLBACK_REASON_REQUIRED';
    throw error;
  }
  const adoptionRequested = Boolean(flags['adopt-online-baseline']);
  const adoptionReason = String(flags['adoption-reason'] || '').trim();
  if (!adoptionRequested && adoptionReason) {
    const error = new Error(
      'RELEASE_SHIP_ADOPTION_FLAG_REQUIRED: --adoption-reason 必须与 --adopt-online-baseline 一起使用；命令已在任何 candidate/deployment 写入前终止'
    );
    error.code = 'RELEASE_SHIP_ADOPTION_FLAG_REQUIRED';
    throw error;
  }
  if (adoptionRequested && adoptionReason.length < 8) {
    const error = new Error(
      'RELEASE_SHIP_ADOPTION_REASON_REQUIRED: --adopt-online-baseline 必须提供至少 8 个字符的 --adoption-reason；命令已在任何 candidate/deployment 写入前终止'
    );
    error.code = 'RELEASE_SHIP_ADOPTION_REASON_REQUIRED';
    throw error;
  }
}

function assertManagedRuntimeRollbackFlags(flags = {}) {
  return resolveRuntimeRollbackBypass({
    allowRollback: flags['allow-runtime-rollback'],
    reason: flags.reason,
  });
}

async function runApplicationShipCommand(
  config,
  initialTarget,
  positional,
  flags
) {
  assertReleaseShipFlags(flags);
  const changeId =
    readStringFlag(flags, 'change') || positional[0];
  if (!changeId) {
    fail(
      '用法: openxiangda release ship --change <id> [--replace-manifest] [--allow-runtime-rollback] [--reason "..."] [--adopt-online-baseline --adoption-reason "..."] [--confirm-production] [--acceptance-note "..."]'
    );
  }
  const logicalApp = requireLogicalApplication(initialTarget);
  const preproduction = managedEnvironmentTarget(
    config,
    initialTarget.state,
    'preproduction'
  );
  const production = managedEnvironmentTarget(
    config,
    initialTarget.state,
    'production'
  );
  let existingShip = readManagedShip(changeId);
  const confirmProduction = Boolean(flags['confirm-production']);
  const intents = resolveManagedShipIntents(flags, existingShip);
  const {
    manifestReplacement,
    baselineAdoption,
    runtimeRollback,
    effectiveFlags,
  } = intents;

  let singleCommand = false;
  if (confirmProduction && !existingShip?.preproductionDeploymentId) {
    singleCommand = true;
    const preproductionFlags = { ...flags };
    delete preproductionFlags['confirm-production'];
    await runApplicationShipCommand(
      config,
      initialTarget,
      positional,
      preproductionFlags
    );
    existingShip = readManagedShip(changeId);
    if (!existingShip?.preproductionDeploymentId) {
      fail(
        'PREPRODUCTION_PHASE_INCOMPLETE: 一键发布未能建立可确认的预发 deployment'
      );
    }
  }

  if (!confirmProduction) {
    let candidate = existingShip?.candidateId
      ? readCandidate(existingShip.candidateId)
      : null;
    if (!candidate) {
      const created = await createApplicationCandidate(
        config,
        preproduction,
        {
          ...effectiveFlags,
          change: changeId,
          'test-plan-json': JSON.stringify(
            managedShipTestPlan()
          ),
        },
        [changeId]
      );
      candidate = created.candidate;
      writeManagedShip(changeId, {
        status: 'candidate_created',
        candidateId: candidate.id,
        candidateHash: candidate.candidateHash,
        sourceRevision: candidate.sourceRevision,
        candidateFile: created.candidateFile,
        manifestReplacement,
        baselineAdoption,
        runtimeRollback,
      });
    } else {
      assertLocalCandidate(candidate);
    }

    let deployment = null;
    if (existingShip?.preproductionDeploymentId) {
      deployment = await readManagedDeployment(
        config,
        preproduction,
        logicalApp.code,
        existingShip.preproductionDeploymentId
      );
    }
    if (
      !deployment ||
      !['deployed', 'succeeded'].includes(deployment.status)
    ) {
      try {
        const deployed = await deployApplicationCandidate(
          config,
          preproduction,
          candidate,
          { kind: 'deploy', flags: effectiveFlags }
        );
        deployment = deployed.deployment;
      } catch (error) {
        const failure = managedShipFailure(error);
        writeManagedShip(changeId, {
          status: 'preproduction_failed',
          candidateId: candidate.id,
          candidateHash: candidate.candidateHash,
          preproductionEnvironment: preproduction.targetName,
          preproductionDeploymentId: failure.deploymentId,
          preproductionStatus: failure.deploymentStatus,
          manifestReplacement,
          baselineAdoption,
          runtimeRollback,
          failure,
          nextCommand: buildManagedShipCommand(
            changeId,
            preproduction.profileName,
            intents
          ),
        });
        throw error;
      }
    }
    const saved = writeManagedShip(changeId, {
      status: 'awaiting_production_confirmation',
      candidateId: candidate.id,
      candidateHash: candidate.candidateHash,
      sourceRevision: candidate.sourceRevision,
      preproductionEnvironment: preproduction.targetName,
      preproductionDeploymentId: deployment.id,
      preproductionAppReleaseId:
        deployment.targetAppReleaseId || null,
      preproductionStatus: deployment.status,
      manifestReplacement,
      baselineAdoption,
      runtimeRollback,
      failure: null,
      preparedAt:
        existingShip?.preparedAt ||
        new Date().toISOString(),
      nextCommand: buildManagedShipCommand(
        changeId,
        preproduction.profileName,
        intents,
        { confirmProduction: true }
      ),
    });
    return {
      phase: 'preproduction',
      status: 'awaiting_production_confirmation',
      candidate,
      deployment,
      automaticPromotion: false,
      manualAcceptanceRecommended: true,
      manualAcceptanceRequired: false,
      shipFile: saved.file,
      nextCommand: saved.record.nextCommand,
    };
  }

  const acceptanceNote = readStringFlag(
    flags,
    'acceptance-note'
  );
  const candidate = readCandidate(existingShip.candidateId);
  assertLocalCandidate(candidate);
  const preproductionResolution = await resolvePreproductionDeploymentForAcceptance(
    config,
    preproduction,
    logicalApp.code,
    existingShip.preproductionDeploymentId,
    candidate
  );
  let preproductionDeployment = preproductionResolution.deployment;
  if (preproductionResolution.recovered) {
    writeManagedShip(
      changeId,
      recoveredPreproductionShipPatch(
        preproductionResolution,
        candidate,
        preproduction
      )
    );
    warn(
      `预发验收已从同 candidate 的成功部署恢复: ${preproductionResolution.replacedDeploymentId} -> ${preproductionDeployment.id}`
    );
  }

  const confirmedAt = new Date().toISOString();
  const manualAcceptance = acceptanceNote
    ? {
        status: 'passed',
        note: acceptanceNote,
        acceptedAt: confirmedAt,
      }
    : null;
  let preproductionEvidence =
    preproductionDeployment.evidenceSummary || null;
  if (preproductionDeployment.status !== 'succeeded') {
    const suppliedEvidence = flags['evidence-json']
      ? readJsonInput(flags['evidence-json'], 'evidence-json')
      : {};
    const requiredGates =
      candidate.testPlan?.requiredGates ||
      managedShipTestPlan().requiredGates;
    const evidenceInput = {
        ...suppliedEvidence,
        requiredGates,
        results: {
          ...(suppliedEvidence.results || {}),
          preproductionDeployment: {
            status: 'passed',
            appReleaseId:
              preproductionDeployment.targetAppReleaseId,
          },
          productionConfirmation: {
            status: 'passed',
            confirmedAt,
            note: acceptanceNote || null,
          },
          cleanup: {
            status: 'passed',
            residueCount: 0,
            reason:
              'release ship does not create test business data',
          },
        },
        cleanup: {
          passed: true,
          residueCount: 0,
          reason:
            'release ship does not create test business data',
        },
        ...(manualAcceptance
          ? { manualAcceptance }
          : {}),
      };
    const completed = await completeManagedDeployment(
      config,
      preproduction,
      logicalApp.code,
      preproductionDeployment,
      candidate,
      evidenceInput
    );
    preproductionDeployment = completed.deployment;
    preproductionEvidence = completed.evidence;
  }
  if (!preproductionEvidence) {
    fail(
      `PREPRODUCTION_EVIDENCE_MISSING: succeeded deployment ${preproductionDeployment.id} 缺少可绑定到生产部署的证据`
    );
  }

  const promotionStartedAt = new Date().toISOString();
  writeManagedShip(changeId, {
    status: 'confirmed_for_production',
    preproductionDeploymentId: preproductionDeployment.id,
    preproductionAppReleaseId: preproductionDeployment.targetAppReleaseId,
    preproductionStatus: preproductionDeployment.status,
    preproductionEvidenceHash: preproductionDeployment.evidenceHash,
    preproductionEvidenceLineage: managedPreproductionEvidenceLineage(
      preproductionDeployment,
      candidate,
      preproduction
    ),
    productionConfirmation: {
      status: 'confirmed',
      confirmedAt,
      profile: preproduction.profileName,
      acceptanceNote: acceptanceNote || null,
    },
    productionPromotion: {
      status: 'running',
      startedAt: promotionStartedAt,
      environment: production.targetName,
      deploymentId: null,
    },
    manualAcceptance,
    preproductionStatus: preproductionDeployment.status,
  });
  let promoted;
  try {
    promoted = await deployApplicationCandidate(
      config,
      production,
      candidate,
      {
        kind: 'promotion',
        sourceEnvironmentId:
          preproduction.environmentId,
        flags: effectiveFlags,
      }
    );
  } catch (error) {
    const failure = managedShipFailure(error);
    writeManagedShip(changeId, {
      status: 'production_failed',
      productionEnvironment: production.targetName,
      productionDeploymentId: failure.deploymentId,
      productionStatus: failure.deploymentStatus,
      manifestReplacement,
      baselineAdoption,
      runtimeRollback,
      failure,
      productionPromotion: {
        status: 'failed',
        startedAt: promotionStartedAt,
        failedAt: failure.recordedAt,
        environment: production.targetName,
        deploymentId: failure.deploymentId,
        deploymentStatus: failure.deploymentStatus,
        failure,
      },
      nextCommand: buildManagedShipCommand(
        changeId,
        preproduction.profileName,
        intents,
        { confirmProduction: true }
      ),
    });
    throw error;
  }
  const completedAt = new Date().toISOString();
  const productionEvidenceInput = {
    ...preproductionEvidence,
    startedAt: promotionStartedAt,
    finishedAt: completedAt,
    validUntil: new Date(
      Date.parse(completedAt) + 24 * 60 * 60 * 1000
    ).toISOString(),
    results: {
      ...(preproductionEvidence.results || {}),
      preproductionDeployment: {
        status: 'passed',
        deploymentId: preproductionDeployment.id,
        appReleaseId:
          preproductionDeployment.targetAppReleaseId,
      },
      productionConfirmation: {
        status: 'passed',
        confirmedAt,
        note: acceptanceNote || null,
      },
    },
    ...(manualAcceptance ? { manualAcceptance } : {}),
  };
  let completedProduction;
  try {
    completedProduction = await completeManagedDeployment(
      config,
      production,
      logicalApp.code,
      promoted.deployment,
      candidate,
      productionEvidenceInput
    );
  } catch (error) {
    const failure = managedShipFailure(error);
    writeManagedShip(changeId, {
      status: 'production_evidence_failed',
      productionEnvironment: production.targetName,
      productionDeploymentId: promoted.deployment.id,
      productionAppReleaseId:
        promoted.deployment.targetAppReleaseId || null,
      productionStatus: promoted.deployment.status,
      manifestReplacement,
      baselineAdoption,
      runtimeRollback,
      failure,
      productionPromotion: {
        status: 'evidence_failed',
        startedAt: promotionStartedAt,
        failedAt: failure.recordedAt,
        environment: production.targetName,
        deploymentId: promoted.deployment.id,
        deploymentStatus: promoted.deployment.status,
        failure,
      },
      nextCommand: buildManagedShipCommand(
        changeId,
        preproduction.profileName,
        intents,
        { confirmProduction: true }
      ),
    });
    throw error;
  }
  promoted.deployment = completedProduction.deployment;
  const saved = writeManagedShip(changeId, {
    status: 'completed',
    productionEnvironment: production.targetName,
    productionDeploymentId: promoted.deployment.id,
    productionAppReleaseId:
      promoted.deployment.targetAppReleaseId || null,
    productionStatus: promoted.deployment.status,
    failure: null,
    completedAt,
    productionPromotion: {
      status: 'completed',
      startedAt: promotionStartedAt,
      completedAt,
      environment: production.targetName,
      deploymentId: promoted.deployment.id,
      deploymentStatus: promoted.deployment.status,
    },
  });
  return {
    phase: 'production',
    status: 'completed',
    candidate,
    preproductionDeployment,
    productionDeployment: promoted.deployment,
    productionConfirmation:
      saved.record.productionConfirmation,
    manualAcceptance: saved.record.manualAcceptance,
    sameCandidate: true,
    singleCommand,
    shipFile: saved.file,
  };
}

async function runApplicationEnvironmentReleaseCommand(
  config,
  target,
  subcommand,
  positional,
  flags
) {
  const logicalApp = requireLogicalApplication(target);
  if (subcommand === 'ship') {
    return await runApplicationShipCommand(
      config,
      target,
      positional,
      flags
    );
  }
  if (subcommand === 'candidate') {
    return await createApplicationCandidate(
      config,
      target,
      flags,
      positional
    );
  }

  if (subcommand === 'reconcile') {
    const deploymentId =
      readStringFlag(flags, 'deployment') ||
      readStringFlag(flags, 'deployment-id') ||
      positional[0] ||
      readRememberedTargetDeployment(target)?.deploymentId;
    const reason = readStringFlag(flags, 'reason');
    if (!deploymentId || reason.length < 8) {
      fail(
        'release reconcile 必须提供 --deployment <id> 和至少 8 个字符的 --reason'
      );
    }
    const reconciled = await requestWithAuth(
      config,
      target.profileName,
      applicationDeploymentApiPath(
        logicalApp.code,
        deploymentId,
        'reconcile'
      ),
      {
        method: 'POST',
        body: { reason },
      }
    );
    rememberTargetDeployment(target, reconciled);
    return { deployment: reconciled, reconciled: true };
  }

  if (subcommand === 'fail') {
    if (target.environmentKind !== 'preproduction') {
      fail(
        'RELEASE_FAIL_PREPRODUCTION_ONLY: release fail 只允许 preproduction target，禁止用于 production deployment'
      );
    }
    const deploymentId =
      readStringFlag(flags, 'deployment') ||
      readStringFlag(flags, 'deployment-id');
    const message = readStringFlag(flags, 'message');
    const failureCode = readStringFlag(flags, 'code');
    const detailsInput = readStringFlag(flags, 'details-json');
    if (!deploymentId || !message) {
      fail(
        'release fail 必须显式提供 --deployment <id> 和 --message <text>'
      );
    }
    const details = detailsInput
      ? readJsonInput(detailsInput, 'details-json')
      : null;
    const deployment = await requestWithAuth(
      config,
      target.profileName,
      applicationDeploymentApiPath(logicalApp.code, deploymentId)
    );
    if (
      deployment?.id !== deploymentId ||
      deployment?.targetEnvironmentId !== target.environmentId
    ) {
      fail(
        `RELEASE_FAIL_DEPLOYMENT_ENVIRONMENT_MISMATCH: deployment ${deploymentId} 不属于当前预发环境 ${target.targetName}(${target.environmentId})，未写入失败状态`
      );
    }
    const failed = await requestWithAuth(
      config,
      target.profileName,
      applicationDeploymentApiPath(
        logicalApp.code,
        deploymentId,
        'fail'
      ),
      {
        method: 'POST',
        body: {
          ...(failureCode ? { code: failureCode } : {}),
          message,
          ...(details ? { details } : {}),
        },
      }
    );
    if (failed?.status !== 'failed') {
      fail(
        `DEPLOYMENT_FAILURE_NOT_CONFIRMED: deployment ${deploymentId} 标记失败后状态为 ${failed?.status || 'unknown'}`
      );
    }
    rememberTargetDeployment(target, failed);
    return { deployment: failed, failed: true };
  }

  if (['deploy', 'promote'].includes(subcommand)) {
    assertManagedRuntimeRollbackFlags(flags);
  }

  const candidateId =
    readStringFlag(flags, 'candidate') ||
    readStringFlag(flags, 'candidate-id') ||
    positional[0] ||
    readRememberedTargetDeployment(target)?.candidateId;
  if (subcommand === 'deploy') {
    if (target.environmentKind !== 'preproduction') {
      fail('release deploy 只允许目标为 preproduction');
    }
    if (!candidateId) fail('release deploy 必须提供 --candidate');
    return await deployApplicationCandidate(
      config,
      target,
      readCandidate(candidateId),
      { kind: 'deploy', flags }
    );
  }

  if (subcommand === 'promote') {
    if (target.environmentKind !== 'production') {
      fail(
        'release promote 必须使用 --environment production（或对应 production target）'
      );
    }
    if (!flags['confirm-production']) {
      fail('正式晋级必须显式提供 --confirm-production');
    }
    if (!candidateId) fail('release promote 必须提供 --candidate');
    const source = resolveEnvironmentTarget(target.state, 'preproduction');
    return await deployApplicationCandidate(
      config,
      target,
      readCandidate(candidateId),
      {
        kind: 'promotion',
        sourceEnvironmentId: source.binding.environmentId,
        flags,
      }
    );
  }

  if (subcommand === 'test') {
    const deploymentId =
      readStringFlag(flags, 'deployment') ||
      readStringFlag(flags, 'deployment-id') ||
      readRememberedTargetDeployment(target)?.deploymentId;
    if (!deploymentId || !flags['evidence-json']) {
      fail(
        'release test 必须提供 --deployment <id>（首次可省略）和 --evidence-json <JSON|file>'
      );
    }
    const deployment = await requestWithAuth(
      config,
      target.profileName,
      applicationDeploymentApiPath(logicalApp.code, deploymentId)
    );
    const candidate = deployment.candidateId
      ? readCandidate(deployment.candidateId)
      : null;
    return await completeManagedDeployment(
      config,
      target,
      logicalApp.code,
      deployment,
      candidate,
      readJsonInput(flags['evidence-json'], 'evidence-json')
    );
  }

  if (subcommand === 'rollback') {
    if (target.environmentKind !== 'production') {
      fail('release rollback 只允许 production target');
    }
    if (!flags['confirm-production']) {
      fail('正式回退必须显式提供 --confirm-production');
    }
    const rollbackTargetReleaseId =
      readStringFlag(flags, 'to') ||
      readStringFlag(flags, 'release-id') ||
      positional[0];
    const reason = readStringFlag(flags, 'reason');
    if (!rollbackTargetReleaseId || reason.length < 8) {
      fail(
        'release rollback 必须提供 --to <AppReleaseId> 和至少 8 个字符的 --reason'
      );
    }
    const deployment = await requestWithAuth(
      config,
      target.profileName,
      applicationDeploymentApiPath(logicalApp.code),
      {
        method: 'POST',
        body: {
          kind: 'rollback',
          targetEnvironmentId: target.environmentId,
          rollbackTargetReleaseId,
        },
      }
    );
    rememberTargetDeployment(target, deployment);
    return {
      deployment,
      prepared: true,
      automaticActivation: false,
      reason:
        '总 AppRelease 回退记录已冻结；各历史子 Release 仍需生成新的审计式 rollback Release 后再原子激活，CLI 不会直接重激活旧行。',
      nextStep: `openxiangda release app-rollback ${rollbackTargetReleaseId} --change rollback-${deployment.id} --reason ${JSON.stringify(
        reason
      )} --environment ${target.targetName}`,
    };
  }

  fail(`未知应用环境 Release 命令: ${subcommand}`);
}

async function release(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda release publish|begin|status|explain|integration-status|renew|end [--change id] [--profile name] [--adopt-online-baseline --adoption-reason text] [--json]',
      '      openxiangda release ship|candidate|deploy|reconcile|test|fail|promote|rollback [--candidate id] [--deployment id] [--environment target] [--replace-manifest] [--allow-runtime-rollback --reason text] [--adopt-online-baseline --adoption-reason text] [--confirm-production] [--json]',
      '      openxiangda release backend-head|backend-list|backend-detail|backend-diff|backend-rollback|backend-abort|backend-retry [releaseId] [--profile name] [--json]',
      '      openxiangda release app-capture|app-head|app-list|app-detail|app-diff|app-post-commit|app-retry|app-prepare|app-verify|app-activate|app-finalize|app-rollback|app-abort [releaseId] [--staged-resources-json <JSON|file>] [--activate-staged-children] [--break-glass-adopt-verified-root --reason text] [--force-activate-without-validation] [--profile name] [--json]',
      '常用流程:',
      '  openxiangda release ship --change <id> --profile <name>',
      '  openxiangda release ship --change <id> --profile <name> --adopt-online-baseline --adoption-reason "已审计目标来自多次历史发布"',
      '  openxiangda release ship --change <id> --profile <name> --replace-manifest --reason "已审查精确 Function manifest"',
      '  openxiangda release ship --change <id> --profile <name> --allow-runtime-rollback --reason "已审计并批准 Runtime 源码基线回退"',
      '  # 确认预发结果后；可选 --acceptance-note 留下人工验收记录：',
      '  openxiangda release ship --change <id> --profile <name> --confirm-production',
      '  openxiangda release fail --deployment <id> --message "UAT 未通过" --code UAT_FAILED --details-json <JSON|file> --environment preproduction --profile <name>',
      '  openxiangda release publish --change <id> --profile <name>',
      '  openxiangda release publish --change <id> --profile <name> --adopt-online-baseline --adoption-reason "已审计目标来自多次历史发布"',
      '  openxiangda release begin --change <id> --profile <name>',
      '  openxiangda resource publish function --only <code> --change <id> --profile <name>',
      '  openxiangda runtime deploy --change <id> --profile <name>',
      '  openxiangda release integration-status --change <id> --profile <name>',
      '  openxiangda release end --profile <name>',
      '  openxiangda release backend-head --profile <name>',
      '  openxiangda release backend-diff <fromReleaseId> <toReleaseId> --profile <name>',
      '  openxiangda release backend-rollback <releaseId> --change <id> --reason "..." --profile <name>',
      '  openxiangda release app-finalize --change <id> --staged-resources-json <JSON|file> --profile <name>',
      '说明:',
      '  - ship 是环境托管应用的有序快车道：默认首次只部署预发并停止，第二次以同一 candidate 晋级正式；明确授权紧急发布时可在首次携带 --confirm-production，一条命令顺序完成两阶段。人工验收备注可选。',
      '  - candidate 封存环境/资源绑定、源码身份和两目标 Runtime 哈希产物；预发与正式部署均不现场重建，Backend/Runtime/Root 始终使用 candidate sourceRevision，并以 deployment succeeded 闭环。',
      '  - 已合入主线但线上来自多次历史 lineage 的精确非删除恢复可显式使用 --adopt-online-baseline 与 --adoption-reason；预发冻结后，正式确认会从 ship.json 自动复用同一意图，仍保留冻结 Head、CAS、租约、staged children 和单次 App finalize。',
      '  - ship 的 --replace-manifest 与 --reason 必须成对，只透传给精确 Backend Function/Automation stage；正式确认必须复用与预发完全相同的参数。',
      '  - --allow-runtime-rollback 与 --reason 必须成对，只透传给 runtime-stage；ship 会冻结并在正式确认自动复用该审计意图，app-finalize 不会收到这些参数。',
      '  - release fail 只允许显式选择 preproduction target，并会先核对 deployment 的 targetEnvironmentId；message 必填，code/details 会一并写入平台审计。',
      '  - ship 当前不支持 --dry-run；任何未声明参数都会在 candidate/deployment 写入前 fail-closed。需要只读检查时使用 environment status/diff 与 release status。',
      '  - publish 默认等待租约并按私有执行日志恢复；上次写结果不确定时必须只读核对后显式 --resume-after-review。',
      '  - 旧式非环境托管 publish 也会把线上基线采纳意图仅透传给精确的 resource publish --only/--code 阶段；无精确资源阶段、原因不足或单独提供 reason 均在获取租约前 fail-closed。',
      '  - app-head 默认只输出紧凑 head 摘要；需要完整 manifest 时显式追加 --full。',
      '  - begin 获取应用级单写者 promotion lease；不同工作区仍可并行开发和验证。',
      '  - 带 --change 的 resource/runtime 写命令在没有本地 lease 时会自动 begin，并在后续命令复用。',
      '  - 子 Runtime/Page/Backend/Form Release 默认先 stage；app-finalize 用 --staged-resources-json 覆盖 capture 中的 changed children，并在同一事务中原子激活。',
      '  - 默认 TTL 为 120 秒；活动发布每 30 秒心跳并在到期前续租，客户端退出后孤儿租约最多阻塞约 2 分钟。',
      '  - begin 仅接受 clean 且与权威远端默认 main/master 完全一致的 HEAD；feature branch 先合并并 push，再由主分支一次发布。',
      '  - 因发布源已在远端主线，成功激活后 integration-status 会立即通过，end 不再等待补合并。',
      '  - 发布已结束时，integration-status --change 会先从 ship.json 恢复托管 candidate 血缘，再自动查找其 production/preproduction deployment execution 日志；恢复失败会列出实际缺失的文件或字段。',
      '  - integration-status --check 可作为 CI 门禁；尚未回合时返回非零。',
      '  - 主线目标只能来自权威 Git remote 的实时默认 main/master；参数和环境变量不能改写。',
      '  - 租约过期也会保留待回合证据；完成 merge/push 后仍可执行 end 清理。',
      '  - 同步本地构建会先续到平台最大 TTL，构建后再次校验；流程结束后显式 end。',
    ].join('\n'));
    return;
  }

  const config = loadConfig();
  const target = getWorkspaceTarget(
    config,
    flags.profile || config.currentProfile,
    flags
  );
  if (
    [
      'ship',
      'candidate',
      'deploy',
      'reconcile',
      'test',
      'fail',
      'promote',
      'rollback',
    ].includes(subcommand)
  ) {
    const result = await runApplicationEnvironmentReleaseCommand(
      config,
      target,
      subcommand,
      positional,
      flags
    );
    if (flags.json) return writeJson(result);
    print(JSON.stringify(result, null, 2));
    return;
  }
  if (String(subcommand || '').startsWith('backend-')) {
    return await runBackendReleaseCommand(
      config,
      target,
      subcommand,
      positional,
      flags
    );
  }
  if (String(subcommand || '').startsWith('app-')) {
    return await runAppReleaseCommand(
      config,
      target,
      subcommand,
      positional,
      flags
    );
  }
  if (subcommand === 'publish') {
    if (target.environmentKind === 'production') {
      fail(
        'PRODUCTION_PROMOTION_REQUIRED: production target 禁止 release publish；请使用 release promote --candidate <id> --environment production --confirm-production'
      );
    }
    if (target.environmentKind === 'preproduction') {
      fail(
        'PREPRODUCTION_DEPLOYMENT_REQUIRED: 环境管理工作区请使用 release candidate + release deploy，确保候选和 deployment 可追踪'
      );
    }
    const result = await publishWorkspaceRelease(config, target, flags);
    if (flags.json) return writeJson(result);
    print(
      result.dryRun
        ? `发布计划已生成（未写入）: ${result.changeId} steps=${result.steps.length}`
        : `应用原子发布完成: ${result.appType} change=${result.changeId}`
    );
    return;
  }
  const leaseIdFromArgs = positional[0] || readStringFlag(flags, 'lease-id');

  if (subcommand === 'explain') {
    const changeId = positional[0] || readStringFlag(flags, 'change');
    if (!changeId) {
      fail('用法: openxiangda release explain --change <id> [--json]');
    }
    const execution = readReleaseExecution(
      changeId,
      readStringFlag(flags, 'deployment-id')
    );
    const result = {
      changeId,
      execution,
      diagnosis: explainReleaseExecution(execution),
    };
    if (flags.json) return writeJson(result);
    print(
      [
        `release ${changeId}: ${result.diagnosis.state}`,
        result.diagnosis.summary,
        `下一步: ${result.diagnosis.nextAction}`,
      ].join('\n')
    );
    return;
  }

  if (subcommand === 'status') {
    const local = getStoredPublishLease(target);
    const baseline = getStoredChangeBaseline(target, {
      access: 'reconciliation-read',
    });
    const clientSessionId =
      (local && isPublishLeaseOwnedByCurrentSession(local)
        ? local.clientSessionId
        : null) ||
      baseline?.clientSessionId ||
      createPublishClientSessionId();
    const remote = await fetchPublishLeaseStatus(
      config,
      target,
      clientSessionId
    );
    const changeId =
      positional[0] ||
      readStringFlag(flags, 'change') ||
      local?.changeId ||
      baseline?.changeId;
    const execution = changeId
      ? readReleaseExecution(
          changeId,
          readStringFlag(flags, 'deployment-id')
        )
      : null;
    const result = {
      remote,
      local,
      releaseSourceRevision: baseline?.releaseSourceRevision || null,
      integration: null,
      integrationCheckRequired: Boolean(baseline?.releaseSourceRevision),
      changeId: changeId || null,
      execution,
      diagnosis: explainReleaseExecution(execution),
      localOwnedByCurrentSession: local
        ? isPublishLeaseOwnedByCurrentSession(local)
        : null,
    };
    if (flags.watch) {
      return await watchTaskStatus(config, target, changeId, flags);
    }
    if (flags.json) return writeJson(result);
    printPublishLeaseStatus(result);
    return;
  }

  if (subcommand === 'integration-status') {
    const baseline = getStoredChangeBaseline(target, {
      access: 'reconciliation-read',
    });
    const changeId = positional[0] || readStringFlag(flags, 'change');
    const recovered = baseline?.releaseSourceRevision
      ? {
          sourceRevision: null,
          source: null,
          checked: [],
        }
      : readReleaseLineageRecovery(
          changeId,
          readStringFlag(flags, 'deployment-id')
        );
    const sourceRevision =
      baseline?.releaseSourceRevision ||
      recovered.sourceRevision;
    if (!sourceRevision) {
      if (changeId) {
        const checked = recovered.checked
          .map(item =>
            item.exists
              ? `${item.file} (${item.field})`
              : `${item.file} (文件不存在)`
          )
          .join('; ');
        fail(
          `RELEASE_SOURCE_LINEAGE_REQUIRED: change ${changeId} 的私有发布记录无法恢复 releaseSourceRevision；已检查: ${checked}`
        );
      }
      fail(
        'RELEASE_SOURCE_LINEAGE_REQUIRED: 当前 release 没有冻结的 releaseSourceRevision；发布已结束时请同时传入 --change <id>，以便从私有执行日志恢复主线证据'
      );
    }
    const result = {
      ...inspectReleaseSourceIntegration(
        sourceRevision,
        { cwd: process.cwd() }
      ),
      lineageSource: baseline?.releaseSourceRevision
        ? '.openxiangda/state.json#promotion.changeBaseline.releaseSourceRevision'
        : recovered.source,
    };
    if (flags.check && !result.integrated) {
      assertReleaseSourceIntegrated(sourceRevision, { cwd: process.cwd() });
    }
    if (flags.json) return writeJson(result);
    printReleaseIntegrationStatus(result);
    return;
  }

  if (subcommand === 'begin' || subcommand === 'acquire') {
    const changeId = positional[0] || readStringFlag(flags, 'change');
    if (!changeId) {
      fail('用法: openxiangda release begin --change <id> [--profile name]');
    }
    assertOrClaimWorktreeOwner({ cwd: process.cwd(), changeId });
    const stored = getStoredPublishLease(target);
    assertLocalPublishLeaseOwnership(stored);
    const existing = getUsableStoredPublishLease(target);
    if (existing && existing.changeId !== changeId) {
      fail(
        `本工作区已有 change ${existing.changeId || '-'} 的发布租约，请先执行 openxiangda release end`
      );
    }
    const pendingBaseline = getStoredChangeBaseline(target);
    const newReleaseLifecycle = !existing && !pendingBaseline;
    const reusableFormCandidates = newReleaseLifecycle
      ? reusableStagedFormReleaseCandidates(target, changeId)
      : [];
    const clientSessionId =
      existing?.clientSessionId ||
      (pendingBaseline?.changeId === changeId &&
      isChangeBaselineOwnedByCurrentSession(pendingBaseline)
        ? pendingBaseline.clientSessionId
        : null) ||
      readStringFlag(flags, 'client-session-id') ||
      createPublishClientSessionId();
    const baseline = await ensureChangeBaseline(
      config,
      target,
      changeId,
      flags,
      clientSessionId
    );
    let lease;
    try {
      lease = existing
        ? await renewPublishLease(config, target, existing, flags)
        : await acquirePublishLease(config, target, changeId, {
            ...flags,
            'client-session-id': clientSessionId,
          });
    } catch (error) {
      clearRejectedPendingBaseline(target, baseline, error);
      throw error;
    }
    const finalizedBaseline = finalizeReleaseBaseline(target, baseline);
    let frozenCapture = null;
    let releaseSessionFile = null;
    let stagedResourcesFile = null;
    let reusedStagedFormReleases = [];
    try {
      if (flags['freeze-app-capture']) {
        frozenCapture = await fetchAppReleaseCapture(config, target, flags);
        releaseSessionFile = saveFrozenAppReleaseCapture(
          target,
          changeId,
          finalizedBaseline,
          lease,
          frozenCapture
        );
      }
      if (newReleaseLifecycle) {
        const initialized = await initializeNewReleaseStagedResources(
          config,
          target,
          changeId,
          reusableFormCandidates
        );
        stagedResourcesFile = initialized.file;
        reusedStagedFormReleases = initialized.reused;
      }
    } catch (error) {
      if (newReleaseLifecycle) {
        try {
          await requestWithAuth(
            config,
            target.profileName,
            publishLeaseApiPath(
              target,
              `/${encodeURIComponent(lease.leaseId)}/release`
            ),
            { method: 'POST', body: { completion: 'local-prepare-failed' } }
          );
        } catch {
          // Preserve the local preparation failure as the primary error.
        }
        clearPublishLease(target, lease.leaseId);
        clearChangeBaseline(target, finalizedBaseline?.baselineId);
        releaseWorktreeOwner({ cwd: process.cwd() });
      }
      throw error;
    }
    const result = {
      ...lease,
      baselineId: finalizedBaseline?.baselineId,
      baselineHeadDigest: finalizedBaseline?.headDigest,
      sourceBase: finalizedBaseline?.sourceBase,
      releaseSourceRevision: finalizedBaseline?.releaseSourceRevision,
      ...(frozenCapture
        ? {
            captureHash: frozenCapture.captureHash,
            releaseSessionFile,
          }
        : {}),
      ...(stagedResourcesFile ? { stagedResourcesFile } : {}),
      ...(reusedStagedFormReleases.length > 0
        ? { reusedStagedFormReleases }
        : {}),
    };
    if (flags.json) return writeJson(result);
    print(
        `应用发布租约与变更基线已获取: ${target.appType} change=${lease.changeId || changeId} baseline=${finalizedBaseline?.baselineId || '-'} publishSource=${String(finalizedBaseline?.releaseSourceRevision?.baseCommit || '-').slice(0, 12)} main=${finalizedBaseline?.releaseSourceRevision?.remoteName ? `${finalizedBaseline.releaseSourceRevision.remoteName}/` : ''}${finalizedBaseline?.releaseSourceRevision?.mainBranch || '-'} expiresAt=${lease.expiresAt}`
    );
    return;
  }

  if (subcommand === 'renew') {
    const stored = getStoredPublishLease(target);
    if (!leaseIdFromArgs) assertLocalPublishLeaseOwnership(stored);
    assertOrClaimWorktreeOwner({
      cwd: process.cwd(),
      changeId: stored?.changeId || readStringFlag(flags, 'change') || 'unscoped-publish',
    });
    const leaseId = leaseIdFromArgs || stored?.leaseId;
    if (!leaseId) fail('当前工作区没有发布租约，请先执行 openxiangda release begin --change <id>');
    const baseline = getStoredChangeBaseline(target);
    assertStoredReleaseSourceStable(baseline);
    const lease = await renewPublishLease(
      config,
      target,
      { ...(stored || {}), leaseId },
      flags
    );
    if (flags.json) return writeJson(lease);
    print(`应用发布租约已续期: ${target.appType} expiresAt=${lease.expiresAt}`);
    return;
  }

  if (subcommand === 'end' || subcommand === 'release') {
    const stored = getStoredPublishLease(target);
    const baseline = getStoredChangeBaseline(target, {
      access: 'reconciliation-read',
    });
    if (
      leaseIdFromArgs &&
      stored?.leaseId &&
      leaseIdFromArgs !== stored.leaseId
    ) {
      fail(
        `RELEASE_LEASE_ID_MISMATCH: 显式 leaseId ${leaseIdFromArgs} 与本地冻结 lease ${stored.leaseId} 不一致；未清理任何发布证据`
      );
    }
    const reconciliationOnly = Boolean(
      (baseline && !isChangeBaselineOwnedByCurrentSession(baseline)) ||
      (stored && !isPublishLeaseOwnedByCurrentSession(stored))
    );
    if (reconciliationOnly) {
      if (!baseline?.releaseSourceRevision) {
        fail(
          'RELEASE_SOURCE_LINEAGE_REQUIRED: 外来 release 缺少冻结 source lineage，禁止接管或清理'
        );
      }
      const result = await reconcileInactiveRelease({
        config,
        target,
        stored,
        baseline,
      });
      if (flags.json) return writeJson(result);
      print(
        `过期 release 已完成只读回合清理: ${target.appType} source=${String(result.integration.sourceCommit || '').slice(0, 12)}`
      );
      return;
    }
    if (!leaseIdFromArgs) assertLocalPublishLeaseOwnership(stored);
    const leaseId = leaseIdFromArgs || stored?.leaseId;
    if (!leaseId) {
      const result = await endReleaseWithoutLocalLease(
        config,
        target,
        flags,
        baseline
      );
      if (flags.json) return writeJson(result);
      print(`当前工作区没有活动发布租约: ${target.appType}`);
      return;
    }
    assertOrClaimWorktreeOwner({
      cwd: process.cwd(),
      changeId: stored?.changeId || readStringFlag(flags, 'change') || 'unscoped-publish',
    });
    const integration = assertReleaseSourceIntegrated(
      baseline?.releaseSourceRevision,
      { cwd: process.cwd() }
    );
    try {
      const remoteResult = await requestWithAuth(
        config,
        target.profileName,
        publishLeaseApiPath(target, `/${encodeURIComponent(leaseId)}/release`),
        {
          method: 'POST',
          body: {
            completion: 'mainline-integrated',
            sourceCommit: integration.sourceCommit,
            mainBranch: integration.mainBranch,
            mainTipCommit: integration.mainTipCommit,
          },
        }
      );
      clearPublishLease(target, leaseId);
      clearChangeBaseline(target);
      releaseWorktreeOwner({ cwd: process.cwd() });
      const result = {
        ...(remoteResult && typeof remoteResult === 'object' ? remoteResult : {}),
        integration,
      };
      if (flags.json) return writeJson(result);
      print(
        `应用发布租约已释放，发布提交已进入 ${integration.remoteName}/${integration.mainBranch}: ${target.appType}`
      );
      return;
    } catch (error) {
      if (
        stored?.leaseId === leaseId &&
        ['PUBLISH_LEASE_EXPIRED', 'PUBLISH_LEASE_INVALID'].includes(error?.code)
      ) {
        clearPublishLease(target, leaseId);
        if (baseline) clearChangeBaseline(target, baseline.baselineId || baseline.id);
        releaseWorktreeOwner({ cwd: process.cwd() });
      }
      throw error;
    }
  }

  fail('用法: openxiangda release publish|begin|status|integration-status|renew|end|backend-*|app-* [--change id] [--profile name]');
}

async function task(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda task status --change <id> [--profile name] [--watch] [--interval-seconds 5] [--timeout-seconds 300] [--json]',
      '说明:',
      '  - 聚合 SDD、task result、主线包含关系、本地 execution、远端 lease 和 App Release post-commit。',
      '  - --watch 只轮询只读状态，不会续租、重试或写平台。',
    ].join('\n'));
    return;
  }
  if (subcommand !== 'status') {
    fail('用法: openxiangda task status --change <id> [--profile name] [--watch]');
  }
  const changeId = positional[0] || readStringFlag(flags, 'change');
  if (!changeId) {
    fail('用法: openxiangda task status --change <id> [--profile name]');
  }
  const config = loadConfig();
  const target = getWorkspaceTarget(
    config,
    flags.profile || config.currentProfile,
    flags
  );
  if (flags.watch) {
    return await watchTaskStatus(config, target, changeId, flags);
  }
  const result = await loadTaskStatusSnapshot(
    config,
    target,
    changeId
  );
  if (flags.json) return writeJson(result);
  printTaskStatus(result);
}

async function loadTaskStatusSnapshot(config, target, changeId) {
  let change = null;
  try {
    const scope = getSddChangeScope({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      changeId,
    });
    change = scope.change || null;
  } catch {
    // Missing local SDD is a status fact, not a status-command failure.
  }
  const taskResult = readIntegrationTaskResult(
    process.cwd(),
    changeId
  );
  const execution = readReleaseExecution(changeId);
  const directPublish = readDirectPublishReceipt(changeId);
  const sourceRevision =
    execution?.releaseSourceRevision ||
    execution?.releaseContext?.releaseSourceRevision ||
    directPublish?.sourceRevision ||
    null;
  let integration = taskResult
    ? inspectIntegrationBundleCommits(
        {
          requiredCommits: [
            {
              changeId,
              commit: taskResult.commit,
              treeHash: taskResult.treeHash,
              sourceBranch: taskResult.branch,
            },
          ],
        },
        { cwd: process.cwd() }
      )
    : null;
  let integrationError = null;
  if (!integration && sourceRevision) {
    try {
      integration = inspectReleaseSourceIntegration(sourceRevision, {
        cwd: process.cwd(),
      });
    } catch (error) {
      integrationError = {
        code: error?.code || 'RELEASE_INTEGRATION_STATUS_UNAVAILABLE',
        message: maskText(error?.message || String(error)),
      };
    }
  }
  const localLease = getStoredPublishLease(target);
  const baseline = getStoredChangeBaseline(target, {
    access: 'reconciliation-read',
  });
  const clientSessionId =
    localLease?.clientSessionId ||
    execution?.releaseContext?.clientSessionId ||
    baseline?.clientSessionId ||
    createPublishClientSessionId();
  let remoteLease = null;
  let remoteLeaseError = null;
  try {
    remoteLease = await fetchPublishLeaseStatus(
      config,
      target,
      clientSessionId
    );
  } catch (error) {
    remoteLeaseError = {
      code: error?.code || 'LEASE_STATUS_UNAVAILABLE',
      message: maskText(error?.message || String(error)),
    };
  }
  const appReleaseId = findAppReleaseId(execution?.steps || []);
  let postCommit = null;
  let postCommitError = null;
  if (appReleaseId) {
    try {
      postCommit = await requestWithAuth(
        config,
        target.profileName,
        appReleaseApiPath(
          target,
          `/${encodeURIComponent(appReleaseId)}/post-commit`
        )
      );
    } catch (error) {
      postCommitError = {
        code: error?.code || 'POST_COMMIT_STATUS_UNAVAILABLE',
        message: maskText(error?.message || String(error)),
      };
    }
  }
  return {
    ...buildTaskStatus({
      changeId,
      change,
      taskResult,
      integration,
      execution,
      directPublish,
      sourceRevision,
      remoteLease,
      postCommit,
    }),
    checkedAt: new Date().toISOString(),
    diagnostics: {
      remoteLeaseError,
      postCommitError,
      integrationError,
    },
  };
}

async function watchTaskStatus(config, target, changeId, flags = {}) {
  if (!changeId) {
    fail('task/release status --watch 需要 --change <id>');
  }
  const intervalSeconds = normalizeWatchNumber(
    flags['interval-seconds'],
    5,
    1,
    60,
    '--interval-seconds'
  );
  const timeoutSeconds = normalizeWatchNumber(
    flags['timeout-seconds'],
    300,
    1,
    3600,
    '--timeout-seconds'
  );
  const deadline = Date.now() + timeoutSeconds * 1000;
  let previousFingerprint = '';
  let result;
  for (;;) {
    result = await loadTaskStatusSnapshot(
      config,
      target,
      changeId
    );
    const fingerprint = [
      result.phase,
      result.progress.currentStep,
      result.progress.completed,
      result.release.postCommitStatus,
      result.blocker?.layer,
    ].join(':');
    if (!flags.json && fingerprint !== previousFingerprint) {
      printTaskStatus(result);
    }
    previousFingerprint = fingerprint;
    if (
      ['healthy', 'failed', 'write-review', 'integration-ready'].includes(
        result.phase
      )
    ) {
      break;
    }
    if (Date.now() >= deadline) {
      result.timedOut = true;
      break;
    }
    await sleep(
      Math.min(intervalSeconds * 1000, Math.max(1, deadline - Date.now()))
    );
  }
  if (flags.json) return writeJson(result);
  if (result.timedOut) {
    warn(
      `状态观察已达到 ${timeoutSeconds}s；没有执行任何写入，稍后可继续使用同一命令。`
    );
  }
  return result;
}

function normalizeWatchNumber(value, fallback, minimum, maximum, label) {
  const number =
    value === undefined || value === null || value === ''
      ? fallback
      : Number(value);
  if (
    !Number.isSafeInteger(number) ||
    number < minimum ||
    number > maximum
  ) {
    fail(`${label} 必须是 ${minimum}-${maximum} 之间的整数`);
  }
  return number;
}

function printTaskStatus(result) {
  const eta =
    result.estimatedRemainingMs === null
      ? 'unknown'
      : formatDurationMs(result.estimatedRemainingMs);
  print(
    [
      `task ${result.changeId || '-'}: ${result.phase}`,
      `progress: ${result.progress.completed}/${result.progress.total} current=${result.progress.currentStep || '-'}`,
      `elapsed: ${result.elapsedMs === null ? 'unknown' : formatDurationMs(result.elapsedMs)} eta=${eta}`,
      `platform write: ${result.wrotePlatform ? 'yes' : 'no'} health=${result.healthy ? 'healthy' : 'pending'}`,
      ...(result.blocker
        ? [
            `blocked by: ${result.blocker.layer}${result.blocker.code ? ` (${result.blocker.code})` : ''}`,
          ]
        : []),
      `下一步: ${result.nextAction}`,
    ].join('\n')
  );
}

async function fetchPublishLeaseStatus(config, target, clientSessionId) {
  return await requestWithAuth(
    config,
    target.profileName,
    `${publishLeaseApiPath(target, '/status')}?clientSessionId=${encodeURIComponent(clientSessionId || createPublishClientSessionId())}`
  );
}

async function reconcileInactiveRelease({ config, target, stored, baseline }) {
  const integration = assertReleaseSourceIntegrated(
    baseline.releaseSourceRevision,
    { cwd: process.cwd() }
  );
  const remote = await fetchPublishLeaseStatus(
    config,
    target,
    baseline.clientSessionId
  );
  if (remote?.active !== false) {
    const error = new Error(
      'RELEASE_RECONCILIATION_REMOTE_ACTIVE: 原任务的远端 publish lease 仍为 active；新任务只能查看回合状态，不能续租、写入、释放或覆盖'
    );
    error.code = 'RELEASE_RECONCILIATION_REMOTE_ACTIVE';
    throw error;
  }

  const expectedOwnerThreadId = String(
    baseline.workspace?.threadId || stored?.workspace?.threadId || ''
  ).trim();
  const ownerStatus = getWorktreeOwnerStatus({ cwd: process.cwd() });
  if (
    ownerStatus.owner &&
    (!expectedOwnerThreadId || ownerStatus.owner.threadId !== expectedOwnerThreadId)
  ) {
    fail(
      'RELEASE_RECONCILIATION_OWNER_CHANGED: worktree owner 已不再对应冻结 release；保留发布证据且禁止清理新任务 owner'
    );
  }
  const evidenceCleared = clearChangeBaselineForReconciliation(
    target,
    {
      ...baseline,
      leaseId: stored?.leaseId || null,
    }
  );
  if (!evidenceCleared) {
    fail(
      'RELEASE_RECONCILIATION_STATE_CHANGED: 本地 lease/baseline 与冻结证据不再精确一致；未清理任何发布证据'
    );
  }
  releaseWorktreeOwner({
    cwd: process.cwd(),
    force: true,
    expectedThreadId: expectedOwnerThreadId || undefined,
    expectedChangeId: baseline.changeId || undefined,
    reason: [
      'inactive release reconciliation',
      `baseline=${baseline.baselineId || baseline.id}`,
      `change=${baseline.changeId}`,
      `source=${baseline.releaseSourceRevision.baseCommit}`,
      'remoteLease=inactive',
      'mainline=integrated',
    ].join(' '),
  });
  return {
    active: false,
    appType: target.appType,
    local: false,
    reconciliationOnly: true,
    remote,
    integration,
  };
}

function backendReleaseApiPath(target, suffix = '') {
  return `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/backend-releases${suffix}`;
}

function workflowReleaseApiPath(target, suffix = '') {
  return `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflow-releases${suffix}`;
}

async function runBackendReleaseCommand(
  config,
  target,
  subcommand,
  positional,
  flags = {}
) {
  const releaseId = positional[0] || readStringFlag(flags, 'release-id');
  let data;
  if (subcommand === 'backend-head') {
    data = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(target, '/head')
    );
  } else if (subcommand === 'backend-list') {
    data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(backendReleaseApiPath(target), {
        limit: flags.limit,
      })
    );
  } else if (subcommand === 'backend-detail') {
    if (!releaseId) {
      fail('用法: openxiangda release backend-detail <releaseId> [--profile name]');
    }
    data = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(target, `/${encodeURIComponent(releaseId)}`)
    );
  } else if (subcommand === 'backend-diff') {
    const fromReleaseId = releaseId || readStringFlag(flags, 'from-release-id');
    const toReleaseId = positional[1] || readStringFlag(flags, 'to-release-id');
    if (!fromReleaseId || !toReleaseId) {
      fail('用法: openxiangda release backend-diff <fromReleaseId> <toReleaseId> [--profile name]');
    }
    data = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(
        target,
        `/${encodeURIComponent(fromReleaseId)}/diff/${encodeURIComponent(toReleaseId)}`
      )
    );
  } else if (subcommand === 'backend-abort') {
    if (!releaseId) {
      fail('用法: openxiangda release backend-abort <releaseId> [--reason text] [--profile name]');
    }
    const releaseContext = await ensureBackendReleasePublishContext(
      config,
      target,
      flags,
      'Backend Release abort'
    );
    data = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(
        target,
        `/${encodeURIComponent(releaseId)}/abort`
      ),
      {
        method: 'POST',
        body: stripUndefinedValues({
          ...releaseContext.control,
          reason: readStringFlag(flags, 'reason'),
        }),
      }
    );
  } else if (subcommand === 'backend-retry') {
    if (!releaseId) {
      fail('用法: openxiangda release backend-retry <releaseId> [--profile name]');
    }
    data = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(
        target,
        `/${encodeURIComponent(releaseId)}/post-commit/retry`
      ),
      { method: 'POST', body: {} }
    );
  } else if (subcommand === 'backend-rollback') {
    if (!releaseId) {
      fail('用法: openxiangda release backend-rollback <releaseId> --change <id> --reason "..." [--profile name]');
    }
    const reason = String(readStringFlag(flags, 'reason') || '').trim();
    if (reason.length < 8) {
      fail('backend-rollback 必须提供至少 8 个字符的 --reason');
    }
    const releaseContext = await ensureBackendReleasePublishContext(
      config,
      target,
      flags,
      'Backend Release 回滚'
    );
    const head = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(target, '/head')
    );
    if (!head?.activeBackendReleaseId) {
      fail('当前应用没有 active Backend Release，不能从历史快照准备回滚');
    }
    const prepared = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(target, '/rollback'),
      {
        method: 'POST',
        body: {
          ...releaseContext.control,
          targetReleaseId: releaseId,
          parentReleaseId: head.activeBackendReleaseId,
          reason,
          sourceRepositoryId: releaseContext.sourceRepositoryId,
          sourceRevision: releaseContext.sourceRevision,
        },
      }
    );
    const verified = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(
        target,
        `/${encodeURIComponent(prepared.id)}/verify`
      ),
      {
        method: 'POST',
        body: {
          ...releaseContext.control,
          manifestHash: prepared.manifestHash,
        },
      }
    );
    const activated = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(
        target,
        `/${encodeURIComponent(verified.id || prepared.id)}/activate`
      ),
      { method: 'POST', body: releaseContext.control }
    );
    const automationStates = await fetchActivatedBackendAutomationStates(
      config,
      target,
      activated.resources || []
    );
    saveBackendReleaseResourceStates(target, activated, automationStates);
    data = activated;
  } else {
    fail(`未知 Backend Release 命令: ${subcommand}`);
  }

  if (flags.json) return writeJson(data);
  print(JSON.stringify(data, null, 2));
}

function appReleaseApiPath(target, suffix = '') {
  return `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/app-releases${suffix}`;
}

async function waitForAppReleasePostCommit(
  config,
  target,
  releaseId,
  flags = {}
) {
  const timeoutSeconds = normalizeWatchNumber(
    flags['health-timeout-seconds'] || flags['timeout-seconds'],
    60,
    1,
    900,
    '--health-timeout-seconds'
  );
  const intervalSeconds = normalizeWatchNumber(
    flags['interval-seconds'],
    2,
    1,
    30,
    '--interval-seconds'
  );
  const startedAt = Date.now();
  const deadline = startedAt + timeoutSeconds * 1000;
  let status = null;
  for (;;) {
    status = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(
        target,
        `/${encodeURIComponent(releaseId)}/post-commit`
      )
    );
    if (status?.status === 'completed') {
      return {
        ...status,
        healthy: true,
        waitedMs: Date.now() - startedAt,
      };
    }
    if (Date.now() >= deadline) {
      return {
        ...(status || {}),
        status: status?.status || 'pending_retry',
        healthy: false,
        timedOut: true,
        waitedMs: Date.now() - startedAt,
        message:
          'App Release 已原子激活，提交后动作仍由平台 outbox 自动重试。',
      };
    }
    await sleep(
      Math.min(intervalSeconds * 1000, Math.max(1, deadline - Date.now()))
    );
  }
}

async function fetchAppReleaseCapture(config, target, flags = {}) {
  const capture = await requestWithAuth(
    config,
    target.profileName,
    appReleaseApiPath(target, '/capture')
  );
  if (
    capture?.schemaVersion !== 1 ||
    !Array.isArray(capture?.resources) ||
    !/^[a-f0-9]{64}$/i.test(String(capture?.captureHash || ''))
  ) {
    fail('APP_RELEASE_CAPTURE_INVALID: 平台未返回完整的权威 App Release capture');
  }
  const { captureHash, ...capturePayload } = capture;
  const actualCaptureHash = canonicalJsonSha256(capturePayload);
  if (actualCaptureHash.toLowerCase() !== String(captureHash).toLowerCase()) {
    fail(
      `APP_RELEASE_CAPTURE_HASH_MISMATCH: 平台 capture 内容哈希为 ${actualCaptureHash}，声明为 ${captureHash}`
    );
  }
  const expectedCaptureHash = readStringFlag(flags, 'expected-capture-hash');
  if (
    expectedCaptureHash &&
    expectedCaptureHash.toLowerCase() !== String(capture.captureHash).toLowerCase()
  ) {
    fail(
      `APP_RELEASE_CAPTURE_MOVED: 期望 capture ${expectedCaptureHash}，当前为 ${capture.captureHash}`
    );
  }
  return clonePlainJson(capture);
}

function releaseSessionFile(changeId, deploymentId) {
  const executionFile = releaseExecutionFile(changeId, deploymentId);
  return path.join(path.dirname(executionFile), 'release-session.json');
}

function saveFrozenAppReleaseCapture(
  target,
  changeId,
  baseline,
  lease,
  capture
) {
  const file = releaseSessionFile(changeId, target.deploymentId);
  writePrivateJsonAtomic(file, {
    schemaVersion: 'openxiangda_release_session_v1',
    appType: target.appType,
    profile: target.profileName,
    changeId,
    deploymentId: target.deploymentId || null,
    baselineId: baseline?.baselineId || baseline?.id || null,
    leaseId: lease?.leaseId || lease?.id || null,
    sourceRevision: baseline?.releaseSourceRevision || null,
    capturedAt: new Date().toISOString(),
    capture,
  });
  return path.relative(process.cwd(), file).replace(/\\/g, '/');
}

function readFrozenAppReleaseCapture(target, flags = {}) {
  const changeId = readStringFlag(flags, 'change');
  if (!changeId) return null;
  const file = releaseSessionFile(
    changeId,
    readStringFlag(flags, 'deployment-id') || target.deploymentId
  );
  if (!fs.existsSync(file)) return null;
  let session;
  try {
    session = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (error) {
    fail(`RELEASE_SESSION_INVALID: ${error.message}`);
  }
  if (
    session?.schemaVersion !== 'openxiangda_release_session_v1' ||
    session?.appType !== target.appType ||
    session?.profile !== target.profileName ||
    session?.changeId !== changeId ||
    (session?.deploymentId || null) !==
      (readStringFlag(flags, 'deployment-id') || target.deploymentId || null)
  ) {
    fail(
      'RELEASE_SESSION_CONTEXT_MISMATCH: 冻结的 App capture 与当前 app/profile/change 不一致'
    );
  }
  const capture = session.capture;
  if (
    !capture ||
    !Array.isArray(capture.resources) ||
    !/^[a-f0-9]{64}$/i.test(String(capture.captureHash || ''))
  ) {
    fail('RELEASE_SESSION_CAPTURE_INVALID: 冻结的 App capture 不完整');
  }
  const expectedCaptureHash = readStringFlag(flags, 'expected-capture-hash');
  if (
    expectedCaptureHash &&
    expectedCaptureHash.toLowerCase() !==
      String(capture.captureHash).toLowerCase()
  ) {
    fail(
      `APP_RELEASE_CAPTURE_MOVED: 期望 capture ${expectedCaptureHash}，冻结为 ${capture.captureHash}`
    );
  }
  return clonePlainJson(capture);
}

function appReleaseWriteBody(releaseContext, extra = {}) {
  return {
    ...releaseContext.control,
    sourceRepositoryId: releaseContext.sourceRepositoryId,
    sourceRevision: releaseContext.sourceRevision,
    ...extra,
  };
}

function appReleaseManifestResources(detail) {
  const resources = detail?.manifestJson?.resources;
  if (!Array.isArray(resources)) {
    fail('APP_RELEASE_MANIFEST_INVALID: App Release 详情缺少不可变 resources');
  }
  return clonePlainJson(resources);
}

const APP_RELEASE_IMMUTABLE_RESOURCE_KINDS = new Set([
  'RuntimeRelease',
  'PageRelease',
  'BackendRelease',
  'WorkflowRelease',
  'FormRelease',
]);

function describeAppReleaseResource(resource, index, label) {
  if (!resource || typeof resource !== 'object' || Array.isArray(resource)) {
    fail(`APP_RELEASE_STAGED_RESOURCES_INVALID: ${label}[${index}] 必须是对象`);
  }
  const kind = String(resource.kind || '').trim();
  if (!APP_RELEASE_IMMUTABLE_RESOURCE_KINDS.has(kind)) {
    fail(
      `APP_RELEASE_STAGED_RESOURCE_KIND_UNSUPPORTED: ${label}[${index}].kind 仅支持 RuntimeRelease/PageRelease/BackendRelease/WorkflowRelease/FormRelease`
    );
  }
  const identity =
    resource.identity &&
    typeof resource.identity === 'object' &&
    !Array.isArray(resource.identity)
      ? resource.identity
      : {};
  const releaseId = String(identity.releaseId || resource.releaseId || '').trim();
  const hash = String(resource.hash || resource.resourceHash || '')
    .trim()
    .toLowerCase();
  if (!releaseId) {
    fail(
      `APP_RELEASE_STAGED_RESOURCE_IDENTITY_INVALID: ${label}[${index}] 缺少 identity.releaseId 或 releaseId`
    );
  }
  if (!/^[a-f0-9]{64}$/.test(hash)) {
    fail(
      `APP_RELEASE_STAGED_RESOURCE_HASH_INVALID: ${label}[${index}] 缺少有效的 64 位 hash`
    );
  }
  const formUuid =
    kind === 'FormRelease'
      ? String(identity.formUuid || resource.formUuid || '').trim()
      : null;
  if (kind === 'FormRelease' && !formUuid) {
    fail(
      `APP_RELEASE_STAGED_RESOURCE_IDENTITY_INVALID: ${label}[${index}] 的 FormRelease 缺少 identity.formUuid 或 formUuid`
    );
  }
  return {
    kind,
    releaseId,
    hash,
    formUuid,
    stableKey: kind === 'FormRelease' ? `${kind}:${formUuid}` : kind,
  };
}

function normalizeStagedAppReleaseResources(value) {
  const resources = Array.isArray(value) ? value : value?.resources;
  if (!Array.isArray(resources) || resources.length === 0) {
    fail(
      'APP_RELEASE_STAGED_RESOURCES_INVALID: --staged-resources-json 必须是非空 resource entry 数组或 {"resources": [...]}'
    );
  }
  const stableKeys = new Set();
  return resources.map((resource, index) => {
    const described = describeAppReleaseResource(
      resource,
      index,
      'stagedResources'
    );
    if (stableKeys.has(described.stableKey)) {
      fail(
        `APP_RELEASE_STAGED_RESOURCE_DUPLICATE: stagedResources 重复覆盖 ${described.stableKey}`
      );
    }
    stableKeys.add(described.stableKey);
    const action = String(resource.action || 'upsert').trim().toLowerCase();
    if (!['create', 'update', 'upsert'].includes(action)) {
      fail(
        `APP_RELEASE_STAGED_RESOURCES_INVALID: stagedResources[${index}].action 仅支持 create/update/upsert`
      );
    }
    return stripUndefinedValues({
      kind: described.kind,
      identity:
        described.kind === 'FormRelease'
          ? {
              releaseId: described.releaseId,
              formUuid: described.formUuid,
            }
          : { releaseId: described.releaseId },
      action,
      hash: described.hash,
      revision:
        resource.revision === undefined
          ? undefined
          : clonePlainJson(resource.revision),
      metadata:
        resource.metadata === undefined
          ? undefined
          : clonePlainJson(resource.metadata),
    });
  });
}

function readStagedAppReleaseResources(flags = {}) {
  if (!flags['staged-resources-json']) return null;
  return normalizeStagedAppReleaseResources(
    readJsonArg(flags['staged-resources-json'], 'staged-resources-json')
  );
}

function stagedResourcesFileForChange(changeId, deploymentId) {
  const normalized = String(changeId || '').trim();
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(normalized)) {
    fail('APP_RELEASE_STAGED_RESOURCES_CHANGE_INVALID: 自动聚合 staged resources 需要有效 --change');
  }
  const base = path.join(
    process.cwd(),
    '.openxiangda',
    'releases',
    normalized
  );
  return path.join(
    deploymentId ? path.join(base, String(deploymentId)) : base,
    'staged-resources.json'
  );
}

function backendBindingContractsFileForChange(changeId, deploymentId) {
  return stagedResourcesFileForChange(changeId, deploymentId).replace(
    /staged-resources\.json$/,
    'backend-binding-contracts.json'
  );
}

function writeBackendBindingContracts(
  target,
  changeId,
  backendReleaseId,
  contracts
) {
  const normalized = normalizeBindingContracts(contracts);
  const file = backendBindingContractsFileForChange(
    changeId,
    target.deploymentId
  );
  const payload = {
    contractVersion: 'backend_binding_contracts_v1',
    appType: target.appType,
    profile: target.profileName,
    changeId,
    deploymentId: target.deploymentId || null,
    backendReleaseId,
    contractHash: resourceBindingContractHash(normalized),
    contracts: normalized,
    recordedAt: new Date().toISOString(),
  };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temporary = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(temporary, `${JSON.stringify(payload, null, 2)}\n`, {
    mode: 0o600,
  });
  fs.renameSync(temporary, file);
  return {
    file: path.relative(process.cwd(), file).replace(/\\/g, '/'),
    ...payload,
  };
}

function readBackendBindingContracts(target, flags = {}) {
  const changeId = readStringFlag(flags, 'change');
  if (!changeId) return null;
  const file = backendBindingContractsFileForChange(
    changeId,
    target.deploymentId
  );
  if (!fs.existsSync(file)) return null;
  const payload = JSON.parse(fs.readFileSync(file, 'utf8'));
  for (const [field, expected] of [
    ['contractVersion', 'backend_binding_contracts_v1'],
    ['appType', target.appType],
    ['profile', target.profileName],
    ['changeId', changeId],
    ['deploymentId', target.deploymentId || null],
  ]) {
    if ((payload?.[field] ?? null) !== (expected ?? null)) {
      fail(
        `BACKEND_BINDING_CONTRACT_CONTEXT_MISMATCH: ${field} 不属于当前 app/profile/change/deployment`
      );
    }
  }
  const contracts = normalizeBindingContracts(payload.contracts);
  const contractHash = resourceBindingContractHash(contracts);
  if (payload.contractHash !== contractHash) {
    fail(
      'BACKEND_BINDING_CONTRACT_HASH_MISMATCH: 本地 Backend 资源绑定契约已损坏或被修改'
    );
  }
  return {
    ...payload,
    file: path.relative(process.cwd(), file).replace(/\\/g, '/'),
    contracts,
    contractHash,
  };
}

function stagedResourcesContextFileForChange(changeId, deploymentId) {
  return stagedResourcesFileForChange(changeId, deploymentId).replace(
    /staged-resources\.json$/,
    'staged-resources.context.json'
  );
}

function currentStagedResourcesContext(target, changeId) {
  const baseline = getStoredChangeBaseline(target);
  if (!baseline?.baselineId || baseline.changeId !== changeId) {
    fail(
      `APP_RELEASE_STAGED_CONTEXT_REQUIRED: change ${changeId} 缺少当前发布基线`
    );
  }
  return {
    contractVersion: 'staged_resources_context_v1',
    appType: target.appType,
    profile: target.profileName,
    changeId,
    deploymentId: target.deploymentId || null,
    baselineId: baseline.baselineId,
    clientSessionId: baseline.clientSessionId || null,
  };
}

function writeStagedResourcesFiles(
  changeId,
  resources,
  context,
  deploymentId
) {
  const file = stagedResourcesFileForChange(changeId, deploymentId);
  const contextFile = stagedResourcesContextFileForChange(
    changeId,
    deploymentId
  );
  fs.mkdirSync(path.dirname(file), { recursive: true });
  for (const [targetFile, value] of [
    [file, resources],
    [contextFile, context],
  ]) {
    const temporary = `${targetFile}.${process.pid}.tmp`;
    fs.writeFileSync(temporary, `${JSON.stringify(value, null, 2)}\n`, {
      mode: 0o600,
    });
    fs.renameSync(temporary, targetFile);
  }
  return path.relative(process.cwd(), file).replace(/\\/g, '/');
}

function initializeStagedAppReleaseResources(
  target,
  changeId,
  resources = [],
  metadata = {}
) {
  const context = currentStagedResourcesContext(target, changeId);
  return writeStagedResourcesFiles(
    changeId,
    Array.isArray(resources) && resources.length === 0
      ? []
      : normalizeStagedAppReleaseResources(resources),
    {
      ...context,
      initializedAt: new Date().toISOString(),
      ...metadata,
    },
    target.deploymentId
  );
}

function assertStagedResourcesContext(target, changeId) {
  const expected = currentStagedResourcesContext(target, changeId);
  const contextFile = stagedResourcesContextFileForChange(
    changeId,
    target.deploymentId
  );
  if (!fs.existsSync(contextFile)) {
    if (
      !fs.existsSync(
        stagedResourcesFileForChange(changeId, target.deploymentId)
      )
    ) {
      initializeStagedAppReleaseResources(target, changeId);
    }
  }
  if (!fs.existsSync(contextFile)) {
    fail(
      'APP_RELEASE_STAGED_CONTEXT_REQUIRED: staged resources 缺少当前 release begin 生成的 context；请重新暂存本次 change 的 child releases'
    );
  }
  const actual = JSON.parse(fs.readFileSync(contextFile, 'utf8'));
  for (const field of [
    'contractVersion',
    'appType',
    'profile',
    'changeId',
    'deploymentId',
    'baselineId',
    'clientSessionId',
  ]) {
    if ((actual?.[field] ?? null) !== (expected[field] ?? null)) {
      fail(
        `APP_RELEASE_STAGED_CONTEXT_MISMATCH: ${field} 不属于当前 change/baseline/session，请重新暂存 child releases`
      );
    }
  }
  return actual;
}

function recordStagedAppReleaseResources(
  changeId,
  resources,
  target
) {
  if (!changeId || !Array.isArray(resources) || resources.length === 0) {
    return null;
  }
  const file = stagedResourcesFileForChange(changeId, target.deploymentId);
  const context = assertStagedResourcesContext(target, changeId);
  let existing = [];
  if (fs.existsSync(file)) {
    const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
    existing = Array.isArray(parsed) && parsed.length === 0
      ? []
      : normalizeStagedAppReleaseResources(parsed);
  }
  const incoming = normalizeStagedAppReleaseResources(resources);
  const merged = new Map();
  for (const resource of [...existing, ...incoming]) {
    const described = describeAppReleaseResource(resource, 0, 'stagedResources');
    merged.set(described.stableKey, resource);
  }
  const output = Array.from(merged.values()).sort((left, right) => {
    const leftKey = describeAppReleaseResource(left, 0, 'stagedResources').stableKey;
    const rightKey = describeAppReleaseResource(right, 0, 'stagedResources').stableKey;
    return leftKey.localeCompare(rightKey);
  });
  return writeStagedResourcesFiles(
    changeId,
    output,
    context,
    target.deploymentId
  );
}

async function discardAbortedStagedFormRelease(
  config,
  target,
  changeId,
  formUuid
) {
  if (!changeId) return null;
  const context = assertStagedResourcesContext(target, changeId);
  const file = stagedResourcesFileForChange(changeId, target.deploymentId);
  if (!fs.existsSync(file)) return null;
  const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
  if (!Array.isArray(parsed) || parsed.length === 0) return null;
  const resources = normalizeStagedAppReleaseResources(parsed);
  const staged = resources.find(
    resource =>
      resource.kind === 'FormRelease' &&
      String(resource.identity?.formUuid || '').trim() === formUuid
  );
  if (!staged) return null;
  const releaseId = String(staged.identity?.releaseId || '').trim();
  const detail = await requestOptionalWithAuth(
    config,
    target.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/releases/${encodeURIComponent(releaseId)}`
  );
  const aborted = Boolean(
    detail?.aborted ||
      (Array.isArray(detail?.journal) &&
        detail.journal.some(entry => entry?.action === 'abort'))
  );
  if (!aborted) return null;
  const remaining = resources.filter(resource => resource !== staged);
  writeStagedResourcesFiles(
    changeId,
    remaining,
    {
      ...context,
      lastAbortedFormRecovery: {
        formUuid,
        discardedReleaseId: releaseId,
        recordedAt: new Date().toISOString(),
      },
    },
    target.deploymentId
  );
  return { formUuid, discardedReleaseId: releaseId };
}

function normalizeSatisfiedAppReleaseSelectors(values) {
  return unique(
    (Array.isArray(values) ? values : [])
      .map(value => String(value || '').trim())
      .filter(value => /^form:[A-Za-z0-9][A-Za-z0-9._-]*$/.test(value))
  ).sort();
}

function satisfiedFormCodesFromContext(context) {
  return new Set(
    normalizeSatisfiedAppReleaseSelectors(context?.satisfiedSelectors)
      .filter(selector => selector.startsWith('form:'))
      .map(selector => selector.slice('form:'.length))
  );
}

function recordSatisfiedAppReleaseSelectors(changeId, selectors, target) {
  const incoming = normalizeSatisfiedAppReleaseSelectors(selectors);
  if (!changeId || incoming.length === 0) return [];
  const contextFile = stagedResourcesContextFileForChange(
    changeId,
    target.deploymentId
  );
  const context = assertStagedResourcesContext(target, changeId);
  const satisfiedSelectors = normalizeSatisfiedAppReleaseSelectors([
    ...(context.satisfiedSelectors || []),
    ...incoming,
  ]);
  const temporary = `${contextFile}.${process.pid}.tmp`;
  fs.writeFileSync(
    temporary,
    `${JSON.stringify({ ...context, satisfiedSelectors }, null, 2)}\n`,
    { mode: 0o600 }
  );
  fs.renameSync(temporary, contextFile);
  return satisfiedSelectors;
}

function exactStringSet(left, right) {
  const normalize = values =>
    Array.from(
      new Set((values || []).map(value => String(value || '').trim()).filter(Boolean))
    ).sort();
  const a = normalize(left);
  const b = normalize(right);
  return a.length === b.length && a.every((value, index) => value === b[index]);
}

function stagedFormCode(target, resource) {
  const explicit = String(resource?.metadata?.formCode || '').trim();
  if (explicit) return explicit;
  const formUuid = String(resource?.identity?.formUuid || '').trim();
  for (const bucketName of ['formSettings', 'forms']) {
    for (const [code, entry] of Object.entries(
      target.bound.resources?.[bucketName] || {}
    )) {
      if (String(entry?.formUuid || '').trim() === formUuid) return code;
    }
  }
  return formUuid;
}

function reusableStagedResourcesContext(target, changeId) {
  const normalizedChangeId = String(changeId || '').trim();
  if (!normalizedChangeId) return null;
  const file = stagedResourcesFileForChange(
    normalizedChangeId,
    target.deploymentId
  );
  if (!fs.existsSync(file)) return null;
  const contextFile = stagedResourcesContextFileForChange(
    normalizedChangeId,
    target.deploymentId
  );
  if (!fs.existsSync(contextFile)) {
    fail(
      `FORM_RELEASE_REUSE_CONTEXT_REQUIRED: change ${normalizedChangeId} 的 staged FormRelease 缺少 context，拒绝重挂接`
    );
  }
  const context = JSON.parse(fs.readFileSync(contextFile, 'utf8'));
  const expected = {
    contractVersion: 'staged_resources_context_v1',
    appType: target.appType,
    profile: target.profileName,
    changeId: normalizedChangeId,
    deploymentId: target.deploymentId || null,
  };
  for (const [field, value] of Object.entries(expected)) {
    if ((context?.[field] ?? null) !== (value ?? null)) {
      fail(
        `FORM_RELEASE_REUSE_CONTEXT_MISMATCH: ${field} 不属于当前 app/profile/change/deployment，拒绝重挂接 staged FormRelease`
      );
    }
  }
  return context;
}

function reusableStagedFormReleaseCandidates(target, changeId) {
  const normalizedChangeId = String(changeId || '').trim();
  if (!normalizedChangeId) return [];
  if (!reusableStagedResourcesContext(target, normalizedChangeId)) return [];
  const file = stagedResourcesFileForChange(
    normalizedChangeId,
    target.deploymentId
  );
  const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
  const resources = Array.isArray(parsed) && parsed.length === 0
    ? []
    : normalizeStagedAppReleaseResources(parsed);
  let scopedForms = null;
  try {
    scopedForms = new Set(
      getSddChangeScope({
        cwd: process.cwd(),
        configText: readWorkspaceConfigText(),
        changeId: normalizedChangeId,
      }).targets.forms || []
    );
  } catch (error) {
    // A direct release may use --change without a local SDD record. The
    // exact local context still supplies the app/profile/change scope, while
    // every candidate is independently verified against immutable server data.
    if (!/SDD 未初始化|change 不存在|ENOENT/i.test(String(error?.message || ''))) {
      throw error;
    }
  }
  return resources
    .filter(resource => resource.kind === 'FormRelease')
    .map(resource => {
      const formCode = stagedFormCode(target, resource);
      if (
        scopedForms &&
        (!formCode || !scopedForms.has(formCode))
      ) {
        fail(
          `FORM_RELEASE_REUSE_SCOPE_MISMATCH: ${formCode || resource.identity?.formUuid || '(unknown)'} 不在 change ${normalizedChangeId} 的精确 Form 范围内`
        );
      }
      return { resource, formCode };
    });
}

function nullableReleaseId(value) {
  const normalized = String(value || '').trim();
  return normalized || null;
}

async function verifyReusableStagedFormRelease(
  config,
  target,
  candidate
) {
  const resource = candidate.resource;
  const formCode = String(candidate.formCode || '').trim();
  const releaseId = String(resource.identity?.releaseId || '').trim();
  const formUuid = String(resource.identity?.formUuid || '').trim();
  const boundFormUuid = String(
    target.bound.resources?.forms?.[formCode]?.formUuid ||
      target.bound.resources?.formSettings?.[formCode]?.formUuid ||
      ''
  ).trim();
  if (!formCode || !boundFormUuid || boundFormUuid !== formUuid) {
    fail(
      `FORM_RELEASE_REUSE_BINDING_MISMATCH: ${formCode || formUuid || '(unknown)'} 的本地 binding 与 staged FormRelease identity 不一致`
    );
  }
  const basePath = `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}`;
  const [detail, head] = await Promise.all([
    requestWithAuth(
      config,
      target.profileName,
      `${basePath}/releases/${encodeURIComponent(releaseId)}`
    ),
    requestWithAuth(
      config,
      target.profileName,
      `${basePath}/releases/head`
    ),
  ]);
  if (
    detail?.immutable !== true ||
    detail?.active === true ||
    detail?.aborted === true ||
    (Array.isArray(detail?.journal) ? detail.journal : []).some(
      entry => entry?.action === 'abort'
    )
  ) {
    fail(
      `FORM_RELEASE_REUSE_STATE_INVALID: ${formCode} 的 FormRelease ${releaseId} 必须 immutable=true、active=false、aborted=false`
    );
  }
  if (
    String(detail?.id || '').trim() !== releaseId ||
    String(detail?.formUuid || '').trim() !== formUuid
  ) {
    fail(
      `FORM_RELEASE_REUSE_IDENTITY_MISMATCH: ${formCode} 的 releaseId/formUuid 与服务端冻结证据不一致`
    );
  }
  const contentHash = String(detail?.contentHash || '')
    .trim()
    .toLowerCase();
  if (
    !/^[a-f0-9]{64}$/.test(contentHash) ||
    contentHash !== String(resource.hash || '').trim().toLowerCase()
  ) {
    fail(
      `FORM_RELEASE_REUSE_HASH_MISMATCH: ${formCode} 的 staged hash 与 immutable FormRelease 不一致`
    );
  }
  const parentReleaseId = nullableReleaseId(detail?.parentReleaseId);
  const baseRevision = Number(detail?.baseRevision);
  if (
    nullableReleaseId(resource.revision?.parentReleaseId) !==
      parentReleaseId ||
    Number(resource.revision?.baseRevision) !== baseRevision
  ) {
    fail(
      `FORM_RELEASE_REUSE_REVISION_MISMATCH: ${formCode} 的 staged parent/baseRevision 与 immutable FormRelease 不一致`
    );
  }
  const activeHead = head?.activeFormReleaseHead || {};
  const currentRevision = Number(head?.revision ?? activeHead.revision);
  if (
    nullableReleaseId(activeHead.releaseId) !== parentReleaseId ||
    !Number.isSafeInteger(currentRevision) ||
    currentRevision !== baseRevision
  ) {
    fail(
      `FORM_RELEASE_REUSE_PARENT_CONFLICT: ${formCode} 的 active head/revision 已变化，拒绝重挂接 staged FormRelease`
    );
  }
  if (
    !Array.isArray(detail?.resources) ||
    detail.resources.length === 0 ||
    detail.resources.some(item => !item?.finalizedAt)
  ) {
    fail(
      `FORM_RELEASE_REUSE_RESOURCES_INVALID: ${formCode} 的 FormRelease 资源尚未全部 finalized`
    );
  }
  const frozenForm = detail?.snapshotJson?.form;
  if (!frozenForm || frozenForm.schema === undefined || !frozenForm.formType) {
    fail(
      `FORM_RELEASE_REUSE_SCHEMA_MISSING: ${formCode} 的 FormRelease 缺少冻结 schema/formType`
    );
  }
  let frozenSchema = frozenForm.schema;
  if (typeof frozenSchema === 'string') {
    try {
      frozenSchema = JSON.parse(frozenSchema);
    } catch {
      fail(
        `FORM_RELEASE_REUSE_SCHEMA_INVALID: ${formCode} 的 FormRelease 冻结 schema 不是合法 JSON`
      );
    }
  }
  if (!frozenSchema || typeof frozenSchema !== 'object') {
    fail(
      `FORM_RELEASE_REUSE_SCHEMA_INVALID: ${formCode} 的 FormRelease 冻结 schema 无效`
    );
  }
  return {
    resource: {
      kind: 'FormRelease',
      identity: { releaseId, formUuid },
      action: resource.action || 'update',
      hash: contentHash,
      revision: { parentReleaseId, baseRevision },
      metadata: {
        ...(resource.metadata || {}),
        formCode,
        releaseStatus: 'staged',
      },
    },
    formCode,
    formUuid,
    releaseId,
    contentHash,
    baseRevision,
    parentReleaseId,
    formSnapshot: {
      ...clonePlainJson(frozenForm),
      schema: clonePlainJson(frozenSchema),
    },
    formType: frozenForm.formType,
  };
}

async function resolveReusableStagedFormReleaseOverlays(
  config,
  target,
  changeId,
  options = {}
) {
  const requested = new Set(
    (options.formCodes || [])
      .map(value => String(value || '').trim())
      .filter(Boolean)
  );
  const candidates = reusableStagedFormReleaseCandidates(target, changeId)
    .filter(candidate => requested.size === 0 || requested.has(candidate.formCode));
  const verified = [];
  for (const candidate of candidates) {
    verified.push(
      await verifyReusableStagedFormRelease(config, target, candidate)
    );
  }
  return new Map(verified.map(item => [item.formCode, item]));
}

async function initializeNewReleaseStagedResources(
  config,
  target,
  changeId,
  candidates
) {
  const verified = [];
  for (const candidate of candidates || []) {
    verified.push(
      await verifyReusableStagedFormRelease(config, target, candidate)
    );
  }
  const reused = verified.map(item => ({
    formCode: item.formCode,
    formUuid: item.formUuid,
    releaseId: item.releaseId,
    contentHash: item.contentHash,
    baseRevision: item.baseRevision,
    parentReleaseId: item.parentReleaseId,
  }));
  const file = initializeStagedAppReleaseResources(
    target,
    changeId,
    verified.map(item => item.resource),
    reused.length > 0
      ? {
          reusedStagedFormReleases: reused,
          reusedAt: new Date().toISOString(),
        }
      : {}
  );
  return { file, reused };
}

function assertStagedAppReleaseScope(target, flags, resources) {
  const changeId = readStringFlag(flags, 'change');
  if (!changeId) {
    fail(
      'APP_RELEASE_STAGED_SCOPE_REQUIRED: staged child activation 必须显式提供 --change'
    );
  }
  const stagedContext = assertStagedResourcesContext(target, changeId);
  let scope;
  if (activeDeliveryV2Context?.changeId === changeId) {
    scope = {
      changeId,
      targets: activeDeliveryV2Context.targets || {},
      changedFiles: [],
      deliveryRunId: activeDeliveryV2Context.runId,
    };
  } else {
    try {
      scope = getSddChangeScope({
        cwd: process.cwd(),
        configText: readWorkspaceConfigText(),
        changeId,
      });
    } catch (error) {
      if (
        /SDD 未初始化|change 不存在|ENOENT/i.test(
          String(error?.message || '')
        )
      ) {
        return {
          changeId,
          scope: null,
          resources: normalizeStagedAppReleaseResources(resources),
          compatibility: 'unmanaged_sdd_scope',
        };
      }
      throw error;
    }
  }
  const runtimeMode = getWorkspaceRuntimeModeFromConfig(
    readWorkspaceConfigText()
  );
  const { activationTargets: targets } = normalizeReleaseTargets(
    scope.targets || {},
    runtimeMode
  );
  const normalized = normalizeStagedAppReleaseResources(resources);
  const byKind = kind => normalized.filter(resource => resource.kind === kind);
  const expectedBackendSelectors = [
    ...(targets.functions || []).map(code => `function:${code}`),
    ...(targets.automations || []).map(code => `automation:${code}`),
  ].sort();
  const backend = byKind('BackendRelease');
  if (expectedBackendSelectors.length > 0) {
    if (
      backend.length !== 1 ||
      !exactStringSet(
        backend[0]?.metadata?.handledSelectors,
        expectedBackendSelectors
      )
    ) {
      fail(
        `APP_RELEASE_STAGED_SCOPE_MISMATCH: Backend handledSelectors 必须精确为 ${expectedBackendSelectors.join(',')}`
      );
    }
  } else if (backend.length > 0) {
    fail('APP_RELEASE_STAGED_SCOPE_MISMATCH: SDD 未授权 BackendRelease child');
  }

  const expectedForms = (targets.forms || []).map(String).sort();
  const satisfiedForms = normalizeSatisfiedAppReleaseSelectors(
    stagedContext?.satisfiedSelectors
  )
    .filter(selector => selector.startsWith('form:'))
    .map(selector => selector.slice('form:'.length));
  const actualForms = unique([
    ...byKind('FormRelease').map(resource => stagedFormCode(target, resource)),
    ...satisfiedForms,
  ]).sort();
  if (!exactStringSet(actualForms, expectedForms)) {
    fail(
      `APP_RELEASE_STAGED_SCOPE_MISMATCH: FormRelease 必须精确覆盖 ${expectedForms.join(',') || '(none)'}`
    );
  }

  const expectedWorkflowSelectors = (targets.workflows || [])
    .map(code => `workflow:${code}`)
    .sort();
  const workflows = byKind('WorkflowRelease');
  if (expectedWorkflowSelectors.length > 0) {
    if (
      workflows.length !== 1 ||
      !exactStringSet(
        workflows[0]?.metadata?.handledSelectors,
        expectedWorkflowSelectors
      )
    ) {
      fail(
        `APP_RELEASE_STAGED_SCOPE_MISMATCH: Workflow handledSelectors 必须精确为 ${expectedWorkflowSelectors.join(',')}`
      );
    }
  } else if (workflows.length > 0) {
    fail('APP_RELEASE_STAGED_SCOPE_MISMATCH: SDD 未授权 WorkflowRelease child');
  }

  const runtimeCount = byKind('RuntimeRelease').length;
  if (runtimeCount !== (targets.runtime ? 1 : 0)) {
    fail(
      `APP_RELEASE_STAGED_SCOPE_MISMATCH: RuntimeRelease 期望 ${targets.runtime ? 1 : 0} 个，实际 ${runtimeCount} 个`
    );
  }
  const pageCount = byKind('PageRelease').length;
  const expectsPageRelease = (targets.pages || []).length > 0;
  if (pageCount !== (expectsPageRelease ? 1 : 0)) {
    fail(
      `APP_RELEASE_STAGED_SCOPE_MISMATCH: PageRelease 期望 ${expectsPageRelease ? 1 : 0} 个，实际 ${pageCount} 个`
    );
  }
  return { changeId, scope, resources: normalized };
}

function changedAppReleaseResources(detailResources, captureResources) {
  const captured = new Map(
    (captureResources || []).map((resource, index) => {
      const described = describeAppReleaseResource(
        resource,
        index,
        'capture.resources'
      );
      return [described.stableKey, described];
    })
  );
  return (detailResources || []).filter((resource, index) => {
    const described = describeAppReleaseResource(
      resource,
      index,
      'release.resources'
    );
    const active = captured.get(described.stableKey);
    return (
      !active ||
      active.releaseId !== described.releaseId ||
      active.hash !== described.hash
    );
  });
}

function assertAppReleaseActualGate(target, flags, scope, command) {
  const runtimeMode = getWorkspaceRuntimeModeFromConfig(
    readWorkspaceConfigText()
  );
  const normalized = normalizeReleaseTargets(
    scope.targets || {},
    runtimeMode
  );
  assertSddReleaseGate(
    buildExplicitSddReleasePlan(normalized.activationTargets, {
      files: scope.changedFiles || [],
      commands: [command],
      changeId: scope.changeId,
      actualCommands: true,
    }),
    flags,
    command
  );
}

function stagedAppReleaseProtocolVersion(stagedResources) {
  const hasBackendReleaseV2 = (stagedResources || []).some(
    resource =>
      resource.kind === 'BackendRelease' &&
      String(
        resource.metadata?.protocolVersion ||
          resource.revision?.protocolVersion ||
          ''
      ) === APP_FUNCTION_SECRET_CAPABILITIES.backendRelease
  );
  const hasWorkflowRelease = (stagedResources || []).some(
    resource => resource.kind === 'WorkflowRelease'
  );
  return hasBackendReleaseV2 || hasWorkflowRelease
    ? APP_FUNCTION_SECRET_CAPABILITIES.atomicActivation
    : null;
}

function overlayAppReleaseResources(capturedResources, stagedResources) {
  if (!Array.isArray(capturedResources)) {
    fail('APP_RELEASE_CAPTURE_INVALID: capture.resources 必须是数组');
  }
  if (!stagedResources) return clonePlainJson(capturedResources);

  const stagedByKey = new Map(
    stagedResources.map((resource, index) => {
      const described = describeAppReleaseResource(
        resource,
        index,
        'stagedResources'
      );
      return [described.stableKey, resource];
    })
  );
  const capturedKeys = new Set();
  const merged = capturedResources.map((resource, index) => {
    const described = describeAppReleaseResource(
      resource,
      index,
      'capture.resources'
    );
    if (capturedKeys.has(described.stableKey)) {
      fail(
        `APP_RELEASE_CAPTURE_INVALID: capture.resources 重复身份 ${described.stableKey}`
      );
    }
    capturedKeys.add(described.stableKey);
    const staged = stagedByKey.get(described.stableKey);
    if (!staged) return clonePlainJson(resource);
    const stagedDescription = describeAppReleaseResource(
      staged,
      index,
      'stagedResources'
    );
    if (
      stagedDescription.releaseId === described.releaseId &&
      stagedDescription.hash === described.hash
    ) {
      fail(
        `APP_RELEASE_STAGED_RESOURCE_NOT_CHANGED: ${described.stableKey} 仍指向 capture 中相同的 immutable release`
      );
    }
    stagedByKey.delete(described.stableKey);
    return clonePlainJson(staged);
  });
  for (const [stableKey, resource] of Array.from(stagedByKey.entries()).sort(
    ([left], [right]) => left.localeCompare(right)
  )) {
    void stableKey;
    merged.push(clonePlainJson(resource));
  }
  return merged;
}

async function prepareAppReleaseFromCapture(
  config,
  target,
  releaseContext,
  capture,
  flags = {}
) {
  const expectedManifestHash = readStringFlag(flags, 'expected-manifest-hash');
  return await requestWithAuth(
    config,
    target.profileName,
    appReleaseApiPath(target),
    {
      method: 'POST',
      body: appReleaseWriteBody(releaseContext, {
        ...(flags.__appReleaseProtocolVersion
          ? { protocolVersion: flags.__appReleaseProtocolVersion }
          : {}),
        parentReleaseId: capture.parentReleaseId || null,
        resources: clonePlainJson(capture.resources),
        ...(expectedManifestHash ? { expectedManifestHash } : {}),
      }),
    }
  );
}

async function verifyAppReleaseDetail(
  config,
  target,
  releaseContext,
  detail,
  resources,
  options = {}
) {
  if (!detail?.id || !/^[a-f0-9]{64}$/i.test(String(detail.manifestHash || ''))) {
    fail('APP_RELEASE_MANIFEST_INVALID: App Release 缺少 id 或 manifestHash');
  }
  return await requestWithAuth(
    config,
    target.profileName,
    appReleaseApiPath(
      target,
      `/${encodeURIComponent(detail.id)}/verify`
    ),
    {
      method: 'POST',
      body: appReleaseWriteBody(releaseContext, {
        ...(options.protocolVersion
          ? { protocolVersion: options.protocolVersion }
          : {}),
        manifestHash: detail.manifestHash,
        resources: clonePlainJson(resources),
      }),
    }
  );
}

async function activateAppReleaseDetail(
  config,
  target,
  releaseContext,
  releaseId,
  options = {}
) {
  const body = stripUndefinedValues({
    ...(options.activateStagedChildren === true
      ? { activateStagedChildren: true }
      : {}),
    ...(options.breakGlassAdoptVerifiedRoot === true
      ? {
          breakGlassAdoptVerifiedRoot: true,
          breakGlassReason: options.breakGlassReason,
        }
      : {}),
    ...(options.forceActivateWithoutValidation === true
      ? { forceActivateWithoutValidation: true }
      : {}),
    protocolVersion: options.protocolVersion,
    ...(options.environmentControl || {}),
  });
  return await requestWithAuth(
    config,
    target.profileName,
    appReleaseApiPath(
      target,
      `/${encodeURIComponent(releaseId)}/activate`
    ),
    {
      method: 'POST',
      body:
        options.forceActivateWithoutValidation === true
          ? body
          : appReleaseWriteBody(releaseContext, body),
    }
  );
}

function appReleaseEnvironmentControl(flags = {}) {
  return stripUndefinedValues({
    environmentId: readStringFlag(flags, 'environment-id') || undefined,
    candidateId: readStringFlag(flags, 'candidate-id') || undefined,
    deploymentId: readStringFlag(flags, 'deployment-id') || undefined,
    deliveryRunId: readStringFlag(flags, 'delivery-run-id') || undefined,
  });
}

function summarizeAppReleaseHead(data) {
  const value =
    data && typeof data === 'object' && !Array.isArray(data) ? data : {};
  const release =
    value.release &&
    typeof value.release === 'object' &&
    !Array.isArray(value.release)
      ? value.release
      : {};
  const manifest =
    release.manifestJson &&
    typeof release.manifestJson === 'object'
      ? release.manifestJson
      : value.manifestJson &&
          typeof value.manifestJson === 'object'
        ? value.manifestJson
        : {};
  const resources = Array.isArray(manifest.resources)
    ? manifest.resources
    : Array.isArray(value.resources)
      ? value.resources
      : [];
  const resourcesByKind = Object.fromEntries(
    Array.from(
      resources.reduce((counts, resource) => {
        const kind = String(resource?.kind || 'Unknown');
        counts.set(kind, (counts.get(kind) || 0) + 1);
        return counts;
      }, new Map())
    ).sort(([left], [right]) => left.localeCompare(right))
  );
  const compactRelease = {};
  for (const key of [
    'id',
    'status',
    'parentReleaseId',
    'manifestHash',
    'verificationHash',
    'protocolVersion',
    'createdAt',
    'updatedAt',
    'activatedAt',
  ]) {
    if (release[key] !== undefined) compactRelease[key] = release[key];
  }
  return {
    appType: value.appType,
    activeAppReleaseId:
      value.activeAppReleaseId || release.id || null,
    ...(value.activeRuntimeReleaseId
      ? { activeRuntimeReleaseId: value.activeRuntimeReleaseId }
      : {}),
    ...(value.activePageReleaseId
      ? { activePageReleaseId: value.activePageReleaseId }
      : {}),
    ...(value.activeBackendReleaseId
      ? { activeBackendReleaseId: value.activeBackendReleaseId }
      : {}),
    release: compactRelease,
    resourceCount: resources.length,
    resourcesByKind,
  };
}

async function runAppReleaseCommand(
  config,
  target,
  subcommand,
  positional,
  flags = {}
) {
  const releaseId = positional[0] || readStringFlag(flags, 'release-id');
  let data;
  if (subcommand === 'app-capture') {
    data = await fetchAppReleaseCapture(config, target, flags);
  } else if (subcommand === 'app-head') {
    data = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(target, '/head')
    );
    if (!flags.full) data = summarizeAppReleaseHead(data);
  } else if (subcommand === 'app-list') {
    data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(appReleaseApiPath(target), { limit: flags.limit })
    );
  } else if (subcommand === 'app-detail') {
    if (!releaseId) {
      fail('用法: openxiangda release app-detail <releaseId> [--profile name]');
    }
    data = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(target, `/${encodeURIComponent(releaseId)}`)
    );
  } else if (subcommand === 'app-post-commit') {
    if (!releaseId) {
      fail(
        '用法: openxiangda release app-post-commit <releaseId> [--profile name]'
      );
    }
    data = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(
        target,
        `/${encodeURIComponent(releaseId)}/post-commit`
      )
    );
  } else if (subcommand === 'app-retry') {
    if (!releaseId) {
      fail('用法: openxiangda release app-retry <releaseId> [--profile name]');
    }
    data = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(
        target,
        `/${encodeURIComponent(releaseId)}/post-commit/retry`
      ),
      { method: 'POST', body: {} }
    );
  } else if (subcommand === 'app-diff') {
    const fromReleaseId = releaseId || readStringFlag(flags, 'from-release-id');
    const toReleaseId = positional[1] || readStringFlag(flags, 'to-release-id');
    if (!fromReleaseId || !toReleaseId) {
      fail('用法: openxiangda release app-diff <fromReleaseId> <toReleaseId>');
    }
    data = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(
        target,
        `/${encodeURIComponent(fromReleaseId)}/diff/${encodeURIComponent(toReleaseId)}`
      )
    );
  } else if (subcommand === 'app-prepare') {
    const stagedResources = readStagedAppReleaseResources(flags);
    if (stagedResources) {
      assertStagedAppReleaseScope(target, flags, stagedResources);
    }
    const protocolVersion = stagedAppReleaseProtocolVersion(stagedResources);
    if (protocolVersion) {
      assertAppFunctionSecretCapabilities(
        await fetchAppFunctionSecretCapabilities(config, target)
      );
    }
    const releaseContext = await ensureAppReleasePublishContext(
      config,
      target,
      flags,
      'App Release prepare'
    );
    const capture = await fetchAppReleaseCapture(config, target, flags);
    const resources = overlayAppReleaseResources(
      capture.resources,
      stagedResources
    );
    data = await prepareAppReleaseFromCapture(
      config,
      target,
      releaseContext,
      { ...capture, resources },
      {
        ...flags,
        __appReleaseProtocolVersion: protocolVersion,
      }
    );
  } else if (subcommand === 'app-verify') {
    if (!releaseId) {
      fail('用法: openxiangda release app-verify <releaseId> --change <id>');
    }
    const detail = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(target, `/${encodeURIComponent(releaseId)}`)
    );
    const detailResources = appReleaseManifestResources(detail);
    const capture = await fetchAppReleaseCapture(config, target, flags);
    const changedResources = changedAppReleaseResources(
      detailResources,
      capture.resources
    );
    if (changedResources.length > 0) {
      assertStagedAppReleaseScope(target, flags, changedResources);
    }
    const protocolVersion = String(detail?.protocolVersion || '');
    if (protocolVersion === APP_FUNCTION_SECRET_CAPABILITIES.atomicActivation) {
      assertAppFunctionSecretCapabilities(
        await fetchAppFunctionSecretCapabilities(config, target)
      );
    }
    const releaseContext = await ensureAppReleasePublishContext(
      config,
      target,
      flags,
      'App Release verify'
    );
    data = await verifyAppReleaseDetail(
      config,
      target,
      releaseContext,
      detail,
      detailResources,
      { protocolVersion: protocolVersion || undefined }
    );
  } else if (subcommand === 'app-activate') {
    if (!releaseId) {
      fail(
        '用法: openxiangda release app-activate <releaseId> [--change <id> | --force-activate-without-validation]'
      );
    }
    const forceActivateWithoutValidation =
      flags['force-activate-without-validation'] === true ||
      String(flags['force-activate-without-validation'] || '').toLowerCase() ===
        'true';
    if (forceActivateWithoutValidation) {
      data = await activateAppReleaseDetail(
        config,
        target,
        null,
        releaseId,
        {
          activateStagedChildren: true,
          forceActivateWithoutValidation: true,
        }
      );
    } else {
    const breakGlassAdoptVerifiedRoot =
      flags['break-glass-adopt-verified-root'] === true ||
      String(flags['break-glass-adopt-verified-root'] || '').toLowerCase() ===
        'true';
    const breakGlassReason =
      readStringFlag(flags, 'reason') ||
      readStringFlag(flags, 'break-glass-reason');
    if (breakGlassAdoptVerifiedRoot && breakGlassReason.length < 12) {
      fail(
        'BREAK_GLASS_REASON_REQUIRED: --break-glass-adopt-verified-root 必须提供至少 12 个字符的 --reason'
      );
    }
    const detail = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(target, `/${encodeURIComponent(releaseId)}`)
    );
    const protocolVersion = String(detail?.protocolVersion || '');
    const atomicV2 =
      protocolVersion === APP_FUNCTION_SECRET_CAPABILITIES.atomicActivation;
    const activatesStagedChildren =
      atomicV2 ||
      flags['activate-staged-children'] === true ||
      String(flags['activate-staged-children'] || '').toLowerCase() === 'true';
    if (activatesStagedChildren && !breakGlassAdoptVerifiedRoot) {
      const capture = await fetchAppReleaseCapture(config, target, flags);
      const changedResources = changedAppReleaseResources(
        appReleaseManifestResources(detail),
        capture.resources
      );
      assertStagedAppReleaseScope(target, flags, changedResources);
    }
    if (atomicV2) {
      assertAppFunctionSecretCapabilities(
        await fetchAppFunctionSecretCapabilities(config, target)
      );
    }
    const releaseContext = await ensureAppReleasePublishContext(
      config,
      target,
      flags,
      'App Release activate'
    );
    data = await activateAppReleaseDetail(
      config,
      target,
      releaseContext,
      releaseId,
      {
        activateStagedChildren: activatesStagedChildren,
        breakGlassAdoptVerifiedRoot,
        breakGlassReason,
        protocolVersion: protocolVersion || undefined,
        environmentControl: appReleaseEnvironmentControl(flags),
      }
    );
    }
  } else if (subcommand === 'app-finalize') {
    const stagedResources = readStagedAppReleaseResources(flags);
    let stagedScope = null;
    if (stagedResources) {
      stagedScope = assertStagedAppReleaseScope(
        target,
        flags,
        stagedResources
      );
      if (stagedScope.scope) {
        assertAppReleaseActualGate(
          target,
          flags,
          stagedScope.scope,
          `openxiangda release app-finalize --staged-resources-json ${String(
            flags['staged-resources-json']
          )} --profile ${target.profileName} --change ${stagedScope.changeId}`
        );
      }
    }
    const protocolVersion = stagedAppReleaseProtocolVersion(stagedResources);
    if (protocolVersion) {
      assertAppFunctionSecretCapabilities(
        await fetchAppFunctionSecretCapabilities(config, target)
      );
    }
    const releaseContext = await ensureAppReleasePublishContext(
      config,
      target,
      flags,
      'App Release finalize'
    );
    const capture =
      readFrozenAppReleaseCapture(target, flags) ||
      (await fetchAppReleaseCapture(config, target, flags));
    const frozenResources = overlayAppReleaseResources(
      capture.resources,
      stagedResources
    );
    const payloadHash = canonicalJsonSha256({
      parentReleaseId: capture.parentReleaseId || null,
      sourceRepositoryId: releaseContext.sourceRepositoryId,
      sourceRevision: releaseContext.sourceRevision,
      resources: frozenResources,
      ...(protocolVersion ? { protocolVersion } : {}),
    });
    const prepared = await prepareAppReleaseFromCapture(
      config,
      target,
      releaseContext,
      { ...capture, resources: frozenResources },
      {
        ...flags,
        __appReleaseProtocolVersion: protocolVersion,
      }
    );
    const verified = await verifyAppReleaseDetail(
      config,
      target,
      releaseContext,
      prepared,
      frozenResources,
      { protocolVersion }
    );
    const activated = await activateAppReleaseDetail(
      config,
      target,
      releaseContext,
      verified?.id || prepared.id,
      {
        activateStagedChildren: Boolean(stagedResources),
        protocolVersion,
        environmentControl: appReleaseEnvironmentControl(flags),
      }
    );
    const finalizedDataViews = await finalizeDeferredDataViewResources(
      config,
      target,
      readCommaSeparatedFlag(flags, 'finalize-data-views')
    );
    const bindingVerification =
      await verifyFinalizedBackendBindingContracts(
        config,
        target,
        flags,
        stagedResources
      );
    const healthWait = flags.wait
      ? await waitForAppReleasePostCommit(
          config,
          target,
          activated?.id || verified?.id || prepared.id,
          flags
        )
      : null;
    let stateReconcileWarning = null;
    try {
      const appHead = await loadRuntimeHeadApp(config, target);
      const stagedRuntime = stagedResources?.find(
        resource => resource.kind === 'RuntimeRelease'
      );
      saveRuntimeHeadState(target, appHead, {
        id:
          stagedRuntime?.identity?.releaseId ||
          stagedRuntime?.releaseId ||
          null,
        buildId: stagedRuntime?.metadata?.buildId || null,
        assetBaseUrl: stagedRuntime?.metadata?.assetBaseUrl || null,
      });
    } catch (error) {
      stateReconcileWarning = {
        component: 'RuntimeStateReadback',
        message: error?.message || String(error),
      };
    }
    data = {
      activationModel: stagedResources
        ? protocolVersion || 'atomic_staged_children_v1'
        : 'retrospective_active_children',
      captureHash: capture.captureHash,
      payloadHash,
      prepared,
      verified,
      activated,
      ...(finalizedDataViews
        ? { finalizedDataViews }
        : {}),
      ...(bindingVerification ? { bindingVerification } : {}),
      ...(healthWait ? { healthWait } : {}),
      ...(stateReconcileWarning ? { stateReconcileWarning } : {}),
    };
  } else if (subcommand === 'app-rollback') {
    if (!releaseId) {
      fail('用法: openxiangda release app-rollback <releaseId> --change <id> --reason "..."');
    }
    const reason = readStringFlag(flags, 'reason');
    if (reason.length < 8) {
      fail('app-rollback 必须提供至少 8 个字符的 --reason');
    }
    const releaseContext = await ensureAppReleasePublishContext(
      config,
      target,
      flags,
      'App Release rollback'
    );
    const head = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(target, '/head')
    );
    if (!head?.activeAppReleaseId) {
      fail('当前应用没有 active App Release，不能准备历史回滚');
    }
    const prepared = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(target, '/rollback'),
      {
        method: 'POST',
        body: appReleaseWriteBody(releaseContext, {
          targetReleaseId: releaseId,
          parentReleaseId: head.activeAppReleaseId,
          reason,
        }),
      }
    );
    data = {
      prepared,
      nextStep:
        '先按 prepared manifest 回滚并激活各不可变子 Release，再执行 app-verify 与 app-activate。',
    };
  } else if (subcommand === 'app-abort') {
    if (!releaseId) {
      fail('用法: openxiangda release app-abort <releaseId> --reason "..."');
    }
    const reason = readStringFlag(flags, 'reason');
    if (!reason) fail('app-abort 必须提供 --reason');
    const releaseContext = await ensureAppReleasePublishContext(
      config,
      target,
      flags,
      'App Release abort'
    );
    data = await requestWithAuth(
      config,
      target.profileName,
      appReleaseApiPath(
        target,
        `/${encodeURIComponent(releaseId)}/abort`
      ),
      {
        method: 'POST',
        body: appReleaseWriteBody(releaseContext, { reason }),
      }
    );
  } else {
    fail(`未知 App Release 命令: ${subcommand}`);
  }

  if (flags.json) return writeJson(data);
  print(JSON.stringify(data, null, 2));
}

function changeBaselineApiPath(target, suffix = '') {
  return `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/change-baselines${suffix}`;
}

function resolveChangeSourceBase(changeId, flags = {}) {
  const explicitBaseRef =
    readStringFlag(flags, 'source-base-ref') || readStringFlag(flags, 'since');
  if (!explicitBaseRef && changeId) {
    try {
      const scope = getSddChangeScope({ cwd: process.cwd(), changeId });
      const recorded =
        scope?.change?.sourceBase ||
        scope?.release?.sourceBase;
      if (recorded?.baseCommit && recorded?.treeHash) return recorded;
      const recordedBaseRevision =
        scope?.change?.baseRevision ||
        scope?.release?.baseRevision;
      if (recordedBaseRevision) {
        return readGitSourceBase(process.cwd(), recordedBaseRevision);
      }
      if (scope?.change?.changeMode === 'mainline-bundle') {
        const error = new Error(
          `SDD_SOURCE_BASE_REQUIRED: mainline bundle ${changeId} 缺少 sourceBase/baseRevision，禁止退化为当前 HEAD`
        );
        error.code = 'SDD_SOURCE_BASE_REQUIRED';
        throw error;
      }
    } catch (error) {
      if (error?.code === 'SDD_SOURCE_BASE_REQUIRED') throw error;
      // A direct release may use --change without a local SDD record. In that
      // case the current Git HEAD is still a deterministic, auditable base.
    }
  }
  return readGitSourceBase(process.cwd(), explicitBaseRef || 'HEAD');
}

async function ensureChangeBaseline(
  config,
  target,
  changeId,
  flags = {},
  clientSessionId
) {
  if (!changeId) return null;
  const candidate =
    flags['sealed-candidate-source'] === true
      ? readReleaseCandidate(readStringFlag(flags, 'candidate-id'))
      : null;
  const sessionId =
    clientSessionId ||
    readStringFlag(flags, 'client-session-id') ||
    createPublishClientSessionId();
  const stored = getStoredChangeBaseline(target);
  if (stored && !isChangeBaselineOwnedByCurrentSession(stored)) {
    fail(
      `当前工作区的变更基线由另一个任务持有 (${stored.workspace?.threadId || stored.clientSessionId || 'another-session'})`
    );
  }
  if (stored) {
    if (!stored.releaseSourceRevision) {
      fail(
        'RELEASE_SOURCE_LINEAGE_REQUIRED: 已存在的发布基线缺少 releaseSourceRevision，禁止覆盖；请先人工核对线上状态'
      );
    }
    if (stored.changeId !== changeId) {
      fail(
        `RELEASE_RECONCILIATION_REQUIRED: change ${stored.changeId || '-'} 的发布提交仍待回合主分支，不能被 ${changeId} 覆盖；请先 merge/push 并执行 release end`
      );
    }
    if (stored.clientSessionId && stored.clientSessionId !== sessionId) {
      fail(
        `RELEASE_RECONCILIATION_REQUIRED: change ${changeId} 必须复用已冻结的 clientSessionId，禁止创建新会话覆盖发布义务`
      );
    }
    if (
      candidate &&
      String(stored.candidateId || '') !== candidate.id
    ) {
      fail(
        'RELEASE_RECONCILIATION_REQUIRED: 当前发布基线与 candidate 不一致，禁止复用'
      );
    }
    assertStoredReleaseSourceStable(stored);
    return stored;
  }
  const activeLease = getUsableStoredPublishLease(target);
  const releaseSourceRevision = normalizeManagedReleaseSourceRevision(
    target,
    candidate?.sourceRevision ||
      prepareReleaseSourceRevision({
        cwd: process.cwd(),
      }),
    { errorCode: 'RELEASE_SOURCE_REPOSITORY_MISMATCH' }
  );
  const sourceBase = normalizeManagedChangeSourceBase(
    target,
    resolveChangeSourceBase(changeId, flags),
    releaseSourceRevision
  );

  const data = await requestWithAuth(
    config,
    target.profileName,
    changeBaselineApiPath(target),
    {
      method: 'POST',
      body: {
        changeId,
        clientSessionId: sessionId,
        sourceBase: {
          repo: sourceBase.repo,
          baseCommit: sourceBase.baseCommit,
          treeHash: sourceBase.treeHash,
        },
      },
    }
  );
  const baseline = saveChangeBaseline(target, {
    ...data,
    changeId,
    clientSessionId: sessionId,
    sourceBase,
    releaseSourceRevision,
    ...(candidate ? { candidateId: candidate.id } : {}),
    lifecycleState: activeLease ? 'active' : 'pending-lease',
  });
  Object.defineProperty(baseline, '__createdForAcquire', {
    value: true,
    configurable: true,
    enumerable: false,
  });
  return baseline;
}

function finalizeReleaseBaseline(target, baseline) {
  if (!baseline?.releaseSourceRevision) {
    fail('RELEASE_SOURCE_LINEAGE_REQUIRED: 无法激活缺少 releaseSourceRevision 的发布基线');
  }
  const finalized = saveChangeBaseline(target, {
    ...baseline,
    lifecycleState: 'active',
  });
  try {
    recordSddReleaseSourceRevision({
      cwd: process.cwd(),
      changeId: finalized.changeId,
      releaseSourceRevision: finalized.releaseSourceRevision,
    });
  } catch (error) {
    if (!/change 不存在|SDD 未初始化|ENOENT/i.test(String(error?.message || ''))) {
      throw error;
    }
  }
  return finalized;
}

function clearRejectedPendingBaseline(target, baseline, error) {
  if (
    baseline?.__createdForAcquire &&
    baseline.lifecycleState === 'pending-lease' &&
    error?.code === 'PUBLISH_LEASE_HELD'
  ) {
    clearChangeBaseline(target, baseline.baselineId);
  }
}

async function acquirePublishLease(config, target, changeId, flags = {}) {
  const clientSessionId =
    readStringFlag(flags, 'client-session-id') || createPublishClientSessionId();
  const baseline = getStoredChangeBaseline(target);
  const baselineId = String(baseline?.baselineId || baseline?.id || '').trim();
  const baselineChangeId = String(baseline?.changeId || '').trim();
  const baselineClientSessionId = String(baseline?.clientSessionId || '').trim();
  const headDigest = String(baseline?.headDigest || '').trim();
  const sourceTree = String(baseline?.sourceBase?.treeHash || '').trim();
  const sourceCommit = String(baseline?.sourceBase?.baseCommit || '').trim();
  if (!baselineId || !headDigest || !sourceTree) {
    throw publishContextRequiredError(
      '发布租约获取',
      'change baseline 缺少 baselineId、headDigest 或 sourceBase.treeHash'
    );
  }
  if (
    baselineChangeId !== String(changeId || '').trim() ||
    baselineClientSessionId !== clientSessionId
  ) {
    throw publishContextRequiredError(
      '发布租约获取',
      'change baseline 与 changeId 或 clientSessionId 不匹配'
    );
  }
  const baseRevision =
    readStringFlag(flags, 'base-revision') ||
    [
      `changeBaseline=${baselineId}`,
      `headDigest=${headDigest}`,
      `sourceTree=${sourceTree}`,
      `sourceCommit=${sourceCommit || '-'}`,
    ].join(';');
  const data = await requestWithAuth(
    config,
    target.profileName,
    publishLeaseApiPath(target, '/acquire'),
    {
      method: 'POST',
      body: {
        changeId,
        baseRevision,
        clientSessionId,
        ttlSeconds: normalizePublishLeaseTtl(flags.ttl),
      },
    }
  );
  return savePublishLease(target, {
    ...data,
    clientSessionId,
    workspace: buildReleaseLeaseWorkspace(
      baseline.releaseSourceRevision,
      target
    ),
  });
}

async function renewPublishLease(config, target, lease, flags = {}) {
  const data = await requestWithAuth(
    config,
    target.profileName,
    publishLeaseApiPath(target, `/${encodeURIComponent(lease.leaseId)}/renew`),
    {
      method: 'POST',
      skipPublishLeaseHeartbeat: true,
      body: { ttlSeconds: normalizePublishLeaseTtl(flags.ttl) },
    }
  );
  return savePublishLease(target, {
    ...lease,
    ...data,
    clientSessionId: data?.clientSessionId || lease?.clientSessionId,
    changeId: data?.changeId || lease?.changeId,
    baseRevision: data?.baseRevision || lease?.baseRevision,
  });
}

async function resolvePublishLeaseForWrite(config, target, flags = {}) {
  if (
    activeDeliveryV2Context?.appType === target.appType &&
    activeDeliveryV2Context?.profileName === target.profileName
  ) {
    activePublishRequestContext = normalizePublishContext({
      appType: target.appType,
      profileName: target.profileName,
      publishLeaseId: activeDeliveryV2Context.publishLeaseId,
      changeBaselineId: activeDeliveryV2Context.baselineId,
      changeId: activeDeliveryV2Context.changeId,
      clientSessionId: activeDeliveryV2Context.clientSessionId,
    });
    return {
      leaseId: activeDeliveryV2Context.publishLeaseId,
      expiresAt: activeDeliveryV2Context.leaseExpiresAt,
      appType: target.appType,
      profile: target.profileName,
      changeId: activeDeliveryV2Context.changeId,
      clientSessionId: activeDeliveryV2Context.clientSessionId,
      baseRevision: activeDeliveryV2Context.packageDigest,
      holder: 'self',
      explicit: true,
    };
  }
  const explicitLeaseId = readStringFlag(flags, 'publish-lease-id');
  const changeId = readStringFlag(flags, 'change');
  const storedLease = getStoredPublishLease(target);
  const baselineAtStart = changeId
    ? getStoredChangeBaseline(target)
    : null;
  const newReleaseLifecycle = Boolean(
    changeId && !getUsableStoredPublishLease(target) && !baselineAtStart
  );
  const reusableFormCandidates = newReleaseLifecycle
    ? reusableStagedFormReleaseCandidates(target, changeId)
    : [];
  let acquiredByCommand = false;
  assertOrClaimWorktreeOwner({
    cwd: process.cwd(),
    changeId: changeId || storedLease?.changeId || 'unscoped-publish',
  });
  if (explicitLeaseId) {
    const clientSessionId =
      readStringFlag(flags, 'client-session-id') ||
      (storedLease?.leaseId === explicitLeaseId
        ? storedLease.clientSessionId
        : null) ||
      getStoredChangeBaseline(target)?.clientSessionId ||
      createPublishClientSessionId();
    if (changeId) {
      const baseline = await ensureChangeBaseline(
        config,
        target,
        changeId,
        flags,
        clientSessionId
      );
      finalizeReleaseBaseline(target, baseline);
    }
    const explicitLease = {
      leaseId: explicitLeaseId,
      explicit: true,
      changeId: changeId || storedLease?.changeId,
      clientSessionId,
    };
    // An explicit lease is opaque: it has no trustworthy expiry metadata and
    // may be owned by an external coordinator. Use it only for the requested
    // writes; never start a timer that would renew it speculatively.
    await stopActivePublishLeaseHeartbeat();
    activatePublishRequestContext(target, explicitLease);
    return explicitLease;
  }

  const stored = storedLease;
  assertLocalPublishLeaseOwnership(stored);
  let lease = getUsableStoredPublishLease(target);
  if (stored && !lease) {
    clearPublishLease(target, stored.leaseId);
  }
  if (!lease && changeId) {
    const pendingBaseline = getStoredChangeBaseline(target);
    const clientSessionId =
      readStringFlag(flags, 'client-session-id') ||
      (pendingBaseline?.changeId === changeId &&
      isChangeBaselineOwnedByCurrentSession(pendingBaseline)
        ? pendingBaseline.clientSessionId
        : null) ||
      createPublishClientSessionId();
    const baseline = await ensureChangeBaseline(
      config,
      target,
      changeId,
      flags,
      clientSessionId
    );
    try {
      lease = await acquirePublishLease(config, target, changeId, {
        ...flags,
        'client-session-id': clientSessionId,
      });
      acquiredByCommand = true;
    } catch (error) {
      clearRejectedPendingBaseline(target, baseline, error);
      throw error;
    }
    const finalizedBaseline = finalizeReleaseBaseline(target, baseline);
    if (newReleaseLifecycle) {
      try {
        await initializeNewReleaseStagedResources(
          config,
          target,
          changeId,
          reusableFormCandidates
        );
      } catch (error) {
        try {
          await requestWithAuth(
            config,
            target.profileName,
            publishLeaseApiPath(
              target,
              `/${encodeURIComponent(lease.leaseId)}/release`
            ),
            {
              method: 'POST',
              body: { completion: 'local-prepare-failed' },
            }
          );
        } catch {
          // Keep the staged child verification failure as the primary error.
        }
        clearPublishLease(target, lease.leaseId);
        clearChangeBaseline(
          target,
          finalizedBaseline?.baselineId || finalizedBaseline?.id
        );
        releaseWorktreeOwner({ cwd: process.cwd() });
        throw error;
      }
    }
  }
  if (!lease) return null;
  if (changeId && lease.changeId !== changeId) {
    fail(
      `当前发布租约属于 change ${lease.changeId || '-'}，不能用于 ${changeId}；请先执行 openxiangda release end`
    );
  }
  if (changeId) {
    const baseline = await ensureChangeBaseline(
      config,
      target,
      changeId,
      flags,
      lease.clientSessionId
    );
    finalizeReleaseBaseline(target, baseline);
  }
  const baseline = getStoredChangeBaseline(target);
  assertStoredReleaseSourceStable(baseline);
  activatePublishRequestContext(target, lease);
  const heartbeat = await activatePublishLeaseHeartbeat(
    config,
    target,
    lease,
    flags
  );
  if (shouldRenewPublishLease(lease)) {
    lease = await heartbeat.beforeWrite({ forceRenew: true });
  }
  if (acquiredByCommand) {
    activeCommandScopedPublishLease = {
      config,
      target,
      leaseId: lease.leaseId,
      changeId: lease.changeId || changeId,
      writeAttempted: false,
      retain: false,
      retentionReason: null,
    };
  }
  return lease;
}

async function renewPublishLeaseFailClosed(config, target, lease, flags = {}) {
  if (!lease?.leaseId) return lease;
  if (lease.explicit) return lease;
  activatePublishRequestContext(target, lease);
  const heartbeat = await activatePublishLeaseHeartbeat(
    config,
    target,
    lease,
    flags
  );
  return await heartbeat.beforeWrite({ forceRenew: true });
}

function activatePublishRequestContext(target, lease) {
  const baseline = getStoredChangeBaseline(target);
  activePublishRequestContext = normalizePublishContext({
    appType: target.appType,
    profileName: target.profileName,
    publishLeaseId: lease?.leaseId,
    changeBaselineId: baseline?.baselineId,
    changeId: lease?.changeId || baseline?.changeId,
    clientSessionId: lease?.clientSessionId || baseline?.clientSessionId,
  });
  return activePublishRequestContext;
}

async function activatePublishLeaseHeartbeat(config, target, lease, flags = {}) {
  if (!lease?.leaseId) return null;
  if (
    activePublishLeaseHeartbeat?.target?.appType === target.appType &&
    activePublishLeaseHeartbeat?.target?.profileName === target.profileName &&
    activePublishLeaseHeartbeat?.heartbeat?.lease?.leaseId === lease.leaseId
  ) {
    activePublishLeaseHeartbeat.renewFlags = flags;
    activePublishLeaseHeartbeat.heartbeat.setLease(lease);
    return activePublishLeaseHeartbeat.heartbeat;
  }
  await stopActivePublishLeaseHeartbeat();
  const active = { target, heartbeat: null, renewFlags: flags };
  const heartbeat = createPublishLeaseHeartbeat({
    lease,
    renew: async currentLease => {
      const renewed = await renewPublishLease(
        config,
        target,
        currentLease,
        active.renewFlags
      );
      activatePublishRequestContext(target, renewed);
      return renewed;
    },
  });
  active.heartbeat = heartbeat;
  activePublishLeaseHeartbeat = active;
  heartbeat.start();
  return heartbeat;
}

async function stopActivePublishLeaseHeartbeat() {
  const active = activePublishLeaseHeartbeat;
  activePublishLeaseHeartbeat = null;
  if (active?.heartbeat) await active.heartbeat.stop();
}

function markCommandScopedPublishWriteAttempted() {
  if (activeCommandScopedPublishLease) {
    activeCommandScopedPublishLease.writeAttempted = true;
  }
}

function retainCommandScopedPublishLease(reason = 'staged-release') {
  if (!activeCommandScopedPublishLease) return false;
  activeCommandScopedPublishLease.retain = true;
  activeCommandScopedPublishLease.retentionReason = String(reason || 'staged-release');
  return true;
}

async function finalizeCommandScopedPublishLease(options = {}) {
  const active = activeCommandScopedPublishLease;
  if (!active) return null;
  activeCommandScopedPublishLease = null;
  if (active.retain) {
    return {
      managed: true,
      released: false,
      retained: true,
      reason: active.retentionReason,
    };
  }
  if (options.succeeded === false && active.writeAttempted) {
    warn(
      `PUBLISH_WRITE_REVIEW_REQUIRED: change=${active.changeId || '-'} 的写请求结果未完整确认，租约已保留供只读核对和恢复`
    );
    return {
      managed: true,
      released: false,
      retained: true,
      reason: 'write-result-review',
    };
  }

  await stopActivePublishLeaseHeartbeat();
  const stored = getStoredPublishLease(active.target);
  if (!stored || stored.leaseId !== active.leaseId) {
    return {
      managed: true,
      released: false,
      retained: false,
      reason: 'local-lease-already-cleared',
    };
  }
  const baseline = getStoredChangeBaseline(active.target, {
    access: 'reconciliation-read',
  });
  const integration = assertReleaseSourceIntegrated(
    baseline?.releaseSourceRevision,
    { cwd: process.cwd() }
  );
  try {
    await requestWithAuth(
      active.config,
      active.target.profileName,
      publishLeaseApiPath(
        active.target,
        `/${encodeURIComponent(active.leaseId)}/release`
      ),
      {
        method: 'POST',
        retryTransient: true,
        retries: 2,
        body: {
          completion:
            options.succeeded === false
              ? 'prewrite-failed'
              : 'direct-publish-completed',
          sourceCommit: integration.sourceCommit,
          mainBranch: integration.mainBranch,
          mainTipCommit: integration.mainTipCommit,
        },
      }
    );
  } catch (error) {
    if (
      !['PUBLISH_LEASE_EXPIRED', 'PUBLISH_LEASE_INVALID'].includes(
        error?.code
      )
    ) {
      activeCommandScopedPublishLease = active;
      throw error;
    }
  }
  clearPublishLease(active.target, active.leaseId);
  if (baseline) {
    clearChangeBaseline(
      active.target,
      baseline.baselineId || baseline.id
    );
  }
  releaseWorktreeOwner({ cwd: process.cwd() });
  activePublishRequestContext = null;
  return {
    managed: true,
    released: true,
    retained: false,
    completion:
      options.succeeded === false
        ? 'prewrite-failed'
        : 'direct-publish-completed',
    integration,
  };
}

function publishContextRequiredError(label, detail) {
  const suffix = detail ? `（${detail}）` : '';
  const error = new Error(
    `PUBLISH_CONTEXT_REQUIRED: ${label || '配置写入'}需要完整发布上下文${suffix}；请先执行 openxiangda release begin --change <id>，或在命令中传入 --change <id>`
  );
  error.code = 'PUBLISH_CONTEXT_REQUIRED';
  return error;
}

function getCompleteStoredPublishContext(target) {
  const lease = getUsableStoredPublishLease(target);
  let baseline;
  try {
    baseline = getStoredChangeBaseline(target);
  } catch {
    return null;
  }
  if (!lease || !baseline) return null;
  const context = normalizePublishContext({
    appType: target.appType,
    profileName: target.profileName,
    publishLeaseId: lease.leaseId,
    changeBaselineId: baseline.baselineId || baseline.id,
    changeId: lease.changeId || baseline.changeId,
    clientSessionId: lease.clientSessionId || baseline.clientSessionId,
  });
  try {
    assertCompletePublishContext(context);
  } catch {
    return null;
  }
  if (
    lease.changeId !== baseline.changeId ||
    lease.clientSessionId !== baseline.clientSessionId
  ) {
    return null;
  }
  return context;
}

async function ensureDirectMutationPublishContext(
  config,
  target,
  flags = {},
  label = '配置写入'
) {
  const changeId = readStringFlag(flags, 'change');
  const active = normalizePublishContext(activePublishRequestContext);
  if (
    active?.appType === target.appType &&
    active?.profileName === target.profileName &&
    (!changeId || active.changeId === changeId)
  ) {
    try {
      return assertCompletePublishContext(active);
    } catch {
      activePublishRequestContext = null;
    }
  }

  const storedContext = getCompleteStoredPublishContext(target);
  if (!changeId && !storedContext) {
    throw publishContextRequiredError(label);
  }
  const explicitLeaseId = readStringFlag(flags, 'publish-lease-id');
  if (
    explicitLeaseId &&
    storedContext &&
    explicitLeaseId !== storedContext.publishLeaseId
  ) {
    throw publishContextRequiredError(
      label,
      '显式 lease 与本地完整发布会话不一致'
    );
  }

  const lease = await resolvePublishLeaseForWrite(config, target, flags);
  if (!lease) throw publishContextRequiredError(label);
  const context = activatePublishRequestContext(target, lease);
  let complete;
  try {
    complete = assertCompletePublishContext(context);
  } catch {
    throw publishContextRequiredError(label, 'lease 或 change baseline 不完整');
  }
  const baseline = getStoredChangeBaseline(target);
  if (
    lease.changeId !== baseline?.changeId ||
    lease.clientSessionId !== baseline?.clientSessionId
  ) {
    throw publishContextRequiredError(label, 'lease 与 change baseline 不匹配');
  }
  return complete;
}

async function resolveRuntimePublishLeaseForWrite(config, target, flags = {}) {
  const stored = getStoredPublishLease(target);
  const effectiveChangeId =
    readStringFlag(flags, 'change') || stored?.changeId || 'runtime-deploy';
  const lease = await resolvePublishLeaseForWrite(config, target, {
    ...flags,
    change: effectiveChangeId,
  });
  if (!lease?.leaseId) {
    fail('Runtime release 必须在应用级 publish lease 内创建/激活');
  }
  return lease;
}

function assertLocalPublishLeaseOwnership(lease) {
  if (
    !lease ||
    isPublishLeaseExpired(lease) ||
    isPublishLeaseOwnedByCurrentSession(lease)
  ) {
    return;
  }
  const owner = lease.workspace?.threadId || lease.clientSessionId || 'another-session';
  fail(
    `当前工作区的应用发布租约由另一个任务持有 (${owner})；请勿复用、续期或释放该任务的租约，请等待其 release end 后再发布`
  );
}

function publishLeaseApiPath(target, suffix) {
  return `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/publish-lease${suffix}`;
}

function buildReleaseLeaseWorkspace(sourceRevision, target) {
  if (!sourceRevision || typeof sourceRevision !== 'object') return undefined;
  return {
    cwd: path.resolve(target?.cwd || process.cwd()),
    branch: sourceRevision.branch || '',
    commit: sourceRevision.baseCommit || '',
    treeHash: sourceRevision.treeHash || '',
    worktreeRoot: sourceRevision.worktreeRoot || '',
    remoteName: sourceRevision.remoteName || null,
    remoteUrlHash: sourceRevision.remoteUrlHash || null,
    mainBranch: sourceRevision.mainBranch || null,
    mainTipCommit: sourceRevision.mainTipCommit || null,
  };
}

function printReleaseIntegrationStatus(result) {
  print(
    [
      `发布提交: ${result.sourceCommit || '-'}`,
      `来源分支: ${result.sourceBranch || '-'}`,
      `权威主分支: ${result.remoteName ? `${result.remoteName}/` : ''}${result.mainBranch}`,
      `主分支提交: ${result.mainTipCommit}`,
      `已回合并推送: ${result.integrated ? 'yes' : 'no'}`,
    ].join('\n')
  );
}

function normalizePublishLeaseTtl(value) {
  if (value === undefined || value === null || value === '') {
    return DEFAULT_CLI_PUBLISH_LEASE_TTL_SECONDS;
  }
  const ttl = Number(value);
  if (!Number.isSafeInteger(ttl) || ttl < 30 || ttl > 3600) {
    fail('--ttl 必须是 30-3600 秒之间的整数');
  }
  return ttl;
}

function printPublishLeaseStatus(result) {
  const remote = result.remote || {};
  const local = result.local || null;
  print(
    [
      `应用发布租约: ${remote.appType || local?.appType || '-'}`,
      `remote: ${remote.active ? `active holder=${remote.holder} expiresAt=${remote.expiresAt}` : 'inactive'}`,
      `local: ${local ? `leaseId=${local.leaseId} change=${local.changeId || '-'} expiresAt=${local.expiresAt}` : 'none'}`,
      result.releaseSourceRevision
        ? `pending mainline: ${String(result.releaseSourceRevision.baseCommit || '').slice(0, 12)} -> ${result.releaseSourceRevision.remoteName}/${result.releaseSourceRevision.mainBranch}（运行 release integration-status）`
        : 'pending mainline: none',
    ].join('\n')
  );
}

function printSddInitReport(result) {
  const lines = [`OpenXiangda SDD initialized: ${result.path}`, `schemaVersion: ${result.schemaVersion || 'unknown'}`];
  for (const op of result.operations) {
    lines.push(`- ${op.action}: ${op.path}`);
  }
  print(lines.join('\n'));
}

function printSddStatusReport(result) {
  const lines = [
    `OpenXiangda SDD status: ${result.governance.initialized ? 'initialized' : 'not initialized'}`,
    `path: ${result.governance.path}`,
    `schemaVersion: ${result.schemaVersion || result.governance.schemaVersion || 'unknown'}`,
    `strictHighRisk: ${result.governance.strictHighRisk ? 'true' : 'false'}`,
    `active changes: ${result.activeChanges.length}`,
  ];
  for (const change of result.activeChanges) {
    lines.push(`- ${change.id}: ${change.status}${change.approvedAt ? ` approvedAt=${change.approvedAt}` : ''}`);
  }
  if (result.activeChange) lines.push(`activeChange: ${result.activeChange.id}`);
  if (result.blockingErrors?.length) {
    lines.push('blockingErrors:');
    for (const error of result.blockingErrors) lines.push(`- ${error.name}: ${error.message}`);
  }
  if (result.bypassLog) lines.push(`bypass log: ${result.bypassLog}`);
  print(lines.join('\n'));
}

function printSddVerifyReport(result) {
  const lines = [
    `OpenXiangda SDD verify: ${result.passed ? 'passed' : 'failed'}`,
    `change: ${result.change.id}`,
    `schemaVersion: ${result.schemaVersion || result.change.schemaVersion || 'unknown'}`,
  ];
  if (result.errors.length > 0) {
    lines.push('Errors:');
    for (const error of result.errors) {
      lines.push(`- ${error.name}: ${error.message}`);
      for (const detail of error.details || []) lines.push(`  ${detail}`);
    }
  }
  if (result.warnings.length > 0) {
    lines.push('Warnings:');
    for (const warning of result.warnings) lines.push(`- ${warning.name}: ${warning.message}`);
  }
  print(lines.join('\n'));
}

async function doctor(args) {
  const { flags } = parseArgs(args);
  if (flags.help || flags.h) {
    print('用法: openxiangda doctor [--profile name] [--app-type APP_XXX] [--agent codex] [--release] [--json]');
    return;
  }
  const config = loadConfig();
  const profileName = resolveDoctorProfileName(config, flags);
  const result = {
    cli: {
      version: CURRENT_VERSION,
      commandDiscovery: 'openxiangda commands --json',
      designGateCommand: 'openxiangda design gates --json',
    },
    profile: {
      requested: profileName || null,
      exists: false,
      baseUrl: null,
      loggedIn: false,
      user: null,
    },
    workspace: {
      cwd: process.cwd(),
      stateFile: path.join(process.cwd(), PROJECT_STATE_FILE),
      hasState: fs.existsSync(path.join(process.cwd(), PROJECT_STATE_FILE)),
      appType: flags['app-type'] || null,
      bound: false,
    },
    resources: {
      hasDirectory: fs.existsSync(path.join(process.cwd(), 'src', 'resources')),
      validation: null,
    },
    sdd: null,
    release: null,
    skills: null,
    checks: [],
  };

  if (profileName && config.profiles?.[profileName]) {
    const { profile } = getProfile(config, profileName);
    result.profile.exists = true;
    result.profile.baseUrl = profile.baseUrl || null;
    result.profile.loggedIn = Boolean(profile.token?.accessToken);
    result.profile.user = profile.user || null;
    try {
      const target = getWorkspaceTarget(config, profileName, flags);
      result.workspace.appType = target.appType;
      result.workspace.bound = true;
      result.workspace.profile = target.profileName;
      result.workspace.boundAt = target.bound.updatedAt || null;
      result.checks.push({ name: 'workspace-binding', status: 'ok' });
    } catch (error) {
      result.checks.push({ name: 'workspace-binding', status: 'warn', message: error.message });
    }
    if (result.profile.loggedIn) {
      try {
        const authStatus = await requestWithAuth(config, profileName, '/openxiangda-api/v1/auth/whoami');
        result.profile.authStatus = authStatus;
        result.checks.push({ name: 'auth', status: 'ok' });
      } catch (error) {
        result.profile.authError = error.message;
        result.checks.push({ name: 'auth', status: 'warn', message: error.message });
      }
    } else {
      result.checks.push({ name: 'auth', status: 'warn', message: 'profile 未登录' });
    }
  } else {
    result.checks.push({ name: 'profile', status: 'warn', message: '未选择或不存在 profile' });
  }

  if (result.resources.hasDirectory) {
    const manifest = loadWorkspaceResources();
    const validation = validateWorkspaceResources(manifest);
    result.resources.validation = {
      errors: validation.errors,
      warnings: validation.warnings,
      counts: Object.fromEntries(
        RESOURCE_SPECS.map(spec => [spec.key, (manifest[spec.key] || []).length])
      ),
    };
    result.checks.push({
      name: 'resource-validate',
      status: validation.errors.length > 0 ? 'error' : 'ok',
      errors: validation.errors.length,
      warnings: validation.warnings.length,
    });
  } else {
    result.checks.push({ name: 'resource-validate', status: 'skip', message: '未发现 src/resources' });
  }

  result.skills = getSkillStatusReport({ agent: flags.agent || 'codex' });
  const outdatedSkills = result.skills.results
    .flatMap(item => item.skills)
    .filter(item => item.status !== 'installed');
  result.checks.push({
    name: 'skills',
    status: outdatedSkills.length > 0 ? 'warn' : 'ok',
    message: outdatedSkills.length > 0 ? `${outdatedSkills.length} 个 skill 未安装或过期` : undefined,
  });

  if (flags.release) {
    result.release = buildWorkspaceReleasePlan({
      changed: true,
      profile: profileName || config.currentProfile || '<profile>',
      check: true,
    });
    result.sdd = result.release.sdd || buildSddStatus({ cwd: process.cwd(), configText: readWorkspaceConfigText() });
    result.checks.push({
      name: 'workspace-release',
      status: result.release.errors.length > 0 ? 'error' : 'ok',
      message:
        result.release.errors.length > 0
          ? `${result.release.errors.length} 个发布前错误`
          : undefined,
    });
  }

  if (flags.json) return writeJson(result);
  printDoctorReport(result);
}

function resolveDoctorProfileName(config, flags) {
  if (flags.profile) return flags.profile;
  const state = loadProjectState();
  const boundEntries = Object.entries(state.profiles || {}).filter(([, bound]) => bound?.appType);
  const requestedAppType = flags['app-type'];
  if (requestedAppType) {
    const matched = boundEntries.find(([, bound]) => bound.appType === requestedAppType);
    if (matched) return matched[0];
  }
  if (config.currentProfile && state.profiles?.[config.currentProfile]?.appType) {
    return config.currentProfile;
  }
  if (boundEntries.length === 1) {
    return boundEntries[0][0];
  }
  return config.currentProfile;
}

function printDoctorReport(result) {
  const lines = [
    `OpenXiangda doctor v${result.cli.version}`,
    `profile: ${result.profile.requested || '(none)'} ${result.profile.loggedIn ? '(logged in)' : '(not logged in)'}`,
    `baseUrl: ${result.profile.baseUrl || '(none)'}`,
    `workspace: ${result.workspace.bound ? `${result.workspace.profile}/${result.workspace.appType}` : 'not bound'}`,
    `resources: ${result.resources.hasDirectory ? 'src/resources found' : 'missing'}`,
  ];
  if (result.resources.validation) {
    lines.push(
      `resource validation: ${result.resources.validation.errors.length} errors, ${result.resources.validation.warnings.length} warnings`
    );
  }
  if (result.release) {
    lines.push(
      `release plan: forms=${result.release.targets.forms.length}, pages=${result.release.targets.pages.length}, functions=${(result.release.targets.functions || []).length}, resources=${result.release.targets.resources ? 'yes' : 'no'}, runtime=${result.release.targets.runtime ? 'yes' : 'no'}`
    );
  }
  if (result.sdd) {
    const governance = result.sdd.governance || result.sdd.governanceConfig || {};
    lines.push(
      `sdd: ${governance.initialized ? 'initialized' : 'not initialized'} path=${governance.path || 'openspec'} strict=${governance.strictHighRisk ? 'true' : 'false'}`
    );
  }
  for (const check of result.checks) {
    const suffix = check.message ? ` - ${check.message}` : '';
    lines.push(`- ${check.name}: ${check.status}${suffix}`);
  }
  lines.push(`design gate: ${result.cli.designGateCommand}`);
  print(lines.join('\n'));
}

