async function appFunction(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda function list|get|create|update|upsert|delete|invoke [functionCode] [--json-file file]',
      '      openxiangda function test <functionCode> [--input-json JSON|file] [--secret-from-env logical=ENV] [--json]',
      '说明: function test 只把父进程环境变量中的值通过 stdin 交给隔离测试子进程；不会写入 workspace/cache/state。',
    ].join('\n'));
    return;
  }
  if (subcommand === 'test') {
    return await testAppFunctionLocally(positional, flags);
  }

  const config = loadConfig();
  const target = getWorkspaceTarget(config, flags.profile || config.currentProfile, flags);

  if (subcommand === 'invoke') {
    const [functionCode] = positional;
    if (!functionCode) fail('用法: openxiangda function invoke <functionCode> [--body-json file|json]');
    if (
      target.logicalApp &&
      Object.keys(target.state.targets || {}).length > 1 &&
      !flags.environment &&
      !flags.target
    ) {
      fail(
        'FUNCTION_INVOKE_ENVIRONMENT_REQUIRED: 托管应用调用 Function 必须显式提供 --environment <target>，避免把预发结果误判为生产结果'
      );
    }
    warn(
      [
        'Resolved target:',
        'operation=function invoke',
        `profile=${target.profileName}`,
        `environment=${target.targetName || 'legacy'}`,
        `kind=${target.environmentKind || 'unmanaged'}`,
        `appType=${target.appType}`,
        `environmentId=${target.environmentId || '-'}`,
      ].join(' ')
    );
    const body = readDirectJsonBody(flags, 'function invoke', { optional: true });
    const openXiangdaApiRequest = buildOpenXiangdaFunctionInvokeRequest(
      target.appType,
      functionCode,
      body
    );
    if (flags['dry-run']) {
      return runDirectRequest(config, target, flags, openXiangdaApiRequest);
    }
    try {
      const data = await requestWithAuth(
        config,
        target.profileName,
        openXiangdaApiRequest.path,
        {
          method: openXiangdaApiRequest.method,
          body: openXiangdaApiRequest.body,
          strictEnvelope: true,
        }
      );
      return outputDirectResult(data, flags);
    } catch (error) {
      if (!isHttpNotFound(error)) throw error;
      return runDirectRequest(
        config,
        target,
        flags,
        buildLegacyFunctionInvokeRequest(target.appType, functionCode, body),
        { controlPlaneMutation: false }
      );
    }
  }

  return directResourceCrud(config, target, {
    commandName: 'function',
    subcommand,
    flags,
    positional,
    resourceType: 'function',
    basePath: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions`,
    manifestDir: path.join('src', 'resources', 'functions'),
    prepareBody: async body => {
      if (functionManifestDeclaresSecretRefs(body)) {
        fail(
          'APP_FUNCTION_SECRET_STAGED_RELEASE_REQUIRED: 带 secretRefs 的 Function 必须使用 resource publish + Backend Release v2，禁止 direct CRUD 绕过原子绑定'
        );
      }
      const definitionJson = await resolveManifestJson(
        config,
        target.profileName,
        body,
        'definitionJson',
        'definitionFile'
      );
      if (definitionJson?.secretRefs !== undefined) {
        fail(
          'APP_FUNCTION_SECRET_STAGED_RELEASE_REQUIRED: secretRefs 必须位于 Function manifest 顶层并通过 Backend Release v2 发布，禁止写入 definitionJson 或 direct CRUD'
        );
      }
      applyResourceBindingsToRuntimeDefinition(target.bound, body, definitionJson);
      const code = body.code || body.functionCode || body.resourceCode;
      return stripUndefinedValues({
        code,
        name: body.name || definitionJson.name || code,
        description: body.description !== undefined ? body.description : definitionJson.description || '',
        definitionJson,
        resourceBindings: definitionJson.resourceBindings,
        inputSchema: body.inputSchema || definitionJson.inputSchema,
        outputSchema: body.outputSchema || definitionJson.outputSchema,
        status: body.status,
      });
    },
    codeOf: body => body.code || body.functionCode || body.resourceCode,
    saveState: (code, data) => saveFunctionResource(target, code, data?.id, {
      status: data?.status,
    }),
  });
}

function appSecretApiPath(target, suffix = '') {
  return `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/secrets${suffix}`;
}

function manifestUsesAppFunctionSecrets(manifest) {
  return (manifest?.functions || []).some(
    item => functionManifestDeclaresSecretRefs(item)
  );
}

function collectCapabilityNames(value) {
  const names = new Set();
  const visit = item => {
    if (!item) return;
    if (typeof item === 'string') {
      names.add(item.trim().toLowerCase());
      return;
    }
    if (Array.isArray(item)) {
      item.forEach(visit);
      return;
    }
    if (typeof item === 'object') {
      for (const [key, enabled] of Object.entries(item)) {
        if (enabled === true) names.add(String(key).trim().toLowerCase());
      }
    }
  };
  visit(value?.capabilities);
  visit(value?.features);
  visit(value?.contracts);
  return names;
}

function appFunctionSecretCapabilityEnabled(capabilities, name) {
  const normalized = String(name || '').toLowerCase();
  const camel = normalized.replace(/_([a-z])/g, (_match, char) => char.toUpperCase());
  return (
    capabilities?.[normalized] === true ||
    capabilities?.[camel] === true ||
    capabilities?.capabilities?.[normalized] === true ||
    capabilities?.features?.[normalized] === true ||
    collectCapabilityNames(capabilities).has(normalized)
  );
}

async function fetchAppFunctionSecretCapabilities(config, target) {
  return await requestWithAuth(
    config,
    target.profileName,
    appSecretApiPath(target, '/capabilities')
  );
}

function assertAppFunctionSecretCapabilities(capabilities) {
  const managementReady =
    capabilities?.enabled === true &&
    String(capabilities?.contractVersion || '') ===
      APP_FUNCTION_SECRET_CAPABILITIES.contractVersion &&
    String(capabilities?.runtimeContractVersion || '') ===
      APP_FUNCTION_SECRET_CAPABILITIES.runtimeContractVersion;
  const missing = [];
  if (!managementReady) missing.push('app_function_secrets_v1/trusted_node_v2');
  for (const feature of [
    'app_function_secrets_v1',
    'trusted_node_v2',
    APP_FUNCTION_SECRET_CAPABILITIES.backendRelease,
    APP_FUNCTION_SECRET_CAPABILITIES.atomicActivation,
  ]) {
    if (!appFunctionSecretCapabilityEnabled(capabilities, feature)) {
      missing.push(feature);
    }
  }
  if (missing.length > 0) {
    const error = new Error(
      `APP_FUNCTION_SECRET_CAPABILITY_REQUIRED: 平台尚未完整启用 ${unique(missing).join(', ')}；禁止忽略 secretRefs 或降级发布`
    );
    error.code = 'APP_FUNCTION_SECRET_CAPABILITY_REQUIRED';
    error.missingCapabilities = unique(missing);
    throw error;
  }
  return capabilities;
}

async function assertManifestAppFunctionSecretCapabilities(
  config,
  target,
  manifest
) {
  if (!manifestUsesAppFunctionSecrets(manifest)) return null;
  try {
    return assertAppFunctionSecretCapabilities(
      await fetchAppFunctionSecretCapabilities(config, target)
    );
  } catch (error) {
    if (isHttpNotFound(error)) {
      const missing = new Error(
        'APP_FUNCTION_SECRET_CAPABILITY_REQUIRED: 当前平台没有 App Function Secret capability endpoint；禁止忽略 secretRefs 或按旧 Function 协议发布'
      );
      missing.code = 'APP_FUNCTION_SECRET_CAPABILITY_REQUIRED';
      throw missing;
    }
    throw error;
  }
}

const SECRET_RESPONSE_FORBIDDEN_KEYS = new Set([
  'value',
  'secretvalue',
  'plaintext',
  'ciphertext',
  'cipher',
  'encryptedvalue',
  'encrypteddek',
  'wrappeddek',
  'valuehash',
  'cipherhash',
  'valuedigest',
  'cipherdigest',
  'valuelength',
  'cipherlength',
  'plaintextlength',
  'iv',
  'nonce',
  'authtag',
  'tag',
]);

function assertSecretMetadataOnly(value, pathParts = []) {
  if (!value || typeof value !== 'object') return;
  if (Array.isArray(value)) {
    value.forEach((item, index) =>
      assertSecretMetadataOnly(item, [...pathParts, String(index)])
    );
    return;
  }
  for (const [key, child] of Object.entries(value)) {
    const normalizedKey = key.replace(/[_-]/g, '').toLowerCase();
    if (SECRET_RESPONSE_FORBIDDEN_KEYS.has(normalizedKey)) {
      const error = new Error(
        `APP_SECRET_RESPONSE_CONTRACT_VIOLATION: Secret API 返回了禁止的明文/密文派生字段 ${[...pathParts, key].join('.')}`
      );
      error.code = 'APP_SECRET_RESPONSE_CONTRACT_VIOLATION';
      throw error;
    }
    assertSecretMetadataOnly(child, [...pathParts, key]);
  }
}

function outputSecretMetadataOnly(value, flags = {}) {
  assertSecretMetadataOnly(value);
  if (flags.json) return writeJson(value);
  print(JSON.stringify(value, null, 2));
}

function requireExplicitProfile(flags, label) {
  const profile = String(flags.profile || '').trim();
  if (!profile) fail(`${label} 必须显式提供 --profile <name>`);
  return profile;
}

function resolveExactSecretName(positional, flags, label) {
  const selectors = [
    ...(positional || []),
    ...splitList(flags.only),
    ...splitList(flags.code),
  ]
    .map(value => String(value || '').trim())
    .filter(Boolean);
  const names = unique(selectors);
  if (names.length !== 1) {
    fail(`${label} 必须通过位置参数、--only 或 --code 精确选择一个 Secret name`);
  }
  if (!/^[A-Za-z][A-Za-z0-9_.-]{0,127}$/.test(names[0])) {
    fail(`${label}: Secret name 只能包含字母、数字、点、下划线和中划线，并以字母开头`);
  }
  return names[0];
}

function rejectUnsafeSecretValueFlags(flags) {
  const forbidden = [
    'value',
    'value-file',
    'secret',
    'secret-file',
    'json-file',
    'body-json',
  ].filter(key => flags[key] !== undefined);
  if (forbidden.length > 0) {
    fail(
      `Secret 明文禁止出现在命令行或文件参数中: ${forbidden
        .map(key => `--${key}`)
        .join(', ')}；请使用隐藏 TTY 输入或 --value-stdin`
    );
  }
}

function readSecretValueFromStdin() {
  const input = fs.readFileSync(0, 'utf8');
  return input.replace(/\r?\n$/, '');
}

async function readHiddenSecretValue(promptText = 'Secret value: ') {
  if (!process.stdin.isTTY || !process.stderr.isTTY) {
    fail('非交互环境必须使用 --value-stdin；不会从参数或 workspace 文件读取 Secret');
  }
  return await new Promise((resolve, reject) => {
    const input = process.stdin;
    const previousRaw = Boolean(input.isRaw);
    let value = '';
    const cleanup = () => {
      input.off('data', onData);
      try {
        input.setRawMode(previousRaw);
      } catch {
        // The TTY may have closed while handling Ctrl-C.
      }
      input.pause();
    };
    const onData = chunk => {
      const textValue = String(chunk);
      for (const char of textValue) {
        if (char === '\u0003') {
          cleanup();
          process.stderr.write('\n');
          reject(new Error('Secret 输入已取消'));
          return;
        }
        if (char === '\r' || char === '\n') {
          cleanup();
          process.stderr.write('\n');
          resolve(value);
          return;
        }
        if (char === '\u007f' || char === '\b') {
          value = value.slice(0, -1);
          continue;
        }
        value += char;
      }
    };
    process.stderr.write(promptText);
    input.setEncoding('utf8');
    input.setRawMode(true);
    input.resume();
    input.on('data', onData);
  });
}

async function readSecretValue(flags, label) {
  rejectUnsafeSecretValueFlags(flags);
  const value = flags['value-stdin']
    ? readSecretValueFromStdin()
    : await readHiddenSecretValue(`${label} value: `);
  if (!value) fail(`${label}: Secret value 不能为空`);
  if (Buffer.byteLength(value, 'utf8') > 64 * 1024) {
    fail(`${label}: Secret value 不能超过 64 KiB`);
  }
  registerSensitiveText(value);
  return value;
}

function readSecretExpectedRevision(flags, label, options = {}) {
  const raw = readStringFlag(flags, 'expected-revision');
  if (options.create && (raw === '' || raw === undefined)) return 0;
  if (raw === '' || raw === undefined || !/^\d+$/.test(String(raw))) {
    fail(`${label} 必须提供 --expected-revision <非负整数>`);
  }
  const revision = Number(raw);
  if (!Number.isSafeInteger(revision) || revision < 0) {
    fail(`${label}: --expected-revision 必须是非负安全整数`);
  }
  if (options.create && revision !== 0) {
    fail(`${label}: create 的 --expected-revision 必须是 0`);
  }
  return revision;
}

function secretMutationControl(context) {
  return {
    publishLeaseId: context.publishLeaseId,
    baselineId: context.changeBaselineId,
    changeId: context.changeId,
    clientSessionId: context.clientSessionId,
  };
}

function secretClientOperationId(
  target,
  control,
  name,
  action,
  expectedRevision,
  flags = {}
) {
  const explicit = String(
    flags['client-operation-id'] || flags['idempotency-key'] || ''
  ).trim();
  if (explicit) return explicit;
  return `openxiangda-secret-${canonicalJsonSha256({
    profile: target.profileName,
    appType: target.appType,
    name,
    action,
    changeId: control.changeId,
    clientSessionId: control.clientSessionId,
    expectedRevision,
  })}`;
}

async function buildSecretDryRun(config, target, subcommand, name, flags) {
  return await withReadOnlyHttpGuard('secret --dry-run', async () => {
    const capabilities = assertAppFunctionSecretCapabilities(
      await fetchAppFunctionSecretCapabilities(config, target)
    );
    const current = name
      ? await requestOptionalWithAuth(
          config,
          target.profileName,
          appSecretApiPath(target, `/${encodeURIComponent(name)}`)
        )
      : null;
    const result = {
      dryRun: true,
      command: `secret ${subcommand}`,
      profile: target.profileName,
      appType: target.appType,
      name,
      changeId: readStringFlag(flags, 'change'),
      expectedRevision:
        subcommand === 'create'
          ? readSecretExpectedRevision(flags, 'secret create', { create: true })
          : readSecretExpectedRevision(flags, `secret ${subcommand}`),
      current,
      valueRead: false,
      writes: 0,
      capabilities: {
        contractVersion: capabilities.contractVersion,
        runtimeContractVersion: capabilities.runtimeContractVersion,
        backend_release_v2: true,
        atomic_staged_children_v2: true,
      },
    };
    assertSecretMetadataOnly(result);
    return result;
  });
}

async function appSecret(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda secret list|unused --profile <name> [--json]',
      '      openxiangda secret metadata|references|audit <name> --profile <name> [--json]',
      '      openxiangda secret create <name> --profile <name> --change <id> [--value-stdin] [--description text] [--expires-at ISO] [--dry-run]',
      '      openxiangda secret update <name> --profile <name> --change <id> --expected-revision <n> [--description text] [--status active|disabled] [--expires-at ISO] [--dry-run]',
      '      openxiangda secret rotate <name> --profile <name> --change <id> --expected-revision <n> [--value-stdin] [--reason text] [--dry-run]',
      '      openxiangda secret delete <name> --profile <name> --change <id> --expected-revision <n> --reason text [--dry-run]',
      'Secret 明文只接受隐藏 TTY 或 stdin；禁止 --value、文件、workspace/state 和明文回读。',
    ].join('\n'));
    return;
  }

  const profileName = requireExplicitProfile(flags, `secret ${subcommand || ''}`);
  const config = loadConfig();
  const target = getWorkspaceTarget(config, profileName, flags);
  const readOnlyCommands = new Set([
    'list',
    'metadata',
    'get',
    'references',
    'audit',
    'unused',
  ]);
  if (readOnlyCommands.has(subcommand)) {
    assertAppFunctionSecretCapabilities(
      await fetchAppFunctionSecretCapabilities(config, target)
    );
    let pathSuffix = '';
    if (subcommand === 'unused') pathSuffix = '/unused';
    else if (subcommand !== 'list') {
      const name = resolveExactSecretName(positional, flags, `secret ${subcommand}`);
      pathSuffix = `/${encodeURIComponent(name)}`;
      if (subcommand === 'references' || subcommand === 'audit') {
        pathSuffix += `/${subcommand}`;
      }
    }
    const data = await requestWithAuth(
      config,
      target.profileName,
      appSecretApiPath(target, pathSuffix)
    );
    return outputSecretMetadataOnly(data, flags);
  }

  if (!['create', 'update', 'rotate', 'delete'].includes(subcommand)) {
    fail('用法: openxiangda secret list|metadata|references|audit|unused|create|update|rotate|delete');
  }
  requireExplicitProfile(flags, `secret ${subcommand}`);
  const changeId = String(readStringFlag(flags, 'change') || '').trim();
  if (!changeId) fail(`secret ${subcommand} 必须提供 --change <id>`);
  const name = resolveExactSecretName(positional, flags, `secret ${subcommand}`);
  rejectUnsafeSecretValueFlags(flags);
  if (flags['dry-run']) {
    const result = await buildSecretDryRun(
      config,
      target,
      subcommand,
      name,
      flags
    );
    return outputSecretMetadataOnly(result, flags);
  }

  assertAppFunctionSecretCapabilities(
    await fetchAppFunctionSecretCapabilities(config, target)
  );
  const context = await ensureDirectMutationPublishContext(
    config,
    target,
    flags,
    `secret ${subcommand}`
  );
  const control = secretMutationControl(context);
  try {
  let method;
  let pathSuffix;
  let body;
  if (subcommand === 'create') {
    const expectedRevision = readSecretExpectedRevision(
      flags,
      'secret create',
      { create: true }
    );
    const value = await readSecretValue(flags, 'secret create');
    method = 'POST';
    pathSuffix = '';
    body = stripUndefinedValues({
      ...control,
      name,
      value,
      description: flags.description,
      expiresAt: flags['expires-at'],
      expectedRevision,
      idempotencyKey: secretClientOperationId(
        target,
        control,
        name,
        'create',
        expectedRevision,
        flags
      ),
    });
  } else if (subcommand === 'update') {
    method = 'PATCH';
    pathSuffix = `/${encodeURIComponent(name)}`;
    body = stripUndefinedValues({
      ...control,
      description: flags.description,
      status: flags.status,
      expiresAt: flags['expires-at'],
      expectedRevision: readSecretExpectedRevision(flags, 'secret update'),
    });
    if (
      body.description === undefined &&
      body.status === undefined &&
      body.expiresAt === undefined
    ) {
      fail('secret update 至少需要 --description、--status 或 --expires-at');
    }
  } else if (subcommand === 'rotate') {
    const expectedRevision = readSecretExpectedRevision(
      flags,
      'secret rotate'
    );
    const value = await readSecretValue(flags, 'secret rotate');
    method = 'POST';
    pathSuffix = `/${encodeURIComponent(name)}/rotate`;
    body = stripUndefinedValues({
      ...control,
      value,
      expectedRevision,
      idempotencyKey: secretClientOperationId(
        target,
        control,
        name,
        'rotate',
        expectedRevision,
        flags
      ),
      reason: flags.reason,
    });
  } else {
    const reason = String(flags.reason || '').trim();
    if (reason.length < 8) {
      fail('secret delete 必须提供至少 8 个字符的 --reason');
    }
    method = 'POST';
    pathSuffix = `/${encodeURIComponent(name)}/delete`;
    body = {
      ...control,
      expectedRevision: readSecretExpectedRevision(flags, 'secret delete'),
      reason,
    };
  }
  const data = await requestWithAuth(
    config,
    target.profileName,
    appSecretApiPath(target, pathSuffix),
    { method, body }
  );
  return outputSecretMetadataOnly(data, flags);
  } catch (error) {
    const safeMessage = maskText(error?.message || String(error));
    if (error && typeof error === 'object') {
      error.message = safeMessage;
      if (typeof error.stack === 'string') error.stack = maskText(error.stack);
      throw error;
    }
    throw new Error(safeMessage);
  } finally {
    clearSensitiveText();
  }
}

function parseFunctionTestSecretMappings(flags, declaredRefs) {
  const raw = flags['secret-from-env'];
  const declared = new Map(declaredRefs.map(ref => [ref.name, ref]));
  const mappings = new Map();
  for (const entry of splitList(raw)) {
    const separator = entry.indexOf('=');
    const name = separator > 0 ? entry.slice(0, separator).trim() : '';
    const envName = separator > 0 ? entry.slice(separator + 1).trim() : '';
    if (!name || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(envName)) {
      fail(
        `function test --secret-from-env 格式必须为 logical=ENV_NAME: ${entry}`
      );
    }
    if (!declared.has(name)) {
      const error = new Error(
        `FUNCTION_SECRET_REF_UNDECLARED: Function manifest 未声明 secretRef ${name}`
      );
      error.code = 'FUNCTION_SECRET_REF_UNDECLARED';
      throw error;
    }
    if (mappings.has(name)) {
      fail(`function test 重复声明 --secret-from-env ${name}`);
    }
    mappings.set(name, envName);
  }
  for (const ref of declaredRefs) {
    const envName = mappings.get(ref.name);
    if (!envName) {
      if (ref.required) {
        const error = new Error(
          `FUNCTION_SECRET_NOT_CONFIGURED: required secretRef ${ref.name} 缺少 --secret-from-env ${ref.name}=ENV_NAME`
        );
        error.code = 'FUNCTION_SECRET_NOT_CONFIGURED';
        throw error;
      }
      continue;
    }
  }
  return mappings;
}

function readFunctionTestSecretsFromEnv(mappings, declaredRefs) {
  const secrets = {};
  for (const ref of declaredRefs) {
    const envName = mappings.get(ref.name);
    if (!envName) continue;
    if (!Object.prototype.hasOwnProperty.call(process.env, envName)) {
      const error = new Error(
        `FUNCTION_SECRET_NOT_CONFIGURED: 测试父进程未设置环境变量 ${envName}（secretRef ${ref.name}）`
      );
      error.code = 'FUNCTION_SECRET_NOT_CONFIGURED';
      throw error;
    }
    secrets[ref.name] = String(process.env[envName]);
  }
  return secrets;
}

function resolveFunctionTestSource(functionItem, functionCode) {
  const definition = resolveManifestPlainJson(
    functionItem,
    'definitionJson',
    'definitionFile'
  );
  const localPath = definition?.sourceFile?.localPath;
  if (!localPath) {
    fail(`Function:${functionCode} 缺少 definitionJson.sourceFile.localPath`);
  }
  const fromManifest = path.resolve(functionItem.__dir || process.cwd(), localPath);
  const fromWorkspace = path.resolve(process.cwd(), localPath);
  const sourcePath = fs.existsSync(fromManifest) ? fromManifest : fromWorkspace;
  if (!fs.existsSync(sourcePath)) {
    fail(`Function:${functionCode} sourceFile 不存在: ${localPath}`);
  }
  return { definition, sourcePath };
}

function isolatedAppFunctionTestBuildRunner() {
  const { builtinModules } = require('module');
  const fs = require('fs');
  const path = require('path');
  const esbuild = require(process.argv[1]);
  const sourcePath = process.argv[2];
  const outfile = process.argv[3];
  const workspaceRoot = process.argv[4];
  const resolveWorkspaceAlias = importPath => {
    const raw = path.join(workspaceRoot, 'src', importPath.replace(/^@\//, ''));
    const candidates = [
      raw,
      `${raw}.ts`,
      `${raw}.tsx`,
      `${raw}.js`,
      `${raw}.mjs`,
      `${raw}.cjs`,
      path.join(raw, 'index.ts'),
      path.join(raw, 'index.tsx'),
      path.join(raw, 'index.js'),
    ];
    return candidates.find(candidate => fs.existsSync(candidate)) || raw;
  };
  const external = Array.from(
    new Set([...builtinModules, ...builtinModules.map(name => `node:${name}`)])
  );
  esbuild
    .build({
      entryPoints: [sourcePath],
      outfile,
      bundle: true,
      platform: 'node',
      format: 'cjs',
      target: ['node20'],
      sourcemap: false,
      logLevel: 'silent',
      external,
      plugins: [
        {
          name: 'openxiangda-function-test-workspace-alias',
          setup(build) {
            build.onResolve({ filter: /^@\// }, args => ({
              path: resolveWorkspaceAlias(args.path),
            }));
          },
        },
      ],
    })
    .catch(error => {
      process.stderr.write(String(error?.message || error));
      process.exitCode = 1;
    });
}

async function buildIsolatedFunctionTestBundle(
  sourcePath,
  workspaceRoot,
  functionCode,
  tempRoot
) {
  const outfile = path.join(tempRoot, 'bundle', `${functionCode}.cjs`);
  fs.mkdirSync(path.dirname(outfile), { recursive: true });
  const build = spawnSync(
    process.execPath,
    [
      '-e',
      `(${isolatedAppFunctionTestBuildRunner.toString()})()`,
      require.resolve('esbuild'),
      sourcePath,
      outfile,
      workspaceRoot,
    ],
    {
      cwd: tempRoot,
      env: stripUndefinedValues({
        PATH: process.env.PATH,
        NODE_ENV: 'test-build',
        HOME: tempRoot,
        USERPROFILE: tempRoot,
        TMPDIR: tempRoot,
      }),
      encoding: 'utf8',
      maxBuffer: 8 * 1024 * 1024,
      timeout: 30000,
      killSignal: 'SIGKILL',
    }
  );
  if (build.error || build.status !== 0 || !fs.existsSync(outfile)) {
    fail(
      `App Function 隔离测试构建失败: ${functionCode}: ${
        build.error?.message || build.stderr || build.stdout || 'unknown error'
      }`
    );
  }
  return outfile;
}

function isolatedAppFunctionTestRunner() {
  const fs = require('fs');
  const payload = JSON.parse(fs.readFileSync(0, 'utf8'));
  const secretValues = Object.values(payload.secrets || {}).map(String);
  const secretVariants = Array.from(
    new Set(
      secretValues.flatMap(secret => {
        const bytes = Buffer.from(secret, 'utf8');
        const jsonEscaped = JSON.stringify(secret).slice(1, -1);
        const base64 = bytes.toString('base64');
        return [
          secret,
          jsonEscaped,
          encodeURIComponent(secret),
          base64,
          base64.replace(/=+$/g, ''),
          bytes.toString('base64url'),
          bytes.toString('hex'),
        ].filter(Boolean);
      })
    )
  ).sort((left, right) => right.length - left.length);
  let exfiltrationDetected = false;
  const containsSecretVariant = (value, seen = new WeakSet()) => {
    const renderings = [];
    if (Buffer.isBuffer(value)) {
      renderings.push(value.toString('utf8'), value.toString('base64'), value.toString('hex'));
    } else if (typeof value === 'string') {
      renderings.push(value);
    } else if (ArrayBuffer.isView(value)) {
      const bytes = Buffer.from(value.buffer, value.byteOffset, value.byteLength);
      renderings.push(bytes.toString('utf8'), bytes.toString('base64'), bytes.toString('hex'));
    } else if (!value || typeof value !== 'object') {
      renderings.push(String(value));
    }
    if (
      renderings.some(rendered =>
        secretVariants.some(variant => variant && String(rendered).includes(variant))
      )
    ) {
      return true;
    }
    if (!value || typeof value !== 'object' || seen.has(value)) return false;
    seen.add(value);
    const children = Array.isArray(value) ? value : Object.values(value);
    if (value instanceof Error) {
      children.push(value.name, value.message, value.stack, value.code, value.cause);
    }
    return children.some(child => containsSecretVariant(child, seen));
  };
  const redactString = value => {
    let result = String(value);
    for (const variant of secretVariants) {
      if (variant) result = result.split(variant).join('***secret***');
    }
    return result;
  };
  const sanitize = (value, seen = new WeakSet()) => {
    if (typeof value === 'string') return redactString(value);
    if (!value || typeof value !== 'object') return value;
    if (seen.has(value)) return '[Circular]';
    seen.add(value);
    if (Array.isArray(value)) return value.map(item => sanitize(item, seen));
    return Object.fromEntries(
      Object.entries(value).map(([key, child]) => [key, sanitize(child, seen)])
    );
  };
  const renderLog = values => {
    if (values.some(containsSecretVariant)) exfiltrationDetected = true;
    return redactString(
      values
        .map(value =>
          typeof value === 'string' ? value : JSON.stringify(sanitize(value))
        )
        .join(' ')
    );
  };
  const safeConsole = Object.freeze({
    log: (...values) => process.stderr.write(`${renderLog(values)}\n`),
    info: (...values) => process.stderr.write(`${renderLog(values)}\n`),
    warn: (...values) => process.stderr.write(`${renderLog(values)}\n`),
    error: (...values) => process.stderr.write(`${renderLog(values)}\n`),
    debug: (...values) => process.stderr.write(`${renderLog(values)}\n`),
  });
  global.console = safeConsole;
  const declaredNames = new Set(
    (payload.secretRefs || []).map(item => String(item.name || ''))
  );
  const secrets = Object.freeze({
    get: async name => {
      const normalized = String(name || '');
      if (!declaredNames.has(normalized)) {
        const error = new Error(`Function secretRef is not declared: ${normalized}`);
        error.code = 'FUNCTION_SECRET_REF_UNDECLARED';
        error.status = 403;
        throw error;
      }
      if (!Object.prototype.hasOwnProperty.call(payload.secrets || {}, normalized)) {
        const error = new Error(`Function secret is not configured: ${normalized}`);
        error.code = 'FUNCTION_SECRET_NOT_CONFIGURED';
        error.status = 424;
        throw error;
      }
      return String(payload.secrets[normalized]);
    },
  });
  const logger = Object.freeze({
    debug: safeConsole.debug,
    info: safeConsole.info,
    warn: safeConsole.warn,
    error: safeConsole.error,
  });
  Promise.resolve()
    .then(() => {
      const loaded = require(process.argv[1]);
      const execute = loaded?.default || loaded;
      if (typeof execute !== 'function') {
        const error = new Error('App Function module must export a function');
        error.code = 'APP_FUNCTION_TEST_EXPORT_INVALID';
        throw error;
      }
      const context = Object.freeze({
        input: payload.input,
        secrets,
        logger,
        console: safeConsole,
      });
      return execute(context, payload.input);
    })
    .then(result => {
      if (containsSecretVariant(result) || exfiltrationDetected) {
        const error = new Error('App Function attempted to expose a secret');
        error.code = 'APP_SECRET_EXFILTRATION_BLOCKED';
        error.status = 500;
        throw error;
      }
      process.stdout.write(
        JSON.stringify({ ok: true, result: sanitize(result) })
      );
    })
    .catch(error => {
      const errorCode = String(error?.code || '');
      const blocked =
        error?.code === 'APP_SECRET_EXFILTRATION_BLOCKED' ||
        exfiltrationDetected ||
        containsSecretVariant(error);
      const safeErrorCode = /^[A-Z][A-Z0-9_]{0,127}$/.test(errorCode)
        ? errorCode
        : 'APP_FUNCTION_TEST_FAILED';
      process.stdout.write(
        JSON.stringify({
          ok: false,
          error: {
            code: blocked
              ? 'APP_SECRET_EXFILTRATION_BLOCKED'
              : safeErrorCode,
            status: blocked ? 500 : error?.status,
            message: blocked
              ? 'App Function secret exfiltration was blocked'
              : redactString(error?.message || String(error)),
          },
        })
      );
      process.exitCode = 1;
    });
}

async function testAppFunctionLocally(positional, flags = {}) {
  rejectUnsafeSecretValueFlags(flags);
  const functionCode = resolveExactSecretName(
    positional,
    flags,
    'function test'
  );
  const typeFilters = new Set(['functions']);
  const codeFilters = [{ key: 'functions', code: functionCode, raw: functionCode }];
  const manifest = loadWorkspaceResources({ typeFilters, codeFilters });
  if (
    flags['stage-only'] &&
    (manifest.functions || []).length + (manifest.automations || []).length === 0
  ) {
    fail('--stage-only 没有匹配到可冻结的 Function/Automation 资源');
  }
  const validation = validateWorkspaceResources(manifest);
  if (validation.errors.length > 0) {
    fail(`Function:${functionCode} 本地 manifest 校验失败: ${validation.errors[0]}`);
  }
  const functionItem = manifest.functions?.[0];
  if (!functionItem) fail(`未找到 Function manifest: ${functionCode}`);
  const secretRefs = functionManifestDeclaresSecretRefs(functionItem)
    ? normalizeFunctionSecretRefs(functionItem.secretRefs)
    : [];
  const secretMappings = parseFunctionTestSecretMappings(flags, secretRefs);
  const input = flags['input-json']
    ? readJsonArg(flags['input-json'], 'input-json')
    : {};
  const { sourcePath } = resolveFunctionTestSource(
    functionItem,
    functionCode
  );
  const workspaceRoot = findWorkspaceRoot(sourcePath);
  const tempRoot = fs.mkdtempSync(
    path.join(os.tmpdir(), 'openxiangda-function-test-')
  );
  try {
    const bundlePath = await buildIsolatedFunctionTestBundle(
      sourcePath,
      workspaceRoot,
      functionCode,
      tempRoot
    );
    const secrets = readFunctionTestSecretsFromEnv(
      secretMappings,
      secretRefs
    );
    for (const value of Object.values(secrets)) registerSensitiveText(value);
    const child = spawnSync(
      process.execPath,
      ['-e', `(${isolatedAppFunctionTestRunner.toString()})()`, bundlePath],
      {
        cwd: tempRoot,
        env: stripUndefinedValues({
          PATH: process.env.PATH,
          NODE_ENV: 'test',
          HOME: tempRoot,
          USERPROFILE: tempRoot,
          TMPDIR: tempRoot,
        }),
        input: JSON.stringify({ input, secretRefs, secrets }),
        encoding: 'utf8',
        maxBuffer: 8 * 1024 * 1024,
        timeout: Number(flags.timeout || 30000),
        killSignal: 'SIGKILL',
      }
    );
    if (child.error) {
      const error = new Error(
        `APP_FUNCTION_SECRET_UNAVAILABLE: 隔离测试子进程失败: ${child.error.message}`
      );
      error.code = 'APP_FUNCTION_SECRET_UNAVAILABLE';
      throw error;
    }
    if (child.stderr) process.stderr.write(maskText(child.stderr));
    let output;
    try {
      output = JSON.parse(String(child.stdout || '{}'));
    } catch (error) {
      fail(`App Function 隔离测试输出无法解析: ${error.message}`);
    }
    const result = {
      ...output,
      functionCode,
      runtimeContractVersion: secretRefs.length
        ? APP_FUNCTION_SECRET_CAPABILITIES.runtimeContractVersion
        : 'trusted_node_v1_compat',
      isolated: true,
      workspaceWrites: 0,
      secretValuesPersisted: false,
    };
    if (flags.json) writeJson(result);
    else print(JSON.stringify(result, null, 2));
    if (child.status !== 0 || output.ok === false) {
      const error = new Error(
        `${output.error?.code || 'APP_FUNCTION_TEST_FAILED'}: ${output.error?.message || 'App Function local test failed'}`
      );
      error.code = output.error?.code || 'APP_FUNCTION_TEST_FAILED';
      throw error;
    }
    return result;
  } finally {
    fs.rmSync(tempRoot, { recursive: true, force: true });
    clearSensitiveText();
  }
}

async function connector(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print('用法: openxiangda connector list|get|create|update|upsert|delete|invoke|download-test [connectorCode[.apiCode]] [--json-file file]');
    return;
  }
  const config = loadConfig();
  const target = getWorkspaceTarget(config, flags.profile || config.currentProfile, flags);

  if (subcommand === 'invoke' || subcommand === 'download-test') {
    const targetName = positional[0] || flags.connector;
    if (!targetName) fail(`用法: openxiangda connector ${subcommand} <connectorCode.apiCode> [--body-json file|json]`);
    const parsed = parseConnectorApiName(targetName, flags);
    const body = {
      connector: parsed.connector,
      api: parsed.api,
      ...readDirectJsonBody(flags, 'connector invoke', { optional: true }),
      ...(flags['path-params-json'] ? { pathParams: readJsonArg(flags['path-params-json'], 'path-params-json') } : {}),
      ...(flags['query-json'] ? { query: readJsonArg(flags['query-json'], 'query-json') } : {}),
      ...(flags['headers-json'] ? { headers: readJsonArg(flags['headers-json'], 'headers-json') } : {}),
      ...(flags['request-body-type'] ? { requestBodyType: flags['request-body-type'] } : {}),
      ...(flags['response-type'] ? { responseType: flags['response-type'] } : {}),
    };
    if (subcommand === 'download-test') body.responseType = 'binary';
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `/${encodeURIComponent(target.appType)}/v1/connectors/actions/${subcommand === 'download-test' ? 'download' : 'invoke'}`,
      body,
      strictEnvelope: subcommand !== 'download-test',
    }, { controlPlaneMutation: false });
  }

  return directResourceCrud(config, target, {
    commandName: 'connector',
    subcommand,
    flags,
    positional,
    resourceType: 'connector',
    basePath: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/connectors`,
    manifestDir: path.join('src', 'resources', 'connectors'),
    createMethod: 'POST',
    createPath: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/connectors/actions/sync`,
    createBody: body => ({ connectors: [normalizeConnectorManifest(body)] }),
    updateMethod: 'POST',
    updatePath: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/connectors/actions/sync`,
    updateBody: body => ({ connectors: [normalizeConnectorManifest(body)] }),
    normalizeBody: body => normalizeConnectorManifest(body),
    codeOf: body => body.code || body.methodName,
    responseData: data => Array.isArray(data?.data) ? data.data[0] : data,
    saveState: (code, data) => saveConnectorResource(target, code, data?.connector?.id || data?.id, {
      apis: Object.fromEntries(
        (data?.apis || []).map(api => [api.code || api.methodName, { apiId: api.id, name: api.name }])
      ),
    }),
  });
}

async function notification(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda notification template-list|template-get|template-upsert|template-delete|type-list|type-get|type-upsert|type-delete|preview|send|batch-send|capabilities|dingding-preview|dingding-send',
      '  preview <notificationType|templateCode> [--form-code code|--form-uuid FORM_XXX] --body-json \'{"payload":{"title":"测试"}}\'',
      '  send <notificationType> --body-json \'{"recipientId":"USER_ID","payload":{"title":"测试"}}\' --force',
      '  batch-send <notificationType> --body-json \'{"recipients":[{"recipientId":"USER_ID","payload":{}}]}\' --force',
      '  capabilities --json',
      '  dingding-preview <notificationType> [--template-code code|--template-id id] --body-json \'{"payload":{"title":"测试"}}\'',
      '  dingding-send <notificationType> --body-json \'{"recipientId":"USER_ID","payload":{"title":"测试"}}\' --force',
    ].join('\n'));
    return;
  }
  const config = loadConfig();
  const target = getWorkspaceTarget(config, flags.profile || config.currentProfile, flags);
  const appPrefix = `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications`;

  if (subcommand === 'template-list') {
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: apiPathWithQuery(`${appPrefix}/templates`, { page: flags.page, pageSize: flags['page-size'] || flags.limit }),
    });
  }
  if (subcommand === 'template-get') {
    const code = positional[0] || flags.code;
    if (!code) fail('用法: openxiangda notification template-get <templateCode>');
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${appPrefix}/templates/${encodeURIComponent(code)}`,
    });
  }
  if (subcommand === 'template-upsert') {
    const body = readDirectJsonBody(flags, 'notification template');
    const template = extractNotificationTemplateBody(target.bound, body);
    const code = positional[0] || body.code || body.templateCode || template.code;
    if (!code) fail('notification template-upsert 缺少 template code');
    const normalized = normalizeNotificationTemplateManifest(target.bound, { ...body, ...template, code });
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/templates/${encodeURIComponent(code)}`,
      body: normalized,
    }, { returnData: true });
    if (!flags['dry-run'] && data?.id) {
      saveNotificationTemplateResource(target, code, data.id, {
        level: data.level || normalized.level,
        formUuid: data.formUuid || normalized.formUuid,
      });
      if (flags['write-manifest']) writeDirectManifest('notification', code, { ...body, code, resourceType: 'template' });
    }
    return outputDirectResult(data, flags);
  }
  if (subcommand === 'template-delete') {
    const code = positional[0] || flags.code;
    if (!code || !flags.force) fail('用法: openxiangda notification template-delete <templateCode> --force');
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: apiPathWithPostDeleteAction(`${appPrefix}/templates/${encodeURIComponent(code)}`),
    });
  }
  if (subcommand === 'type-list') {
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: apiPathWithQuery(`${appPrefix}/type-configs`, { page: flags.page, pageSize: flags['page-size'] || flags.limit }),
    });
  }
  if (subcommand === 'type-get') {
    const code = positional[0] || flags.code;
    if (!code) fail('用法: openxiangda notification type-get <notificationType>');
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${appPrefix}/type-configs/${encodeURIComponent(code)}`,
    });
  }
  if (subcommand === 'type-upsert') {
    const body = readDirectJsonBody(flags, 'notification type-config');
    const configBody = extractNotificationTypeConfigBody(target.bound, body);
    const code = positional[0] || body.notificationType || configBody.notificationType;
    if (!code) fail('notification type-upsert 缺少 notificationType');
    const normalized = normalizeNotificationTypeConfigManifest(target.bound, { ...body, ...configBody, notificationType: code });
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/type-configs/${encodeURIComponent(code)}`,
      body: normalized,
    }, { returnData: true });
    if (!flags['dry-run'] && data?.id) {
      saveNotificationTypeConfigResource(target, body.code || code, data.id, {
        notificationType: data.notificationType || code,
        level: data.level || normalized.level,
        formUuid: data.formUuid || normalized.formUuid,
        templateId: data.templateId,
        templateCode: data.template?.code || body.templateCode,
      });
      if (flags['write-manifest']) writeDirectManifest('notification', body.code || code, { ...body, notificationType: code, resourceType: 'typeConfig' });
    }
    return outputDirectResult(data, flags);
  }
  if (subcommand === 'type-delete') {
    const code = positional[0] || flags.code;
    if (!code || !flags.force) fail('用法: openxiangda notification type-delete <notificationType> --force');
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: apiPathWithPostDeleteAction(`${appPrefix}/type-configs/${encodeURIComponent(code)}`),
    });
  }
  if (subcommand === 'capabilities') {
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${appPrefix}/dingtalk/capabilities`,
      strictEnvelope: true,
    });
  }
  if (subcommand === 'dingding-preview' || subcommand === 'dingding-send') {
    if (subcommand === 'dingding-send' && !flags.force) {
      fail('openxiangda notification dingding-send 是发送动作，必须加 --force');
    }
    const code = positional[0] || flags.code;
    const rawBody = readDirectJsonBody(flags, `notification ${subcommand}`, { optional: true });
    const body = buildDingTalkNotificationActionBody(target, code, rawBody, flags);
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/dingtalk/${subcommand === 'dingding-send' ? 'send' : 'preview'}`,
      body,
      strictEnvelope: true,
    }, { controlPlaneMutation: false });
  }
  if (['preview', 'send', 'batch-send'].includes(subcommand)) {
    if ((subcommand === 'send' || subcommand === 'batch-send') && !flags.force) {
      fail(`openxiangda notification ${subcommand} 是发送动作，必须加 --force`);
    }
    const code = positional[0] || flags.code;
    const rawBody = readDirectJsonBody(flags, `notification ${subcommand}`, { optional: true });
    const body =
      subcommand === 'preview'
        ? await normalizeNotificationPreviewBody(config, target, code, rawBody, flags)
        : normalizeNotificationActionBody(subcommand, code, rawBody);
    const actionPath =
      subcommand === 'preview'
        ? 'templates/preview'
        : subcommand === 'batch-send'
          ? 'batch-send-by-type'
          : 'send-by-type';
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/${actionPath}`,
      body,
      strictEnvelope: true,
    }, { controlPlaneMutation: false });
  }

  fail('用法: openxiangda notification template-list|template-get|template-upsert|template-delete|type-list|type-get|type-upsert|type-delete|preview|send|batch-send|capabilities|dingding-preview|dingding-send');
}

async function organization(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda organization capabilities|department-list|department-get|department-create|department-update|account-list|account-get|account-create|account-update|account-reset-password',
      '  capabilities --json',
      '  department-list --json',
      '  department-get <departmentId> --json',
      '  department-create --body-json \'{"name":"销售部"}\' --force',
      '  department-update <departmentId> --body-json \'{"name":"华东销售"}\' --force',
      '  account-list [--keyword text|--department-ids id1,id2] --json',
      '  account-get <userId> --json',
      '  account-create --body-json \'{"username":"u1","password":"P@ssw0rd","name":"张三"}\' --force',
      '  account-update <userId> --body-json \'{"name":"张三"}\' --force',
      '  account-reset-password <userId> --body-json \'{"newPassword":"P@ssw0rd"}\' --force',
    ].join('\n'));
    return;
  }

  const config = loadConfig();
  const target = getWorkspaceTarget(config, flags.profile || config.currentProfile, flags);
  const appPrefix = `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/organization`;

  if (subcommand === 'capabilities') {
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${appPrefix}/capabilities`,
      strictEnvelope: true,
    });
  }

  if (subcommand === 'department-list') {
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${appPrefix}/departments`,
      strictEnvelope: true,
    });
  }

  if (subcommand === 'department-get') {
    const departmentId = positional[0] || flags['department-id'] || flags.id;
    if (!departmentId) fail('用法: openxiangda organization department-get <departmentId>');
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${appPrefix}/departments/${encodeURIComponent(departmentId)}`,
      strictEnvelope: true,
    });
  }

  if (subcommand === 'department-create') {
    if (!flags.force) fail('openxiangda organization department-create 是写操作，必须加 --force');
    const body = readDirectJsonBody(flags, 'organization department-create');
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/departments`,
      body,
      strictEnvelope: true,
    }, { controlPlaneMutation: false });
  }

  if (subcommand === 'department-update') {
    if (!flags.force) fail('openxiangda organization department-update 是写操作，必须加 --force');
    const departmentId = positional[0] || flags['department-id'] || flags.id;
    if (!departmentId) fail('用法: openxiangda organization department-update <departmentId> --body-json ... --force');
    const body = readDirectJsonBody(flags, 'organization department-update');
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/departments/${encodeURIComponent(departmentId)}`,
      body,
      strictEnvelope: true,
    }, { controlPlaneMutation: false });
  }

  if (subcommand === 'account-list') {
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: apiPathWithQuery(`${appPrefix}/accounts`, {
        ids: flags.ids,
        departmentIds: flags['department-ids'],
        keyword: flags.keyword,
        name: flags.name,
        username: flags.username,
        phone: flags.phone,
        email: flags.email,
        jobNumber: flags['job-number'],
        page: flags.page,
        pageSize: flags['page-size'] || flags.limit,
      }),
      strictEnvelope: true,
    });
  }

  if (subcommand === 'account-get') {
    const userId = positional[0] || flags['user-id'] || flags.id;
    if (!userId) fail('用法: openxiangda organization account-get <userId>');
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${appPrefix}/accounts/${encodeURIComponent(userId)}`,
      strictEnvelope: true,
    });
  }

  if (subcommand === 'account-create') {
    if (!flags.force) fail('openxiangda organization account-create 是写操作，必须加 --force');
    const body = readDirectJsonBody(flags, 'organization account-create');
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/accounts`,
      body,
      strictEnvelope: true,
    }, { controlPlaneMutation: false });
  }

  if (subcommand === 'account-update') {
    if (!flags.force) fail('openxiangda organization account-update 是写操作，必须加 --force');
    const userId = positional[0] || flags['user-id'] || flags.id;
    if (!userId) fail('用法: openxiangda organization account-update <userId> --body-json ... --force');
    const body = readDirectJsonBody(flags, 'organization account-update');
    if (Object.prototype.hasOwnProperty.call(body || {}, 'password')) {
      fail('account-update 不允许包含 password，请使用 account-reset-password');
    }
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/accounts/${encodeURIComponent(userId)}`,
      body,
      strictEnvelope: true,
    }, { controlPlaneMutation: false });
  }

  if (subcommand === 'account-reset-password') {
    if (!flags.force) fail('openxiangda organization account-reset-password 是密码写操作，必须加 --force');
    const userId = positional[0] || flags['user-id'] || flags.id;
    if (!userId) fail('用法: openxiangda organization account-reset-password <userId> --body-json ... --force');
    const body = readDirectJsonBody(flags, 'organization account-reset-password');
    if (!body.newPassword) fail('account-reset-password body 缺少 newPassword');
    return runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `${appPrefix}/accounts/${encodeURIComponent(userId)}/password/reset`,
      body,
      strictEnvelope: true,
    }, { controlPlaneMutation: false });
  }

  fail('用法: openxiangda organization capabilities|department-list|department-get|department-create|department-update|account-list|account-get|account-create|account-update|account-reset-password');
}

function buildDingTalkNotificationActionBody(target, code, rawBody = {}, flags = {}) {
  const body = { ...(rawBody || {}) };
  if (flags['template-code'] && !body.templateCode) body.templateCode = flags['template-code'];
  if (flags['template-id'] && !body.templateId) body.templateId = flags['template-id'];
  if (code && !body.notificationType && !body.templateCode && !body.templateId && !body.code) {
    body.notificationType = code;
  }
  const formUuid =
    body.formUuid ||
    flags['form-uuid'] ||
    resolveOptionalFormUuid(target.bound, body.formCode || flags['form-code']);
  if (formUuid) body.formUuid = formUuid;
  delete body.formCode;
  return body;
}

async function normalizeNotificationPreviewBody(config, target, code, rawBody = {}, flags = {}) {
  const body = normalizeNotificationActionBody('preview', code, rawBody);
  const rawHasTemplate =
    rawBody?.templateCode || rawBody?.templateId || rawBody?.code;
  if (!code || rawHasTemplate) return body;

  const resolvedConfig = await resolveNotificationTypeConfigForPreview(
    config,
    target,
    code,
    rawBody,
    flags
  );
  if (!resolvedConfig) return body;

  delete body.templateCode;
  const templateCode =
    resolvedConfig.template?.code ||
    resolvedConfig.templateCode ||
    resolvedConfig.template?.templateCode;
  if (resolvedConfig.templateId) body.templateId = resolvedConfig.templateId;
  if (templateCode) body.templateCode = templateCode;
  body.notificationType = code;
  return body;
}

async function resolveNotificationTypeConfigForPreview(
  config,
  target,
  notificationType,
  rawBody = {},
  flags = {}
) {
  const formUuid =
    rawBody.formUuid ||
    flags['form-uuid'] ||
    resolveOptionalFormUuid(target.bound, rawBody.formCode || flags['form-code']);
  const data = await requestOptionalWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications/type-configs`,
      {
        page: 1,
        pageSize: 1000,
      }
    )
  );
  const matches = normalizeItems(data).filter(item => {
    if (String(item.notificationType || '') !== String(notificationType || '')) {
      return false;
    }
    if (formUuid) return String(item.formUuid || '') === String(formUuid);
    return true;
  });
  if (matches.length === 0) return null;
  const appLevel = matches.find(item => String(item.level || 'app') === 'app');
  if (!formUuid && appLevel) return appLevel;
  return matches[0];
}

async function permission(args) {
  const [subcommand, ...rest] = args;
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print(
      [
        '用法: openxiangda permission role-list|role-create|role-update|role-delete|role-bind|role-users|role-add-users|page-group-list|page-group-create|page-group-update|page-group-delete|page-group-bind|form-group-list|form-group-create|form-group-update|form-group-delete|form-group-bind|form-summary|menu-permissions|snapshot|audit',
        'role-users/role-add-users 接受角色 code 或 UUID；本地未绑定的 code 会从当前应用角色列表精确解析，找不到或不唯一时显式失败。',
      ].join('\n')
    );
    return;
  }
  const config = loadConfig();
  const profileName = flags.profile || config.currentProfile;

  if (subcommand === 'role-list') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`,
        {
          name: flags.name,
          code: flags.code,
          page: flags.page,
          limit: flags.limit,
        }
      )
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'role-bind') {
    const [roleCode, maybeRoleId] = positional;
    const roleId = flags['role-id'] || maybeRoleId;
    if (!roleCode || !roleId) {
      fail('用法: openxiangda permission role-bind <roleCode> --role-id <id>');
    }
    const target = getWorkspaceTarget(config, profileName, flags);
    saveRoleResource(target, roleCode, roleId);
    print(`已绑定角色 ${roleCode}: ${roleId}`);
    return;
  }

  if (subcommand === 'role-create') {
    const [roleCode] = positional;
    const name = flags.name || positional.slice(1).join(' ') || roleCode;
    if (!roleCode || !name) {
      fail('用法: openxiangda permission role-create <roleCode> --name <text>');
    }
    const target = getWorkspaceTarget(config, profileName, flags);
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`,
      body: {
        code: flags.code || roleCode,
        name,
        description: flags.description || '',
      },
    }, {
      returnData: true,
      mutationLabel: 'permission role-create',
    });
    if (!flags['dry-run'] && data?.id) {
      saveRoleResource(target, roleCode, data.id, {
        code: data.code,
        name: data.name,
      });
    }
    return outputDirectResult(data, flags);
  }

  if (subcommand === 'role-update') {
    const [roleKey] = positional;
    const body = readDirectJsonBody(flags, 'role update');
    const roleCode = roleKey || body.code || body.resourceCode;
    if (!roleCode) fail('用法: openxiangda permission role-update <roleCode|roleId> --json-file file');
    const target = getWorkspaceTarget(config, profileName, flags);
    const roleId = resolveRoleId(target.bound, roleCode, flags);
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles/${encodeURIComponent(roleId)}`,
      body: {
        code: body.code || roleCode,
        name: body.name || roleCode,
        description: body.description || '',
      },
    }, { returnData: true });
    if (!flags['dry-run']) {
      const resultCode = body.code || roleCode;
      if (data?.id) saveRoleResource(target, resultCode, data.id);
      if (flags['write-manifest']) writeDirectManifest('role', resultCode, { ...body, code: resultCode });
    }
    return outputDirectResult(data, flags);
  }

  if (subcommand === 'role-delete') {
    const [roleKey] = positional;
    if (!roleKey || !flags.force) fail('用法: openxiangda permission role-delete <roleCode|roleId> --force');
    const target = getWorkspaceTarget(config, profileName, flags);
    const roleId = resolveRoleId(target.bound, roleKey, flags);
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: apiPathWithPostDeleteAction(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles/${encodeURIComponent(roleId)}`
      ),
    }, { returnData: true });
    if (!flags['dry-run'] && target.bound.resources?.roles?.[roleKey]) {
      delete target.bound.resources.roles[roleKey];
      saveProjectState(target.state);
    }
    return outputDirectResult(data, flags);
  }

  if (subcommand === 'role-users') {
    const [roleKey] = positional;
    if (!roleKey) fail('用法: openxiangda permission role-users <roleCode|roleId>');
    const target = getWorkspaceTarget(config, profileName, flags);
    const roleId = await resolveRoleMembershipIdForCommand(
      config,
      target,
      roleKey,
      flags
    );
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles/${encodeURIComponent(roleId)}/users`,
        {
          keyword: flags.keyword,
          page: flags.page,
          limit: flags.limit,
        }
      )
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'role-add-users') {
    const [roleKey] = positional;
    const userIds = splitList(flags['user-ids']);
    if (!roleKey || userIds.length === 0) {
      fail('用法: openxiangda permission role-add-users <roleCode|roleId> --user-ids <id1,id2>');
    }
    const target = getWorkspaceTarget(config, profileName, flags);
    const roleId = await resolveRoleMembershipIdForCommand(
      config,
      target,
      roleKey,
      flags
    );
    await ensureDirectMutationPublishContext(config, target, flags, 'permission role-add-users');
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles/${encodeURIComponent(roleId)}/users`,
      {
        method: 'POST',
        body: { userIds },
      }
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'page-group-list') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups`,
        {
          name: flags.name,
          page: flags.page,
          limit: flags.limit,
        }
      )
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'page-group-bind') {
    const [groupCode, maybeGroupId] = positional;
    const groupId = flags['group-id'] || maybeGroupId;
    if (!groupCode || !groupId) {
      fail('用法: openxiangda permission page-group-bind <groupCode> --group-id <id>');
    }
    const target = getWorkspaceTarget(config, profileName, flags);
    savePagePermissionGroupResource(target, groupCode, groupId);
    print(`已绑定页面权限组 ${groupCode}: ${groupId}`);
    return;
  }

  if (subcommand === 'page-group-create') {
    const [groupCode] = positional;
    const name = flags.name || positional.slice(1).join(' ') || groupCode;
    if (!groupCode || !name) {
      fail('用法: openxiangda permission page-group-create <groupCode> --name <text> [--menu-codes <menuCode...>|--route-codes <routeCode...>|--path-patterns <pattern...>|--page-codes <pageCode...>|--form-codes <formCode...>|--menu-ids <id...>] [--no-runtime-aliases]');
    }
    const target = getWorkspaceTarget(config, profileName, flags);
    const roles = splitList(flags.roles);
    const editableTargets = resolvePagePermissionMenuTargets(target.bound, flags);
    const menuCodes = splitList(flags['menu-codes']);
    const routeCodes = splitList(flags['route-codes']);
    const pathPatterns = splitList(flags['path-patterns']);
    const runtimeAliasTargets = flags['no-runtime-aliases']
      ? []
      : resolvePagePermissionRuntimeAliasTargets(target.bound, flags);
    await ensureDirectMutationPublishContext(config, target, flags, 'permission page-group-create');
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups`,
      {
        method: 'POST',
        body: {
          name,
          roles,
          menuFormUuids: editableTargets,
          menuCodes,
          routeCodes,
          pathPatterns,
        },
      }
    );
    if (data?.id) savePagePermissionGroupResource(target, groupCode, data.id, { name });
    let runtimeAliasData = null;
    if (runtimeAliasTargets.length > 0) {
      const runtimeAliasName = `${name}（运行时别名）`;
      runtimeAliasData = await requestWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups`,
        {
          method: 'POST',
          body: {
            name: runtimeAliasName,
            roles,
            menuFormUuids: runtimeAliasTargets,
          },
        }
      );
      if (runtimeAliasData?.id) {
        savePagePermissionGroupResource(target, `${groupCode}__runtime_aliases`, runtimeAliasData.id, {
          name: runtimeAliasName,
        });
      }
    }
    const output = runtimeAliasData
      ? { editableGroup: data, runtimeAliasGroup: runtimeAliasData }
      : data;
    if (flags.json) return writeJson(output);
    print(JSON.stringify(output, null, 2));
    return;
  }

  if (subcommand === 'page-group-update') {
    const [groupKey] = positional;
    const body = readDirectJsonBody(flags, 'page permission group update');
    const groupCode = groupKey || body.code || body.resourceCode;
    if (!groupCode) fail('用法: openxiangda permission page-group-update <groupCode|groupId> --json-file file');
    const target = getWorkspaceTarget(config, profileName, flags);
    const groupId = flags['group-id'] || target.bound.resources?.pagePermissionGroups?.[groupCode]?.groupId || groupCode;
    const normalized = normalizePagePermissionGroupDirectBody(target.bound, { ...body, code: body.code || groupCode });
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups/${encodeURIComponent(groupId)}`,
      body: normalized,
    }, { returnData: true });
    if (!flags['dry-run']) {
      if (data?.id) savePagePermissionGroupResource(target, body.code || groupCode, data.id, { name: data.name, resourceCode: body.code || groupCode });
      if (flags['write-manifest']) writeDirectManifest('page-permission-group', body.code || groupCode, { ...body, code: body.code || groupCode });
    }
    return outputDirectResult(data, flags);
  }

  if (subcommand === 'page-group-delete') {
    const [groupKey] = positional;
    if (!groupKey || !flags.force) fail('用法: openxiangda permission page-group-delete <groupCode|groupId> --force');
    const target = getWorkspaceTarget(config, profileName, flags);
    const groupId = flags['group-id'] || target.bound.resources?.pagePermissionGroups?.[groupKey]?.groupId || groupKey;
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: apiPathWithPostDeleteAction(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups/${encodeURIComponent(groupId)}`
      ),
    }, { returnData: true });
    if (!flags['dry-run'] && target.bound.resources?.pagePermissionGroups?.[groupKey]) {
      delete target.bound.resources.pagePermissionGroups[groupKey];
      saveProjectState(target.state);
    }
    return outputDirectResult(data, flags);
  }

  if (subcommand === 'form-group-list') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = flags['form-uuid'] || resolveOptionalFormUuid(target.bound, flags['form-code']);
    if (!formUuid) {
      fail('用法: openxiangda permission form-group-list --form-code <formCode>|--form-uuid <FORM_XXX>');
    }
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-groups`,
        {
          type: flags.type,
          name: flags.name,
          page: flags.page,
          limit: flags.limit,
        }
      )
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'form-group-bind') {
    const [groupCode, maybeGroupId] = positional;
    const groupId = flags['group-id'] || maybeGroupId;
    if (!groupCode || !groupId) {
      fail('用法: openxiangda permission form-group-bind <groupCode> --group-id <id>');
    }
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = flags['form-uuid'] || resolveOptionalFormUuid(target.bound, flags['form-code']);
    saveFormPermissionGroupResource(target, groupCode, groupId, { formUuid });
    print(`已绑定表单权限组 ${groupCode}: ${groupId}`);
    return;
  }

  if (subcommand === 'form-group-create') {
    const [groupCode] = positional;
    const name = flags.name || positional.slice(1).join(' ') || groupCode;
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = flags['form-uuid'] || resolveOptionalFormUuid(target.bound, flags['form-code']);
    if (!groupCode || !name || !formUuid) {
      fail('用法: openxiangda permission form-group-create <groupCode> --form-code <formCode>|--form-uuid <FORM_XXX> --name <text> --type <submit|view> [--field-access-policy-json <file|json>]');
    }
    await ensureDirectMutationPublishContext(config, target, flags, 'permission form-group-create');
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-groups`,
      {
        method: 'POST',
        body: {
          name,
          type: flags.type || 'view',
          roles: splitList(flags.roles),
          operations: splitList(flags.operations),
          ...(flags['data-scope-json']
            ? { dataScope: readJsonArg(flags['data-scope-json'], 'data-scope-json') }
            : {}),
          ...(flags['field-permissions-json']
            ? {
                fieldPermissions: readJsonArg(
                  flags['field-permissions-json'],
                  'field-permissions-json'
                ),
              }
            : {}),
          ...(flags['field-access-policy-json']
            ? {
                fieldAccessPolicy: readJsonArg(
                  flags['field-access-policy-json'],
                  'field-access-policy-json'
                ),
              }
            : {}),
          ...(flags['data-permission-json']
            ? {
                dataPermission: readJsonArg(
                  flags['data-permission-json'],
                  'data-permission-json'
                ),
              }
            : {}),
        },
      }
    );
    if (data?.id) {
      saveFormPermissionGroupResource(target, groupCode, data.id, {
        name,
        formUuid,
      });
    }
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'form-group-update') {
    const [groupKey] = positional;
    const body = readDirectJsonBody(flags, 'form permission group update');
    const groupCode = groupKey || body.code || body.resourceCode;
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = flags['form-uuid'] || resolveManifestFormUuid(target.bound, body);
    if (!groupCode || !formUuid) fail('用法: openxiangda permission form-group-update <groupCode|groupId> --form-code code|--form-uuid FORM --json-file file');
    const groupId = flags['group-id'] || target.bound.resources?.formPermissionGroups?.[groupCode]?.groupId || groupCode;
    const normalized = normalizeFormPermissionGroupManifest(target.bound, { ...body, code: body.code || groupCode, formUuid });
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-groups/${encodeURIComponent(groupId)}`,
      body: normalized,
    }, { returnData: true });
    if (!flags['dry-run']) {
      if (data?.id) saveFormPermissionGroupResource(target, body.code || groupCode, data.id, { formUuid, name: data.name, resourceCode: body.code || groupCode });
      if (flags['write-manifest']) writeDirectManifest('form-permission-group', body.code || groupCode, { ...body, code: body.code || groupCode });
    }
    return outputDirectResult(data, flags);
  }

  if (subcommand === 'form-group-delete') {
    const [groupKey] = positional;
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = flags['form-uuid'] || resolveOptionalFormUuid(target.bound, flags['form-code']);
    if (!groupKey || !formUuid || !flags.force) fail('用法: openxiangda permission form-group-delete <groupCode|groupId> --form-code code|--form-uuid FORM --force');
    const groupId = flags['group-id'] || target.bound.resources?.formPermissionGroups?.[groupKey]?.groupId || groupKey;
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: apiPathWithPostDeleteAction(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-groups/${encodeURIComponent(groupId)}`
      ),
    }, { returnData: true });
    if (!flags['dry-run'] && target.bound.resources?.formPermissionGroups?.[groupKey]) {
      delete target.bound.resources.formPermissionGroups[groupKey];
      saveProjectState(target.state);
    }
    return outputDirectResult(data, flags);
  }

  if (subcommand === 'form-summary') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = flags['form-uuid'] || resolveOptionalFormUuid(target.bound, flags['form-code'] || positional[0]);
    if (!formUuid) fail('用法: openxiangda permission form-summary --form-code <formCode>|--form-uuid <FORM_XXX>');
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-summary`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'menu-permissions') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups/user-menu-permissions`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'snapshot') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuids = resolvePermissionSnapshotFormUuids(target.bound, flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/permissions/snapshot`,
      {
        method: 'POST',
        body: {
          formUuids,
          includeRoles: flags['no-roles'] ? false : undefined,
          includePageGroups: flags['no-page-groups'] ? false : undefined,
          includeFormGroups: flags['no-form-groups'] ? false : undefined,
        },
      }
    );
    if (flags.json) return writeJson(data);
    const formGroups = data.formPermissionGroups || {};
    print(
      [
        `Permission snapshot appType=${data.appType || target.appType}`,
        `roles=${Array.isArray(data.roles) ? data.roles.length : 0}`,
        `pageGroups=${Array.isArray(data.pagePermissionGroups) ? data.pagePermissionGroups.length : 0}`,
        `formGroups=${Number(formGroups.total || 0)}`,
      ].join(' ')
    );
    return;
  }

  if (subcommand === 'audit') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const result = await buildPermissionAudit(config, target, flags);
    if (flags.json) return writeJson(result);
    print(JSON.stringify(result, null, 2));
    if (result.errors.length > 0) fail(`permission audit 发现 ${result.errors.length} 个错误`);
    return;
  }

  fail(
    '用法: openxiangda permission role-list|role-create|role-update|role-delete|role-bind|role-users|role-add-users|page-group-list|page-group-create|page-group-update|page-group-delete|page-group-bind|form-group-list|form-group-create|form-group-update|form-group-delete|form-group-bind|form-summary|menu-permissions|snapshot|audit'
  );
}

async function settings(args) {
  const [subcommand, ...rest] = args;
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print(
      '用法: openxiangda settings get|save|indexes|indexes-save|data-management|data-management-save|public-access|public-access-save|public-access-delete'
    );
    return;
  }
  const config = loadConfig();
  const profileName = flags.profile || config.currentProfile;

  if (subcommand === 'get') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/settings`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'save') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    if (!flags['settings-json']) {
      fail('用法: openxiangda settings save <formCode|formUuid> --settings-json <file>');
    }
    await ensureDirectMutationPublishContext(config, target, flags, 'settings save');
    const data = await requestFrozenFormMutation(
      config,
      target,
      formUuid,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/settings`,
      'settings',
      { settings: readJsonArg(flags['settings-json'], 'settings-json') },
      { flags }
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'indexes') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/field-indexes`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'indexes-save') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    if (!flags['indexes-json']) {
      fail('用法: openxiangda settings indexes-save <formCode|formUuid> --indexes-json <file>');
    }
    await ensureDirectMutationPublishContext(config, target, flags, 'settings indexes-save');
    const data = await requestFrozenFormMutation(
      config,
      target,
      formUuid,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/field-indexes`,
      'field-indexes',
      { indexes: readJsonArg(flags['indexes-json'], 'indexes-json') },
      { flags }
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'data-management') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/data-management`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'data-management-save') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    if (!flags['config-json']) {
      fail('用法: openxiangda settings data-management-save <formCode|formUuid> --config-json <file>');
    }
    await ensureDirectMutationPublishContext(
      config,
      target,
      flags,
      'settings data-management-save'
    );
    const data = await requestFrozenFormMutation(
      config,
      target,
      formUuid,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/data-management`,
      'data-management',
      { config: readJsonArg(flags['config-json'], 'config-json') },
      { flags }
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'public-access') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/public-access`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'public-access-save') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    await ensureDirectMutationPublishContext(config, target, flags, 'settings public-access-save');
    const data = await requestFrozenFormMutation(
      config,
      target,
      formUuid,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/public-access`,
      'public-access',
      {
        isPublic: flags.public === undefined ? true : String(flags.public) !== 'false',
        description: flags.description || '',
      },
      { flags }
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'public-access-delete') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    await ensureDirectMutationPublishContext(config, target, flags, 'settings public-access-delete');
    const data = await requestFrozenFormMutation(
      config,
      target,
      formUuid,
      apiPathWithPostDeleteAction(
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/public-access`
      ),
      'public-access-delete',
      {},
      { flags }
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  fail(
    '用法: openxiangda settings get|save|indexes|indexes-save|data-management|data-management-save|public-access|public-access-save|public-access-delete'
  );
}

async function resource(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda resource validate|plan|publish|pull|typegen|explain [type] [--only code1,code2|--code code] [--profile name] [--json] [--dry-run]',
      '常用流程:',
      '  openxiangda resource validate --profile <name>',
      '  openxiangda resource plan [type] --only <code1,code2> --profile <name> --json',
      '  openxiangda resource publish [type] --only <code1,code2> --profile <name>',
      '  openxiangda resource publish function,workflow --only function:<code>,workflow:<code> --stage-only --profile <name>',
      '  openxiangda resource publish form-settings --only <code> --activate --profile <name>',
      '  openxiangda resource publish [type] --all --reason "approved app-wide closure" --profile <name>',
      '说明:',
      '  - 读取 src/resources/**；workflowFile 会先走非写入编译校验。',
      '  - publish 默认跳过 plan 判定为 noop 的资源，避免无意义 upsert；需要强制写入时加 --force。',
      '  - Form settings bundle 默认只 stage，不推进线上 Form head；只有显式 --activate 才 CAS 激活。',
      '  - Function/Automation/Workflow 可用 --stage-only 只 prepare + verify immutable child；随后由 release app-finalize 一次原子激活。',
      '  - --include-noop 仅可与 --stage-only 一起使用，用于受管候选为内容未变的目标生成带当前来源的不可变子版本。',
      '  - publish --dry-run 等价于发布前计划，不会写平台资源。',
      '  - 在线 publish 必须用 --only/--code 精确选择；真正全量发布必须显式 --all --reason，SDD bypass 不能绕过此范围门。',
      '  - 历史代码已先合入主线、线上又来自多次分批发布时，可显式使用 --adopt-online-baseline --adoption-reason "..."；仅允许绑定同一 change/lease 的精确非删除范围，仍保留 lease、冻结 head 检查与写入 CAS。',
      '  - 源码依赖触发的 Function/Automation 更新默认只替换 source snapshot，保留线上 bindings/schema/metadata；显式替换 manifest 必须加 --replace-manifest --reason。',
      '  - --only/--code 会在读取/分析 manifest 与构建源码前按逻辑资源 code 早期收窄；也支持 function:foo 这类带类型 selector。',
      '  - type 可选: workflow, notification, route, menu, role, permission, data-view, function, connector 等。',
      '  - plan/publish 会在 stderr 输出阶段进度，超过 15 秒持续心跳；JSON 结果包含 timings，不污染 stdout。',
      '  - plan/publish --dry-run 严格只允许 GET/HEAD；READ_ONLY_AUTH_REQUIRED 时先执行 auth refresh 或重新登录。',
    ].join('\n'));
    return;
  }
  const config = loadConfig();
  const profileName = flags.profile || config.currentProfile;

  if (!['validate', 'plan', 'publish', 'pull', 'typegen', 'explain'].includes(subcommand)) {
    fail('用法: openxiangda resource validate|plan|publish|pull|typegen|explain [--profile name] [--json] [--dry-run]');
  }

  if (subcommand === 'explain') {
    const type = positional[0] || flags.type || 'route';
    const result = getResourceExplain(type);
    if (!result) fail(`未知资源类型: ${type}`);
    if (flags.json) return writeJson({ type, ...result });
    print(renderResourceExplain(type));
    return;
  }

  if (subcommand === 'pull') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const result = await pullResources(config, target);
    if (flags.json) return writeJson(result);
    printResourceResult(result);
    return;
  }

  const typeFilters = getResourceTypeFilters(positional, flags);
  const codeFilters = getResourceCodeFilters(flags);
  assertBackendStageOnlyScope(subcommand, flags, typeFilters);
  if (flags['include-noop'] && !flags['stage-only']) {
    fail('--include-noop 仅允许与 --stage-only 一起使用');
  }
  assertExplicitResourcePublishScope(subcommand, flags, codeFilters);
  assertExplicitManifestReplacement(flags);
  if (codeFilters && flags.prune) {
    fail('resource publish --only/--code 不能与 --prune 同时使用，避免删除未选中的资源');
  }
  const manifest = loadWorkspaceResources({ typeFilters, codeFilters });
  if (subcommand !== 'typegen') {
    await attachLocalFormSchemas(manifest);
  }
  if (
    subcommand === 'plan' &&
    process.env.OPENXIANGDA_GIT_BASE_RESOURCE_PLAN === '1'
  ) {
    // The frozen Git base is expected not to contain a resource that the
    // current change creates. Keep the exact selector while allowing that one
    // absence to appear as "no base action" for the parent preflight.
    manifest.unmatchedResourceCodeFilters = [];
  }
  if (subcommand === 'typegen') {
    const result = generateResourceTypes(manifest, flags.out || flags.output);
    if (flags.json) return writeJson(result);
    print(`已生成资源类型: ${result.filePath}`);
    return;
  }

  const validation = validateWorkspaceResources(manifest);
  let target = null;
  let stagedFormBindingOverlays = new Map();
  if (!isManifestEmpty(manifest)) {
    target = getWorkspaceTarget(config, profileName, flags);
    const workflowFormCodes = unique(
      (manifest.workflows || [])
        .map(item => item.formCode || item.form)
        .filter(Boolean)
    );
    const scopeGrantSourceNeedsInitialSync = (
      manifest.scopeGrantSources || []
    ).some(item => item.sync === true);
    const stagedChangeId =
      readStringFlag(flags, 'change') ||
      getStoredChangeBaseline(target, { access: 'reconciliation-read' })
        ?.changeId ||
      '';
    const scopeGrantSourceFormCodes =
      scopeGrantSourceNeedsInitialSync && stagedChangeId
        ? await resolveScopeGrantSourceFormCodes(
            config,
            target,
            manifest.scopeGrantSources || []
          )
        : [];
    const dataViewFormCodes = stagedChangeId
      ? resolveDataViewSourceFormCodes(
          manifest.dataViews || [],
          target.bound
        )
      : [];
    const stagedContractFormCodes = unique([
      ...workflowFormCodes,
      ...scopeGrantSourceFormCodes,
      ...dataViewFormCodes,
    ]).sort();
    if (
      stagedContractFormCodes.length > 0 &&
      stagedChangeId
    ) {
      stagedFormBindingOverlays =
        await resolveReusableStagedFormReleaseOverlays(
          config,
          target,
          stagedChangeId,
          { formCodes: stagedContractFormCodes }
        );
    }
    validateWorkspaceResourceBindings(
      manifest,
      target.bound,
      validation,
      stagedFormBindingOverlays
    );
  }
  await validateCompiledWorkflowResources(manifest, validation);
  if (subcommand === 'validate') {
    if (flags.json) return writeJson(validation);
    printResourceValidation(validation);
    if (validation.errors.length > 0) {
      fail(`资源配置校验失败: ${validation.errors.length} 个错误`);
    }
    return;
  }
  if (validation.errors.length > 0) {
    fail(`资源配置校验失败: ${validation.errors[0]}`);
  }

  const dryRun = subcommand === 'publish' && Boolean(flags['dry-run']);
  target = target || getWorkspaceTarget(config, profileName, flags);
  if (subcommand === 'plan' || dryRun) {
    const telemetry = createCliReleaseTelemetry(
      dryRun ? 'resource publish --dry-run' : 'resource plan'
    );
    try {
      const plan = await telemetry.runPhase('plan', async () =>
        buildResourcePlan(config, target, manifest, { flags })
      );
      if (dryRun) {
        plan.dryRun = true;
        plan.command = 'resource publish --dry-run';
      }
      plan.timings = telemetry.stop();
      if (flags.json) return writeJson(plan);
      printResourcePlan(plan);
      return;
    } finally {
      telemetry.stop();
    }
  }

  const telemetry = createCliReleaseTelemetry('resource publish');
  try {
    const publishPlan = await telemetry.runPhase('plan', async () =>
      buildResourcePlan(config, target, manifest, { flags })
    );
    if (publishPlan.functionSecretRefs?.valid === false) {
      const missing = publishPlan.functionSecretRefs.functions
        .flatMap(item =>
          item.missingRequired.map(ref => `${item.code}:${ref.name}`)
        )
        .sort();
      const error = new Error(
        `FUNCTION_SECRET_NOT_CONFIGURED: 以下 Function required secretRefs 尚未配置或未激活: ${missing.join(', ')}`
      );
      error.code = 'FUNCTION_SECRET_NOT_CONFIGURED';
      error.missingSecretRefs = missing;
      throw error;
    }
    if (publishPlan.formFieldContracts?.valid === false) {
      const violations = publishPlan.formFieldContracts.errors || [];
      const error = new Error(
        `FORM_FIELD_CONTRACT_INVALID: ${violations
          .slice(0, 8)
          .map(item => item.message)
          .join('; ')}`
      );
      error.code = 'FORM_FIELD_CONTRACT_INVALID';
      error.violations = violations;
      throw error;
    }
    const pruneCandidates = flags.prune
      ? await telemetry.runPhase('prune-plan', async () =>
          collectPruneResourceCandidates(config, target, manifest)
        )
      : [];
    if (pruneCandidates.length > 0) {
      publishPlan.actions.push(...pruneCandidatesToPlanActions(pruneCandidates));
      publishPlan.summary = summarizeActions(publishPlan.actions);
    }
    let scopedFiles = [];
    if ((publishPlan.summary.create || 0) + (publishPlan.summary.update || 0) + (publishPlan.summary.delete || 0) > 0) {
      const resourceTargets = buildResourceManifestSddTargets(
        manifest,
        publishPlan.actions
      );
      scopedFiles = resolveReleaseCommandScopedFiles(flags, profileName);
      assertSddReleaseGate(
        buildExplicitSddReleasePlan(
          resourceTargets,
          {
            files: scopedFiles,
            commands: [
              buildResourcePublishCommand(
                typeFilters,
                codeFilters,
                profileName,
                flags
              ),
            ],
            changeId: flags.change,
            actualCommands: true,
          }
        ),
        flags,
        'openxiangda resource publish'
      );
    }
    const publishLease = await telemetry.runPhase('lease', async () =>
      resolvePublishLeaseForWrite(config, target, flags)
    );
    const deliveryV2BackendManifestIntent =
      resolveDeliveryV2BackendManifestReplacementIntent({
        flags,
        typeFilters,
        codeFilters,
        manifest,
      });
    const publishLeaseFlags = deliveryV2BackendManifestIntent
      ? {
          ...flags,
          reason: deliveryV2BackendManifestIntent.reason,
          'replace-reason': deliveryV2BackendManifestIntent.reason,
        }
      : flags;
    const changeBaselinePreflight = await telemetry.runPhase(
      'preflight',
      {
        resourceCount:
          (publishPlan.summary.create || 0) +
          (publishPlan.summary.update || 0) +
          (publishPlan.summary.delete || 0),
      },
      async () =>
        runResourceChangeBaselinePreflight(
          config,
          target,
          manifest,
          publishPlan.actions,
          flags,
          publishLease
        )
    );
    const result = await telemetry.runPhase(
      'write',
      { planned: publishPlan.summary },
      async () =>
        publishResourceManifest(config, target, manifest, {
          planActions: publishPlan.actions,
          skipNoop: !Boolean(flags.force || flags['include-noop']),
          prune: Boolean(flags.prune),
          pruneCandidates,
          publishLeaseId: publishLease?.leaseId,
          publishLease,
          publishLeaseFlags,
          scopedFiles,
          baseRef: flags.since || 'HEAD',
          replaceManifest:
            Boolean(flags['replace-manifest']) ||
            Boolean(deliveryV2BackendManifestIntent),
          changeId:
            flags.change || getStoredChangeBaseline(target)?.changeId || null,
          stagedFormBindingOverlays,
          activateFormBundles: Boolean(flags.activate),
          stageBackendReleaseOnly:
            Boolean(flags['stage-only']) &&
            Boolean(
              typeFilters?.has('functions') ||
                typeFilters?.has('automations')
            ),
          stageWorkflowReleaseOnly:
            Boolean(flags['stage-only']) &&
            Boolean(typeFilters?.has('workflows')),
        })
    );
    if (deliveryV2BackendManifestIntent) {
      result.deliveryV2BackendManifestReplacement =
        deliveryV2BackendManifestIntent;
    }
    if (changeBaselinePreflight) {
      result.changeBaselinePreflight = changeBaselinePreflight;
    }
    const stagedResources =
      Array.isArray(result.stagedResources) && result.stagedResources.length > 0
        ? result.stagedResources
        : result.stagedResource
          ? [result.stagedResource]
          : [];
    const stagedChangeId =
      flags.change || getStoredChangeBaseline(target)?.changeId;
    const directPublishSourceRevision =
      getStoredChangeBaseline(target)?.releaseSourceRevision || null;
    if (stagedResources.length > 0 && stagedChangeId) {
      result.stagedResourcesFile = recordStagedAppReleaseResources(
        stagedChangeId,
        stagedResources,
        target
      );
    }
    const satisfiedFormSelectors = (result.published || [])
      .filter(
        item => item?.kind === 'formSetting' && item?.action === 'noop'
      )
      .map(item => `form:${item.code}`);
    if (satisfiedFormSelectors.length > 0 && stagedChangeId) {
      result.satisfiedSelectors = recordSatisfiedAppReleaseSelectors(
        stagedChangeId,
        satisfiedFormSelectors,
        target
      );
    }
    if (stagedResources.length > 0 || flags['stage-only']) {
      retainCommandScopedPublishLease('staged-resource');
    }
    const leaseCompletion = await telemetry.runPhase(
      'lease-release',
      async () =>
        finalizeCommandScopedPublishLease({
          succeeded: true,
        })
    );
    if (leaseCompletion) {
      result.publishLeaseLifecycle = leaseCompletion;
    }
    result.timings = telemetry.stop();
    if (leaseCompletion?.released && stagedChangeId) {
      const receipt = writeDirectPublishReceipt(stagedChangeId, {
        command: 'resource publish',
        writeAttempted:
          (result.published || []).some(item => item.action !== 'noop') ||
          (result.deleted || []).length > 0,
        selectors: [
          ...(result.published || []).map(
            item => `${item.kind || 'resource'}:${item.code}`
          ),
          ...(result.deleted || []).map(
            item => `${item.kind || 'resource'}:${item.code}`
          ),
        ],
        sourceRevision: directPublishSourceRevision,
        result: {
          published: (result.published || []).length,
          deleted: (result.deleted || []).length,
        },
      });
      result.directPublishReceipt = receipt?.file || null;
    }
    if (flags.json) return writeJson(result);
    printResourceResult(result);
  } finally {
    telemetry.stop();
  }
}

function assertBackendStageOnlyScope(subcommand, flags, typeFilters) {
  if (!flags['stage-only']) return;
  if (subcommand !== 'publish' || flags['dry-run']) {
    fail('--stage-only 仅适用于在线 resource publish');
  }
  if (flags.prune || flags.activate) {
    fail('--stage-only 不能与 --prune 或 --activate 同时使用');
  }
  const normalized = Array.from(typeFilters || []);
  if (
    normalized.length === 0 ||
    normalized.some(
      type => !['functions', 'automations', 'workflows'].includes(type)
    )
  ) {
    fail('--stage-only 必须显式选择 function、automation 或 workflow 资源类型');
  }
}

function assertExplicitResourcePublishScope(subcommand, flags, codeFilters) {
  if (subcommand !== 'publish' || flags['dry-run']) return;
  if (Array.isArray(codeFilters) && codeFilters.length > 0) return;
  if (!flags.all) {
    fail(
      '在线 resource publish 必须使用 --only/--code 精确选择逻辑资源；如批准范围确实覆盖全类型/全应用，请显式使用 --all --reason "..."'
    );
  }
  const reason = String(flags.reason || flags['full-publish-reason'] || '').trim();
  if (reason.length < 8) {
    fail('resource publish --all 必须提供至少 8 个字符的 --reason，说明为何批准范围覆盖全部资源');
  }
}

function assertExplicitManifestReplacement(flags) {
  if (!flags['replace-manifest']) return;
  const reason = String(flags.reason || flags['replace-reason'] || '').trim();
  if (reason.length < 8) {
    fail('--replace-manifest 必须提供至少 8 个字符的 --reason，说明为何允许覆盖线上元数据');
  }
}

function resolveReleaseCommandScopedFiles(
  flags,
  profileName,
  deliveryContext = activeDeliveryV2Context
) {
  if (deliveryContext) return [];
  return flags.change
    ? buildWorkspaceReleasePlan({
        changeId: flags.change,
        changed: true,
        profile: profileName,
        skipSdd: true,
      }).changedFiles || []
    : getWorkspaceChangedFiles();
}

function resolveOnlineBaselineAdoption(
  flags = {},
  planActions = [],
  publishLease = null
) {
  if (!flags['adopt-online-baseline']) return null;
  const reason = String(
    flags['adoption-reason'] || flags.reason || ''
  ).trim();
  if (reason.length < 8) {
    fail(
      '--adopt-online-baseline 必须提供至少 8 个字符的 --adoption-reason，说明为何线上资源无法对应单一 Git 基线'
    );
  }
  const changeId = String(flags.change || publishLease?.changeId || '').trim();
  if (!changeId) {
    fail(
      '--adopt-online-baseline 必须与 --change <id> 或已持有的同 change 发布租约一起使用'
    );
  }
  if (flags.all || flags.force || flags.prune) {
    fail('--adopt-online-baseline 禁止与 --all、--force 或 --prune 一起使用');
  }
  if (!flags.only && !flags.code) {
    fail('--adopt-online-baseline 只允许 --only/--code 精确资源范围');
  }
  const deletes = (planActions || []).filter(
    action => action?.action === 'delete'
  );
  if (deletes.length > 0) {
    fail('--adopt-online-baseline 禁止任何 delete 计划');
  }
  return {
    mode: 'frozen_online_heads_v1',
    changeId,
    reason,
  };
}

function buildResourceManifestSddTargets(manifest, planActions = []) {
  const codes = key => unique((manifest[key] || []).map(getResourceItemCode).filter(Boolean)).sort();
  const deletedCodes = kind =>
    unique(
      (planActions || [])
        .filter(action => action?.action === 'delete' && action.kind === kind)
        .map(action => action.code)
        .filter(Boolean)
    ).sort();
  const codeResourceKeys = new Set([
    'functions',
    'automations',
    'workflows',
    'formSettings',
  ]);
  const resourceSelectors = Object.fromEntries(
    RESOURCE_SPECS
      .filter(
        spec =>
          !codeResourceKeys.has(spec.key) &&
          directResourceTypeForKey(spec.key)
      )
      .map(spec => [spec.key, codes(spec.key)])
      .filter(([, selectedCodes]) => selectedCodes.length > 0)
  );
  const hasGenericResources = RESOURCE_SPECS.some(
    spec =>
      !codeResourceKeys.has(spec.key) &&
      !directResourceTypeForKey(spec.key) &&
      (manifest[spec.key] || []).length > 0
  ) || (planActions || []).some(
    action =>
      action?.action === 'delete' &&
      !['function', 'automation', 'workflow'].includes(action.kind)
  );
  return {
    forms: codes('formSettings'),
    pages: [],
    functions: unique([...codes('functions'), ...deletedCodes('function')]).sort(),
    automations: unique([
      ...codes('automations'),
      ...deletedCodes('automation'),
    ]).sort(),
    workflows: unique([...codes('workflows'), ...deletedCodes('workflow')]).sort(),
    jsCodeNodes: [],
    resources: hasGenericResources,
    resourceSelectors,
    runtime: false,
    other: [],
  };
}

function buildResourcePublishCommand(
  typeFilters,
  codeFilters,
  profileName,
  flags = {}
) {
  const args = ['openxiangda resource publish'];
  if (typeFilters?.size > 0) {
    args.push(Array.from(typeFilters).sort().join(','));
  }
  if (codeFilters?.length) {
    const qualifierAliases = {
      functions: 'function',
      automations: 'automation',
      workflows: 'workflow',
      formSettings: 'form-setting',
    };
    const selectors = codeFilters.map(selector =>
      (selector.key || selector.qualifier) && (!typeFilters || typeFilters.size !== 1)
        ? `${
            qualifierAliases[selector.key || selector.qualifier] ||
            selector.key ||
            selector.qualifier
          }:${selector.code}`
        : selector.code
    );
    args.push(`--only ${Array.from(new Set(selectors)).join(',')}`);
  }
  args.push(`--profile ${profileName}`);
  if (flags.change) args.push(`--change ${flags.change}`);
  if (flags['stage-only']) args.push('--stage-only');
  if (flags.activate) args.push('--activate');
  if (flags['replace-manifest']) args.push('--replace-manifest');
  if (flags.reason) args.push(`--reason ${JSON.stringify(String(flags.reason))}`);
  return args.join(' ');
}

function buildWorkspacePublishCommand(flags = {}, profileName) {
  const args = ['openxiangda workspace publish', `--profile ${profileName}`];
  if (flags.environment) args.push(`--environment ${flags.environment}`);
  else if (flags.target) args.push(`--environment ${flags.target}`);
  if (flags.change) args.push(`--change ${flags.change}`);
  if (flags.form) args.push(`--form ${flags.form}`);
  if (flags.page) args.push(`--page ${flags.page}`);
  if (flags.only) args.push(`--only ${flags.only}`);
  if (flags.changed) args.push('--changed');
  if (flags['include-resources']) args.push('--include-resources');
  return args.join(' ');
}

async function runtime(args) {
  const { subcommand, rest } = parseSubcommandArgs(args);
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print([
      '用法: openxiangda runtime deploy|releases [--full]|activate [--profile name] [--json]',
      '常用流程:',
      '  npm run build',
      '  openxiangda runtime deploy --no-activate --change <change> --profile <name> --json',
      '  openxiangda runtime releases --profile <name> [--full]',
      '说明:',
      '  - deploy 上传当前工作区 dist/ 并激活 React SPA runtime release。',
      '  - 默认 --upload-mode auto；multipart 上传遇到 403 时自动切换到平台内置对象存储直传。',
      '  - --upload-mode oss-direct 是兼容参数名，实际 provider 由平台内置存储配置决定。',
      '  - 如果平台服务较旧不支持分片上传，可临时使用 --upload-mode legacy-json。',
      '  - runtime 只发布前端产物；表单、流程、通知等资源仍走 resource publish。',
      '  - deploy/activate 会读取当前 Runtime head 并携带 CAS preconditions；head 已变化时平台返回 409，避免静默覆盖。',
      '  - 所有 deploy（含 --no-activate）先获取应用 publish lease；在任何构建/上传前要求 Git clean committed HEAD，并校验当前 HEAD 继承线上 Runtime 源码血缘。',
      '  - release begin 只接受与权威远端默认主分支完全一致的 clean HEAD；先合并/push 所有 approved changes，再一次发布。',
      '  - Runtime 同步构建前把 lease 续到平台最大 TTL；构建/上传后每次写入仍会重新校验，失租不会继续激活。',
      '  - build 不能安全前移到 lease 之前：直传模式的 assetBase 由受保护的 upload-plan 返回，不能用 gateway 路径静默替换。',
      '  - deploy 会输出 lease/head/preflight/build/upload/activate 阶段进度，JSON 结果包含 timings。',
      '  - 审计式回退必须显式使用 --allow-runtime-rollback --reason "至少 8 个字符"；不会跳过 dirty/non-Git 阻断。',
    ].join('\n'));
    return;
  }
  const config = loadConfig();
  const profileName = flags.profile || config.currentProfile;
  const target = getWorkspaceTarget(config, profileName, flags);

  if (subcommand === 'releases' || subcommand === 'list') {
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/runtime/releases`
    );
    const output = flags.full ? data : summarizeRuntimeReleaseList(data);
    if (flags.json) return writeJson(output);
    print(JSON.stringify(output, null, 2));
    return;
  }

  if (subcommand === 'activate') {
    const releaseId = positional[0] || flags['release-id'];
    if (!releaseId) fail('用法: openxiangda runtime activate <releaseId> [--profile name]');
    const rollback = resolveRuntimeRollbackBypass({
      allowRollback: flags['allow-runtime-rollback'],
      reason: readStringFlag(flags, 'reason'),
    });
    if (rollback.enabled) {
      warn(
        `[RUNTIME_LINEAGE_BYPASS] 正在请求审计式 Runtime 回退激活: release=${releaseId} reason=${rollback.reason}`
      );
    }
    const publishLease = await resolveRuntimePublishLeaseForWrite(
      config,
      target,
      flags
    );
    const directChangeId =
      flags.change || getStoredChangeBaseline(target)?.changeId;
    const directSourceRevision =
      getStoredChangeBaseline(target)?.releaseSourceRevision || null;
    await runRuntimeChangeBaselinePreflight(config, target);
    const activationPreconditions = await resolveRuntimeActivationPreconditions(
      config,
      target,
      flags
    );
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/runtime/releases/${encodeURIComponent(releaseId)}/activate`,
      {
        method: 'POST',
        body: {
          ...activationPreconditions,
          ...(publishLease?.leaseId
            ? { publishLeaseId: publishLease.leaseId }
            : {}),
          ...(rollback.enabled
            ? { lineageBypassReason: rollback.reason }
            : {}),
        },
      }
    );
    saveRuntimeReleaseState(target, data);
    const leaseCompletion = await finalizeCommandScopedPublishLease({
      succeeded: true,
    });
    if (leaseCompletion?.released && directChangeId) {
      writeDirectPublishReceipt(directChangeId, {
        command: 'runtime activate',
        writeAttempted: true,
        selectors: ['runtime:active'],
        sourceRevision: directSourceRevision,
        result: { releaseId: data?.id || releaseId },
      });
    }
    if (flags.json) return writeJson(data);
    print(`runtime release 已激活: ${data.id || releaseId} build=${data.buildId || '-'}`);
    return;
  }

  if (subcommand === 'deploy') {
    const runtimeBuildCommand = flags['no-build']
      ? null
      : assertRuntimeBuildReady(flags['build-command']);
    const scopedRuntimeFiles = resolveReleaseCommandScopedFiles(
      flags,
      target.profileName
    );
    assertSddReleaseGate(
      buildExplicitSddReleasePlan(
        { forms: [], pages: [], resources: false, runtime: true, other: [] },
        {
          files: scopedRuntimeFiles,
          commands: [
            `openxiangda runtime deploy --profile ${target.profileName}${
              flags.change ? ` --change ${flags.change}` : ''
            }${flags['no-activate'] ? ' --no-activate' : ''}`,
          ],
          changeId: flags.change,
          actualCommands: true,
        }
      ),
      flags,
      'openxiangda runtime deploy'
    );
    const telemetry = createCliReleaseTelemetry('runtime deploy');
    try {
    // Preserve Runtime's dedicated dirty-source contract before the generic
    // frozen-release revision check runs inside lease resolution. The release
    // freeze and clean-HEAD gates still run immediately afterwards.
    if (!activeDeliveryV2Context) {
      assertRuntimeSourceClean(process.cwd());
    }
    // Keep build after lease acquisition. In direct-storage modes the build
    // embeds the provider-specific assetBaseUrl returned by the protected
    // upload plan; substituting the gateway URL would change chunk/publicPath
    // behavior. The async build keeps the short publish-lease heartbeat alive
    // instead of extending a crash-prone one-hour lease.
    let publishLease = await telemetry.runPhase('lease', async () =>
      resolveRuntimePublishLeaseForWrite(config, target, flags)
    );
    const runtimeHead = await telemetry.runPhase('head', async () =>
      loadRuntimeHeadApp(config, target)
    );
    const releaseBaseline = activeDeliveryV2Context
      ? null
      : getStoredChangeBaseline(target);
    const sealedCandidateSourceRevision = releaseBaseline?.candidateId
      ? releaseBaseline.releaseSourceRevision
      : null;
    const runtimeLineage = activeDeliveryV2Context
      ? {
          sourceRevision: activeDeliveryV2Context.sourceRevision,
          parentReleaseId: runtimeHead?.activeRuntimeReleaseId || null,
          parentSourceRevision:
            runtimeHead?.activeRuntimeSourceRevision || null,
          lineageBypassReason: null,
          lineageStatus: 'delivery-v2-package',
          legacyBootstrap: Boolean(
            runtimeHead?.activeRuntimeReleaseId &&
              !runtimeHead?.activeRuntimeSourceRevision
          ),
        }
      : prepareRuntimeDeployLineage({
          cwd: process.cwd(),
          app: runtimeHead,
          activate: !flags['no-activate'],
          allowRollback: flags['allow-runtime-rollback'],
          reason: readStringFlag(flags, 'reason'),
          ...(sealedCandidateSourceRevision
            ? { sourceRevision: sealedCandidateSourceRevision }
            : {}),
        });
    if (runtimeLineage.lineageStatus === 'rollback-bypass') {
      warn(
        `[RUNTIME_LINEAGE_BYPASS] 已允许审计式 Runtime 源码回退: reason=${runtimeLineage.lineageBypassReason}`
      );
    } else if (runtimeLineage.legacyBootstrap) {
      warn(
        '[RUNTIME_LINEAGE_LEGACY_BOOTSTRAP] 当前线上 Runtime 无源码血缘；本次将使用 clean committed HEAD 建立首个可审计基线。'
      );
    }
    if (!flags['no-activate']) {
      await telemetry.runPhase('preflight', async () =>
        runRuntimeChangeBaselinePreflight(config, target)
      );
    }
    const activationPreconditions = flags['no-activate']
      ? {}
      : await resolveRuntimeActivationPreconditions(
          config,
          target,
          flags,
          runtimeHead
        );
    const buildId = normalizeRuntimeBuildId(flags['build-id'] || createRuntimeBuildId());
    const distDir = path.resolve(process.cwd(), flags.dist || 'dist');
    const uploadMode = normalizeRuntimeUploadMode(flags['upload-mode']);
    const uploadTimeoutMs = normalizeRuntimeUploadTimeoutMs(flags['upload-timeout-ms']);
    const traceId = createRuntimeTraceId();
    const gatewayAssetBaseUrl = buildRuntimeAssetBaseUrl(target.appType, buildId);
    let assetBaseUrl = gatewayAssetBaseUrl;
    let effectiveUploadMode = uploadMode;
    if (uploadMode === 'auto' || uploadMode === 'oss-direct') {
      try {
        const plan = await telemetry.runPhase('upload-plan', async () =>
          createRuntimeOssUploadBasePlan({
            config,
            profileName: target.profileName,
            appType: target.appType,
            buildId,
            traceId,
            timeoutMs: uploadTimeoutMs,
          })
        );
        if (plan?.assetBaseUrl) {
          assetBaseUrl = plan.assetBaseUrl;
          if (uploadMode === 'auto') {
            effectiveUploadMode = 'oss-direct';
            const storageProvider = resolveRuntimeStorageProvider(
              plan.storageProvider,
              plan.provider
            );
            printRuntimeProgress(
              `runtime builtin storage available; using ${formatRuntimeStorageProvider(storageProvider)} direct upload traceId=${traceId}`
            );
          }
        }
      } catch (error) {
        if (uploadMode === 'oss-direct') {
          throw error;
        }
        effectiveUploadMode = 'auto';
        assetBaseUrl = gatewayAssetBaseUrl;
        printRuntimeProgress(
          `runtime builtin storage preflight unavailable; using staged upload first traceId=${traceId}`
        );
      }
    }
    if (!flags['no-build']) {
      // Runtime builds run in an asynchronous child process so the promotion
      // heartbeat keeps renewing the short lease while compilation proceeds.
      await telemetry.runPhase('build', async () =>
        runRuntimeBuild({
          buildId,
          appType: target.appType,
          assetBaseUrl,
          command: runtimeBuildCommand,
          jsonOutput: Boolean(flags.json),
        })
      );
      const postBuildLineage = activeDeliveryV2Context
        ? runtimeLineage
        : prepareRuntimeDeployLineage({
            cwd: process.cwd(),
            app: runtimeHead,
            activate: !flags['no-activate'],
            allowRollback: flags['allow-runtime-rollback'],
            reason: readStringFlag(flags, 'reason'),
            ...(sealedCandidateSourceRevision
              ? { sourceRevision: sealedCandidateSourceRevision }
              : {}),
          });
      assertRuntimeSourceRevisionStable(
        runtimeLineage.sourceRevision,
        postBuildLineage.sourceRevision
      );
    }
    const files = collectRuntimeDistFiles(distDir, {
      includeSourceMaps: Boolean(flags['include-sourcemaps']),
    });
    const declaredReleaseFiles = runtimeReleaseFileDescriptors(files);
    const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
    const reusableRuntimeRelease = await telemetry.runPhase(
      'reuse-check',
      async () =>
        findRuntimeReleaseByBuildId(config, target, buildId)
    );
    printRuntimeProgress(
      `runtime release upload: mode=${effectiveUploadMode} traceId=${traceId} files=${files.length} size=${formatBytes(totalBytes)} timeout=${uploadTimeoutMs}ms`
    );
    const releaseFiles = await telemetry.runPhase(
      'upload',
      { fileCount: files.length, totalBytes, mode: effectiveUploadMode },
      async () => {
        if (reusableRuntimeRelease) {
          const expectedRuntimeRelease = {
            appType: target.appType,
            buildId,
            files: declaredReleaseFiles,
            sourceRevision: runtimeLineage.sourceRevision,
            parentReleaseId: runtimeLineage.parentReleaseId,
          };
          try {
            assertRuntimeReleaseReusable(
              reusableRuntimeRelease,
              expectedRuntimeRelease
            );
          } catch (error) {
            if (
              error?.code !== 'RUNTIME_RELEASE_REUSE_SOURCE_MISMATCH' ||
              !flags['recover-stale-source-mismatch']
            ) {
              throw error;
            }
            await abortStaleRuntimeReleaseSourceMismatch({
              config,
              target,
              existing: reusableRuntimeRelease,
              expected: expectedRuntimeRelease,
              publishLeaseId: publishLease?.leaseId,
            });
            effectiveUploadMode = 'reuse-aborted-storage';
            printRuntimeProgress(
              `runtime stale source residue aborted: releaseId=${reusableRuntimeRelease.id} buildId=${buildId} traceId=${traceId}`
            );
            return declaredReleaseFiles;
          }
          effectiveUploadMode = 'reuse-existing';
          printRuntimeProgress(
            `runtime immutable release reused: releaseId=${reusableRuntimeRelease.id} buildId=${buildId} traceId=${traceId}`
          );
          return declaredReleaseFiles;
        }
        if (uploadMode === 'legacy-json') {
          effectiveUploadMode = 'legacy-json';
          return files.map(file => ({
            path: file.path,
            size: file.size,
            sha256: file.sha256,
            contentType: file.contentType,
            contentBase64: file.buffer.toString('base64'),
          }));
        }
        if (effectiveUploadMode === 'oss-direct') {
          return await uploadRuntimeDistFilesOssDirect({
            config,
            profileName: target.profileName,
            appType: target.appType,
            buildId,
            files,
            traceId,
            timeoutMs: uploadTimeoutMs,
          });
        }
        try {
          return await uploadRuntimeDistFilesStaged({
            config,
            profileName: target.profileName,
            appType: target.appType,
            buildId,
            files,
            traceId,
            timeoutMs: uploadTimeoutMs,
          });
        } catch (error) {
          if (isRuntimeBuildImmutableConflict(error)) {
            const racedRuntimeRelease = await findRuntimeReleaseByBuildId(
              config,
              target,
              buildId
            );
            if (racedRuntimeRelease) {
              assertRuntimeReleaseReusable(racedRuntimeRelease, {
                appType: target.appType,
                buildId,
                files: declaredReleaseFiles,
                sourceRevision: runtimeLineage.sourceRevision,
                parentReleaseId: runtimeLineage.parentReleaseId,
              });
              effectiveUploadMode = 'reuse-existing';
              printRuntimeProgress(
                `runtime immutable release won upload race and was reused: releaseId=${racedRuntimeRelease.id} buildId=${buildId} traceId=${traceId}`
              );
              return declaredReleaseFiles;
            }
          }
          if (uploadMode !== 'auto' || !isRuntimeStagedUploadBlocked(error)) {
            throw error;
          }
          effectiveUploadMode = 'oss-direct';
          printRuntimeProgress(
            `runtime staged upload blocked by HTTP 403; fallback to builtin storage direct upload traceId=${traceId}`
          );
          return await uploadRuntimeDistFilesOssDirect({
            config,
            profileName: target.profileName,
            appType: target.appType,
            buildId,
            files,
            traceId,
            timeoutMs: uploadTimeoutMs,
          });
        }
      }
    );
    if (
      publishLease &&
      !publishLease.explicit &&
      shouldRenewPublishLease(publishLease)
    ) {
      publishLease = await renewPublishLeaseFailClosed(
        config,
        target,
        publishLease,
        flags
      );
    }
    const data = await telemetry.runPhase(
      flags['no-activate'] ? 'stage' : 'activate',
      { fileCount: releaseFiles.length },
      async () =>
        requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/runtime/releases`,
          {
            method: 'POST',
            timeoutMs: uploadTimeoutMs,
            headers: { 'x-openxiangda-trace-id': traceId },
            body: {
              buildId,
              version: flags.version || readWorkspaceVersion(),
              releaseNotes: flags.notes || flags['release-notes'] || '',
              activate: !flags['no-activate'],
              sourceRevision: runtimeLineage.sourceRevision,
              parentReleaseId: runtimeLineage.parentReleaseId,
              parentSourceRevision: runtimeLineage.parentSourceRevision,
              ...(runtimeLineage.lineageBypassReason
                ? { lineageBypassReason: runtimeLineage.lineageBypassReason }
                : {}),
              ...activationPreconditions,
              ...(publishLease?.leaseId
                ? { publishLeaseId: publishLease.leaseId }
                : {}),
              files: releaseFiles,
            },
          }
        )
    );
    const runtimeContentHash = String(data?.contentHash || '')
      .trim()
      .toLowerCase();
    const releaseAssetBaseUrl = data?.assetBaseUrl || assetBaseUrl;
    const stagedResource = flags['no-activate']
      ? stripUndefinedValues({
          kind: 'RuntimeRelease',
          identity: { releaseId: data?.id },
          action: 'update',
          hash: runtimeContentHash,
          revision: {
            parentReleaseId:
              data?.parentReleaseId || runtimeLineage.parentReleaseId || null,
          },
          metadata: {
            buildId: data?.buildId || buildId,
            releaseStatus: data?.status || 'staged',
            assetBaseUrl: releaseAssetBaseUrl,
          },
        })
      : null;
    if (
      flags['no-activate'] &&
      (!data?.id || !/^[a-f0-9]{64}$/.test(runtimeContentHash))
    ) {
      fail(
        'RUNTIME_RELEASE_STAGED_RESOURCE_INVALID: --no-activate 响应缺少 releaseId 或 64 位 contentHash'
      );
    }
    if (!flags['no-activate']) {
      saveRuntimeReleaseState(target, data);
    }
    const stagedChangeId =
      flags.change || getStoredChangeBaseline(target)?.changeId;
    const stagedResourcesFile =
      stagedResource && stagedChangeId
        ? recordStagedAppReleaseResources(
            stagedChangeId,
            [stagedResource],
            target
          )
        : null;
    const result = {
      appType: target.appType,
      buildId,
      release: data,
      distDir,
      fileCount: files.length,
      totalBytes,
      assetBaseUrl: releaseAssetBaseUrl,
      activated: !flags['no-activate'],
      sourceRevision: runtimeLineage.sourceRevision,
      parentReleaseId: runtimeLineage.parentReleaseId,
      parentSourceRevision: runtimeLineage.parentSourceRevision,
      lineageStatus: runtimeLineage.lineageStatus,
      lineageBootstrap: Boolean(data?.lineageBootstrap || runtimeLineage.legacyBootstrap),
      uploadMode: effectiveUploadMode,
      storageProvider:
        data?.storageProvider ||
        releaseFiles.find(file => file.storageProvider)?.storageProvider ||
        null,
      traceId,
      ...(stagedResource ? { stagedResource } : {}),
      ...(stagedResourcesFile ? { stagedResourcesFile } : {}),
    };
    if (stagedResource) {
      retainCommandScopedPublishLease('staged-runtime');
    }
    const leaseCompletion = await telemetry.runPhase(
      'lease-release',
      async () =>
        finalizeCommandScopedPublishLease({
          succeeded: true,
        })
    );
    if (leaseCompletion) {
      result.publishLeaseLifecycle = leaseCompletion;
    }
    result.timings = telemetry.stop();
    if (leaseCompletion?.released && stagedChangeId) {
      const receipt = writeDirectPublishReceipt(stagedChangeId, {
        command: 'runtime deploy',
        writeAttempted: true,
        selectors: ['runtime:active'],
        sourceRevision: runtimeLineage.sourceRevision,
        result: {
          releaseId: data?.id || null,
          buildId,
          activated: true,
        },
      });
      result.directPublishReceipt = receipt?.file || null;
    }
    if (flags.json) return writeJson(result);
    print(
      [
        `runtime release 已上传: ${target.appType}`,
        `build: ${buildId}`,
        `files: ${files.length} (${formatBytes(totalBytes)})`,
        `upload: ${effectiveUploadMode}`,
        `traceId: ${traceId}`,
        `assetBase: ${releaseAssetBaseUrl}`,
        `active: ${result.activated ? 'yes' : 'no'}`,
        ...(stagedResourcesFile
          ? [`staged resources: ${stagedResourcesFile}`]
          : []),
      ].join('\n')
    );
    return;
    } finally {
      telemetry.stop();
    }
  }

  fail('用法: openxiangda runtime deploy|releases [--full]|activate [--profile name]');
}

async function loadRuntimeHeadApp(config, target) {
  try {
    return (
      (await requestWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/runtime/releases/head`
      )) || {}
    );
  } catch (error) {
    if (!isHttpNotFound(error)) throw error;
    const snapshot = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/snapshot`
    );
    return snapshot?.app || snapshot?.application || snapshot || {};
  }
}

function assertRuntimeSourceRevisionStable(beforeBuild, afterBuild) {
  const fields = ['repo', 'baseCommit', 'treeHash'];
  if (fields.every(field => beforeBuild?.[field] === afterBuild?.[field])) return;
  const error = new Error(
    '[RUNTIME_SOURCE_CHANGED_DURING_BUILD] Runtime 构建期间 Git HEAD 或源码树发生变化，已在上传前阻断；请确认构建脚本不修改受控源码，然后重新构建。'
  );
  error.code = 'RUNTIME_SOURCE_CHANGED_DURING_BUILD';
  throw error;
}

async function resolveRuntimeActivationPreconditions(
  config,
  target,
  flags = {},
  snapshotApp
) {
  const hasExplicitRelease = flags['expected-active-release-id'] !== undefined;
  const hasExplicitUpdatedAt = flags['expected-runtime-updated-at'] !== undefined;
  let app = snapshotApp || null;
  if (!hasExplicitRelease || !hasExplicitUpdatedAt) {
    app = app || await loadRuntimeHeadApp(config, target);
  }

  let expectedActiveReleaseId;
  if (hasExplicitRelease) {
    const value = readStringFlag(flags, 'expected-active-release-id');
    expectedActiveReleaseId = /^(null|none)$/i.test(value) ? null : value;
  } else if (app && Object.prototype.hasOwnProperty.call(app, 'activeRuntimeReleaseId')) {
    expectedActiveReleaseId = app.activeRuntimeReleaseId || null;
  }

  const expectedRuntimeUpdatedAt = hasExplicitUpdatedAt
    ? readStringFlag(flags, 'expected-runtime-updated-at')
    : app?.updatedAt || undefined;
  return stripUndefinedValues({
    expectedActiveReleaseId,
    expectedRuntimeUpdatedAt,
  });
}

async function createRuntimeOssUploadBasePlan(options) {
  return await requestWithAuth(
    options.config,
    options.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(options.appType)}/runtime/releases/oss-upload-plan`,
    {
      method: 'POST',
      timeoutMs: options.timeoutMs,
      headers: { 'x-openxiangda-trace-id': options.traceId },
      body: {
        buildId: options.buildId,
        planOnly: true,
        files: [],
      },
    }
  );
}

async function runRuntimeBuild(options) {
  const command = options.command || defaultRuntimeBuildCommand();
  if (options.jsonOutput) {
    printRuntimeProgress(`构建 React SPA runtime: ${command}`);
  } else {
    print(`构建 React SPA runtime: ${command}`);
  }
  await new Promise((resolve, reject) => {
    let child;
    try {
      child = spawn(command, [], {
        cwd: process.cwd(),
        shell: true,
        stdio: options.jsonOutput
          ? ['ignore', 'pipe', 'pipe']
          : 'inherit',
        env: {
          ...process.env,
          OPENXIANGDA_APP_TYPE: options.appType,
          APP_TYPE: options.appType,
          OPENXIANGDA_BUILD_ID: options.buildId,
          OPENXIANGDA_RUNTIME_ASSET_BASE: options.assetBaseUrl,
        },
      });
    } catch (error) {
      reject(
        new Error(`runtime build 无法启动: ${error?.message || String(error)}`)
      );
      return;
    }
    if (options.jsonOutput) {
      child.stdout?.on('data', chunk => {
        process.stderr.write(maskText(String(chunk)));
      });
      child.stderr?.on('data', chunk => {
        process.stderr.write(maskText(String(chunk)));
      });
    }
    child.once('error', error => {
      reject(new Error(`runtime build 无法启动: ${error.message}`));
    });
    child.once('close', (code, signal) => {
      if (code === 0) {
        resolve();
        return;
      }
      reject(
        new Error(
          `runtime build 失败: ${
            Number.isInteger(code) ? `exit ${code}` : `signal ${signal || '-'}`
          }`
        )
      );
    });
  });
}

function assertRuntimeBuildReady(explicitCommand) {
  if (explicitCommand) return String(explicitCommand);
  const packageFile = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(packageFile)) {
    fail('RUNTIME_BUILD_NOT_READY: 缺少 package.json；尚未获取发布租约');
  }
  let packageJson;
  try {
    packageJson = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
  } catch (error) {
    fail(`RUNTIME_BUILD_NOT_READY: package.json 无法解析: ${error.message}`);
  }
  if (!packageJson?.scripts?.build) {
    fail('RUNTIME_BUILD_NOT_READY: package.json 缺少 scripts.build；尚未获取发布租约');
  }
  const modulesDir = path.join(process.cwd(), 'node_modules');
  if (!fs.existsSync(modulesDir)) {
    fail(
      'RUNTIME_BUILD_DEPENDENCIES_MISSING: 缺少 node_modules；请在开发阶段完成依赖安装，发布命令不会临时安装或修改锁文件'
    );
  }
  return defaultRuntimeBuildCommand();
}

function defaultRuntimeBuildCommand() {
  // npm run only executes the already-declared script and resolves
  // node_modules/.bin. Unlike pnpm build, it does not reject a valid worktree
  // whose node_modules is a symlink into the primary checkout.
  return 'npm run build';
}

function collectRuntimeDistFiles(distDir, options = {}) {
  if (!fs.existsSync(distDir) || !fs.statSync(distDir).isDirectory()) {
    fail(`runtime dist 目录不存在: ${distDir}`);
  }
  const files = [];
  walkRuntimeDist(distDir, distDir, files, options);
  if (!files.some(file => file.path === 'index.html')) {
    fail(`runtime dist 缺少 index.html: ${distDir}`);
  }
  const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
  if (totalBytes > 25 * 1024 * 1024) {
    fail(`runtime dist 过大: ${formatBytes(totalBytes)}，当前 runtime 发布通道上限为 25MB`);
  }
  return files;
}

function runtimeReleaseFileDescriptors(files) {
  return (files || []).map(file => ({
    path: file.path,
    size: file.size,
    sha256: file.sha256,
    contentType: file.contentType,
  }));
}

function calculateRuntimeReleaseContentHash(files) {
  const hash = crypto.createHash('sha256');
  for (const file of files || []) {
    const filePath = String(file?.path || '').trim();
    const fileSha256 = String(file?.sha256 || '').trim().toLowerCase();
    if (!filePath || !/^[a-f0-9]{64}$/.test(fileSha256)) {
      throw runtimeReleaseReuseError(
        'RUNTIME_RELEASE_REUSE_LOCAL_MANIFEST_INVALID',
        `本地 Runtime 文件描述不完整: ${filePath || '(unknown)'}`,
        { filePath: filePath || null }
      );
    }
    hash.update(filePath);
    hash.update(fileSha256);
  }
  return hash.digest('hex');
}

async function findRuntimeReleaseByBuildId(config, target, buildId) {
  const appPath = `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/runtime/releases`;
  try {
    const exact = await requestWithAuth(
      config,
      target.profileName,
      `${appPath}/by-build/${encodeURIComponent(buildId)}`
    );
    return exact?.id ? exact : null;
  } catch (error) {
    if (Number(error?.status) !== 404) throw error;
  }
  const releases = await requestWithAuth(
    config,
    target.profileName,
    appPath
  );
  const items = Array.isArray(releases)
    ? releases
    : Array.isArray(releases?.items)
      ? releases.items
      : [];
  return (
    items.find(item => String(item?.buildId || '') === String(buildId)) ||
    null
  );
}

function assertRuntimeReleaseReusable(existing, expected) {
  const context = {
    appType: expected.appType,
    buildId: expected.buildId,
    existingReleaseId: existing?.id || null,
  };
  if (String(existing?.status || '') !== 'uploaded') {
    throw runtimeReleaseReuseError(
      'RUNTIME_RELEASE_REUSE_STATUS_INVALID',
      `相同 buildId 的 Runtime Release 状态为 ${existing?.status || '(unknown)'}，仅 uploaded 状态可作为失败发布的暂存恢复点`,
      { ...context, existingStatus: existing?.status || null }
    );
  }
  const expectedContentHash = calculateRuntimeReleaseContentHash(
    expected.files
  );
  if (
    String(existing?.contentHash || '').trim().toLowerCase() !==
    expectedContentHash
  ) {
    throw runtimeReleaseReuseError(
      'RUNTIME_RELEASE_REUSE_CONTENT_MISMATCH',
      '相同 buildId 的历史 Runtime Release 内容与当前密封包不一致，拒绝复用',
      {
        ...context,
        expectedContentHash,
        existingContentHash: existing?.contentHash || null,
      }
    );
  }
  if (
    !runtimeSourceRevisionEquals(
      existing?.sourceRevision,
      expected.sourceRevision
    )
  ) {
    throw runtimeReleaseReuseError(
      'RUNTIME_RELEASE_REUSE_SOURCE_MISMATCH',
      '相同 buildId 的历史 Runtime Release 源码血缘与当前密封包不一致，拒绝复用',
      context
    );
  }
  const existingParentReleaseId =
    String(existing?.parentReleaseId || '').trim() || null;
  const expectedParentReleaseId =
    String(expected.parentReleaseId || '').trim() || null;
  if (existingParentReleaseId !== expectedParentReleaseId) {
    throw runtimeReleaseReuseError(
      'RUNTIME_RELEASE_REUSE_PARENT_MISMATCH',
      '相同 buildId 的历史 Runtime Release 父版本已与当前 Runtime head 不一致，拒绝复用',
      {
        ...context,
        existingParentReleaseId,
        expectedParentReleaseId,
      }
    );
  }
  return existing;
}

async function abortStaleRuntimeReleaseSourceMismatch(options) {
  const existing = options.existing || {};
  const expected = options.expected || {};
  const expectedContentHash = calculateRuntimeReleaseContentHash(
    expected.files
  );
  const existingContentHash = String(existing.contentHash || '')
    .trim()
    .toLowerCase();
  const existingParentReleaseId =
    String(existing.parentReleaseId || '').trim() || null;
  const expectedParentReleaseId =
    String(expected.parentReleaseId || '').trim() || null;
  if (
    String(existing.status || '') !== 'uploaded' ||
    !existing.id ||
    !options.publishLeaseId ||
    existingContentHash !== expectedContentHash ||
    existingParentReleaseId !== expectedParentReleaseId ||
    !existing.sourceRevision ||
    !expected.sourceRevision ||
    runtimeSourceRevisionEquals(
      existing.sourceRevision,
      expected.sourceRevision
    )
  ) {
    throw runtimeReleaseReuseError(
      'RUNTIME_RELEASE_SOURCE_RECOVERY_UNSAFE',
      '历史 Runtime Release 不满足自动终止条件，拒绝清理',
      {
        appType: expected.appType || null,
        buildId: expected.buildId || null,
        existingReleaseId: existing.id || null,
      }
    );
  }
  return await requestWithAuth(
    options.config,
    options.target.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(
      options.target.appType
    )}/runtime/releases/${encodeURIComponent(existing.id)}/abort`,
    {
      method: 'POST',
      body: {
        reason:
          'Replace stale Runtime source lineage left by a failed Delivery V2 run',
        publishLeaseId: options.publishLeaseId,
        expectedBuildId: expected.buildId,
        expectedContentHash,
        expectedSourceRevision: existing.sourceRevision,
        expectedParentReleaseId,
        replacementSourceRevision: expected.sourceRevision,
      },
    }
  );
}

function runtimeSourceRevisionEquals(left, right) {
  return ['repo', 'baseCommit', 'treeHash'].every(
    key => String(left?.[key] || '').trim() === String(right?.[key] || '').trim()
  );
}

function runtimeReleaseReuseError(code, message, data = {}) {
  const error = new Error(`${code}: ${message}`);
  error.code = code;
  error.data = data;
  return error;
}

function walkRuntimeDist(rootDir, currentDir, files, options) {
  const entries = fs.readdirSync(currentDir, { withFileTypes: true });
  for (const entry of entries) {
    const absolute = path.join(currentDir, entry.name);
    if (entry.isDirectory()) {
      walkRuntimeDist(rootDir, absolute, files, options);
      continue;
    }
    if (!entry.isFile()) continue;
    if (!options.includeSourceMaps && entry.name.endsWith('.map')) continue;
    const relative = path.relative(rootDir, absolute).replace(/\\/g, '/');
    const buffer = fs.readFileSync(absolute);
    files.push({
      path: relative,
      size: buffer.length,
      sha256: crypto.createHash('sha256').update(buffer).digest('hex'),
      contentType: inferRuntimeContentType(relative),
      buffer,
    });
  }
}

async function uploadRuntimeDistFilesStaged(options) {
  const files = options.files || [];
  let completed = 0;
  const results = await runWithConcurrency(
    files,
    RUNTIME_UPLOAD_CONCURRENCY,
    async file => {
      const uploaded = await uploadRuntimeDistFile(options, file);
      completed += 1;
      if (shouldReportRuntimeUploadProgress(completed, files.length)) {
        printRuntimeProgress(
          `runtime file uploaded [${completed}/${files.length}] ${file.path} ${formatBytes(file.size)} traceId=${options.traceId}`
        );
      }
      return uploaded;
    }
  );
  return results.map(file => ({
    path: file.path,
    size: file.size,
    sha256: file.sha256,
    contentType: file.contentType,
  }));
}

async function uploadRuntimeDistFilesOssDirect(options) {
  const files = options.files || [];
  const plan = await requestWithAuth(
    options.config,
    options.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(options.appType)}/runtime/releases/oss-upload-plan`,
    {
      method: 'POST',
      timeoutMs: options.timeoutMs,
      headers: { 'x-openxiangda-trace-id': options.traceId },
      body: {
        buildId: options.buildId,
        files: files.map(file => ({
          path: file.path,
          size: file.size,
          sha256: file.sha256,
          contentType: file.contentType,
        })),
      },
    }
  );
  const uploadFiles = Array.isArray(plan?.files) ? plan.files : [];
  const uploadByPath = new Map(uploadFiles.map(file => [file.path, file]));
  const planStorageProvider = resolveRuntimeStorageProvider(
    plan?.storageProvider,
    plan?.provider
  );
  let completed = 0;
  const results = await runWithConcurrency(
    files,
    RUNTIME_UPLOAD_CONCURRENCY,
    async file => {
      const uploadInfo = uploadByPath.get(file.path);
      if (!uploadInfo?.uploadUrl) {
        fail(`runtime 内置对象存储上传计划缺少文件: ${file.path}`);
      }
      const storageProvider = resolveRuntimeStorageProvider(
        uploadInfo.storageProvider,
        uploadInfo.provider,
        planStorageProvider
      );
      const uploaded = await uploadRuntimeDistFileToSignedUrl(options, file, uploadInfo);
      completed += 1;
      if (shouldReportRuntimeUploadProgress(completed, files.length)) {
        printRuntimeProgress(
          `runtime ${formatRuntimeStorageProvider(storageProvider)} file uploaded [${completed}/${files.length}] ${file.path} ${formatBytes(file.size)} traceId=${options.traceId}`
        );
      }
      return { ...uploaded, storageProvider };
    }
  );
  return results.map(file => ({
    path: file.path,
    size: file.size,
    sha256: file.sha256,
    contentType: file.contentType,
    storageProvider: resolveRuntimeStorageProvider(file.storageProvider),
    objectName: file.objectName,
    bucketName: file.bucketName,
  }));
}

async function uploadRuntimeDistFileToSignedUrl(options, file, uploadInfo) {
  const method = String(uploadInfo.uploadMethod || 'PUT').toUpperCase();
  assertReadOnlyHttpRequest(uploadInfo.uploadUrl, { method });
  const timeoutMs = normalizeRuntimeUploadTimeoutMs(options.timeoutMs);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let response;
  try {
    response = await fetch(uploadInfo.uploadUrl, {
      method,
      headers: uploadInfo.headers || {},
      body: file.buffer,
      signal: controller.signal,
    });
  } catch (error) {
    if (isAbortError(error)) {
      throw new Error(`runtime 内置对象存储文件上传超时: ${file.path}, timeout=${timeoutMs}ms`);
    }
    throw new Error(formatFetchError(error, `runtime builtin storage upload ${file.path}`));
  } finally {
    clearTimeout(timer);
  }
  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(
      `runtime 内置对象存储文件上传失败: ${file.path}, HTTP ${response.status}: ${
        text || response.statusText || 'request failed'
      }`
    );
  }
  return {
    path: file.path,
    size: file.size,
    sha256: file.sha256,
    contentType: file.contentType,
    objectName: uploadInfo.objectName,
    bucketName: uploadInfo.bucketName,
  };
}

async function uploadRuntimeDistFile(options, file) {
  const apiPath = apiPathWithQuery(
    `/openxiangda-api/v1/apps/${encodeURIComponent(options.appType)}/runtime/releases/files`,
    {
      buildId: options.buildId,
      path: file.path,
      size: file.size,
      sha256: file.sha256,
      contentType: file.contentType,
    }
  );
  return await requestFormWithAuth(
    options.config,
    options.profileName,
    apiPath,
    () => {
      const form = new FormData();
      form.append(
        'file',
        new Blob([file.buffer], { type: file.contentType }),
        path.basename(file.path)
      );
      return form;
    },
    {
      timeoutMs: options.timeoutMs,
      headers: { 'x-openxiangda-trace-id': options.traceId },
    }
  );
}

async function runWithConcurrency(items, concurrency, worker) {
  const results = new Array(items.length);
  let nextIndex = 0;
  let firstError = null;
  const workers = Array.from(
    { length: Math.min(concurrency, items.length) },
    async () => {
      while (nextIndex < items.length && !firstError) {
        const index = nextIndex;
        nextIndex += 1;
        try {
          results[index] = await worker(items[index], index);
        } catch (error) {
          firstError = error;
        }
      }
    }
  );
  await Promise.all(workers);
  if (firstError) throw firstError;
  return results;
}

function normalizeRuntimeUploadMode(value) {
  const normalized = String(value || 'auto').trim().toLowerCase();
  if (
    normalized === 'auto' ||
    normalized === 'staged' ||
    normalized === 'oss-direct' ||
    normalized === 'legacy-json'
  ) {
    return normalized;
  }
  fail(`--upload-mode 只支持 auto、staged、oss-direct 或 legacy-json，当前: ${value}`);
}

function resolveRuntimeStorageProvider(...values) {
  for (const value of values) {
    const provider = String(value || '').trim().toLowerCase();
    if (provider) return provider;
  }
  return 'oss';
}

function formatRuntimeStorageProvider(value) {
  const provider = resolveRuntimeStorageProvider(value);
  if (provider === 'oss') return 'OSS';
  if (provider === 'cos') return 'COS';
  return provider.toUpperCase();
}

function isRuntimeStagedUploadBlocked(error) {
  return /^HTTP 403\b/.test(String(error?.message || ''));
}

function isRuntimeBuildImmutableConflict(error) {
  return (
    Number(error?.status) === 409 &&
    (String(error?.code || '') === 'RUNTIME_BUILD_IMMUTABLE' ||
      /Runtime buildId .*禁止覆盖|RUNTIME_BUILD_IMMUTABLE/.test(
        String(error?.message || '')
      ))
  );
}

function normalizeRuntimeUploadTimeoutMs(value) {
  const candidate =
    value === undefined || value === null || value === ''
      ? process.env.OPENXIANGDA_RUNTIME_UPLOAD_TIMEOUT_MS
      : value;
  const parsed = Number(candidate);
  if (Number.isFinite(parsed) && parsed > 0) return parsed;
  return RUNTIME_UPLOAD_DEFAULT_TIMEOUT_MS;
}

function createRuntimeTraceId() {
  return `oxd-${Date.now().toString(36)}-${crypto.randomBytes(4).toString('hex')}`;
}

function printRuntimeProgress(message) {
  process.stderr.write(`${maskText(message)}\n`);
}

function createCliReleaseTelemetry(operation) {
  const telemetry = createReleaseTelemetry({
    operation,
    onProgress: event => {
      const phase = event.phase;
      if (!phase) return;
      if (event.type === 'phase-start') {
        process.stderr.write(
          `[release] ${operation}: ${phase.name} started\n`
        );
        return;
      }
      if (event.type === 'heartbeat') {
        process.stderr.write(
          `[release] ${operation}: ${phase.name} still running (${formatDurationMs(
            phase.durationMs
          )})\n`
        );
        return;
      }
      if (
        event.type === 'phase-end' &&
        (phase.status !== 'success' || phase.durationMs >= 1000)
      ) {
        process.stderr.write(
          `[release] ${operation}: ${phase.name} ${phase.status} (${formatDurationMs(
            phase.durationMs
          )})\n`
        );
      }
    },
  });
  return telemetry.start();
}

function formatDurationMs(value) {
  const durationMs = Math.max(0, Number(value) || 0);
  if (durationMs < 1000) return `${Math.round(durationMs)}ms`;
  if (durationMs < 60_000) return `${(durationMs / 1000).toFixed(1)}s`;
  const minutes = Math.floor(durationMs / 60_000);
  const seconds = Math.floor((durationMs % 60_000) / 1000);
  return `${minutes}m${String(seconds).padStart(2, '0')}s`;
}

function buildRuntimeAssetBaseUrl(appType, buildId) {
  return `/service/openxiangda-api/v1/apps/${encodeURIComponent(appType)}/runtime/releases/by-build/${encodeURIComponent(buildId)}/files/`;
}

function createRuntimeBuildId() {
  const stamp = new Date()
    .toISOString()
    .replace(/[-:.TZ]/g, '')
    .slice(0, 14);
  return `${stamp}-${crypto.randomBytes(4).toString('hex')}`;
}

function normalizeRuntimeBuildId(value) {
  const normalized = String(value || '').trim().replace(/[^a-zA-Z0-9_.:-]/g, '-');
  if (!normalized) fail('buildId 不能为空');
  return normalized.slice(0, 128);
}

function inferRuntimeContentType(filePath) {
  const extension = String(filePath || '').split('.').pop().toLowerCase();
  if (extension === 'html') return 'text/html; charset=utf-8';
  if (extension === 'js' || extension === 'mjs') return 'application/javascript; charset=utf-8';
  if (extension === 'css') return 'text/css; charset=utf-8';
  if (extension === 'json') return 'application/json; charset=utf-8';
  if (extension === 'svg') return 'image/svg+xml';
  if (extension === 'png') return 'image/png';
  if (extension === 'jpg' || extension === 'jpeg') return 'image/jpeg';
  if (extension === 'webp') return 'image/webp';
  if (extension === 'woff') return 'font/woff';
  if (extension === 'woff2') return 'font/woff2';
  return 'application/octet-stream';
}

function readWorkspaceVersion() {
  const packageFile = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(packageFile)) return '';
  try {
    const pkg = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
    return String(pkg.version || '');
  } catch {
    return '';
  }
}

function saveRuntimeReleaseState(target, release) {
  target.bound.runtime = {
    ...(target.bound.runtime || {}),
    activeReleaseId: release?.id || target.bound.runtime?.activeReleaseId || null,
    activeBuildId: release?.buildId || target.bound.runtime?.activeBuildId || null,
    assetBaseUrl: release?.assetBaseUrl || target.bound.runtime?.assetBaseUrl || null,
    updatedAt: new Date().toISOString(),
  };
  target.bound.updatedAt = new Date().toISOString();
  if (!target.targetName && target.state.profiles?.[target.profileName]) {
    target.state.profiles[target.profileName] = target.bound;
  }
  saveProjectState(target.state);
}

function saveRuntimeHeadState(target, app, fallbackRelease = {}) {
  const activeReleaseId =
    app?.activeRuntimeReleaseId ||
    app?.activeRuntime?.releaseId ||
    fallbackRelease?.id ||
    fallbackRelease?.releaseId ||
    null;
  const activeBuildId =
    app?.activeRuntimeBuildId ||
    app?.activeRuntime?.buildId ||
    fallbackRelease?.buildId ||
    null;
  if (!activeReleaseId && !activeBuildId) return false;
  saveRuntimeReleaseState(target, {
    id: activeReleaseId,
    buildId: activeBuildId,
    assetBaseUrl:
      app?.runtimeAssetBaseUrl ||
      app?.activeRuntime?.assetBaseUrl ||
      fallbackRelease?.assetBaseUrl ||
      null,
  });
  return true;
}

function summarizeRuntimeReleaseList(data) {
  const items = Array.isArray(data)
    ? data
    : Array.isArray(data?.items)
      ? data.items
      : [];
  const summarized = items.map(item =>
    stripUndefinedValues({
      id: item?.id,
      version: item?.version,
      buildId: item?.buildId,
      status: item?.status,
      storageProvider: item?.storageProvider,
      fileCount: item?.fileCount,
      sizeBytes: item?.sizeBytes,
      contentHash: item?.contentHash,
      sourceRevision: item?.sourceRevision,
      parentReleaseId: item?.parentReleaseId,
      parentSourceRevision: item?.parentSourceRevision,
      lineageBypassReason: item?.lineageBypassReason,
      lineageBootstrap: item?.lineageBootstrap,
      releaseNotes: item?.releaseNotes,
      createdAt: item?.createdAt,
      activatedAt: item?.activatedAt,
    })
  );
  return Array.isArray(data)
    ? summarized
    : {
        ...(data && typeof data === 'object' ? data : {}),
        items: summarized,
      };
}

function shouldReportRuntimeUploadProgress(completed, total) {
  if (total <= 10) return true;
  const interval = Math.max(1, Math.ceil(total / 10));
  return completed === 1 || completed === total || completed % interval === 0;
}

function formatBytes(value) {
  const bytes = Number(value || 0);
  if (bytes < 1024) return `${bytes}B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)}MB`;
}

async function inspect(args) {
  const [subcommand, ...rest] = args;
  const { flags, positional } = parseArgs(rest);
  if (
    subcommand === 'help' ||
    subcommand === '--help' ||
    subcommand === '-h' ||
    flags.help ||
    flags.h
  ) {
    print('用法: openxiangda inspect app|form|workflow|automation|permissions [--profile name] [--json]');
    return;
  }
  const config = loadConfig();
  const profileName = flags.profile || config.currentProfile;

  if (!subcommand || subcommand === 'app' || subcommand === 'snapshot') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const appType = positional[0] || target.appType;
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(appType)}/snapshot`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'form') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'workflow') {
    const [workflowKey] = positional;
    if (!workflowKey) fail('用法: openxiangda inspect workflow <workflowCode|workflowId>');
    const target = getWorkspaceTarget(config, profileName, flags);
    const workflowId = resolveWorkflowId(target.bound, workflowKey, flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows/${encodeURIComponent(workflowId)}`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'automation') {
    const [automationKey] = positional;
    if (!automationKey) fail('用法: openxiangda inspect automation <automationCode|automationId>');
    const target = getWorkspaceTarget(config, profileName, flags);
    const automationId = resolveAutomationId(target.bound, automationKey, flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(automationId)}`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  if (subcommand === 'permissions') {
    const target = getWorkspaceTarget(config, profileName, flags);
    const formUuid = resolveSettingsFormUuid(target.bound, positional[0], flags);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-summary`
    );
    if (flags.json) return writeJson(data);
    print(JSON.stringify(data, null, 2));
    return;
  }

  fail('用法: openxiangda inspect app|form|workflow|automation|permissions');
}

