function printWorkspaceInitReport(result) {
  const lines = [
    `已创建 OpenXiangda workspace: ${result.targetDir}`,
    `package: ${result.packageName}`,
  ];
  if (result.createdApp) {
    lines.push(`已创建平台应用: ${result.createdApp.name} (${result.createdApp.appType})`);
  }
  if (result.bound) {
    lines.push(`已绑定 ${result.bound.profile}: ${result.bound.appType}`);
  }
  if (result.sdd?.initialized) {
    lines.push(`SDD: ${result.sdd.path}`);
  }
  if (result.installedDependencies) {
    lines.push('依赖已安装');
  }
  lines.push('下一步:');
  for (const step of result.nextSteps) {
    lines.push(`  ${step}`);
  }
  print(lines.join('\n'));
}

async function skill(args) {
  const [subcommand, ...rest] = args;
  const { flags, positional } = parseArgs(rest);
  if (wantsSubcommandHelp(subcommand, flags)) {
    print('用法: openxiangda skill install|status [--agent codex|claude|qoder|dual] [--dest <skills-dir>] [--force] [--dry-run] [--json]\n      openxiangda skill bootstrap [<dir>] [--force] [--dry-run] [--json]');
    return;
  }
  const options = {
    agent: flags.agent || 'codex',
    dest: flags.dest,
    force: Boolean(flags.force),
    dryRun: Boolean(flags['dry-run']),
  };

  if (subcommand === 'install') {
    const result = installSkills(options);
    if (flags.json) return writeJson(result);
    printSkillInstallReport(result);
    return;
  }

  if (subcommand === 'status') {
    const result = getSkillStatusReport(options);
    if (flags.json) return writeJson(result);
    printSkillStatusReport(result);
    return;
  }

  if (subcommand === 'bootstrap') {
    const result = bootstrapWorkspace({
      dir: positional[0],
      force: Boolean(flags.force),
      dryRun: Boolean(flags['dry-run']),
    });
    if (flags.json) return writeJson(result);
    printSkillBootstrapReport(result);
    return;
  }

  fail('用法: openxiangda skill install|status [--agent codex|claude|qoder|dual] [--dest <skills-dir>]\n      openxiangda skill bootstrap [<dir>] [--force] [--dry-run] [--json]');
}

function printSkillInstallReport(result) {
  if (result.results) {
    // 多平台安装结果
    print(`OpenXiangda skill install (${result.agent})`);
    for (const res of result.results) {
      print(`Destination: ${res.skillsDir}`);
      for (const item of res.operations) {
        print(`- ${item.name}: ${item.operation}`);
      }
    }
  } else {
    // 单平台安装结果
    const lines = [
      `OpenXiangda skill install (${result.agent})`,
      `Destination: ${result.skillsDir}`,
    ];
    for (const item of result.operations) {
      lines.push(`- ${item.name}: ${item.operation}`);
    }
    for (const warning of result.warnings) {
      lines.push(`Warning: ${warning}`);
    }
    print(lines.join('\n'));
  }

  print(result.message);
}

function printSkillStatusReport(result) {
  if (result.results) {
    // 多平台状态结果
    print(`OpenXiangda skill status (${result.agent})`);
    for (const res of result.results) {
      print(`Destination: ${res.skillsDir}`);
      for (const item of res.skills) {
        const version = item.installedVersion ? ` (${item.installedVersion})` : '';
        print(`- ${item.name}: ${item.status}${version}`);
      }
    }
  } else {
    // 单平台状态结果
    const lines = [
      `OpenXiangda skill status (${result.agent})`,
      `Destination: ${result.skillsDir}`,
    ];
    for (const item of result.skills) {
      const version = item.installedVersion ? ` (${item.installedVersion})` : '';
      lines.push(`- ${item.name}: ${item.status}${version}`);
    }
    for (const warning of result.warnings) {
      lines.push(`Warning: ${warning}`);
    }
    print(lines.join('\n'));
  }
}

function printSkillBootstrapReport(result) {
  const lines = [
    `OpenXiangda skill bootstrap${result.dryRun ? ' (dry-run)' : ''}`,
    `Workspace: ${result.targetDir}`,
  ];
  for (const file of result.files) {
    const reason = file.reason ? ` — ${file.reason}` : '';
    lines.push(`- ${file.path}: ${file.action}${reason}`);
  }
  const pkg = result.packageJson;
  const pkgReason = pkg.reason ? ` — ${pkg.reason}` : '';
  lines.push(`- ${pkg.path}: ${pkg.action}${pkgReason}`);
  if (pkg.added && pkg.added.length > 0) {
    lines.push(`  + scripts: ${pkg.added.join(', ')}`);
  }
  if (pkg.changed && pkg.changed.length > 0) {
    lines.push(`  ~ scripts: ${pkg.changed.join(', ')}`);
  }
  lines.push(`Summary: ${result.summary}`);
  if (result.dryRun) {
    lines.push('dry-run completed; no files were changed');
  } else {
    lines.push('Done. 重启 Qoder / Cursor / Claude / Codex 以加载新的 always-on rules。');
  }
  print(lines.join('\n'));
}

function getWorkspaceTarget(config, profileName, flags = {}) {
  const state = loadProjectState();
  const environmentSelector =
    flags.environment || flags.target || state.currentTarget;
  if (
    environmentSelector &&
    state.logicalApp &&
    Object.keys(state.targets || {}).length > 0
  ) {
    const selected = resolveEnvironmentTarget(state, environmentSelector);
    const targetProfileName = selected.binding.profile;
    if (profileName && profileName !== targetProfileName) {
      fail(
        `target ${selected.targetName} 固定使用 profile ${targetProfileName}，不能改写为 ${profileName}`
      );
    }
    const resolved = getProfile(config, targetProfileName);
    if (!selected.binding.appType || !selected.binding.environmentId) {
      fail(`target ${selected.targetName} 缺少 appType 或 environmentId`);
    }
    ensureResourceBuckets(selected.binding);
    return {
      profileName: resolved.profileName,
      profile: resolved.profile,
      state,
      bound: selected.binding,
      appType: selected.binding.appType,
      targetName: selected.targetName,
      environmentId: selected.binding.environmentId,
      environmentKind: selected.binding.kind,
      deploymentId: readStringFlag(flags, 'deployment-id') || null,
      logicalApp: state.logicalApp,
    };
  }
  const resolved = getProfile(config, profileName);
  const bound = state.profiles?.[resolved.profileName] || {};
  const appType = flags['app-type'] || bound.appType;
  if (!appType) {
    fail(
      `profile ${resolved.profileName} 未绑定应用。先执行 openxiangda workspace bind --profile ${resolved.profileName} --app-type APP_XXX`
    );
  }
  return {
    profileName: resolved.profileName,
    profile: resolved.profile,
    state,
    bound,
    appType,
  };
}

async function directResourceCrud(config, target, spec) {
  const { subcommand, flags, positional } = spec;
  const basePath = spec.basePath;

  if (subcommand === 'list') {
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: apiPathWithQuery(basePath, {
        page: flags.page,
        pageSize: flags['page-size'] || flags.limit,
        limit: flags.limit,
        code: flags.code,
      }),
    });
  }

  if (subcommand === 'get') {
    const code = positional[0] || flags.code;
    if (!code) fail(`用法: openxiangda ${spec.commandName} get <code>`);
    return runDirectRequest(config, target, flags, {
      method: 'GET',
      path: `${basePath}/${encodeURIComponent(code)}`,
    });
  }

  if (subcommand === 'delete') {
    const code = positional[0] || flags.code;
    if (!code || !flags.force) fail(`用法: openxiangda ${spec.commandName} delete <code> --force`);
    const data = await runDirectRequest(config, target, flags, {
      method: 'POST',
      path: apiPathWithPostDeleteAction(`${basePath}/${encodeURIComponent(code)}`),
    }, { returnData: true });
    if (!flags['dry-run']) removeDirectStateResource(target, spec.resourceType, code);
    return outputDirectResult(data, flags);
  }

  if (!['create', 'update', 'upsert'].includes(subcommand)) {
    fail(`用法: openxiangda ${spec.commandName} list|get|create|update|upsert|delete`);
  }

  const rawBody = readDirectJsonBody(flags, spec.commandName);
  const explicitCode = positional[0] || flags.code;
  if (explicitCode && !rawBody.code && !rawBody.resourceCode && !rawBody.functionCode && !rawBody.methodName) {
    rawBody.code = explicitCode;
  }
  const code = explicitCode || spec.codeOf(rawBody);
  if (!code) fail(`openxiangda ${spec.commandName} ${subcommand} 缺少资源 code`);
  const normalizedBody = spec.prepareBody
    ? await spec.prepareBody(rawBody)
    : spec.normalizeBody
      ? spec.normalizeBody(rawBody)
      : rawBody;

  let method = subcommand === 'create' ? (spec.createMethod || 'POST') : (spec.updateMethod || 'POST');
  let requestPath = subcommand === 'create'
    ? (spec.createPath || basePath)
    : (spec.updatePath || `${basePath}/${encodeURIComponent(code)}`);
  let requestBody = subcommand === 'create'
    ? (spec.createBody ? spec.createBody(rawBody, normalizedBody) : normalizedBody)
    : (spec.updateBody ? spec.updateBody(rawBody, normalizedBody) : normalizedBody);
  let action = subcommand;

  if (subcommand === 'upsert') {
    if (flags['dry-run']) {
      return outputDirectResult({
        dryRun: true,
        action: 'upsert',
        existsCheck: { method: 'GET', path: `${basePath}/${encodeURIComponent(code)}` },
        create: {
          method: spec.createMethod || 'POST',
          path: spec.createPath || basePath,
          body: spec.createBody ? spec.createBody(rawBody, normalizedBody) : normalizedBody,
        },
        update: {
          method: spec.updateMethod || 'POST',
          path: spec.updatePath || `${basePath}/${encodeURIComponent(code)}`,
          body: spec.updateBody ? spec.updateBody(rawBody, normalizedBody) : normalizedBody,
        },
      }, flags);
    }
    const existing = await requestOptionalWithAuth(
      config,
      target.profileName,
      `${basePath}/${encodeURIComponent(code)}`
    );
    action = existing ? 'update' : 'create';
    method = existing ? (spec.updateMethod || 'POST') : (spec.createMethod || 'POST');
    requestPath = existing
      ? (spec.updatePath || `${basePath}/${encodeURIComponent(code)}`)
      : (spec.createPath || basePath);
    requestBody = existing
      ? (spec.updateBody ? spec.updateBody(rawBody, normalizedBody) : normalizedBody)
      : (spec.createBody ? spec.createBody(rawBody, normalizedBody) : normalizedBody);
  }

  const response = await runDirectRequest(config, target, flags, {
    method,
    path: requestPath,
    body: requestBody,
  }, { returnData: true });
  const data = spec.responseData ? spec.responseData(response) : response;
  if (!flags['dry-run']) {
    if (spec.saveState) spec.saveState(code, data);
    if (flags['write-manifest']) writeDirectManifest(spec.resourceType, code, { ...rawBody, code });
  }
  return outputDirectResult({ action, data }, flags);
}

async function runDirectRequest(config, target, flags, request, options = {}) {
  const plan = {
    dryRun: true,
    method: request.method || 'GET',
    path: request.path,
    body: request.body,
  };
  if (flags['dry-run']) {
    if (options.returnData) return plan;
    return outputDirectResult(plan, flags);
  }

  const method = String(request.method || 'GET').toUpperCase();
  if (
    !['GET', 'HEAD', 'OPTIONS'].includes(method) &&
    options.controlPlaneMutation !== false
  ) {
    await ensureDirectMutationPublishContext(
      config,
      target,
      flags,
      options.mutationLabel || `${method} ${request.path}`
    );
  }

  const requestOptions = {
    method: request.method || 'GET',
    body: request.body,
    strictEnvelope: request.strictEnvelope,
    timeoutMs:
      request.timeoutMs || flags['timeout-ms'] || flags.timeout || undefined,
  };
  let data;
  if (request.auth === false) {
    const payload = await requestJson(target.profile.baseUrl, request.path, requestOptions);
    data = request.strictEnvelope ? unwrapStrictApi(payload) : unwrapApi(payload);
  } else {
    data = await requestWithAuth(config, target.profileName, request.path, requestOptions);
  }
  if (options.returnData) return data;
  return outputDirectResult(data, flags);
}

function outputDirectResult(data, flags = {}) {
  if (flags.json) return writeJson(data);
  print(JSON.stringify(data, null, 2));
}

function readDirectJsonBody(flags = {}, label, options = {}) {
  if (flags['json-file']) return readJsonArg(flags['json-file'], 'json-file');
  if (flags['body-json']) return readJsonArg(flags['body-json'], 'body-json');
  if (options.optional) return {};
  fail(`${label} 缺少 --json-file <file> 或 --body-json <json|file>`);
}

function writeDirectManifest(resourceType, code, value) {
  const dir = directManifestDir(resourceType);
  if (!dir) return;
  const fileName = `${String(code).replace(/[^A-Za-z0-9_.-]+/g, '_')}.json`;
  writeResourceJsonFile(path.join(process.cwd(), dir, fileName), value);
}

function directManifestDir(resourceType) {
  const dirs = {
    route: path.join('src', 'resources', 'routes'),
    'public-access': path.join('src', 'resources', 'public-access'),
    'auth-config': path.join('src', 'resources', 'auth'),
    function: path.join('src', 'resources', 'functions'),
    connector: path.join('src', 'resources', 'connectors'),
    notification: path.join('src', 'resources', 'notifications'),
    'data-view': path.join('src', 'resources', 'data-views'),
    menu: path.join('src', 'resources', 'menus'),
    role: path.join('src', 'resources', 'roles'),
    'page-permission-group': path.join('src', 'resources', 'permissions', 'page-groups'),
    'form-permission-group': path.join('src', 'resources', 'permissions', 'form-groups'),
    'scope-dimension': path.join('src', 'resources', 'permissions', 'scope-dimensions'),
    'scope-grant-source': path.join('src', 'resources', 'permissions', 'scope-grant-sources'),
    'data-scope-policy': path.join('src', 'resources', 'permissions', 'data-scope-policies'),
  };
  return dirs[resourceType];
}

function removeDirectStateResource(target, resourceType, code) {
  const buckets = {
    route: 'routes',
    'public-access': 'publicAccessPolicies',
    'auth-config': 'authConfigs',
    function: 'functions',
    connector: 'connectors',
    'data-view': 'dataViews',
  };
  const bucket = buckets[resourceType];
  if (!bucket || !target.bound.resources?.[bucket]?.[code]) return;
  delete target.bound.resources[bucket][code];
  saveProjectState(target.state);
}

function normalizeMenuDirectBody(bound, menuItem) {
  const formUuid = resolveManifestFormUuid(bound, menuItem);
  const pageId = resolveManifestPageId(bound, menuItem);
  const parentId = requireResolvedMenuParentId(
    bound,
    menuItem,
    new Map(),
    'direct menu mutation'
  );
  return stripUndefinedValues({
    resourceCode: menuItem.code || menuItem.resourceCode,
    name: menuItem.name || menuItem.code,
    type: menuItem.type || 'nav',
    formUuid,
    pageId,
    parentId,
    sortOrder: menuItem.sortOrder,
    icon: menuItem.icon || null,
    isHidden: menuItem.isHidden,
    routeCode: menuItem.routeCode || null,
    path: menuItem.path || null,
  });
}

function normalizePagePermissionGroupDirectBody(bound, group) {
  return stripUndefinedValues({
    resourceCode: group.code || group.resourceCode,
    name: group.name || group.code,
    roles: group.roles || [],
    menuFormUuids: resolvePagePermissionGroupTargets(bound, group),
    menuCodes: normalizePermissionCodeArray(group.menuCodes),
    routeCodes: normalizePermissionCodeArray(group.routeCodes),
    pathPatterns: normalizePermissionCodeArray(group.pathPatterns),
  });
}

function parseConnectorApiName(targetName, flags = {}) {
  const raw = String(targetName || '');
  const separator = raw.indexOf('.');
  const connectorCode = separator >= 0 ? raw.slice(0, separator) : raw;
  const apiCode = flags.api || flags['api-code'] || (separator >= 0 ? raw.slice(separator + 1) : undefined);
  if (!connectorCode || !apiCode) fail('连接器调用需要 <connectorCode.apiCode> 或 --api <apiCode>');
  return { connector: connectorCode, api: apiCode };
}

function extractNotificationTemplateBody(bound, body) {
  const template = Array.isArray(body.templates) ? body.templates[0] : body.template || body;
  return {
    ...template,
    code: template.code || template.templateCode || body.code || body.templateCode,
    formCode: template.formCode || body.formCode,
    formUuid: template.formUuid || body.formUuid,
    level: template.level || body.level,
  };
}

function extractNotificationTypeConfigBody(bound, body) {
  const config = Array.isArray(body.typeConfigs)
    ? body.typeConfigs[0]
    : Array.isArray(body.notificationTypeConfigs)
      ? body.notificationTypeConfigs[0]
      : body.typeConfig || body;
  return {
    ...config,
    notificationType: config.notificationType || body.notificationType || body.code,
    formCode: config.formCode || body.formCode,
    formUuid: config.formUuid || body.formUuid,
    level: config.level || body.level,
  };
}

function normalizeNotificationActionBody(subcommand, code, rawBody = {}) {
  const body = { ...(rawBody || {}) };
  if (body.variables && !body.payload) {
    body.payload = body.variables;
  }
  delete body.variables;

  if (subcommand === 'preview') {
    if (code && !body.templateCode && !body.templateId && !body.code) {
      body.templateCode = code;
    }
    return body;
  }

  if (code && !body.notificationType) {
    body.notificationType = code;
  }

  if (subcommand === 'send') {
    if (!body.recipientId && Array.isArray(body.recipientIds) && body.recipientIds.length === 1) {
      body.recipientId = body.recipientIds[0];
    }
    delete body.recipientIds;
    return body;
  }

  if (subcommand === 'batch-send') {
    if (!body.recipients && Array.isArray(body.recipientIds)) {
      body.recipients = body.recipientIds.map(recipientId => ({
        recipientId,
        payload: body.payload || {},
        ...(body.channels ? { channels: body.channels } : {}),
      }));
    }
    delete body.recipientIds;
    return body;
  }

  return body;
}

function buildPublicGrantChecks(bound, grants, flags = {}) {
  const checks = [];
  const formTargets = [
    ...splitList(flags['form-code']).map(code => resolveOptionalFormUuid(bound, code)),
    ...splitList(flags['form-uuid']),
  ].filter(Boolean);
  for (const formUuid of formTargets) {
    const action = String(flags['form-action'] || flags.action || '').trim().toLowerCase();
    const fieldId = String(flags['field-id'] || '').trim();
    checks.push({
      type: 'form',
      code: formUuid,
      action: action || undefined,
      fieldId: fieldId || undefined,
      allowed: (grants.forms || []).some(grant =>
        publicFormGrantAllows(grant, { formUuid, action, fieldId })
      ),
    });
  }
  for (const code of splitList(flags['data-view'])) {
    checks.push({ type: 'dataView', code, allowed: (grants.dataViews || []).includes(code) });
  }
  for (const code of splitList(flags.function || flags['function-code'])) {
    checks.push({ type: 'function', code, allowed: (grants.functions || []).includes(code) });
  }
  for (const code of splitList(flags.connector || flags['connector-code'])) {
    checks.push({ type: 'connector', code, allowed: (grants.connectors || []).includes(code) });
  }
  const storageGrants = Array.isArray(grants.storage) ? grants.storage : [];
  for (const bucketName of splitList(flags['storage-bucket'] || flags.bucket)) {
    const action = String(flags['storage-action'] || flags.action || 'upload').trim();
    const extension = String(flags.extension || flags.ext || '').replace(/^\./, '').toLowerCase();
    const mimeType = String(flags.mime || flags['mime-type'] || '').trim().toLowerCase();
    const visibility = String(flags.visibility || '').trim();
    const size = Number(flags.size || flags['size-bytes'] || 0);
    checks.push({
      type: 'storage',
      bucketName,
      action,
      allowed: storageGrants.some(grant =>
        publicStorageGrantAllows(grant, {
          bucketName,
          action,
          extension,
          mimeType,
          visibility,
          size,
        })
      ),
    });
  }
  if (checks.length === 0) {
    return [
      { type: 'forms', granted: grants.forms || [], allowed: true },
      { type: 'dataViews', granted: grants.dataViews || [], allowed: true },
      { type: 'functions', granted: grants.functions || [], allowed: true },
      { type: 'connectors', granted: grants.connectors || [], allowed: true },
      { type: 'storage', granted: storageGrants, allowed: true },
    ];
  }
  return checks;
}

function publicFormGrantAllows(grant, input) {
  if (!grant || typeof grant !== 'object' || Array.isArray(grant)) {
    return !input.action && (grant === '*' || grant === input.formUuid);
  }
  const identifiers = [grant.formUuid, grant.code, grant.formCode]
    .map(value => String(value || '').trim())
    .filter(Boolean);
  if (!identifiers.includes('*') && !identifiers.includes(input.formUuid)) return false;
  const actions = normalizePermissionCodeArray(grant.actions).map(action => action.toLowerCase());
  if (input.action && !actions.includes(input.action)) return false;
  const fields = normalizePermissionCodeArray(grant.fields || grant.fieldIds);
  if (fields.length > 0 && (!input.fieldId || !fields.includes(input.fieldId))) return false;
  return true;
}

function publicStorageGrantAllows(grant, input) {
  if (!grant || grant.bucketName !== input.bucketName) return false;
  const actions = Array.isArray(grant.actions) ? grant.actions : [];
  if (!actions.includes(input.action)) return false;
  if (input.visibility && String(grant.visibility || 'private') !== input.visibility) return false;
  if (input.size > 0 && Number(grant.maxSizeBytes || 0) > 0 && input.size > Number(grant.maxSizeBytes)) {
    return false;
  }
  if (input.extension) {
    const extensions = (grant.allowedExtensions || []).map(value =>
      String(value || '').replace(/^\./, '').toLowerCase()
    );
    if (!extensions.includes(input.extension)) return false;
  }
  if (input.mimeType) {
    const mimeTypes = (grant.allowedMimeTypes || []).map(value =>
      String(value || '').trim().toLowerCase()
    );
    if (!mimeTypes.includes(input.mimeType)) return false;
  }
  return true;
}

async function buildPermissionAudit(config, target, flags = {}) {
  const manifest = loadWorkspaceResources();
  const validation = validateWorkspaceResources(manifest);
  const roleCodes = new Set((manifest.roles || []).map(item => item.code || item.resourceCode).filter(Boolean));
  const policyCodes = new Set((manifest.dataScopePolicies || []).map(item => item.code || item.resourceCode).filter(Boolean));
  const scopePolicyRefs = [];
  const warnings = [...validation.warnings];
  const errors = [...validation.errors];
  for (const group of manifest.pagePermissionGroups || []) {
    for (const roleCode of group.roles || []) {
      if (roleCodes.size > 0 && !roleCodes.has(roleCode)) warnings.push(`page permission group ${group.code} 引用未声明角色: ${roleCode}`);
    }
  }
  for (const group of manifest.formPermissionGroups || []) {
    for (const roleCode of group.roles || []) {
      if (roleCodes.size > 0 && !roleCodes.has(roleCode)) warnings.push(`form permission group ${group.code} 引用未声明角色: ${roleCode}`);
    }
    const formUuid = resolveManifestFormUuid(target.bound, group);
    if (!formUuid) errors.push(`form permission group ${group.code} 缺少 formCode/formUuid`);
    if (group.dataPermission?.type === 'scope_policy') {
      const policyCode = getScopePolicyCode(group.dataPermission);
      if (policyCode) scopePolicyRefs.push(policyCode);
      if (policyCode && policyCodes.size > 0 && !policyCodes.has(policyCode)) {
        warnings.push(`form permission group ${group.code} 引用未声明 data-scope-policy: ${policyCode}`);
      }
    }
  }
  for (const dataView of manifest.dataViews || []) {
    for (const group of dataView.permissionGroups || []) {
      for (const roleCode of group.roles || []) {
        if (roleCodes.size > 0 && !roleCodes.has(roleCode)) {
          warnings.push(`data view ${dataView.code} permission group ${group.code || group.name || '?'} 引用未声明角色: ${roleCode}`);
        }
      }
      if (group.dataPermission?.type !== 'scope_policy') continue;
      const policyCode = getScopePolicyCode(group.dataPermission);
      if (policyCode) scopePolicyRefs.push(policyCode);
      if (policyCode && policyCodes.size > 0 && !policyCodes.has(policyCode)) {
        warnings.push(`data view ${dataView.code} permission group ${group.code || group.name || '?'} 引用未声明 data-scope-policy: ${policyCode}`);
      }
    }
  }
  if (scopePolicyRefs.length > 0 && (manifest.scopeGrantSources || []).length === 0) {
    warnings.push('权限组已引用 scope_policy，但本工作区未声明 scopeGrantSources；请确认授权来源由其他工作区或平台后台维护');
  }
  for (const policy of manifest.publicAccessPolicies || []) {
    const grants = normalizePublicAccessPolicyManifest(target.bound, policy).grants || {};
    if (
      (grants.forms || []).length === 0 &&
      (grants.dataViews || []).length === 0 &&
      (grants.functions || []).length === 0 &&
      (grants.connectors || []).length === 0
    ) {
      warnings.push(`public-access policy ${policy.code} 未声明任何 grants`);
    }
  }
  const result = {
    appType: target.appType,
    manifestCounts: Object.fromEntries(
      RESOURCE_SPECS.map(spec => [spec.key, (manifest[spec.key] || []).length])
    ),
    errors,
    warnings,
    scope: {
      dimensions: (manifest.scopeDimensions || []).length,
      grantSources: (manifest.scopeGrantSources || []).length,
      policies: (manifest.dataScopePolicies || []).length,
      referencedPolicies: unique(scopePolicyRefs),
    },
  };
  if (flags.live) {
    result.live = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/permissions/snapshot`,
      {
        method: 'POST',
        body: {
          formUuids: unique(
            (manifest.formPermissionGroups || [])
              .map(group => resolveManifestFormUuid(target.bound, group))
              .filter(Boolean)
          ),
        },
      }
    );
  }
  return result;
}

function ensureResourceBuckets(bound) {
  bound.resources = bound.resources || {};
  bound.resources.forms = bound.resources.forms || {};
  bound.resources.pages = bound.resources.pages || {};
  bound.resources.workflows = bound.resources.workflows || {};
  bound.resources.automations = bound.resources.automations || {};
  bound.resources.functions = bound.resources.functions || {};
  bound.resources.menus = bound.resources.menus || {};
  bound.resources.roles = bound.resources.roles || {};
  bound.resources.connectors = bound.resources.connectors || {};
  bound.resources.dataViews = bound.resources.dataViews || {};
  bound.resources.storageConfigs = bound.resources.storageConfigs || {};
  bound.resources.authConfigs = bound.resources.authConfigs || {};
  bound.resources.routes = bound.resources.routes || {};
  bound.resources.publicAccessPolicies = bound.resources.publicAccessPolicies || {};
  bound.resources.scopeDimensions = bound.resources.scopeDimensions || {};
  bound.resources.scopeGrantSources = bound.resources.scopeGrantSources || {};
  bound.resources.dataScopePolicies = bound.resources.dataScopePolicies || {};
  bound.resources.notifications = bound.resources.notifications || {};
  bound.resources.notifications.templates = bound.resources.notifications.templates || {};
  bound.resources.notifications.typeConfigs = bound.resources.notifications.typeConfigs || {};
  bound.resources.pagePermissionGroups = bound.resources.pagePermissionGroups || {};
  bound.resources.formPermissionGroups = bound.resources.formPermissionGroups || {};
  bound.resources.formSettings = bound.resources.formSettings || {};
}

function resolveFormUuid(bound, formKey, flags = {}) {
  if (flags['form-uuid']) return flags['form-uuid'];
  const mapped = bound.resources?.forms?.[formKey]?.formUuid;
  return mapped || formKey;
}

function normalizeFormExportMode(value) {
  const mode = String(value || 'xlsx').trim();
  if (['xlsx', 'xlsx-images', 'package'].includes(mode)) return mode;
  fail('--mode 只能是 xlsx、xlsx-images 或 package');
}

function buildFormExportQuery(formUuid, mode, flags = {}) {
  const query = {
    formUuid,
    exportAll: flags.all ? 'y' : 'n',
    embedImages: mode === 'xlsx-images' || mode === 'package' ? 'y' : 'n',
    currentPage: flags.page,
    pageSize: flags['page-size'],
    conditionType: flags['condition-type'],
    searchKeyWord: flags['search-keyword'],
    instanceStatus: flags['instance-status'],
    exportFields: flags.fields,
  };
  if (flags['filters-json']) {
    query.filters = JSON.stringify(readJsonArg(flags['filters-json'], 'filters-json'));
  }
  if (flags['order-json']) {
    query.order = JSON.stringify(readJsonArg(flags['order-json'], 'order-json'));
  }
  return query;
}

function writeDownloadedFile(download, outputFlag, fallbackFilename) {
  const filename = sanitizeDownloadFilename(download.filename || fallbackFilename);
  const target = String(outputFlag || '.');
  const absoluteTarget = path.resolve(process.cwd(), target);
  const targetIsDirectory =
    target.endsWith('/') ||
    target.endsWith(path.sep) ||
    target === '.' ||
    (fs.existsSync(absoluteTarget) && fs.statSync(absoluteTarget).isDirectory()) ||
    (!fs.existsSync(absoluteTarget) && !path.extname(absoluteTarget));
  const file = targetIsDirectory
    ? path.join(absoluteTarget, filename)
    : absoluteTarget;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, download.buffer);
  return {
    file,
    filename: path.basename(file),
  };
}

function sanitizeDownloadFilename(value) {
  return String(value || 'download.bin')
    .replace(/[\\/]+/g, '_')
    .replace(/[\0\r\n]+/g, '')
    .trim() || 'download.bin';
}

function readFormSchemaPlanBody(flags = {}) {
  if (flags['schema-json']) {
    return { schema: readJsonArg(flags['schema-json'], 'schema-json') };
  }
  if (flags['components-json']) {
    return { components: readJsonArg(flags['components-json'], 'components-json') };
  }
  if (flags['json-file'] || flags['body-json']) {
    return readDirectJsonBody(flags, 'form schema-plan');
  }
  fail('form schema-plan 需要 --schema-json <file> 或 --components-json <file>');
}

function resolveOptionalFormUuid(bound, formCode) {
  if (!formCode) return undefined;
  return bound.resources?.forms?.[formCode]?.formUuid || formCode;
}

function resolvePermissionSnapshotFormUuids(bound, flags = {}) {
  const directFormUuids = [
    ...splitList(flags['form-uuids']),
    ...splitList(flags['form-uuid']),
  ];
  const mappedFormUuids = [
    ...splitList(flags['form-codes']),
    ...splitList(flags['form-code']),
  ]
    .map(formCode => resolveOptionalFormUuid(bound, formCode))
    .filter(Boolean);
  const allFormUuids = flags['all-forms']
    ? Object.values(bound.resources?.forms || {})
        .map(item => item?.formUuid)
        .filter(Boolean)
    : [];
  return unique([...directFormUuids, ...mappedFormUuids, ...allFormUuids]);
}

function resolveOptionalPageId(bound, pageCode) {
  if (!pageCode) return undefined;
  return bound.resources?.pages?.[pageCode]?.pageId || pageCode;
}

function resolveMenuId(bound, menuKey, flags = {}) {
  if (flags['menu-id']) return flags['menu-id'];
  const mapped = bound.resources?.menus?.[menuKey]?.menuId;
  return mapped || menuKey;
}

function resolveWorkflowId(bound, workflowKey, flags = {}) {
  if (flags['workflow-id']) return flags['workflow-id'];
  const mapped = bound.resources?.workflows?.[workflowKey]?.workflowId;
  return mapped || workflowKey;
}

function resolveAutomationId(bound, automationKey, flags = {}) {
  if (flags['automation-id']) return flags['automation-id'];
  const mapped = bound.resources?.automations?.[automationKey]?.automationId;
  return mapped || automationKey;
}

function resolveRoleId(bound, roleKey, flags = {}) {
  if (flags['role-id']) return flags['role-id'];
  const mapped = bound.resources?.roles?.[roleKey]?.roleId;
  return mapped || roleKey;
}

async function resolveRoleMembershipIdForCommand(
  config,
  target,
  roleKey,
  flags = {}
) {
  return resolveRoleMembershipId({
    roleKey,
    explicitRoleId: flags['role-id'],
    localRoleId: target.bound.resources?.roles?.[roleKey]?.roleId,
    listRoles: async roleCode => {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`,
          {
            code: roleCode,
            page: 1,
            limit: 200,
          }
        )
      );
      return normalizeItems(data);
    },
  });
}

function resolvePagePermissionMenuTargets(bound, flags = {}) {
  const direct = [
    ...splitList(flags['menu-form-uuids']),
    ...splitList(flags['menu-ids']),
  ];
  const fromMenuCodes = splitList(flags['menu-codes']).flatMap(code => resolveMenuPermissionTargets(bound, code));
  const fromFormCodes = splitList(flags['form-codes']).map(code => resolveOptionalFormUuid(bound, code));
  const fromPageCodes = splitList(flags['page-codes']).flatMap(code => resolvePagePermissionTargets(bound, code));
  return unique([...direct, ...fromMenuCodes, ...fromFormCodes, ...fromPageCodes].filter(Boolean));
}

function resolveMenuPermissionTargets(bound, menuCode) {
  const menuEntry = bound.resources?.menus?.[menuCode];
  if (menuEntry?.formUuid) return [menuEntry.formUuid];
  return [resolveMenuId(bound, menuCode)];
}

function resolvePagePermissionTargets(bound, pageCode) {
  const menuEntry = findPagePermissionMenuEntry(bound, pageCode);
  if (menuEntry?.menuId) {
    return [menuEntry.menuId];
  }
  fail(`页面 ${pageCode} 未找到已绑定代码页菜单。请先发布/创建菜单，或直接传 --menu-form-uuids/--menu-ids。`);
}

function resolvePagePermissionRuntimeAliasTargets(bound, flags = {}) {
  const fromMenuCodes = splitList(flags['menu-codes']).flatMap(code => resolveMenuPermissionRuntimeAliases(bound, code));
  const fromPageCodes = splitList(flags['page-codes']).flatMap(code => resolvePagePermissionRuntimeAliases(bound, code));
  return unique([...fromMenuCodes, ...fromPageCodes].filter(Boolean));
}

function resolveMenuPermissionRuntimeAliases(bound, menuCode) {
  const menuEntry = bound.resources?.menus?.[menuCode];
  if (!menuEntry || menuEntry.formUuid) return [];
  if (menuEntry.pageId || menuEntry.pageCode || menuEntry.routeKey || menuEntry.legacyFormUuid) {
    return resolveCodePagePermissionAliases(bound, menuEntry);
  }
  return [];
}

function resolvePagePermissionRuntimeAliases(bound, pageCode) {
  const menuEntry = findPagePermissionMenuEntry(bound, pageCode);
  if (menuEntry?.menuId) return resolveCodePagePermissionAliases(bound, menuEntry, pageCode);
  fail(`页面 ${pageCode} 未找到已绑定菜单。请先发布/创建菜单，或直接传 --menu-codes/--menu-ids。`);
}

function findPagePermissionMenuEntry(bound, pageCode) {
  const pageId = resolveOptionalPageId(bound, pageCode);
  return findMenuEntry(bound, entry => {
    if (!entry) return false;
    return entry.pageId === pageId || entry.pageCode === pageCode || entry.routeKey === pageCode;
  });
}

function resolveCodePagePermissionAliases(bound, menuEntry = {}, pageCode) {
  const pageEntry = findPageEntry(bound, entry => {
    if (!entry) return false;
    return (
      entry.pageCode === pageCode ||
      entry.routeKey === pageCode ||
      entry.pageId === menuEntry.pageId ||
      entry.pageCode === menuEntry.pageCode ||
      entry.routeKey === menuEntry.routeKey ||
      entry.legacyFormUuid === menuEntry.legacyFormUuid
    );
  });
  return unique([
    pageCode,
    menuEntry.pageId,
    menuEntry.pageCode,
    menuEntry.routeKey,
    menuEntry.legacyFormUuid,
    pageEntry?.pageId,
    pageEntry?.pageCode,
    pageEntry?.routeKey,
    pageEntry?.legacyFormUuid,
  ].filter(Boolean));
}

function findMenuEntry(bound, predicate) {
  return Object.values(bound.resources?.menus || {}).find(predicate);
}

function findPageEntry(bound, predicate) {
  return Object.entries(bound.resources?.pages || {})
    .map(([pageCode, entry]) => ({ pageCode, ...(entry || {}) }))
    .find(predicate);
}

function resolveSettingsFormUuid(bound, formKey, flags = {}) {
  const key = formKey || flags['form-code'] || flags['form-uuid'];
  if (!key && !flags['form-uuid']) {
    fail('缺少表单标识。传入 <formCode|formUuid> 或 --form-code/--form-uuid');
  }
  return resolveFormUuid(bound, key, flags);
}

