function getResourceTypeFilters(positional = [], flags = {}) {
  const rawValues = [
    ...positional,
    flags.type,
    flags['resource-type'],
    flags['resource-types'],
  ]
    .filter(Boolean)
    .flatMap(value => String(value).split(','))
    .map(value => value.trim())
    .filter(Boolean);

  if (rawValues.length === 0) return null;

  const filters = new Set();
  for (const rawType of rawValues) {
    const normalized = normalizeResourceTypeAlias(rawType);
    const group = RESOURCE_TYPE_ALIAS_GROUPS.get(normalized);
    if (group) {
      for (const key of group) filters.add(key);
      continue;
    }
    const key = RESOURCE_TYPE_ALIASES.get(normalized);
    if (!key) {
      fail(
        `未知资源类型: ${rawType}。常用类型包括 workflow, notification, route, menu, role, ` +
          `storage, page-permission-group, form-permission-group, scope-policy, public-access。`
      );
    }
    filters.add(key);
  }
  return filters;
}

function getResourceCodeFilters(flags = {}) {
  const rawValues = [flags.only, flags.code, flags.codes]
    .filter(value => value !== undefined && value !== null && value !== false)
    .flatMap(value => String(value).split(','))
    .map(value => value.trim())
    .filter(Boolean);
  if (rawValues.length === 0) return null;

  const selectors = [];
  for (const rawValue of rawValues) {
    let resourceKey = null;
    let code = rawValue;
    const qualified = rawValue.match(/^([^:/]+)[:/](.+)$/);
    if (qualified) {
      const normalizedType = normalizeResourceTypeAlias(qualified[1]);
      const keys = RESOURCE_TYPE_ALIAS_GROUPS.get(normalizedType);
      const key = RESOURCE_TYPE_ALIASES.get(normalizedType);
      if (keys) {
        code = qualified[2].trim();
        selectors.push({ keys, qualifier: normalizedType, code, raw: rawValue });
        continue;
      }
      if (key) {
        code = qualified[2].trim();
        selectors.push({ key, code, raw: rawValue });
        continue;
      }
    }
    selectors.push({ key: resourceKey, code: code.trim(), raw: rawValue });
  }
  if (selectors.some(selector => !selector.code)) {
    fail('--only/--code 必须提供非空资源 code');
  }
  return selectors;
}

function getResourceItemCode(item) {
  return String(
    item?.code ||
      item?.resourceCode ||
      item?.methodName ||
      item?.formCode ||
      item?.notificationType ||
      ''
  );
}

function resourceCodeSelectorMatches(selector, resourceKey, item) {
  if (selector.key && selector.key !== resourceKey) return false;
  if (selector.keys && !selector.keys.includes(resourceKey)) return false;
  return getResourceItemCode(item) === selector.code;
}

function resourceCodeSelectorAppliesToKey(selector, resourceKey) {
  if (selector.key) return selector.key === resourceKey;
  if (selector.keys) return selector.keys.includes(resourceKey);
  return true;
}

function normalizeResourceTypeAlias(value) {
  return String(value || '')
    .trim()
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/[_\s]+/g, '-')
    .toLowerCase();
}

function loadWorkspaceResources(options = {}) {
  const baseDir = path.join(process.cwd(), 'src', 'resources');
  const typeFilters = options.typeFilters || null;
  const codeFilters = options.codeFilters || null;
  const matchedCodeFilters = new Set();
  const manifest = {
    baseDir,
    ...(typeFilters ? { resourceTypeFilters: Array.from(typeFilters).sort() } : {}),
    ...(codeFilters
      ? {
          resourceCodeFilters: codeFilters
            .map(selector =>
              selector.key
                ? `${selector.key}:${selector.code}`
                : selector.qualifier
                  ? `${selector.qualifier}:${selector.code}`
                  : selector.code
            )
            .sort(),
        }
      : {}),
  };
  if (codeFilters) {
    Object.defineProperty(manifest, '__resourceCodeSelectors', {
      value: codeFilters,
      configurable: true,
      enumerable: false,
      writable: false,
    });
  }
  for (const spec of RESOURCE_SPECS) {
    if (typeFilters && !typeFilters.has(spec.key)) {
      manifest[spec.key] = [];
      continue;
    }
    if (!codeFilters) {
      manifest[spec.key] = readResourceItems(baseDir, spec);
      continue;
    }

    const selectorEntries = codeFilters
      .map((selector, index) => ({ selector, index }))
      .filter(({ selector }) => resourceCodeSelectorAppliesToKey(selector, spec.key));
    if (selectorEntries.length === 0) {
      manifest[spec.key] = [];
      continue;
    }
    manifest[spec.key] = readResourceItems(baseDir, spec, {
      selectorEntries,
      matchedCodeFilters,
      // Composite menu/notification files may expose several logical codes
      // whose children cannot be located from the filename alone. They still
      // filter before validation/source analysis; exact Function/Automation
      // manifests use the fail-safe early file path below.
      selectorFileScope: !['menus', 'notifications'].includes(spec.key),
    });
  }
  if (codeFilters) {
    manifest.unmatchedResourceCodeFilters = codeFilters
      .filter((_, index) => !matchedCodeFilters.has(index))
      .map(selector => selector.raw);
  }
  return manifest;
}

async function attachLocalFormSchemas(manifest) {
  if (
    Array.isArray(manifest.resourceTypeFilters) &&
    !manifest.resourceTypeFilters.includes('formSettings')
  ) {
    return manifest;
  }
  const selectors = Array.isArray(manifest.__resourceCodeSelectors)
    ? manifest.__resourceCodeSelectors.filter(selector =>
        resourceCodeSelectorAppliesToKey(selector, 'formSettings')
      )
    : [];
  const candidateCodes = unique([
    ...(manifest.formSettings || []).map(getResourceItemCode),
    ...selectors.map(selector => selector.code),
  ]).filter(Boolean);
  if (candidateCodes.length === 0) return manifest;

  const loadedCodes = new Set();
  for (const code of candidateCodes) {
    let localSchema;
    try {
      localSchema = await loadLocalFormSchema(process.cwd(), code);
    } catch (error) {
      const wrapped = new Error(
        `FORM_SCHEMA_LOAD_FAILED: ${code}: ${error.message}`
      );
      wrapped.code = 'FORM_SCHEMA_LOAD_FAILED';
      throw wrapped;
    }
    if (!localSchema) continue;
    loadedCodes.add(code);
    const existing = (manifest.formSettings || []).find(
      item => getResourceItemCode(item) === code
    );
    const merged = {
      ...(existing || {}),
      code,
      formCode: existing?.formCode || code,
      name: existing?.name ?? localSchema.name,
      schema: localSchema.schema,
      packages: localSchema.packages,
      formType: existing?.formType ?? localSchema.formType,
      __source: existing?.__source || path.join(
        process.cwd(),
        localSchema.sourcePath
      ),
      __dir: existing?.__dir || path.dirname(
        path.join(process.cwd(), localSchema.sourcePath)
      ),
      __localSchema: {
        sourcePath: localSchema.sourcePath,
        fieldCount: localSchema.fieldCount,
      },
    };
    if (existing) {
      Object.assign(existing, merged);
    } else {
      manifest.formSettings = manifest.formSettings || [];
      manifest.formSettings.push(merged);
    }
  }
  manifest.formSettings = (manifest.formSettings || []).sort((left, right) =>
    getResourceItemCode(left).localeCompare(getResourceItemCode(right))
  );
  if (
    loadedCodes.size > 0 &&
    Array.isArray(manifest.unmatchedResourceCodeFilters)
  ) {
    manifest.unmatchedResourceCodeFilters =
      manifest.unmatchedResourceCodeFilters.filter(raw => {
        const code = String(raw || '').replace(/^.*[:/]/, '');
        return !loadedCodes.has(code);
      });
  }
  return manifest;
}

function readResourceItems(baseDir, spec, options = {}) {
  const items = [];
  const selectorEntries = options.selectorEntries || null;
  const matchedSelectorIndexes = new Set();
  const visitedFiles = new Set();
  const appendFile = filePath => {
    if (visitedFiles.has(filePath)) return;
    visitedFiles.add(filePath);
    const fileItems = readResourceItemsFromFile(filePath, spec);
    if (!selectorEntries) {
      items.push(...fileItems);
      return;
    }
    for (const item of fileItems) {
      let matched = false;
      for (const { selector, index } of selectorEntries) {
        if (!resourceCodeSelectorMatches(selector, spec.key, item)) continue;
        options.matchedCodeFilters?.add(index);
        matchedSelectorIndexes.add(index);
        matched = true;
      }
      if (matched) items.push(item);
    }
  };
  for (const relativeFile of spec.topFiles || []) {
    const filePath = path.join(baseDir, relativeFile);
    if (fs.existsSync(filePath)) {
      appendFile(filePath);
    }
  }

  const dirPath = path.join(baseDir, spec.dir);
  if (fs.existsSync(dirPath)) {
    if (selectorEntries && options.selectorFileScope !== false) {
      const remaining = () => selectorEntries.filter(
        ({ index }) => !matchedSelectorIndexes.has(index)
      );
      for (const filePath of listSelectedResourceJsonFiles(
        dirPath,
        spec,
        remaining().map(({ selector }) => selector.code)
      )) {
        appendFile(filePath);
      }
      if (remaining().length > 0) {
        // A direct path is only a hint. The file may declare another explicit
        // code, while the requested logical resource lives in an arbitrarily
        // named legacy bundle. Fall back only when no selected item actually
        // matched, preserving the standard-layout fast path.
        for (const filePath of listResourceJsonFiles(dirPath, spec)) {
          appendFile(filePath);
        }
      }
    } else {
      for (const filePath of listResourceJsonFiles(dirPath, spec)) {
        appendFile(filePath);
      }
    }
  }
  return items;
}

function readResourceItemsFromFile(filePath, spec) {
  let value;
  try {
    value = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (error) {
    return [
      {
        __invalid: true,
        __source: filePath,
        __error: `JSON 解析失败: ${error.message}`,
      },
    ];
  }

  return readResourceItemsFromValue(value, filePath, spec);
}

function readResourceItemsFromValue(value, filePath, spec) {
  const defaultCode = path.basename(filePath, '.json');
  const values = extractResourceValues(value, spec);
  return values.map((item, index) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      return {
        __invalid: true,
        __source: filePath,
        __error: '资源项必须是 JSON object',
      };
    }
    const code = inferResourceCode(item, spec, values.length === 1 ? defaultCode : undefined);
    return {
      ...item,
      ...(code ? { code } : {}),
      __source: filePath,
      __dir: path.dirname(filePath),
      __index: index,
    };
  });
}

function inferResourceCode(item, spec, defaultCode) {
  if (item.code || item.resourceCode || item.methodName) {
    return item.code || item.resourceCode || item.methodName;
  }
  if (spec.key === 'notifications') {
    return inferNotificationResourceCode(item) || defaultCode;
  }
  if (spec.key === 'formSettings') {
    return item.formCode || defaultCode;
  }
  return defaultCode;
}

function inferNotificationResourceCode(item) {
  const resourceType = normalizeNotificationResourceType(item);
  if (resourceType === 'template') return item.code || item.templateCode;
  if (resourceType !== 'typeConfig' || !item.notificationType) {
    return item.notificationType || item.templateCode;
  }
  const level = item.level || (item.formCode || item.formUuid ? 'form' : 'app');
  if (level === 'app') return item.notificationType;
  const formKey = item.formCode || item.formUuid || 'form';
  return `${level}:${formKey}:${item.notificationType}`;
}

function extractResourceValues(value, spec) {
  if (spec.key === 'notifications') return extractNotificationResourceValues(value);
  if (spec.key === 'menus') return extractMenuResourceValues(value);
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [value];
  for (const key of spec.pluralKeys || []) {
    if (Array.isArray(value[key])) return value[key];
  }
  if (value.resource && typeof value.resource === 'object') return [value.resource];
  return [value];
}

function extractMenuResourceValues(value) {
  const baseValues = (() => {
    if (Array.isArray(value)) return value;
    if (!value || typeof value !== 'object') return [value];
    if (Array.isArray(value.menus)) return value.menus;
    if (value.resource && typeof value.resource === 'object') return [value.resource];
    return [value];
  })();
  const result = [];
  const visit = (item, parentCode) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      result.push(item);
      return;
    }
    const { children, ...rest } = item;
    const code = rest.code || rest.resourceCode;
    result.push(parentCode && !rest.parentCode && !rest.parentId ? { ...rest, parentCode } : rest);
    if (!Array.isArray(children)) return;
    for (const child of children) {
      visit(child, code || parentCode);
    }
  };
  for (const item of baseValues) visit(item, null);
  return result;
}

function extractNotificationResourceValues(value) {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [value];
  const result = [];
  for (const template of value.templates || []) {
    result.push({ ...template, resourceType: 'template' });
  }
  for (const config of value.typeConfigs || value.notificationTypeConfigs || []) {
    result.push({ ...config, resourceType: 'typeConfig' });
  }
  if (Array.isArray(value.notifications)) {
    result.push(...value.notifications);
  }
  if (result.length > 0) return result;
  if (value.template || value.typeConfig) {
    return [
      value.template ? { ...value.template, resourceType: 'template' } : null,
      value.typeConfig ? { ...value.typeConfig, resourceType: 'typeConfig' } : null,
    ].filter(Boolean);
  }
  return [value];
}

function listJsonFiles(dirPath) {
  if (!fs.existsSync(dirPath)) return [];
  return fs
    .readdirSync(dirPath, { withFileTypes: true })
    .flatMap(entry => {
      const nextPath = path.join(dirPath, entry.name);
      if (entry.isDirectory()) return listJsonFiles(nextPath);
      return entry.isFile() && entry.name.endsWith('.json') ? [nextPath] : [];
    })
    .sort();
}

function listResourceJsonFiles(dirPath, spec) {
  return listJsonFiles(dirPath).filter(filePath =>
    shouldReadResourceJsonFile(filePath, dirPath, spec)
  );
}

function listSelectedResourceJsonFiles(dirPath, spec, selectedCodes = []) {
  const codeSet = new Set(selectedCodes.map(code => String(code || '').trim()).filter(Boolean));
  if (codeSet.size === 0) return [];

  const directCandidates = new Set();
  for (const code of codeSet) {
    if (
      code === '.' ||
      code === '..' ||
      code.includes('/') ||
      code.includes('\\')
    ) {
      continue;
    }
    const directFile = path.join(dirPath, `${code}.json`);
    if (fs.existsSync(directFile) && fs.statSync(directFile).isFile()) {
      directCandidates.add(directFile);
    }
    const directDir = path.join(dirPath, code);
    if (fs.existsSync(directDir) && fs.statSync(directDir).isDirectory()) {
      for (const filePath of listJsonFiles(directDir)) {
        if (shouldReadResourceJsonFile(filePath, dirPath, spec)) {
          directCandidates.add(filePath);
        }
      }
    }
  }
  return Array.from(directCandidates).sort();
}

function shouldReadResourceJsonFile(filePath, dirPath, spec) {
  if (spec.key !== 'workflows') return true;
  const relativeParts = path.relative(dirPath, filePath).split(path.sep);
  if (relativeParts.length <= 1) return true;
  return path.basename(filePath) === 'workflow.json';
}

function validateWorkspaceResources(manifest) {
  const errors = [];
  const warnings = [];
  const counts = {};
  if (!fs.existsSync(manifest.baseDir)) {
    warnings.push('未发现 src/resources；多资源正式开发请在该目录声明资源，或使用一等 CLI 子命令进行只读诊断/小步维护');
  }
  for (const spec of RESOURCE_SPECS) {
    const items = manifest[spec.key] || [];
    counts[spec.key] = items.length;
    for (const item of items) {
      validateResourceItem(spec.key, item, errors, warnings);
    }
  }
  validateNotificationReferences(manifest.notifications || [], errors);
  validateScopePermissionResources(manifest, errors, warnings);
  const sourceValidation = validateManifestSourceBindings({
    workspaceRoot: process.cwd(),
    manifest,
  });
  errors.push(...sourceValidation.errors);
  warnings.push(...sourceValidation.warnings);
  if ((manifest.unmatchedResourceCodeFilters || []).length > 0) {
    errors.push(
      `--only/--code 未匹配本地资源: ${manifest.unmatchedResourceCodeFilters.join(', ')}`
    );
  }
  return {
    valid: errors.length === 0,
    errors,
    warnings,
    counts,
    baseDir: manifest.baseDir,
    ...(manifest.resourceTypeFilters ? { resourceTypeFilters: manifest.resourceTypeFilters } : {}),
    ...(manifest.resourceCodeFilters ? { resourceCodeFilters: manifest.resourceCodeFilters } : {}),
    sourceDependencies: sourceValidation.sourceDependencies,
  };
}

function validateRuntimeResourceDeclarationParity(kind, item, errors) {
  if (!['automations', 'functions'].includes(kind)) return;
  if (!item.definitionJson && !item.definitionFile) return;
  let definition = item.definitionJson;
  if (definition === undefined && item.definitionFile) {
    const definitionPath = path.resolve(
      item.__dir || process.cwd(),
      item.definitionFile
    );
    try {
      definition = JSON.parse(fs.readFileSync(definitionPath, 'utf8'));
    } catch (error) {
      errors.push(
        `${resourceLabel(kind, item)}: 无法读取 definitionFile ${definitionPath}: ${error.message}`
      );
      return;
    }
  }
  // Function manifests historically use the outer resources block as the
  // authoritative declaration and inject resolved bindings into the runtime
  // definition during publish. Preserve that contract when the runtime omits
  // resources entirely; if it opts into an explicit declaration, it must agree.
  if (
    kind === 'functions' &&
    !Object.prototype.hasOwnProperty.call(definition || {}, 'resources')
  ) {
    return;
  }
  const diff = diffResourceDeclarations(
    item.resources,
    definition?.resources
  );
  if (!diff.matches) {
    errors.push(
      formatResourceDeclarationDrift(
        kind === 'automations' ? 'Automation' : 'Function',
        item.code || item.resourceCode || item.functionCode || 'unknown',
        diff
      )
    );
  }
}

function validateWorkspaceResourceBindings(
  manifest,
  bound,
  validation,
  stagedFormBindingOverlays = new Map()
) {
  for (const item of manifest.workflows || []) {
    if (!item.formCode && !item.form) continue;
    const formCode = item.formCode || item.form;
    const formBinding = bound?.resources?.forms?.[formCode];
    const formUuid = formBinding?.formUuid;
    if (!formUuid) {
      validation.errors.push(
        `${resourceLabel('workflow', item)}: formCode ${formCode} 未绑定。请先运行 openxiangda workspace publish --profile <name> --form ${formCode}`
      );
      continue;
    }
    const localSchemaPath = path.join(process.cwd(), 'src', 'forms', formCode, 'schema.ts');
    const stagedOverlay = stagedFormBindingOverlays.get(formCode);
    if (
      fs.existsSync(localSchemaPath) &&
      !formBinding.schemaSyncedAt &&
      !stagedOverlay
    ) {
      validation.errors.push(
        `${resourceLabel('workflow', item)}: formCode ${formCode} 已绑定但本地 schema 尚未同步。请先运行 openxiangda workspace publish --profile <name> --form ${formCode}`
      );
    }
    if (stagedOverlay) {
      validation.warnings.push(
        `${resourceLabel('workflow', item)}: formCode ${formCode} 使用已验证 staged FormRelease ${stagedOverlay.releaseId} 的冻结 schema/formType`
      );
    }
    const effectiveFormType = stagedOverlay?.formType || formBinding.formType;
    if (effectiveFormType && effectiveFormType !== 'process') {
      validation.errors.push(
        `${resourceLabel('workflow', item)}: formCode ${formCode} 当前 formType=${effectiveFormType}，流程表单需要 process`
      );
    }
  }
  validation.valid = validation.errors.length === 0;
  return validation;
}

async function validateCompiledWorkflowResources(manifest, validation) {
  for (const item of manifest.workflows || []) {
    if (!item.workflowFile) continue;
    try {
      item.__compiledWorkflow = await compileWorkflowSourceFile(item, {
        writeFiles: false,
      });
    } catch (error) {
      validation.errors.push(error?.message || String(error));
    }
  }
  validation.valid = validation.errors.length === 0;
  return validation;
}

function generateResourceTypes(manifest, outputFile) {
  const filePath = path.resolve(outputFile || path.join('src', 'generated', 'openxiangda.gen.ts'));
  const menus = (manifest.menus || []).map(item => ({
    code: item.code,
    routeCode: item.routeCode || null,
    path: item.path || null,
  }));
  const routes = (manifest.routes || []).map(item => ({
    code: item.code,
    pathPattern: item.pathPattern || item.path || null,
    publicAccess: item.publicAccess || 'none',
    publicPolicyCode: item.publicPolicyCode || item.policyCode || null,
  }));
  const pagePermissionGroups = (manifest.pagePermissionGroups || []).map(item => ({
    code: item.code,
    menuCodes: normalizePermissionCodeArray(item.menuCodes),
    routeCodes: normalizePermissionCodeArray(item.routeCodes),
    pathPatterns: normalizePermissionCodeArray(item.pathPatterns),
  }));
  const routeCodes = unique(
    [
      ...menus.map(item => item.routeCode),
      ...routes.map(item => item.code),
      ...pagePermissionGroups.flatMap(item => item.routeCodes),
    ].filter(Boolean)
  );
  const menuCodes = unique(menus.map(item => item.code).filter(Boolean));
  const pagePermissionGroupCodes = unique(
    pagePermissionGroups.map(item => item.code).filter(Boolean)
  );
  const dataViewCodes = unique((manifest.dataViews || []).map(item => item.code).filter(Boolean));
  const functionCodes = unique((manifest.functions || []).map(item => item.code).filter(Boolean));
  const storageConfigCodes = unique((manifest.storageConfigs || []).map(item => item.code).filter(Boolean));
  const authConfigCodes = unique((manifest.authConfigs || []).map(item => item.code).filter(Boolean));
  const publicAccessPolicyCodes = unique((manifest.publicAccessPolicies || []).map(item => item.code).filter(Boolean));
  const scopeDimensionCodes = unique((manifest.scopeDimensions || []).map(item => item.code).filter(Boolean));
  const scopeGrantSourceCodes = unique((manifest.scopeGrantSources || []).map(item => item.code).filter(Boolean));
  const dataScopePolicyCodes = unique((manifest.dataScopePolicies || []).map(item => item.code).filter(Boolean));
  const content = [
    '/* eslint-disable */',
    '// Generated by openxiangda resource typegen. Do not edit manually.',
    '',
    `export const menuCodes = ${JSON.stringify(menuCodes, null, 2)} as const`,
    'export type MenuCode = typeof menuCodes[number]',
    '',
    `export const routeCodes = ${JSON.stringify(routeCodes, null, 2)} as const`,
    'export type RouteCode = typeof routeCodes[number]',
    '',
    `export const pagePermissionGroupCodes = ${JSON.stringify(pagePermissionGroupCodes, null, 2)} as const`,
    'export type PagePermissionGroupCode = typeof pagePermissionGroupCodes[number]',
    '',
    `export const dataViewCodes = ${JSON.stringify(dataViewCodes, null, 2)} as const`,
    'export type DataViewCode = typeof dataViewCodes[number]',
    '',
    `export const storageConfigCodes = ${JSON.stringify(storageConfigCodes, null, 2)} as const`,
    'export type StorageConfigCode = typeof storageConfigCodes[number]',
    '',
    `export const functionCodes = ${JSON.stringify(functionCodes, null, 2)} as const`,
    'export type FunctionCode = typeof functionCodes[number]',
    '',
    `export const authConfigCodes = ${JSON.stringify(authConfigCodes, null, 2)} as const`,
    'export type AuthConfigCode = typeof authConfigCodes[number]',
    '',
    `export const publicAccessPolicyCodes = ${JSON.stringify(publicAccessPolicyCodes, null, 2)} as const`,
    'export type PublicAccessPolicyCode = typeof publicAccessPolicyCodes[number]',
    '',
    `export const scopeDimensionCodes = ${JSON.stringify(scopeDimensionCodes, null, 2)} as const`,
    'export type ScopeDimensionCode = typeof scopeDimensionCodes[number]',
    '',
    `export const scopeGrantSourceCodes = ${JSON.stringify(scopeGrantSourceCodes, null, 2)} as const`,
    'export type ScopeGrantSourceCode = typeof scopeGrantSourceCodes[number]',
    '',
    `export const dataScopePolicyCodes = ${JSON.stringify(dataScopePolicyCodes, null, 2)} as const`,
    'export type DataScopePolicyCode = typeof dataScopePolicyCodes[number]',
    '',
    `export const runtimeMenus = ${JSON.stringify(menus, null, 2)} as const`,
    '',
    `export const runtimeRoutes = ${JSON.stringify(routes, null, 2)} as const`,
    '',
    `export const pagePermissionGroups = ${JSON.stringify(pagePermissionGroups, null, 2)} as const`,
    '',
  ].join('\n');
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
  return {
    filePath,
    menuCodes: menuCodes.length,
    routeCodes: routeCodes.length,
    pagePermissionGroups: pagePermissionGroupCodes.length,
    dataViews: dataViewCodes.length,
    storageConfigs: storageConfigCodes.length,
    functions: functionCodes.length,
    authConfigs: authConfigCodes.length,
    publicAccessPolicies: publicAccessPolicyCodes.length,
    scopeDimensions: scopeDimensionCodes.length,
    scopeGrantSources: scopeGrantSourceCodes.length,
    dataScopePolicies: dataScopePolicyCodes.length,
  };
}

function validateResourceItem(kind, item, errors, warnings) {
  const label = resourceLabel(kind, item);
  if (item.__invalid) {
    errors.push(`${item.__source}: ${item.__error}`);
    return;
  }
  if (!item.code) errors.push(`${label}: 缺少 code`);

  if (kind === 'connectors') {
    if (!item.name) errors.push(`${label}: 缺少 name`);
    if (!item.domain && !item.url) errors.push(`${label}: 缺少 domain 或 url`);
    if (!Array.isArray(item.apis) || item.apis.length === 0) {
      errors.push(`${label}: 缺少 apis`);
    } else {
      item.apis.forEach((api, index) => {
        if (!api.code && !api.methodName) errors.push(`${label}.apis[${index}]: 缺少 code`);
        if (!api.path) errors.push(`${label}.apis[${index}]: 缺少 path`);
        if (!api.method) errors.push(`${label}.apis[${index}]: 缺少 method`);
      });
    }
    return;
  }

  if (kind === 'notifications') {
    validateNotificationResourceItem(item, errors, warnings);
    return;
  }

  if (kind === 'roles') {
    if (!item.name) errors.push(`${label}: 缺少 name`);
    if (
      item.apiPermissionCodes !== undefined &&
      !Array.isArray(item.apiPermissionCodes)
    ) {
      errors.push(`${label}: apiPermissionCodes 必须是数组`);
    }
    if (
      item.apiPermissionMode !== undefined &&
      !['merge', 'replace'].includes(String(item.apiPermissionMode))
    ) {
      errors.push(`${label}: apiPermissionMode 只能是 merge 或 replace`);
    }
  }
  if (kind === 'menus' && !item.name) errors.push(`${label}: 缺少 name`);
  if (kind === 'workflows') {
    if (!item.formCode && !item.formUuid) errors.push(`${label}: 缺少 formCode 或 formUuid`);
    if (!item.definitionJson && !item.definitionFile && !item.workflowFile) {
      errors.push(`${label}: 缺少 definitionJson、definitionFile 或 workflowFile`);
    }
  }
  if (kind === 'automations') {
    if (!item.name) errors.push(`${label}: 缺少 name`);
    if (!item.triggerConfig) errors.push(`${label}: 缺少 triggerConfig`);
    if (!item.definitionJson && !item.definitionFile) {
      errors.push(`${label}: 缺少 definitionJson 或 definitionFile`);
    }
    validateRuntimeResourceDeclarationParity(kind, item, errors);
  }
  if (kind === 'functions') {
    if (!item.name) errors.push(`${label}: 缺少 name`);
    if (!item.definitionJson && !item.definitionFile) {
      errors.push(`${label}: 缺少 definitionJson 或 definitionFile`);
    }
    validateRuntimeResourceDeclarationParity(kind, item, errors);
    validateFunctionSecretRefs(label, item, errors);
    validateFunctionRuntimeInvoke(label, item, errors, warnings);
    validateFunctionPerformancePolicies(label, item, errors);
  }
  if (kind === 'dataViews') {
    const definition = item.definition || item;
    const viewType = String(definition.viewType || 'row').toLowerCase();
    const storageMode = normalizeDataViewStorageMode(
      item.storageMode || definition.storageMode || 'materialized',
      label,
      errors
    );
    if (!item.name && !definition.name) errors.push(`${label}: 缺少 name`);
    if (!definition.base) errors.push(`${label}: 缺少 base`);
    if (viewType === 'aggregate') {
      if (Array.isArray(definition.select) && definition.select.length > 0) {
        errors.push(`${label}: 聚合数据视图不能同时使用 select`);
      }
      if (!Array.isArray(definition.measures) || definition.measures.length === 0) {
        errors.push(`${label}: 缺少 measures`);
      }
    } else if (viewType === 'row') {
      if (!Array.isArray(definition.select) || definition.select.length === 0) {
        errors.push(`${label}: 缺少 select`);
      }
    } else {
      errors.push(`${label}: 不支持的 viewType: ${definition.viewType}`);
    }
    for (const [index, group] of (item.permissionGroups || []).entries()) {
      const actions = group.actions || group.operations;
      if (actions !== undefined) {
        if (!Array.isArray(actions)) {
          errors.push(`${label}.permissionGroups[${index}]: actions/operations 必须是数组`);
        } else {
          for (const action of actions) {
            const normalizedAction = normalizePermissionActionValue(action);
            if (!DATA_VIEW_PERMISSION_ACTIONS.has(normalizedAction)) {
              errors.push(`${label}.permissionGroups[${index}]: 不支持的数据视图 action "${action}"`);
            }
          }
        }
      }
    }
    validateDataViewPerformance(label, definition, errors, warnings, storageMode);
  }
  if (kind === 'storageConfigs') {
    const config = item.configJson || item.config || item;
    const provider = String(item.provider || config.provider || 'oss').toLowerCase();
    if (provider !== 'oss') errors.push(`${label}: 当前仅支持 provider=oss`);
    if (!item.name && !config.name) warnings.push(`${label}: 未声明 name，将使用 code`);
    if (!config.region) errors.push(`${label}: 缺少 OSS region`);
    if (!config.bucket) errors.push(`${label}: 缺少 OSS bucket`);
    const status = item.status === undefined ? 'active' : String(item.status);
    if (!['active', 'disabled'].includes(status)) {
      errors.push(`${label}: status 只能是 active 或 disabled`);
    }
    const credentials = item.credentials || item.secret || item.secretJson || {};
    for (const key of ['accessKeyId', 'accessKeySecret']) {
      if (credentials[key] !== undefined && !isEnvReference(credentials[key])) {
        errors.push(`${label}.credentials.${key}: OSS 凭据必须使用环境变量引用`);
      }
    }
    if (!credentials.accessKeyId || !credentials.accessKeySecret) {
      warnings.push(`${label}: 未声明凭据；publish 只适用于更新并保留平台已有密文`);
    }
    const cors = config.cors || item.cors;
    if (cors?.managed === true) {
      const allowedOrigins = normalizeManifestStringArray(
        cors.allowedOrigins || cors.allowedOrigin || cors.origins || cors.origin
      );
      if (allowedOrigins.length === 0) {
        warnings.push(`${label}.cors.allowedOrigins: 未声明时后端将尝试使用当前平台域名`);
      }
      const allowedMethods = normalizeManifestStringArray(
        cors.allowedMethods || cors.allowedMethod || ['PUT', 'GET', 'HEAD']
      );
      if (allowedMethods.length === 0) errors.push(`${label}.cors.allowedMethods: 不能为空`);
      const maxAgeSeconds = Number(cors.maxAgeSeconds || 600);
      if (!Number.isFinite(maxAgeSeconds) || maxAgeSeconds < 0 || maxAgeSeconds > 86400) {
        errors.push(`${label}.cors.maxAgeSeconds: 必须在 0 到 86400 秒之间`);
      }
    }
  }
  if (kind === 'authConfigs') {
    const config = item.configJson || item.config || item;
    if (!Array.isArray(config.methods)) {
      errors.push(`${label}: 缺少 methods`);
    } else {
      config.methods.forEach((method, index) => {
        if (!method?.type) errors.push(`${label}.methods[${index}]: 缺少 type`);
        if (
          method?.type === 'phone_code' &&
          method.enabled !== false &&
          !(
            method.provider?.functionCode ||
            method.providerFunctionCode ||
            config.providers?.phone_code?.functionCode ||
            config.providers?.phoneCode?.functionCode
          )
        ) {
          errors.push(`${label}.methods[${index}]: phone_code 缺少 provider.functionCode`);
        }
      });
    }
    const registrationMode = String(config.registration?.mode || 'reject');
    if (registrationMode !== 'reject') {
      warnings.push(`${label}: 已开启非默认注册策略 ${registrationMode}，请确认身份匹配键、默认角色和审计字段`);
    }
  }
  if (kind === 'routes') {
    if (!item.pathPattern && !item.path) errors.push(`${label}: 缺少 pathPattern`);
    const mode = item.publicAccess === undefined ? 'none' : String(item.publicAccess);
    if (!['none', 'guest', 'ticket'].includes(mode)) {
      errors.push(`${label}: publicAccess 只能是 none、guest 或 ticket`);
    }
  }
  if (kind === 'publicAccessPolicies') {
    if (!item.name) warnings.push(`${label}: 未声明 name，将使用 code`);
    const mode = item.mode === undefined ? 'guest' : String(item.mode);
    if (!['guest', 'ticket'].includes(mode)) {
      errors.push(`${label}: mode 只能是 guest 或 ticket`);
    }
    if (!item.routeCode && !item.pathPattern && !item.path) {
      warnings.push(`${label}: 未声明 routeCode/pathPattern，建议绑定到 /view/:appType/public/* 路由`);
    }
    if (!item.grants || typeof item.grants !== 'object' || Array.isArray(item.grants)) {
      errors.push(`${label}: 缺少 grants object；未显式 grant 的 form/dataView/function/connector 默认拒绝`);
    }
    if (!Array.isArray(item.externalRoleCodes || item.externalRoles || item.roles || [])) {
      errors.push(`${label}: externalRoleCodes 必须是数组`);
    }
  }
  if (kind === 'scopeDimensions') {
    if (!item.name) warnings.push(`${label}: 未声明 name，将使用 code`);
    if (item.hierarchyMode && !['flat', 'self_parent'].includes(String(item.hierarchyMode))) {
      errors.push(`${label}: hierarchyMode 只能是 flat 或 self_parent`);
    }
    if ((item.sourceFormUuid || item.formUuid) && !item.sourceValueField && !item.valueField) {
      errors.push(`${label}: 使用表单维护维度时缺少 sourceValueField`);
    }
  }
  if (kind === 'scopeGrantSources') {
    if (!item.name) warnings.push(`${label}: 未声明 name，将使用 code`);
    if (!item.sourceFormUuid && !item.formUuid) errors.push(`${label}: 缺少 sourceFormUuid`);
    if (
      item.syncMode !== undefined &&
      !['on_write', 'manual'].includes(String(item.syncMode))
    ) {
      errors.push(`${label}: syncMode 只能是 on_write 或 manual`);
    }
    const subjectMappings = item.subjectMappings || item.subjects;
    const dimensionMappings = item.dimensionMappings || item.dimensions;
    if (!Array.isArray(subjectMappings) || subjectMappings.length === 0) {
      errors.push(`${label}: 缺少 subjectMappings`);
    }
    if (!Array.isArray(dimensionMappings) || dimensionMappings.length === 0) {
      errors.push(`${label}: 缺少 dimensionMappings`);
    }
  }
  if (kind === 'dataScopePolicies') {
    if (!item.name) warnings.push(`${label}: 未声明 name，将使用 code`);
    const rules = item.rules || item.dimensions;
    if (!Array.isArray(rules) || rules.length === 0) {
      errors.push(`${label}: 缺少 rules`);
    } else {
      rules.forEach((rule, index) => {
        const ruleLabel = `${label}.rules[${index}]`;
        const dimensionCode = rule.dimensionCode || rule.dimension;
        const targetField = rule.field || rule.targetField;
        if (!dimensionCode) errors.push(`${ruleLabel}: 缺少 dimensionCode`);
        if (!targetField) errors.push(`${ruleLabel}: 缺少 field/targetField`);
        if (rule.valuePath && !isSafeScopePolicyValuePath(rule.valuePath)) {
          errors.push(`${ruleLabel}: valuePath 只能包含字母、数字、下划线、中划线、点或 >`);
        }
        if (isScopePolicyMultiValueComponent(rule.componentType)) {
          warnings.push(`${ruleLabel}: 多值选择/人员/部门字段不适合直接作为 scope_policy 目标字段，建议派生隐藏 scalar key 字段`);
        } else if (
          !rule.valuePath &&
          !rule.componentType &&
          looksLikeJsonScopeTargetField(targetField)
        ) {
          warnings.push(`${ruleLabel}: 目标字段看起来可能是选择/人员/部门类字段；若底层是 JSONB，请声明 valuePath:"value" 或 componentType，优先使用隐藏 scalar key`);
        }
      });
    }
  }
  if (kind === 'pagePermissionGroups' && !item.name) errors.push(`${label}: 缺少 name`);
  if (kind === 'formPermissionGroups') {
    if (!item.name) errors.push(`${label}: 缺少 name`);
    if (!item.formCode && !item.formUuid) errors.push(`${label}: 缺少 formCode 或 formUuid`);
    const actions = item.actions || item.operations;
    if (actions !== undefined) {
      if (!Array.isArray(actions)) {
        errors.push(`${label}: actions/operations 必须是数组`);
      } else {
        for (const action of actions) {
          const normalizedAction = normalizePermissionActionValue(action);
          if (!FORM_PERMISSION_ACTIONS.has(normalizedAction)) {
            errors.push(`${label}: 不支持的表单 action "${action}"`);
          }
        }
      }
    }
    if (item.dataPermission?.type === 'scope_policy' && !getScopePolicyCode(item.dataPermission)) {
      errors.push(`${label}: dataPermission.type=scope_policy 时必须声明 policyCode`);
    }
  }
  if (kind === 'formSettings') {
    if (!item.formCode && !item.formUuid && !item.code) {
      errors.push(`${label}: 缺少 formCode、formUuid 或 code`);
    }
    validateFormRuntimeWriteSettings(label, item, errors);
    if (
      item.settings === undefined &&
      item.indexes === undefined &&
      item.dataManagement === undefined &&
      item.publicAccess === undefined &&
      item.runtimeWrite === undefined &&
      item.bundle === undefined &&
      item.name === undefined &&
      item.schema === undefined &&
      item.packages === undefined &&
      item.formType === undefined &&
      item.relateUuid === undefined
    ) {
      warnings.push(`${label}: 未声明任何 Form bundle 配置`);
    }
  }
}

const FUNCTION_RUNTIME_INVOKE_AUDIENCE_TYPES = new Set([
  'authenticated',
  'app_roles',
  'page_permission_group',
  'scope_policy',
]);

const FUNCTION_RUNTIME_INVOKE_MAGIC_ROLE_CODES = new Set([
  '*',
  'all-app-roles',
  'all_app_roles',
  'authenticated',
  'logged_in',
  'login',
]);

function validateFunctionRuntimeInvoke(label, item, errors, warnings) {
  const definition = item.definitionJson || {};
  const runtimeInvoke = item.runtimeInvoke || definition.runtimeInvoke;
  if (!runtimeInvoke) return;
  if (typeof runtimeInvoke !== 'object' || Array.isArray(runtimeInvoke)) {
    errors.push(`${label}: runtimeInvoke 必须是对象`);
    return;
  }
  if (
    runtimeInvoke.enabled !== undefined &&
    typeof runtimeInvoke.enabled !== 'boolean'
  ) {
    errors.push(`${label}: runtimeInvoke.enabled 必须是 boolean`);
  }

  const roleCodeValues = [
    runtimeInvoke.roleCodes,
    runtimeInvoke.roles,
    runtimeInvoke.allowedRoleCodes,
    definition.invokeRoleCodes,
  ];
  let hasRoleGrant = false;
  for (const value of roleCodeValues) {
    if (value === undefined) continue;
    if (!Array.isArray(value)) {
      errors.push(`${label}: runtimeInvoke roleCodes/roles/allowedRoleCodes 必须是数组`);
      continue;
    }
    if (value.length > 0) hasRoleGrant = true;
    for (const roleCode of value) {
      const normalized = String(roleCode || '').trim();
      if (!normalized) continue;
      if (FUNCTION_RUNTIME_INVOKE_MAGIC_ROLE_CODES.has(normalized.toLowerCase())) {
        errors.push(
          `${label}: runtimeInvoke.roleCodes 不支持魔法值 "${normalized}"；请使用 audience.type`
        );
      }
    }
  }

  const audiences = [
    runtimeInvoke.audience,
    runtimeInvoke.audiences,
    definition.invokeAudience,
    definition.invokeAudiences,
  ].filter(value => value !== undefined);
  for (const audience of audiences) {
    validateFunctionRuntimeInvokeAudience(label, audience, errors);
  }

  const hasAudience =
    audiences.length > 0 ||
    runtimeInvoke.allowAuthenticated === true ||
    runtimeInvoke.authenticated === true ||
    runtimeInvoke.allowLoggedIn === true ||
    runtimeInvoke.scopePolicyCode ||
    runtimeInvoke.policyCode ||
    runtimeInvoke.dataScopePolicyCode ||
    runtimeInvoke.pagePermissionGroupCodes ||
    runtimeInvoke.pagePermissionGroups ||
    runtimeInvoke.pageGroups;

  if (!hasAudience && !hasRoleGrant) {
    warnings.push(
      `${label}: runtimeInvoke 未声明 audience 或有效 roleCodes，页面运行时调用仍会要求 app:automation:manage`
    );
  }
}

function validateFunctionPerformancePolicies(label, item, errors) {
  const definition = item.definitionJson || {};
  const responseCache = definition.responseCache;
  if (responseCache !== undefined) {
    if (!responseCache || typeof responseCache !== 'object' || Array.isArray(responseCache)) {
      errors.push(`${label}: responseCache 必须是对象`);
    } else {
      if (responseCache.enabled !== undefined && typeof responseCache.enabled !== 'boolean') {
        errors.push(`${label}: responseCache.enabled 必须是 boolean`);
      }
      const ttlSeconds = Number(responseCache.ttlSeconds);
      if (!Number.isInteger(ttlSeconds) || ttlSeconds < 1 || ttlSeconds > 86400) {
        errors.push(`${label}: responseCache.ttlSeconds 必须是 1-86400 的整数`);
      }
      if (!Array.isArray(responseCache.actions) || responseCache.actions.length === 0) {
        errors.push(`${label}: responseCache.actions 必须是非空数组`);
      }
      if (responseCache.scope !== 'public_policy') {
        errors.push(`${label}: responseCache.scope 当前仅支持 public_policy`);
      }
      if (
        responseCache.invalidateOnForms !== undefined &&
        !Array.isArray(responseCache.invalidateOnForms)
      ) {
        errors.push(`${label}: responseCache.invalidateOnForms 必须是数组`);
      }
      if (responseCache.maxValueBytes !== undefined) {
        const maxValueBytes = Number(responseCache.maxValueBytes);
        if (!Number.isInteger(maxValueBytes) || maxValueBytes < 1024 || maxValueBytes > 4194304) {
          errors.push(`${label}: responseCache.maxValueBytes 必须是 1024-4194304 的整数`);
        }
      }
    }
  }

  const invocationAudit = definition.invocationAudit;
  if (invocationAudit !== undefined) {
    if (!invocationAudit || typeof invocationAudit !== 'object' || Array.isArray(invocationAudit)) {
      errors.push(`${label}: invocationAudit 必须是对象`);
    } else {
      if (
        invocationAudit.successOutput !== undefined &&
        !['full', 'summary'].includes(String(invocationAudit.successOutput))
      ) {
        errors.push(`${label}: invocationAudit.successOutput 只能是 full 或 summary`);
      }
      if (invocationAudit.maxLogBytes !== undefined) {
        const maxLogBytes = Number(invocationAudit.maxLogBytes);
        if (!Number.isInteger(maxLogBytes) || maxLogBytes < 1024 || maxLogBytes > 65536) {
          errors.push(`${label}: invocationAudit.maxLogBytes 必须是 1024-65536 的整数`);
        }
      }
    }
  }
}

function validateFunctionRuntimeInvokeAudience(label, value, errors) {
  if (Array.isArray(value)) {
    value.forEach(item => validateFunctionRuntimeInvokeAudience(label, item, errors));
    return;
  }
  if (typeof value === 'string') {
    const type = normalizeFunctionRuntimeInvokeAudienceType(value);
    if (!FUNCTION_RUNTIME_INVOKE_AUDIENCE_TYPES.has(type)) {
      errors.push(`${label}: 不支持的 runtimeInvoke.audience 类型 "${value}"`);
    }
    return;
  }
  if (!value || typeof value !== 'object') {
    errors.push(`${label}: runtimeInvoke.audience 必须是字符串、对象或数组`);
    return;
  }
  const type = normalizeFunctionRuntimeInvokeAudienceType(value.type);
  if (!FUNCTION_RUNTIME_INVOKE_AUDIENCE_TYPES.has(type)) {
    errors.push(`${label}: 不支持的 runtimeInvoke.audience.type "${value.type || ''}"`);
    return;
  }
  if (type === 'app_roles') {
    const roleCodes = normalizePermissionCodeArray(value.roleCodes || value.roles);
    if (!roleCodes.length) {
      errors.push(`${label}: audience.type=app_roles 时必须声明 roleCodes`);
    }
    for (const roleCode of roleCodes) {
      if (FUNCTION_RUNTIME_INVOKE_MAGIC_ROLE_CODES.has(roleCode.toLowerCase())) {
        errors.push(
          `${label}: audience.roleCodes 不支持魔法值 "${roleCode}"；请改用 authenticated/page_permission_group/scope_policy`
        );
      }
    }
  }
  if (type === 'scope_policy') {
    const policyCode = String(
      value.policyCode || value.scopePolicyCode || value.dataScopePolicyCode || ''
    ).trim();
    if (!policyCode) {
      errors.push(`${label}: audience.type=scope_policy 时必须声明 policyCode`);
    }
  }
}

function normalizeFunctionRuntimeInvokeAudienceType(value) {
  const type = String(value || '')
    .trim()
    .replace(/[-\s]+/g, '_')
    .toLowerCase();
  if (['logged_in', 'login', 'all_authenticated'].includes(type)) {
    return 'authenticated';
  }
  if (['app_role', 'roles', 'role_codes'].includes(type)) {
    return 'app_roles';
  }
  if (['page_permission_groups', 'page_group', 'page_groups'].includes(type)) {
    return 'page_permission_group';
  }
  if (['data_scope_policy', 'business_scope_policy'].includes(type)) {
    return 'scope_policy';
  }
  return type;
}

function validateFormRuntimeWriteSettings(label, item, errors) {
  const runtimeWrite = item.runtimeWrite || item.settings?.runtimeWrite;
  if (runtimeWrite === undefined) return;
  if (!runtimeWrite || typeof runtimeWrite !== 'object' || Array.isArray(runtimeWrite)) {
    errors.push(`${label}: runtimeWrite 必须是对象`);
    return;
  }
  const mode = String(runtimeWrite.mode || '').trim();
  if (!['permission_group', 'function_only', 'public_form'].includes(mode)) {
    errors.push(
      `${label}: runtimeWrite.mode 只能是 permission_group、function_only 或 public_form`
    );
  }
}

function validateScopePermissionResources(manifest, errors, warnings) {
  const policyCodes = new Set(
    (manifest.dataScopePolicies || [])
      .map(item => item.code || item.resourceCode)
      .filter(Boolean)
      .map(String)
  );
  const scopePolicyRefs = [];
  for (const source of manifest.scopeGrantSources || []) {
    if (String(source.syncMode || '').trim() === 'manual') {
      warnings.push(`${resourceLabel('scopeGrantSources', source)}: syncMode=manual，运行时来源表单变更不会自动物化；请确认有显式 scope sync 作业`);
    }
  }
  const inspectPermissionGroup = (kind, item) => {
    const groups = kind === 'dataViews'
      ? (Array.isArray(item.permissionGroups) ? item.permissionGroups : [])
      : [item];
    for (const group of groups) {
      const actions = kind === 'dataViews'
        ? normalizeDataViewPermissionGroupActions(group)
        : normalizeFormPermissionGroupActions(group);
      const dataPermission = group?.dataPermission;
      if (
        kind === 'formPermissionGroups' &&
        actions.includes('create') &&
        (!dataPermission || dataPermission.type !== 'scope_policy')
      ) {
        warnings.push(`${resourceLabel(kind, item)}: 声明了 create，但未声明 create 对应的 scope_policy；若新增数据必须落在用户业务范围内，请补充 dataPermission.type=scope_policy`);
      }
      if (!dataPermission) continue;
      if (dataPermission.type === 'scope_policy') {
        if (kind === 'formPermissionGroups') {
          const missing = ['view', 'edit', 'delete', 'export']
            .filter(action => !actions.includes(action));
          if (missing.length) {
            warnings.push(`${resourceLabel(kind, item)}: 使用 scope_policy 但 action 覆盖不完整，缺少 ${missing.join(', ')}；请确认每个角色的 action matrix`);
          }
        }
        if (kind === 'dataViews') {
          const missing = ['query', 'stats', 'export']
            .filter(action => !actions.includes(action));
          if (missing.length) {
            warnings.push(`${resourceLabel(kind, item)}: Data View 使用 scope_policy 但 action 覆盖不完整，缺少 ${missing.join(', ')}`);
          }
        }
        const policyCode = getScopePolicyCode(dataPermission);
        if (!policyCode) {
          errors.push(`${resourceLabel(kind, item)}: scope_policy 缺少 policyCode`);
          continue;
        }
        scopePolicyRefs.push(policyCode);
        if (policyCodes.size > 0 && !policyCodes.has(policyCode)) {
          warnings.push(`${resourceLabel(kind, item)}: scope_policy 引用 ${policyCode}，但 src/resources 中未声明同名 data-scope-policy`);
        }
      } else if (containsBusinessScopeLikeField(dataPermission)) {
        warnings.push(`${resourceLabel(kind, item)}: 检测到疑似业务范围字段条件，业务对象数量超过少量枚举时优先改为 dataPermission.type=scope_policy`);
      }
    }
  };
  for (const group of manifest.formPermissionGroups || []) {
    inspectPermissionGroup('formPermissionGroups', group);
  }
  for (const view of manifest.dataViews || []) {
    inspectPermissionGroup('dataViews', view);
  }
  const formGroupCount = (manifest.formPermissionGroups || []).length;
  const pageGroupCount = (manifest.pagePermissionGroups || []).length;
  if (formGroupCount >= 30) {
    warnings.push(`formPermissionGroups 当前 ${formGroupCount} 个；如这些组按客户/项目/区域/学院/班级/门店拆分，建议收敛为业务授权表 + scope_policy`);
  }
  if (pageGroupCount >= 30) {
    warnings.push(`pagePermissionGroups 当前 ${pageGroupCount} 个；如这些组按业务对象拆分，建议只保留入口角色，数据范围交给 scope_policy`);
  }
  if (scopePolicyRefs.length > 0 && (manifest.scopeGrantSources || []).length === 0) {
    warnings.push('已引用 scope_policy，但未声明 scopeGrantSources；请确认授权来源由平台后台或其他工作区维护');
  }
}

function getScopePolicyCode(dataPermission = {}) {
  return String(
    dataPermission.policyCode ||
      dataPermission.scopePolicyCode ||
      dataPermission.code ||
      ''
  ).trim();
}

function isSafeScopePolicyValuePath(value) {
  return /^[A-Za-z0-9_.>-]+$/.test(String(value || ''));
}

function isScopePolicyMultiValueComponent(componentType) {
  const normalized = String(componentType || '').trim().toLowerCase();
  return [
    'multiselect',
    'multiselectfield',
    'checkbox',
    'checkboxfield',
    'cascadeselect',
    'cascadeselectfield',
  ].includes(normalized);
}

function looksLikeJsonScopeTargetField(field) {
  return /(select|option|user|employee|member|dept|department|linked|association|人员|用户|部门|选择)/i.test(String(field || ''));
}

function containsBusinessScopeLikeField(value) {
  const fields = [];
  const visit = item => {
    if (!item || typeof item !== 'object') return;
    if (Array.isArray(item)) {
      item.forEach(visit);
      return;
    }
    if (item.field || item.key || item.targetField) {
      fields.push(String(item.field || item.key || item.targetField));
    }
    visit(item.condition);
    visit(item.conditions);
    visit(item.rules);
  };
  visit(value);
  return fields.some(field =>
    /(scope|customer|client|project|region|area|store|shop|campus|college|school|class|班级|学院|校区|区域|门店|客户|项目)/i.test(field)
  );
}

function validateDataViewPerformance(label, definition, errors, warnings, storageMode = 'materialized') {
  const viewType = String(definition.viewType || 'row').toLowerCase();
  if (viewType !== 'row' && viewType !== 'aggregate') return;
  const outputAliases = collectDataViewOutputAliases(definition, viewType);
  const outputAliasSet = new Set(outputAliases);
  const indexes = Array.isArray(definition.indexes)
    ? definition.indexes.filter(index => Array.isArray(index.fields) && index.fields.length > 0)
    : [];

  for (const index of indexes) {
    for (const field of index.fields || []) {
      if (!outputAliasSet.has(field)) {
        errors.push(`${label}: 索引字段不在输出字段中: ${field}`);
      }
    }
  }

  if (storageMode === 'live') {
    if (indexes.length) {
      warnings.push(`${label}: live 数据视图不会创建物化索引，indexes 仅在 materialized 模式生效`);
    }
    return;
  }

  if (!indexes.length) {
    warnings.push(
      viewType === 'aggregate'
        ? `${label}: 聚合数据视图未声明 indexes；请优先索引常用维度、时间桶或排序字段，避免统计查询扫描物化视图`
        : `${label}: 未声明 indexes；请为常用 filters/order 字段声明索引，避免运行时查询扫描物化视图`
    );
  }

  if (viewType === 'aggregate') {
    const dimensionAliases = new Set(
      (Array.isArray(definition.dimensions) ? definition.dimensions : [])
        .map(item => item && item.as)
        .filter(Boolean)
    );
    const indexesCoverDimension =
      dimensionAliases.size === 0 ||
      indexes.some(index => index.fields.some(field => dimensionAliases.has(field)));
    if (indexes.length && !indexesCoverDimension) {
      warnings.push(`${label}: 聚合数据视图 indexes 未覆盖任何 dimension；按维度筛选或排序时可能扫描物化视图`);
    }
    if ((definition.measures || []).some(isCountDistinctMeasure)) {
      warnings.push(`${label}: 聚合数据视图使用 countDistinct；高基数字段刷新成本较高，请确认数据量和刷新频率`);
    }
  }

  const refresh = definition.refresh && typeof definition.refresh === 'object' ? definition.refresh : {};
  if (refresh.mode === 'scheduled') {
    const intervalMs = estimateCronIntervalMsFromExpression(refresh.cron);
    if (intervalMs !== null && intervalMs < 5 * 60 * 1000) {
      warnings.push(`${label}: 数据视图刷新间隔低于 5 分钟；请先确认业务时间敏感度，高频刷新会增加源表和物化视图压力`);
    }
  }
}

function normalizeDataViewStorageMode(value, label, errors) {
  const storageMode = String(value || 'materialized').trim().toLowerCase();
  if (storageMode === 'materialized' || storageMode === 'live') return storageMode;
  errors.push(`${label}: 不支持的 storageMode: ${value}`);
  return 'materialized';
}

function collectDataViewOutputAliases(definition, viewType) {
  if (viewType === 'aggregate') {
    return [
      ...(Array.isArray(definition.dimensions) ? definition.dimensions : []),
      ...(Array.isArray(definition.measures) ? definition.measures : []),
    ]
      .map(item => item && item.as)
      .filter(Boolean);
  }
  return (Array.isArray(definition.select) ? definition.select : [])
    .map(item => item && item.as)
    .filter(Boolean);
}

function isCountDistinctMeasure(measure) {
  const normalized = String(measure?.type || '')
    .toLowerCase()
    .replace(/[-_]/g, '');
  return normalized === 'countdistinct' || normalized === 'distinctcount';
}

function estimateCronIntervalMsFromExpression(cron) {
  const parts = String(cron || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (parts.length < 5) return null;
  const hasSeconds = parts.length >= 6;
  const seconds = hasSeconds ? parts[0] : '0';
  const minutes = hasSeconds ? parts[1] : parts[0];
  if (seconds === '*') return 1000;
  const secondStep = parseCronStep(seconds);
  if (secondStep) return secondStep * 1000;
  if (seconds === '0') {
    if (minutes === '*') return 60 * 1000;
    const minuteStep = parseCronStep(minutes);
    if (minuteStep) return minuteStep * 60 * 1000;
  }
  return null;
}

function parseCronStep(field) {
  const match = String(field || '').match(/^(?:\*|0)\/(\d+)$/);
  if (!match) return null;
  const value = Number(match[1]);
  return Number.isFinite(value) && value > 0 ? value : null;
}

const NOTIFICATION_CHANNELS = new Set([
  'inapp',
  'email',
  'dingding',
  'wechat',
  'thirdparty_todo',
]);

function validateNotificationResourceItem(item, errors, warnings) {
  const label = resourceLabel('notifications', item);
  const resourceType = normalizeNotificationResourceType(item);
  if (!resourceType) {
    errors.push(`${label}: resourceType 必须是 template 或 typeConfig`);
    return;
  }

  if (resourceType === 'template') {
    if (!item.code) errors.push(`${label}: 通知模板缺少 code`);
    if (!item.name) errors.push(`${label}: 通知模板缺少 name`);
    if (item.level && !['app', 'form'].includes(item.level)) {
      errors.push(`${label}: OpenXiangda 通知模板 level 只能是 app 或 form`);
    }
    if ((item.level === 'form' || item.formCode || item.formUuid) && !item.formCode && !item.formUuid) {
      errors.push(`${label}: 表单级通知模板缺少 formCode 或 formUuid`);
    }
    if (!item.content && !item.channelsConfig) {
      warnings.push(`${label}: 未声明 content 或 channelsConfig`);
    }
    validateNotificationChannels(label, item.channelsConfig, errors);
    return;
  }

  if (!item.notificationType) errors.push(`${label}: 通知类型配置缺少 notificationType`);
  if (!item.templateCode && !item.templateId) {
    errors.push(`${label}: 通知类型配置缺少 templateCode 或 templateId`);
  }
  if (item.level && !['app', 'form'].includes(item.level)) {
    errors.push(`${label}: OpenXiangda 通知类型配置 level 只能是 app 或 form`);
  }
  if ((item.level === 'form' || item.formCode || item.formUuid) && !item.formCode && !item.formUuid) {
    errors.push(`${label}: 表单级通知类型配置缺少 formCode 或 formUuid`);
  }
}

function normalizeNotificationResourceType(item) {
  const value = item.resourceType || item.kind || item.type;
  if (value === 'template' || value === 'notificationTemplate') return 'template';
  if (value === 'typeConfig' || value === 'notificationTypeConfig') return 'typeConfig';
  if (item.notificationType || item.templateCode || item.templateId) return 'typeConfig';
  if (item.channelsConfig || item.content || item.variables) return 'template';
  return undefined;
}

function validateNotificationReferences(items, errors) {
  const templates = new Set(
    (items || [])
      .filter(item => normalizeNotificationResourceType(item) === 'template')
      .map(item => item.code)
      .filter(Boolean)
  );
  for (const item of items || []) {
    if (normalizeNotificationResourceType(item) !== 'typeConfig') continue;
    if (item.templateCode && !templates.has(item.templateCode) && !item.templateId) {
      errors.push(
        `${resourceLabel('notifications', item)}: templateCode ${item.templateCode} 未在 src/resources/notifications 中声明`
      );
    }
  }
}

function validateNotificationChannels(label, channelsConfig, errors) {
  if (!channelsConfig || typeof channelsConfig !== 'object' || Array.isArray(channelsConfig)) {
    return;
  }
  for (const [channel, config] of Object.entries(channelsConfig)) {
    if (!NOTIFICATION_CHANNELS.has(channel)) {
      errors.push(`${label}: 不支持的通知渠道 ${channel}`);
    }
    validateNoSensitiveNotificationConfig(`${label}.channelsConfig.${channel}`, config, errors);
    if (channel === 'dingding') {
      validateDingTalkNotificationConfig(
        `${label}.channelsConfig.${channel}`,
        config,
        errors
      );
    }
  }
}

function validateNoSensitiveNotificationConfig(label, value, errors) {
  if (!value || typeof value !== 'object') return;
  for (const [key, item] of Object.entries(value)) {
    if (/token|secret|password|authorization|auth|credential|headers/i.test(key)) {
      errors.push(`${label}.${key}: 通知资源不允许配置通道密钥或鉴权字段`);
      continue;
    }
    validateNoSensitiveNotificationConfig(`${label}.${key}`, item, errors);
  }
}

function validateDingTalkNotificationConfig(label, value, errors) {
  const config = value?.config || {};
  if (!config || typeof config !== 'object' || Array.isArray(config)) return;
  if (
    config.deliveryMode !== undefined &&
    !['card_preferred', 'card_only', 'work_notice_only'].includes(
      String(config.deliveryMode)
    )
  ) {
    errors.push(`${label}.config.deliveryMode: 只能是 card_preferred、card_only 或 work_notice_only`);
  }
  const card = config.card || {};
  if (card && typeof card === 'object' && !Array.isArray(card)) {
    if (
      card.mode !== undefined &&
      !['standard', 'custom'].includes(String(card.mode))
    ) {
      errors.push(`${label}.config.card.mode: 只能是 standard 或 custom`);
    }
    if (
      card.mode === 'custom' &&
      card.paramMap !== undefined &&
      (!card.paramMap ||
        typeof card.paramMap !== 'object' ||
        Array.isArray(card.paramMap))
    ) {
      errors.push(`${label}.config.card.paramMap: custom 卡片 paramMap 必须是对象`);
    }
    if (
      card.fieldConfigs !== undefined &&
      !Array.isArray(card.fieldConfigs)
    ) {
      errors.push(`${label}.config.card.fieldConfigs: 必须是数组`);
    }
  }
}

function resolveNotificationChannelEnvReferences(value) {
  if (!value || typeof value !== 'object') return value;
  if (Array.isArray(value)) {
    return value.map(item => resolveNotificationChannelEnvReferences(item));
  }
  const next = {};
  for (const [key, item] of Object.entries(value)) {
    if (
      ['cardTemplateId', 'dingTalkTemplateId'].includes(key) &&
      isEnvReference(item)
    ) {
      next[key] = resolveEnvReference(item, `DingTalk ${key}`);
    } else {
      next[key] = resolveNotificationChannelEnvReferences(item);
    }
  }
  return next;
}

function resourceLabel(kind, item) {
  return `${kind}:${item.code || item.__source || item.__index || '?'}`;
}

async function getAutomationExecutionDetailFromCli(config, target, instanceId, automationKey) {
  const automationIds = [];
  if (automationKey) {
    automationIds.push(resolveAutomationId(target.bound, automationKey, {}));
  } else {
    for (const entry of Object.values(target.bound.resources?.automations || {})) {
      if (entry?.automationId) automationIds.push(entry.automationId);
    }
  }
  const uniqueAutomationIds = Array.from(new Set(automationIds.filter(Boolean)));
  if (uniqueAutomationIds.length === 0) {
    fail('无法定位自动化，请传入 --automation <automationCode|automationId> 或先绑定本地自动化资源');
  }

  let lastError;
  for (const automationId of uniqueAutomationIds) {
    try {
      return await requestWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(automationId)}/executions/${encodeURIComponent(instanceId)}`
      );
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError || new Error(`执行记录不存在: ${instanceId}`);
}

function printAutomationExecutionList(result) {
  const rows = Array.isArray(result?.data) ? result.data : [];
  if (rows.length === 0) {
    print('暂无执行记录');
    return;
  }
  for (const item of rows) {
    print(
      [
        item.id,
        item.status,
        item.triggerEventType,
        `${item.executionDuration ?? 0}ms`,
        item.startedAt || item.createdAt || '',
        item.errorMessage ? `error=${item.errorMessage}` : '',
      ]
        .filter(Boolean)
        .join('  ')
    );
  }
  if (result?.totalCount !== undefined) {
    print(`共 ${result.totalCount} 条，page=${result.page || 1}, pageSize=${result.pageSize || rows.length}`);
  }
}

function printAutomationExecutionLogs(detail, options = {}) {
  if (options.summary) {
    print(buildAutomationDiagnosis(detail));
    return;
  }
  print(`执行记录: ${detail.id}`);
  print(`状态: ${detail.status}`);
  print(`自动化: ${detail.definitionName || detail.definitionId}`);
  print(`触发: ${detail.triggerEventType || ''} ${detail.triggerEventId || ''}`.trim());
  print(`耗时: ${detail.executionDuration ?? 0}ms`);
  if (detail.errorMessage) print(`错误: ${detail.errorMessage}`);
  if (detail.triggerEventData !== undefined) {
    print('\ntriggerEventData:');
    print(JSON.stringify(detail.triggerEventData, null, 2));
  }
  if (detail.result !== undefined && detail.result !== null) {
    print('\nresult:');
    print(typeof detail.result === 'string' ? detail.result : JSON.stringify(detail.result, null, 2));
  }
  print('\nlogs:');
  const executionLogs = Array.isArray(detail.nodeExecutionLogs) ? detail.nodeExecutionLogs : [];
  for (const entry of executionLogs) {
    if (entry?.logs && Array.isArray(entry.logs)) {
      print(`# ${entry.nodeLabel || entry.nodeId || entry.nodeType || 'node'} (${entry.success ? 'success' : 'failed'})`);
      for (const log of entry.logs) print(formatAutomationLogLine(log));
    } else {
      print(formatAutomationLogLine(entry));
    }
  }
}

function formatAutomationLogLine(log) {
  if (typeof log === 'string') return log;
  if (!log || typeof log !== 'object') return String(log);
  const prefix = [log.timestamp, log.level, log.stepKey ? `step=${log.stepKey}` : '']
    .filter(Boolean)
    .join(' ');
  const message = log.message || JSON.stringify(log);
  const data = log.data !== undefined ? ` ${JSON.stringify(log.data)}` : '';
  return `${prefix ? `[${prefix}] ` : ''}${message}${data}`;
}

function buildAutomationDiagnosis(detail) {
  const lines = [];
  lines.push(`执行记录: ${detail.id}`);
  lines.push(`状态: ${detail.status}`);
  lines.push(`自动化: ${detail.definitionName || detail.definitionId}`);
  if (detail.errorMessage) lines.push(`错误: ${detail.errorMessage}`);
  lines.push(`耗时: ${detail.executionDuration ?? 0}ms`);
  const importantLogs = flattenAutomationLogs(detail.nodeExecutionLogs).filter(log => {
    if (typeof log === 'string') return /ERROR|WARN|异常|失败|超时/i.test(log);
    const level = String(log?.level || '').toUpperCase();
    return ['ERROR', 'WARN', 'CONSOLE ERROR', 'CONSOLE WARN'].includes(level);
  });
  if (importantLogs.length > 0) {
    lines.push('\n关键日志:');
    for (const log of importantLogs) lines.push(`- ${formatAutomationLogLine(log)}`);
  }
  if (detail.triggerEventData !== undefined) {
    lines.push('\n触发数据:');
    lines.push(JSON.stringify(detail.triggerEventData, null, 2));
  }
  if (detail.result !== undefined && detail.result !== null) {
    lines.push('\n返回结果:');
    lines.push(typeof detail.result === 'string' ? detail.result : JSON.stringify(detail.result, null, 2));
  }
  return lines.join('\n');
}

function flattenAutomationLogs(nodeExecutionLogs) {
  const result = [];
  for (const entry of Array.isArray(nodeExecutionLogs) ? nodeExecutionLogs : []) {
    if (Array.isArray(entry?.logs)) result.push(...entry.logs);
    else result.push(entry);
  }
  return result;
}

function redactLogValue(value) {
  if (typeof value === 'string') {
    return value
      .replace(/(access[_-]?token|refresh[_-]?token|authorization|password|secret|key)(["':= ]+)([^"',\s}]+)/gi, '$1$2***')
      .replace(/1[3-9]\d{9}/g, '1**********')
      .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '***@***');
  }
  if (Array.isArray(value)) return value.map(redactLogValue);
  if (value && typeof value === 'object') {
    const next = {};
    for (const [key, item] of Object.entries(value)) {
      next[key] = /token|authorization|password|secret|credential/i.test(key)
        ? '***'
        : redactLogValue(item);
    }
    return next;
  }
  return value;
}

async function publishResourcesForWorkspace(config, profileName, options = {}) {
  const manifest = loadWorkspaceResources();
  const validation = validateWorkspaceResources(manifest);
  if (validation.errors.length > 0) {
    fail(`资源配置校验失败: ${validation.errors[0]}`);
  }
  const target = getWorkspaceTarget(
    config,
    profileName,
    options.targetName ? { environment: options.targetName } : {}
  );
  const plan = await buildResourcePlan(config, target, manifest);
  if (plan.formFieldContracts?.valid === false) {
    const violations = plan.formFieldContracts.errors || [];
    const error = new Error(
      `FORM_FIELD_CONTRACT_INVALID: ${violations
        .slice(0, 8)
        .map(item => item.message)
        .join('; ')}`
    );
    error.code = 'FORM_FIELD_CONTRACT_INVALID';
    error.violations = violations;
    throw error;
  }
  const pruneCandidates = options.prune
    ? await collectPruneResourceCandidates(config, target, manifest)
    : [];
  if (pruneCandidates.length > 0) {
    plan.actions.push(...pruneCandidatesToPlanActions(pruneCandidates));
    plan.summary = summarizeActions(plan.actions);
  }
  const changeBaselinePreflight = await runResourceChangeBaselinePreflight(
    config,
    target,
    manifest,
    plan.actions,
    options.publishLeaseFlags || {},
    options.publishLease || null
  );
  const result = await publishResourceManifest(config, target, manifest, {
    ...options,
    pruneCandidates,
    planActions: plan.actions,
    skipNoop: options.skipNoop !== false,
  });
  if (changeBaselinePreflight) {
    result.changeBaselinePreflight = changeBaselinePreflight;
  }
  return result;
}

async function buildResourcePlan(
  config,
  target,
  manifest,
  options = {}
) {
  return await withReadOnlyHttpGuard('resource plan', async () => {
  const secretCapabilities = await assertManifestAppFunctionSecretCapabilities(
    config,
    target,
    manifest
  );
  await prepareManifestJsCodeBundlesForPlan(manifest);
  const stagedLocalFormSnapshots =
    await resolveStagedLocalFormContractSnapshots(
      config,
      target,
      options.flags || {},
      (manifest.workflows || [])
        .map(item => item.formCode || item.form)
        .filter(Boolean)
    );
  const [existing, formFieldContracts] = await Promise.all([
    fetchExistingResourceMaps(config, target, manifest),
    buildFormFieldContractPlan(config, target, manifest, {
      stagedLocalFormSnapshots,
    }),
  ]);
  const actions = [];
  addPlanActions(actions, 'role', manifest.roles, existing.roles, roleEquals);
  const orderedMenus = orderMenuResourcesForPublish(
    manifest.menus,
    target.bound,
    existing.menus
  );
  addPlanActions(
    actions,
    'menu',
    orderedMenus,
    existing.menus,
    (item, current) =>
      menuEquals(target.bound, item, current, existing.menus)
  );
  addPlanActions(actions, 'connector', manifest.connectors, existing.connectors, connectorEquals);
  addNotificationPlanActions(target, actions, manifest.notifications || [], existing);
  await addWorkflowPlanActions(config, target, actions, manifest.workflows, existing.workflows);
  addPlanActions(
    actions,
    'function',
    manifest.functions,
    existing.functions,
    (item, current) => functionEquals(target, item, current),
    (item, current) =>
      resourceBindingPlanFields(target, 'Function', item, current)
  );
  addPlanActions(actions, 'authConfig', manifest.authConfigs, existing.authConfigs, (item, current) => authConfigEquals(item, current));
  addPlanActions(actions, 'route', manifest.routes, existing.routes, (item, current) => routeEquals(item, current));
  addPlanActions(actions, 'publicAccessPolicy', manifest.publicAccessPolicies, existing.publicAccessPolicies, (item, current) => publicAccessPolicyEquals(target.bound, item, current));
  await addAutomationPlanActions(config, target, actions, manifest.automations, existing.automations);
  addPlanActions(actions, 'dataView', manifest.dataViews, existing.dataViews, (item, current) => dataViewEquals(target.bound, item, current));
  addPlanActions(actions, 'storageConfig', manifest.storageConfigs, existing.storageConfigs, (item, current) => storageConfigEquals(item, current));
  addPlanActions(actions, 'scopeDimension', manifest.scopeDimensions, existing.scopeDimensions, (item, current) => scopeDimensionEquals(target.bound, item, current));
  addPlanActions(actions, 'scopeGrantSource', manifest.scopeGrantSources, existing.scopeGrantSources, (item, current) => scopeGrantSourceEquals(target.bound, item, current));
  addPlanActions(actions, 'dataScopePolicy', manifest.dataScopePolicies, existing.dataScopePolicies, dataScopePolicyEquals);
  addPlanActions(actions, 'pagePermissionGroup', manifest.pagePermissionGroups, existing.pagePermissionGroups, (item, current) => pagePermissionGroupEquals(target.bound, item, current));
  addPlanActions(actions, 'formPermissionGroup', manifest.formPermissionGroups, existing.formPermissionGroups, (item, current) => formPermissionGroupEquals(target.bound, item, current));
  await addFormSettingPlanActions(
    config,
    target,
    actions,
    manifest.formSettings || []
  );
  const functionSecretRefs = secretCapabilities
    ? await buildAppFunctionSecretRefPlan(
        config,
        target,
        manifest.functions || [],
        existing.functions
      )
    : null;
  return {
    appType: target.appType,
    profile: target.profileName,
    ...(manifest.resourceTypeFilters ? { resourceTypeFilters: manifest.resourceTypeFilters } : {}),
    ...(manifest.resourceCodeFilters ? { resourceCodeFilters: manifest.resourceCodeFilters } : {}),
    actions,
    summary: summarizeActions(actions),
    formFieldContracts,
    ...(functionSecretRefs
      ? {
          capabilities: {
            app_function_secrets_v1: true,
            trusted_node_v2: true,
            backend_release_v2: true,
            atomic_staged_children_v2: true,
          },
          functionSecretRefs,
        }
      : {}),
  };
  });
}

async function buildAppFunctionSecretRefPlan(
  config,
  target,
  functions,
  existingFunctions
) {
  const declaredFunctions = (functions || []).filter(
    functionManifestDeclaresSecretRefs
  );
  if (declaredFunctions.length === 0) return null;
  const metadataResponse = await requestWithAuth(
    config,
    target.profileName,
    appSecretApiPath(target)
  );
  assertSecretMetadataOnly(metadataResponse);
  const metadataByName = new Map(
    normalizeItems(metadataResponse)
      .filter(item => item?.name)
      .map(item => [String(item.name), item])
  );
  const plans = declaredFunctions.map(item => {
    const code = item.code || item.functionCode || item.resourceCode;
    const desired = normalizeFunctionSecretRefs(item.secretRefs);
    const current = normalizeFunctionSecretRefs(
      existingFunctions?.get(code)?.secretRefs ??
        existingFunctions?.get(code)?.secretReferences ??
        []
    );
    const desiredNames = new Set(desired.map(ref => ref.name));
    const currentNames = new Set(current.map(ref => ref.name));
    const added = desired
      .map(ref => ref.name)
      .filter(name => !currentNames.has(name));
    const removed = current
      .map(ref => ref.name)
      .filter(name => !desiredNames.has(name));
    const missingRequired = [];
    const unavailableOptional = [];
    for (const ref of desired) {
      const metadata = metadataByName.get(ref.name);
      let reason = null;
      if (!metadata) reason = 'missing';
      else if (String(metadata.status || 'active') !== 'active') {
        reason = `status:${metadata.status || 'unknown'}`;
      } else if (metadata.hasValue !== true) {
        reason = 'value-not-configured';
      }
      if (!reason) continue;
      (ref.required ? missingRequired : unavailableOptional).push({
        name: ref.name,
        reason,
      });
    }
    const unusedAfterActivation = removed.filter(name => {
      const referenceCount = Number(metadataByName.get(name)?.referenceCount);
      return Number.isFinite(referenceCount) && referenceCount <= 1;
    });
    return {
      code,
      desired,
      current,
      added,
      removed,
      missingRequired,
      unavailableOptional,
      unusedAfterActivation,
    };
  });
  return {
    contractVersion: APP_FUNCTION_SECRET_CAPABILITIES.contractVersion,
    runtimeContractVersion:
      APP_FUNCTION_SECRET_CAPABILITIES.runtimeContractVersion,
    functions: plans,
    valid: plans.every(item => item.missingRequired.length === 0),
  };
}

async function prepareManifestJsCodeBundlesForPlan(manifest) {
  const targetsByWorkspace = new Map();
  const seenObjects = new Set();

  const visit = (value, baseDir) => {
    if (!value || typeof value !== 'object') return;
    if (seenObjects.has(value)) return;
    seenObjects.add(value);
    if (Array.isArray(value)) {
      for (const item of value) visit(item, baseDir);
      return;
    }

    const currentBaseDir = value.__dir || baseDir || manifest.baseDir || process.cwd();
    if (value.sourceFile?.localPath) {
      const rawLocalPath = String(value.sourceFile.localPath);
      const baseResolvedPath = path.resolve(currentBaseDir, rawLocalPath);
      const cwdResolvedPath = path.resolve(process.cwd(), rawLocalPath);
      const resolvedLocalPath = fs.existsSync(baseResolvedPath)
        ? baseResolvedPath
        : cwdResolvedPath;
      const sourceInfo = getJsCodeSourceInfoForPlan(resolvedLocalPath);
      if (sourceInfo) {
        const key = [
          sourceInfo.workspaceRoot,
          sourceInfo.sourceKind,
          sourceInfo.scriptCode,
        ].join('\0');
        if (!jsCodePlanBuildCache.has(key)) {
          if (!targetsByWorkspace.has(sourceInfo.workspaceRoot)) {
            targetsByWorkspace.set(sourceInfo.workspaceRoot, new Map());
          }
          targetsByWorkspace.get(sourceInfo.workspaceRoot).set(key, sourceInfo);
        }
      }
    }

    if (typeof value.definitionFile === 'string') {
      const definitionPath = path.resolve(currentBaseDir, value.definitionFile);
      if (fs.existsSync(definitionPath) && path.extname(definitionPath).toLowerCase() === '.json') {
        try {
          visit(JSON.parse(fs.readFileSync(definitionPath, 'utf8')), path.dirname(definitionPath));
        } catch {
          // Resource validation/normalization reports the actionable JSON error later.
        }
      }
    }

    for (const [key, item] of Object.entries(value)) {
      if (key === 'sourceFile' || key.startsWith('__')) continue;
      visit(item, currentBaseDir);
    }
  };

  for (const spec of RESOURCE_SPECS) {
    const selectors = manifest.__resourceCodeSelectors || null;
    const items = selectors
      ? (manifest[spec.key] || []).filter(item =>
          selectors.some(selector =>
            resourceCodeSelectorMatches(selector, spec.key, item)
          )
        )
      : manifest[spec.key] || [];
    visit(items, manifest.baseDir);
  }

  for (const [workspaceRoot, sourceMap] of targetsByWorkspace.entries()) {
    const sourceInfos = Array.from(sourceMap.values());
    if (sourceInfos.length === 0) continue;
    let result = runWorkspaceJsCodeBuildBatch(
      workspaceRoot,
      sourceInfos.map(item => ({
        sourceKind: item.sourceKind,
        scriptCode: item.scriptCode,
      })),
      { forceCanonical: Boolean(activeDeliveryV2Context) }
    );
    if (result.status !== 0) {
      const legacyFallback = result.openxiangdaBuildMode === 'workspace-script'
        ? await tryBuildFunctionSourcesWithLegacyWorkspaceBuilder(
            workspaceRoot,
            sourceInfos
          )
        : { ok: false, result: null };
      if (legacyFallback.ok) {
        result = { status: 0, stdout: '', stderr: '' };
      } else {
        const failure = legacyFallback.result || result;
        if (failure.stdout) process.stderr.write(failure.stdout);
        if (failure.stderr) process.stderr.write(failure.stderr);
      }
    } else {
      if (result.stdout) process.stderr.write(result.stdout);
      if (result.stderr) process.stderr.write(result.stderr);
    }
    if (result.status !== 0) {
      fail(
        `JS_CODE batch bundle构建失败，无法生成资源计划: ${sourceInfos
          .map(item => `${item.sourceKind}:${item.scriptCode}`)
          .join(', ')}`
      );
    }
    for (const sourceInfo of sourceInfos) {
      if (!fs.existsSync(sourceInfo.bundlePath)) {
        fail(`JS_CODE bundle构建未生成产物，无法生成资源计划: ${sourceInfo.bundlePath}`);
      }
      jsCodePlanBuildCache.add(
        [sourceInfo.workspaceRoot, sourceInfo.sourceKind, sourceInfo.scriptCode].join('\0')
      );
    }
  }
}

async function tryBuildFunctionSourcesWithLegacyWorkspaceBuilder(
  workspaceRoot,
  sourceInfos
) {
  if (
    sourceInfos.length === 0 ||
    sourceInfos.some(item => item.sourceKind !== 'functions')
  ) {
    return { ok: false, result: null };
  }

  let usedLegacyBuilder = false;
  for (const sourceInfo of sourceInfos) {
    const result = runLegacyWorkspaceJsCodeBuild(
      workspaceRoot,
      sourceInfo.scriptCode,
      sourceInfo.sourceKind
    );
    if (result.status === 0) {
      usedLegacyBuilder = true;
      if (result.stdout) process.stderr.write(result.stdout);
      if (result.stderr) process.stderr.write(result.stderr);
      continue;
    }
    if (!isUnsupportedFunctionsBuildScript(result)) {
      return { ok: false, result };
    }
    warn(
      `当前工作区 scripts/build-js-code.mjs 不支持 App Function source=functions，已使用 openxiangda 内置构建器兼容构建 ${sourceInfo.scriptCode}`
    );
    await buildFunctionSourceWithBundledEsbuild(
      sourceInfo.entryPath,
      workspaceRoot,
      sourceInfo.scriptCode
    );
  }
  if (usedLegacyBuilder) {
    warn('当前工作区 build-js-code 不支持批量 --scripts，已兼容使用逐 Function 构建');
  }
  return { ok: true, result: null };
}

function buildResourcePlanActionIndex(actions = []) {
  const index = new Map();
  for (const action of actions || []) {
    if (!action?.kind || !action?.code) continue;
    index.set(`${action.kind}:${action.code}`, action);
  }
  return index;
}

function getPlannedResourceAction(options, kind, code) {
  if (!code) return undefined;
  return options?.planIndex?.get(`${kind}:${code}`);
}

function getResourceUpdatePreconditions(options, kind, code, existing = {}) {
  const action = getPlannedResourceAction(options, kind, code) || {};
  return stripUndefinedValues({
    expectedRevision: action.expectedRevision ?? existing?.revision,
    expectedVersion: action.expectedVersion ?? existing?.version,
    expectedUpdatedAt: action.expectedUpdatedAt ?? existing?.updatedAt,
  });
}

function shouldSkipNoopResource(options, kind, code) {
  if (options?.skipNoop === false) return false;
  const action = getPlannedResourceAction(options, kind, code);
  return action?.action === 'noop';
}

function recordNoopResource(result, kind, code, options) {
  const action = getPlannedResourceAction(options, kind, code);
  result.published.push({
    kind,
    code,
    action: 'noop',
    ...(action?.platformId ? { id: action.platformId } : {}),
  });
}

function collectBackendReleaseCandidates(manifest, options = {}) {
  const candidates = [];
  const append = (kind, resourceKey, items) => {
    const planKind = kind === 'Function' ? 'function' : 'automation';
    for (const item of items || []) {
      const code = item.code || item.functionCode || item.resourceCode;
      const action = getPlannedResourceAction(options, planKind, code);
      if (!action || !['create', 'update', 'noop'].includes(action.action)) continue;
      if (action.action === 'noop' && options.skipNoop !== false) continue;
      const replaceManifest =
        action.action !== 'create' &&
        shouldReplaceResourceManifestItem(item, resourceKey, code, options);
      if (
        action.action === 'update' &&
        action.manifestReplacementRequired === true &&
        !replaceManifest
      ) {
        const reasons = Array.isArray(action.manifestReplacementReasons)
          ? action.manifestReplacementReasons.join(', ')
          : 'resource manifest';
        const differences = Array.isArray(
          action.resourceBindingContract?.differences
        )
          ? `；差异: ${action.resourceBindingContract.differences.join('; ')}`
          : '';
        const error = new Error(
          `RESOURCE_MANIFEST_REPLACEMENT_REQUIRED: ${kind}:${code} 的 ${reasons} 已变化，source_only 会保留线上旧 manifest${differences}。请在精确 --only/--code 范围内使用 --replace-manifest --reason "<至少 8 个字符的原因>"`
        );
        error.code = 'RESOURCE_MANIFEST_REPLACEMENT_REQUIRED';
        error.kind = kind;
        error.resourceCode = code;
        error.requiredMode = 'manifest_replacement';
        error.reasons = action.manifestReplacementReasons || [];
        throw error;
      }
      candidates.push({
        kind,
        code,
        item,
        plannedAction: action.action,
        operation: action.action === 'create' ? 'create' : 'update',
        mode: replaceManifest ? 'manifest_replacement' : 'source_only',
      });
    }
  };
  append('Function', 'functions', manifest.functions);
  append('Automation', 'automations', manifest.automations);
  return candidates;
}

function isBackendReleaseFeatureAbsent(error) {
  const status = Number(error?.status || error?.statusCode || error?.apiCode);
  const code = String(error?.code || '').trim().toUpperCase();
  return (
    (status === 404 || String(error?.message || '').includes('HTTP 404')) &&
    (!code || code === '404' || code === 'NOT_FOUND' || code === 'ROUTE_NOT_FOUND')
  );
}

async function ensureBackendReleasePublishContext(
  config,
  target,
  flags = {},
  label = 'Backend Release'
) {
  return await ensureOwnedImmutableReleasePublishContext(
    config,
    target,
    flags,
    label,
    'Backend Release'
  );
}

async function ensureAppReleasePublishContext(
  config,
  target,
  flags = {},
  label = 'App Release'
) {
  return await ensureOwnedImmutableReleasePublishContext(
    config,
    target,
    flags,
    label,
    'App Release'
  );
}

async function ensureOwnedImmutableReleasePublishContext(
  config,
  target,
  flags = {},
  label = 'Release',
  releaseKind = 'Release'
) {
  const context = await ensureDirectMutationPublishContext(
    config,
    target,
    flags,
    label
  );
  const baseline = getStoredChangeBaseline(target);
  const storedLease = getUsableStoredPublishLease(target);
  if (
    !baseline?.baselineId ||
    !storedLease?.leaseId ||
    context.publishLeaseId !== storedLease.leaseId ||
    context.changeBaselineId !== baseline.baselineId ||
    context.changeId !== baseline.changeId ||
    context.clientSessionId !== baseline.clientSessionId ||
    storedLease.changeId !== baseline.changeId ||
    storedLease.clientSessionId !== baseline.clientSessionId
  ) {
    throw publishContextRequiredError(
      label,
      `${releaseKind} 只接受与本地冻结基线匹配的 stored lease；外部 opaque lease 不能用于原子发布`
    );
  }
  const sourceRevision = normalizeReleaseSourceRevisionForBaseline(
    target,
    baseline.sourceBase || {},
    baseline.releaseSourceRevision || {},
    { errorCode: 'RELEASE_SOURCE_REPOSITORY_MISMATCH' }
  );
  const sourceRepositoryId = String(
    sourceRevision.repositoryId || sourceRevision.repo || ''
  ).trim();
  if (
    !sourceRepositoryId ||
    !String(sourceRevision.baseCommit || '').trim() ||
    !String(sourceRevision.treeHash || '').trim()
  ) {
    throw publishContextRequiredError(
      label,
      'change baseline 缺少 sourceBase.repositoryId/baseCommit/treeHash'
    );
  }

  // An explicit lease remains opaque globally. It is safe to heartbeat here
  // only because the exact same lease is present in the owned local state with
  // trustworthy expiry, change and client-session metadata.
  activatePublishRequestContext(target, storedLease);
  const heartbeat = await activatePublishLeaseHeartbeat(
    config,
    target,
    storedLease,
    flags
  );
  await heartbeat.beforeWrite();
  return {
    baseline,
    publishLease: storedLease,
    sourceRepositoryId,
    sourceRevision,
    control: {
      publishLeaseId: storedLease.leaseId,
      baselineId: baseline.baselineId,
      changeId: baseline.changeId,
      clientSessionId: baseline.clientSessionId,
    },
  };
}

function backendSourcePlane(definition, label) {
  const sourceFile = definition?.sourceFile;
  if (!sourceFile || typeof sourceFile !== 'object') {
    fail(`${label} 缺少 sourceFile，不能进入 source-only Backend Release`);
  }
  return stripUndefinedValues({
    sourceFile: clonePlainJson(sourceFile),
    sourceType: definition.sourceType || 'file_snapshot',
    runtimeMode: definition.runtimeMode,
    sourceProvenance: clonePlainJson(definition.sourceProvenance),
  });
}

function buildAutomationBackendReleaseSources(definition, label) {
  const sources = buildAutomationSourcePatchSources({}, definition).map(
    source =>
      stripUndefinedValues({
        nodeId: source.nodeId,
        sourceFile: clonePlainJson(source.sourceFile),
        sourceType: source.sourceType || 'file_snapshot',
        runtimeMode: source.runtimeMode,
        sourceProvenance: clonePlainJson(source.sourceProvenance),
      })
  );
  if (sources.length === 0) {
    fail(`${label} 不包含可发布的源码快照，不能进入 source-only Backend Release`);
  }
  return sources;
}

function isCompleteDeclarativeAutomationDefinition(definition) {
  if (
    !definition ||
    typeof definition !== 'object' ||
    Array.isArray(definition) ||
    definition.version !== 'v3' ||
    !Array.isArray(definition.nodes) ||
    definition.nodes.length === 0 ||
    !Array.isArray(definition.edges)
  ) {
    return false;
  }
  const nodeIds = new Set();
  let startCount = 0;
  for (const node of definition.nodes) {
    if (
      !node ||
      typeof node !== 'object' ||
      !String(node.id || '').trim() ||
      !String(node.type || '').trim() ||
      !node.data ||
      typeof node.data !== 'object' ||
      Array.isArray(node.data)
    ) {
      return false;
    }
    const nodeId = String(node.id);
    if (nodeIds.has(nodeId)) return false;
    nodeIds.add(nodeId);
    if (node.type === 'start') startCount += 1;
  }
  if (startCount !== 1) return false;
  return definition.edges.every(
    edge =>
      edge &&
      typeof edge === 'object' &&
      String(edge.id || '').trim() &&
      nodeIds.has(String(edge.source || '')) &&
      nodeIds.has(String(edge.target || ''))
  );
}

function resolveAutomationCreateBackendReleaseMode(candidate, definition) {
  if (
    candidate.operation !== 'create' ||
    candidate.mode === 'manifest_replacement'
  ) {
    return candidate.mode;
  }
  if (buildAutomationSourcePatchSources({}, definition).length > 0) {
    return 'source_only';
  }
  if (isCompleteDeclarativeAutomationDefinition(definition)) {
    return 'manifest_replacement';
  }
  fail(
    `Automation:${candidate.code} 新建资源既不包含可发布的源码快照，也不包含完整的 definitionJson.version=v3 声明式定义`
  );
}

async function buildBackendReleaseResourceInput(
  config,
  target,
  candidate,
  uploadCache
) {
  let definitionJson = await resolveManifestJson(
    config,
    target.profileName,
    candidate.item,
    'definitionJson',
    'definitionFile',
    false,
    uploadCache
  );
  applyResourceBindingsToRuntimeDefinition(
    target.bound,
    candidate.item,
    definitionJson
  );
  if (candidate.kind === 'Function') {
    definitionJson = normalizeFunctionDefinitionJson(
      candidate.item,
      definitionJson
    );
    const secretRefsDeclared = functionManifestDeclaresSecretRefs(
      candidate.item
    );
    const common = {
      kind: 'Function',
      code: candidate.code,
      mode: candidate.mode,
      operation: candidate.operation,
      ...(secretRefsDeclared
        ? {
            secretRefs: normalizeFunctionSecretRefs(
              candidate.item.secretRefs
            ),
          }
        : {}),
    };
    if (candidate.mode === 'manifest_replacement') {
      return {
        ...common,
        replacement: buildBackendReleaseFunctionReplacementInput(
          candidate.item,
          definitionJson
        ),
      };
    }
    const source = backendSourcePlane(
      definitionJson,
      `Function:${candidate.code}`
    );
    if (secretRefsDeclared) {
      source.version = definitionJson.version;
      source.runtimeContractVersion = definitionJson.runtimeContractVersion;
    }
    return {
      ...common,
      ...(candidate.operation === 'create'
        ? {
            create: buildBackendReleaseFunctionCreateInput(
              candidate.item,
              definitionJson
            ),
          }
        : {}),
      source,
    };
  }
  const viewJson =
    (await resolveManifestJson(
      config,
      target.profileName,
      candidate.item,
      'viewJson',
      'viewFile',
      true,
      uploadCache
    )) ??
    (await resolveManifestJson(
      config,
      target.profileName,
      candidate.item,
      'previewJson',
      'previewFile',
      true,
      uploadCache
    ));
  const mode = resolveAutomationCreateBackendReleaseMode(
    candidate,
    definitionJson
  );
  candidate.mode = mode;
  const common = {
    kind: 'Automation',
    code: candidate.code,
    mode,
    operation: candidate.operation,
  };
  if (mode === 'manifest_replacement') {
    return {
      ...common,
      ...(candidate.operation === 'create'
        ? {
            create: buildBackendReleaseAutomationMetadata(
              target,
              candidate.item,
              definitionJson,
              viewJson
            ),
          }
        : {
            replacement: buildBackendReleaseAutomationMetadata(
              target,
              candidate.item,
              definitionJson,
              viewJson
            ),
          }),
    };
  }
  return {
    ...common,
    sources: buildAutomationBackendReleaseSources(
      definitionJson,
      `Automation:${candidate.code}`
    ),
    ...(candidate.operation === 'create'
      ? {
          create: buildBackendReleaseAutomationMetadata(
            target,
            candidate.item,
            withoutBackendSourcePlanes(definitionJson),
            viewJson
          ),
        }
      : {}),
  };
}

function buildBackendReleaseFunctionCreateInput(functionItem, definitionJson) {
  const baseDefinition = clonePlainJson(definitionJson || {});
  for (const key of [
    'sourceFile',
    'sourceType',
    'sourceProvenance',
    'secretRefs',
  ]) {
    delete baseDefinition[key];
  }
  const code =
    functionItem.code || functionItem.functionCode || functionItem.resourceCode;
  return stripUndefinedValues({
    name: functionItem.name || definitionJson.name || code,
    description:
      functionItem.description !== undefined
        ? functionItem.description
        : definitionJson.description || '',
    definitionJson: baseDefinition,
    resourceBindings: clonePlainJson(definitionJson.resourceBindings || {}),
    inputSchema: clonePlainJson(
      functionItem.inputSchema || definitionJson.inputSchema
    ),
    outputSchema: clonePlainJson(
      functionItem.outputSchema || definitionJson.outputSchema
    ),
    status: functionItem.status || 'active',
  });
}

function buildBackendReleaseFunctionReplacementInput(
  functionItem,
  definitionJson
) {
  const code =
    functionItem.code || functionItem.functionCode || functionItem.resourceCode;
  return stripUndefinedValues({
    name: functionItem.name || definitionJson.name || code,
    description:
      functionItem.description !== undefined
        ? functionItem.description
        : definitionJson.description || '',
    definitionJson: clonePlainJson(definitionJson),
    resourceBindings: clonePlainJson(definitionJson.resourceBindings || {}),
    inputSchema: clonePlainJson(
      functionItem.inputSchema || definitionJson.inputSchema
    ),
    outputSchema: clonePlainJson(
      functionItem.outputSchema || definitionJson.outputSchema
    ),
    status: functionItem.status || 'active',
  });
}

function buildBackendReleaseAutomationMetadata(
  target,
  automationItem,
  definitionJson,
  viewJson
) {
  const payload = resolveAutomationManifestPayload(target, automationItem);
  const enabled =
    automationItem.enable !== undefined
      ? Boolean(automationItem.enable)
      : automationItem.isEnabled !== undefined
        ? Boolean(automationItem.isEnabled)
        : true;
  return stripUndefinedValues({
    name: automationItem.name || automationItem.code,
    description: automationItem.description || '',
    formUuid: payload.formUuid,
    triggerConfig: clonePlainJson(payload.triggerConfig),
    definitionJson: clonePlainJson(definitionJson),
    ...(viewJson !== undefined ? { viewJson: clonePlainJson(viewJson) } : {}),
    isPublished: Boolean(automationItem.publish || automationItem.isPublished),
    isEnabled: enabled,
    ...(automationItem.tags !== undefined
      ? {
          tags: Array.isArray(automationItem.tags)
            ? automationItem.tags.join(',')
            : automationItem.tags,
        }
      : {}),
  });
}

function withoutBackendSourcePlanes(value) {
  if (Array.isArray(value)) return value.map(withoutBackendSourcePlanes);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(
    Object.entries(value)
      .filter(
        ([key]) =>
          !['sourceFile', 'sourceType', 'sourceProvenance'].includes(key)
      )
      .map(([key, item]) => [key, withoutBackendSourcePlanes(item)])
  );
}

function indexCurrentAutomationStates(items, codes) {
  const codeSet = new Set(codes);
  const groups = new Map();
  for (const item of items || []) {
    const code = String(item?.resourceCode || item?.code || '').trim();
    if (!codeSet.has(code)) continue;
    if (!groups.has(code)) groups.set(code, []);
    groups.get(code).push(item);
  }
  const result = new Map();
  for (const [code, candidates] of groups.entries()) {
    const selected = candidates.slice().sort((left, right) => {
      const leftState = left.isPublished && left.isEnabled
        ? 2
        : left.isPublished
          ? 1
          : 0;
      const rightState = right.isPublished && right.isEnabled
        ? 2
        : right.isPublished
          ? 1
          : 0;
      return (
        rightState - leftState ||
        Number(right.version || 0) - Number(left.version || 0) ||
        new Date(right.updatedAt || 0).getTime() -
          new Date(left.updatedAt || 0).getTime()
      );
    })[0];
    if (selected) result.set(code, selected);
  }
  return result;
}

function backendBindingContractsForCandidates(target, candidates) {
  return normalizeBindingContracts(
    candidates.map(candidate => ({
      ...expectedResourceBindingContract(
        target,
        candidate.kind,
        candidate.item
      ),
      policy:
        candidate.mode === 'manifest_replacement'
          ? 'exact'
          : 'contains_expected',
    }))
  );
}

function resourceDesiredBindings(resource) {
  return normalizeResourceBindings(
    resource?.desired?.resourceBindings ??
      resource?.desired?.resourceBindingsJson ??
      resource?.desired?.definitionJson?.resourceBindings ??
      {}
  );
}

function resourceBindingDiffViolatesPolicy(diff, policy) {
  if (policy === 'exact') return !diff.matches;
  return diff.differences.some(
    item => item.missing.length > 0 || item.changed.length > 0
  );
}

function summarizeBindingPolicyDifferences(diff, policy) {
  if (policy === 'exact') return summarizeBindingDifferences(diff);
  return diff.differences.flatMap(item => {
    const parts = [];
    if (item.missing.length > 0) {
      parts.push(`${item.resourceType}.missing=[${item.missing.join(', ')}]`);
    }
    if (item.changed.length > 0) {
      parts.push(`${item.resourceType}.changed=[${item.changed.join(', ')}]`);
    }
    return parts;
  });
}

function verifyBackendReleaseBindingSnapshot(
  contracts,
  resources,
  phase = 'verified'
) {
  const byKey = new Map(
    (resources || []).map(resource => [
      `${resource.kind}:${resource.code}`,
      resource,
    ])
  );
  const violations = [];
  for (const contract of contracts) {
    const resource = byKey.get(`${contract.kind}:${contract.code}`);
    if (!resource) {
      violations.push({
        kind: contract.kind,
        code: contract.code,
        differences: ['release-resource-missing'],
      });
      continue;
    }
    const diff = diffResourceBindings(
      contract.expected,
      resourceDesiredBindings(resource)
    );
    if (resourceBindingDiffViolatesPolicy(diff, contract.policy)) {
      violations.push({
        kind: contract.kind,
        code: contract.code,
        differences: summarizeBindingPolicyDifferences(
          diff,
          contract.policy
        ),
      });
    }
  }
  if (violations.length > 0) {
    const error = new Error(
      `BACKEND_RELEASE_BINDING_SNAPSHOT_MISMATCH: ${phase} Backend Release 的资源绑定与本地候选不一致: ${violations
        .map(
          item =>
            `${item.kind}:${item.code} ${item.differences.join('; ')}`
        )
        .join(' | ')}`
    );
    error.code = 'BACKEND_RELEASE_BINDING_SNAPSHOT_MISMATCH';
    error.phase = phase;
    error.violations = violations;
    throw error;
  }
  return {
    contractVersion: 'resource_binding_verification_v1',
    phase,
    status: 'passed',
    contractCount: contracts.length,
    contractHash: resourceBindingContractHash(contracts),
  };
}

function hasExpectedResourceBindings(contract) {
  return (
    contract.policy === 'exact' ||
    Object.values(contract.expected || {}).some(
      value => value && Object.keys(value).length > 0
    )
  );
}

async function fetchActivatedBackendBindingDetails(
  config,
  target,
  contracts,
  automationStates = new Map()
) {
  const relevant = contracts.filter(hasExpectedResourceBindings);
  const rows = await runWithConcurrency(
    relevant,
    Math.min(8, relevant.length || 1),
    async contract => {
      const pathValue =
        contract.kind === 'Automation'
          ? automationStates.get(contract.code)?.id
          : contract.code;
      if (!pathValue) {
        return {
          contract,
          detail: null,
        };
      }
      const endpoint =
        contract.kind === 'Automation'
          ? `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(pathValue)}`
          : `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions/${encodeURIComponent(pathValue)}`;
      const detail = await requestOptionalWithAuth(
        config,
        target.profileName,
        endpoint
      );
      return { contract, detail };
    }
  );
  return rows;
}

async function verifyActivatedBackendBindingContracts(
  config,
  target,
  contracts,
  automationStates = new Map()
) {
  const rows = await fetchActivatedBackendBindingDetails(
    config,
    target,
    contracts,
    automationStates
  );
  const violations = [];
  for (const { contract, detail } of rows) {
    if (!detail) {
      violations.push({
        kind: contract.kind,
        code: contract.code,
        differences: ['active-resource-detail-missing'],
      });
      continue;
    }
    const actual = normalizeResourceBindings(
      detail.resourceBindings ??
        detail.resourceBindingsJson ??
        detail.definitionJson?.resourceBindings ??
        {}
    );
    const diff = diffResourceBindings(contract.expected, actual);
    if (resourceBindingDiffViolatesPolicy(diff, contract.policy)) {
      violations.push({
        kind: contract.kind,
        code: contract.code,
        differences: summarizeBindingPolicyDifferences(
          diff,
          contract.policy
        ),
      });
    }
  }
  if (violations.length > 0) {
    const error = new Error(
      `BACKEND_RELEASE_BINDING_VERIFICATION_FAILED: 激活后线上有效资源绑定与候选不一致: ${violations
        .map(
          item =>
            `${item.kind}:${item.code} ${item.differences.join('; ')}`
        )
        .join(' | ')}`
    );
    error.code = 'BACKEND_RELEASE_BINDING_VERIFICATION_FAILED';
    error.violations = violations;
    throw error;
  }
  return {
    contractVersion: 'resource_binding_verification_v1',
    phase: 'active-readback',
    status: 'passed',
    contractCount: contracts.length,
    checkedResourceCount: rows.length,
    contractHash: resourceBindingContractHash(contracts),
  };
}

async function verifyFinalizedBackendBindingContracts(
  config,
  target,
  flags,
  stagedResources
) {
  const stored = readBackendBindingContracts(target, flags);
  if (!stored) return null;
  const stagedBackend = (stagedResources || []).find(
    resource => resource.kind === 'BackendRelease'
  );
  const stagedBackendReleaseId = String(
    stagedBackend?.identity?.releaseId ||
      stagedBackend?.releaseId ||
      ''
  ).trim();
  if (
    !stagedBackendReleaseId ||
    stagedBackendReleaseId !== stored.backendReleaseId
  ) {
    fail(
      `BACKEND_BINDING_CONTRACT_RELEASE_MISMATCH: 本地契约属于 BackendRelease ${stored.backendReleaseId || '-'}，当前 AppRelease 将激活 ${stagedBackendReleaseId || '-'}`
    );
  }
  const automationCodes = stored.contracts
    .filter(
      contract =>
        contract.kind === 'Automation' &&
        hasExpectedResourceBindings(contract)
    )
    .map(contract => contract.code);
  const automationStates =
    await fetchActivatedBackendAutomationStates(
      config,
      target,
      [],
      automationCodes
    );
  const verification =
    await verifyActivatedBackendBindingContracts(
      config,
      target,
      stored.contracts,
      automationStates
    );
  return {
    ...verification,
    backendReleaseId: stored.backendReleaseId,
    contractFile: stored.file,
  };
}

async function fetchActivatedBackendAutomationStates(
  config,
  target,
  resources,
  additionalCodes = []
) {
  const codes = unique([
    ...resources
      .filter(resource => resource.kind === 'Automation' && resource.action === 'update')
      .map(resource => resource.code),
    ...additionalCodes,
  ]);
  if (codes.length === 0) return new Map();
  const data = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations`,
      { page: 1, pageSize: 1000 }
    )
  );
  const states = indexCurrentAutomationStates(normalizeItems(data), codes);
  const missing = codes.filter(code => !states.get(code)?.id);
  if (missing.length > 0) {
    const error = new Error(
      `BACKEND_RELEASE_STATE_SYNC_FAILED: 激活成功后无法解析 Automation 当前版本: ${missing.join(', ')}`
    );
    error.code = 'BACKEND_RELEASE_STATE_SYNC_FAILED';
    throw error;
  }
  return states;
}

async function applyBackendAutomationStateTransitions(
  config,
  target,
  candidates,
  automationStates,
  publishLeaseId,
  options = {}
) {
  const automationCandidates = candidates.filter(
    candidate => candidate.kind === 'Automation'
  );
  const results = await runWithConcurrency(
    automationCandidates,
    Math.min(6, automationCandidates.length),
    async candidate => {
      let current = automationStates.get(candidate.code);
      if (!current?.id) {
        fail(`Backend Release 激活后缺少 Automation:${candidate.code} 当前版本`);
      }
      if (candidate.mode === 'manifest_replacement') {
        return { code: candidate.code, transitions: [] };
      }
      const plan = getPlannedResourceAction(
        options,
        'automation',
        candidate.code
      );
      if (
        plan?.currentIsPublished !== undefined &&
        Boolean(current.isPublished) !== Boolean(plan.currentIsPublished)
      ) {
        const error = new Error(
          `BACKEND_RELEASE_STATE_DIVERGED: Automation:${candidate.code} published 状态未保持冻结值`
        );
        error.code = 'BACKEND_RELEASE_STATE_DIVERGED';
        throw error;
      }
      if (
        plan?.currentIsEnabled !== undefined &&
        Boolean(current.isEnabled) !== Boolean(plan.currentIsEnabled)
      ) {
        const error = new Error(
          `BACKEND_RELEASE_STATE_DIVERGED: Automation:${candidate.code} enabled 状态未保持冻结值`
        );
        error.code = 'BACKEND_RELEASE_STATE_DIVERGED';
        throw error;
      }

      const transitions = [];
      if (candidate.item.publish === true && !current.isPublished) {
        const published = await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(current.id)}/publish`,
          {
            method: 'POST',
            body: stripUndefinedValues({
              expectedVersion: current.version,
              expectedUpdatedAt: current.updatedAt,
              publishLeaseId,
            }),
          }
        );
        current = { ...current, ...(published || {}) };
        transitions.push('publish');
      }
      if (
        candidate.item.enable !== undefined &&
        Boolean(current.isEnabled) !== Boolean(candidate.item.enable)
      ) {
        const enabled = await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(current.id)}/${candidate.item.enable ? 'enable' : 'disable'}`,
          {
            method: 'POST',
            body: stripUndefinedValues({
              expectedVersion: current.version,
              expectedUpdatedAt: current.updatedAt,
              publishLeaseId,
            }),
          }
        );
        current = { ...current, ...(enabled || {}) };
        transitions.push(candidate.item.enable ? 'enable' : 'disable');
      }
      automationStates.set(candidate.code, current);
      return { code: candidate.code, transitions };
    }
  );
  return new Map(results.map(item => [item.code, item.transitions]));
}

function saveBackendReleaseResourceStates(
  target,
  release,
  automationStates,
  stateTransitionCodes = new Set()
) {
  const changed = (release.resources || []).filter(
    resource =>
      resource.action === 'update' || stateTransitionCodes.has(resource.code)
  );
  if (changed.length === 0) return;
  const nextBound = prepareStateResourceWrite(target);
  const now = new Date().toISOString();
  for (const resource of changed) {
    if (resource.kind === 'Function') {
      const previous = nextBound.resources.functions?.[resource.code] || {};
      nextBound.resources.functions[resource.code] = {
        ...previous,
        functionId: resource.desired?.id || resource.resourceId,
        status: resource.desired?.status,
        revision: Number(resource.baseRevision || 0) + 1,
        backendReleaseId: release.id,
        updatedAt: now,
      };
      continue;
    }
    const current = automationStates.get(resource.code);
    const previous = nextBound.resources.automations?.[resource.code] || {};
    nextBound.resources.automations[resource.code] = {
      ...previous,
      automationId: current.id,
      formUuid: current.formUuid || resource.desired?.formUuid,
      groupId: current.groupId || resource.groupId,
      version: current.version,
      backendReleaseId: release.id,
      updatedAt: now,
    };
  }
  saveProjectState(target.state);
  target.bound = nextBound;
}

function backendReleaseResultSummary(
  release,
  stateTransitions = new Map(),
  protocolVersion = null,
  handledSelectors = []
) {
  const resources = release.resources || [];
  const resolvedProtocolVersion =
    release.protocolVersion || protocolVersion || undefined;
  const releaseResource = {
    kind: 'BackendRelease',
    identity: { releaseId: release.id },
    action: 'update',
    hash: release.manifestHash,
    metadata: resolvedProtocolVersion
      ? {
          protocolVersion: resolvedProtocolVersion,
          mode: release.mode,
          parentReleaseId: release.parentReleaseId || null,
          handledSelectors,
        }
      : {
          mode: release.mode,
          parentReleaseId: release.parentReleaseId || null,
          handledSelectors,
        },
  };
  const isStaged = ['prepared', 'verified'].includes(
    String(release.status || '').toLowerCase()
  );
  return {
    id: release.id,
    status: release.status,
    manifestHash: release.manifestHash,
    verificationHash: release.verificationHash,
    parentReleaseId: release.parentReleaseId || null,
    mode: release.mode,
    handledSelectors,
    resourceCount: resources.length,
    updateCount: resources.filter(resource => resource.action === 'update').length,
    noopCount: resources.filter(resource => resource.action === 'noop').length,
    stateTransitionCount: Array.from(stateTransitions.values()).reduce(
      (count, transitions) => count + transitions.length,
      0
    ),
    postCommitStatus: release.postCommitStatus,
    postCommit: release.postCommit,
    ...(resolvedProtocolVersion
      ? { protocolVersion: resolvedProtocolVersion }
      : {}),
    ...(isStaged
      ? { stagedResource: releaseResource }
      : { activeResource: releaseResource }),
  };
}

async function publishBackendReleaseResources(
  config,
  target,
  manifest,
  result,
  options = {}
) {
  const candidates = collectBackendReleaseCandidates(manifest, options);
  if (candidates.length === 0) {
    if (options.stageBackendReleaseOnly) {
      fail('--stage-only 没有匹配到可冻结的 Function/Automation 资源');
    }
    return;
  }
  const bindingContracts = backendBindingContractsForCandidates(
    target,
    candidates
  );
  const protocolVersion = APP_FUNCTION_SECRET_CAPABILITIES.backendRelease;
  const handledSelectors = candidates
    .map(candidate =>
      `${candidate.kind === 'Function' ? 'function' : 'automation'}:${candidate.code}`
    )
    .sort();
  const replacementReason = String(
    options.publishLeaseFlags?.reason ||
      options.publishLeaseFlags?.['replace-reason'] ||
      ''
  ).trim();

  let head;
  try {
    head = await requestWithAuth(
      config,
      target.profileName,
      backendReleaseApiPath(target, '/head')
    );
  } catch (error) {
    if (isBackendReleaseFeatureAbsent(error)) {
      const secretRefsRequired = candidates.some(
        candidate =>
          candidate.kind === 'Function' &&
          functionManifestDeclaresSecretRefs(candidate.item)
      );
      if (!options.stageBackendReleaseOnly && !secretRefsRequired) {
        const message =
          '当前平台未提供 Backend Release API（head=404）；非 stage-only 发布兼容降级为逐项写入。升级平台后会自动使用 Backend Release v2。';
        result.warnings.push(message);
        warn(message);
        return;
      }
      const missing = new Error(
        'BACKEND_RELEASE_V2_REQUIRED: 本次 Function/Automation 发布包含 v2 operation/mode，平台必须支持 Backend Release v2，禁止降级为逐项写入'
      );
      missing.code = 'BACKEND_RELEASE_V2_REQUIRED';
      throw missing;
    }
    throw error;
  }

  const releaseContext = await ensureBackendReleasePublishContext(
    config,
    target,
    options.publishLeaseFlags || {},
    'Function + Automation 原子发布'
  );
  options.publishLease = releaseContext.publishLease;
  options.publishLeaseId = releaseContext.publishLease.leaseId;

  const uploadCache = new Map();
  const resources = await runWithConcurrency(
    candidates,
    Math.min(6, candidates.length),
    candidate =>
      buildBackendReleaseResourceInput(
        config,
        target,
        candidate,
        uploadCache
      )
  );
  const resourceModes = unique(resources.map(resource => resource.mode));
  const releaseMode =
    resourceModes.length > 1 ? 'mixed' : resourceModes[0] || 'source_only';
  const requiresReplacementReason = resources.some(
    resource =>
      resource.mode === 'manifest_replacement' &&
      resource.operation === 'update'
  );
  const prepared = await requestWithAuth(
    config,
    target.profileName,
    backendReleaseApiPath(target),
    {
      method: 'POST',
      body: {
        ...releaseContext.control,
        ...(protocolVersion ? { protocolVersion } : {}),
        parentReleaseId: head?.activeBackendReleaseId || null,
        mode: releaseMode,
        ...(requiresReplacementReason
          ? { replacementReason }
          : {}),
        sourceRepositoryId: releaseContext.sourceRepositoryId,
        sourceRevision: releaseContext.sourceRevision,
        resources,
      },
    }
  );
  if (!prepared?.id || !prepared?.manifestHash) {
    fail('Backend Release prepare 响应缺少 id 或 manifestHash');
  }
  const expectedKeys = candidates
    .map(candidate => `${candidate.kind}:${candidate.code}`)
    .sort();
  const preparedKeys = (prepared.resources || [])
    .map(resource => `${resource.kind}:${resource.code}`)
    .sort();
  if (JSON.stringify(expectedKeys) !== JSON.stringify(preparedKeys)) {
    fail('Backend Release prepare 返回的资源集合与冻结发布范围不一致');
  }
  const verified = await requestWithAuth(
    config,
    target.profileName,
    backendReleaseApiPath(
      target,
      `/${encodeURIComponent(prepared.id)}/verify`
    ),
    {
      method: 'POST',
      body: {
        ...releaseContext.control,
        ...(protocolVersion ? { protocolVersion } : {}),
        manifestHash: prepared.manifestHash,
      },
    }
  );
  const verifiedRelease = {
    ...prepared,
    ...verified,
    resources:
      Array.isArray(verified.resources) && verified.resources.length > 0
        ? verified.resources
        : prepared.resources || [],
  };
  if (String(verifiedRelease.status || '').toLowerCase() !== 'verified') {
    fail('Backend Release verify 未获得 verified 状态，拒绝激活');
  }
  const verifiedBindingSnapshot =
    verifyBackendReleaseBindingSnapshot(
      bindingContracts,
      verifiedRelease.resources,
      'verified'
    );
  if (options.stageBackendReleaseOnly) {
    const stagedRelease = verifiedRelease;
    const bindingVerification = verifiedBindingSnapshot;
    const bindingContractRecord = writeBackendBindingContracts(
      target,
      releaseContext.control.changeId,
      stagedRelease.id,
      bindingContracts
    );
    const handledKeys = new Set(
      candidates.map(candidate => `${candidate.kind}:${candidate.code}`)
    );
    options.backendReleaseSourceHandledKeys = handledKeys;
    options.backendReleaseHandledKeys = handledKeys;
    for (const resource of stagedRelease.resources) {
      result.published.push({
        kind: resource.kind === 'Function' ? 'function' : 'automation',
        code: resource.code,
        action: resource.action === 'noop' ? 'noop' : 'stage',
        writeMode: 'backend-release-stage',
        backendReleaseId: stagedRelease.id,
        activation: 'staged',
        id:
          resource.kind === 'Function'
            ? resource.desired?.id || resource.resourceId
            : resource.desired?.id || resource.resourceId,
      });
    }
    result.backendRelease = backendReleaseResultSummary(
      stagedRelease,
      new Map(),
      protocolVersion,
      handledSelectors
    );
    result.backendRelease.bindingVerification = bindingVerification;
    result.backendRelease.bindingContractRecord = {
      file: bindingContractRecord.file,
      contractHash: bindingContractRecord.contractHash,
      contractCount: bindingContractRecord.contracts.length,
    };
    if (!result.backendRelease.stagedResource) {
      fail('Backend Release stage-only 响应缺少 verified stagedResource');
    }
    result.stagedResources = result.stagedResources || [];
    result.stagedResources.push(result.backendRelease.stagedResource);
    if (result.stagedResources.length === 1) {
      result.stagedResource = result.backendRelease.stagedResource;
    } else {
      delete result.stagedResource;
    }
    result.handledSelectors = unique([
      ...(result.handledSelectors || []),
      ...handledSelectors,
    ]).sort();
    return;
  }
  const activated = await requestWithAuth(
    config,
    target.profileName,
    backendReleaseApiPath(
      target,
      `/${encodeURIComponent(verifiedRelease.id || prepared.id)}/activate`
    ),
    {
      method: 'POST',
      body: {
        ...releaseContext.control,
        ...(protocolVersion ? { protocolVersion } : {}),
      },
    }
  );
  options.backendReleaseSourceHandledKeys = new Set(
    candidates.map(candidate => `${candidate.kind}:${candidate.code}`)
  );
  const automationCodes = candidates
    .filter(candidate => candidate.kind === 'Automation')
    .map(candidate => candidate.code);
  const automationStates = await fetchActivatedBackendAutomationStates(
    config,
    target,
    activated.resources || [],
    automationCodes
  );
  const stateTransitions = await applyBackendAutomationStateTransitions(
    config,
    target,
    candidates,
    automationStates,
    releaseContext.publishLease.leaseId,
    options
  );
  const bindingVerification =
    await verifyActivatedBackendBindingContracts(
      config,
      target,
      bindingContracts,
      automationStates
    );
  const stateTransitionCodes = new Set(
    Array.from(stateTransitions.entries())
      .filter(([, transitions]) => transitions.length > 0)
      .map(([code]) => code)
  );
  saveBackendReleaseResourceStates(
    target,
    activated,
    automationStates,
    stateTransitionCodes
  );

  options.backendReleaseHandledKeys = new Set(
    candidates.map(candidate => `${candidate.kind}:${candidate.code}`)
  );
  for (const resource of activated.resources || []) {
    const currentAutomation = automationStates.get(resource.code);
    result.published.push({
      kind: resource.kind === 'Function' ? 'function' : 'automation',
      code: resource.code,
      action:
        resource.action === 'update' ||
        (stateTransitions.get(resource.code) || []).length > 0
          ? 'update'
          : 'noop',
      writeMode: 'source-patch',
      sourcePatchTransport: 'backend-release',
      backendReleaseId: activated.id,
      id:
        resource.kind === 'Function'
          ? resource.desired?.id || resource.resourceId
          : currentAutomation?.id || resource.resourceId,
      ...(currentAutomation?.version !== undefined
        ? { version: currentAutomation.version }
        : {}),
      ...((stateTransitions.get(resource.code) || []).length > 0
        ? { stateTransitions: stateTransitions.get(resource.code) }
        : {}),
    });
  }
  result.backendRelease = backendReleaseResultSummary(
    activated,
    stateTransitions,
    protocolVersion,
    handledSelectors
  );
  result.backendRelease.bindingVerification = bindingVerification;
  result.handledSelectors = handledSelectors;
}

async function publishWorkflowReleaseResources(
  config,
  target,
  manifest,
  result,
  options = {}
) {
  if (!options.stageWorkflowReleaseOnly) return;
  const candidates = (manifest.workflows || [])
    .map(item => {
      const code = item.code || item.resourceCode;
      const action = getPlannedResourceAction(options, 'workflow', code);
      return { item, code, action };
    })
    .filter(
      candidate =>
        candidate.action &&
        ['create', 'update', 'noop'].includes(candidate.action.action) &&
        !(candidate.action.action === 'noop' && options.skipNoop !== false)
    );
  if (candidates.length === 0) {
    fail('--stage-only 没有匹配到可冻结的 Workflow 资源');
  }
  const head = await requestWithAuth(
    config,
    target.profileName,
    workflowReleaseApiPath(target, '/head')
  );
  const releaseContext = await ensureOwnedImmutableReleasePublishContext(
    config,
    target,
    options.publishLeaseFlags || {},
    'Workflow 原子发布',
    'Workflow Release'
  );
  options.publishLease = releaseContext.publishLease;
  options.publishLeaseId = releaseContext.publishLease.leaseId;
  const resources = await runWithConcurrency(
    candidates,
    Math.min(6, candidates.length),
    async candidate => {
      const compiled = await compileWorkflowSourceFile(candidate.item);
      const definitionJson =
        compiled?.definitionJson ||
        (await resolveManifestJson(
          config,
          target.profileName,
          candidate.item,
          'definitionJson',
          'definitionFile'
        ));
      const viewJson =
        compiled?.previewJson ??
        (await resolveManifestJson(
          config,
          target.profileName,
          candidate.item,
          'viewJson',
          'viewFile',
          true
        )) ??
        (await resolveManifestJson(
          config,
          target.profileName,
          candidate.item,
          'previewJson',
          'previewFile',
          true
        ));
      return {
        code: candidate.code,
        operation:
          candidate.action.action === 'create' ? 'create' : 'update',
        formUuid: resolveManifestFormUuid(target.bound, candidate.item),
        definitionJson,
        ...(viewJson !== undefined ? { viewJson } : {}),
        publish: candidate.item.publish !== false,
      };
    }
  );
  const prepared = await requestWithAuth(
    config,
    target.profileName,
    workflowReleaseApiPath(target),
    {
      method: 'POST',
      body: {
        ...releaseContext.control,
        sourceRepositoryId: releaseContext.sourceRepositoryId,
        sourceRevision: releaseContext.sourceRevision,
        parentReleaseId: head?.activeWorkflowReleaseId || null,
        resources,
      },
    }
  );
  if (!prepared?.id || !/^[a-f0-9]{64}$/i.test(prepared?.manifestHash || '')) {
    fail('Workflow Release prepare 响应缺少 id 或 manifestHash');
  }
  const preparedCodes = (prepared.resources || [])
    .map(resource => String(resource.code || ''))
    .sort();
  const expectedCodes = candidates.map(candidate => candidate.code).sort();
  if (!exactStringSet(preparedCodes, expectedCodes)) {
    fail('Workflow Release prepare 返回的资源集合与精确 selector 不一致');
  }
  const verified = await requestWithAuth(
    config,
    target.profileName,
    workflowReleaseApiPath(
      target,
      `/${encodeURIComponent(prepared.id)}/verify`
    ),
    {
      method: 'POST',
      body: {
        ...releaseContext.control,
        manifestHash: prepared.manifestHash,
      },
    }
  );
  if (String(verified?.status || '').toLowerCase() !== 'verified') {
    fail('Workflow Release stage-only 未获得 verified 状态');
  }
  const handledSelectors = candidates
    .map(candidate => `workflow:${candidate.code}`)
    .sort();
  const stagedResource = {
    kind: 'WorkflowRelease',
    identity: { releaseId: verified.id || prepared.id },
    action: 'update',
    hash: verified.manifestHash || prepared.manifestHash,
    revision: {
      releaseId: verified.id || prepared.id,
      manifestHash: verified.manifestHash || prepared.manifestHash,
      sourceRevision: verified.sourceRevision || prepared.sourceRevision,
    },
    metadata: {
      contractVersion: 'workflow_release_v1',
      handledSelectors,
      resourceCount: candidates.length,
    },
  };
  result.stagedResources = result.stagedResources || [];
  result.stagedResources.push(stagedResource);
  result.workflowRelease = {
    id: verified.id || prepared.id,
    manifestHash: verified.manifestHash || prepared.manifestHash,
    status: verified.status,
    handledSelectors,
    stagedResource,
  };
  result.handledSelectors = unique([
    ...(result.handledSelectors || []),
    ...handledSelectors,
  ]).sort();
  options.workflowReleaseHandledKeys = new Set(
    candidates.map(candidate => `Workflow:${candidate.code}`)
  );
  for (const candidate of candidates) {
    result.published.push({
      kind: 'workflow',
      code: candidate.code,
      action: 'stage',
      writeMode: 'workflow-release-stage',
      workflowReleaseId: stagedResource.identity.releaseId,
      activation: 'staged',
    });
  }
}

async function publishResourceManifest(config, target, manifest, options = {}) {
  const result = {
    appType: target.appType,
    profile: target.profileName,
    ...(manifest.resourceTypeFilters ? { resourceTypeFilters: manifest.resourceTypeFilters } : {}),
    ...(manifest.resourceCodeFilters ? { resourceCodeFilters: manifest.resourceCodeFilters } : {}),
    published: [],
    pruned: [],
    warnings: [],
  };
  const publishOptions = {
    ...options,
    planIndex: buildResourcePlanActionIndex(options.planActions || []),
  };
  if (isManifestEmpty(manifest)) {
    if (!options.quiet) result.warnings.push('未发现 src/resources 资源配置');
    if (!options.prune) return result;
  }

  await publishRoleResources(config, target, manifest.roles || [], result, publishOptions);
  await publishFormSettingsResources(
    config,
    target,
    manifest.formSettings || [],
    manifest.formPermissionGroups || [],
    result,
    publishOptions
  );
  await publishMenuResources(config, target, manifest.menus || [], result, publishOptions);
  await publishConnectorResources(config, target, manifest.connectors || [], result, publishOptions);
  await publishNotificationResources(config, target, manifest.notifications || [], result, publishOptions);
  await publishWorkflowReleaseResources(
    config,
    target,
    manifest,
    result,
    publishOptions
  );
  await publishWorkflowResources(config, target, manifest.workflows || [], result, publishOptions);
  await publishBackendReleaseResources(
    config,
    target,
    manifest,
    result,
    publishOptions
  );
  await publishFunctionResources(config, target, manifest.functions || [], result, publishOptions);
  await publishAuthConfigResources(config, target, manifest.authConfigs || [], result, publishOptions);
  await publishRouteResources(config, target, manifest.routes || [], result, publishOptions);
  await publishAutomationResources(config, target, manifest.automations || [], result, publishOptions);
  await publishScopeDimensionResources(config, target, manifest.scopeDimensions || [], result, publishOptions);
  await publishScopeGrantSourceResources(config, target, manifest.scopeGrantSources || [], result, publishOptions);
  await publishDataScopePolicyResources(config, target, manifest.dataScopePolicies || [], result, publishOptions);
  await publishDataViewResources(config, target, manifest.dataViews || [], result, publishOptions);
  await publishStorageConfigResources(config, target, manifest.storageConfigs || [], result, publishOptions);
  await publishPublicAccessPolicyResources(config, target, manifest.publicAccessPolicies || [], result, publishOptions);
  await publishPagePermissionGroupResources(config, target, manifest.pagePermissionGroups || [], result, publishOptions);
  await publishFormPermissionGroupResources(
    config,
    target,
    manifest.formPermissionGroups || [],
    result,
    publishOptions
  );
  if (options.prune) {
    await pruneResourceManifest(
      config,
      target,
      manifest,
      result,
      options.pruneCandidates
    );
  }
  return result;
}

async function refreshResourcePublishLease(config, target, options) {
  if (!options?.publishLease) return options?.publishLeaseId;
  // A caller-supplied lease id is opaque to this process; without its expiry
  // metadata we must use it as-is instead of attempting an unsolicited renew.
  if (options.publishLease.explicit) return options.publishLeaseId;
  if (shouldRenewPublishLease(options.publishLease)) {
    options.publishLease = await renewPublishLeaseFailClosed(
      config,
      target,
      options.publishLease,
      options.publishLeaseFlags || {}
    );
    options.publishLeaseId = options.publishLease.leaseId;
  }
  return options.publishLeaseId;
}

function resourceBaselineTargetKey(kind, code) {
  return `${kind}:${code}`;
}

function inferManifestSourceKind(item, kind) {
  const candidates = [];
  const seen = new Set();
  const visit = (value, baseDir) => {
    if (!value || typeof value !== 'object' || seen.has(value)) return;
    seen.add(value);
    if (Array.isArray(value)) {
      value.forEach(child => visit(child, baseDir));
      return;
    }
    const currentBase = value.__dir || baseDir || process.cwd();
    if (value.sourceFile?.localPath) {
      candidates.push(String(value.sourceFile.localPath).replace(/\\/g, '/'));
    }
    if (typeof value.definitionFile === 'string') {
      const file = path.resolve(currentBase, value.definitionFile);
      try {
        visit(JSON.parse(fs.readFileSync(file, 'utf8')), path.dirname(file));
      } catch {
        // Resource validation reports malformed/missing definition files.
      }
    }
    Object.entries(value).forEach(([key, child]) => {
      if (!key.startsWith('__') && key !== 'sourceFile') visit(child, currentBase);
    });
  };
  visit(item, item?.__dir || process.cwd());
  if (candidates.some(value => value.includes('/js-code-nodes/'))) return 'js-code-nodes';
  if (candidates.some(value => value.includes('/automations/'))) return 'automations';
  if (candidates.some(value => value.includes('/functions/'))) return 'functions';
  if (kind === 'Function') return 'functions';
  if (kind === 'Workflow') return 'workflows';
  return 'automations';
}

function buildResourceChangeBaselineTargets(manifest, actions = [], options = {}) {
  const actionIndex = buildResourcePlanActionIndex(actions);
  const targets = [];
  const seen = new Set();
  const append = (kind, items) => {
    for (const item of items || []) {
      const code = item.code || item.functionCode || item.resourceCode;
      if (!code) continue;
      const planKind =
        kind === 'Function'
          ? 'function'
          : kind === 'Workflow'
            ? 'workflow'
            : 'automation';
      const action = actionIndex.get(`${planKind}:${code}`);
      if (action?.action === 'create') continue;
      if (action?.action === 'noop' && !options.force) continue;
      const key = resourceBaselineTargetKey(kind, code);
      if (seen.has(key)) continue;
      seen.add(key);
      targets.push({
        kind,
        code,
        sourceKind: inferManifestSourceKind(item, kind),
      });
    }
  };
  append('Function', manifest.functions);
  append('Automation', manifest.automations);
  append('Workflow', manifest.workflows);
  for (const action of actions || []) {
    if (action?.action !== 'delete' || !action.code) continue;
    const kind =
      action.kind === 'function'
        ? 'Function'
        : action.kind === 'automation'
          ? 'Automation'
          : action.kind === 'workflow'
            ? 'Workflow'
          : null;
    if (!kind) continue;
    const key = resourceBaselineTargetKey(kind, action.code);
    if (seen.has(key)) continue;
    seen.add(key);
    targets.push({
      kind,
      code: action.code,
      sourceKind:
        kind === 'Function'
          ? 'functions'
          : kind === 'Workflow'
            ? 'workflows'
            : 'automations',
    });
  }
  return targets;
}

const GENERIC_RESOURCE_KEY_BY_PLAN_KIND = Object.freeze({
  role: 'roles',
  menu: 'menus',
  connector: 'connectors',
  notificationTemplate: 'notifications',
  notificationTypeConfig: 'notifications',
  authConfig: 'authConfigs',
  route: 'routes',
  publicAccessPolicy: 'publicAccessPolicies',
  dataView: 'dataViews',
  storageConfig: 'storageConfigs',
  scopeDimension: 'scopeDimensions',
  scopeGrantSource: 'scopeGrantSources',
  dataScopePolicy: 'dataScopePolicies',
  pagePermissionGroup: 'pagePermissionGroups',
  formPermissionGroup: 'formPermissionGroups',
  formSetting: 'formSettings',
});

function buildGenericResourceGitBaseTargets(planActions = [], options = {}) {
  const targets = [];
  const seen = new Set();
  for (const action of planActions || []) {
    const resourceKey = GENERIC_RESOURCE_KEY_BY_PLAN_KIND[action?.kind];
    const code = String(action?.code || '').trim();
    if (!resourceKey || !code) continue;
    if (action.action === 'noop' && !options.force) continue;
    if (!['create', 'update', 'delete', 'noop'].includes(action.action)) continue;
    const key = `${action.kind}:${code}`;
    if (seen.has(key)) continue;
    seen.add(key);
    targets.push({
      kind: action.kind,
      code,
      resourceKey,
      action: action.action === 'noop' ? 'update' : action.action,
      plannedAction: action.action,
    });
  }
  return targets.sort((left, right) =>
    `${left.resourceKey}\0${left.code}`.localeCompare(
      `${right.resourceKey}\0${right.code}`
    )
  );
}

function runGenericResourceGitBasePreflight({
  target,
  manifest,
  baseline,
  publishLease,
  targets,
  onlineBaselineAdoption = null,
}) {
  if (!targets.length) return null;
  const publishLeaseId = String(
    publishLease?.leaseId ||
      activePublishRequestContext?.publishLeaseId ||
      ''
  ).trim();
  if (!publishLeaseId) {
    throwSourceBaseDiverged(
      '通用资源发布缺少应用级 publish lease，不能验证 Git 基线',
      targets
    );
  }
  const baseCommit = String(baseline?.sourceBase?.baseCommit || '').trim();
  const headDigest = String(baseline?.headDigest || '').trim();
  if (!baseCommit || !headDigest) {
    throwSourceBaseDiverged(
      'change baseline 缺少 sourceBase.baseCommit 或 headDigest',
      targets
    );
  }

  const selectors = unique(
    targets.map(item => `${item.resourceKey}:${item.code}`)
  ).sort();
  if (onlineBaselineAdoption) {
    return {
      ok: true,
      baselineId: baseline.baselineId,
      publishLeaseId,
      headDigest,
      baseCommit,
      checkedTargets: targets.map(({ kind, code, action }) => ({
        kind,
        code,
        action,
      })),
      selectors,
      planRuns: 0,
      cached: false,
      readOnly: true,
      gitBasePlanSkipped: true,
      onlineBaselineAdoption,
    };
  }
  const typeFilters = unique(manifest.resourceTypeFilters || []).sort();
  const cacheKey = canonicalJsonSha256({
    publishLeaseId,
    headDigest,
    baseCommit,
    appType: target.appType,
    profile: target.profileName,
    repository: baseline?.sourceBase?.repo,
    resourceHeads: baseline?.resourceHeads,
    selectors,
    typeFilters,
  });
  let basePlan =
    genericGitBasePlanCache.get(cacheKey) ||
    readContentCache({
      cwd: process.cwd(),
      namespace: 'generic-git-base-plan',
      key: cacheKey,
    });
  let cached = Boolean(basePlan);
  if (!basePlan) {
    basePlan = withGitBaseWorkspace(
      {
        cwd: process.cwd(),
        baseCommit,
        env: process.env,
        copyProjectState: true,
      },
      ({ buildRoot, buildEnv, tempRoot }) => {
        const isolatedHome = prepareReadonlyGitBasePlanHome(tempRoot);
        const childEnv = {
          ...buildEnv,
          HOME: isolatedHome,
          USERPROFILE: isolatedHome,
          OPENXIANGDA_GIT_BASE_RESOURCE_PLAN: '1',
        };
        for (const name of [
          'OPENXIANGDA_PUBLISH_LEASE_ID',
          'OPENXIANGDA_CHANGE_BASELINE_ID',
          'OPENXIANGDA_CHANGE_ID',
          'OPENXIANGDA_CLIENT_SESSION_ID',
        ]) {
          delete childEnv[name];
        }
        const childArgs = [
          path.resolve(__dirname, '..', 'bin', 'openxiangda.js'),
          'resource',
          'plan',
          '--only',
          selectors.join(','),
          '--profile',
          target.profileName,
          '--app-type',
          target.appType,
          '--json',
        ];
        if (typeFilters.length > 0) {
          childArgs.push('--type', typeFilters.join(','));
        }
        const child = spawnSync(process.execPath, childArgs, {
          cwd: buildRoot,
          env: childEnv,
          encoding: 'utf8',
          maxBuffer: 32 * 1024 * 1024,
          timeout: 60_000,
          killSignal: 'SIGKILL',
        });
        if (child.error || child.status !== 0) {
          const detail = [child.error?.message, child.stderr, child.stdout]
            .filter(Boolean)
            .join('\n')
            .trim()
            .slice(-6000);
          const error = new Error(
            `SOURCE_BASE_PLAN_FAILED: Git 基线 resource plan 执行失败${detail ? `\n${detail}` : ''}`
          );
          error.code = 'SOURCE_BASE_PLAN_FAILED';
          throw error;
        }
        try {
          return JSON.parse(String(child.stdout || ''));
        } catch (parseError) {
          const error = new Error(
            `SOURCE_BASE_PLAN_FAILED: Git 基线 resource plan --json 输出不可解析: ${parseError.message}`
          );
          error.code = 'SOURCE_BASE_PLAN_FAILED';
          throw error;
        }
      }
    );
    genericGitBasePlanCache.set(cacheKey, basePlan);
    writeContentCache({
      cwd: process.cwd(),
      namespace: 'generic-git-base-plan',
      key: cacheKey,
      value: {
        actions: (basePlan.actions || [])
          .filter(action => action?.kind && action?.code && action?.action)
          .map(action => ({
            kind: action.kind,
            code: action.code,
            action: action.action,
          })),
      },
    });
    while (genericGitBasePlanCache.size > 32) {
      genericGitBasePlanCache.delete(genericGitBasePlanCache.keys().next().value);
    }
  }

  const baseIndex = buildResourcePlanActionIndex(basePlan.actions || []);
  const conflicts = [];
  for (const targetItem of targets) {
    const baseAction = baseIndex.get(
      `${targetItem.kind}:${targetItem.code}`
    );
    if (targetItem.action === 'create') {
      if (baseAction) {
        conflicts.push({
          kind: targetItem.kind,
          code: targetItem.code,
          currentAction: targetItem.action,
          baseAction: baseAction.action,
          reason: 'target-existed-in-git-base',
        });
      }
      continue;
    }
    if (!baseAction || baseAction.action !== 'noop') {
      conflicts.push({
        kind: targetItem.kind,
        code: targetItem.code,
        currentAction: targetItem.action,
        baseAction: baseAction?.action || 'missing',
        reason: baseAction
          ? 'remote-diverged-from-git-base'
          : 'target-missing-from-git-base',
      });
    }
  }
  if (conflicts.length > 0) {
    throwSourceBaseDiverged(
      '线上通用资源已不再匹配冻结 Git 基线，请先拉取/合并并重新开始 release',
      conflicts
    );
  }

  return {
    ok: true,
    baselineId: baseline.baselineId,
    publishLeaseId,
    headDigest,
    baseCommit,
    checkedTargets: targets.map(({ kind, code, action }) => ({
      kind,
      code,
      action,
    })),
    selectors,
    planRuns: cached ? 0 : 1,
    cached,
    readOnly: true,
  };
}

function prepareReadonlyGitBasePlanHome(tempRoot) {
  if (!fs.existsSync(CONFIG_FILE)) {
    const error = new Error(
      'SOURCE_BASE_PLAN_FAILED: 当前 profile 配置不存在，无法执行隔离 Git 基线 plan'
    );
    error.code = 'SOURCE_BASE_PLAN_FAILED';
    throw error;
  }
  const home = path.join(tempRoot, 'plan-home');
  const configDir = path.join(home, '.openxiangda');
  const configFile = path.join(configDir, 'profiles.json');
  fs.mkdirSync(configDir, { recursive: true, mode: 0o700 });
  fs.copyFileSync(CONFIG_FILE, configFile);
  try {
    fs.chmodSync(configFile, 0o400);
  } catch {
    // Best-effort on non-POSIX filesystems. The entire isolated home is inside
    // the disposable Git-base directory and never points at the real profile.
  }
  return home;
}

function throwSourceBaseDiverged(message, conflicts = []) {
  const summary = (conflicts || [])
    .slice(0, 12)
    .map(item =>
      item?.kind && item?.code
        ? `${item.kind}:${item.code}(${item.baseAction || item.action || 'conflict'})`
        : String(item)
    )
    .join(', ');
  const error = new Error(
    `SOURCE_BASE_DIVERGED: ${message}${summary ? `: ${summary}` : ''}`
  );
  error.code = 'SOURCE_BASE_DIVERGED';
  error.conflicts = conflicts;
  throw error;
}

async function runResourceChangeBaselinePreflight(
  config,
  target,
  manifest,
  planActions,
  flags = {},
  publishLease = null
) {
  if (activeDeliveryV2Context) {
    return {
      ok: true,
      baselineId: activeDeliveryV2Context.baselineId,
      checkedTargets: [],
      skipped: 'trusted-delivery-v2-package',
    };
  }
  const onlineBaselineAdoption = resolveOnlineBaselineAdoption(
    flags,
    planActions,
    publishLease
  );
  const genericTargets = buildGenericResourceGitBaseTargets(planActions, {
    force: Boolean(flags.force),
  });
  const baseline = getStoredChangeBaseline(target);
  if (!baseline?.baselineId) {
    return null;
  }
  if (!isChangeBaselineOwnedByCurrentSession(baseline)) {
    fail('当前任务不是该变更基线的持有者，禁止发布');
  }
  const targets = buildResourceChangeBaselineTargets(manifest, planActions, {
    force: Boolean(flags.force),
  });
  let serverPreflight;
  if (targets.length === 0) {
    serverPreflight = {
      ok: true,
      baselineId: baseline.baselineId,
      checkedTargets: [],
      skipped: 'no-existing-function-automation-or-workflow-writes',
    };
  } else {
    const artifactCache = { ...(baseline.localBaseArtifactHashes || {}) };
    const missingArtifactTargets = onlineBaselineAdoption
      ? []
      : targets.filter(targetItem => {
          const frozen =
            baseline.resourceHeads?.[targetItem.kind]?.[targetItem.code];
          const cached = artifactCache[
            resourceBaselineTargetKey(targetItem.kind, targetItem.code)
          ];
          const hasStableLineage =
            frozen?.fields?.sourceLineageHash &&
            frozen.fields.sourceLineageHash !== canonicalJsonSha256(null);
          return (
            frozen?.fields?.sourceArtifactHash &&
            (!cached || (hasStableLineage && !cached.sourceHash))
          );
        });
    if (missingArtifactTargets.length > 0) {
      const built = buildGitBaseSourceArtifacts({
        cwd: process.cwd(),
        baseCommit: baseline.sourceBase?.baseCommit,
        targets: missingArtifactTargets,
      });
      for (const [key, value] of Object.entries(built.artifacts || {})) {
        artifactCache[key] = value;
      }
      saveChangeBaseline(target, {
        ...baseline,
        localBaseArtifactHashes: artifactCache,
      });
    }

    const localBaseHeads = targets.map(targetItem => {
      const frozen = baseline.resourceHeads?.[targetItem.kind]?.[targetItem.code];
      if (!frozen) {
        return {
          kind: targetItem.kind,
          code: targetItem.code,
          fields: {},
        };
      }
      const fields = { ...(frozen.fields || {}) };
      if (onlineBaselineAdoption) {
        return {
          kind: targetItem.kind,
          code: targetItem.code,
          fields,
        };
      }
      const artifact = artifactCache[
        resourceBaselineTargetKey(targetItem.kind, targetItem.code)
      ];
      const hasStableLineage =
        fields.sourceLineageHash &&
        fields.sourceLineageHash !== canonicalJsonSha256(null);
      if (hasStableLineage) {
        if (!artifact?.sourceHash) {
          throwSourceBaseDiverged(
            `Git 基线构建未生成稳定源码血缘: ${targetItem.kind}:${targetItem.code}`,
            [targetItem]
          );
        }
        fields.sourceLineageHash =
          targetItem.kind === 'Automation'
            ? canonicalJsonSha256([
                {
                  nodeId: '$definition',
                  sha256: String(artifact.sourceHash).toLowerCase(),
                },
              ])
            : String(artifact.sourceHash).toLowerCase();
      } else if (artifact?.artifactHash && fields.sourceArtifactHash) {
        fields.sourceArtifactHash =
          targetItem.kind === 'Automation'
            ? canonicalJsonSha256([
                {
                  nodeId: '$definition',
                  sha256: String(artifact.artifactHash).toLowerCase(),
                },
              ])
            : String(artifact.artifactHash).toLowerCase();
      }
      return {
        kind: targetItem.kind,
        code: targetItem.code,
        fields,
      };
    });

    serverPreflight = await requestWithAuth(
      config,
      target.profileName,
      changeBaselineApiPath(
        target,
        `/${encodeURIComponent(baseline.baselineId)}/preflight`
      ),
      {
        method: 'POST',
        body: {
          targets: targets.map(({ kind, code }) => ({ kind, code })),
          localBaseHeads,
        },
      },
    );
    if (onlineBaselineAdoption) {
      serverPreflight = {
        ...serverPreflight,
        onlineBaselineAdoption,
      };
    }
  }

  const genericResourcePreflight = runGenericResourceGitBasePreflight({
    target,
    manifest,
    baseline,
    publishLease,
    targets: genericTargets,
    onlineBaselineAdoption,
  });
  return genericResourcePreflight
    ? { ...serverPreflight, genericResourcePreflight }
    : serverPreflight;
}

async function runRuntimeChangeBaselinePreflight(config, target) {
  const baseline = getStoredChangeBaseline(target);
  if (!baseline?.baselineId) return null;
  if (!isChangeBaselineOwnedByCurrentSession(baseline)) {
    fail('当前任务不是该变更基线的持有者，禁止激活 Runtime');
  }
  const frozen = baseline.resourceHeads?.Runtime?.active;
  return requestWithAuth(
    config,
    target.profileName,
    changeBaselineApiPath(
      target,
      `/${encodeURIComponent(baseline.baselineId)}/preflight`
    ),
    {
      method: 'POST',
      body: {
        targets: [{ kind: 'Runtime', code: 'active' }],
        localBaseHeads: [
          frozen
            ? { kind: 'Runtime', code: 'active', fields: { ...frozen.fields } }
            : { kind: 'Runtime', code: 'active', fields: {} },
        ],
      },
    }
  );
}

function isManifestEmpty(manifest) {
  return RESOURCE_SPECS.every(spec => (manifest[spec.key] || []).length === 0);
}

async function fetchExistingResourceMaps(config, target, manifest) {
  const maps = {
    roles: new Map(),
    menus: new Map(),
    connectors: new Map(),
    notificationTemplates: new Map(),
    notificationTypeConfigs: new Map(),
    workflows: new Map(),
    functions: new Map(),
    authConfigs: new Map(),
    routes: new Map(),
    publicAccessPolicies: new Map(),
    automations: new Map(),
    dataViews: new Map(),
    storageConfigs: new Map(),
    scopeDimensions: new Map(),
    scopeGrantSources: new Map(),
    dataScopePolicies: new Map(),
    pagePermissionGroups: new Map(),
    formPermissionGroups: new Map(),
  };

  if ((manifest.roles || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`, {
        page: 1,
        limit: 1000,
      })
    );
    indexByCode(maps.roles, normalizeItems(data), item => item.code);
    await hydrateRoleApiPermissions(
      config,
      target,
      maps.roles,
      manifest.roles || []
    );
  }
  if ((manifest.menus || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/menus`
    );
    indexByCode(maps.menus, flattenItems(normalizeItems(data)), item => item.resourceCode);
  }
  if ((manifest.connectors || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/connectors`
    );
    indexByCode(maps.connectors, normalizeItems(data), item => item.code || item.methodName);
  }
  if ((manifest.notifications || []).length > 0) {
    const templates = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications/templates`, {
        page: 1,
        limit: 1000,
      })
    );
    indexByCode(maps.notificationTemplates, normalizeItems(templates), item => item.code);

    const typeConfigs = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications/type-configs`, {
        page: 1,
        limit: 1000,
      })
    );
    indexByCode(
      maps.notificationTypeConfigs,
      normalizeItems(typeConfigs),
      item => notificationTypeConfigExistingKey(item)
    );
  }
  if ((manifest.workflows || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.workflows, normalizeItems(data), item => item.resourceCode);
  }
  if ((manifest.automations || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.automations, normalizeItems(data), item => item.resourceCode);
  }
  if ((manifest.functions || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.functions, normalizeItems(data), item => item.code || item.functionCode || item.resourceCode);
    const missingFunctionDetails = (manifest.functions || [])
      .map(item => item.code || item.functionCode || item.resourceCode)
      .filter(code => {
        const existing = maps.functions.get(code);
        return Boolean(
          existing &&
            (!existing.definitionJson || existing.revision === undefined)
        );
      });
    const functionDetails = await runWithConcurrency(
      missingFunctionDetails,
      8,
      async code => ({
        code,
        detail: await requestOptionalWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions/${encodeURIComponent(code)}`
        ),
      })
    );
    for (const { code, detail } of functionDetails) {
      const existing = maps.functions.get(code);
      maps.functions.set(code, { ...existing, ...(detail || {}) });
    }
  }
  if ((manifest.authConfigs || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/auth/configs`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.authConfigs, normalizeItems(data), item => item.code || item.resourceCode);
    for (const item of manifest.authConfigs || []) {
      const code = item.code || item.resourceCode;
      const existing = maps.authConfigs.get(code);
      if (!existing) continue;
      const detail = await requestOptionalWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/auth/configs/${encodeURIComponent(code)}`
      );
      maps.authConfigs.set(code, {
        ...existing,
        ...(detail || {}),
      });
    }
  }
  if ((manifest.routes || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/routes`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.routes, normalizeItems(data), item => item.code || item.resourceCode);
  }
  if ((manifest.publicAccessPolicies || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/public-access/policies`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.publicAccessPolicies, normalizeItems(data), item => item.code || item.resourceCode);
  }
  if ((manifest.dataViews || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/data-views`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.dataViews, normalizeItems(data), item => item.code || item.resourceCode);
    for (const item of manifest.dataViews || []) {
      const code = item.code || item.resourceCode;
      const existing = maps.dataViews.get(code);
      if (!existing) continue;
      const detail = await requestOptionalWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/data-views/${encodeURIComponent(code)}`
      );
      const groups = await requestOptionalWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/data-views/${encodeURIComponent(code)}/permission-groups`
      );
      maps.dataViews.set(code, {
        ...existing,
        ...(detail || {}),
        permissionGroups: normalizeItems(groups),
      });
    }
  }
  if ((manifest.storageConfigs || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/storage-configs`, {
        page: 1,
        pageSize: 1000,
      })
    );
    indexByCode(maps.storageConfigs, normalizeItems(data), item => item.code || item.resourceCode);
    for (const item of manifest.storageConfigs || []) {
      const code = item.code || item.resourceCode;
      const existing = maps.storageConfigs.get(code);
      if (!existing) continue;
      const detail = await requestOptionalWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/storage-configs/${encodeURIComponent(code)}`
      );
      maps.storageConfigs.set(code, {
        ...existing,
        ...(detail || {}),
      });
    }
  }
  if ((manifest.scopeDimensions || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/scope/dimensions`
    );
    indexByCode(maps.scopeDimensions, normalizeItems(data), item => item.code || item.resourceCode);
  }
  if ((manifest.scopeGrantSources || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/scope/grant-sources`
    );
    indexByCode(maps.scopeGrantSources, normalizeItems(data), item => item.code || item.resourceCode);
  }
  if ((manifest.dataScopePolicies || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/scope/policies`
    );
    indexByCode(maps.dataScopePolicies, normalizeItems(data), item => item.code || item.resourceCode);
  }
  if ((manifest.pagePermissionGroups || []).length > 0) {
    const data = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups`, {
        page: 1,
        limit: 1000,
      })
    );
    indexByCode(maps.pagePermissionGroups, normalizeItems(data), item => item.resourceCode);
  }
  if ((manifest.formPermissionGroups || []).length > 0) {
    for (const formUuid of unique((manifest.formPermissionGroups || []).map(item => resolveManifestFormUuid(target.bound, item)).filter(Boolean))) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-groups`, {
          page: 1,
          limit: 1000,
        })
      );
      indexByCode(maps.formPermissionGroups, normalizeItems(data), item => item.resourceCode);
    }
  }
  return maps;
}

function roleDeclaresApiPermissions(role) {
  if (!Array.isArray(role?.apiPermissionCodes)) return false;
  if (normalizePermissionCodeArray(role.apiPermissionCodes).length > 0) {
    return true;
  }
  return String(role?.apiPermissionMode || '').trim().toLowerCase() === 'replace';
}

function normalizeApiPermissionMode(role) {
  const mode = String(role?.apiPermissionMode || 'merge').trim().toLowerCase();
  if (mode === 'merge' || mode === 'replace') return mode;
  fail(`${resourceLabel('role', role)}: apiPermissionMode 只能是 merge 或 replace`);
}

function sameStringSet(left, right) {
  const a = normalizePermissionCodeArray(left);
  const b = normalizePermissionCodeArray(right);
  if (a.length !== b.length) return false;
  const bSet = new Set(b);
  return a.every(item => bSet.has(item));
}

function isSubsetStringSet(subset, source) {
  const sourceSet = new Set(normalizePermissionCodeArray(source));
  return normalizePermissionCodeArray(subset).every(item => sourceSet.has(item));
}

function normalizeApiPermissionRecords(data) {
  return flattenItems(normalizeItems(data)).filter(item => item?.code);
}

async function fetchRoleApiPermissions(config, target, roleId) {
  if (!roleId) return [];
  const data = await requestWithAuth(
    config,
    target.profileName,
    `/permission/api/role/${encodeURIComponent(roleId)}`
  );
  return normalizeApiPermissionRecords(data);
}

async function hydrateRoleApiPermissions(config, target, roleMap, desiredRoles) {
  const roles = (desiredRoles || []).filter(roleDeclaresApiPermissions);
  if (roles.length === 0) return;
  for (const role of roles) {
    const code = role.code || role.resourceCode;
    const existing = roleMap.get(code);
    if (!existing?.id) continue;
    const permissions = await fetchRoleApiPermissions(config, target, existing.id);
    roleMap.set(code, {
      ...existing,
      apiPermissionCodes: normalizePermissionCodeArray(
        permissions.map(item => item.code)
      ),
    });
  }
}

async function fetchAppApiPermissionMap(config, target) {
  const data = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery('/permission/api', {
      scope: 'app',
      appType: target.appType,
      page: 1,
      limit: 1000,
    })
  );
  const map = new Map();
  for (const item of normalizeApiPermissionRecords(data)) {
    map.set(String(item.code), item);
  }
  return map;
}

async function syncRoleApiPermissions(config, target, role, roleId) {
  if (!roleDeclaresApiPermissions(role) || !roleId) return null;
  const desiredCodes = normalizePermissionCodeArray(role.apiPermissionCodes);
  const mode = normalizeApiPermissionMode(role);
  const currentPermissions = await fetchRoleApiPermissions(config, target, roleId);
  const currentCodes = normalizePermissionCodeArray(
    currentPermissions.map(item => item.code)
  );
  const nextCodes =
    mode === 'replace' ? desiredCodes : unique([...currentCodes, ...desiredCodes]);
  if (sameStringSet(currentCodes, nextCodes)) {
    return { action: 'noop', mode, codes: desiredCodes };
  }

  const permissionMap = await fetchAppApiPermissionMap(config, target);
  const currentByCode = new Map(
    currentPermissions.map(item => [String(item.code), item])
  );
  const permissionIds = nextCodes.map(code => {
    const permission = currentByCode.get(code) || permissionMap.get(code);
    if (!permission?.id) {
      fail(
        `${resourceLabel('role', role)}: 未找到接口权限点 ${code}，请确认平台已 seed 该权限`
      );
    }
    return permission.id;
  });

  await requestWithAuth(config, target.profileName, '/permission/api/assign', {
    method: 'POST',
    body: { roleId, permissionIds },
  });

  return { action: 'update', mode, codes: desiredCodes };
}

function addPlanActions(
  actions,
  kind,
  desiredItems = [],
  existingMap,
  equals,
  extraFields
) {
  for (const item of desiredItems) {
    const code = item.code || item.resourceCode || item.methodName;
    const existing = existingMap.get(code);
    actions.push({
      kind,
      code,
      action: existing ? (equals(item, existing) ? 'noop' : 'update') : 'create',
      platformId: existing?.id,
      ...(existing?.revision !== undefined ? { expectedRevision: existing.revision } : {}),
      ...(existing?.version !== undefined ? { expectedVersion: existing.version } : {}),
      ...(existing?.updatedAt ? { expectedUpdatedAt: existing.updatedAt } : {}),
      ...sourceAnalysisPlanFields(item),
      ...(typeof extraFields === 'function'
        ? extraFields(item, existing)
        : {}),
    });
  }
}

function sourceAnalysisPlanFields(item) {
  const analysis = item?.__sourceAnalysis;
  const definition = item?.definitionJson || {};
  return {
    ...(analysis
      ? {
          sourceDependencies: analysis.sourceDependencies,
          resourceReferences: analysis.resourceReferences,
        }
      : {}),
    ...(definition.responseCache !== undefined
      ? { responseCache: clonePlainJson(definition.responseCache) }
      : {}),
    ...(definition.invocationAudit !== undefined
      ? { invocationAudit: clonePlainJson(definition.invocationAudit) }
      : {}),
  };
}

function addNotificationPlanActions(target, actions, notificationItems = [], existing) {
  const { templates, typeConfigs } = splitNotificationResources(notificationItems);
  for (const template of templates) {
    const existingTemplate = existing.notificationTemplates.get(template.code);
    actions.push({
      kind: 'notificationTemplate',
      code: template.code,
      action: existingTemplate
        ? notificationTemplateEquals(target.bound, template, existingTemplate)
          ? 'noop'
          : 'update'
        : 'create',
      platformId: existingTemplate?.id,
    });
  }
  for (const config of typeConfigs) {
    const key = notificationTypeConfigDesiredKey(target.bound, config);
    const existingConfig = existing.notificationTypeConfigs.get(key);
    actions.push({
      kind: 'notificationTypeConfig',
      code: config.code || config.notificationType,
      action: existingConfig
        ? notificationTypeConfigEquals(target.bound, config, existingConfig)
          ? 'noop'
          : 'update'
        : 'create',
      platformId: existingConfig?.id,
    });
  }
}

async function addWorkflowPlanActions(config, target, actions, desiredItems = [], existingMap) {
  const planned = await runWithConcurrency(desiredItems, 8, async item => {
    const code = item.code || item.resourceCode;
    const existing = existingMap.get(code);
    if (!existing) {
      return {
        kind: 'workflow',
        code,
        action: 'create',
        expectedRevision: 0,
        ...sourceAnalysisPlanFields(item),
      };
    }
    const detail = await requestOptionalWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows/${encodeURIComponent(existing.id)}`
    );
    const remoteRevision = Number(detail?.revision ?? existing.revision);
    if (!Number.isSafeInteger(remoteRevision) || remoteRevision <= 0) {
      throw workflowRevisionRequiredError(`resource plan workflow ${code}`);
    }
    return {
      kind: 'workflow',
      code,
      action: workflowEquals(target.bound, item, detail || existing) ? 'noop' : 'update',
      platformId: existing.id,
      expectedRevision: remoteRevision,
      remoteRevision,
      ...sourceAnalysisPlanFields(item),
    };
  });
  actions.push(...planned);
}

async function addAutomationPlanActions(config, target, actions, desiredItems = [], existingMap) {
  const planned = await runWithConcurrency(desiredItems, 8, async item => {
    const code = item.code || item.resourceCode;
    const existing = existingMap.get(code);
    if (!existing) {
      return {
        kind: 'automation',
        code,
        action: 'create',
        ...sourceAnalysisPlanFields(item),
      };
    }
    const detail = await requestOptionalWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(existing.id)}`
    );
    return {
      kind: 'automation',
      code,
      action: automationEquals(target, item, detail || existing) ? 'noop' : 'update',
      platformId: existing.id,
      ...((detail || existing)?.version !== undefined
        ? { expectedVersion: (detail || existing).version }
        : {}),
      ...((detail || existing)?.updatedAt
        ? { expectedUpdatedAt: (detail || existing).updatedAt }
        : {}),
      currentIsPublished: Boolean((detail || existing)?.isPublished),
      currentIsEnabled: Boolean((detail || existing)?.isEnabled),
      ...resourceBindingPlanFields(
        target,
        'Automation',
        item,
        detail || existing
      ),
      ...sourceAnalysisPlanFields(item),
    };
  });
  actions.push(...planned);
}

async function addFormSettingPlanActions(
  config,
  target,
  actions,
  desiredItems = []
) {
  for (const item of desiredItems) {
    const code = item.code || item.formCode || item.formUuid;
    const formUuid = resolveManifestFormUuid(target.bound, item, {
      fallbackToCode: true,
    });
    if (!formUuid) {
      actions.push({ kind: 'formSetting', code, action: 'update' });
      continue;
    }
    const frozen = await fetchFrozenFormConfig(config, target, formUuid);
    const existing = formSettingValuesFromSnapshot(frozen);
    actions.push({
      kind: 'formSetting',
      code,
      action: formSettingEquals(item, existing) ? 'noop' : 'update',
      formUuid,
      expectedRevision: frozen.revision,
      expectedEtag: frozen.etag,
      expectedParent: frozen.expectedParent,
    });
  }
}

function formSettingValuesFromSnapshot(frozen) {
  const snapshot = frozen?.snapshot || {};
  return {
    name: snapshot?.form?.name,
    schema: snapshot?.form?.schema,
    packages: snapshot?.form?.packages,
    formType: snapshot?.form?.formType,
    relateUuid: snapshot?.form?.relateUuid ?? null,
    settings: snapshot?.form?.settingsJson || {},
    indexes: snapshot?.resources?.fieldIndexes || [],
    dataManagement: snapshot?.resources?.dataManagement ?? null,
    publicAccess: snapshot?.resources?.publicAccess ?? null,
    bundle: snapshot?.resources?.bundle ?? null,
  };
}

function formSettingManifestSettings(item) {
  const resourceCode = String(item.code || item.formCode || '').trim();
  if (
    item.settings === undefined &&
    item.runtimeWrite === undefined &&
    !resourceCode
  ) {
    return undefined;
  }
  return {
    ...(item.settings || {}),
    ...(item.runtimeWrite !== undefined
      ? { runtimeWrite: item.runtimeWrite }
      : {}),
    ...(resourceCode ? { openxiangdaResourceCode: resourceCode } : {}),
  };
}

function buildFormSettingBundleBody(item) {
  const body = {};
  const settings = formSettingManifestSettings(item);
  if (settings !== undefined) body.settings = settings;
  for (const key of [
    'name',
    'schema',
    'packages',
    'formType',
    'relateUuid',
    'bundle',
    'indexes',
    'dataManagement',
  ]) {
    if (item[key] !== undefined) body[key] = item[key];
  }
  if (item.publicAccess !== undefined) {
    const publicAccess =
      typeof item.publicAccess === 'object' && item.publicAccess !== null
        ? item.publicAccess
        : { isPublic: Boolean(item.publicAccess) };
    body.publicAccess =
      publicAccess.isPublic === false
        ? null
        : {
            isPublic: true,
            description: publicAccess.description || '',
          };
  }
  return body;
}

function frozenFormConfigFromPlanAction(action) {
  if (
    !action ||
    action.expectedRevision === undefined ||
    !action.expectedEtag ||
    !action.expectedParent
  ) {
    return null;
  }
  return normalizeFrozenFormConfig(
    {
      revision: action.expectedRevision,
      etag: action.expectedEtag,
      activeFormReleaseHead: action.expectedParent,
    },
    'Form publish plan'
  );
}

function summarizeActions(actions) {
  return actions.reduce(
    (acc, item) => {
      acc[item.action] = (acc[item.action] || 0) + 1;
      return acc;
    },
    { create: 0, update: 0, noop: 0, delete: 0 }
  );
}

function normalizeItems(data) {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  if (Array.isArray(data.items)) return data.items;
  if (Array.isArray(data.data)) return data.data;
  if (Array.isArray(data.data?.items)) return data.data.items;
  return [];
}

function flattenItems(items) {
  const result = [];
  const visit = item => {
    if (!item || typeof item !== 'object') return;
    result.push(item);
    for (const child of item.children || []) visit(child);
  };
  for (const item of items || []) visit(item);
  return result;
}

function indexByCode(map, items, getCode) {
  for (const item of items || []) {
    const code = getCode(item);
    if (code) map.set(String(code), item);
  }
}

async function requestOptionalWithAuth(config, profileName, apiPath, options = {}) {
  try {
    return await requestWithAuth(config, profileName, apiPath, options);
  } catch (error) {
    const status = Number(error?.status || error?.statusCode || error?.response?.status);
    const apiCode = Number(error?.apiCode);
    const message = String(error?.message || '');
    if (
      status === 404 ||
      apiCode === 404 ||
      message.includes('HTTP 404') ||
      message.includes('不存在') ||
      /not\s*found/i.test(message)
    ) {
      return null;
    }
    throw error;
  }
}

async function publishRoleResources(config, target, roles, result, options = {}) {
  for (const role of roles) {
    if (shouldSkipNoopResource(options, 'role', role.code)) {
      recordNoopResource(result, 'role', role.code, options);
      continue;
    }
    const existing = await findExistingRole(config, target, role.code);
    const body = {
      code: role.code,
      name: role.name || role.code,
      description: role.description || '',
    };
    const data = existing
      ? await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles/${encodeURIComponent(existing.id)}`,
          { method: 'POST', body }
        )
      : await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`,
          { method: 'POST', body }
        );
    if (data?.id) {
      saveRoleResource(target, role.code, data.id, { code: data.code, name: data.name });
    }
    if (Array.isArray(role.userIds) && role.userIds.length > 0 && data?.id) {
      await requestWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles/${encodeURIComponent(data.id)}/users`,
        { method: 'POST', body: { userIds: role.userIds } }
      );
    }
    const apiPermissions = await syncRoleApiPermissions(
      config,
      target,
      role,
      data?.id
    );
    result.published.push({
      kind: 'role',
      code: role.code,
      action: existing ? 'update' : 'create',
      id: data?.id,
      ...(apiPermissions ? { apiPermissions } : {}),
    });
  }
}

async function findExistingRole(config, target, code) {
  const data = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`, {
      code,
      page: 1,
      limit: 1,
    })
  );
  return normalizeItems(data).find(item => item.code === code);
}

async function publishFormSettingsResources(
  config,
  target,
  settingsItems,
  permissionGroups,
  result,
  options = {}
) {
  const settingsByForm = new Map();
  for (const item of settingsItems) {
    const code = item.code || item.formCode || item.formUuid;
    const formUuid = resolveManifestFormUuid(target.bound, item, {
      fallbackToCode: true,
    });
    if (!formUuid) fail(`表单设置 ${code} 无法解析 formUuid`);
    settingsByForm.set(formUuid, { item, code });
  }
  const changedGroupsByForm = new Map();
  options.formReleaseHandledPermissionCodes =
    options.formReleaseHandledPermissionCodes || new Set();
  for (const group of permissionGroups || []) {
    const code = group.code || group.resourceCode;
    if (shouldSkipNoopResource(options, 'formPermissionGroup', code)) {
      recordNoopResource(result, 'formPermissionGroup', code, options);
      options.formReleaseHandledPermissionCodes.add(code);
      continue;
    }
    const formUuid = resolveManifestFormUuid(target.bound, group);
    if (!formUuid) {
      fail(`表单权限组 ${code} 无法解析 formUuid，不能进入 FormRelease`);
    }
    if (!changedGroupsByForm.has(formUuid)) {
      changedGroupsByForm.set(formUuid, []);
    }
    changedGroupsByForm.get(formUuid).push(group);
  }
  const formUuids = unique([
    ...settingsByForm.keys(),
    ...changedGroupsByForm.keys(),
  ]).sort();
  for (const formUuid of formUuids) {
    const setting = settingsByForm.get(formUuid);
    const item = setting?.item || null;
    const groups = changedGroupsByForm.get(formUuid) || [];
    const code =
      setting?.code ||
      groups[0]?.formCode ||
      groups[0]?.form ||
      formUuid;
    const settingNoop =
      item && shouldSkipNoopResource(options, 'formSetting', code);
    const recovered = await discardAbortedStagedFormRelease(
      config,
      target,
      options.changeId,
      formUuid
    );
    if (recovered) {
      result.recoveredStagedFormReleases =
        result.recoveredStagedFormReleases || [];
      result.recoveredStagedFormReleases.push(recovered);
    }
    if (settingNoop) {
      recordNoopResource(result, 'formSetting', code, options);
    }
    if (settingNoop && groups.length === 0) continue;
    const action = item
      ? getPlannedResourceAction(options, 'formSetting', code)
      : null;
    const frozen =
      frozenFormConfigFromPlanAction(action) ||
      (await fetchFrozenFormConfig(config, target, formUuid));
    const bundleBody =
      item && !settingNoop ? buildFormSettingBundleBody(item) : {};
    if (groups.length > 0) {
      bundleBody.permissionGroups = groups.map(group => {
        const body = {
          ...withoutResourceMeta(group),
          resourceCode: group.code || group.resourceCode,
          name: group.name || group.code || group.resourceCode,
          type: group.type || 'view',
          roles: group.roles || [],
        };
        delete body.code;
        delete body.formCode;
        delete body.form;
        delete body.formUuid;
        return body;
      });
      bundleBody.permissionGroupsMode = 'merge';
    }
    const activate = options.activateFormBundles === true;
    const artifactId = stableFormArtifactId(
      'config-bundle',
      target,
      formUuid,
      frozen,
      bundleBody
    );
    const data = await requestFrozenFormMutation(
      config,
      target,
      formUuid,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/bundle`,
      'config-bundle',
      {
        ...bundleBody,
        ...(activate ? { activate: true } : {}),
      },
      { frozen, artifactId }
    );
    if (item) {
      saveResourceEntry(target, 'formSettings', code, { formUuid });
    }
    for (const group of groups) {
      const groupCode = group.code || group.resourceCode;
      saveFormPermissionGroupResource(
        target,
        groupCode,
        undefined,
        { formUuid }
      );
      options.formReleaseHandledPermissionCodes.add(groupCode);
    }
    const releaseId = data?.release?.id;
    const contentHash = String(
      data?.release?.contentHash || data?.contentHash || ''
    ).toLowerCase();
    const stagedResource =
      data?.staged && !data?.active && releaseId
        ? {
            kind: 'FormRelease',
            identity: { releaseId, formUuid },
            action: 'update',
            hash: contentHash,
            revision: stripUndefinedValues({
              parentReleaseId:
                data?.release?.parentReleaseId ||
                frozen.expectedParent?.releaseId ||
                null,
              baseRevision:
                data?.release?.baseRevision ?? frozen.expectedParent?.revision,
            }),
            metadata: {
              releaseStatus: data?.releaseStatus || 'staged',
              formCode: code,
            },
          }
        : null;
    if (
      !activate &&
      !data?.noop &&
      (!data?.staged || data?.active || !releaseId || !stagedResource)
    ) {
      fail(
        `FORM_RELEASE_STAGE_REQUIRED: ${code} 的非激活 bundle 响应必须返回 staged=true、active=false、releaseId 和 contentHash`
      );
    }
    if (stagedResource && !/^[a-f0-9]{64}$/.test(contentHash)) {
      fail(
        `FORM_RELEASE_STAGED_RESOURCE_INVALID: ${code} 的 staged FormRelease 缺少 64 位 contentHash`
      );
    }
    if (stagedResource) {
      result.stagedResources = result.stagedResources || [];
      result.stagedResources.push(stagedResource);
      if (result.stagedResources.length === 1) {
        result.stagedResource = stagedResource;
      } else {
        delete result.stagedResource;
      }
    }
    if (item && !settingNoop) {
      result.published.push({
        kind: 'formSetting',
        code,
        action: data?.noop ? 'noop' : data?.active ? 'update' : 'stage',
        formUuid,
        revision: data?.revision,
        activeFormReleaseHead: data?.activeFormReleaseHead,
        staged: Boolean(data?.staged),
        active: Boolean(data?.active),
        releaseStatus: data?.releaseStatus,
        releaseId,
        contentHash: contentHash || undefined,
        ...(stagedResource ? { stagedResource } : {}),
      });
    }
    for (const group of groups) {
      result.published.push({
        kind: 'formPermissionGroup',
        code: group.code || group.resourceCode,
        action: data?.noop ? 'noop' : data?.active ? 'update' : 'stage',
        formUuid,
        staged: Boolean(data?.staged),
        active: Boolean(data?.active),
        releaseStatus: data?.releaseStatus,
        releaseId,
        contentHash: contentHash || undefined,
        ...(stagedResource ? { stagedResource } : {}),
      });
    }
  }
}

async function publishMenuResources(config, target, menus, result, options = {}) {
  if (menus.length === 0) return;
  const existingMenus = await fetchExistingMenusByCode(config, target);
  const orderedMenus = orderMenuResourcesForPublish(
    menus,
    target.bound,
    existingMenus
  );
  for (const menuItem of orderedMenus) {
    const code = menuResourceCode(menuItem);
    const plannedAction = getPlannedResourceAction(options, 'menu', code);
    const existing = existingMenus.get(code);
    if (existing && !menuPlatformId(existing)) {
      const error = new Error(
        `MENU_ONLINE_ID_REQUIRED: 在线 menu ${code} 缺少 menuId，禁止执行恢复发布`
      );
      error.code = 'MENU_ONLINE_ID_REQUIRED';
      throw error;
    }
    if (
      ['noop', 'update'].includes(plannedAction?.action) &&
      !menuPlatformId(existing)
    ) {
      const error = new Error(
        `MENU_PLAN_TARGET_MISSING: menu ${code} 的冻结计划为 ${plannedAction.action}，但写入前在线菜单已不存在`
      );
      error.code = 'MENU_PLAN_TARGET_MISSING';
      throw error;
    }
  }
  for (const menuItem of orderedMenus) {
    const code = menuResourceCode(menuItem);
    const existing = existingMenus.get(code);
    if (shouldSkipNoopResource(options, 'menu', code)) {
      const existingId = menuPlatformId(existing);
      saveMenuResource(target, code, existingId, {
        formUuid: existing.formUuid,
        pageId: existing.pageId,
        parentId: existing.parentId,
        routeCode: existing.routeCode,
        path: existing.path,
      });
      recordNoopResource(result, 'menu', code, options);
      continue;
    }
    const formUuid = resolveManifestFormUuid(target.bound, menuItem);
    const pageId = resolveManifestPageId(target.bound, menuItem);
    const parentId = requireResolvedMenuParentId(
      target.bound,
      menuItem,
      existingMenus,
      `resource publish menu ${code}`
    );
    const body = {
      resourceCode: code,
      name: menuItem.name || code,
      type: menuItem.type || 'nav',
      formUuid,
      pageId,
      parentId,
      sortOrder: menuItem.sortOrder,
      icon: menuItem.icon || null,
      isHidden: menuItem.isHidden,
      routeCode: menuItem.routeCode || null,
      path: menuItem.path || null,
    };
    const existingId = menuPlatformId(existing);
    let data = existing
      ? await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/menus/${encodeURIComponent(existingId)}`,
          { method: 'POST', body }
        )
      : await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/menus`,
          { method: 'POST', body }
        );
    if (!data?.id) {
      const error = new Error(
        `MENU_WRITE_ID_REQUIRED: menu ${code} 写入成功响应缺少 menuId，禁止继续发布子菜单`
      );
      error.code = 'MENU_WRITE_ID_REQUIRED';
      throw error;
    }
    saveMenuResource(target, code, data.id, {
      resourceCode: code,
      name: data.name,
      type: data.type,
      ...(formUuid ? { formUuid } : {}),
      ...(pageId ? { pageId } : {}),
      ...(menuItem.pageCode ? { pageCode: menuItem.pageCode } : {}),
      ...(menuItem.routeCode || data.routeCode
        ? { routeCode: data.routeCode || menuItem.routeCode }
        : {}),
      ...(menuItem.path || data.path ? { path: data.path || menuItem.path } : {}),
      parentId: data.parentId || parentId,
    });
    existingMenus.set(code, {
      ...(existing || {}),
      ...body,
      ...data,
      id: data.id,
    });
    result.published.push({
      kind: 'menu',
      code,
      action: existing ? 'update' : 'create',
      id: data?.id,
    });
  }
}

async function fetchExistingMenusByCode(config, target) {
  const data = await requestWithAuth(
    config,
    target.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/menus`
  );
  const menus = new Map();
  indexByCode(
    menus,
    flattenItems(normalizeItems(data)),
    item => item.resourceCode
  );
  return menus;
}

async function publishConnectorResources(config, target, connectors, result, options = {}) {
  if (connectors.length === 0) return;
  const changedConnectors = [];
  for (const connector of connectors) {
    const code = connector.code || connector.connectorCode;
    if (shouldSkipNoopResource(options, 'connector', code)) {
      recordNoopResource(result, 'connector', code, options);
    } else {
      changedConnectors.push(connector);
    }
  }
  if (changedConnectors.length === 0) return;
  const body = { connectors: changedConnectors.map(normalizeConnectorManifest) };
  const data = await requestWithAuth(
    config,
    target.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/connectors/actions/sync`,
    { method: 'POST', body }
  );
  for (const item of data.data || []) {
    const apiEntries = {};
    for (const api of item.apis || []) {
      const apiCode = api.code || api.methodName;
      if (apiCode) apiEntries[apiCode] = { apiId: api.id, name: api.name };
    }
    saveConnectorResource(target, item.code, item.connector?.id, {
      code: item.code,
      name: item.connector?.name,
      apis: apiEntries,
    });
    result.published.push({
      kind: 'connector',
      code: item.code,
      action: item.created ? 'create' : 'update',
      id: item.connector?.id,
    });
  }
}

async function publishNotificationResources(config, target, notifications, result, options = {}) {
  const { templates, typeConfigs } = splitNotificationResources(notifications);
  for (const template of templates) {
    if (shouldSkipNoopResource(options, 'notificationTemplate', template.code)) {
      recordNoopResource(result, 'notificationTemplate', template.code, options);
      continue;
    }
    const body = normalizeNotificationTemplateManifest(target.bound, template);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications/templates/${encodeURIComponent(template.code)}`,
      { method: 'POST', body }
    );
    if (data?.id) {
      saveNotificationTemplateResource(target, template.code, data.id, {
        level: data.level || body.level,
        formUuid: data.formUuid || body.formUuid,
      });
    }
    result.published.push({
      kind: 'notificationTemplate',
      code: template.code,
      action: data?.created ? 'create' : 'update',
      id: data?.id,
    });
  }

  for (const configItem of typeConfigs) {
    const configCode = configItem.code || configItem.notificationType;
    if (shouldSkipNoopResource(options, 'notificationTypeConfig', configCode)) {
      recordNoopResource(result, 'notificationTypeConfig', configCode, options);
      continue;
    }
    const body = normalizeNotificationTypeConfigManifest(target.bound, configItem);
    const data = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications/type-configs/${encodeURIComponent(configItem.notificationType)}`,
      { method: 'POST', body }
    );
    const stateCode = configItem.code || notificationTypeConfigDesiredKey(target.bound, configItem);
    if (data?.id) {
      saveNotificationTypeConfigResource(target, stateCode, data.id, {
        notificationType: data.notificationType || configItem.notificationType,
        level: data.level || body.level,
        formUuid: data.formUuid || body.formUuid,
        templateId: data.templateId,
        templateCode: data.template?.code || configItem.templateCode,
      });
    }
    result.published.push({
      kind: 'notificationTypeConfig',
      code: configItem.code || configItem.notificationType,
      action: data?.created ? 'create' : 'update',
      id: data?.id,
    });
  }
}

async function publishWorkflowResources(config, target, workflows, result, options = {}) {
  for (const workflowItem of workflows) {
    if (
      options.workflowReleaseHandledKeys?.has(
        `Workflow:${workflowItem.code}`
      )
    ) {
      continue;
    }
    if (shouldSkipNoopResource(options, 'workflow', workflowItem.code)) {
      recordNoopResource(result, 'workflow', workflowItem.code, options);
      continue;
    }
    const plannedAction = getPlannedResourceAction(
      options,
      'workflow',
      workflowItem.code
    );
    if (!plannedAction) {
      fail(
        `WORKFLOW_REVISION_REQUIRED: workflow ${workflowItem.code} 缺少冻结的 publishPlan action`
      );
    }
    const existing =
      plannedAction.action === 'create'
        ? null
        : {
            id: plannedAction.platformId,
            revision:
              plannedAction.expectedRevision ?? plannedAction.remoteRevision,
          };
    if (existing && !existing.id) {
      fail(
        `WORKFLOW_REVISION_REQUIRED: workflow ${workflowItem.code} 的冻结计划缺少 platformId`
      );
    }
    if (
      existing &&
      (!Number.isSafeInteger(Number(existing.revision)) ||
        Number(existing.revision) <= 0)
    ) {
      throw workflowRevisionRequiredError(
        `resource publish workflow ${workflowItem.code}`
      );
    }
    const compiledWorkflow = await compileWorkflowSourceFile(workflowItem);
    const definitionJson = compiledWorkflow?.definitionJson || await resolveManifestJson(
      config,
      target.profileName,
      workflowItem,
      'definitionJson',
      'definitionFile'
    );
    const viewJson =
      compiledWorkflow?.previewJson ??
      (await resolveManifestJson(
        config,
        target.profileName,
        workflowItem,
        'viewJson',
        'viewFile',
        true
      )) ??
      (await resolveManifestJson(
      config,
      target.profileName,
      workflowItem,
      'previewJson',
      'previewFile',
      true
    ));
    const formUuid = resolveManifestFormUuid(target.bound, workflowItem);
    const changeId = workflowChangeIdFromPublishOptions(target, options);
    const mutationAction = existing
      ? `workflow.update:${existing.id}`
      : `workflow.create:${workflowItem.code}`;
    const body = buildWorkflowMutationBody(changeId, mutationAction, {
      expectedRevision: existing ? Number(existing.revision) : 0,
      resourceCode: workflowItem.code,
      formUuid,
      definitionJson,
      ...(viewJson !== undefined ? { viewJson } : {}),
    });
    let data = existing
      ? await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows/${encodeURIComponent(existing.id)}`,
          { method: 'POST', body }
        )
      : await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows`,
          { method: 'POST', body }
        );
    if (data?.id) {
      saveWorkflowResource(target, workflowItem.code, data.id, {
        formUuid,
        revision: data.revision,
        etag: data.etag,
      });
    }
    if (workflowItem.publish && data?.id) {
      const publishRevision = Number(data.revision);
      if (!Number.isSafeInteger(publishRevision) || publishRevision <= 0) {
        throw workflowRevisionRequiredError(
          `resource publish workflow ${workflowItem.code} follow-up`
        );
      }
      const publishBody = buildWorkflowMutationBody(
        changeId,
        `workflow.publish:${data.id}`,
        { isPublished: true, expectedRevision: publishRevision }
      );
      data = await requestWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows/${encodeURIComponent(data.id)}/publish`,
        { method: 'POST', body: publishBody }
      );
    }
    if (data?.id) {
      saveWorkflowResource(target, workflowItem.code, data.id, {
        formUuid,
        revision: data.revision,
        etag: data.etag,
      });
    }
    result.published.push({ kind: 'workflow', code: workflowItem.code, action: existing ? 'update' : 'create', id: data?.id });
  }
}

async function publishAutomationResources(config, target, automations, result, options = {}) {
  for (const automationItem of automations) {
    if (
      options.backendReleaseSourceHandledKeys?.has(
        `Automation:${automationItem.code}`
      ) ||
      options.backendReleaseHandledKeys?.has(`Automation:${automationItem.code}`)
    ) {
      continue;
    }
    if (shouldSkipNoopResource(options, 'automation', automationItem.code)) {
      recordNoopResource(result, 'automation', automationItem.code, options);
      continue;
    }
    const publishLeaseId = await refreshResourcePublishLease(
      config,
      target,
      options
    );
    const existing = await findExistingAutomation(config, target, automationItem.code);
    let definitionJson = await resolveManifestJson(
      config,
      target.profileName,
      automationItem,
      'definitionJson',
      'definitionFile'
    );
    applyResourceBindingsToRuntimeDefinition(target.bound, automationItem, definitionJson);
    const viewJson =
      (await resolveManifestJson(
        config,
        target.profileName,
        automationItem,
        'viewJson',
        'viewFile',
        true
      )) ??
      (await resolveManifestJson(
      config,
      target.profileName,
      automationItem,
      'previewJson',
      'previewFile',
      true
    ));
    const replaceManifest =
      !existing ||
      shouldReplaceResourceManifestItem(
        automationItem,
        'automations',
        automationItem.code,
        options
      );
    const sourceOnlyPatch = Boolean(existing && !replaceManifest);
    const automationPayload = resolveAutomationManifestPayload(target, automationItem);
    const automationSourcePatchSources = sourceOnlyPatch
      ? buildAutomationSourcePatchSources(existing.definitionJson, definitionJson)
      : [];
    if (sourceOnlyPatch) {
      definitionJson = mergeSourceSnapshotDefinition(
        existing.definitionJson,
        definitionJson
      );
    }
    const updatePreconditions = getResourceUpdatePreconditions(
      options,
      'automation',
      automationItem.code,
      existing
    );
    const body = {
      resourceCode: automationItem.code,
      name: sourceOnlyPatch
        ? existing.name
        : automationItem.name || automationItem.code,
      description: sourceOnlyPatch
        ? existing.description
        : automationItem.description || '',
      formUuid: sourceOnlyPatch ? existing.formUuid : automationPayload.formUuid,
      triggerConfig: sourceOnlyPatch
        ? existing.triggerConfig
        : automationPayload.triggerConfig,
      definitionJson,
      ...(sourceOnlyPatch
        ? existing.viewJson !== undefined
          ? { viewJson: existing.viewJson }
          : {}
        : viewJson !== undefined
          ? { viewJson }
          : {}),
      ...(sourceOnlyPatch
        ? existing.tags !== undefined
          ? { tags: existing.tags }
          : {}
        : automationItem.tags !== undefined
          ? {
              tags: Array.isArray(automationItem.tags)
                ? automationItem.tags.join(',')
                : automationItem.tags,
            }
          : {}),
      ...(sourceOnlyPatch
        ? existing.isEnabled !== undefined
          ? { isEnabled: Boolean(existing.isEnabled) }
          : {}
        : automationItem.isEnabled !== undefined
          ? { isEnabled: Boolean(automationItem.isEnabled) }
          : {}),
      ...(publishLeaseId ? { publishLeaseId } : {}),
      ...(existing ? {
        ...(updatePreconditions.expectedVersion !== undefined
          ? { expectedVersion: updatePreconditions.expectedVersion }
          : {}),
        ...(updatePreconditions.expectedUpdatedAt
          ? { expectedUpdatedAt: updatePreconditions.expectedUpdatedAt }
          : {}),
      } : {}),
    };
    const useServerSourcePatch = Boolean(
      existing &&
      sourceOnlyPatch &&
      publishLeaseId &&
      automationSourcePatchSources.length > 0
    );
    let data = useServerSourcePatch
      ? await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(existing.id)}/source`,
          {
            method: 'PATCH',
            body: stripUndefinedValues({
              publishLeaseId,
              expectedVersion: updatePreconditions.expectedVersion,
              expectedUpdatedAt: updatePreconditions.expectedUpdatedAt,
              sources: automationSourcePatchSources,
            }),
          }
        )
      : existing
        ? await requestWithAuth(
            config,
            target.profileName,
            `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(existing.id)}`,
            { method: 'POST', body }
          )
        : await requestWithAuth(
            config,
            target.profileName,
            `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations`,
            { method: 'POST', body }
          );
    if (automationItem.publish && data?.id) {
      data = await requestWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(data.id)}/publish`,
        {
          method: 'POST',
          body: stripUndefinedValues({
            expectedVersion: data.version,
            expectedUpdatedAt: data.updatedAt,
            publishLeaseId,
          }),
        }
      );
    }
    if (automationItem.enable !== undefined && data?.id) {
      data = await requestWithAuth(
        config,
        target.profileName,
        `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(data.id)}/${automationItem.enable ? 'enable' : 'disable'}`,
        {
          method: 'POST',
          body: stripUndefinedValues({
            expectedVersion: data.version,
            expectedUpdatedAt: data.updatedAt,
            publishLeaseId,
          }),
        }
      );
    }
    const savedFormUuid = sourceOnlyPatch
      ? existing.formUuid
      : automationPayload.formUuid;
    if (data?.id) saveAutomationResource(target, automationItem.code, data.id, { formUuid: savedFormUuid, resourceCode: automationItem.code });
    result.published.push({
      kind: 'automation',
      code: automationItem.code,
      action: existing ? 'update' : 'create',
      ...(sourceOnlyPatch
        ? {
            writeMode: 'source-patch',
            sourcePatchTransport: useServerSourcePatch
              ? 'field-patch'
              : 'compat-merge',
            preservedFields: ['name', 'description', 'formUuid', 'triggerConfig', 'viewJson', 'tags', 'isEnabled', 'resourceBindings'],
          }
        : { writeMode: 'manifest-replace' }),
      id: data?.id,
    });
  }
}

async function publishFunctionResources(config, target, functions, result, options = {}) {
  for (const functionItem of functions) {
    const code = functionItem.code || functionItem.functionCode || functionItem.resourceCode;
    if (
      options.backendReleaseSourceHandledKeys?.has(`Function:${code}`) ||
      options.backendReleaseHandledKeys?.has(`Function:${code}`)
    ) {
      continue;
    }
    if (functionManifestDeclaresSecretRefs(functionItem)) {
      const error = new Error(
        `APP_FUNCTION_SECRET_STAGED_RELEASE_REQUIRED: Function:${code} secretRefs 必须由 Backend Release v2 原子发布，禁止 direct/source PATCH 降级`
      );
      error.code = 'APP_FUNCTION_SECRET_STAGED_RELEASE_REQUIRED';
      throw error;
    }
    if (shouldSkipNoopResource(options, 'function', code)) {
      recordNoopResource(result, 'function', code, options);
      continue;
    }
    const publishLeaseId = await refreshResourcePublishLease(
      config,
      target,
      options
    );
    const existing = await findExistingFunction(config, target, code);
    let definitionJson = await resolveManifestJson(
      config,
      target.profileName,
      functionItem,
      'definitionJson',
      'definitionFile'
    );
    applyResourceBindingsToRuntimeDefinition(target.bound, functionItem, definitionJson);
    definitionJson = normalizeFunctionDefinitionJson(functionItem, definitionJson);
    const replaceManifest =
      !existing ||
      shouldReplaceResourceManifestItem(
        functionItem,
        'functions',
        code,
        options
      );
    const sourceOnlyPatch = Boolean(existing && !replaceManifest);
    const preservedBindings = sourceOnlyPatch
      ? clonePlainJson(
          existing.resourceBindings ??
            existing.resourceBindingsJson ??
            existing.definitionJson?.resourceBindings ??
            {}
        )
      : null;
    if (sourceOnlyPatch) {
      definitionJson = mergeSourceSnapshotDefinition(
        existing.definitionJson,
        definitionJson
      );
      definitionJson.resourceBindings = preservedBindings;
    }
    const updatePreconditions = getResourceUpdatePreconditions(
      options,
      'function',
      code,
      existing
    );
    const body = stripUndefinedValues({
      code,
      name: sourceOnlyPatch
        ? existing.name
        : functionItem.name || definitionJson.name || code,
      description: sourceOnlyPatch
        ? existing.description
        : functionItem.description !== undefined
          ? functionItem.description
          : definitionJson.description || '',
      definitionJson,
      resourceBindings: sourceOnlyPatch
        ? preservedBindings
        : definitionJson.resourceBindings,
      inputSchema: sourceOnlyPatch
        ? existing.inputSchema ?? existing.definitionJson?.inputSchema
        : functionItem.inputSchema || definitionJson.inputSchema,
      outputSchema: sourceOnlyPatch
        ? existing.outputSchema ?? existing.definitionJson?.outputSchema
        : functionItem.outputSchema || definitionJson.outputSchema,
      status: sourceOnlyPatch ? existing.status : functionItem.status,
      publishLeaseId,
      ...(existing ? {
        expectedRevision: updatePreconditions.expectedRevision,
        expectedUpdatedAt: updatePreconditions.expectedUpdatedAt,
      } : {}),
    });
    const useServerSourcePatch = Boolean(
      existing && sourceOnlyPatch && publishLeaseId
    );
    const data = useServerSourcePatch
      ? await requestWithAuth(
          config,
          target.profileName,
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions/${encodeURIComponent(code)}/source`,
          {
            method: 'PATCH',
            body: stripUndefinedValues({
              publishLeaseId,
              expectedRevision: updatePreconditions.expectedRevision,
              expectedUpdatedAt: updatePreconditions.expectedUpdatedAt,
              baseSourceHash: existing.definitionJson?.sourceFile?.sha256,
              sourceFile: definitionJson.sourceFile,
              sourceType: definitionJson.sourceType,
              runtimeMode: definitionJson.runtimeMode,
              sourceProvenance: definitionJson.sourceProvenance,
            }),
          }
        )
      : existing
        ? await requestWithAuth(
            config,
            target.profileName,
            `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions/${encodeURIComponent(code)}`,
            { method: 'POST', body }
          )
        : await requestWithAuth(
            config,
            target.profileName,
            `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions`,
            { method: 'POST', body }
          );
    if (data?.id) {
      saveFunctionResource(target, code, data.id, {
        status: data.status,
      });
    }
    result.published.push({
      kind: 'function',
      code,
      action: existing ? 'update' : 'create',
      ...(sourceOnlyPatch
        ? {
            writeMode: 'source-patch',
            sourcePatchTransport: useServerSourcePatch
              ? 'field-patch'
              : 'compat-merge',
            preservedFields: ['name', 'description', 'resourceBindings', 'inputSchema', 'outputSchema', 'status'],
          }
        : { writeMode: 'manifest-replace' }),
      id: data?.id,
    });
  }
}

