async function collectPruneResourceCandidates(config, target, manifest) {
  return withReadOnlyHttpGuard('resource prune plan', async () => {
    const candidates = [];
    const typeFilters = manifest.resourceTypeFilters
      ? new Set(manifest.resourceTypeFilters)
      : null;
    const enabled = resourceKey => !typeFilters || typeFilters.has(resourceKey);
    const append = (kind, desired, items, getCode, options = {}) => {
      for (const item of items || []) {
        const code = String(getCode(item) || '').trim();
        if (!code || desired.has(code) || options.skip?.(item)) continue;
        candidates.push({
          kind,
          code,
          id: item.id,
          ...(item.updatedAt ? { frozenUpdatedAt: item.updatedAt } : {}),
          ...(item.revision !== undefined
            ? { frozenRevision: item.revision }
            : {}),
          ...(item.version !== undefined ? { frozenVersion: item.version } : {}),
          ...(options.extra ? options.extra(item) : {}),
        });
      }
    };
    const appPath = `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}`;

    if (enabled('roles')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/roles`, { page: 1, limit: 1000 })
      );
      append('role', desiredCodes(manifest.roles), normalizeItems(data), item => item.code, {
        skip: item => Boolean(item.isAppAdmin),
      });
    }
    if (enabled('connectors')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        `${appPath}/connectors`
      );
      append(
        'connector',
        desiredCodes(manifest.connectors),
        normalizeItems(data),
        item => item.code || item.methodName
      );
    }
    if (enabled('menus')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        `${appPath}/menus`
      );
      append(
        'menu',
        desiredCodes(manifest.menus),
        flattenItems(normalizeItems(data)).reverse(),
        item => item.resourceCode
      );
    }
    if (enabled('workflows')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/workflows`, { page: 1, pageSize: 1000 })
      );
      append(
        'workflow',
        desiredCodes(manifest.workflows),
        normalizeItems(data),
        item => item.resourceCode,
        { extra: item => ({ isPublished: Boolean(item.isPublished) }) }
      );
    }
    if (enabled('automations')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/automations`, { page: 1, pageSize: 1000 })
      );
      append(
        'automation',
        desiredCodes(manifest.automations),
        normalizeItems(data),
        item => item.resourceCode,
        { extra: item => ({ isPublished: Boolean(item.isPublished) }) }
      );
    }
    if (enabled('functions')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/functions`, { page: 1, pageSize: 1000 })
      );
      append(
        'function',
        desiredCodes(manifest.functions),
        normalizeItems(data),
        item => item.code || item.functionCode || item.resourceCode
      );
    }
    if (enabled('authConfigs')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/auth/configs`, { page: 1, pageSize: 1000 })
      );
      append(
        'authConfig',
        desiredCodes(manifest.authConfigs),
        normalizeItems(data),
        item => item.code || item.resourceCode
      );
    }
    if (enabled('routes')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/routes`, { page: 1, pageSize: 1000 })
      );
      append(
        'route',
        desiredCodes(manifest.routes),
        normalizeItems(data),
        item => item.code || item.resourceCode
      );
    }
    if (enabled('dataViews')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/data-views`, { page: 1, pageSize: 1000 })
      );
      append(
        'dataView',
        desiredCodes(manifest.dataViews),
        normalizeItems(data),
        item => item.code || item.resourceCode
      );
    }
    if (enabled('storageConfigs')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/storage-configs`, { page: 1, pageSize: 1000 })
      );
      append(
        'storageConfig',
        desiredCodes(manifest.storageConfigs),
        normalizeItems(data),
        item => item.code || item.resourceCode
      );
    }
    if (enabled('publicAccessPolicies')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/public-access/policies`, {
          page: 1,
          pageSize: 1000,
        })
      );
      append(
        'publicAccessPolicy',
        desiredCodes(manifest.publicAccessPolicies),
        normalizeItems(data),
        item => item.code || item.resourceCode
      );
    }
    if (enabled('pagePermissionGroups')) {
      const data = await requestWithAuth(
        config,
        target.profileName,
        apiPathWithQuery(`${appPath}/page-permission-groups`, {
          page: 1,
          limit: 1000,
        })
      );
      append(
        'pagePermissionGroup',
        desiredCodes(manifest.pagePermissionGroups),
        normalizeItems(data),
        item => item.resourceCode
      );
    }
    if (enabled('formPermissionGroups')) {
      const forms = await requestWithAuth(
        config,
        target.profileName,
        `${appPath}/forms`
      );
      const desired = desiredCodes(manifest.formPermissionGroups);
      for (const form of normalizeItems(forms)) {
        const formUuid = form.formUuid;
        if (!formUuid) continue;
        const data = await requestWithAuth(
          config,
          target.profileName,
          apiPathWithQuery(
            `${appPath}/forms/${encodeURIComponent(formUuid)}/permission-groups`,
            { page: 1, limit: 1000 }
          )
        );
        append(
          'formPermissionGroup',
          desired,
          normalizeItems(data),
          item => item.resourceCode,
          { extra: () => ({ formUuid }) }
        );
      }
    }
    return candidates.map(item => ({ ...item, action: 'delete' }));
  });
}

function pruneCandidatesToPlanActions(candidates = []) {
  return candidates.map(item => ({
    kind: item.kind,
    code: item.code,
    action: 'delete',
    ...(item.id ? { platformId: item.id } : {}),
    ...(item.frozenRevision !== undefined
      ? { expectedRevision: item.frozenRevision }
      : {}),
    ...(item.frozenVersion !== undefined
      ? { expectedVersion: item.frozenVersion }
      : {}),
    ...(item.frozenUpdatedAt
      ? { expectedUpdatedAt: item.frozenUpdatedAt }
      : {}),
  }));
}

async function pruneResourceManifest(
  config,
  target,
  manifest,
  result,
  frozenCandidates
) {
  if (!Array.isArray(frozenCandidates)) {
    fail('resource --prune 缺少发布前冻结的精确删除清单，已拒绝边查询边删除');
  }
  for (const candidate of frozenCandidates) {
    await pruneFrozenResourceCandidate(config, target, result, candidate);
  }
}

async function pruneFrozenResourceCandidate(config, target, result, candidate) {
  const appPath = `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}`;
  const { kind, code, id } = candidate || {};
  if (!kind || !code) fail('冻结 prune target 缺少 kind/code');
  const postDelete = apiPath =>
    requestWithAuth(
      config,
      target.profileName,
      apiPathWithPostDeleteAction(apiPath),
      { method: 'POST' }
    );
  await pruneOne(config, target, result, kind, code, id, async () => {
    if (kind === 'role') {
      if (!id) fail(`冻结 prune target ${kind}:${code} 缺少 id`);
      return postDelete(`${appPath}/roles/${encodeURIComponent(id)}`);
    }
    if (kind === 'connector') {
      return postDelete(`${appPath}/connectors/${encodeURIComponent(code)}`);
    }
    if (kind === 'menu') {
      if (!id) fail(`冻结 prune target ${kind}:${code} 缺少 id`);
      return postDelete(`${appPath}/menus/${encodeURIComponent(id)}`);
    }
    if (kind === 'workflow') {
      if (!id) fail(`冻结 prune target ${kind}:${code} 缺少 id`);
      let expectedRevision = Number(candidate.frozenRevision);
      if (!Number.isSafeInteger(expectedRevision) || expectedRevision <= 0) {
        throw workflowRevisionRequiredError(`resource prune workflow ${code}`);
      }
      const changeId = workflowChangeIdFromPublishOptions(target);
      if (candidate.isPublished) {
        const unpublished = await requestWithAuth(
          config,
          target.profileName,
          `${appPath}/workflows/${encodeURIComponent(id)}/publish`,
          {
            method: 'POST',
            body: buildWorkflowMutationBody(
              changeId,
              `workflow.unpublish:${id}`,
              { isPublished: false, expectedRevision }
            ),
          }
        );
        expectedRevision = Number(unpublished?.revision);
        if (!Number.isSafeInteger(expectedRevision) || expectedRevision <= 0) {
          throw workflowRevisionRequiredError(
            `resource prune workflow ${code} delete follow-up`
          );
        }
      }
      return requestWithAuth(
        config,
        target.profileName,
        apiPathWithPostDeleteAction(
          `${appPath}/workflows/${encodeURIComponent(id)}`
        ),
        {
          method: 'POST',
          body: buildWorkflowMutationBody(
            changeId,
            `workflow.delete:${id}`,
            { expectedRevision }
          ),
        }
      );
    }
    if (kind === 'automation') {
      if (!id) fail(`冻结 prune target ${kind}:${code} 缺少 id`);
      if (candidate.isPublished) {
        await requestWithAuth(
          config,
          target.profileName,
          `${appPath}/automations/${encodeURIComponent(id)}/unpublish`,
          { method: 'POST' }
        );
      }
      return postDelete(`${appPath}/automations/${encodeURIComponent(id)}`);
    }
    if (kind === 'function') {
      return postDelete(`${appPath}/functions/${encodeURIComponent(code)}`);
    }
    if (kind === 'authConfig') {
      return postDelete(`${appPath}/auth/configs/${encodeURIComponent(code)}`);
    }
    if (kind === 'route') {
      return postDelete(`${appPath}/routes/${encodeURIComponent(code)}`);
    }
    if (kind === 'dataView') {
      return postDelete(`${appPath}/data-views/${encodeURIComponent(code)}`);
    }
    if (kind === 'storageConfig') {
      return postDelete(`${appPath}/storage-configs/${encodeURIComponent(code)}`);
    }
    if (kind === 'publicAccessPolicy') {
      return postDelete(`${appPath}/public-access/policies/${encodeURIComponent(code)}`);
    }
    if (kind === 'pagePermissionGroup') {
      if (!id) fail(`冻结 prune target ${kind}:${code} 缺少 id`);
      return postDelete(`${appPath}/page-permission-groups/${encodeURIComponent(id)}`);
    }
    if (kind === 'formPermissionGroup') {
      if (!id || !candidate.formUuid) {
        fail(`冻结 prune target ${kind}:${code} 缺少 id/formUuid`);
      }
      return postDelete(
        `${appPath}/forms/${encodeURIComponent(candidate.formUuid)}/permission-groups/${encodeURIComponent(id)}`
      );
    }
    fail(`不支持的冻结 prune target: ${kind}:${code}`);
  });
}

function desiredCodes(items = []) {
  return new Set(
    items
      .map(item => item.code || item.resourceCode || item.methodName)
      .filter(Boolean)
      .map(String)
  );
}

async function pruneRoles(config, target, desired, result) {
  const data = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`, {
      page: 1,
      limit: 1000,
    })
  );
  for (const role of normalizeItems(data)) {
    if (!role.code || desired.has(role.code) || role.isAppAdmin) continue;
    await pruneOne(config, target, result, 'role', role.code, role.id, async () => {
      await requestWithAuth(
        config,
        target.profileName,
        apiPathWithPostDeleteAction(
          `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles/${encodeURIComponent(role.id)}`
        ),
        { method: 'POST' }
      );
    });
  }
}

