async function pruneOne(config, target, result, kind, code, id, deleter) {
  try {
    await deleter();
    removeStateResource(target, kind, code);
    result.pruned.push({ kind, code, id });
  } catch (error) {
    const wrapped = new Error(
      `prune ${kind}:${code} failed: ${error?.message || String(error)}`
    );
    wrapped.code = error?.code || 'RESOURCE_PRUNE_FAILED';
    wrapped.cause = error;
    throw wrapped;
  }
}

function removeStateResource(target, kind, code) {
  const bucketByKind = {
    role: 'roles',
    connector: 'connectors',
    menu: 'menus',
    workflow: 'workflows',
    automation: 'automations',
    function: 'functions',
    authConfig: 'authConfigs',
    route: 'routes',
    publicAccessPolicy: 'publicAccessPolicies',
    dataView: 'dataViews',
    storageConfig: 'storageConfigs',
    pagePermissionGroup: 'pagePermissionGroups',
    formPermissionGroup: 'formPermissionGroups',
  };
  const bucket = bucketByKind[kind];
  if (!bucket || !target.bound.resources?.[bucket]?.[code]) return;
  delete target.bound.resources[bucket][code];
  target.bound.updatedAt = new Date().toISOString();
  if (!target.targetName && target.state.profiles?.[target.profileName]) {
    target.state.profiles[target.profileName] = target.bound;
  }
  saveProjectState(target.state);
}

async function pullResources(config, target) {
  const baseDir = path.join(process.cwd(), 'src', 'resources');
  const written = [];
  const pullLookups = buildPullResourceLookups(target.bound);
  const connectors = await requestWithAuth(
    config,
    target.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/connectors`
  );
  for (const connector of normalizeItems(connectors)) {
    const filePath = path.join(baseDir, 'connectors', `${connector.code || connector.methodName}.json`);
    writeResourceJsonFile(filePath, stripPulledResource(connector));
    written.push(path.relative(process.cwd(), filePath));
  }

  const roles = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/roles`, {
      page: 1,
      limit: 1000,
    })
  );
  for (const role of normalizeItems(roles)) {
    const filePath = path.join(baseDir, 'roles', `${role.code}.json`);
    const apiPermissions = role.id
      ? await fetchRoleApiPermissions(config, target, role.id)
      : [];
    const apiPermissionCodes = normalizePermissionCodeArray(
      apiPermissions.map(item => item.code)
    );
    writeResourceJsonFile(filePath, {
      code: role.code,
      name: role.name,
      description: role.description || '',
      ...(apiPermissionCodes.length > 0 ? { apiPermissionCodes } : {}),
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const notificationTemplates = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications/templates`, {
      page: 1,
      limit: 1000,
    })
  );
  for (const template of normalizeItems(notificationTemplates)) {
    const code = template.code || template.id;
    const filePath = path.join(baseDir, 'notifications', 'templates', `${code}.json`);
    writeResourceJsonFile(filePath, {
      templates: [toPulledNotificationTemplate(template, pullLookups)],
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const notificationTypeConfigs = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/notifications/type-configs`, {
      page: 1,
      limit: 1000,
    })
  );
  for (const configItem of normalizeItems(notificationTypeConfigs)) {
    const code = notificationTypeConfigExistingKey(configItem).replace(/[^a-zA-Z0-9_.-]+/g, '_');
    const filePath = path.join(baseDir, 'notifications', 'type-configs', `${code}.json`);
    writeResourceJsonFile(filePath, {
      typeConfigs: [toPulledNotificationTypeConfig(configItem, pullLookups)],
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const menus = await requestWithAuth(
    config,
    target.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/menus`
  );
  const flatMenus = flattenItems(normalizeItems(menus));
  for (const menu of flatMenus) {
    if (menu.id && menu.resourceCode) pullLookups.menuCodeById.set(menu.id, menu.resourceCode);
  }
  for (const menu of flatMenus) {
    const code = menu.resourceCode || menu.id;
    const filePath = path.join(baseDir, 'menus', `${code}.json`);
    const formCode = pullLookups.formCodeByUuid.get(menu.formUuid);
    const pageCode = pullLookups.pageCodeById.get(menu.pageId);
    const parentCode = pullLookups.menuCodeById.get(menu.parentId);
    writeResourceJsonFile(filePath, {
      code,
      name: menu.name,
      type: menu.type,
      ...(formCode ? { formCode } : menu.formUuid ? { formUuid: menu.formUuid } : {}),
      ...(pageCode ? { pageCode } : menu.pageId ? { pageId: menu.pageId } : {}),
      ...(parentCode ? { parentCode } : menu.parentId ? { parentId: menu.parentId } : {}),
      sortOrder: menu.sortOrder,
      icon: menu.icon || undefined,
      isHidden: menu.isHidden,
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const workflows = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const workflow of normalizeItems(workflows)) {
    const detail = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/workflows/${encodeURIComponent(workflow.id)}`
    );
    const code = detail.resourceCode || workflow.resourceCode || workflow.id;
    const filePath = path.join(baseDir, 'workflows', `${code}.json`);
    const formCode = pullLookups.formCodeByUuid.get(detail.formUuid);
    writeResourceJsonFile(filePath, {
      code,
      ...(formCode ? { formCode } : detail.formUuid ? { formUuid: detail.formUuid } : {}),
      definitionJson: detail.definitionJson,
      viewJson: detail.viewJson || undefined,
      publish: Boolean(detail.isPublished),
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const automations = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const automation of normalizeItems(automations)) {
    const detail = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/automations/${encodeURIComponent(automation.id)}`
    );
    const code = detail.resourceCode || automation.resourceCode || automation.id;
    const filePath = path.join(baseDir, 'automations', `${code}.json`);
    const formCode = pullLookups.formCodeByUuid.get(detail.formUuid);
    writeResourceJsonFile(filePath, {
      code,
      name: detail.name,
      description: detail.description || '',
      ...(formCode ? { formCode } : detail.formUuid ? { formUuid: detail.formUuid } : {}),
      triggerConfig: detail.triggerConfig,
      definitionJson: detail.definitionJson,
      viewJson: detail.viewJson || undefined,
      tags: detail.tags || undefined,
      publish: Boolean(detail.isPublished),
      enable: Boolean(detail.isEnabled),
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const functions = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const fn of normalizeItems(functions)) {
    const code = fn.code || fn.functionCode || fn.resourceCode || fn.id;
    const detail = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/functions/${encodeURIComponent(code)}`
    );
    const filePath = path.join(baseDir, 'functions', `${code}.json`);
    writeResourceJsonFile(filePath, {
      code,
      name: detail.name,
      description: detail.description || '',
      ...(Array.isArray(detail.secretRefs)
        ? { secretRefs: normalizeFunctionSecretRefs(detail.secretRefs) }
        : {}),
      definitionJson: detail.definitionJson,
      resourceBindings: detail.resourceBindings || undefined,
      inputSchema: detail.inputSchema || undefined,
      outputSchema: detail.outputSchema || undefined,
      status: detail.status || undefined,
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const authConfigs = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/auth/configs`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const item of normalizeItems(authConfigs)) {
    const code = item.code || item.resourceCode || item.id;
    const detail = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/auth/configs/${encodeURIComponent(code)}`
    );
    const filePath = path.join(baseDir, 'auth', `${code}.json`);
    writeResourceJsonFile(filePath, toPulledAuthConfig(detail));
    written.push(path.relative(process.cwd(), filePath));
  }

  const routes = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/routes`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const route of normalizeItems(routes)) {
    const code = route.code || route.resourceCode || route.id;
    const filePath = path.join(baseDir, 'routes', `${code}.json`);
    writeResourceJsonFile(filePath, toPulledRoute(route));
    written.push(path.relative(process.cwd(), filePath));
  }

  const publicAccessPolicies = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/public-access/policies`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const policy of normalizeItems(publicAccessPolicies)) {
    const code = policy.code || policy.resourceCode || policy.id;
    const filePath = path.join(baseDir, 'public-access', `${code}.json`);
    writeResourceJsonFile(filePath, toPulledPublicAccessPolicy(policy, pullLookups));
    written.push(path.relative(process.cwd(), filePath));
  }

  const dataViews = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/data-views`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const dataView of normalizeItems(dataViews)) {
    const code = dataView.code || dataView.resourceCode || dataView.id;
    const detail = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/data-views/${encodeURIComponent(code)}`
    );
    const permissionGroups = await requestOptionalWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/data-views/${encodeURIComponent(code)}/permission-groups`
    );
    const filePath = path.join(baseDir, 'data-views', `${code}.json`);
    writeResourceJsonFile(filePath, toPulledDataView(detail, permissionGroups, pullLookups));
    written.push(path.relative(process.cwd(), filePath));
  }

  const storageConfigs = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/storage-configs`, {
      page: 1,
      pageSize: 1000,
    })
  );
  for (const storageConfig of normalizeItems(storageConfigs)) {
    const code = storageConfig.code || storageConfig.resourceCode || storageConfig.id;
    const detail = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/storage-configs/${encodeURIComponent(code)}`
    );
    const filePath = path.join(baseDir, 'storage', `${code}.json`);
    writeResourceJsonFile(filePath, toPulledStorageConfig(detail));
    written.push(path.relative(process.cwd(), filePath));
  }

  const pageGroups = await requestWithAuth(
    config,
    target.profileName,
    apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/page-permission-groups`, {
      page: 1,
      limit: 1000,
    })
  );
  for (const group of normalizeItems(pageGroups)) {
    const code = group.resourceCode || group.id;
    const filePath = path.join(baseDir, 'permissions', 'page-groups', `${code}.json`);
    const targets = splitPagePermissionTargetsForManifest(group.menuFormUuids || [], pullLookups);
    writeResourceJsonFile(filePath, {
      code,
      name: group.name,
      roles: group.roles || [],
      ...targets,
      ...arrayField('menuCodes', group.menuCodes),
      ...arrayField('routeCodes', group.routeCodes),
      ...arrayField('pathPatterns', group.pathPatterns),
    });
    written.push(path.relative(process.cwd(), filePath));
  }

  const forms = await requestWithAuth(
    config,
    target.profileName,
    `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms`
  );
  const stateFormCodesByUuid = new Map(
    Object.entries(target.bound.resources?.forms || {})
      .filter(([, entry]) => entry?.formUuid)
      .map(([code, entry]) => [entry.formUuid, code])
  );
  const formEntries = normalizeItems(forms).map(form => [
    stateFormCodesByUuid.get(form.formUuid) || form.formUuid,
    { formUuid: form.formUuid },
  ]);
  for (const [formCode, formEntry] of formEntries) {
    const formUuid = formEntry?.formUuid;
    if (!formUuid) continue;
    const formGroups = await requestWithAuth(
      config,
      target.profileName,
      apiPathWithQuery(`/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/permission-groups`, {
        page: 1,
        limit: 1000,
      })
    );
    for (const group of normalizeItems(formGroups)) {
      const code = group.resourceCode || group.id;
      const filePath = path.join(baseDir, 'permissions', 'form-groups', `${code}.json`);
      const mappedFormCode = pullLookups.formCodeByUuid.get(formUuid);
      const pulledGroup = stripPulledResource(group);
      if (mappedFormCode) delete pulledGroup.formUuid;
      writeResourceJsonFile(filePath, {
        ...pulledGroup,
        code,
        ...(mappedFormCode ? { formCode: mappedFormCode } : { formUuid }),
      });
      written.push(path.relative(process.cwd(), filePath));
    }

    const mappedFormCode = pullLookups.formCodeByUuid.get(formUuid);
    const formSetting = {
      code: mappedFormCode || formCode,
      ...(mappedFormCode ? { formCode: mappedFormCode } : { formUuid }),
    };
    formSetting.settings = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/settings`
    );
    formSetting.indexes = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/field-indexes`
    );
    formSetting.dataManagement = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/data-management`
    );
    formSetting.publicAccess = await requestWithAuth(
      config,
      target.profileName,
      `/openxiangda-api/v1/apps/${encodeURIComponent(target.appType)}/forms/${encodeURIComponent(formUuid)}/public-access`
    );
    const filePath = path.join(baseDir, 'settings', 'forms', `${formCode}.json`);
    writeResourceJsonFile(filePath, formSetting);
    written.push(path.relative(process.cwd(), filePath));
  }
  return { appType: target.appType, profile: target.profileName, written };
}

function buildPullResourceLookups(bound = {}) {
  const formCodeByUuid = new Map();
  for (const [code, entry] of Object.entries(bound.resources?.forms || {})) {
    if (entry?.formUuid) formCodeByUuid.set(entry.formUuid, code);
  }

  const pageCodeById = new Map();
  for (const [code, entry] of Object.entries(bound.resources?.pages || {})) {
    if (entry?.pageId) pageCodeById.set(entry.pageId, code);
  }

  const menuCodeById = new Map();
  for (const [code, entry] of Object.entries(bound.resources?.menus || {})) {
    if (entry?.menuId) menuCodeById.set(entry.menuId, code);
  }

  return { formCodeByUuid, pageCodeById, menuCodeById };
}

function splitPagePermissionTargetsForManifest(values = [], lookups) {
  const formCodes = [];
  const menuCodes = [];
  const menuFormUuids = [];
  for (const value of values || []) {
    if (lookups.formCodeByUuid.has(value)) {
      formCodes.push(lookups.formCodeByUuid.get(value));
    } else if (lookups.menuCodeById.has(value)) {
      menuCodes.push(lookups.menuCodeById.get(value));
    } else if (value) {
      menuFormUuids.push(value);
    }
  }
  return {
    ...(formCodes.length > 0 ? { formCodes: unique(formCodes) } : {}),
    ...(menuCodes.length > 0 ? { menuCodes: unique(menuCodes) } : {}),
    ...(menuFormUuids.length > 0 ? { menuFormUuids: unique(menuFormUuids) } : {}),
  };
}

function arrayField(key, value) {
  const items = normalizePermissionCodeArray(value);
  return items.length > 0 ? { [key]: items } : {};
}

function toPulledNotificationTemplate(template, lookups) {
  const formCode = lookups.formCodeByUuid.get(template.formUuid);
  return stripUndefinedValues({
    code: template.code,
    name: template.name,
    content: template.content || '',
    description: template.description || '',
    level: template.level === 'form' ? 'form' : 'app',
    ...(formCode ? { formCode } : template.formUuid ? { formUuid: template.formUuid } : {}),
    priority: template.priority,
    enabled: template.enabled,
    variables: template.variables || undefined,
    channelsConfig: stripNotificationSecrets(template.channelsConfig),
  });
}

function toPulledNotificationTypeConfig(configItem, lookups) {
  const formCode = lookups.formCodeByUuid.get(configItem.formUuid);
  return stripUndefinedValues({
    code: notificationTypeConfigExistingKey(configItem),
    notificationType: configItem.notificationType,
    level: configItem.level === 'form' ? 'form' : 'app',
    ...(formCode ? { formCode } : configItem.formUuid ? { formUuid: configItem.formUuid } : {}),
    templateCode: configItem.template?.code,
    enabled: configItem.enabled,
    priority: configItem.priority,
    description: configItem.description || '',
  });
}

function toPulledDataView(dataView, permissionGroups, lookups) {
  const definition = rewriteDataViewDefinitionForManifest(
    clonePlainJson(dataView.definition || {}),
    lookups
  );
  const groups = normalizeItems(permissionGroups).map(group => {
    const item = stripPulledResource(group);
    delete item.dataViewCode;
    return item;
  });
  return stripUndefinedValues({
    code: dataView.code || dataView.resourceCode,
    name: dataView.name,
    description: dataView.description || '',
    storageMode: dataView.storageMode || 'materialized',
    definition,
    refreshConfig: dataView.refreshConfig || undefined,
    permissionGroups: groups.length > 0 ? groups : undefined,
  });
}

function toPulledRoute(route) {
  return stripUndefinedValues({
    code: route.code || route.resourceCode,
    title: route.title || route.name,
    kind: route.kind || 'page',
    pathPattern: route.pathPattern || route.path,
    menuCode: route.menuCode || undefined,
    publicAccess: route.publicAccess || 'none',
    publicPolicyCode: route.publicPolicyCode || route.policyCode || undefined,
    meta: route.metaJson || route.meta || undefined,
  });
}

function toPulledPublicAccessPolicy(policy, lookups) {
  return stripUndefinedValues({
    code: policy.code || policy.resourceCode,
    name: policy.name,
    description: policy.description || '',
    enabled: policy.enabled !== false,
    mode: policy.mode || 'guest',
    routeCode: policy.routeCode || undefined,
    pathPattern: policy.pathPattern || policy.path || undefined,
    externalRoleCodes: policy.externalRoleCodes || policy.externalRoles || [],
    grants: rewritePublicAccessGrantsForManifest(policy.grantsJson || policy.grants || {}, lookups),
    ticketConfig: policy.ticketConfigJson || policy.ticketConfig || undefined,
    rateLimit: policy.rateLimitJson || policy.rateLimit || undefined,
    expiresAt: policy.expiresAt || undefined,
  });
}

function rewritePublicAccessGrantsForManifest(grants, lookups) {
  const formCodes = [];
  const structuredForms = [];
  for (const entry of Array.isArray(grants.forms) ? grants.forms : []) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      const formUuid = String(entry || '').trim();
      if (formUuid) formCodes.push(lookups.formCodeByUuid.get(formUuid) || formUuid);
      continue;
    }
    const formUuid = String(entry.formUuid || '').trim();
    const code =
      lookups.formCodeByUuid.get(formUuid) ||
      String(entry.code || entry.formCode || formUuid).trim();
    structuredForms.push(
      stripUndefinedValues({
        ...clonePlainJson(entry),
        code: code || undefined,
        formUuid: lookups.formCodeByUuid.has(formUuid) ? undefined : formUuid || undefined,
      })
    );
  }
  return stripUndefinedValues({
    formCodes: formCodes.length > 0 ? unique(formCodes) : undefined,
    forms: structuredForms.length > 0 ? structuredForms : undefined,
    dataViews: normalizePermissionCodeArray(grants.dataViews),
    functions: normalizePermissionCodeArray(grants.functions),
    connectors: normalizePermissionCodeArray(grants.connectors),
    storage: normalizePublicStorageGrants(grants.storage),
  });
}

function toPulledAuthConfig(authConfig) {
  return stripUndefinedValues({
    code: authConfig.code || authConfig.resourceCode,
    name: authConfig.name,
    description: authConfig.description || '',
    status: authConfig.status || 'active',
    configJson: authConfig.configJson || authConfig.config || {},
  });
}

function toPulledStorageConfig(storageConfig) {
  return stripUndefinedValues({
    code: storageConfig.code || storageConfig.resourceCode,
    name: storageConfig.name,
    description: storageConfig.description || '',
    provider: storageConfig.provider || 'oss',
    status: storageConfig.status || 'active',
    configJson: storageConfig.configJson || storageConfig.config || {},
    credentialStatus: storageConfig.credentials || storageConfig.credentialStatus || undefined,
  });
}

function rewriteDataViewDefinitionForManifest(definition, lookups) {
  rewriteDataViewSourceForManifest(definition.base, lookups);
  for (const join of definition.joins || []) {
    rewriteDataViewSourceForManifest(join, lookups);
  }
  return definition;
}

function rewriteDataViewSourceForManifest(source, lookups) {
  if (!source || typeof source !== 'object') return;
  const formCode = lookups.formCodeByUuid.get(source.formUuid);
  if (formCode) {
    source.formCode = formCode;
    delete source.formUuid;
  }
}

function stripNotificationSecrets(value) {
  if (!value || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(stripNotificationSecrets);
  const next = {};
  for (const [key, item] of Object.entries(value)) {
    if (/token|secret|password|authorization|auth|credential|headers/i.test(key)) continue;
    next[key] = stripNotificationSecrets(item);
  }
  return next;
}

function writeResourceJsonFile(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

function stripPulledResource(value) {
  if (!value || typeof value !== 'object') return value;
  const next = { ...value };
  delete next.id;
  delete next.appType;
  delete next.createdAt;
  delete next.updatedAt;
  if (Array.isArray(next.apis)) {
    next.apis = next.apis.map(api => {
      const item = { ...api };
      delete item.id;
      delete item.connectorId;
      delete item.createdAt;
      delete item.updatedAt;
      return item;
    });
  }
  return next;
}

function normalizeConnectorManifest(connector) {
  const parsedUrl = parseConnectorUrl(connector);
  return {
    code: connector.code || connector.methodName,
    name: connector.name || connector.code || connector.methodName,
    description: connector.description || '',
    protocol: connector.protocol || parsedUrl.protocol || 'https',
    domain: connector.domain || parsedUrl.domain,
    baseUrl: connector.baseUrl !== undefined ? connector.baseUrl : parsedUrl.baseUrl,
    authType: connector.authType || 'none',
    authConfig: connector.authConfig,
    defaultHeaders: connector.defaultHeaders || connector.headers,
    userContext: connector.userContext,
    sensitiveLog: connector.sensitiveLog,
    apis: (connector.apis || []).map(api => ({
      code: api.code || api.methodName,
      name: api.name || api.code || api.methodName,
      description: api.description || '',
      path: api.path,
      method: String(api.method || 'GET').toUpperCase(),
      timeout: api.timeout,
      requestBodyType: api.requestBodyType,
      responseType: api.responseType,
      pathParams: api.pathParams || [],
      queryParams: api.queryParams || [],
      headerParams: api.headerParams || [],
      bodyParams: api.bodyParams || [],
      responseDefinition: api.responseDefinition,
    })),
  };
}

function parseConnectorUrl(connector) {
  const rawUrl = connector.url;
  if (!rawUrl) return {};
  try {
    const url = new URL(rawUrl);
    const baseUrl = url.pathname && url.pathname !== '/' ? url.pathname.replace(/^\/+|\/+$/g, '') : '';
    return {
      protocol: url.protocol.replace(':', ''),
      domain: url.host,
      baseUrl,
    };
  } catch {
    return {};
  }
}

function splitNotificationResources(items = []) {
  const templates = [];
  const typeConfigs = [];
  for (const item of items || []) {
    const resourceType = normalizeNotificationResourceType(item);
    if (resourceType === 'template') templates.push(item);
    if (resourceType === 'typeConfig') typeConfigs.push(item);
  }
  return { templates, typeConfigs };
}

function normalizeNotificationTemplateManifest(bound, template) {
  const level = template.level || (template.formCode || template.formUuid ? 'form' : 'app');
  const formUuid = level === 'form' ? resolveManifestFormUuid(bound, template) : undefined;
  return stripUndefinedValues({
    name: template.name || template.code,
    content: template.content || '',
    description: template.description || '',
    channelsConfig: resolveNotificationChannelEnvReferences(
      template.channelsConfig
    ),
    level,
    formUuid,
    priority: template.priority,
    enabled: template.enabled,
    variables: template.variables,
  });
}

function normalizeNotificationTypeConfigManifest(bound, config) {
  const level = config.level || (config.formCode || config.formUuid ? 'form' : 'app');
  const formUuid = level === 'form' ? resolveManifestFormUuid(bound, config) : undefined;
  return stripUndefinedValues({
    level,
    formUuid,
    templateId: config.templateId,
    templateCode: config.templateCode,
    enabled: config.enabled,
    priority: config.priority,
    description: config.description || '',
  });
}

function notificationTypeConfigDesiredKey(bound, config) {
  const level = config.level || (config.formCode || config.formUuid ? 'form' : 'app');
  const formUuid = level === 'form' ? resolveManifestFormUuid(bound, config) : '';
  return `${level}:${formUuid || ''}:${config.notificationType}`;
}

function notificationTypeConfigExistingKey(config) {
  const level = config.level || 'app';
  return `${level}:${config.formUuid || ''}:${config.notificationType}`;
}

function normalizeDataViewManifest(bound, dataView) {
  const definition = dataView.definition !== undefined
    ? clonePlainJson(dataView.definition)
    : clonePlainJson(withoutDataViewManifestMeta(dataView));
  if (!definition.code) definition.code = dataView.code || dataView.resourceCode;
  if (!definition.name && dataView.name) definition.name = dataView.name;
  if (definition.description === undefined && dataView.description !== undefined) {
    definition.description = dataView.description;
  }
  const normalizedDefinition = normalizeDataViewDefinitionFormRefs(bound, definition, dataView);
  const storageMode = String(dataView.storageMode || normalizedDefinition.storageMode || 'materialized').toLowerCase();
  delete normalizedDefinition.storageMode;
  return stripUndefinedValues({
    code: dataView.code || dataView.resourceCode || normalizedDefinition.code,
    name: dataView.name || normalizedDefinition.name || dataView.code || normalizedDefinition.code,
    description: dataView.description !== undefined
        ? dataView.description
        : normalizedDefinition.description || '',
    storageMode,
    definition: normalizedDefinition,
    refreshConfig: dataView.refreshConfig || dataView.refresh || normalizedDefinition.refresh,
    permissionGroups: Array.isArray(dataView.permissionGroups)
      ? dataView.permissionGroups.map(group => normalizeDataViewPermissionGroupManifest(group))
      : undefined,
  });
}

function normalizeDataViewPermissionGroupManifest(group = {}) {
  const body = stripUndefinedValues({
    ...withoutResourceMeta(group),
    operations: normalizeDataViewPermissionGroupActions(group),
  });
  delete body.actions;
  return body;
}

function normalizeRouteManifest(route) {
  const code = route.code || route.resourceCode;
  return stripUndefinedValues({
    code,
    title: route.title || route.name || code,
    kind: route.kind || 'page',
    pathPattern: route.pathPattern || route.path,
    menuCode: route.menuCode,
    publicAccess: route.publicAccess || 'none',
    publicPolicyCode: route.publicPolicyCode || route.policyCode,
    meta: route.meta || route.metaJson,
  });
}

function normalizePublicAccessPolicyManifest(bound, policy) {
  const code = policy.code || policy.resourceCode;
  return stripUndefinedValues({
    code,
    name: policy.name || policy.title || code,
    description: policy.description || '',
    enabled: policy.enabled !== false,
    mode: policy.mode || 'guest',
    routeCode: policy.routeCode,
    pathPattern: policy.pathPattern || policy.path,
    externalRoleCodes: normalizePermissionCodeArray(
      policy.externalRoleCodes || policy.externalRoles || policy.roles
    ),
    grants: normalizePublicAccessGrants(bound, policy.grants || {}),
    ticketConfig: policy.ticketConfig,
    rateLimit: policy.rateLimit,
    expiresAt: policy.expiresAt,
  });
}

function normalizeScopeDimensionManifest(dimension, bound) {
  const code = dimension.code || dimension.resourceCode;
  const sourceFormUuid =
    resolveOptionalFormUuid(bound, dimension.sourceFormCode || dimension.formCode) ||
    dimension.sourceFormUuid ||
    dimension.formUuid;
  return stripUndefinedValues({
    code,
    name: dimension.name || dimension.title || code,
    valueType: dimension.valueType || 'string',
    hierarchyMode: dimension.hierarchyMode || 'flat',
    sourceFormUuid,
    sourceValueField: dimension.sourceValueField || dimension.valueField,
    sourceLabelField: dimension.sourceLabelField || dimension.labelField,
    sourceParentField: dimension.sourceParentField || dimension.parentField,
    enabledField: dimension.enabledField,
    enabled: dimension.enabled !== false,
    configJson: dimension.configJson || dimension.config,
  });
}

function normalizeScopeGrantSourceManifest(source, bound) {
  const code = source.code || source.resourceCode;
  const sourceFormUuid =
    resolveOptionalFormUuid(bound, source.sourceFormCode || source.formCode) ||
    source.sourceFormUuid ||
    source.formUuid;
  return stripUndefinedValues({
    code,
    name: source.name || source.title || code,
    sourceFormUuid,
    subjectMappings: source.subjectMappings || source.subjects || [],
    dimensionMappings: source.dimensionMappings || source.dimensions || [],
    operationField: source.operationField,
    enabledField: source.enabledField,
    effectiveFromField: source.effectiveFromField,
    effectiveToField: source.effectiveToField,
    filterJson: source.filterJson || source.filter,
    syncMode: normalizeScopeGrantSourceSyncMode(source.syncMode, source.sync),
    enabled: source.enabled !== false,
  });
}

function normalizeScopeGrantSourceSyncMode(value, legacySync) {
  const raw = String(value || '').trim().toLowerCase();
  if (['manual', 'off', 'none', 'disabled', 'false'].includes(raw)) {
    return 'manual';
  }
  if (legacySync === false) return 'manual';
  return 'on_write';
}

function normalizeDataScopePolicyManifest(policy) {
  const code = policy.code || policy.resourceCode;
  return stripUndefinedValues({
    code,
    name: policy.name || policy.title || code,
    matchMode: policy.matchMode === 'OR' ? 'OR' : 'AND',
    rules: policy.rules || policy.dimensions || [],
    configJson: policy.configJson || policy.config,
    enabled: policy.enabled !== false,
  });
}

function normalizePublicAccessGrants(bound, grants = {}) {
  return stripUndefinedValues({
    forms: normalizePublicFormGrants(bound, grants),
    dataViews: normalizePermissionCodeArray(grants.dataViews),
    functions: normalizePermissionCodeArray(grants.functions),
    connectors: normalizePermissionCodeArray(grants.connectors),
    storage: normalizePublicStorageGrants(grants.storage),
  });
}

function normalizePublicFormGrants(bound, grants = {}) {
  const entries = [
    ...(Array.isArray(grants.forms) ? grants.forms : []),
    ...normalizePermissionCodeArray(grants.formCodes),
    ...normalizePermissionCodeArray(grants.formUuids),
  ];
  const normalized = [];
  const seen = new Set();
  for (const entry of entries) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      const identifier = String(entry || '').trim();
      const formUuid = resolveOptionalFormUuid(bound, identifier);
      if (!formUuid || seen.has(`legacy:${formUuid}`)) continue;
      seen.add(`legacy:${formUuid}`);
      normalized.push(formUuid);
      continue;
    }
    const item = clonePlainJson(entry);
    const code = String(item.code || item.formCode || '').trim();
    const formUuid = String(
      item.formUuid || resolveOptionalFormUuid(bound, code)
    ).trim();
    if (!code && !formUuid) continue;
    const actions = normalizePermissionCodeArray(item.actions).map(action =>
      action.toLowerCase()
    );
    const fields = normalizePermissionCodeArray(item.fields || item.fieldIds);
    const key = `structured:${formUuid || code}:${actions.join(',')}:${fields.join(',')}`;
    if (seen.has(key)) continue;
    seen.add(key);
    normalized.push(
      stripUndefinedValues({
        ...item,
        code: code || undefined,
        formUuid: formUuid || undefined,
        actions,
        fields: fields.length > 0 ? fields : undefined,
        fieldIds: undefined,
        upload: normalizePublicFormUploadGrant(item.upload || item.uploadPolicy),
        uploadPolicy: undefined,
      })
    );
  }
  return normalized;
}

function normalizePublicFormUploadGrant(upload) {
  if (!upload || typeof upload !== 'object' || Array.isArray(upload)) return undefined;
  const normalized = normalizePublicStorageGrants([
    { ...upload, bucketName: upload.bucketName || 'attachments', actions: ['upload'] },
  ])[0];
  if (!normalized) return undefined;
  const { actions, ...withoutActions } = normalized;
  if (!upload.bucketName) delete withoutActions.bucketName;
  return withoutActions;
}

function normalizePublicStorageGrants(storage = []) {
  if (!Array.isArray(storage)) return [];
  return storage
    .map(item => {
      const bucketName = String(item?.bucketName || '').trim();
      if (!bucketName) return null;
      return stripUndefinedValues({
        bucketName,
        actions: normalizePublicStorageActions(item.actions),
        allowedMimeTypes: normalizePermissionCodeArray(item.allowedMimeTypes).map(value =>
          value.toLowerCase()
        ),
        allowedExtensions: normalizePermissionCodeArray(item.allowedExtensions).map(value =>
          value.replace(/^\./, '').toLowerCase()
        ),
        maxSizeBytes: normalizePublicStoragePositiveInteger(item.maxSizeBytes),
        visibility: String(item.visibility || '').trim() === 'public' ? 'public' : 'private',
        pathPrefix: normalizePublicStoragePathPrefix(item.pathPrefix),
      });
    })
    .filter(Boolean);
}

function normalizePublicStorageActions(actions) {
  const allowed = new Set(['upload', 'preview', 'download']);
  const normalized = normalizePermissionCodeArray(actions).filter(action => allowed.has(action));
  return normalized.length > 0 ? unique(normalized) : ['upload'];
}

function normalizePublicStoragePositiveInteger(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric <= 0) return undefined;
  return Math.floor(numeric);
}

function normalizePublicStoragePathPrefix(value) {
  const normalized = String(value || '').trim().replace(/^\/+/, '');
  if (!normalized) return undefined;
  return normalized.endsWith('/') ? normalized : `${normalized}/`;
}

function normalizeAuthConfigManifest(authConfig) {
  const code = authConfig.code || authConfig.resourceCode || 'default';
  const configJson = clonePlainJson(
    authConfig.configJson || authConfig.config || withoutAuthConfigManifestMeta(authConfig)
  );
  return stripUndefinedValues({
    code,
    name: authConfig.name || configJson.name || code,
    description:
      authConfig.description !== undefined
        ? authConfig.description
        : configJson.description || '',
    status: authConfig.status || configJson.status || 'active',
    configJson: {
      ...configJson,
      methods: Array.isArray(configJson.methods) ? configJson.methods : [],
      registration: configJson.registration || { mode: 'reject' },
      binding: configJson.binding || { mode: 'auto' },
    },
  });
}

function normalizeStorageConfigManifest(storageConfig) {
  const code = storageConfig.code || storageConfig.resourceCode;
  const configJson = clonePlainJson(
    storageConfig.configJson ||
      storageConfig.config ||
      withoutStorageConfigManifestMeta(storageConfig)
  );
  const cors = normalizeStorageCorsForPublish(configJson.cors || storageConfig.cors);
  const credentials = normalizeStorageCredentialsForPublish(storageConfig);
  return stripUndefinedValues({
    code,
    name: storageConfig.name || configJson.name || code,
    description:
      storageConfig.description !== undefined
        ? storageConfig.description
        : configJson.description || '',
    provider: storageConfig.provider || configJson.provider || 'oss',
    status: storageConfig.status || configJson.status || 'active',
    configJson: stripUndefinedValues({
      region: configJson.region,
      bucket: configJson.bucket,
      endpoint: configJson.endpoint,
      publicBaseUrl: configJson.publicBaseUrl,
      pathPrefix: configJson.pathPrefix,
      maxFileSizeMb: configJson.maxFileSizeMb,
      allowedExtensions: configJson.allowedExtensions,
      uploadUrlExpiresSeconds: configJson.uploadUrlExpiresSeconds,
      cors,
    }),
    ...(credentials ? { credentials } : {}),
  });
}

function normalizeStorageCorsForPublish(cors) {
  if (cors === undefined || cors === null || cors === '') return undefined;
  const managed =
    cors === true ||
    cors.managed === true ||
    String(cors.managed || '').toLowerCase() === 'true';
  if (!managed) return { managed: false };
  return stripUndefinedValues({
    managed: true,
    allowedOrigins: normalizeManifestStringArray(
      cors.allowedOrigins || cors.allowedOrigin || cors.origins || cors.origin
    ),
    allowedMethods: normalizeManifestStringArray(
      cors.allowedMethods || cors.allowedMethod || ['PUT', 'GET', 'HEAD'],
      { uppercase: true }
    ),
    allowedHeaders: normalizeManifestStringArray(
      cors.allowedHeaders || cors.allowedHeader || ['content-type', 'x-oss-*']
    ),
    exposeHeaders: normalizeManifestStringArray(
      cors.exposeHeaders || cors.exposeHeader || ['ETag', 'x-oss-request-id']
    ),
    maxAgeSeconds: Number(cors.maxAgeSeconds || 600),
  });
}

function withoutStorageConfigManifestMeta(storageConfig) {
  const next = withoutResourceMeta(storageConfig);
  delete next.code;
  delete next.resourceCode;
  delete next.name;
  delete next.description;
  delete next.provider;
  delete next.status;
  delete next.cors;
  delete next.config;
  delete next.configJson;
  delete next.credentials;
  delete next.secret;
  delete next.secretJson;
  delete next.credentialStatus;
  return next;
}

function normalizeStorageCredentialsForPublish(storageConfig) {
  const source =
    storageConfig.credentials || storageConfig.secret || storageConfig.secretJson || {};
  const hasAccessKeyId = source.accessKeyId !== undefined;
  const hasAccessKeySecret = source.accessKeySecret !== undefined;
  if (!hasAccessKeyId && !hasAccessKeySecret) return null;
  return {
    accessKeyId: resolveEnvReference(source.accessKeyId, 'OSS accessKeyId'),
    accessKeySecret: resolveEnvReference(
      source.accessKeySecret,
      'OSS accessKeySecret'
    ),
  };
}

let cachedManifestEnv = null;

function getManifestEnv() {
  if (!cachedManifestEnv) {
    cachedManifestEnv = {
      ...loadGlobalEnv(),
      ...process.env,
    };
  }
  return cachedManifestEnv;
}

function isEnvReference(value) {
  return Boolean(parseEnvReferenceName(value));
}

function resolveEnvReference(value, label) {
  const envName = parseEnvReferenceName(value);
  if (!envName) fail(`${label} 必须使用环境变量引用`);
  const env = getManifestEnv();
  const resolved = env[envName];
  if (resolved === undefined || resolved === '') {
    fail(`${label} 引用的环境变量未设置: ${envName}`);
  }
  return resolved;
}

function parseEnvReferenceName(value) {
  const text = String(value || '').trim();
  const match =
    text.match(/^\$\{([A-Za-z_][A-Za-z0-9_]*)\}$/) ||
    text.match(/^\$([A-Za-z_][A-Za-z0-9_]*)$/) ||
    text.match(/^env:([A-Za-z_][A-Za-z0-9_]*)$/) ||
    text.match(/^\{\{env\.([A-Za-z_][A-Za-z0-9_]*)\}\}$/);
  return match?.[1];
}

function withoutAuthConfigManifestMeta(authConfig) {
  const next = withoutResourceMeta(authConfig);
  delete next.code;
  delete next.resourceCode;
  delete next.name;
  delete next.description;
  delete next.status;
  delete next.config;
  delete next.configJson;
  return next;
}

function withoutDataViewManifestMeta(dataView) {
  const next = withoutResourceMeta(dataView);
  delete next.permissionGroups;
  delete next.refreshConfig;
  delete next.storageMode;
  return next;
}

function normalizeDataViewDefinitionFormRefs(bound, definition, dataView) {
  if (!definition?.base) {
    fail(`${resourceLabel('dataView', dataView)} 缺少 base`);
  }
  resolveDataViewSourceFormUuid(bound, definition.base, dataView, 'base');
  for (const [index, join] of (definition.joins || []).entries()) {
    resolveDataViewSourceFormUuid(bound, join, dataView, `joins[${index}]`);
  }
  return definition;
}

function resolveDataViewSourceFormUuid(bound, source, dataView, label) {
  if (!source || typeof source !== 'object') {
    fail(`${resourceLabel('dataView', dataView)} ${label} 必须是 object`);
  }
  if (source.formUuid) {
    delete source.formCode;
    delete source.form;
    return;
  }
  const formCode = source.formCode || source.form;
  if (!formCode) {
    fail(`${resourceLabel('dataView', dataView)} ${label} 缺少 formCode 或 formUuid`);
  }
  const formUuid = bound.resources?.forms?.[formCode]?.formUuid;
  if (!formUuid) {
    fail(`${resourceLabel('dataView', dataView)} ${label}.formCode 未绑定: ${formCode}`);
  }
  source.formUuid = formUuid;
  delete source.formCode;
  delete source.form;
}

function applyResourceBindingsToRuntimeDefinition(bound, item, definitionJson) {
  if (!definitionJson || typeof definitionJson !== 'object') return definitionJson;
  const topBindings = resolveRuntimeResourceBindings(
    bound,
    item.resources || definitionJson.resources,
    item
  );
  if (!isEmptyResourceBindings(topBindings)) {
    definitionJson.resourceBindings = mergeResourceBindings(
      definitionJson.resourceBindings,
      topBindings
    );
  }
  applyNestedRuntimeResourceBindings(bound, definitionJson, item);
  return definitionJson;
}

function applyNestedRuntimeResourceBindings(bound, value, owner) {
  if (!value || typeof value !== 'object') return;
  if (Array.isArray(value)) {
    for (const item of value) applyNestedRuntimeResourceBindings(bound, item, owner);
    return;
  }
  if (value.resources && typeof value.resources === 'object') {
    const bindings = resolveRuntimeResourceBindings(bound, value.resources, owner);
    if (!isEmptyResourceBindings(bindings)) {
      value.resourceBindings = mergeResourceBindings(value.resourceBindings, bindings);
    }
  }
  for (const child of Object.values(value)) {
    if (child && typeof child === 'object') {
      applyNestedRuntimeResourceBindings(bound, child, owner);
    }
  }
}

function resolveRuntimeResourceBindings(bound, resources, item) {
  if (!resources || typeof resources !== 'object') return {};
  const label = resourceLabel('resource', item);
  const forms = {};
  for (const formCode of normalizeResourceCodeList(resources.forms)) {
    const formUuid = bound.resources?.forms?.[formCode]?.formUuid;
    if (!formUuid) {
      fail(`${label}: resources.forms 未绑定: ${formCode}`);
    }
    forms[formCode] = formUuid;
  }
  const dataViews = {};
  for (const dataViewCode of normalizeResourceCodeList(resources.dataViews)) {
    dataViews[dataViewCode] = dataViewCode;
  }
  return stripEmptyResourceBindings({ forms, dataViews });
}

function normalizeResourceCodeList(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(item => String(item || '').trim()).filter(Boolean);
  if (typeof value === 'object') return Object.keys(value).map(item => String(item || '').trim()).filter(Boolean);
  return [String(value).trim()].filter(Boolean);
}

function mergeResourceBindings(left, right) {
  return stripEmptyResourceBindings({
    ...(left || {}),
    ...(right || {}),
    forms: {
      ...((left && left.forms) || {}),
      ...((right && right.forms) || {}),
    },
    dataViews: {
      ...((left && left.dataViews) || {}),
      ...((right && right.dataViews) || {}),
    },
  });
}

function stripEmptyResourceBindings(bindings) {
  const next = { ...(bindings || {}) };
  if (!next.forms || Object.keys(next.forms).length === 0) delete next.forms;
  if (!next.dataViews || Object.keys(next.dataViews).length === 0) delete next.dataViews;
  return next;
}

function isEmptyResourceBindings(bindings) {
  return Object.keys(stripEmptyResourceBindings(bindings)).length === 0;
}

async function resolveManifestJson(
  config,
  profileName,
  item,
  objectKey,
  fileKey,
  optional = false,
  uploadCache = new Map()
) {
  let value = item[objectKey];
  if (value === undefined && item[fileKey]) {
    const filePath = path.resolve(item.__dir || process.cwd(), item[fileKey]);
    value = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  }
  if (value === undefined) {
    if (optional) return undefined;
    fail(`${resourceLabel('resource', item)} 缺少 ${objectKey} 或 ${fileKey}`);
  }
  await resolveJsCodeSnapshotFiles(
    config,
    profileName,
    value,
    item.__dir || process.cwd(),
    uploadCache
  );
  return value;
}

async function compileWorkflowSourceFile(workflowItem, options = {}) {
  if (!workflowItem.workflowFile) return undefined;
  const writeFiles = options.writeFiles !== false;
  const sourcePath = path.resolve(workflowItem.__dir || process.cwd(), workflowItem.workflowFile);
  if (!fs.existsSync(sourcePath)) {
    fail(`${resourceLabel('workflow', workflowItem)} workflowFile 不存在: ${sourcePath}`);
  }
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'openxiangda-workflow-'));
  const outfile = path.join(tmpDir, `${workflowItem.code || 'workflow'}.mjs`);
  try {
    await esbuild.build({
      entryPoints: [sourcePath],
      outfile,
      bundle: true,
      platform: 'node',
      format: 'esm',
      target: ['node18'],
      sourcemap: false,
      logLevel: 'silent',
      plugins: [openXiangdaWorkflowAliasPlugin()],
    });
    const mod = await import(`${pathToFileURL(outfile).href}?t=${Date.now()}`);
    const exported = mod.default || mod.workflow || mod.definition;
    if (!exported) {
      fail(`${resourceLabel('workflow', workflowItem)} workflowFile 必须 default export defineWorkflow(...)`);
    }
    const compiled =
      typeof exported.compile === 'function'
        ? exported.compile()
        : typeof exported === 'function'
          ? exported()
          : exported;
    if (!compiled?.definitionJson || !compiled?.previewJson) {
      fail(`${resourceLabel('workflow', workflowItem)} workflowFile 编译结果必须包含 definitionJson 和 previewJson`);
    }
    if (writeFiles && workflowItem.definitionFile) {
      writeCompiledResourceFile(workflowItem, workflowItem.definitionFile, compiled.definitionJson);
    }
    if (writeFiles && workflowItem.previewFile) {
      writeCompiledResourceFile(workflowItem, workflowItem.previewFile, compiled.previewJson);
    }
    return compiled;
  } finally {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
}

function openXiangdaWorkflowAliasPlugin() {
  return {
    name: 'openxiangda-workflow-alias',
    setup(build) {
      build.onResolve({ filter: /^openxiangda\/workflow$/ }, () => {
        const candidates = [
          path.join(__dirname, '..', 'packages', 'sdk', 'dist', 'workflow', 'index.mjs'),
          path.join(__dirname, '..', 'packages', 'sdk', 'src', 'workflow', 'index.ts'),
        ];
        const resolved = candidates.find(candidate => fs.existsSync(candidate));
        return resolved ? { path: resolved } : undefined;
      });
    },
  };
}

function writeCompiledResourceFile(item, relativeFile, value) {
  const filePath = path.resolve(item.__dir || process.cwd(), relativeFile);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

function resolveManifestFormUuid(bound, item, options = {}) {
  const formKey = item.formCode || item.form || (options.fallbackToCode ? item.code : undefined);
  if (formKey) {
    const mapped = bound.resources?.forms?.[formKey]?.formUuid;
    if (mapped) return mapped;
  }
  if (item.formUuid) return item.formUuid;
  return formKey;
}

function resolveManifestPageId(bound, item) {
  if (item.pageCode) {
    const mapped = bound.resources?.pages?.[item.pageCode]?.pageId;
    if (mapped) return mapped;
  }
  return item.pageId || item.pageCode;
}

function resolveManifestMenuId(bound, menuCode) {
  if (!menuCode) return undefined;
  return bound.resources?.menus?.[menuCode]?.menuId;
}

function menuResourceCode(menuItem) {
  return String(menuItem?.code || menuItem?.resourceCode || '').trim();
}

function menuPlatformId(menuItem) {
  const value = menuItem?.id || menuItem?.menuId;
  return value ? String(value) : undefined;
}

function resolveMenuParentId(bound, menuItem, existingMenus = new Map()) {
  const parentCode = String(menuItem?.parentCode || '').trim();
  if (!parentCode) return menuItem?.parentId || null;
  const boundId = resolveManifestMenuId(bound, parentCode);
  const onlineId = menuPlatformId(existingMenus.get(parentCode));
  return onlineId || boundId || menuItem?.parentId;
}

function menuParentResolutionError(code, parentCode, label) {
  const error = new Error(
    `MENU_PARENT_UNRESOLVED: ${label || `menu ${code}`} 无法将 parentCode ${parentCode} 解析为在线 menuId`
  );
  error.code = 'MENU_PARENT_UNRESOLVED';
  return error;
}

function requireResolvedMenuParentId(
  bound,
  menuItem,
  existingMenus = new Map(),
  label
) {
  const parentId = resolveMenuParentId(bound, menuItem, existingMenus);
  if (menuItem?.parentCode && !parentId) {
    throw menuParentResolutionError(
      menuResourceCode(menuItem),
      menuItem.parentCode,
      label
    );
  }
  return parentId || null;
}

function orderMenuResourcesForPublish(
  menus = [],
  bound = {},
  existingMenus = new Map()
) {
  const items = Array.isArray(menus) ? menus : [];
  const byCode = new Map();
  const sourceIndex = new Map();
  for (const [index, menuItem] of items.entries()) {
    const code = menuResourceCode(menuItem);
    if (!code) {
      const error = new Error('MENU_CODE_REQUIRED: menu resource 缺少 code');
      error.code = 'MENU_CODE_REQUIRED';
      throw error;
    }
    if (byCode.has(code)) {
      const error = new Error(`MENU_CODE_DUPLICATE: menu code ${code} 重复`);
      error.code = 'MENU_CODE_DUPLICATE';
      throw error;
    }
    byCode.set(code, menuItem);
    sourceIndex.set(code, index);
  }

  const children = new Map();
  const indegree = new Map([...byCode.keys()].map(code => [code, 0]));
  for (const [code, menuItem] of byCode) {
    const parentCode = String(menuItem.parentCode || '').trim();
    if (!parentCode) continue;
    if (!byCode.has(parentCode)) {
      if (!resolveMenuParentId(bound, menuItem, existingMenus)) {
        throw menuParentResolutionError(code, parentCode, `menu ${code}`);
      }
      continue;
    }
    indegree.set(code, indegree.get(code) + 1);
    const siblings = children.get(parentCode) || [];
    siblings.push(code);
    children.set(parentCode, siblings);
  }

  const bySourceOrder = (left, right) =>
    sourceIndex.get(left) - sourceIndex.get(right);
  const ready = [...indegree.entries()]
    .filter(([, count]) => count === 0)
    .map(([code]) => code)
    .sort(bySourceOrder);
  const ordered = [];
  while (ready.length > 0) {
    const code = ready.shift();
    ordered.push(byCode.get(code));
    for (const childCode of (children.get(code) || []).sort(bySourceOrder)) {
      const next = indegree.get(childCode) - 1;
      indegree.set(childCode, next);
      if (next === 0) {
        ready.push(childCode);
        ready.sort(bySourceOrder);
      }
    }
  }
  if (ordered.length !== items.length) {
    const cycleCodes = [...indegree.entries()]
      .filter(([, count]) => count > 0)
      .map(([code]) => code)
      .sort(bySourceOrder);
    const error = new Error(
      `MENU_PARENT_CYCLE: menu parentCode 存在循环依赖: ${cycleCodes.join(' -> ')}`
    );
    error.code = 'MENU_PARENT_CYCLE';
    throw error;
  }
  return ordered;
}

function resolveAutomationManifestPayload(target, automationItem) {
  const triggerConfig = {
    ...(automationItem.triggerConfig || {}),
  };
  if (!triggerConfig.appType) triggerConfig.appType = target.appType;
  const formUuid = resolveManifestFormUuid(target.bound, automationItem) || triggerConfig.formUuid;
  if (formUuid && !triggerConfig.formUuid) {
    triggerConfig.formUuid = formUuid;
  }
  return { formUuid, triggerConfig };
}

function resolvePagePermissionGroupTargets(bound, group) {
  const direct = [
    ...(Array.isArray(group.menuFormUuids) ? group.menuFormUuids : []),
    ...(Array.isArray(group.menuIds) ? group.menuIds : []),
  ];
  const fromMenus = (group.menuCodes || []).flatMap(code => resolveMenuPermissionTargets(bound, code));
  const fromForms = (group.formCodes || []).map(code => resolveOptionalFormUuid(bound, code));
  const fromPages = (group.pageCodes || []).flatMap(code => resolvePagePermissionTargets(bound, code));
  return unique([...direct, ...fromMenus, ...fromForms, ...fromPages].filter(Boolean));
}

function normalizePermissionCodeArray(value) {
  return unique(
    (Array.isArray(value) ? value : [])
      .map(item => String(item || '').trim())
      .filter(Boolean)
  );
}

function normalizeManifestStringArray(value, options = {}) {
  const source = Array.isArray(value) ? value : value === undefined || value === null ? [] : [value];
  const items = source
    .flatMap(item => String(item || '').split(','))
    .map(item => item.trim())
    .filter(Boolean)
    .map(item => options.uppercase ? item.toUpperCase() : item);
  return unique(items);
}

function saveResourceEntry(target, bucket, code, extra = {}) {
  saveStateResource(target, bucket, code, pickStateFields(extra, ['formUuid']), [
    'formUuid',
  ]);
}

function withoutResourceMeta(value) {
  const next = { ...(value || {}) };
  for (const key of Object.keys(next)) {
    if (key.startsWith('__')) delete next[key];
  }
  return next;
}

function roleEquals(desired, existing) {
  const metadataEquals =
    String(existing.name || '') === String(desired.name || desired.code || '') &&
    String(existing.description || '') === String(desired.description || '');
  if (!metadataEquals) return false;
  if (!roleDeclaresApiPermissions(desired)) return true;

  const desiredCodes = normalizePermissionCodeArray(desired.apiPermissionCodes);
  const existingCodes = normalizePermissionCodeArray(existing.apiPermissionCodes);
  return normalizeApiPermissionMode(desired) === 'replace'
    ? sameStringSet(desiredCodes, existingCodes)
    : isSubsetStringSet(desiredCodes, existingCodes);
}

function formSettingEquals(desired, existing = {}) {
  const baseDir = desired.__dir || process.cwd();
  for (const key of [
    'name',
    'schema',
    'packages',
    'formType',
    'relateUuid',
    'bundle',
  ]) {
    if (
      desired[key] !== undefined &&
      !jsonEqualsForPlan(existing[key] ?? null, desired[key] ?? null, baseDir)
    ) {
      return false;
    }
  }
  const expectedSettings = formSettingManifestSettings(desired);
  if (expectedSettings !== undefined) {
    const currentSettings = unwrapFormSettingPlanValue(
      existing.settings,
      'settings'
    );
    if (!jsonEqualsForPlan(currentSettings || {}, expectedSettings, baseDir)) {
      return false;
    }
  }
  if (desired.indexes !== undefined) {
    const currentIndexes = unwrapFormSettingPlanValue(
      existing.indexes,
      'indexes'
    );
    if (!jsonEqualsForPlan(currentIndexes || [], desired.indexes, baseDir)) {
      return false;
    }
  }
  if (desired.dataManagement !== undefined) {
    const currentConfig = unwrapFormSettingPlanValue(
      existing.dataManagement,
      'config'
    );
    if (!jsonEqualsForPlan(currentConfig || {}, desired.dataManagement, baseDir)) {
      return false;
    }
  }
  if (desired.publicAccess !== undefined) {
    const expectedPublicAccess =
      typeof desired.publicAccess === 'object'
        ? {
            isPublic: desired.publicAccess.isPublic !== false,
            description: desired.publicAccess.description || '',
          }
        : { isPublic: Boolean(desired.publicAccess), description: '' };
    const currentPublicAccess = unwrapFormSettingPlanValue(
      existing.publicAccess,
      'publicAccess'
    ) || {};
    if (
      Boolean(currentPublicAccess.isPublic) !== expectedPublicAccess.isPublic ||
      String(currentPublicAccess.description || '') !==
        expectedPublicAccess.description
    ) {
      return false;
    }
  }
  return true;
}

function unwrapFormSettingPlanValue(value, key) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    Object.prototype.hasOwnProperty.call(value, key)
  ) {
    return value[key];
  }
  return value;
}

function menuEquals(bound, desired, existing, existingMenus = new Map()) {
  if (!existing) return false;
  const desiredFormUuid = resolveManifestFormUuid(bound, desired);
  const desiredPageId = resolveManifestPageId(bound, desired);
  const desiredParentId = resolveMenuParentId(
    bound,
    desired,
    existingMenus
  );
  if (desired.parentCode && !desiredParentId) return false;
  return (
    String(existing.name || '') === String(desired.name || desired.code || '') &&
    String(existing.type || '') === String(desired.type || 'nav') &&
    String(existing.resourceCode || '') === String(desired.code || '') &&
    optionalScalarEquals(existing.formUuid, desiredFormUuid, hasAnyKey(desired, ['formCode', 'formUuid', 'form'])) &&
    optionalScalarEquals(existing.pageId, desiredPageId, hasAnyKey(desired, ['pageCode', 'pageId'])) &&
    optionalScalarEquals(existing.parentId || null, desiredParentId, hasAnyKey(desired, ['parentCode', 'parentId'])) &&
    optionalScalarEquals(existing.sortOrder, desired.sortOrder, desired.sortOrder !== undefined) &&
    optionalScalarEquals(existing.icon || null, desired.icon || null, desired.icon !== undefined) &&
    optionalScalarEquals(Boolean(existing.isHidden), Boolean(desired.isHidden), desired.isHidden !== undefined) &&
    optionalScalarEquals(existing.routeCode || null, desired.routeCode || null, desired.routeCode !== undefined) &&
    optionalScalarEquals(existing.path || null, desired.path || null, desired.path !== undefined)
  );
}

function connectorEquals(desired, existing) {
  const normalizedDesired = normalizeConnectorManifest(desired);
  const normalizedExisting = normalizeConnectorManifest(existing);
  delete normalizedExisting.appType;
  return JSON.stringify(normalizedExisting) === JSON.stringify(normalizedDesired);
}

function notificationTemplateEquals(bound, desired, existing) {
  if (!existing) return false;
  const expected = normalizeNotificationTemplateManifest(bound, desired);
  return (
    String(existing.code || '') === String(desired.code || '') &&
    String(existing.name || '') === String(expected.name || '') &&
    String(existing.content || '') === String(expected.content || '') &&
    String(existing.description || '') === String(expected.description || '') &&
    String(existing.level || 'app') === String(expected.level || 'app') &&
    String(existing.formUuid || '') === String(expected.formUuid || '') &&
    optionalScalarEquals(existing.priority, expected.priority, expected.priority !== undefined) &&
    optionalScalarEquals(Boolean(existing.enabled), Boolean(expected.enabled), expected.enabled !== undefined) &&
    jsonEqualsForPlan(existing.variables || [], expected.variables || [], desired.__dir) &&
    jsonEqualsForPlan(existing.channelsConfig || {}, expected.channelsConfig || {}, desired.__dir)
  );
}

function notificationTypeConfigEquals(bound, desired, existing) {
  if (!existing) return false;
  const expected = normalizeNotificationTypeConfigManifest(bound, desired);
  const existingTemplateCode = existing.template?.code;
  return (
    String(existing.notificationType || '') === String(desired.notificationType || '') &&
    String(existing.level || 'app') === String(expected.level || 'app') &&
    String(existing.formUuid || '') === String(expected.formUuid || '') &&
    (expected.templateId
      ? String(existing.templateId || '') === String(expected.templateId)
      : String(existingTemplateCode || '') === String(expected.templateCode || '')) &&
    optionalScalarEquals(Boolean(existing.enabled), Boolean(expected.enabled), expected.enabled !== undefined) &&
    optionalScalarEquals(existing.priority, expected.priority, expected.priority !== undefined) &&
    String(existing.description || '') === String(expected.description || '')
  );
}

function pagePermissionGroupEquals(bound, desired, existing) {
  if (!existing) return false;
  const desiredTargets = resolvePagePermissionGroupTargets(bound, desired);
  return (
    String(existing.name || '') === String(desired.name || desired.code || '') &&
    String(existing.resourceCode || '') === String(desired.code || '') &&
    stringSetEquals(existing.roles || [], desired.roles || []) &&
    stringSetEquals(existing.menuFormUuids || [], desiredTargets) &&
    stringSetEquals(existing.menuCodes || [], normalizePermissionCodeArray(desired.menuCodes)) &&
    stringSetEquals(existing.routeCodes || [], normalizePermissionCodeArray(desired.routeCodes)) &&
    stringSetEquals(existing.pathPatterns || [], normalizePermissionCodeArray(desired.pathPatterns))
  );
}

function formPermissionGroupEquals(bound, desired, existing) {
  if (!existing) return false;
  const expected = normalizeFormPermissionGroupManifest(bound, desired);
  const current = pickObjectKeys(existing, Object.keys(expected));
  return stableStringifyForPlan(current, process.cwd()) === stableStringifyForPlan(expected, desired.__dir || process.cwd());
}

function scopeDimensionEquals(bound, desired, existing) {
  if (!existing) return false;
  const expected = normalizeScopeDimensionManifest(desired, bound);
  return scopeResourceEquals(expected, existing, desired.__dir);
}

function scopeGrantSourceEquals(bound, desired, existing) {
  if (!existing) return false;
  const expected = normalizeScopeGrantSourceManifest(desired, bound);
  return scopeResourceEquals(expected, existing, desired.__dir);
}

function dataScopePolicyEquals(desired, existing) {
  if (!existing) return false;
  const expected = normalizeDataScopePolicyManifest(desired);
  return scopeResourceEquals(expected, existing, desired.__dir);
}

function scopeResourceEquals(expected, existing, baseDir) {
  const current = pickObjectKeys(existing, Object.keys(expected));
  return stableStringifyForPlan(current, process.cwd()) ===
    stableStringifyForPlan(expected, baseDir || process.cwd());
}

function normalizeFormPermissionGroupManifest(bound, group) {
  const formUuid = resolveManifestFormUuid(bound, group);
  const body = {
    ...withoutResourceMeta(group),
    resourceCode: group.code,
    formUuid,
    name: group.name || group.code,
    type: group.type || 'view',
    roles: group.roles || [],
    operations: normalizeFormPermissionGroupActions(group),
  };
  delete body.code;
  delete body.formCode;
  delete body.form;
  delete body.actions;
  return stripUndefinedValues(body);
}

function optionalScalarEquals(existingValue, desiredValue, enabled) {
  if (!enabled) return true;
  return String(existingValue ?? '') === String(desiredValue ?? '');
}

function hasAnyKey(value, keys) {
  return keys.some(key => value?.[key] !== undefined);
}

function stringSetEquals(left = [], right = []) {
  return stableStringifyForPlan(sortStringValues(left), process.cwd()) ===
    stableStringifyForPlan(sortStringValues(right), process.cwd());
}

function sortStringValues(value = []) {
  return [...(value || [])].map(item => String(item)).sort();
}

const FORM_PERMISSION_ACTIONS = new Set([
  'view',
  'create',
  'edit',
  'delete',
  'export',
  'import',
  'change_records',
  'workflow',
]);

const DATA_VIEW_PERMISSION_ACTIONS = new Set([
  'query',
  'stats',
  'export',
  'refresh',
]);

function normalizePermissionActionValue(action) {
  const value = String(action || '').trim();
  if (!value) return '';
  if (value === 'submit') return 'create';
  return value;
}

function normalizePermissionActionArray(value, allowed, fallback = []) {
  const source = Array.isArray(value) ? value : fallback;
  return unique(source.map(normalizePermissionActionValue).filter(action => allowed.has(action)));
}

function normalizeFormPermissionGroupActions(group = {}) {
  if (group.actions !== undefined || group.operations !== undefined) {
    return normalizePermissionActionArray(group.actions || group.operations, FORM_PERMISSION_ACTIONS);
  }
  return group.type === 'submit'
    ? ['create']
    : ['view', 'edit', 'delete', 'change_records', 'workflow'];
}

function normalizeDataViewPermissionGroupActions(group = {}) {
  if (group.actions !== undefined || group.operations !== undefined) {
    return normalizePermissionActionArray(group.actions || group.operations, DATA_VIEW_PERMISSION_ACTIONS);
  }
  return ['query'];
}

function pickObjectKeys(source = {}, keys = []) {
  return keys.reduce((acc, key) => {
    acc[key] = source[key];
    return acc;
  }, {});
}

function stripUndefinedValues(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  return Object.entries(value).reduce((acc, [key, item]) => {
    if (item !== undefined) acc[key] = item;
    return acc;
  }, {});
}

function clonePlainJson(value) {
  if (value === undefined) return undefined;
  return JSON.parse(JSON.stringify(value));
}

function workflowEquals(bound, desired, existing) {
  if (!existing) return false;
  const compiledWorkflow = desired.__compiledWorkflow;
  const desiredDefinition =
    compiledWorkflow?.definitionJson ||
    resolveManifestPlainJson(desired, 'definitionJson', 'definitionFile');
  const desiredView =
    compiledWorkflow?.previewJson ??
    resolveManifestPlainJson(desired, 'viewJson', 'viewFile', true) ??
    resolveManifestPlainJson(desired, 'previewJson', 'previewFile', true);
  const desiredFormUuid = resolveManifestFormUuid(bound, desired);
  return (
    String(existing.resourceCode || '') === String(desired.code || desired.resourceCode || '') &&
    String(existing.formUuid || '') === String(desiredFormUuid || '') &&
    jsonEqualsForPlan(existing.definitionJson, desiredDefinition, desired.__dir) &&
    optionalJsonEqualsForPlan(existing.viewJson, desiredView, desired.__dir) &&
    (desired.publish ? Boolean(existing.isPublished) === true : true)
  );
}

function automationEquals(target, desired, existing) {
  if (!existing) return false;
  const desiredDefinition = resolveManifestPlainJson(desired, 'definitionJson', 'definitionFile');
  applyResourceBindingsToRuntimeDefinition(target.bound, desired, desiredDefinition);
  const desiredView =
    resolveManifestPlainJson(desired, 'viewJson', 'viewFile', true) ??
    resolveManifestPlainJson(desired, 'previewJson', 'previewFile', true);
  const automationPayload = resolveAutomationManifestPayload(target, desired);
  const desiredTags =
    desired.tags === undefined
      ? undefined
      : Array.isArray(desired.tags)
        ? desired.tags.join(',')
        : String(desired.tags);
  const desiredEnabled =
    desired.enable !== undefined
      ? Boolean(desired.enable)
      : desired.isEnabled !== undefined
        ? Boolean(desired.isEnabled)
        : undefined;

  const matches = {
    resourceCode: String(existing.resourceCode || '') === String(desired.code || desired.resourceCode || ''),
    name: String(existing.name || '') === String(desired.name || desired.code || ''),
    description: String(existing.description || '') === String(desired.description || ''),
    formUuid: String(existing.formUuid || '') === String(automationPayload.formUuid || ''),
    triggerConfig: jsonEqualsForPlan(existing.triggerConfig, automationPayload.triggerConfig, desired.__dir),
    definitionJson: jsonEqualsForPlan(existing.definitionJson, desiredDefinition, desired.__dir),
    viewJson: optionalJsonEqualsForPlan(existing.viewJson, desiredView, desired.__dir),
    tags: desiredTags === undefined ? true : String(existing.tags || '') === desiredTags,
    published: desired.publish ? Boolean(existing.isPublished) === true : true,
    enabled: desiredEnabled === undefined ? true : Boolean(existing.isEnabled) === desiredEnabled,
  };
  return (
    matches.resourceCode &&
    matches.name &&
    matches.description &&
    matches.formUuid &&
    matches.triggerConfig &&
    matches.definitionJson &&
    matches.viewJson &&
    matches.tags &&
    matches.published &&
    matches.enabled
  );
}

function functionEquals(target, desired, existing) {
  if (!existing) return false;
  let desiredDefinition = resolveManifestPlainJson(desired, 'definitionJson', 'definitionFile');
  applyResourceBindingsToRuntimeDefinition(target.bound, desired, desiredDefinition);
  desiredDefinition = normalizeFunctionDefinitionJson(desired, desiredDefinition);
  const desiredStatus = desired.status === undefined ? 'active' : String(desired.status || 'active');
  const existingResourceBindings =
    existing.resourceBindings ??
    existing.resourceBindingsJson ??
    existing.definitionJson?.resourceBindings ??
    {};
  const secretRefsEqual = functionManifestDeclaresSecretRefs(desired)
    ? jsonEqualsForPlan(
        normalizeFunctionSecretRefs(
          existing.secretRefs ?? existing.secretReferences ?? []
        ),
        normalizeFunctionSecretRefs(desired.secretRefs),
        desired.__dir
      )
    : true;
  return (
    String(existing.code || existing.functionCode || existing.resourceCode || '') === String(desired.code || desired.functionCode || desired.resourceCode || '') &&
    String(existing.name || '') === String(desired.name || desiredDefinition.name || desired.code || '') &&
    String(existing.description || '') === String(
      desired.description !== undefined ? desired.description : desiredDefinition.description || ''
    ) &&
    jsonEqualsForPlan(existing.definitionJson, desiredDefinition, desired.__dir) &&
    jsonEqualsForPlan(existingResourceBindings, desiredDefinition.resourceBindings || {}, desired.__dir) &&
    String(existing.status || 'active') === desiredStatus &&
    secretRefsEqual
  );
}

function expectedResourceBindingContract(target, kind, item) {
  let definitionJson = clonePlainJson(
    resolveManifestPlainJson(
      item,
      'definitionJson',
      'definitionFile'
    )
  );
  applyResourceBindingsToRuntimeDefinition(
    target.bound,
    item,
    definitionJson
  );
  if (kind === 'Function') {
    definitionJson = normalizeFunctionDefinitionJson(item, definitionJson);
  }
  return {
    kind,
    code:
      item.code ||
      item.functionCode ||
      item.resourceCode ||
      'unknown',
    expected: normalizeResourceBindings(
      definitionJson.resourceBindings || {}
    ),
  };
}

function existingResourceBindingsForContract(existing) {
  return normalizeResourceBindings(
    existing?.resourceBindings ??
      existing?.resourceBindingsJson ??
      existing?.definitionJson?.resourceBindings ??
      {}
  );
}

function resourceBindingPlanFields(target, kind, item, existing) {
  const contract = expectedResourceBindingContract(
    target,
    kind,
    item
  );
  const expectedHash = resourceBindingContractHash([contract]);
  if (!existing) {
    return {
      resourceBindingContract: {
        contractVersion: 'resource_binding_contract_v1',
        expectedHash,
        changed: false,
      },
    };
  }
  const diff = diffResourceBindings(
    contract.expected,
    existingResourceBindingsForContract(existing)
  );
  const differences = summarizeBindingDifferences(diff);
  const manifestReplacementRequired = resourceBindingDiffViolatesPolicy(
    diff,
    'contains_expected'
  );
  return {
    resourceBindingContract: {
      contractVersion: 'resource_binding_contract_v1',
      expectedHash,
      changed: !diff.matches,
      ...(differences.length > 0 ? { differences } : {}),
    },
    ...(manifestReplacementRequired
      ? {
          manifestReplacementRequired: true,
          requiredPublishMode: 'manifest_replacement',
          manifestReplacementReasons: ['resourceBindings'],
        }
      : {}),
  };
}

function functionManifestDeclaresSecretRefs(functionItem) {
  return Boolean(
    functionItem &&
      Object.prototype.hasOwnProperty.call(functionItem, 'secretRefs')
  );
}

function normalizeFunctionSecretRefs(value) {
  if (!Array.isArray(value)) return [];
  return value
    .filter(item => item && typeof item === 'object' && !Array.isArray(item))
    .map(item => ({
      name: String(item.name || '').trim(),
      required: item.required !== false,
    }))
    .filter(item => item.name)
    .sort((left, right) => left.name.localeCompare(right.name));
}

function validateFunctionSecretRefs(label, item, errors) {
  if (!functionManifestDeclaresSecretRefs(item)) return;
  if (!Array.isArray(item.secretRefs)) {
    errors.push(`${label}: secretRefs 必须是数组`);
    return;
  }
  const names = new Set();
  for (const [index, ref] of item.secretRefs.entries()) {
    const refLabel = `${label}.secretRefs[${index}]`;
    if (!ref || typeof ref !== 'object' || Array.isArray(ref)) {
      errors.push(`${refLabel}: 必须是 {name, required} 对象`);
      continue;
    }
    const extraKeys = Object.keys(ref).filter(
      key => !['name', 'required'].includes(key)
    );
    if (extraKeys.length > 0) {
      errors.push(
        `${refLabel}: 仅允许 name/required metadata，禁止 value/file/env 等字段: ${extraKeys.join(', ')}`
      );
    }
    const name = String(ref.name || '').trim();
    if (!/^[A-Za-z][A-Za-z0-9_.-]{0,127}$/.test(name)) {
      errors.push(`${refLabel}.name: 格式无效`);
    } else if (names.has(name)) {
      errors.push(`${refLabel}.name: 重复声明 ${name}`);
    } else {
      names.add(name);
    }
    if (typeof ref.required !== 'boolean') {
      errors.push(`${refLabel}.required: 必须显式为 boolean`);
    }
  }
  let definition = item.definitionJson;
  if (!definition && item.definitionFile) {
    try {
      definition = resolveManifestPlainJson(
        item,
        'definitionJson',
        'definitionFile'
      );
    } catch (error) {
      errors.push(`${label}: 无法校验 secretRefs runtime contract: ${error.message}`);
      return;
    }
  }
  if (definition?.secretRefs !== undefined) {
    errors.push(`${label}: secretRefs 必须位于 Function resource 顶层，不能进入 definitionJson/source snapshot`);
  }
  if (String(definition?.version || '') !== 'function_v2') {
    errors.push(`${label}: 声明 secretRefs 时 definitionJson.version 必须是 function_v2`);
  }
  if (String(definition?.runtimeMode || '') !== 'trusted_node') {
    errors.push(`${label}: 声明 secretRefs 时 runtimeMode 必须是 trusted_node`);
  }
  if (
    String(definition?.runtimeContractVersion || '') !== 'trusted_node_v2'
  ) {
    errors.push(
      `${label}: 声明 secretRefs 时 runtimeContractVersion 必须是 trusted_node_v2`
    );
  }
}

function normalizeFunctionDefinitionJson(functionItem, definitionJson) {
  const definition = clonePlainJson(definitionJson || {});
  const functionCode =
    definition.functionCode ||
    functionItem.functionCode ||
    functionItem.resourceCode ||
    functionItem.code;
  return stripUndefinedValues({
    ...definition,
    kind: definition.kind || 'app_function',
    version: definition.version || 'function_v1',
    ...(functionCode ? { functionCode: String(functionCode) } : {}),
    ...(functionItem.runtimeInvoke !== undefined && definition.runtimeInvoke === undefined
      ? { runtimeInvoke: functionItem.runtimeInvoke }
      : {}),
    runtimeMode: definition.runtimeMode || 'trusted_node',
    sourceType: definition.sourceType || 'file_snapshot',
  });
}

function authConfigEquals(desired, existing) {
  if (!existing) return false;
  const expected = normalizeAuthConfigManifest(desired);
  return (
    String(existing.code || existing.resourceCode || '') === String(expected.code || '') &&
    String(existing.name || '') === String(expected.name || '') &&
    String(existing.description || '') === String(expected.description || '') &&
    String(existing.status || 'active') === String(expected.status || 'active') &&
    jsonEqualsForPlan(existing.configJson || {}, expected.configJson || {}, desired.__dir)
  );
}

function storageConfigEquals(desired, existing) {
  if (!existing) return false;
  const expected = normalizeStorageConfigManifest({
    ...desired,
    credentials: undefined,
    secret: undefined,
    secretJson: undefined,
  });
  return (
    String(existing.code || existing.resourceCode || '') === String(expected.code || '') &&
    String(existing.name || '') === String(expected.name || '') &&
    String(existing.description || '') === String(expected.description || '') &&
    String(existing.provider || 'oss') === String(expected.provider || 'oss') &&
    String(existing.status || 'active') === String(expected.status || 'active') &&
    jsonEqualsForPlan(existing.configJson || existing.config || {}, expected.configJson || {}, desired.__dir)
  );
}

function routeEquals(desired, existing) {
  if (!existing) return false;
  const expected = normalizeRouteManifest(desired);
  return (
    String(existing.code || existing.resourceCode || '') === String(expected.code || '') &&
    String(existing.title || existing.name || '') === String(expected.title || '') &&
    String(existing.kind || 'page') === String(expected.kind || 'page') &&
    String(existing.pathPattern || existing.path || '') === String(expected.pathPattern || '') &&
    String(existing.menuCode || '') === String(expected.menuCode || '') &&
    String(existing.publicAccess || 'none') === String(expected.publicAccess || 'none') &&
    String(existing.publicPolicyCode || existing.policyCode || '') === String(expected.publicPolicyCode || '') &&
    jsonEqualsForPlan(existing.metaJson || existing.meta || {}, expected.meta || {}, desired.__dir)
  );
}

function publicAccessPolicyEquals(bound, desired, existing) {
  if (!existing) return false;
  const expected = normalizePublicAccessPolicyManifest(bound, desired);
  return (
    String(existing.code || existing.resourceCode || '') === String(expected.code || '') &&
    String(existing.name || '') === String(expected.name || '') &&
    String(existing.description || '') === String(expected.description || '') &&
    Boolean(existing.enabled) === Boolean(expected.enabled) &&
    String(existing.mode || 'guest') === String(expected.mode || 'guest') &&
    String(existing.routeCode || '') === String(expected.routeCode || '') &&
    String(existing.pathPattern || '') === String(expected.pathPattern || '') &&
    stringSetEquals(existing.externalRoleCodes || [], expected.externalRoleCodes || []) &&
    jsonEqualsForPlan(
      normalizePublicAccessGrants(bound, existing.grantsJson || existing.grants || {}),
      expected.grants || {},
      desired.__dir
    ) &&
    jsonEqualsForPlan(existing.ticketConfigJson || existing.ticketConfig || {}, expected.ticketConfig || {}, desired.__dir) &&
    jsonEqualsForPlan(existing.rateLimitJson || existing.rateLimit || {}, expected.rateLimit || {}, desired.__dir) &&
    String(existing.expiresAt || '') === String(expected.expiresAt || '')
  );
}

function dataViewEquals(bound, desired, existing) {
  if (!existing) return false;
  const expected = normalizeDataViewManifest(bound, desired);
  const permissionGroupsEqual = expected.permissionGroups === undefined
    ? true
    : dataViewPermissionGroupsEqual(expected.permissionGroups, existing.permissionGroups || []);
  return (
    String(existing.code || existing.resourceCode || '') === String(expected.code || '') &&
    String(existing.name || '') === String(expected.name || '') &&
    String(existing.description || '') === String(expected.description || '') &&
    String(existing.storageMode || 'materialized') === String(expected.storageMode || 'materialized') &&
    jsonEqualsForPlan(existing.definition || {}, expected.definition || {}, desired.__dir) &&
    jsonEqualsForPlan(existing.refreshConfig || {}, expected.refreshConfig || {}, desired.__dir) &&
    permissionGroupsEqual
  );
}

function dataViewPermissionGroupsEqual(desiredGroups = [], existingGroups = []) {
  return stableStringifyForPlan(normalizeDataViewPermissionGroupsForPlan(existingGroups), process.cwd()) ===
    stableStringifyForPlan(normalizeDataViewPermissionGroupsForPlan(desiredGroups), process.cwd());
}

function normalizeDataViewPermissionGroupsForPlan(groups = []) {
  return (groups || [])
    .map(group => {
      const code = group.code || group.resourceCode || '';
      return stripUndefinedValues({
        code,
        name: group.name || code || '默认权限组',
        roles: Array.isArray(group.roles) ? sortStringValues(group.roles) : [],
        operations: sortStringValues(normalizeDataViewPermissionGroupActions(group)),
        fieldPermissions: normalizeFieldPermissionsForPlan(group.fieldPermissions),
        dataPermission: group.dataPermission || undefined,
      });
    })
    .sort((left, right) => {
      const leftKey = `${left.code || ''}:${left.name || ''}`;
      const rightKey = `${right.code || ''}:${right.name || ''}`;
      return leftKey.localeCompare(rightKey);
    });
}

function normalizeFieldPermissionsForPlan(fieldPermissions) {
  if (!Array.isArray(fieldPermissions) || !fieldPermissions.length) return undefined;
  return fieldPermissions
    .map(item => ({
      field: item.field,
      value: item.value,
    }))
    .sort((left, right) => `${left.field || ''}:${left.value || ''}`.localeCompare(`${right.field || ''}:${right.value || ''}`));
}

function resolveManifestPlainJson(item, objectKey, fileKey, optional = false) {
  if (item[objectKey] !== undefined) return item[objectKey];
  if (item[fileKey]) {
    const filePath = path.resolve(item.__dir || process.cwd(), item[fileKey]);
    try {
      return JSON.parse(fs.readFileSync(filePath, 'utf8'));
    } catch (error) {
      fail(`${resourceLabel('resource', item)} 无法读取 ${fileKey}: ${error.message}`);
    }
  }
  if (optional) return undefined;
  fail(`${resourceLabel('resource', item)} 缺少 ${objectKey} 或 ${fileKey}`);
}

function optionalJsonEqualsForPlan(existingValue, desiredValue, desiredBaseDir) {
  const normalizedExisting =
    existingValue === null || existingValue === undefined ? undefined : existingValue;
  const normalizedDesired =
    desiredValue === null || desiredValue === undefined ? undefined : desiredValue;
  return jsonEqualsForPlan(normalizedExisting, normalizedDesired, desiredBaseDir);
}

function jsonEqualsForPlan(existingValue, desiredValue, desiredBaseDir) {
  return (
    stableStringifyForPlan(existingValue, process.cwd()) ===
    stableStringifyForPlan(desiredValue, desiredBaseDir || process.cwd())
  );
}

function stableStringifyForPlan(value, baseDir) {
  const normalized = normalizeJsonForPlan(value, baseDir, null);
  const result = JSON.stringify(normalized);
  return result === undefined ? 'undefined' : result;
}

function normalizeJsonForPlan(value, baseDir, keyName) {
  if (value === undefined || value === null) return value;
  if (Array.isArray(value)) {
    return value.map(item => normalizeJsonForPlan(item, baseDir, null));
  }
  if (typeof value !== 'object') return value;

  if (keyName === 'sourceFile') {
    if (value.localPath) return normalizeLocalSourceFileForPlan(value.localPath, baseDir);
    if (value.sha256) return { sha256: value.sha256 };
  }

  const result = {};
  const hasLocalSourceFile =
    value.sourceFile && typeof value.sourceFile === 'object' && value.sourceFile.localPath;
  for (const key of Object.keys(value).sort()) {
    if (key.startsWith('__') || value[key] === undefined) continue;
    result[key] = normalizeJsonForPlan(value[key], baseDir, key);
  }
  if (hasLocalSourceFile) {
    result.code = result.code === undefined ? '' : result.code;
    result.runtimeMode = result.runtimeMode || 'trusted_node';
    result.sourceType = result.sourceType || 'file_snapshot';
    const sourceProvenance = resolveLocalSourceProvenanceForPlan(
      value.sourceFile.localPath,
      baseDir
    );
    if (sourceProvenance) {
      result.sourceProvenance = {
        ...(result.sourceProvenance || {}),
        ...sourceProvenance,
      };
    }
  }
  if (result.code === '') delete result.code;
  return sortObjectForStableJson(result);
}

function resolveLocalSourceProvenanceForPlan(localPath, baseDir) {
  const rawLocalPath = String(localPath);
  const baseResolvedPath = path.resolve(baseDir || process.cwd(), rawLocalPath);
  const cwdResolvedPath = path.resolve(process.cwd(), rawLocalPath);
  const resolvedLocalPath = fs.existsSync(baseResolvedPath)
    ? baseResolvedPath
    : cwdResolvedPath;
  const sourceInfo = getJsCodeSourceInfoForPlan(resolvedLocalPath);
  if (!sourceInfo) return null;
  return readJsCodeSourceProvenance(
    sourceInfo.workspaceRoot,
    sourceInfo.sourceKind,
    sourceInfo.scriptCode
  );
}

function normalizeLocalSourceFileForPlan(localPath, baseDir) {
  const rawLocalPath = String(localPath);
  const baseResolvedPath = path.resolve(baseDir || process.cwd(), rawLocalPath);
  const cwdResolvedPath = path.resolve(process.cwd(), rawLocalPath);
  const resolvedLocalPath = fs.existsSync(baseResolvedPath)
    ? baseResolvedPath
    : cwdResolvedPath;
  const sourceInfo = getJsCodeSourceInfoForPlan(resolvedLocalPath);
  if (sourceInfo) {
    ensureJsCodeBundleForPlan(sourceInfo);
  }
  if (sourceInfo?.bundlePath && fs.existsSync(sourceInfo.bundlePath)) {
    return {
      sha256: crypto
        .createHash('sha256')
        .update(fs.readFileSync(sourceInfo.bundlePath))
        .digest('hex'),
    };
  }
  return {
    localPath: path.relative(process.cwd(), resolvedLocalPath).replace(/\\/g, '/'),
  };
}

function resolveJsCodeBundlePathForPlan(localPath) {
  return getJsCodeSourceInfoForPlan(localPath)?.bundlePath || null;
}

function getJsCodeSourceInfoForPlan(localPath) {
  const extension = path.extname(localPath).toLowerCase();
  if (extension && extension !== '.ts' && extension !== '.tsx') return null;
  const normalized = localPath.replace(/\\/g, '/');
  const jsCodeMatched = normalized.match(/src\/js-code-nodes\/([^/]+)\/index\.tsx?$/);
  const automationMatched = normalized.match(/src\/automations\/([^/]+)\/index\.tsx?$/);
  const functionMatched = normalized.match(/src\/functions\/([^/]+)\/index\.tsx?$/);
  const matched = jsCodeMatched || automationMatched || functionMatched;
  if (!matched) return null;
  const sourceKind = functionMatched
    ? 'functions'
    : automationMatched
      ? 'automations'
      : 'js-code-nodes';
  const workspaceRoot = findWorkspaceRoot(localPath);
  const scriptCode = matched[1];
  return {
    workspaceRoot,
    sourceKind,
    scriptCode,
    entryPath: localPath,
    bundlePath: path.join(workspaceRoot, 'dist', sourceKind, scriptCode, 'index.cjs'),
  };
}

const jsCodePlanBuildCache = new Set();

function ensureJsCodeBundleForPlan(sourceInfo) {
  const cacheKey = [
    sourceInfo.workspaceRoot,
    sourceInfo.sourceKind,
    sourceInfo.scriptCode,
  ].join('\0');
  if (jsCodePlanBuildCache.has(cacheKey)) return;
  const result = runWorkspaceJsCodeBuildBatch(
    sourceInfo.workspaceRoot,
    [
      {
        sourceKind: sourceInfo.sourceKind,
        scriptCode: sourceInfo.scriptCode,
      },
    ],
    { forceCanonical: Boolean(activeDeliveryV2Context) }
  );
  if (result.stdout) process.stderr.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  if (result.status !== 0) {
    fail(`JS_CODE bundle构建失败，无法生成资源计划: ${sourceInfo.scriptCode}`);
  }
  if (!fs.existsSync(sourceInfo.bundlePath)) {
    fail(`JS_CODE bundle构建未生成产物，无法生成资源计划: ${sourceInfo.bundlePath}`);
  }
  jsCodePlanBuildCache.add(cacheKey);
}

function sortObjectForStableJson(value) {
  return Object.keys(value)
    .sort()
    .reduce((acc, key) => {
      acc[key] = value[key];
      return acc;
    }, {});
}

function printResourceValidation(validation) {
  const lines = [
    `资源目录: ${path.relative(process.cwd(), validation.baseDir) || validation.baseDir}`,
    `校验状态: ${validation.valid ? '通过' : '失败'}`,
  ];
  for (const [key, count] of Object.entries(validation.counts)) {
    lines.push(`- ${key}: ${count}`);
  }
  for (const error of validation.errors) lines.push(`Error: ${error}`);
  const warningLimit = 20;
  for (const warning of validation.warnings.slice(0, warningLimit)) {
    lines.push(`Warning: ${warning}`);
  }
  if (validation.warnings.length > warningLimit) {
    lines.push(
      `Warning: 另有 ${validation.warnings.length - warningLimit} 条 warning 未展开；使用 --json 查看完整列表`
    );
  }
  print(lines.join('\n'));
}

function printResourcePlan(plan) {
  const lines = [
    `profile: ${plan.profile}`,
    `appType: ${plan.appType}`,
    `summary: create=${plan.summary.create} update=${plan.summary.update} noop=${plan.summary.noop} delete=${plan.summary.delete}`,
  ];
  for (const action of plan.actions) {
    lines.push(`- ${action.kind}:${action.code} ${action.action}${action.platformId ? ` (${action.platformId})` : ''}`);
  }
  print(lines.join('\n'));
}

function printResourceResult(result) {
  const lines = [`profile: ${result.profile}`, `appType: ${result.appType}`];
  if (result.backendRelease) {
    lines.push(
      `backendRelease: ${result.backendRelease.id} status=${result.backendRelease.status} update=${result.backendRelease.updateCount} noop=${result.backendRelease.noopCount}`
    );
  }
  if (result.written) {
    lines.push(`written: ${result.written.length}`);
    result.written.forEach(file => lines.push(`- ${file}`));
  }
  if (result.published) {
    lines.push(`published: ${result.published.length}`);
    result.published.forEach(item => lines.push(`- ${item.kind}:${item.code} ${item.action}${item.id ? ` (${item.id})` : ''}`));
  }
  if (result.pruned) {
    lines.push(`pruned: ${result.pruned.length}`);
    result.pruned.forEach(item => lines.push(`- ${item.kind}:${item.code}${item.id ? ` (${item.id})` : ''}`));
  }
  for (const warning of result.warnings || []) lines.push(`Warning: ${warning}`);
  print(lines.join('\n'));
}

function readJsonArg(value, label) {
  return readJsonArgWithBase(value, label).data;
}

function buildDataViewQueryBody(flags = {}) {
  const explicit = flags['query-json'] || flags['params-json'] || flags['body-json'];
  if (explicit) return readJsonArg(explicit, explicit === flags['query-json'] ? 'query-json' : 'params-json');
  const body = {};
  const fields = splitList(flags.fields || flags.field);
  if (fields.length > 0) body.fields = fields;
  if (flags['filters-json']) body.filters = readJsonArg(flags['filters-json'], 'filters-json');
  if (flags['filter-json']) body.filters = readJsonArg(flags['filter-json'], 'filter-json');
  if (flags['having-json']) body.having = readJsonArg(flags['having-json'], 'having-json');
  if (flags['condition-type']) body.conditionType = String(flags['condition-type']).toUpperCase();
  if (flags.keyword || flags.search) body.searchKeyWord = flags.keyword || flags.search;
  if (flags.page) body.currentPage = Number(flags.page);
  if (flags['page-size'] || flags.limit) body.pageSize = Number(flags['page-size'] || flags.limit);
  if (flags['order-json']) {
    body.order = readJsonArg(flags['order-json'], 'order-json');
  } else if (flags['sort-field'] || flags.sort) {
    const field = flags['sort-field'] || flags.sort;
    body.order = [
      {
        field,
        isAsc:
          String(flags.desc || flags.direction || '').toLowerCase() === 'desc'
            ? 'n'
            : flags.asc === false
              ? 'n'
              : 'y',
      },
    ];
  }
  return body;
}

function readJsonArgWithBase(value, label) {
  if (!value) fail(`缺少 ${label}`);
  const raw = String(value).trim();
  try {
    if (raw.startsWith('{') || raw.startsWith('[')) {
      return { data: JSON.parse(raw), baseDir: process.cwd() };
    }
    const filePath = path.resolve(process.cwd(), raw);
    return {
      data: JSON.parse(fs.readFileSync(filePath, 'utf8')),
      baseDir: path.dirname(filePath),
    };
  } catch (error) {
    fail(`无法读取 ${label}: ${error.message}`);
  }
}

async function readDefinitionJsonArg(config, profileName, value, label) {
  const { data, baseDir } = readJsonArgWithBase(value, label);
  const uploadCache = new Map();
  await resolveJsCodeSnapshotFiles(config, profileName, data, baseDir, uploadCache);
  return data;
}

async function resolveJsCodeSnapshotFiles(config, profileName, value, baseDir, uploadCache) {
  if (!value || typeof value !== 'object') return;
  if (Array.isArray(value)) {
    for (const item of value) {
      await resolveJsCodeSnapshotFiles(config, profileName, item, baseDir, uploadCache);
    }
    return;
  }

  if (
    value.sourceFile &&
    typeof value.sourceFile === 'object' &&
    value.sourceFile.localPath
  ) {
    const snapshot = await uploadJsCodeSnapshotFile(
      config,
      profileName,
      value.sourceFile.localPath,
      baseDir,
      value.scriptCode,
      uploadCache
    );
    value.runtimeMode = value.runtimeMode || 'trusted_node';
    value.sourceType = 'file_snapshot';
    value.sourceFile = snapshot.sourceFile;
    if (snapshot.sourceProvenance) {
      value.sourceProvenance = {
        ...(value.sourceProvenance || {}),
        ...snapshot.sourceProvenance,
      };
    }
    value.code = value.code || '';
  }

  for (const child of Object.values(value)) {
    await resolveJsCodeSnapshotFiles(config, profileName, child, baseDir, uploadCache);
  }
}

async function uploadJsCodeSnapshotFile(
  config,
  profileName,
  localPath,
  baseDir,
  scriptCode,
  uploadCache
) {
  const rawLocalPath = String(localPath);
  const baseResolvedPath = path.resolve(baseDir || process.cwd(), rawLocalPath);
  const cwdResolvedPath = path.resolve(process.cwd(), rawLocalPath);
  const resolvedLocalPath = fs.existsSync(baseResolvedPath)
    ? baseResolvedPath
    : cwdResolvedPath;
  const bundlePath = await resolveJsCodeBundlePath(resolvedLocalPath, scriptCode);
  if (!fs.existsSync(bundlePath)) {
    fail(`JS_CODE bundle不存在: ${bundlePath}`);
  }
  const extension = path.extname(bundlePath).toLowerCase();
  if (!['.js', '.cjs', '.mjs'].includes(extension)) {
    fail(`JS_CODE bundle必须是 .js/.cjs/.mjs: ${bundlePath}`);
  }
  const cacheKey = bundlePath;
  if (uploadCache.has(cacheKey)) return await uploadCache.get(cacheKey);

  const buffer = fs.readFileSync(bundlePath);
  const sourceInfo = getJsCodeSourceInfoForPlan(resolvedLocalPath);
  const sourceProvenance = sourceInfo
    ? readJsCodeSourceProvenance(
        sourceInfo.workspaceRoot,
        sourceInfo.sourceKind,
        sourceInfo.scriptCode
      )
    : null;
  const pending = requestFormWithAuth(
    config,
    profileName,
    '/file/js-code-snapshot/upload',
    () => {
      const formData = new FormData();
      const blob = new Blob([buffer], { type: 'application/javascript' });
      formData.append('file', blob, path.basename(bundlePath));
      return formData;
    }
  ).then(uploaded => {
    const sourceFile = {
      bucketName: uploaded.bucketName,
      objectName: uploaded.objectName,
      sha256: uploaded.sha256,
      size: uploaded.size,
      originalName: uploaded.originalName,
      contentType: uploaded.contentType,
    };
    const snapshot = {
      sourceFile,
      ...(sourceProvenance ? { sourceProvenance } : {}),
    };
    uploadCache.set(cacheKey, snapshot);
    // Progress belongs on stderr so `--json` keeps stdout machine-readable.
    warn(`已上传JS_CODE快照: ${path.relative(process.cwd(), bundlePath)} (${sourceFile.sha256})`);
    return snapshot;
  });
  uploadCache.set(cacheKey, pending);
  try {
    return await pending;
  } catch (error) {
    if (uploadCache.get(cacheKey) === pending) uploadCache.delete(cacheKey);
    throw error;
  }
}

function readJsCodeSourceProvenance(workspaceRoot, sourceKind, scriptCode) {
  const key = `${sourceKind}/${scriptCode}`;
  for (const filename of [
    'build-cache.json',
    'build-cache.cli-v4.json',
    'build-cache.cli-v3.json',
  ]) {
    try {
      const cache = JSON.parse(
        fs.readFileSync(
          path.join(workspaceRoot, '.openxiangda', filename),
          'utf8'
        )
      );
      const metadata = cache?.targets?.[key];
      const sourceHash = String(metadata?.sourceHash || '').toLowerCase();
      if (!/^[a-f0-9]{64}$/.test(sourceHash)) continue;
      return {
        contractVersion: 'source_lineage_v1',
        sourceHash,
        entryPath: `src/${sourceKind}/${scriptCode}/index.ts`,
        dependencies: Array.isArray(metadata.dependencies)
          ? metadata.dependencies.slice().sort()
          : [],
      };
    } catch {
      // Custom workspace builders are compatible but may not emit lineage.
    }
  }
  return null;
}

async function resolveJsCodeBundlePath(localPath, scriptCode) {
  const extension = path.extname(localPath).toLowerCase();
  if (['.js', '.cjs', '.mjs'].includes(extension)) {
    fail(
      `JS_CODE V2 要求 AI 源码使用 TypeScript，请把 sourceFile.localPath 指向 src/js-code-nodes/<scriptCode>/index.ts、src/automations/<scriptCode>/index.ts 或 src/functions/<functionCode>/index.ts，而不是已构建的 ${extension} 文件: ${localPath}`
    );
  }
  if (!['.ts', '.tsx'].includes(extension)) {
    fail(
      `JS_CODE V2 sourceFile.localPath 必须指向 TypeScript 源文件 src/js-code-nodes/<scriptCode>/index.ts、src/automations/<scriptCode>/index.ts 或 src/functions/<functionCode>/index.ts: ${localPath}`
    );
  }

  const normalized = localPath.replace(/\\/g, '/');
  const jsCodeMatched = normalized.match(/src\/js-code-nodes\/([^/]+)\/index\.tsx?$/);
  const automationMatched = normalized.match(/src\/automations\/([^/]+)\/index\.tsx?$/);
  const functionMatched = normalized.match(/src\/functions\/([^/]+)\/index\.tsx?$/);
  const matched = jsCodeMatched || automationMatched || functionMatched;
  const resolvedScriptCode = scriptCode || matched?.[1];
  if (!resolvedScriptCode) {
    fail(
      `无法从 sourceFile.localPath 推断 scriptCode，请使用 src/js-code-nodes/<scriptCode>/index.ts、src/automations/<scriptCode>/index.ts 或 src/functions/<functionCode>/index.ts: ${localPath}`
    );
  }
  const sourceKind = functionMatched
    ? 'functions'
    : automationMatched
      ? 'automations'
      : 'js-code-nodes';

  const workspaceRoot = findWorkspaceRoot(localPath);
  const bundlePath = path.join(
    workspaceRoot,
    'dist',
    sourceKind,
    resolvedScriptCode,
    'index.cjs'
  );
  const cacheKey = [workspaceRoot, sourceKind, resolvedScriptCode].join('\0');
  if (jsCodePlanBuildCache.has(cacheKey) && fs.existsSync(bundlePath)) {
    return bundlePath;
  }
  const result = runWorkspaceJsCodeBuild(workspaceRoot, resolvedScriptCode, sourceKind);
  if (result.status !== 0 && sourceKind === 'functions' && isUnsupportedFunctionsBuildScript(result)) {
    warn(
      `当前工作区 scripts/build-js-code.mjs 不支持 App Function source=functions，已使用 openxiangda 内置构建器兼容构建 ${resolvedScriptCode}`
    );
    await buildFunctionSourceWithBundledEsbuild(localPath, workspaceRoot, resolvedScriptCode);
  } else if (result.status !== 0) {
    if (result.stdout) process.stderr.write(result.stdout);
    if (result.stderr) process.stderr.write(result.stderr);
    fail(`JS_CODE bundle构建失败: ${resolvedScriptCode}`);
  } else {
    if (result.stdout) process.stderr.write(result.stdout);
    if (result.stderr) process.stderr.write(result.stderr);
  }
  jsCodePlanBuildCache.add(cacheKey);
  return bundlePath;
}

function runWorkspaceJsCodeBuild(workspaceRoot, resolvedScriptCode, sourceKind) {
  return runWorkspaceJsCodeBuildBatch(
    workspaceRoot,
    [{ sourceKind, scriptCode: resolvedScriptCode }],
    { forceCanonical: Boolean(activeDeliveryV2Context) }
  );
}

function runLegacyWorkspaceJsCodeBuild(
  workspaceRoot,
  resolvedScriptCode,
  sourceKind
) {
  return spawnSync(
    'pnpm',
    [
      'build-js-code',
      '--script',
      resolvedScriptCode,
      '--source',
      sourceKind,
    ],
    {
      cwd: workspaceRoot,
      encoding: 'utf8',
    }
  );
}

function isUnsupportedFunctionsBuildScript(result) {
  const output = `${result.stdout || ''}\n${result.stderr || ''}`;
  return (
    output.includes('unsupported source: functions') ||
    output.includes('Expected js-code-nodes or automations')
  );
}

async function buildFunctionSourceWithBundledEsbuild(localPath, workspaceRoot, functionCode) {
  const outfile = path.join(workspaceRoot, 'dist', 'functions', functionCode, 'index.cjs');
  fs.mkdirSync(path.dirname(outfile), { recursive: true });
  const external = Array.from(
    new Set([...builtinModules, ...builtinModules.map(name => `node:${name}`)])
  );
  try {
    await esbuild.build({
      entryPoints: [localPath],
      outfile,
      bundle: true,
      platform: 'node',
      format: 'cjs',
      target: ['node20'],
      sourcemap: true,
      logLevel: 'silent',
      external,
      plugins: [
        {
          name: 'openxiangda-workspace-alias',
          setup(build) {
            build.onResolve({ filter: /^@\// }, args => ({
              path: resolveWorkspaceAliasPath(workspaceRoot, args.path),
            }));
          },
        },
      ],
    });
  } catch (error) {
    fail(`App Function 内置构建失败: ${functionCode}: ${error.message}`);
  }
  print(`built functions/${functionCode} -> ${path.relative(workspaceRoot, outfile)}`);
}

function resolveWorkspaceAliasPath(workspaceRoot, importPath) {
  const raw = path.join(workspaceRoot, 'src', importPath.replace(/^@\//, ''));
  const candidates = [
    raw,
    `${raw}.ts`,
    `${raw}.tsx`,
    `${raw}.js`,
    `${raw}.mjs`,
    `${raw}.cjs`,
    path.join(raw, 'index.ts'),
    path.join(raw, 'index.tsx'),
    path.join(raw, 'index.js'),
  ];
  return candidates.find(candidate => fs.existsSync(candidate)) || raw;
}

function findWorkspaceRoot(startPath) {
  if (!fs.existsSync(startPath)) {
    return process.cwd();
  }
  let dir = fs.statSync(startPath).isDirectory() ? startPath : path.dirname(startPath);
  while (dir && dir !== path.dirname(dir)) {
    const packageFile = path.join(dir, 'package.json');
    if (fs.existsSync(packageFile)) {
      try {
        const pkg = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
        if (pkg.scripts?.['build-js-code'] || pkg.name === 'sy-lowcode-app-workspace') {
          return dir;
        }
      } catch {
        return dir;
      }
    }
    dir = path.dirname(dir);
  }
  return process.cwd();
}

function apiPathWithPostDeleteAction(apiPath) {
  const value = String(apiPath || '');
  const queryIndex = value.indexOf('?');
  const base = queryIndex >= 0 ? value.slice(0, queryIndex) : value;
  const suffix = queryIndex >= 0 ? value.slice(queryIndex) : '';
  if (!base || base === '/') return '/delete' + suffix;
  if (/(^|\/)delete(\/|$)/.test(base)) return value;
  return base.replace(/\/$/, '') + '/delete' + suffix;
}

function apiPathWithQuery(apiPath, query) {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query || {})) {
    if (value === undefined || value === null || value === false || value === '') continue;
    params.set(key, String(value));
  }
  const queryString = params.toString();
  return queryString ? `${apiPath}?${queryString}` : apiPath;
}

function splitList(value) {
  if (!value) return [];
  return String(value)
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);
}

function unique(values) {
  return [...new Set(values)];
}

function renderTerminalQr(text) {
  try {
    require('qrcode-terminal').generate(text, { small: true });
  } catch {
    print('未安装 qrcode-terminal，已改为展示登录链接。');
  }
}

function unwrapApi(payload) {
  if (!payload || typeof payload !== 'object') return payload;
  if ('code' in payload && Number(payload.code) >= 400) {
    const error = new Error(payload.message || 'OpenXiangda API request failed');
    error.apiCode = Number(payload.code);
    throw error;
  }
  return 'data' in payload ? payload.data : payload;
}

function unwrapStrictApi(payload) {
  if (!payload || typeof payload !== 'object') return payload;
  if (payload.success === false) {
    const error = new Error(payload.message || payload.errorMessage || 'OpenXiangda API request failed');
    error.apiCode = payload.code;
    throw error;
  }
  if ('code' in payload) {
    const code = payload.code;
    const numericCode = Number(code);
    const normalizedCode = String(code || '').toUpperCase();
    const isOk =
      numericCode === 0 ||
      (Number.isFinite(numericCode) && numericCode >= 200 && numericCode < 300) ||
      normalizedCode === 'OK' ||
      normalizedCode === 'SUCCESS';
    if (!isOk) {
      const error = new Error(payload.message || payload.errorMessage || String(code));
      error.apiCode = code;
      throw error;
    }
  }
  return 'data' in payload ? payload.data : payload;
}

function listDirectoriesIfExists(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter(entry => entry.isDirectory())
    .map(entry => entry.name)
    .sort();
}

function normalizeWorkspaceRelativePath(value) {
  return String(value || '')
    .trim()
    .replace(/^"|"$/g, '')
    .split(path.sep)
    .join('/');
}

function parseGitStatusPath(line) {
  const raw = line.slice(3).trim();
  const renamed = raw.includes(' -> ') ? raw.split(' -> ').pop() : raw;
  return normalizeWorkspaceRelativePath(renamed);
}

function readGitNameList(args, options = {}) {
  const result = spawnSync('git', args, {
    cwd: process.cwd(),
    encoding: 'utf8',
  });
  if (result.status !== 0) {
    if (options.required) {
      fail(`git ${args.join(' ')} 失败: ${(result.stderr || result.stdout || '').trim()}`);
    }
    return [];
  }
  return result.stdout
    .split(/\r?\n/)
    .map(line => line.trimEnd())
    .filter(Boolean)
    .map(normalizeWorkspaceRelativePath)
    .filter(Boolean);
}

function getWorkspaceChangedFiles(options = {}) {
  const since = String(options.since || '').trim();
  if (since) {
    return unique([
      ...readGitNameList(
        ['diff', '--name-only', '--diff-filter=ACMRTUXB', `${since}...HEAD`],
        { required: true }
      ),
      ...readGitNameList(['diff', '--name-only', '--diff-filter=ACMRTUXB']),
      ...readGitNameList(['diff', '--name-only', '--cached', '--diff-filter=ACMRTUXB']),
      ...readGitNameList(['ls-files', '--others', '--exclude-standard']),
    ]).sort();
  }

  const result = spawnSync('git', ['status', '--short', '--untracked-files=all'], {
    cwd: process.cwd(),
    encoding: 'utf8',
  });
  if (result.status !== 0) {
    return [];
  }
  return result.stdout
    .split(/\r?\n/)
    .map(line => line.trimEnd())
    .filter(Boolean)
    .map(parseGitStatusPath)
    .filter(Boolean);
}

function getAllWorkspaceSourceFiles() {
  const files = [];
  const visit = dir => {
    if (!fs.existsSync(dir)) return;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (['node_modules', 'dist', '.vite', '.cache', 'coverage'].includes(entry.name)) continue;
      const entryPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        visit(entryPath);
        continue;
      }
      if (!entry.isFile()) continue;
      files.push(normalizeWorkspaceRelativePath(path.relative(process.cwd(), entryPath)));
    }
  };
  ['src', 'public'].forEach(item => {
    const target = path.join(process.cwd(), item);
    if (fs.existsSync(target) && fs.statSync(target).isDirectory()) {
      visit(target);
    }
  });
  return files.sort();
}

function getCandidateBuildControlFiles() {
  const files = [];
  for (const name of fs.readdirSync(process.cwd(), { withFileTypes: true })) {
    if (
      name.isFile() &&
      (
        /^(app-workspace\.config\.(ts|js|mjs|cjs)|package(-lock)?\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?|tsconfig.*\.json|vite\.config\.(ts|js|mjs|cjs)|tailwind\.config\.(ts|js|mjs|cjs)|postcss\.config\.(ts|js|mjs|cjs)|components\.json|index\.html|\.browserslistrc|browserslist|\.env(?:\.[A-Za-z0-9_-]+)*)$/.test(
          name.name
        )
      )
    ) {
      files.push(normalizeWorkspaceRelativePath(name.name));
    }
  }
  const scriptsDir = path.join(process.cwd(), 'scripts');
  if (isDirectory(scriptsDir)) {
    const visitScripts = directory => {
      for (const name of fs.readdirSync(directory, { withFileTypes: true })) {
        const absolute = path.join(directory, name.name);
        if (name.isDirectory()) {
          visitScripts(absolute);
        } else if (name.isFile()) {
          files.push(
            normalizeWorkspaceRelativePath(
              path.relative(process.cwd(), absolute)
            )
          );
        }
      }
    };
    visitScripts(scriptsDir);
  }
  return unique(files).sort();
}

function isDirectory(value) {
  try {
    return fs.statSync(value).isDirectory();
  } catch {
    return false;
  }
}

function getCandidateSourceFiles(plan) {
  const files = new Set(plan.changedFiles || []);
  for (const file of getCandidateBuildControlFiles()) files.add(file);
  if (plan.targets?.runtime) {
    for (const file of getAllWorkspaceSourceFiles()) {
      if (
        /^src\/(functions|automations|workflows|js-code-nodes|resources)\//.test(
          file
        )
      ) {
        continue;
      }
      files.add(file);
    }
  }

  const selected = Object.fromEntries(
    ['functions', 'automations', 'workflows', 'jsCodeNodes'].map(key => [
      key,
      new Set(plan.targets?.[key] || []),
    ])
  );
  const dependencyIndex = getWorkspaceSourceDependencyIndex();
  for (const target of dependencyIndex.targets || []) {
    if (!selected[target.targetKey]?.has(target.code)) continue;
    for (const file of [
      ...(target.entryFiles || []),
      ...(target.sourceDependencies || []),
    ]) {
      files.add(file);
    }
  }
  return Array.from(files)
    .map(normalizeWorkspaceRelativePath)
    .filter(Boolean)
    .sort();
}

let workspaceSourceDependencyIndexCache = null;

function getWorkspaceSourceDependencyIndex() {
  const cwd = process.cwd();
  if (workspaceSourceDependencyIndexCache?.workspaceRoot === cwd) {
    return workspaceSourceDependencyIndexCache;
  }
  workspaceSourceDependencyIndexCache = analyzeManifestSourceDependencies({
    workspaceRoot: cwd,
    manifest: loadWorkspaceResources(),
  });
  return workspaceSourceDependencyIndexCache;
}

function getWorkspaceImpactedResourceTargets(files) {
  return getImpactedResourceTargets(getWorkspaceSourceDependencyIndex(), files);
}

function scopeNeedsBackendDependencyAnalysis(scope) {
  const targets = scope?.targets || {};
  return (
    Boolean(targets.resources) ||
    ['functions', 'automations', 'workflows', 'jsCodeNodes'].some(
      key => (targets[key] || []).length > 0
    )
  );
}

function addCodeResourceTargetFromPath(targets, file, prefix, key, options = {}) {
  if (!file.startsWith(prefix)) return false;
  const rest = file.slice(prefix.length);
  const first = rest.split('/').filter(Boolean)[0] || '';
  if (prefix.startsWith('src/resources/') && first.endsWith('.json')) {
    const manifestCodes = getChangedManifestResourceCodes(
      file,
      key,
      options.baseRef || 'HEAD'
    );
    for (const manifestCode of manifestCodes) {
      if (manifestCode && manifestCode !== '_shared') targets[key].add(manifestCode);
    }
    return true;
  }
  const code = first.replace(/\.json$/i, '');
  if (code && code !== '_shared') targets[key].add(code);
  return true;
}

function getChangedManifestResourceCodes(file, resourceKey, baseRef = 'HEAD') {
  const spec = RESOURCE_SPECS.find(item => item.key === resourceKey);
  if (!spec) return [];
  const abs = path.join(process.cwd(), file);
  const currentItems = fs.existsSync(abs)
    ? readResourceItemsFromFile(abs, spec)
    : [];
  const baseItems = readResourceItemsFromGit(baseRef, file, spec);
  if (baseItems === null) {
    return unique(currentItems.map(getResourceItemCode).filter(Boolean)).sort();
  }
  const current = indexResourceItemsForDiff(currentItems);
  const base = indexResourceItemsForDiff(baseItems);
  const changed = [];
  for (const code of new Set([...current.keys(), ...base.keys()])) {
    if (current.get(code) !== base.get(code)) changed.push(code);
  }
  return changed.sort();
}

function shouldReplaceResourceManifestItem(item, resourceKey, code, options = {}) {
  return options.replaceManifest === true;
}

function resolveDeliveryV2BackendManifestReplacementIntent({
  flags = {},
  typeFilters = null,
  codeFilters = null,
  manifest = {},
  deliveryContext = activeDeliveryV2Context,
} = {}) {
  if (!deliveryContext || !flags['stage-only']) return null;
  const selectedTypes = Array.from(typeFilters || []);
  if (
    selectedTypes.length === 0 ||
    selectedTypes.some(
      type => !['functions', 'automations'].includes(type)
    )
  ) {
    return null;
  }
  if (!Array.isArray(codeFilters) || codeFilters.length === 0) {
    const error = new Error(
      'DELIVERY_BACKEND_SCOPE_MISMATCH: Delivery V2 Backend stage 缺少冻结的精确 selector'
    );
    error.code = 'DELIVERY_BACKEND_SCOPE_MISMATCH';
    error.retryable = false;
    throw error;
  }
  const expectedSelectors = unique([
    ...(deliveryContext.targets?.functions || []).map(
      code => `Function:${String(code)}`
    ),
    ...(deliveryContext.targets?.automations || []).map(
      code => `Automation:${String(code)}`
    ),
  ]).sort();
  const actualSelectors = unique([
    ...(manifest.functions || []).map(
      item => `Function:${getResourceItemCode(item)}`
    ),
    ...(manifest.automations || []).map(
      item => `Automation:${getResourceItemCode(item)}`
    ),
  ])
    .filter(selector => !selector.endsWith(':'))
    .sort();
  if (
    expectedSelectors.length === 0 ||
    JSON.stringify(actualSelectors) !== JSON.stringify(expectedSelectors)
  ) {
    const error = new Error(
      `DELIVERY_BACKEND_SCOPE_MISMATCH: Delivery V2 Backend stage 与 ReleaseRun 冻结范围不一致；expected=[${expectedSelectors.join(
        ','
      )}] actual=[${actualSelectors.join(',')}]`
    );
    error.code = 'DELIVERY_BACKEND_SCOPE_MISMATCH';
    error.retryable = false;
    error.expectedSelectors = expectedSelectors;
    error.actualSelectors = actualSelectors;
    throw error;
  }
  const runId = String(deliveryContext.runId || '').trim();
  const packageDigest = String(deliveryContext.packageDigest || '').trim();
  if (!runId || !/^[a-f0-9]{64}$/.test(packageDigest)) {
    const error = new Error(
      'DELIVERY_CONTROL_INVALID: Delivery V2 Backend stage 缺少 ReleaseRun/packageDigest 权威上下文'
    );
    error.code = 'DELIVERY_CONTROL_INVALID';
    error.retryable = false;
    throw error;
  }
  return {
    mode: 'manifest_replacement',
    authority: 'delivery_v2_sealed_package',
    runId,
    packageDigest,
    selectors: actualSelectors,
    reason:
      `Delivery V2 ReleaseRun ${runId} sealed package ${packageDigest} ` +
      'authoritative backend manifest and binding contract replacement',
  };
}

function buildAutomationSourcePatchSources(existingDefinition, desiredDefinition) {
  const existing = existingDefinition || {};
  const desired = desiredDefinition || {};
  if (desired.sourceFile && typeof desired.sourceFile === 'object') {
    return [
      stripUndefinedValues({
        baseSourceHash: existing.sourceFile?.sha256,
        sourceFile: clonePlainJson(desired.sourceFile),
        sourceType: desired.sourceType,
        runtimeMode: desired.runtimeMode,
        sourceProvenance: clonePlainJson(desired.sourceProvenance),
      }),
    ];
  }

  const existingNodes = new Map(
    (Array.isArray(existing.nodes) ? existing.nodes : [])
      .filter(node => node?.id !== undefined && node?.id !== null)
      .map(node => [String(node.id), node])
  );
  const sources = [];
  for (const desiredNode of Array.isArray(desired.nodes) ? desired.nodes : []) {
    if (desiredNode?.id === undefined || desiredNode?.id === null) continue;
    const nodeId = String(desiredNode.id);
    const desiredContainer = resolveAutomationNodeSourceContainer(desiredNode);
    if (!desiredContainer) continue;
    const existingContainer = resolveAutomationNodeSourceContainer(
      existingNodes.get(nodeId)
    );
    sources.push(
      stripUndefinedValues({
        nodeId,
        baseSourceHash: existingContainer?.sourceFile?.sha256,
        sourceFile: clonePlainJson(desiredContainer.sourceFile),
        sourceType: desiredContainer.sourceType,
        runtimeMode: desiredContainer.runtimeMode,
        sourceProvenance: clonePlainJson(desiredContainer.sourceProvenance),
      })
    );
  }
  return sources;
}

function resolveAutomationNodeSourceContainer(node) {
  if (node?.data?.sourceFile && typeof node.data.sourceFile === 'object') {
    return node.data;
  }
  if (
    node?.data?.config?.sourceFile &&
    typeof node.data.config.sourceFile === 'object'
  ) {
    return node.data.config;
  }
  return null;
}

function mergeSourceSnapshotDefinition(existingDefinition, desiredDefinition) {
  const existing = clonePlainJson(existingDefinition || {});
  const desired = clonePlainJson(desiredDefinition || {});
  const merged = { ...existing };
  for (const key of ['sourceFile', 'sourceType', 'runtimeMode']) {
    if (Object.prototype.hasOwnProperty.call(desired, key)) {
      merged[key] = clonePlainJson(desired[key]);
    }
  }
  for (const key of ['kind', 'version', 'functionCode', 'scriptCode']) {
    if (
      merged[key] === undefined &&
      Object.prototype.hasOwnProperty.call(desired, key)
    ) {
      merged[key] = clonePlainJson(desired[key]);
    }
  }
  return merged;
}

function readResourceItemsFromGit(baseRef, file, spec) {
  const result = spawnSync('git', ['show', `${baseRef}:${file}`], {
    cwd: process.cwd(),
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'ignore'],
  });
  if (result.status !== 0) return null;
  try {
    return readResourceItemsFromValue(JSON.parse(result.stdout), file, spec);
  } catch {
    return [];
  }
}

function indexResourceItemsForDiff(items) {
  const index = new Map();
  for (const item of items || []) {
    const code = getResourceItemCode(item);
    if (!code) continue;
    index.set(
      code,
      JSON.stringify(sortObjectForStableJson(withoutResourceMeta(item)))
    );
  }
  return index;
}

function isRuntimeSourceFile(file) {
  return /\.(ts|tsx|js|jsx|mjs|cjs|css|scss|sass|less|html|json|svg|png|jpe?g|gif|webp|avif|ico)$/i.test(file);
}

function resourceSpecForWorkspaceFile(file) {
  const prefix = 'src/resources/';
  if (!file.startsWith(prefix)) return null;
  const relative = file.slice(prefix.length);
  return (
    RESOURCE_SPECS.find(spec => {
      const dir = String(spec.dir || '').replace(/\\/g, '/').replace(/\/+$/, '');
      const topFiles = (spec.topFiles || []).map(item =>
        String(item).replace(/\\/g, '/')
      );
      return (
        topFiles.includes(relative) ||
        (dir && (relative === dir || relative.startsWith(`${dir}/`)))
      );
    }) || null
  );
}

function changedResourceCodesForFile(file, spec, baseRef = 'HEAD') {
  const absolute = path.join(process.cwd(), file);
  const currentItems = fs.existsSync(absolute)
    ? readResourceItemsFromFile(absolute, spec)
    : [];
  const baseItems = readResourceItemsFromGit(baseRef, file, spec) || [];
  const current = indexResourceItemsForDiff(currentItems);
  const base = indexResourceItemsForDiff(baseItems);
  const codes = unique([...current.keys(), ...base.keys()]).filter(
    code => current.get(code) !== base.get(code)
  );
  if (codes.length > 0) {
    return {
      codes: codes.sort(),
      deletedCodes: codes
        .filter(code => base.has(code) && !current.has(code))
        .sort(),
    };
  }
  if (currentItems.some(item => item?.__invalid) || baseItems.some(item => item?.__invalid)) {
    return { codes: ['*'], deletedCodes: [] };
  }
  return { codes: [], deletedCodes: [] };
}

function classifyGenericResourceFiles(files, baseRef = 'HEAD') {
  const resourceSelectors = {};
  const resourceDeletes = {};
  const formSettings = new Set();
  const unknown = new Set();
  const codeResourceKeys = new Set([
    'functions',
    'automations',
    'workflows',
  ]);
  for (const file of files || []) {
    if (!file.startsWith('src/resources/')) continue;
    const spec = resourceSpecForWorkspaceFile(file);
    if (!spec) {
      unknown.add(file);
      continue;
    }
    if (codeResourceKeys.has(spec.key)) continue;
    const diff = changedResourceCodesForFile(file, spec, baseRef);
    const codes = diff.codes;
    if (spec.key === 'formSettings') {
      for (const code of codes) formSettings.add(code);
      continue;
    }
    if (codes.length === 0) continue;
    resourceSelectors[spec.key] = unique([
      ...(resourceSelectors[spec.key] || []),
      ...codes,
    ]).sort();
    if (diff.deletedCodes.length > 0) {
      resourceDeletes[spec.key] = unique([
        ...(resourceDeletes[spec.key] || []),
        ...diff.deletedCodes,
      ]).sort();
    }
  }
  if (unknown.size > 0) {
    resourceSelectors.unknown = Array.from(unknown).sort();
  }
  return {
    formSettings: Array.from(formSettings).sort(),
    resourceSelectors,
    resourceDeletes,
  };
}

function classifyWorkspaceFiles(files, runtimeMode, options = {}) {
  const forms = new Set();
  const pages = new Set();
  const functions = new Set();
  const automations = new Set();
  const workflows = new Set();
  const jsCodeNodes = new Set();
  let resources = false;
  let runtime = false;
  const other = [];
  const codeResourceTargets = {
    functions,
    automations,
    workflows,
    jsCodeNodes,
  };
  const dependencyTargets = getWorkspaceImpactedResourceTargets(files);
  const genericTargets = classifyGenericResourceFiles(
    files,
    options.baseRef || 'HEAD'
  );
  for (const code of genericTargets.formSettings) forms.add(code);
  for (const [key, codes] of Object.entries(dependencyTargets)) {
    for (const code of codes) codeResourceTargets[key]?.add(code);
  }

  for (const file of files) {
    const formMatch = file.match(/^src\/forms\/([^/]+)/);
    if (formMatch) {
      forms.add(formMatch[1]);
      continue;
    }
    const pageMatch = file.match(/^src\/pages\/([^/]+)/);
    if (pageMatch) {
      if (runtimeMode === 'react-spa') {
        runtime = true;
      } else {
        pages.add(pageMatch[1]);
      }
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/functions/', 'functions')) {
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/automations/', 'automations')) {
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/workflows/', 'workflows')) {
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/js-code-nodes/', 'jsCodeNodes')) {
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/resources/functions/', 'functions', options)) {
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/resources/automations/', 'automations', options)) {
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/resources/workflows/', 'workflows', options)) {
      continue;
    }
    if (addCodeResourceTargetFromPath(codeResourceTargets, file, 'src/resources/js-code-nodes/', 'jsCodeNodes', options)) {
      continue;
    }
    if (file.startsWith('src/resources/')) {
      if (!resourceSpecForWorkspaceFile(file)) resources = true;
      continue;
    }
    if (
      file === 'package.json' ||
      file === 'vite.config.ts' ||
      file === 'index.html' ||
      file.startsWith('src/runtime/') ||
      (file.startsWith('src/') && isRuntimeSourceFile(file))
    ) {
      runtime = runtimeMode === 'react-spa' || runtime;
      continue;
    }
    other.push(file);
  }

  return {
    forms: Array.from(forms).sort(),
    pages: Array.from(pages).sort(),
    functions: Array.from(functions).sort(),
    automations: Array.from(automations).sort(),
    workflows: Array.from(workflows).sort(),
    jsCodeNodes: Array.from(jsCodeNodes).sort(),
    resources,
    resourceSelectors: genericTargets.resourceSelectors,
    resourceDeletes: genericTargets.resourceDeletes,
    runtime,
    other,
  };
}

function scopeIncludesCode(codes, code) {
  return (codes || []).includes('*') || (codes || []).includes(code);
}

function resourceManifestContainsScopeCode(file, resourceKey, codes) {
  if ((codes || []).includes('*')) return true;
  const spec = RESOURCE_SPECS.find(item => item.key === resourceKey);
  const abs = path.join(process.cwd(), file);
  if (!spec || !fs.existsSync(abs)) return false;
  return readResourceItemsFromFile(abs, spec).some(item =>
    scopeIncludesCode(codes, getResourceItemCode(item))
  );
}

function fileBelongsToChangeScope(file, scope, runtimeMode) {
  if ((scope.ownedFiles || []).includes(file)) return true;
  const targets = scope.targets || {};
  const formMatch = file.match(/^src\/forms\/([^/]+)/);
  if (formMatch) return scopeIncludesCode(targets.forms, formMatch[1]);
  const pageMatch = file.match(/^src\/pages\/([^/]+)/);
  if (pageMatch) return scopeIncludesCode(targets.pages, pageMatch[1]);
  const functionMatch = file.match(/^src\/functions\/([^/]+)/);
  if (functionMatch) return scopeIncludesCode(targets.functions, functionMatch[1]);
  const automationMatch = file.match(/^src\/automations\/([^/]+)/);
  if (automationMatch) return scopeIncludesCode(targets.automations, automationMatch[1]);
  const workflowMatch = file.match(/^src\/workflows\/([^/]+)/);
  if (workflowMatch) return scopeIncludesCode(targets.workflows, workflowMatch[1]);
  const jsCodeMatch = file.match(/^src\/js-code-nodes\/([^/]+)/);
  if (jsCodeMatch) return scopeIncludesCode(targets.jsCodeNodes, jsCodeMatch[1]);
  if (file.startsWith('src/resources/functions/')) {
    return resourceManifestContainsScopeCode(file, 'functions', targets.functions);
  }
  if (file.startsWith('src/resources/automations/')) {
    return resourceManifestContainsScopeCode(file, 'automations', targets.automations);
  }
  if (file.startsWith('src/resources/workflows/')) {
    return resourceManifestContainsScopeCode(file, 'workflows', targets.workflows);
  }
  if (file.startsWith('src/resources/')) return Boolean(targets.resources);
  if (
    file === 'app-workspace.config.ts' ||
    file === 'package.json' ||
    file === 'vite.config.ts' ||
    file === 'index.html' ||
    file.startsWith('src/runtime/')
  ) {
    return Boolean(targets.runtime);
  }
  if (runtimeMode === 'react-spa' && file.startsWith('src/') && isRuntimeSourceFile(file)) {
    return Boolean(targets.runtime && (scope.ownedFiles || []).includes(file));
  }
  return false;
}

function getChangeScopedWorkspaceFiles(changeScope, runtimeMode, options = {}) {
  const dirtyFiles = getWorkspaceChangedFiles({ since: options.since });
  const dependencyIndex = scopeNeedsBackendDependencyAnalysis(changeScope)
    ? getWorkspaceSourceDependencyIndex()
    : null;
  const dependencyBelongsToScope = file => {
    if (!dependencyIndex) return false;
    const impacted = getImpactedResourceTargets(dependencyIndex, [file]);
    return ['functions', 'automations', 'workflows', 'jsCodeNodes'].some(key =>
      (impacted[key] || []).some(code => scopeIncludesCode(changeScope.targets?.[key], code))
    );
  };
  return unique([
    ...unique([
      ...(changeScope.recordedChangedFiles || []),
      ...(changeScope.ownedFiles || []),
      ...dirtyFiles,
    ]).filter(file =>
      fileBelongsToChangeScope(file, changeScope, runtimeMode) || dependencyBelongsToScope(file)
    ),
  ]).sort();
}

function readWorkspaceConfigText() {
  const file = path.join(process.cwd(), 'app-workspace.config.ts');
  return fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
}

function getWorkspaceRuntimeModeFromConfig(configText) {
  return /runtimeMode\s*:\s*['"]react-spa['"]/.test(configText) ? 'react-spa' : 'legacy';
}

function getWorkspaceCompatibilityFromConfig(configText) {
  return {
    apiContracts: /apiContracts\s*:\s*['"]legacy['"]/.test(configText) ? 'legacy' : 'strict',
    legacyFallbacks: /legacyFallbacks\s*:\s*true/.test(configText),
    requestTrace: /requestTrace\s*:\s*true/.test(configText),
  };
}

const AI_RELIABILITY_RULES = [
  {
    id: 'fake-form-instance-id',
    severity: 'error',
    pattern: /inst_\$\{Date\.now\(\)\}|inst_['"]?\s*\+\s*Date\.now\(/,
    message: '禁止生成假 formInstanceId；保存接口缺少实例 ID 必须报错。',
  },
  {
    id: 'implicit-response-guessing',
    severity: 'warn',
    pattern: /response\??\.(data|result)\s*(\?\?|\|\|)\s*response\??\.(result|data)/,
    message: '避免在业务代码中猜 data/result；应使用 SDK 契约或 endpoint normalizer。',
  },
  {
    id: 'legacy-lookup-after-create',
    severity: 'warn',
    pattern: /lookupAfterCreate\s*:\s*true/,
    message: 'lookupAfterCreate 只能用于旧项目兼容；新代码保存后应显式 getDetail。',
  },
  {
    id: 'direct-openxiangda-api',
    severity: 'error',
    pattern: /fetch\s*\([^)]*openxiangda-api|axios\.[a-z]+\([^)]*openxiangda-api/,
    message: '页面代码不要直接请求 openxiangda-api；使用 Page SDK、connector 或 App Function。',
  },
  {
    id: 'mock-or-fallback-data',
    severity: 'warn',
    pattern: /\b(mockData|fallbackData|fallbackRows|demoRows)\b/,
    message: '不要用 mock/fallback 数据掩盖真实接口失败；开发态应暴露错误。',
  },
];

function scanWorkspaceReliabilityIssues(files) {
  const issues = [];
  for (const file of files) {
    if (!file.startsWith('src/')) continue;
    if (/\.(test|spec)\.(ts|tsx|js|jsx)$/.test(file)) continue;
    if (!/\.(ts|tsx|js|jsx|mjs|cjs)$/.test(file)) continue;
    const abs = path.join(process.cwd(), file);
    if (!fs.existsSync(abs) || !fs.statSync(abs).isFile()) continue;
    const content = fs.readFileSync(abs, 'utf8');
    const lines = content.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index];
      for (const rule of AI_RELIABILITY_RULES) {
        if (rule.pattern.test(line)) {
          issues.push({
            rule: rule.id,
            severity: rule.severity,
            file,
            line: index + 1,
            message: rule.message,
          });
        }
      }
    }
  }
  return issues;
}

function buildWorkspaceReleasePlan(options = {}) {
  const configText = readWorkspaceConfigText();
  const runtimeMode = getWorkspaceRuntimeModeFromConfig(configText);
  const compatibility = getWorkspaceCompatibilityFromConfig(configText);
  const changeScope = options.changeId
    ? getSddChangeScope({ cwd: process.cwd(), configText, changeId: options.changeId })
    : null;
  const files = changeScope
    ? getChangeScopedWorkspaceFiles(changeScope, runtimeMode, options)
    : options.changed
      ? getWorkspaceChangedFiles({ since: options.since })
      : getAllWorkspaceSourceFiles();
  const targets = changeScope
      ? (() => {
        const inferred = classifyWorkspaceFiles(files, runtimeMode, {
          baseRef:
            options.since ||
            changeScope.change?.sourceBase?.baseCommit ||
            'HEAD',
        });
        const explicitScopes = changeScope.scopeModelExplicit === true;
        return {
        forms: explicitScopes
          ? [...(changeScope.targets.forms || [])]
          : unique([
              ...(changeScope.targets.forms || []),
              ...(inferred.forms || []),
            ]).sort(),
        pages: [...(changeScope.targets.pages || [])],
        functions: [...(changeScope.targets.functions || [])],
        automations: [...(changeScope.targets.automations || [])],
        workflows: [...(changeScope.targets.workflows || [])],
        jsCodeNodes: [...(changeScope.targets.jsCodeNodes || [])],
        resources:
          Boolean(changeScope.targets.resources) &&
          (
            Object.keys(inferred.resourceSelectors || {}).length === 0 ||
            Boolean(inferred.resourceSelectors?.unknown?.length)
          ),
        resourceSelectors: Object.fromEntries(
          unique([
            ...Object.keys(changeScope.targets.resourceSelectors || {}),
            ...(explicitScopes
              ? []
              : Object.keys(inferred.resourceSelectors || {})),
          ]).map(key => [
            key,
            unique([
              ...(changeScope.targets.resourceSelectors?.[key] || []),
              ...(explicitScopes
                ? []
                : inferred.resourceSelectors?.[key] || []),
            ]).sort(),
          ])
        ),
        resourceDeletes: Object.fromEntries(
          Object.entries(inferred.resourceDeletes || {}).map(
            ([key, codes]) => [key, unique(codes || []).sort()]
          )
        ),
        runtime: Boolean(changeScope.targets.runtime),
        other: [...(changeScope.targets.other || [])],
        };
      })()
      : classifyWorkspaceFiles(files, runtimeMode, {
        baseRef: options.since || 'HEAD',
      });
  let dependencyImpact = {};
  const scopeDependencyErrors = [];
  if (changeScope && scopeNeedsBackendDependencyAnalysis(changeScope)) {
    const dependencyTargets = getWorkspaceImpactedResourceTargets(files);
    dependencyImpact = Object.fromEntries(
      ['functions', 'automations', 'workflows', 'jsCodeNodes'].map(key => [
        key,
        (dependencyTargets[key] || []).filter(
          code => !(targets[key] || []).includes(code)
        ),
      ])
    );
    // The approved structured scope is authoritative. Shared-source impact is
    // reported for review, but no longer silently broadens a release into
    // dozens of unrelated resources. Callers may opt in when the intended
    // change genuinely requires the whole dependency closure.
    if (options.expandDependencies) {
      for (const key of [
        'functions',
        'automations',
        'workflows',
        'jsCodeNodes',
      ]) {
        targets[key] = unique([
          ...(targets[key] || []),
          ...(dependencyTargets[key] || []),
        ]).sort();
      }
    }
    if (changeScope.scopeModelExplicit) {
      for (const key of [
        'functions',
        'automations',
        'workflows',
        'jsCodeNodes',
      ]) {
        const declared = new Set(
          changeScope.scopeModel?.runtimeDependencies?.[key] || []
        );
        const missing = (dependencyImpact[key] || []).filter(
          code => !declared.has(code)
        );
        if (missing.length > 0) {
          scopeDependencyErrors.push({
            name: 'sdd-runtime-dependencies-undeclared',
            message:
              `${key} 受共享源码影响但未写入 scopes.runtimeDependencies: ${missing.join(', ')}`,
          });
        }
      }
    }
  }
  if (options.includeResources) targets.resources = true;
  const issues = [
    ...scanWorkspaceReliabilityIssues(files),
    ...Object.entries(dependencyImpact).flatMap(([key, codes]) =>
      codes.length > 0
        ? [
            {
              rule: 'shared-source-outside-approved-scope',
              severity: 'warn',
              file: '(release scope)',
              line: 0,
              message: `${key} shared-source impact not included unless explicitly approved: ${codes.join(', ')}`,
            },
          ]
        : []
    ),
  ];
  const errors = [
    ...issues
    .filter(issue => issue.severity === 'error')
    .map(issue => ({
      name: issue.rule,
      message: `${issue.file}:${issue.line} ${issue.message}`,
    })),
    ...scopeDependencyErrors,
  ];
  const normalizedReleaseTargets = normalizeReleaseTargets(
    targets,
    runtimeMode
  );
  let generatedCommands = [];
  try {
    generatedCommands = buildWorkspaceReleaseCommands(
      targets,
      runtimeMode,
      options.profile,
      changeScope?.changeId
    );
  } catch (error) {
    if (error?.code !== 'RELEASE_ATOMIC_TARGET_UNSUPPORTED') throw error;
    errors.push({
      name: 'release-atomic-target-unsupported',
      message: error.message,
      unsupportedTargets: error.unsupportedTargets || [],
    });
  }
  const knownTargetCount =
    targets.forms.length +
    targets.pages.length +
    (targets.functions || []).length +
    (targets.automations || []).length +
    (targets.workflows || []).length +
    (targets.jsCodeNodes || []).length +
    (targets.runtime ? 1 : 0);
  const commands =
    targets.resources && knownTargetCount === 0 && changeScope?.commands?.length > 0
      ? [...changeScope.commands]
      : generatedCommands;
  if (commands.length === generatedCommands.length && targets.resources && knownTargetCount === 0) {
    errors.push({
      name: 'sdd-release-generic-resource-selector-required',
      message:
        '变更包含尚未归一化为 code 的通用资源；已保留可确定的 Function/Automation/Workflow 命令，请在 release.json.commands 中补一条精确 --only/--code 命令覆盖剩余资源。',
    });
  }
  if (
    commands.length === generatedCommands.length &&
    (targets.jsCodeNodes || []).length > 0 &&
    (targets.functions || []).length === 0 &&
    (targets.automations || []).length === 0 &&
    (targets.workflows || []).length === 0
  ) {
    errors.push({
      name: 'sdd-release-js-code-owner-required',
      message: `JS_CODE 源码尚未映射到可发布资源: ${targets.jsCodeNodes.join(', ')}；请在 coverage/release 中声明所属 Function、Automation 或 Workflow。`,
    });
  }
  const sdd = options.skipSdd
    ? null
      : buildSddGovernanceReport({
        cwd: process.cwd(),
        configText,
        targets,
        files,
        commands,
        changeId: changeScope?.changeId,
        verifyStage: options.verifyStage,
      });
  const sddErrors = sdd ? sdd.errors.map(error => ({ name: error.name, message: error.message })) : [];
  const checks = [
    {
      name: 'workspace-config',
      status: configText ? 'ok' : 'warn',
      message: configText ? undefined : '未发现 app-workspace.config.ts',
    },
    {
      name: 'api-contracts',
      status: compatibility.apiContracts === 'strict' ? 'ok' : 'warn',
      message:
        compatibility.apiContracts === 'strict'
          ? undefined
          : '当前工作区处于 legacy API 契约模式',
    },
    {
      name: 'legacy-fallbacks',
      status: compatibility.legacyFallbacks ? 'warn' : 'ok',
      message: compatibility.legacyFallbacks ? 'legacyFallbacks 已开启，可能掩盖接口/schema 问题' : undefined,
    },
    {
      name: 'ai-reliability',
      status: errors.length > 0 ? 'error' : issues.length > 0 ? 'warn' : 'ok',
      message: issues.length > 0 ? `${issues.length} 个风险项` : undefined,
    },
    ...(sdd ? sdd.checks : []),
  ];

  return {
    workspace: {
      cwd: process.cwd(),
      runtimeMode,
      configFile: path.join(process.cwd(), 'app-workspace.config.ts'),
      compatibility,
    },
    mode: changeScope ? 'change' : options.changed ? 'changed' : 'all',
    changeId: changeScope?.changeId,
    since: options.changed ? options.since || undefined : undefined,
    changedFiles: changeScope || options.changed ? files : undefined,
    targets,
    activationTargets: normalizedReleaseTargets.activationTargets,
    publishOrder:
      runtimeMode === 'react-spa'
        ? ['forms', 'resources', 'runtime']
        : ['forms/pages', 'resources'],
    commands,
    checks,
    sdd,
    issues,
    dependencyImpact,
    scopeModel: changeScope?.scopeModel || null,
    errors: [...errors, ...sddErrors],
  };
}

function printWorkspaceReleasePlan(plan) {
  const lines = [
    `OpenXiangda workspace ${plan.mode} plan`,
    ...(plan.changeId ? [`change: ${plan.changeId}`] : []),
    `runtime: ${plan.workspace.runtimeMode}`,
    `compatibility: apiContracts=${plan.workspace.compatibility.apiContracts}, legacyFallbacks=${plan.workspace.compatibility.legacyFallbacks}`,
    `forms: ${plan.targets.forms.length ? plan.targets.forms.join(', ') : '(none)'}`,
    `pages: ${plan.targets.pages.length ? plan.targets.pages.join(', ') : '(none)'}`,
    `functions: ${(plan.targets.functions || []).length ? plan.targets.functions.join(', ') : '(none)'}`,
    `automations: ${(plan.targets.automations || []).length ? plan.targets.automations.join(', ') : '(none)'}`,
    `workflows: ${(plan.targets.workflows || []).length ? plan.targets.workflows.join(', ') : '(none)'}`,
    `jsCodeNodes: ${(plan.targets.jsCodeNodes || []).length ? plan.targets.jsCodeNodes.join(', ') : '(none)'}`,
    `resources: ${plan.targets.resources ? 'yes' : 'no'}`,
    ...Object.entries(plan.targets.resourceSelectors || {}).map(
      ([type, codes]) =>
        `resource ${type}: ${codes.length ? codes.join(', ') : '(none)'}`
    ),
    `runtime deploy: ${plan.targets.runtime ? 'yes' : 'no'}`,
  ];
  if (plan.commands.length > 0) {
    lines.push('', 'Commands:', ...plan.commands.map(command => `  ${command}`));
  }
  if (plan.issues.length > 0) {
    lines.push('', 'Reliability issues:');
    for (const issue of plan.issues) {
      lines.push(`- [${issue.severity}] ${issue.file}:${issue.line} ${issue.message}`);
    }
  }
  if (plan.sdd) {
    lines.push(
      '',
      `SDD: enabled=${plan.sdd.governance.enabled ? 'true' : 'false'}, initialized=${plan.sdd.governance.initialized ? 'true' : 'false'}, strictHighRisk=${plan.sdd.governance.strictHighRisk ? 'true' : 'false'}, activeChanges=${plan.sdd.activeChanges.length}`
    );
    if (plan.sdd.highRiskFiles.length > 0) {
      lines.push(`high-risk files: ${plan.sdd.highRiskFiles.join(', ')}`);
    }
  }
  for (const check of plan.checks) {
    const suffix = check.message ? ` - ${check.message}` : '';
    lines.push(`- ${check.name}: ${check.status}${suffix}`);
  }
  print(lines.join('\n'));
}

function buildExplicitSddReleasePlan(targets, options = {}) {
  const configText = readWorkspaceConfigText();
  const commands = options.commands || [];
  const sdd = buildSddGovernanceReport({
    cwd: process.cwd(),
    configText,
    targets,
    files: options.files || [],
    commands,
    changeId: options.changeId,
    verifyStage: options.verifyStage || 'prepublish',
    actualCommands: options.actualCommands === true,
  });
  return {
    targets,
    commands,
    sdd,
    errors: sdd.errors.map(error => ({ name: error.name, message: error.message })),
  };
}

function assertSddReleaseGate(plan, flags, command) {
  if (activeDeliveryV2Context) return;
  if (!plan?.sdd || plan.sdd.errors.length === 0) return;
  const nonBypassable = new Set([
    'sdd-release-direct-form-schema-forbidden',
    'sdd-release-direct-form-activation-forbidden',
    'sdd-release-resource-scope-missing',
    'sdd-release-runtime-direct-activation-forbidden',
    'sdd-release-backend-direct-activation-forbidden',
    'sdd-release-backend-scope-inexact',
    'sdd-release-form-scope-inexact',
  ]);
  const hardFailure = plan.sdd.errors.find(error =>
    nonBypassable.has(error.name)
  );
  if (hardFailure) {
    fail(`${hardFailure.message}\n该原子发布安全门禁不可通过 --sdd-bypass 绕过。`);
  }
  if (flags['sdd-bypass']) {
    const bypass = appendBypassLog({
      cwd: process.cwd(),
      configText: readWorkspaceConfigText(),
      command,
      reason: flags.reason,
      targets: plan.targets,
      changeId: flags.change,
    });
    warn(`SDD gate 已通过 bypass 放行: ${bypass.file}`);
    return;
  }
  const first = plan.sdd.errors[0];
  fail(`${first.message}\n如为紧急修复，可使用 --sdd-bypass --reason "..." 并在发布后补齐 SDD 归档。`);
}

function buildWorkspacePublishSddPlan(publishOptions, runtimeMode, profile) {
  if (publishOptions.changed || (!publishOptions.targetForm && !publishOptions.targetPage && !publishOptions.only)) {
    return buildWorkspaceReleasePlan({
      changed: publishOptions.changed,
      since: publishOptions.since,
      profile,
      includeResources: publishOptions.includeResources,
      changeId: publishOptions.changeId,
      verifyStage: 'prepublish',
    });
  }
  const targets = {
    forms: [],
    pages: [],
    resources: Boolean(publishOptions.includeResources),
    runtime: false,
    other: [],
  };
  if (publishOptions.targetForm) targets.forms.push(publishOptions.targetForm);
  if (publishOptions.targetPage) {
    if (runtimeMode === 'react-spa') targets.runtime = true;
    else targets.pages.push(publishOptions.targetPage);
  }
  if (publishOptions.only) {
    for (const item of publishOptions.only.split(',').map(value => value.trim()).filter(Boolean)) {
      const formMatch = item.match(/^forms\/([^/]+)$/);
      const pageMatch = item.match(/^pages\/([^/]+)$/);
      if (formMatch) targets.forms.push(formMatch[1]);
      else if (pageMatch) targets.pages.push(pageMatch[1]);
    }
  }
  targets.forms = unique(targets.forms).sort();
  targets.pages = unique(targets.pages).sort();
  const commands = buildWorkspaceReleaseCommands(
    targets,
    runtimeMode,
    profile,
    publishOptions.changeId
  );
  const sddPlan = buildExplicitSddReleasePlan(targets, {
    files: [],
    commands,
    changeId: publishOptions.changeId,
  });
  return {
    workspace: {
      cwd: process.cwd(),
      runtimeMode,
      configFile: path.join(process.cwd(), 'app-workspace.config.ts'),
      compatibility: getWorkspaceCompatibilityFromConfig(readWorkspaceConfigText()),
    },
    mode: 'targeted',
    targets,
    publishOrder:
      runtimeMode === 'react-spa'
        ? ['forms', 'resources', 'runtime']
        : ['forms/pages', 'resources'],
    commands,
    checks: sddPlan.sdd.checks,
    sdd: sddPlan.sdd,
    issues: [],
    errors: sddPlan.errors,
  };
}

function isUnauthorized(error) {
  return (
    Number(error?.apiCode) === 401 ||
    String(error?.message || '').includes('HTTP 401')
  );
}

function isTransientNetworkError(error) {
  const message = String(error?.message || error || '').toLowerCase();
  return (
    message.includes('und_err_connect_timeout') ||
    message.includes('connect_timeout') ||
    message.includes('econnreset') ||
    message.includes('und_err_socket') ||
    message.includes('other side closed') ||
    message.includes('socket hang up') ||
    message.includes('network socket disconnected') ||
    message.includes('fetch failed')
  );
}

function requestMethodAllowsTransientRetry(options = {}) {
  const method = String(options.method || 'GET').toUpperCase();
  return method === 'GET' || method === 'HEAD';
}

async function retryTransientFetch(fn, options = {}) {
  const retries = Number.isFinite(Number(options.retries))
    ? Number(options.retries)
    : 2;
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;
      if (attempt >= retries || !isTransientNetworkError(error)) {
        throw error;
      }
      await sleep(Math.min(500 * Math.pow(2, attempt), 3000));
    }
  }
  throw lastError;
}

async function downloadWithAuth(config, profileName, apiPath, options = {}) {
  assertReadOnlyHttpRequest(apiPath, { ...options, method: 'GET' });
  const resolved = getProfile(config, profileName);
  const profile = resolved.profile;
  if (!profile.token?.accessToken) {
    fail(`profile ${resolved.profileName} 未登录，请先执行 openxiangda login --profile ${resolved.profileName}`);
  }
  const requestOptions = {
    method: 'GET',
    timeoutMs: options.timeoutMs,
    retries: options.retries,
  };
  const send = () =>
    downloadBinary(profile.baseUrl, apiPath, profile.token.accessToken, requestOptions);
  try {
    return await retryTransientFetch(send, requestOptions);
  } catch (error) {
    if (isUnauthorized(error) && readOnlyHttpGuardDepth > 0) {
      throw createReadOnlyAuthenticationError(resolved.profileName, apiPath);
    }
    if (!isUnauthorized(error) || !profile.token?.refreshToken) {
      throw error;
    }
    await refreshProfile(config, resolved.profileName);
    return await retryTransientFetch(send, requestOptions);
  }
}

async function downloadBinary(baseUrl, apiPath, accessToken, options = {}) {
  assertReadOnlyHttpRequest(apiPath, { ...options, method: options.method || 'GET' });
  if (typeof fetch !== 'function') {
    throw new Error('当前 Node.js 版本不支持 fetch，请使用 Node.js 18 或更高版本');
  }
  const url = `${baseUrl.replace(/\/+$/, '')}${apiPath}`;
  const timeoutMs = normalizeRuntimeUploadTimeoutMs(options.timeoutMs);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let response;
  try {
    response = await fetch(url, {
      method: options.method || 'GET',
      headers: {
        accept: '*/*',
        authorization: `Bearer ${accessToken}`,
      },
      signal: controller.signal,
    });
  } catch (error) {
    if (isAbortError(error)) {
      throw new Error(maskText(`HTTP download timed out after ${timeoutMs}ms: ${apiPath}`));
    }
    throw new Error(formatFetchError(error, apiPath));
  } finally {
    clearTimeout(timer);
  }

  if (!response.ok) {
    const text = await response.text().catch(() => '');
    let payload = null;
    try {
      payload = text ? JSON.parse(text) : null;
    } catch {
      payload = { message: text };
    }
    const message = payload?.message || response.statusText || 'download failed';
    const error = new Error(maskText(`HTTP ${response.status}: ${message}`));
    error.status = response.status;
    error.payload = payload;
    throw error;
  }

  const arrayBuffer = await response.arrayBuffer();
  const buffer = Buffer.from(arrayBuffer);
  const disposition = response.headers.get('content-disposition') || '';
  return {
    buffer,
    filename: parseContentDispositionFilename(disposition),
    mime: response.headers.get('content-type') || 'application/octet-stream',
    bytes: buffer.length,
  };
}

function parseContentDispositionFilename(header) {
  const value = String(header || '');
  const encodedMatch = value.match(/filename\*=([^;]+)/i);
  if (encodedMatch) {
    const encoded = encodedMatch[1].trim().replace(/^UTF-8''/i, '');
    try {
      return sanitizeDownloadFilename(decodeURIComponent(encoded.replace(/^"|"$/g, '')));
    } catch {
      return sanitizeDownloadFilename(encoded);
    }
  }
  const plainMatch = value.match(/filename="?([^";]+)"?/i);
  return plainMatch ? sanitizeDownloadFilename(plainMatch[1]) : '';
}

function resolveRequestPublishContext(config, profileName, apiPath) {
  const match = /^\/openxiangda-api\/v1\/apps\/([^/?]+)(?:\/|$)/.exec(
    String(apiPath || '')
  );
  if (!match) return null;
  const appType = decodeURIComponent(match[1]);
  const resolved = getProfile(config, profileName);
  if (
    activePublishRequestContext?.appType === appType &&
    activePublishRequestContext?.profileName === resolved.profileName
  ) {
    return activePublishRequestContext;
  }

  const state = loadProjectState();
  const bound = state.profiles?.[resolved.profileName];
  if (!bound || String(bound.appType || '') !== appType) return null;
  const target = {
    state,
    bound,
    profileName: resolved.profileName,
    appType,
  };
  const lease = getUsableStoredPublishLease(target);
  const baseline = getStoredChangeBaseline(target);
  if (!lease && !baseline) return null;
  return normalizePublishContext({
    appType,
    profileName: resolved.profileName,
    publishLeaseId: lease?.leaseId,
    changeBaselineId: baseline?.baselineId,
    changeId: lease?.changeId || baseline?.changeId,
    clientSessionId: lease?.clientSessionId || baseline?.clientSessionId,
  });
}

function publishContextHeadersForRequest(config, profileName, apiPath, options = {}) {
  const method = String(options.method || 'GET').toUpperCase();
  if (['GET', 'HEAD', 'OPTIONS'].includes(method)) return {};
  return buildPublishContextHeaders(
    resolveRequestPublishContext(config, profileName, apiPath)
  );
}

function isPublishMutationRequest(apiPath, options = {}) {
  const method = String(options.method || 'GET').toUpperCase();
  if (['GET', 'HEAD', 'OPTIONS'].includes(method)) return false;
  const normalizedPath = String(apiPath || '').split('?')[0];
  if (
    normalizedPath.includes('/publish-lease/') ||
    normalizedPath.endsWith('/publish-lease/acquire') ||
    normalizedPath.includes('/change-baselines') ||
    normalizedPath.includes('/delivery/')
  ) {
    return false;
  }
  if (
    normalizedPath.endsWith('/oss-upload-plan') &&
    options.body?.planOnly === true
  ) {
    return false;
  }
  if (
    normalizedPath.endsWith('/schema-storage-plan') ||
    normalizedPath.endsWith('/storage-plan')
  ) {
    return false;
  }
  return true;
}

async function requestWithAuth(config, profileName, apiPath, options = {}) {
  assertReadOnlyHttpRequest(apiPath, options);
  const resolved = getProfile(config, profileName);
  const profile = resolved.profile;
  if (!profile.token?.accessToken) {
    fail(`profile ${resolved.profileName} 未登录，请先执行 openxiangda login --profile ${resolved.profileName}`);
  }
  const {
    strictEnvelope,
    skipPublishLeaseHeartbeat,
    retryTransient,
    ...requestOptions
  } = options;
  const send = async () => {
    if (
      !skipPublishLeaseHeartbeat &&
      !['GET', 'HEAD', 'OPTIONS'].includes(
        String(requestOptions.method || 'GET').toUpperCase()
      )
    ) {
      await activePublishLeaseHeartbeat?.heartbeat?.beforeWrite();
    }
    if (isPublishMutationRequest(apiPath, requestOptions)) {
      markCommandScopedPublishWriteAttempted();
    }
    // Build headers after the lease check: a successful renew may replace the
    // live client session/expiry metadata, and auth/transient retries must not
    // replay stale publish context.
    const currentRequestOptions = {
      ...requestOptions,
      headers: {
        ...(requestOptions.headers || {}),
        ...publishContextHeadersForRequest(
          config,
          resolved.profileName,
          apiPath,
          requestOptions
        ),
      },
    };
    return requestJson(profile.baseUrl, apiPath, {
      ...currentRequestOptions,
      accessToken: profile.token.accessToken,
    });
  };
  const sendWithRetry = () =>
    retryTransient === true ||
    requestMethodAllowsTransientRetry(requestOptions)
      ? retryTransientFetch(send, requestOptions)
      : send();

  try {
    const payload = await sendWithRetry();
    return strictEnvelope ? unwrapStrictApi(payload) : unwrapApi(payload);
  } catch (error) {
    if (isUnauthorized(error) && readOnlyHttpGuardDepth > 0) {
      throw createReadOnlyAuthenticationError(resolved.profileName, apiPath);
    }
    if (!isUnauthorized(error) || !profile.token?.refreshToken) {
      throw error;
    }
    await refreshProfile(config, resolved.profileName);
    const payload = await sendWithRetry();
    return strictEnvelope ? unwrapStrictApi(payload) : unwrapApi(payload);
  }
}

async function requestFormWithAuth(config, profileName, apiPath, formDataFactory, options = {}) {
  assertReadOnlyHttpRequest(apiPath, { ...options, method: 'POST' });
  const resolved = getProfile(config, profileName);
  const profile = resolved.profile;
  if (!profile.token?.accessToken) {
    fail(`profile ${resolved.profileName} 未登录，请先执行 openxiangda login --profile ${resolved.profileName}`);
  }
  const {
    skipPublishLeaseHeartbeat,
    ...formRequestOptions
  } = options;
  const requestOptions = {
    ...formRequestOptions,
    method: 'POST',
  };
  const send = async () => {
    if (!skipPublishLeaseHeartbeat) {
      await activePublishLeaseHeartbeat?.heartbeat?.beforeWrite();
    }
    markCommandScopedPublishWriteAttempted();
    const currentRequestOptions = {
      ...requestOptions,
      headers: {
        ...(requestOptions.headers || {}),
        ...publishContextHeadersForRequest(
          config,
          resolved.profileName,
          apiPath,
          requestOptions
        ),
      },
    };
    return requestForm(
      profile.baseUrl,
      apiPath,
      formDataFactory(),
      profile.token.accessToken,
      currentRequestOptions
    );
  };

  try {
    const payload = await retryTransientFetch(send, requestOptions);
    return unwrapApi(payload);
  } catch (error) {
    if (isUnauthorized(error) && readOnlyHttpGuardDepth > 0) {
      throw createReadOnlyAuthenticationError(resolved.profileName, apiPath);
    }
    if (!isUnauthorized(error) || !profile.token?.refreshToken) {
      throw error;
    }
    await refreshProfile(config, resolved.profileName);
    const payload = await retryTransientFetch(send, requestOptions);
    return unwrapApi(payload);
  }
}

async function withReadOnlyHttpGuard(label, operation) {
  const previousLabel = readOnlyHttpGuardLabel;
  readOnlyHttpGuardDepth += 1;
  readOnlyHttpGuardLabel = label || previousLabel || 'read-only operation';
  try {
    return await operation();
  } finally {
    readOnlyHttpGuardDepth -= 1;
    readOnlyHttpGuardLabel = readOnlyHttpGuardDepth > 0 ? previousLabel : null;
  }
}

function assertReadOnlyHttpRequest(apiPath, options = {}) {
  if (readOnlyHttpGuardDepth <= 0) return;
  const method = String(options.method || 'GET').toUpperCase();
  if (['GET', 'HEAD'].includes(method)) return;
  const error = new Error(
    `${readOnlyHttpGuardLabel || '只读操作'} 禁止发起 ${method} ${apiPath}`
  );
  error.code = 'READ_ONLY_HTTP_WRITE_BLOCKED';
  error.method = method;
  error.apiPath = apiPath;
  throw error;
}

function createReadOnlyAuthenticationError(profileName, apiPath) {
  const label = readOnlyHttpGuardLabel || '只读操作';
  const error = new Error(
    `READ_ONLY_AUTH_REQUIRED: ${label} 收到 HTTP 401；只读守卫禁止自动 POST 刷新 token。请先执行 openxiangda auth refresh --profile ${profileName}（或重新登录），然后重试。`
  );
  error.code = 'READ_ONLY_AUTH_REQUIRED';
  error.status = 401;
  error.apiPath = apiPath;
  return error;
}

async function requestJson(baseUrl, apiPath, options = {}) {
  assertReadOnlyHttpRequest(apiPath, options);
  return await rawRequestJson(baseUrl, apiPath, options);
}

async function requestForm(baseUrl, apiPath, formData, accessToken, options = {}) {
  assertReadOnlyHttpRequest(apiPath, { ...options, method: 'POST' });
  if (typeof fetch !== 'function') {
    throw new Error('当前 Node.js 版本不支持 fetch，请使用 Node.js 18 或更高版本');
  }
  const url = `${baseUrl.replace(/\/+$/, '')}${apiPath}`;
  const timeoutMs = normalizeRuntimeUploadTimeoutMs(options.timeoutMs);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let response;
  try {
    response = await fetch(url, {
      method: 'POST',
      headers: {
        accept: 'application/json',
        authorization: `Bearer ${accessToken}`,
        ...(options.headers || {}),
      },
      body: formData,
      signal: controller.signal,
    });
  } catch (error) {
    if (isAbortError(error)) {
      throw new Error(maskText(`HTTP form request timed out after ${timeoutMs}ms: ${apiPath}`));
    }
    throw new Error(formatFetchError(error, apiPath));
  } finally {
    clearTimeout(timer);
  }
  const text = await response.text();
  let payload = null;
  if (text) {
    try {
      payload = JSON.parse(text);
    } catch {
      payload = { message: text };
    }
  }
  if (!response.ok) {
    const message = payload?.message || response.statusText || 'request failed';
    throw new Error(`HTTP ${response.status}: ${message}`);
  }
  return payload;
}

function isAbortError(error) {
  return (
    error?.name === 'AbortError' ||
    String(error?.message || '').toLowerCase().includes('aborted')
  );
}

async function refreshProfile(config, profileName) {
  const { profile } = getProfile(config, profileName);
  if (!profile.token?.refreshToken) {
    fail(`profile ${profileName} 没有 refresh token，请重新登录`);
  }
  const payload = await requestJson(profile.baseUrl, '/openxiangda-api/v1/auth/refresh', {
    method: 'POST',
    body: { refreshToken: profile.token.refreshToken },
  });
  const data = unwrapApi(payload);
  profile.token = {
    ...profile.token,
    accessToken: data.accessToken,
    refreshToken: data.refreshToken,
    accessTokenExpiresAt: data.accessTokenExpiresAt,
    refreshTokenExpiresAt: data.refreshTokenExpiresAt,
  };
  profile.updatedAt = new Date().toISOString();
  return {
    accessTokenExpiresAt: profile.token.accessTokenExpiresAt,
    refreshTokenExpiresAt: profile.token.refreshTokenExpiresAt,
  };
}

function readStringFlag(flags, key) {
  const value = flags[key];
  if (value === undefined || value === null || value === false) return '';
  if (value === true) fail(`--${key} 需要提供值`);
  return String(value).trim();
}

function readCommaSeparatedFlag(flags, key) {
  const value = readStringFlag(flags, key);
  return unique(
    value
      .split(',')
      .map(item => item.trim())
      .filter(Boolean)
  ).sort();
}

function normalizeWorkspacePublishOptions(flags) {
  const targetForm = readStringFlag(flags, 'form');
  const targetPage = readStringFlag(flags, 'page');
  const only = readStringFlag(flags, 'only');
  const since = readStringFlag(flags, 'since');
  const changed = Boolean(flags.changed || flags['changed-only']);
  const dryRun = Boolean(flags['dry-run']);
  const force = Boolean(flags.force);
  const skipResources = Boolean(flags['skip-resources']);
  const includeResourcesFlag = Boolean(flags.resources || flags['include-resources']);
  const prune = Boolean(flags.prune);
  const changeId = readStringFlag(flags, 'change');

  if (targetForm && targetPage) {
    fail('workspace publish 不能同时使用 --form 和 --page，请分两次发布');
  }
  if (changed && (targetForm || targetPage || only)) {
    fail('workspace publish --changed 不能与 --form、--page 或 --only 同时使用');
  }
  if (since && !changed) {
    fail('workspace publish --since 只能与 --changed 一起使用');
  }
  if (skipResources && prune) {
    fail('workspace publish --skip-resources 不能与 --prune 同时使用');
  }

  const workspaceArgs = [];
  if (targetForm) workspaceArgs.push('--form', targetForm);
  if (targetPage) workspaceArgs.push('--page', targetPage);
  if (only) workspaceArgs.push('--only', only);
  if (changed) workspaceArgs.push('--changed');
  if (since) workspaceArgs.push('--since', since);
  if (dryRun) workspaceArgs.push('--dry-run');
  if (force) workspaceArgs.push('--force');
  if (flags['legacy-form-bundle']) workspaceArgs.push('--legacy-form-bundle');

  const targeted = Boolean(targetForm || targetPage || only || changed);
  const includeResources =
    !skipResources && (includeResourcesFlag || prune || !targeted);

  return {
    workspaceArgs,
    dryRun,
    targetForm,
    targetPage,
    only,
    changed,
    since,
    legacyFormBundle: Boolean(flags['legacy-form-bundle']),
    includeResources,
    prune,
    changeId,
    quietResourceSkip: !targeted || skipResources,
  };
}

async function runWorkspacePublish(
  profileName,
  profile,
  appType,
  publishArgs = [],
  targetName = ''
) {
  const packageFile = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(packageFile)) {
    fail('当前目录没有 package.json，无法识别工作区发布脚本');
  }
  const pkg = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
  const scripts = pkg.scripts || {};
  const scriptName = scripts['openxiangda:publish']
    ? 'openxiangda:publish'
    : scripts['publish:all']
      ? 'publish:all'
      : null;
  if (!scriptName) {
    fail('当前工作区缺少 openxiangda:publish 或 publish:all 脚本');
  }

  const usePnpm = fs.existsSync(path.join(process.cwd(), 'pnpm-lock.yaml'));
  const command = usePnpm ? 'pnpm' : 'npm';
  const args = publishArgs.length
    ? ['run', scriptName, '--', ...publishArgs]
    : ['run', scriptName];
  const globalEnv = loadGlobalEnv();
  await runWorkspaceChildCommand(command, args, {
    cwd: process.cwd(),
    env: buildWorkspacePublishEnv(
      profileName,
      profile,
      appType,
      globalEnv,
      targetName
    ),
    failureCode: 'WORKSPACE_PUBLISH_FAILED',
    label: scriptName,
    marksPublishWrite: true,
  });
}

function isReactSpaWorkspace() {
  const configFile = path.join(process.cwd(), 'app-workspace.config.ts');
  if (!fs.existsSync(configFile)) return false;
  const content = fs.readFileSync(configFile, 'utf8');
  return /runtimeMode\s*:\s*['"]react-spa['"]/.test(content);
}

async function runReactSpaFormSchemaPublish(
  profileName,
  profile,
  appType,
  publishOptions,
  targetName = ''
) {
  const packageFile = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(packageFile)) {
    fail('当前目录没有 package.json，无法识别工作区发布脚本');
  }
  const pkg = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
  const scripts = pkg.scripts || {};
  const usePnpm = fs.existsSync(path.join(process.cwd(), 'pnpm-lock.yaml'));
  const command = usePnpm ? 'pnpm' : 'npm';
  const syncArgs = ['--form', publishOptions.targetForm];
  if (publishOptions.dryRun) syncArgs.push('--dry-run');
  const args = scripts['sync-schema']
    ? ['run', 'sync-schema', '--', ...syncArgs]
    : usePnpm
      ? ['exec', 'lowcode-workspace', 'sync-schema', ...syncArgs]
      : ['exec', '--', 'lowcode-workspace', 'sync-schema', ...syncArgs];
  print(
    `React SPA 表单 schema 发布${publishOptions.dryRun ? ' (dry-run)' : ''}: ${publishOptions.targetForm}`
  );
  const globalEnv = loadGlobalEnv();
  await runWorkspaceChildCommand(command, args, {
    cwd: process.cwd(),
    env: buildWorkspacePublishEnv(
      profileName,
      profile,
      appType,
      globalEnv,
      targetName
    ),
    failureCode: 'FORM_SCHEMA_PUBLISH_FAILED',
    label: `form schema ${publishOptions.targetForm}`,
    marksPublishWrite: true,
  });
}

async function runWorkspaceChildCommand(command, args, options = {}) {
  await new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd: options.cwd || process.cwd(),
      stdio: 'inherit',
      env: options.env || process.env,
    });
    child.once('spawn', () => {
      if (options.marksPublishWrite) {
        markCommandScopedPublishWriteAttempted();
      }
    });
    child.once('error', reject);
    child.once('close', (code, signal) => {
      if (code === 0) {
        resolve();
        return;
      }
      const error = new Error(
        `${options.label || command} 执行失败${signal ? `（signal=${signal}）` : `（exit=${code ?? 1}）`}`
      );
      error.code = options.failureCode || 'WORKSPACE_CHILD_COMMAND_FAILED';
      error.exitCode = Number.isInteger(code) ? code : 1;
      reject(error);
  });
  });
}

async function resolveStagedLocalFormContractSnapshots(
  config,
  target,
  flags = {},
  implicitFormCodes = []
) {
  const explicitFormCodes = unique(
    String(flags['staged-form-contracts'] || '')
      .split(',')
      .map(value => value.trim())
      .filter(Boolean)
  ).sort();
  const formCodes = unique([
    ...explicitFormCodes,
    ...(implicitFormCodes || [])
      .map(value => String(value || '').trim())
      .filter(Boolean),
  ]).sort();
  if (formCodes.length === 0) return new Map();
  const changeId = readStringFlag(flags, 'change');
  if (!changeId) {
    if (explicitFormCodes.length === 0) return new Map();
    fail(
      'FORM_FIELD_STAGED_CONTRACT_CHANGE_REQUIRED: --staged-form-contracts 必须与 --change 一起使用'
    );
  }
  const stagedOverlays =
    await resolveReusableStagedFormReleaseOverlays(
      config,
      target,
      changeId,
      { formCodes }
    );
  const satisfiedFormCodes = satisfiedFormCodesFromContext(
    reusableStagedResourcesContext(target, changeId)
  );
  const snapshots = new Map();
  for (const formCode of formCodes) {
    const formUuid = resolveManifestFormUuid(
      target.bound,
      { formCode },
      { fallbackToCode: false }
    );
    const staged = stagedOverlays.get(formCode);
    if (!staged) {
      if (satisfiedFormCodes.has(formCode)) {
        // form-stage proved this exact selector is a noop in the current
        // deployment. Let buildFormFieldContractPlan read the active frozen
        // snapshot instead of requiring an unnecessary immutable child.
        continue;
      }
      fail(
        `FORM_FIELD_STAGED_CONTRACT_REQUIRED: ${formCode} 尚未在 change ${changeId} 的当前 deployment 中获得 verified FormRelease`
      );
    }
    if (staged.formUuid !== formUuid) {
      fail(
        `FORM_FIELD_STAGED_CONTRACT_REQUIRED: ${formCode} 尚未在 change ${changeId} 的当前 deployment 中获得 verified FormRelease`
      );
    }
    snapshots.set(
      formUuid,
      collectFormSnapshotFieldIds({ form: staged.formSnapshot })
    );
  }
  return snapshots;
}

async function buildFormFieldContractPlan(
  config,
  target,
  manifest,
  options = {}
) {
  const targets = [];
  for (const [manifestKey, kind] of [
    ['functions', 'Function'],
    ['automations', 'Automation'],
    ['workflows', 'Workflow'],
    ['jsCodeNodes', 'JsCodeNode'],
  ]) {
    for (const item of manifest[manifestKey] || []) {
      const analysis = item.__sourceAnalysis;
      if (!analysis?.formFieldReferences?.length) continue;
      const code =
        item.code ||
        item.functionCode ||
        item.resourceCode ||
        item.scriptCode;
      for (const reference of analysis.formFieldReferences) {
        const formUuid = resolveManifestFormBindingForContract(
          target,
          item,
          reference.formCode
        );
        targets.push({
          kind,
          code,
          formCode: reference.formCode,
          formUuid,
          field: reference.field,
          api: reference.api,
          file: reference.file,
          line: reference.line,
        });
      }
    }
  }
  if (targets.length === 0) {
    return {
      contractVersion: 'form_field_contract_v1',
      valid: true,
      checkedForms: 0,
      checkedReferences: 0,
      errors: [],
    };
  }
  const snapshots = new Map(
    options.stagedLocalFormSnapshots || []
  );
  const formTargets = unique(
    targets.map(item => item.formUuid).filter(Boolean)
  ).sort();
  await Promise.all(
    formTargets.map(async formUuid => {
      if (snapshots.has(formUuid)) return;
      const frozen = await fetchFrozenFormConfig(
        config,
        target,
        formUuid
      );
      snapshots.set(formUuid, collectFormSnapshotFieldIds(frozen.snapshot));
    })
  );
  return validateFormFieldContracts(targets, snapshots);
}

function resolveManifestFormBindingForContract(target, item, formCode) {
  const containers = [
    item.resourceBindings,
    item.resources,
    item.definitionJson?.resourceBindings,
    item.definitionJson?.resources,
  ];
  if (item.definitionFile) {
    try {
      const definition = JSON.parse(
        fs.readFileSync(
          path.resolve(item.__dir || process.cwd(), item.definitionFile),
          'utf8'
        )
      );
      containers.push(definition.resourceBindings, definition.resources);
    } catch {
      // Resource validation reports invalid definition files separately.
    }
  }
  for (const container of containers) {
    const binding = container?.forms?.[formCode];
    if (typeof binding === 'string' && binding.trim()) return binding.trim();
    const formUuid = String(
      binding?.formUuid || binding?.id || binding?.uuid || ''
    ).trim();
    if (formUuid) return formUuid;
  }
  return resolveManifestFormUuid(
    target.bound,
    { formCode },
    { fallbackToCode: false }
  );
}

function buildWorkspacePublishEnv(
  profileName,
  profile,
  appType,
  globalEnv,
  targetName = ''
) {
  const env = { ...process.env };
  const injectedGlobalKeys = [];

  for (const [key, value] of Object.entries(globalEnv)) {
    if (key.startsWith('APP_') && env[key] === undefined) {
      env[key] = value;
      injectedGlobalKeys.push(key);
    }
  }

  env.OPENXIANGDA_PROFILE = profileName;
  env.OPENXIANGDA_BASE_URL = profile.baseUrl;
  env.OPENXIANGDA_ACCESS_TOKEN = profile.token.accessToken;
  env.OPENXIANGDA_APP_TYPE = appType;
  if (targetName) env.OPENXIANGDA_TARGET = targetName;
  else delete env.OPENXIANGDA_TARGET;
  env.OPENXIANGDA_GLOBAL_ENV_KEYS = injectedGlobalKeys.join(',');
  Object.assign(env, buildPublishContextEnv(activePublishRequestContext));

  return env;
}

